export const LESSON_HTML = {
  "economics": {
    "1": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"progress-container\">\n  <div class=\"progress-bar\" id=\"progressBar\"></div>\n</div>\n\n<canvas id=\"particles\"></canvas>\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">Chapter 1</div>\n  <h1>Introduction to<br>Economics</h1>\n  <p>Exploring the fundamentals of economic behavior, scarcity, and the choices that shape our world.</p>\n  <div class=\"hero-scroll\">↓</div>\n</section>\n\n<div class=\"container\">\n\n\n\n  <!-- 1. What is Economics? -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📊</div>\n    <h2>What is Economics? <span class=\"underline\"></span></h2>\n    <p>Every subject in the world can be divided into two main parts:</p>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🔬 Natural Sciences</div>\n        <ul>\n          <li>Studies natural phenomena</li>\n          <li>Based on laboratory tests</li>\n          <li>Biology, Chemistry, Physics, Geology, Space Science, Medical Science</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">👥 Social Sciences</div>\n        <ul>\n          <li>Studies behavior of people in society</li>\n          <li>Political Science, Psychology, Criminology, Sociology, Geography, History</li>\n          <li><strong>Economics</strong> — studies economic behavior of people</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"info-card\" style=\"margin-top: 1rem;\">\n      <div class=\"emoji\">👑</div>\n      <div class=\"label\">Economics is the Queen of Social Sciences</div>\n      <div class=\"desc\">Adam Smith — Father of Economics, author of <em>The Wealth of Nations</em> (1776)</div>\n    </div>\n  </div>\n\n  <!-- 2. Micro vs Macro -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📋</div>\n    <h2>Microeconomics vs Macroeconomics <span class=\"underline\"></span></h2>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🧠 Microeconomics</div>\n        <ul>\n          <li>Study of economics <strong>as units</strong></li>\n          <li>Small units: households, firms, individuals</li>\n          <li>Analyzes separate economic variables</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🌍 Macroeconomics</div>\n        <ul>\n          <li>Study of economics <strong>as a whole</strong></li>\n          <li>Aggregate economic behavior</li>\n          <li>National income, inflation, unemployment</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 3. Positive vs Normative -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚖️</div>\n    <h2>Positive &amp; Normative Statements <span class=\"underline\"></span></h2>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">✅ Positive Statements</div>\n        <ul>\n          <li>Answer: what is, what happened, what will happen</li>\n          <li>Can be verified with real-world facts</li>\n          <li>Scientific and objective</li>\n          <li>Ex: \"Positive relationship exists between money supply and price level\"</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">💭 Normative Statements</div>\n        <ul>\n          <li>Answer: what should be / should happen</li>\n          <li>Based on personal views, beliefs, traditions</li>\n          <li>Subjective — hard to test objectively</li>\n          <li>Ex: \"Sri Lanka should obtain foreign aids for development\"</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 4. Needs & Wants -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🛒</div>\n    <h2>Needs &amp; Wants <span class=\"underline\"></span></h2>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">❤️ Needs</div>\n        <ul>\n          <li>Basic necessities to sustain life</li>\n          <li>Combined with biological sources</li>\n          <li>Limited</li>\n          <li>Do not change with time</li>\n          <li>Common to all</li>\n          <li>Ex: Food</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">✨ Wants</div>\n        <ul>\n          <li>Various forms of fulfilling needs</li>\n          <li>Combined with traditions, values, culture</li>\n          <li>Unlimited</li>\n          <li>Change with time</li>\n          <li>Differ from person to person</li>\n          <li>Ex: Rice, Bread, String Hoppers, Hoppers</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 5. Goods & Services -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📦</div>\n    <h2>Goods &amp; Services <span class=\"underline\"></span></h2>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">💠</div>\n        <div class=\"label\">Goods</div>\n        <div class=\"desc\">Tangible, positive utility</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🏭</div>\n        <div class=\"label\">Services</div>\n        <div class=\"desc\">Intangible, positive utility</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">☢️</div>\n        <div class=\"label\">Bads</div>\n        <div class=\"desc\">Negative utility, disposal cost</div>\n      </div>\n    </div>\n\n    <h3>Economic vs Non-Economic Goods</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">💰 Economic Goods</div>\n        <ul>\n          <li>Scarce supply</li>\n          <li>Resource cost involved</li>\n          <li>Opportunity cost exists</li>\n          <li>Has ownership</li>\n          <li>Involves a price</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🌊 Non-Economic Goods</div>\n        <ul>\n          <li>Unlimited supply at zero price</li>\n          <li>No resource cost</li>\n          <li>No opportunity cost</li>\n          <li>No ownership</li>\n        </ul>\n      </div>\n    </div>\n    <p style=\"margin-top: 0.8rem; font-size: 0.95rem; color: var(--text-muted);\">\n      <em>Can non-economic goods become economic goods?</em> Yes! Examples: oxygen for divers, bottled water, solar panels.\n    </p>\n  </div>\n\n  <!-- 6. Production Resources -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏗️</div>\n    <h2>Production Resources <span class=\"underline\"></span></h2>\n    <p>All inputs used to produce goods and services to fulfill human wants.</p>\n\n    <div class=\"flashcard-container\">\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🏔️ Land\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Natural resources from nature<br>\n            <small>Forests, minerals, oceans, rivers, air<br>Payment: <strong>Rent</strong></small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🧑‍🏫 Labour\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Mental &amp; physical effort<br>\n            <small>Payment: <strong>Wages</strong></small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🏭 Capital\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Man-made aids for production<br>\n            <small>Payment: <strong>Interest</strong></small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🧩 Entrepreneurship\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Combining all factors, risk-taking<br>\n            <small>Payment: <strong>Profit</strong></small>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <h3>Types of Capital</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🏷️</div><div class=\"label\">Fixed Capital</div><div class=\"desc\">Durable: factories, machinery</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📦</div><div class=\"label\">Circulating Capital</div><div class=\"desc\">Raw materials, semi-finished goods</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏭</div><div class=\"label\">Economic Overhead</div><div class=\"desc\">Ports, airports, highways</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">❤️</div><div class=\"label\">Social Overhead</div><div class=\"desc\">Hospitals, schools, drainage</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧑‍🎓</div><div class=\"label\">Human Capital</div><div class=\"desc\">Skills, education, training</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤝</div><div class=\"label\">Social Capital</div><div class=\"desc\">Institutions, networks, traditions</div></div>\n    </div>\n  </div>\n\n  <!-- 7. Scarcity & Choice -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚠️</div>\n    <h2>Scarcity &amp; Choice <span class=\"underline\"></span></h2>\n    <div class=\"info-card\">\n      <div class=\"emoji\">⚠️</div>\n      <div class=\"label\">Scarcity</div>\n      <div class=\"desc\">Limited resources × Unlimited wants → the central economic problem</div>\n    </div>\n    <h3>Scarcity vs Poverty</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">⚠️ Scarcity</div>\n        <ul>\n          <li>Lack of resources relative to wants</li>\n          <li>Cannot be reduced by government policy</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">💰 Poverty</div>\n        <ul>\n          <li>Total absence of resources for basic needs</li>\n          <li>Can be reduced by government policy</li>\n        </ul>\n      </div>\n    </div>\n    <h3>Scarcity vs Shortage</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">⚠️ Scarcity</div>\n        <ul>\n          <li>Permanent resource limitation</li>\n          <li>Central problem of every economy</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">⏰ Shortage</div>\n        <ul>\n          <li>Delay of stocks; demand &gt; supply</li>\n          <li>Temporary — disappears with arrival of stocks</li>\n        </ul>\n      </div>\n    </div>\n    <h3>Three Basic Economic Questions</h3>\n    <div class=\"timeline\">\n      <div class=\"timeline-item\"><div class=\"title\">📋 What to produce — in what quantity?</div><div class=\"desc\">Due to scarcity and alternative uses</div></div>\n      <div class=\"timeline-item\"><div class=\"title\">⚙️ How to produce?</div><div class=\"desc\">Labour-intensive vs Capital-intensive techniques</div></div>\n      <div class=\"timeline-item\"><div class=\"title\">👥 For whom to produce?</div><div class=\"desc\">Distribution of limited goods and services</div></div>\n    </div>\n  </div>\n\n  <!-- 8. Opportunity Cost -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💱</div>\n    <h2>Opportunity Cost <span class=\"underline\"></span></h2>\n    <div class=\"info-card\">\n      <div class=\"emoji\">💱</div>\n      <div class=\"label\">Opportunity Cost</div>\n      <div class=\"desc\">The value of the next best alternative forgone when making a choice</div>\n    </div>\n    <div class=\"formula-box\">\n      Opportunity Cost = Value of Next Best Alternative Forgone\n    </div>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">✅</div><div class=\"label\">Positive Concept</div><div class=\"desc\">Only with economic goods</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💰</div><div class=\"label\">Real, not Financial</div><div class=\"desc\">Shows real value, not monetary</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧑‍💬</div><div class=\"label\">Individual</div><div class=\"desc\">Expressed only by the person choosing</div></div>\n    </div>\n    <h3>When can opportunity cost be zero?</h3>\n    <ul>\n      <li>Unlimited resources (non-economic goods)</li>\n      <li>Absence of alternative uses</li>\n      <li>Unemployed resources</li>\n    </ul>\n  </div>\n\n  <!-- 9. Economic Systems -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏛️</div>\n    <h2>Economic Systems <span class=\"underline\"></span></h2>\n    <p>An institutional structure made by people to solve basic economic problems caused by scarcity.</p>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🏭</div><div class=\"label\">Market Economy</div><div class=\"desc\">Private ownership, price mechanism, self-interest</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏰</div><div class=\"label\">Command Economy</div><div class=\"desc\">Public ownership, central planning, social welfare</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">⚖️</div><div class=\"label\">Mixed Economy</div><div class=\"desc\">Both price mechanism &amp; planning</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏴</div><div class=\"label\">Traditional Economy</div><div class=\"desc\">Customs, barter, tribes, hunting/gathering</div></div>\n    </div>\n    <div class=\"formula-box\" style=\"font-size: 0.9rem;\">\n      Classification: Ownership of Property × Decision Coordination × Incentives\n    </div>\n  </div>\n\n  <!-- 10. PPF -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📈</div>\n    <h2>Production Possibility Frontier <span class=\"underline\"></span></h2>\n    <div class=\"info-card\">\n      <div class=\"emoji\">📈</div>\n      <div class=\"label\">PPF</div>\n      <div class=\"desc\">The line showing maximum combination of two goods an economy can produce with full efficiency</div>\n    </div>\n    <div class=\"diagram-box\">\n      <pre>Pen\n  |\n6 |    A\n5 |   /\n4 |  /\n3 | /\n2 |/\n1 |\n  +------------------ Pencil\n  0  20 40 60 80 100\n      </pre>\n    </div>\n    <h3>Types of Opportunity Cost on PPF</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">—</div><div class=\"label\">Constant OC</div><div class=\"desc\">Linear PPF, homogeneous resources</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">↗️</div><div class=\"label\">Increasing OC</div><div class=\"desc\">Concave PPF, non-homogeneous resources</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">↘️</div><div class=\"label\">Decreasing OC</div><div class=\"desc\">Convex PPF</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">○</div><div class=\"label\">Zero OC</div><div class=\"desc\">Moving inside curve → to curve</div></div>\n    </div>\n    <div class=\"formula-box\" style=\"font-size: 0.9rem;\">\n      Opportunity Cost = Amount Reduced ÷ Amount Increased\n    </div>\n  </div>\n\n  <!-- PPF Concepts -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧩</div>\n    <h2>PPF Concepts <span class=\"underline\"></span></h2>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">❌</div><div class=\"label\">Scarcity</div><div class=\"desc\">Point <strong>outside</strong> PPF</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">✅</div><div class=\"label\">Production Efficiency</div><div class=\"desc\">Any point <strong>on</strong> PPF (full employment + full production)</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🎯</div><div class=\"label\">Allocative Efficiency</div><div class=\"desc\"><strong>One</strong> point on PPF where P = MC or MC = MB</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📉</div><div class=\"label\">Unemployment/Innefficiency</div><div class=\"desc\">Point <strong>inside</strong> PPF</div></div>\n    </div>\n    <div class=\"diagram-box\">\n      <pre>        Good X\n          |\n    C     |     B\n     \\    |    /\n      \\   |   /\n       \\  |  /\n        \\ | /\n         \\|/\n          +---------- Good Y\n\n  A - Inside (unemployment, inefficiency)\n  B - On PPF (full employment, efficiency)\n  C - Outside (scarcity - unattainable)\n      </pre>\n    </div>\n    <h3>Economic Growth &amp; Depression</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">📈</div><div class=\"label\">Economic Growth</div><div class=\"desc\">PPF shifts <strong>right</strong> — increased production capacity</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📉</div><div class=\"label\">Economic Depression</div><div class=\"desc\">PPF shifts <strong>left</strong> — decreased production capacity</div></div>\n    </div>\n    <h3>Factors Affecting Production Capacity</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">↗️ Increase (Growth)</div>\n        <ul>\n          <li>Increase in resources (Land, Labour, Capital, Entrepreneurship)</li>\n          <li>Increase in productivity (Investment, Technology, Management)</li>\n          <li>Increase in innovations</li>\n          <li>Economic development</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">↘️ Decrease (Depression)</div>\n        <ul>\n          <li>Decrease in resources</li>\n          <li>Decrease in productivity</li>\n          <li>Decrease in innovations</li>\n          <li>Natural disasters / Civil war</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- Interactive Quiz -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧰</div>\n    <h2>Test Your Knowledge <span class=\"underline\"></span></h2>\n\n    <div class=\"quiz-question\" data-q=\"1\">\n      <div class=\"q\">1. Who is known as the Father of Economics?</div>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Adam Smith</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">John Maynard Keynes</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Karl Marx</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">David Ricardo</button>\n      <div class=\"quiz-feedback\" data-feedback=\"1\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"2\">\n      <div class=\"q\">2. What does Macroeconomics study?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Small economic units like households</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">The economy as a whole</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Individual market prices</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Consumer behavior only</button>\n      <div class=\"quiz-feedback\" data-feedback=\"2\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"3\">\n      <div class=\"q\">3. Which is an example of a Positive Statement?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Sri Lanka should obtain foreign aid</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Positive relationship exists between money supply and price level</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">People should control their expenditures</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">The government ought to reduce taxes</button>\n      <div class=\"quiz-feedback\" data-feedback=\"3\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"4\">\n      <div class=\"q\">4. The payment for the factor \"Capital\" is called:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Rent</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Wages</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Interest</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Profit</button>\n      <div class=\"quiz-feedback\" data-feedback=\"4\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"5\">\n      <div class=\"q\">5. A point inside the PPF represents:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Scarcity</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Economic growth</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Unemployment / Inefficiency</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Production efficiency</button>\n      <div class=\"quiz-feedback\" data-feedback=\"5\"></div>\n    </div>\n  </div>\n\n</div>\n\n<script>\n  // Particles\n  const canvas = document.getElementById('particles');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  class Particle {\n    constructor() {\n      this.reset();\n    }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.5;\n      this.speedY = (Math.random() - 0.5) * 0.5;\n      this.opacity = Math.random() * 0.5 + 0.1;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n      if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(9, 132, 227, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 80; i++) particles.push(new Particle());\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n\n    // Draw connections\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 150) {\n          ctx.beginPath();\n          ctx.strokeStyle = `rgba(9, 132, 227, ${0.06 * (1 - dist / 150)})`;\n          ctx.lineWidth = 0.5;\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  // Scroll reveal\n  const sections = document.querySelectorAll('[data-section]');\n\n  function revealSections() {\n    sections.forEach(section => {\n      const rect = section.getBoundingClientRect();\n      if (rect.top < window.innerHeight - 80) {\n        section.classList.add('visible');\n      }\n    });\n  }\n  window.addEventListener('scroll', revealSections);\n  revealSections();\n\n  // Progress bar\n  const progressBar = document.getElementById('progressBar');\n\n  window.addEventListener('scroll', () => {\n    const scrollTop = window.scrollY;\n    const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n    const progress = (scrollTop / docHeight) * 100;\n    progressBar.style.width = progress + '%';\n  });\n\n  // Quiz\n  function checkAnswer(btn, isCorrect) {\n    const question = btn.closest('.quiz-question');\n    const options = question.querySelectorAll('.quiz-option');\n    const feedback = question.querySelector('.quiz-feedback');\n\n    options.forEach(opt => {\n      opt.disabled = true;\n      opt.style.cursor = 'not-allowed';\n      if (opt.dataset.correct === 'true') opt.classList.add('correct');\n    });\n\n    if (isCorrect) {\n      btn.classList.add('correct');\n      feedback.textContent = '&#x2705; Correct!';\n      feedback.className = 'quiz-feedback show correct';\n    } else {\n      btn.classList.add('wrong');\n      const correctBtn = question.querySelector('[data-correct=\"true\"]');\n      feedback.textContent = '&#x274C; Incorrect. The answer was: ' + correctBtn.textContent;\n      feedback.className = 'quiz-feedback show wrong';\n    }\n  }\n</script>\n\n\n\n\n</body>\n</html>",
    "2": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"progress-container\">\n  <div class=\"progress-bar\" id=\"progressBar\"></div>\n</div>\n\n<canvas id=\"particles\"></canvas>\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">Lesson 2</div>\n  <h1>Demand, Supply &amp;<br>Market Equilibrium</h1>\n  <p>Understanding how buyers and sellers interact to determine prices and quantities in a market economy.</p>\n  <div class=\"hero-scroll\">↓</div>\n</section>\n\n<div class=\"container\">\n\n\n\n  <!-- 1. Demand -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📉</div>\n    <h2>Demand <span class=\"underline\"></span></h2>\n    <p><strong>Demand</strong> refers to the various quantities of a good or service that buyers are <strong>ready to purchase</strong> at alternative prices during a given time period.</p>\n\n    <h3>Individual vs Market Demand</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🧑 Individual Demand</div>\n        <ul>\n          <li>Quantity demanded by a <strong>single consumer</strong></li>\n          <li>Determinants: P, P<sub>n</sub>, Y, T, Ex, O</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">👥 Market Demand</div>\n        <ul>\n          <li>Sum of all individual demands</li>\n          <li>Determinants: P, P<sub>n</sub>, Y, T, Ex, <strong>N</strong>, O</li>\n          <li>N = Number of consumers</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Determinants of Demand</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">💵</div><div class=\"label\">P — Price</div><div class=\"desc\">Price of the good itself</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💲</div><div class=\"label\">P<sub>n</sub> — Related Goods</div><div class=\"desc\">Substitutes &amp; complements</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💰</div><div class=\"label\">Y — Income</div><div class=\"desc\">Consumer purchasing power</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏠</div><div class=\"label\">T — Tastes</div><div class=\"desc\">Preferences &amp; fashions</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌍</div><div class=\"label\">Ex — Expectations</div><div class=\"desc\">Future price expectations</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📊</div><div class=\"label\">O — Other</div><div class=\"desc\">Weather, ads, population etc.</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">👥</div><div class=\"label\">N — Population</div><div class=\"desc\">Only for market demand</div></div>\n    </div>\n\n    <h3>Law of Demand</h3>\n    <div class=\"info-card\">\n      <div class=\"emoji\">↓</div>\n      <div class=\"label\">Inverse Relationship</div>\n      <div class=\"desc\">As price ↑, quantity demanded ↓ and vice versa (ceteris paribus)</div>\n    </div>\n\n    <h4>Reasons for the Law</h4>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">💸</div><div class=\"label\">Substitution Effect</div><div class=\"desc\">When P ↑, consumers switch to cheaper substitutes</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💶</div><div class=\"label\">Income Effect</div><div class=\"desc\">When P ↑, real income ↓, purchasing power ↓</div></div>\n    </div>\n\n    <h3>Change in Quantity Demanded vs Change in Demand</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">↕ Change in Q<sub>d</sub></div>\n        <ul>\n          <li>Movement <strong>along</strong> the demand curve</li>\n          <li>Caused by change in <strong>own price</strong> (P)</li>\n          <li>Extension: P ↓ → Q<sub>d</sub> ↑</li>\n          <li>Contraction: P ↑ → Q<sub>d</sub> ↓</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">↔ Change in Demand</div>\n        <ul>\n          <li><strong>Shift</strong> of the entire demand curve</li>\n          <li>Caused by non-price factors (P<sub>n</sub>, Y, T, Ex, O, N)</li>\n          <li>Increase: curve shifts <strong>right</strong></li>\n          <li>Decrease: curve shifts <strong>left</strong></li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"diagram-box\">\n      <pre>Demand Curve (Law of Demand)\nPrice\n  |\nP1 |    o--- D\n  |   /|\n  |  / |\nP2 | /  o--- D\n  |/\n  +------------------ Quantity\n     Q1    Q2\n\nD slopes downward: inverse relationship\n      </pre>\n    </div>\n  </div>\n\n  <!-- 2. Supply -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📈</div>\n    <h2>Supply <span class=\"underline\"></span></h2>\n    <p><strong>Supply</strong> refers to the various quantities of a good or service that producers are <strong>willing to supply</strong> at alternative prices during a given time period.</p>\n\n    <h3>Institutional vs Market Supply</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🏭 Institutional Supply</div>\n        <ul>\n          <li>Quantity supplied by a <strong>single firm</strong></li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">👥 Market Supply</div>\n        <ul>\n          <li>Sum of all institutional supplies</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Law of Supply</h3>\n    <div class=\"info-card\">\n      <div class=\"emoji\">↑</div>\n      <div class=\"label\">Positive Relationship</div>\n      <div class=\"desc\">As price ↑, quantity supplied ↑ and vice versa (ceteris paribus)</div>\n    </div>\n\n    <h4>Reasons for the Law</h4>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">💰</div><div class=\"label\">Profit Concept</div><div class=\"desc\">Higher price → higher profit incentive to produce more</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">↗️</div><div class=\"label\">Law of Increasing Opportunity Cost</div><div class=\"desc\">Higher output requires higher price to cover rising marginal costs</div></div>\n    </div>\n\n    <div class=\"diagram-box\">\n      <pre>Supply Curve (Law of Supply)\nPrice\n  |\n  |    / S\n  |   /\nP2 |  o---\n  | / |\nP1 |/  o---\n  +------------------ Quantity\n     Q1    Q2\n\nS slopes upward: positive relationship\n      </pre>\n    </div>\n  </div>\n\n  <!-- 3. Market Equilibrium -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚖️</div>\n    <h2>Market Equilibrium <span class=\"underline\"></span></h2>\n    <p>At equilibrium, the quantity demanded <strong>equals</strong> the quantity supplied at a particular price where buyers and producers mutually agree.</p>\n\n    <h3>Conditions for Equilibrium</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">💵</div><div class=\"label\">Demand Price = Supply Price</div><div class=\"desc\">Buyers and sellers agree on price</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📊</div><div class=\"label\">Q<sub>d</sub> = Q<sub>s</sub></div><div class=\"desc\">Quantity demanded = Quantity supplied</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">❌</div><div class=\"label\">Excess Demand = 0</div><div class=\"desc\">No shortage</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">❌</div><div class=\"label\">Excess Supply = 0</div><div class=\"desc\">No surplus</div></div>\n    </div>\n\n    <h3>Excess Demand &amp; Excess Supply</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">📈 Excess Demand (Shortage)</div>\n        <ul>\n          <li>Price is <strong>below</strong> equilibrium</li>\n          <li>Q<sub>d</sub> &gt; Q<sub>s</sub></li>\n          <li>Market pressure: Price ↑</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📉 Excess Supply (Surplus)</div>\n        <ul>\n          <li>Price is <strong>above</strong> equilibrium</li>\n          <li>Q<sub>s</sub> &gt; Q<sub>d</sub></li>\n          <li>Market pressure: Price ↓</li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"diagram-box\">\n      <pre>Market Equilibrium\nPrice\n  |\n  |        S\n  |       /\n  |      /   Equilibrium Point (E)\nP* |-----X-------\n  |    /|   \\\n  |   / |    \\  D\n  |  /  |     \\\n  +------------------ Quantity\n     Q*\n     \nAt P*: Qd = Qs = Q*\nAbove P*: Surplus (Qs &gt; Qd)\nBelow P*: Shortage (Qd &gt; Qs)\n      </pre>\n    </div>\n\n    <h3>Finding Equilibrium from Equations</h3>\n    <h4>Example 1</h4>\n    <div class=\"formula-box\" style=\"font-size: 0.95rem;\">\n      Q<sub>d</sub> = 4250 − 25P &nbsp;&nbsp; Q<sub>s</sub> = 2000 + 50P\n    </div>\n    <ol class=\"step-list\">\n      <li>Set Q<sub>d</sub> = Q<sub>s</sub>: 4250 − 25P = 2000 + 50P</li>\n      <li>4250 − 2000 = 50P + 25P → 2250 = 75P</li>\n      <li><strong>P* = 30</strong></li>\n      <li>Substitute: Q<sub>d</sub> = 4250 − 25(30) = 4250 − 750</li>\n      <li><strong>Q* = 3500</strong></li>\n    </ol>\n\n    <h4>Example 2</h4>\n    <div class=\"formula-box\" style=\"font-size: 0.95rem;\">\n      Q<sub>d</sub> = 30 − 2P &nbsp;&nbsp; Q<sub>s</sub> = −6 + 2P\n    </div>\n    <ol class=\"step-list\">\n      <li>Set Q<sub>d</sub> = Q<sub>s</sub>: 30 − 2P = −6 + 2P</li>\n      <li>30 + 6 = 2P + 2P → 36 = 4P</li>\n      <li><strong>P* = 9</strong></li>\n      <li>Substitute: Q<sub>d</sub> = 30 − 2(9) = 30 − 18</li>\n      <li><strong>Q* = 12</strong></li>\n    </ol>\n\n    <div class=\"info-card\">\n      <div class=\"emoji\">💡</div>\n      <div class=\"label\">Check: Excess = Q<sub>d</sub> − Q<sub>s</sub></div>\n      <div class=\"desc\">If P &lt; P* → Excess Demand (positive) → Price ↑<br>If P &gt; P* → Excess Supply (negative) → Price ↓</div>\n    </div>\n  </div>\n\n  <!-- 4. Consumer & Producer Surplus -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💰</div>\n    <h2>Consumer &amp; Producer Surplus <span class=\"underline\"></span></h2>\n\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🧑 Consumer Surplus</div>\n        <ul>\n          <li>Difference between <strong>maximum price</strong> a consumer is willing to pay and the <strong>equilibrium price</strong></li>\n          <li>Area <strong>below</strong> the demand curve and <strong>above</strong> the price</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🏭 Producer Surplus</div>\n        <ul>\n          <li>Difference between the <strong>equilibrium price</strong> and the <strong>minimum supply price</strong></li>\n          <li>Area <strong>above</strong> the supply curve and <strong>below</strong> the price</li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"formula-box\">\n      Economic Surplus = Consumer Surplus + Producer Surplus\n    </div>\n\n    <div class=\"diagram-box\">\n      <pre>Consumer &amp; Producer Surplus\nPrice\n  |\n  |    S\n  |   / \\\n  |  /   \\\nP* |-/-----X-------\n  |/ CS |PS \\\n  +-----+----\\---- Quantity\n        Q*\n\nCS = area between demand &amp; price (above P*)\nPS = area between supply &amp; price (below P*)\n      </pre>\n    </div>\n  </div>\n\n  <!-- 5. Elasticity of Demand -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">↔️</div>\n    <h2>Elasticity of Demand <span class=\"underline\"></span></h2>\n    <p>Elasticity measures the <strong>responsiveness</strong> of quantity demanded to changes in its determinants.</p>\n\n    <h3>Price Elasticity of Demand (PED)</h3>\n    <div class=\"formula-box\">\n      PED = %ΔQ<sub>d</sub> / %ΔP\n    </div>\n\n    <h4>Point Elasticity Formula</h4>\n    <div class=\"formula-box\">\n      E<sub>d</sub> = (ΔQ<sub>d</sub>/ΔP) × (P/Q<sub>d</sub>)\n    </div>\n\n    <h3>Types of Elasticity</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">∞</div><div class=\"label\">Perfectly Elastic (E = ∞)</div><div class=\"desc\">Horizontal demand curve; infinite response to price change</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">↑</div><div class=\"label\">Elastic (|E| &gt; 1)</div><div class=\"desc\">%ΔQ<sub>d</sub> &gt; %ΔP; luxury goods</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">↔</div><div class=\"label\">Unit Elastic (|E| = 1)</div><div class=\"desc\">%ΔQ<sub>d</sub> = %ΔP</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">↓</div><div class=\"label\">Inelastic (|E| &lt; 1)</div><div class=\"desc\">%ΔQ<sub>d</sub> &lt; %ΔP; necessities</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">0</div><div class=\"label\">Perfectly Inelastic (E = 0)</div><div class=\"desc\">Vertical demand curve; no response to price change</div></div>\n    </div>\n\n    <h3>Cross Price Elasticity of Demand (XED)</h3>\n    <div class=\"formula-box\">\n      XED = %ΔQ<sub>d</sub> of Good X / %ΔP of Good Y\n    </div>\n    <ul>\n      <li><strong>Positive XED</strong> → Substitutes (tea &amp; coffee)</li>\n      <li><strong>Negative XED</strong> → Complements (cars &amp; petrol)</li>\n      <li><strong>Zero XED</strong> → Unrelated goods</li>\n    </ul>\n\n    <h3>Income Elasticity of Demand (YED)</h3>\n    <div class=\"formula-box\">\n      YED = %ΔQ<sub>d</sub> / %ΔY\n    </div>\n    <ul>\n      <li><strong>Positive YED</strong> → Normal goods (Y ↑ → Q<sub>d</sub> ↑)</li>\n      <li><strong>Negative YED</strong> → Inferior goods (Y ↑ → Q<sub>d</sub> ↓)</li>\n      <li>YED &gt; 1 → Luxury goods; 0 &lt; YED &lt; 1 → Necessities</li>\n    </ul>\n\n    <h3>Determinants of Price Elasticity of Demand</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🔄</div><div class=\"label\">Availability of Substitutes</div><div class=\"desc\">More substitutes = more elastic</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💵</div><div class=\"label\">Proportion of Income</div><div class=\"desc\">Higher proportion = more elastic</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📅</div><div class=\"label\">Time Period</div><div class=\"desc\">Longer time = more elastic</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🔔</div><div class=\"label\">Necessity vs Luxury</div><div class=\"desc\">Necessities = inelastic; Luxuries = elastic</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🪙</div><div class=\"label\">Nature of Good</div><div class=\"desc\">Addictive goods = inelastic</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📦</div><div class=\"label\">Narrowness of Market</div><div class=\"desc\">Narrower definition = more elastic</div></div>\n    </div>\n\n    <h3>Practical Importance of Price Elasticity</h3>\n    <div class=\"timeline\">\n      <div class=\"timeline-item\"><div class=\"title\">💰 Pricing Decisions</div><div class=\"desc\">Firms set prices based on elasticity to maximize revenue</div></div>\n      <div class=\"timeline-item\"><div class=\"title\">🏛️ Government Policy</div><div class=\"desc\">Taxation: inelastic goods generate more tax revenue</div></div>\n      <div class=\"timeline-item\"><div class=\"title\">🌍 International Trade</div><div class=\"desc\">Exchange rate changes affect export/import demand</div></div>\n      <div class=\"timeline-item\"><div class=\"title\">👥 Consumer Behavior</div><div class=\"desc\">Understanding how consumers respond to price changes</div></div>\n    </div>\n  </div>\n\n  <!-- 6. Price Elasticity of Supply -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📄</div>\n    <h2>Price Elasticity of Supply <span class=\"underline\"></span></h2>\n    <p>Measures the responsiveness of quantity supplied to a change in price.</p>\n\n    <div class=\"formula-box\">\n      PES = %ΔQ<sub>s</sub> / %ΔP\n    </div>\n\n    <h3>Types of Supply Elasticity</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">∞</div><div class=\"label\">Perfectly Elastic (PES = ∞)</div><div class=\"desc\">Horizontal supply curve</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">↑</div><div class=\"label\">Elastic (PES &gt; 1)</div><div class=\"desc\">%ΔQ<sub>s</sub> &gt; %ΔP</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">↔</div><div class=\"label\">Unit Elastic (PES = 1)</div><div class=\"desc\">%ΔQ<sub>s</sub> = %ΔP</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">↓</div><div class=\"label\">Inelastic (PES &lt; 1)</div><div class=\"desc\">%ΔQ<sub>s</sub> &lt; %ΔP</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">0</div><div class=\"label\">Perfectly Inelastic (PES = 0)</div><div class=\"desc\">Vertical supply curve; fixed supply (land, unique art)</div></div>\n    </div>\n\n    <div class=\"diagram-box\">\n      <pre>Price Elasticity of Supply\nPrice\n  |\n  |   S3  S2  S1\n  |    \\   \\   \\\n  |     \\   \\   \\\nP1|------\\---\\---\\---\n  |       \\   \\   \\\n  +------------------ Quantity\n         \nS1: Elastic (PES &gt; 1)   - flatter\nS2: Unit Elastic (PES=1)\nS3: Inelastic (PES &lt; 1) - steeper\n      </pre>\n    </div>\n  </div>\n\n  <!-- 7. Flashcards -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📚</div>\n    <h2>Key Concepts Flashcards <span class=\"underline\"></span></h2>\n\n    <div class=\"flashcard-container\">\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            Law of Demand\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Inverse relationship between price and quantity demanded<br>\n            <small>P ↑ → Q<sub>d</sub> ↓ (ceteris paribus)</small>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            Law of Supply\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Positive relationship between price and quantity supplied<br>\n            <small>P ↑ → Q<sub>s</sub> ↑ (ceteris paribus)</small>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            Market Equilibrium\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Q<sub>d</sub> = Q<sub>s</sub><br>\n            <small>No excess demand or supply</small>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            Consumer Surplus\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Max price willing to pay − equilibrium price<br>\n            <small>Benefit to consumers</small>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            Price Elasticity of Demand\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            %ΔQ<sub>d</sub> / %ΔP<br>\n            <small>Responsiveness of demand to price</small>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            Cross Price Elasticity\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            %ΔQ<sub>dX</sub> / %ΔP<sub>Y</sub><br>\n            <small>Substitutes (+) / Complements (−)</small>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 8. Quick Comparison Tables -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📊</div>\n    <h2>Comparison Tables <span class=\"underline\"></span></h2>\n\n    <h3>Demand vs Supply</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">📉 Demand</div>\n        <ul>\n          <li>Buyers / Consumers</li>\n          <li>Inverse relationship with price</li>\n          <li>Downward-sloping curve</li>\n          <li>Determinants: P, P<sub>n</sub>, Y, T, Ex, O</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📈 Supply</div>\n        <ul>\n          <li>Sellers / Producers</li>\n          <li>Positive relationship with price</li>\n          <li>Upward-sloping curve</li>\n          <li>Profit concept &amp; increasing opportunity cost</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Change in Quantity Demanded vs Change in Demand</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">↕ Change in Q<sub>d</sub></div>\n        <ul>\n          <li>Movement along curve</li>\n          <li>Caused by price change</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">↔ Change in Demand</div>\n        <ul>\n          <li>Shift of entire curve</li>\n          <li>Caused by non-price factors</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Types of Goods by Income Elasticity</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">💰 Normal Goods</div>\n        <ul>\n          <li>YED &gt; 0</li>\n          <li>Demand increases with income</li>\n          <li>Necessities: 0 &lt; YED &lt; 1</li>\n          <li>Luxuries: YED &gt; 1</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📉 Inferior Goods</div>\n        <ul>\n          <li>YED &lt; 0</li>\n          <li>Demand decreases as income rises</li>\n          <li>Ex: public transport, instant noodles</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 9. Elasticity Formulas Summary -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📏</div>\n    <h2>Elasticity Formulas Summary <span class=\"underline\"></span></h2>\n\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">💵</div>\n        <div class=\"label\">Price Elasticity of Demand</div>\n        <div class=\"desc\" style=\"font-family: 'Courier New', monospace; font-size: 0.9rem;\">\n          Ed = %ΔQd / %ΔP<br>\n          = (ΔQ/ΔP) × (P/Q)\n        </div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🔄</div>\n        <div class=\"label\">Cross Price Elasticity</div>\n        <div class=\"desc\" style=\"font-family: 'Courier New', monospace; font-size: 0.9rem;\">\n          XED = %ΔQdX / %ΔPY\n        </div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">💰</div>\n        <div class=\"label\">Income Elasticity</div>\n        <div class=\"desc\" style=\"font-family: 'Courier New', monospace; font-size: 0.9rem;\">\n          YED = %ΔQd / %ΔY\n        </div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📄</div>\n        <div class=\"label\">Price Elasticity of Supply</div>\n        <div class=\"desc\" style=\"font-family: 'Courier New', monospace; font-size: 0.9rem;\">\n          PES = %ΔQs / %ΔP\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 10. Interactive Quiz -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧰</div>\n    <h2>Test Your Knowledge <span class=\"underline\"></span></h2>\n\n    <div class=\"quiz-question\" data-q=\"1\">\n      <div class=\"q\">1. According to the Law of Demand, when price increases:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Quantity supplied increases</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Quantity demanded decreases</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Demand shifts right</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Supply shifts left</button>\n      <div class=\"quiz-feedback\" data-feedback=\"1\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"2\">\n      <div class=\"q\">2. Which of the following causes a change in demand (shift of the curve)?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">A decrease in the price of the good</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">An increase in consumer income</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">An increase in the price of the good</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">All of the above</button>\n      <div class=\"quiz-feedback\" data-feedback=\"2\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"3\">\n      <div class=\"q\">3. At market equilibrium:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Price is always high</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">There is excess demand</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">There is excess supply</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Quantity demanded equals quantity supplied</button>\n      <div class=\"quiz-feedback\" data-feedback=\"3\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"4\">\n      <div class=\"q\">4. If Qd = 30 − 2P and Qs = −6 + 2P, the equilibrium price is:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">6</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">9</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">12</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">36</button>\n      <div class=\"quiz-feedback\" data-feedback=\"4\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"5\">\n      <div class=\"q\">5. Consumer surplus is the difference between:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Price and cost</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Maximum willingness to pay and equilibrium price</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Equilibrium price and minimum supply price</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Total revenue and total cost</button>\n      <div class=\"quiz-feedback\" data-feedback=\"5\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"6\">\n      <div class=\"q\">6. If a good has many close substitutes, its price elasticity is likely to be:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Inelastic</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Elastic</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Unit elastic</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Perfectly inelastic</button>\n      <div class=\"quiz-feedback\" data-feedback=\"6\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"7\">\n      <div class=\"q\">7. Cross price elasticity between substitutes is:</div>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Positive</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Negative</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Zero</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Infinite</button>\n      <div class=\"quiz-feedback\" data-feedback=\"7\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"8\">\n      <div class=\"q\">8. The Law of Supply states there is a:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Inverse relationship between price and quantity supplied</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Positive relationship between price and quantity supplied</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">No relationship between price and quantity supplied</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Constant relationship between price and quantity supplied</button>\n      <div class=\"quiz-feedback\" data-feedback=\"8\"></div>\n    </div>\n  </div>\n\n</div>\n\n<script>\n  const canvas = document.getElementById('particles');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  class Particle {\n    constructor() {\n      this.reset();\n    }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.5;\n      this.speedY = (Math.random() - 0.5) * 0.5;\n      this.opacity = Math.random() * 0.5 + 0.1;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n      if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(9, 132, 227, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 80; i++) particles.push(new Particle());\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 150) {\n          ctx.beginPath();\n          ctx.strokeStyle = `rgba(9, 132, 227, ${0.06 * (1 - dist / 150)})`;\n          ctx.lineWidth = 0.5;\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  const sections = document.querySelectorAll('[data-section]');\n\n  function revealSections() {\n    sections.forEach(section => {\n      const rect = section.getBoundingClientRect();\n      if (rect.top < window.innerHeight - 80) {\n        section.classList.add('visible');\n      }\n    });\n  }\n  window.addEventListener('scroll', revealSections);\n  revealSections();\n\n  const progressBar = document.getElementById('progressBar');\n\n  window.addEventListener('scroll', () => {\n    const scrollTop = window.scrollY;\n    const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n    const progress = (scrollTop / docHeight) * 100;\n    progressBar.style.width = progress + '%';\n  });\n\n  function checkAnswer(btn, isCorrect) {\n    const question = btn.closest('.quiz-question');\n    const options = question.querySelectorAll('.quiz-option');\n    const feedback = question.querySelector('.quiz-feedback');\n\n    options.forEach(opt => {\n      opt.disabled = true;\n      opt.style.cursor = 'not-allowed';\n      if (opt.dataset.correct === 'true') opt.classList.add('correct');\n    });\n\n    if (isCorrect) {\n      btn.classList.add('correct');\n      feedback.textContent = '&#x2705; Correct!';\n      feedback.className = 'quiz-feedback show correct';\n    } else {\n      btn.classList.add('wrong');\n      const correctBtn = question.querySelector('[data-correct=\"true\"]');\n      feedback.textContent = '&#x274C; Incorrect. The answer was: ' + correctBtn.textContent;\n      feedback.className = 'quiz-feedback show wrong';\n    }\n  }\n</script>\n\n\n\n\n</body>\n</html>",
    "3": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"progress-container\">\n  <div class=\"progress-bar\" id=\"progressBar\"></div>\n</div>\n\n<canvas id=\"particles\"></canvas>\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">Lesson 3</div>\n  <h1>Government Intervention<br>in Markets</h1>\n  <p>Understanding how governments intervene through price controls, taxes, subsidies, and supporting policies to correct market outcomes.</p>\n  <div class=\"hero-scroll\">↓</div>\n</section>\n\n<div class=\"container\">\n\n\n\n  <!-- 1. Price Control Overview -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚖️</div>\n    <h2>Price Control <span class=\"underline\"></span></h2>\n    <p>Governments intervene in markets when they perceive the market equilibrium price as <strong>unfair</strong> or socially undesirable. The two main types of price control are:</p>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🟢 Maximum Price (Ceiling)</div>\n        <ul>\n          <li>Legal price set <strong>below</strong> equilibrium</li>\n          <li>Also called a <strong>price ceiling</strong></li>\n          <li>Only effective when set below market equilibrium</li>\n          <li>Aims to protect consumers from high prices</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🔴 Minimum Price (Floor)</div>\n        <ul>\n          <li>Legal price set <strong>above</strong> equilibrium</li>\n          <li>Also called a <strong>price floor</strong></li>\n          <li>Only effective when set above market equilibrium</li>\n          <li>Aims to protect producers from low prices</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 2. Maximum Price -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📭</div>\n    <h2>Maximum Price (Ceiling Price) <span class=\"underline\"></span></h2>\n    <p>A legal maximum price set <strong>below</strong> the equilibrium price. At this price, the quantity demanded exceeds the quantity supplied, creating a <strong>shortage</strong>.</p>\n\n    <h3>Effects of Maximum Price</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">⚠️</div>\n        <div class=\"label\">Shortage</div>\n        <div class=\"desc\">Excess demand: Qd &gt; Qs at the ceiling price</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🎵</div>\n        <div class=\"label\">Black Market</div>\n        <div class=\"desc\">Illegal trading at prices above the ceiling</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">💰</div>\n        <div class=\"label\">Hidden Supply</div>\n        <div class=\"desc\">Suppliers may hide goods to sell at higher prices</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📉</div>\n        <div class=\"label\">Welfare Loss</div>\n        <div class=\"desc\">Reduction in total economic surplus</div>\n      </div>\n    </div>\n\n    <h3>Surplus Analysis: Before vs After</h3>\n    <div class=\"surplus-table\" style=\"overflow-x: auto;\">\n      <table class=\"surplus-table\">\n        <tbody><tr>\n          <th>Component</th>\n          <th>Before Ceiling</th>\n          <th>After Ceiling</th>\n          <th>Change</th>\n        </tr>\n        <tr>\n          <td>Consumer Surplus</td>\n          <td>A + B</td>\n          <td>A + C</td>\n          <td class=\"accent2\">+C − B</td>\n        </tr>\n        <tr>\n          <td>Producer Surplus</td>\n          <td>C + D + E</td>\n          <td>E</td>\n          <td class=\"red\">−(C + D)</td>\n        </tr>\n        <tr>\n          <td>Economic Surplus</td>\n          <td>A + B + C + D + E</td>\n          <td>A + C + E</td>\n          <td class=\"red\">−(B + D)</td>\n        </tr>\n      </tbody></table>\n    </div>\n\n    <h3>Black Market Price Calculation</h3>\n    <p>In a black market, goods are sold illegally at prices above the ceiling. The black market price is determined by the quantity supplied at the ceiling price and the demand curve.</p>\n    <div class=\"formula-box\">\n      Black Market Price = Price at which Q<sub>supplied</sub> = Q<sub>demanded</sub> on the original demand curve\n    </div>\n\n    <h3>Remedies for Shortage</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🌍</div><div class=\"label\">Import</div><div class=\"desc\">Import goods from abroad to increase supply</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📈</div><div class=\"label\">Producer Incentives</div><div class=\"desc\">Subsidies or tax breaks to encourage domestic production</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🎯</div><div class=\"label\">Rationing</div><div class=\"desc\">Ration cards, queueing, bribes, or connecting goods to allocate scarce supply</div></div>\n    </div>\n\n    <div class=\"walkthrough\">\n      <div style=\"font-weight: 600; color: #fff; margin-bottom: 0.8rem;\">📍 Step-by-Step: Maximum Price Effects</div>\n      <div class=\"step\">\n        <div class=\"step-num\">1</div>\n        <div class=\"step-content\">Government sets a ceiling price <strong>P<sub>c</sub></strong> below equilibrium <strong>P<sub>e</sub></strong></div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">2</div>\n        <div class=\"step-content\">At P<sub>c</sub>, Q<sub>d</sub> &gt; Q<sub>s</sub> → <strong>shortage</strong> of size (Q<sub>d</sub> − Q<sub>s</sub>)</div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">3</div>\n        <div class=\"step-content\">Transaction quantity falls from Q<sub>e</sub> to Q<sub>s</sub> (supply constrained)</div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">4</div>\n        <div class=\"step-content\">Consumer surplus: some consumers gain (lower price), others lose (cannot buy) → net ambiguous change</div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">5</div>\n        <div class=\"step-content\">Producer surplus <strong>decreases</strong> → producers sell less at a lower price</div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">6</div>\n        <div class=\"step-content\">Deadweight loss = area <strong>B + D</strong> → economic surplus <strong>decreases</strong></div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 3. Minimum Price -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📑</div>\n    <h2>Minimum Price (Floor Price) <span class=\"underline\"></span></h2>\n    <p>A legal minimum price set <strong>above</strong> the equilibrium price. At this price, the quantity supplied exceeds the quantity demanded, creating <strong>excess supply</strong> (surplus).</p>\n\n    <h3>Effects of Minimum Price</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">📦</div>\n        <div class=\"label\">Excess Supply</div>\n        <div class=\"desc\">Qs &gt; Qd at the floor price</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🙅‍♂️</div>\n        <div class=\"label\">Unemployment</div>\n        <div class=\"desc\">In labour markets: minimum wage → job losses</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">💵</div>\n        <div class=\"label\">Excess Investment</div>\n        <div class=\"desc\">Firms over-invest due to guaranteed higher price</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📉</div>\n        <div class=\"label\">Welfare Loss</div>\n        <div class=\"desc\">Deadweight loss from reduced transactions</div>\n      </div>\n    </div>\n\n    <h3>Surplus Analysis: Before vs After</h3>\n    <div class=\"surplus-table\" style=\"overflow-x: auto;\">\n      <table class=\"surplus-table\">\n        <tbody><tr>\n          <th>Component</th>\n          <th>Before Floor</th>\n          <th>After Floor</th>\n          <th>Change</th>\n        </tr>\n        <tr>\n          <td>Consumer Surplus</td>\n          <td>A + B + C</td>\n          <td>A</td>\n          <td class=\"red\">−(B + C)</td>\n        </tr>\n        <tr>\n          <td>Producer Surplus</td>\n          <td>D + E</td>\n          <td>B + D</td>\n          <td class=\"accent2\">+B − E</td>\n        </tr>\n        <tr>\n          <td>Economic Surplus</td>\n          <td>A + B + C + D + E</td>\n          <td>A + B + D</td>\n          <td class=\"red\">−(C + E)</td>\n        </tr>\n      </tbody></table>\n    </div>\n\n    <h3>Remedies for Excess Supply</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">📦</div><div class=\"label\">Storage</div><div class=\"desc\">Government stores the surplus for future use</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🔄</div><div class=\"label\">By-Products</div><div class=\"desc\">Convert surplus into other usable products</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📈</div><div class=\"label\">Demand Promotion</div><div class=\"desc\">Advertising campaigns to boost consumption</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌍</div><div class=\"label\">Exports</div><div class=\"desc\">Sell surplus in international markets</div></div>\n    </div>\n\n    <h3>Maximum vs Minimum Price</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🟢 Maximum Price</div>\n        <ul>\n          <li>Set <strong>below</strong> equilibrium</li>\n          <li>Creates <strong>shortage</strong> (excess demand)</li>\n          <li>Benefits <strong>consumers</strong></li>\n          <li>Leads to black markets</li>\n          <li>Remedies: import, rationing, incentives</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🔴 Minimum Price</div>\n        <ul>\n          <li>Set <strong>above</strong> equilibrium</li>\n          <li>Creates <strong>surplus</strong> (excess supply)</li>\n          <li>Benefits <strong>producers</strong></li>\n          <li>Leads to over-investment</li>\n          <li>Remedies: storage, exports, promotion</li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"walkthrough\">\n      <div style=\"font-weight: 600; color: #fff; margin-bottom: 0.8rem;\">📍 Step-by-Step: Minimum Price Effects</div>\n      <div class=\"step\">\n        <div class=\"step-num\">1</div>\n        <div class=\"step-content\">Government sets a floor price <strong>P<sub>f</sub></strong> above equilibrium <strong>P<sub>e</sub></strong></div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">2</div>\n        <div class=\"step-content\">At P<sub>f</sub>, Q<sub>s</sub> &gt; Q<sub>d</sub> → <strong>excess supply</strong> of size (Q<sub>s</sub> − Q<sub>d</sub>)</div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">3</div>\n        <div class=\"step-content\">Transaction quantity falls from Q<sub>e</sub> to Q<sub>d</sub> (demand constrained)</div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">4</div>\n        <div class=\"step-content\">Consumers buy less at a higher price → consumer surplus <strong>decreases</strong></div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">5</div>\n        <div class=\"step-content\">Producers sell less but at higher price → net change ambiguous depending on elasticities</div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">6</div>\n        <div class=\"step-content\">Deadweight loss = area <strong>C + E</strong> → economic surplus <strong>decreases</strong></div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 4. Price Supporting Policies -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💶</div>\n    <h2>Price Supporting Policies <span class=\"underline\"></span></h2>\n    <p>Two main methods governments use to support prices (especially in agriculture):</p>\n\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">💵 Government Purchases</div>\n        <ul>\n          <li>Government buys excess supply at the minimum price</li>\n          <li>Effectively removes surplus from the market</li>\n          <li>Requires government storage or disposal</li>\n          <li>Cost to government = (P<sub>min</sub> × surplus quantity)</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">💳 Deficiency Payment System</div>\n        <ul>\n          <li>Government pays producers the <strong>difference</strong> between the minimum price and what consumers actually pay</li>\n          <li>Consumers pay the market-clearing price</li>\n          <li>Producers receive the target (minimum) price</li>\n          <li>Cost to government = (P<sub>min</sub> − P<sub>market</sub>) × Q</li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"walkthrough\">\n      <div style=\"font-weight: 600; color: #fff; margin-bottom: 0.8rem;\">📍 Deficiency Payment Walkthrough</div>\n      <div class=\"step\">\n        <div class=\"step-num\">1</div>\n        <div class=\"step-content\">Target price (P<sub>min</sub>) is set above equilibrium</div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">2</div>\n        <div class=\"step-content\">Consumers pay market-clearing price P<sub>m</sub> (where demand meets supply at Q produced)</div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">3</div>\n        <div class=\"step-content\">Government pays producers the deficiency: <strong>(P<sub>min</sub> − P<sub>m</sub>) × Q</strong></div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">4</div>\n        <div class=\"step-content\">Producers receive total revenue = (P<sub>m</sub> × Q) + deficiency payment = P<sub>min</sub> × Q</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 5. Unit Tax -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💰</div>\n    <h2>Unit Tax <span class=\"underline\"></span></h2>\n    <p>A <strong>unit tax</strong> is a fixed tax per unit of a good imposed on producers. It shifts the supply curve upward (leftward) by the amount of the tax.</p>\n\n    <h3>The New Supply Equation</h3>\n    <div class=\"formula-box\">\n      Q<sub>s</sub> = a + b(P − t)\n    </div>\n    <p>Where <strong>t</strong> = tax per unit. For any given market price P, producers only receive (P − t), so they supply less.</p>\n\n    <h3>Tax Burden: Who Pays More?</h3>\n    <p>The distribution of the tax burden depends on <strong>elasticity</strong>:</p>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">📉 Inelastic Demand</div>\n        <ul>\n          <li>Consumers bear <strong>more</strong> of the tax</li>\n          <li>Price rises significantly → consumer price ↑</li>\n          <li>Example: necessities, petrol, cigarettes</li>\n          <li>Consumer share = ΔP / t (larger)</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📈 Elastic Demand</div>\n        <ul>\n          <li>Producers bear <strong>more</strong> of the tax</li>\n          <li>Price rises little → producer price ↓</li>\n          <li>Example: luxury goods, non-essentials</li>\n          <li>Producer share = 1 − (ΔP / t) (larger)</li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"elasticity-meter\">\n      <span class=\"label\">Consumer burden</span>\n      <div class=\"bar\"><div class=\"fill consumer\" style=\"width: 70%\" data-width=\"inelastic\"></div></div>\n      <span style=\"font-size: 0.8rem; color: var(--text-muted);\">Inelastic →</span>\n    </div>\n    <div class=\"elasticity-meter\">\n      <span class=\"label\">Producer burden</span>\n      <div class=\"bar\"><div class=\"fill producer\" style=\"width: 30%\" data-width=\"inelastic\"></div></div>\n      <span style=\"font-size: 0.8rem; color: var(--text-muted);\">← Elastic</span>\n    </div>\n\n    <h3>Surplus Analysis with Tax</h3>\n    <div class=\"surplus-table\" style=\"overflow-x: auto;\">\n      <table class=\"surplus-table\">\n        <tbody><tr>\n          <th>Component</th>\n          <th>Before Tax</th>\n          <th>After Tax</th>\n          <th>Change</th>\n        </tr>\n        <tr>\n          <td>Consumer Surplus</td>\n          <td>A + B + C</td>\n          <td>A</td>\n          <td class=\"red\">−(B + C)</td>\n        </tr>\n        <tr>\n          <td>Producer Surplus</td>\n          <td>D + E + F</td>\n          <td>F</td>\n          <td class=\"red\">−(D + E)</td>\n        </tr>\n        <tr>\n          <td>Government Revenue</td>\n          <td>—</td>\n          <td>B + D</td>\n          <td class=\"accent2\">+(B + D)</td>\n        </tr>\n        <tr>\n          <td>Economic Surplus</td>\n          <td>A + B + C + D + E + F</td>\n          <td>A + B + D + F</td>\n          <td class=\"red\">−(C + E)</td>\n        </tr>\n      </tbody></table>\n    </div>\n\n    <div class=\"walkthrough\">\n      <div style=\"font-weight: 600; color: #fff; margin-bottom: 0.8rem;\">📍 Step-by-Step: Unit Tax Effects</div>\n      <div class=\"step\">\n        <div class=\"step-num\">1</div>\n        <div class=\"step-content\">Tax of <strong>t</strong> per unit imposed on producers → supply shifts up by <strong>t</strong></div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">2</div>\n        <div class=\"step-content\">New equilibrium: quantity falls, consumer price <strong>rises</strong>, producer price <strong>falls</strong></div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">3</div>\n        <div class=\"step-content\">Consumer pays: P<sub>c</sub> = original P<sub>e</sub> + ΔP<sub>c</sub></div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">4</div>\n        <div class=\"step-content\">Producer receives: P<sub>p</sub> = P<sub>c</sub> − t = original P<sub>e</sub> − ΔP<sub>p</sub></div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">5</div>\n        <div class=\"step-content\">Government revenue = <strong>t × Q<sub>new</sub></strong> (area <strong>B + D</strong>)</div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">6</div>\n        <div class=\"step-content\">Deadweight loss = area <strong>C + E</strong> (transactions that no longer occur)</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 6. Unit Subsidy -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💸</div>\n    <h2>Unit Subsidy <span class=\"underline\"></span></h2>\n    <p>A <strong>unit subsidy</strong> is a payment per unit of a good from the government to producers (a \"negative tax\"). It shifts the supply curve downward (rightward) by the amount of the subsidy.</p>\n\n    <h3>The New Supply Equation</h3>\n    <div class=\"formula-box\">\n      Q<sub>s</sub> = a + b(P + s)\n    </div>\n    <p>Where <strong>s</strong> = subsidy per unit. For any given market price P, producers receive (P + s), so they supply more.</p>\n\n    <h3>Subsidy Benefit: Who Gains More?</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">📉 Inelastic Demand</div>\n        <ul>\n          <li>Producers capture <strong>more</strong> of the subsidy</li>\n          <li>Price falls little → producers keep most of it</li>\n          <li>Consumer share = ΔP / s (smaller)</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📈 Elastic Demand</div>\n        <ul>\n          <li>Consumers capture <strong>more</strong> of the subsidy</li>\n          <li>Price falls significantly → consumers benefit</li>\n          <li>Consumer share = ΔP / s (larger)</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Surplus Analysis with Subsidy</h3>\n    <div class=\"surplus-table\" style=\"overflow-x: auto;\">\n      <table class=\"surplus-table\">\n        <tbody><tr>\n          <th>Component</th>\n          <th>Before Subsidy</th>\n          <th>After Subsidy</th>\n          <th>Change</th>\n        </tr>\n        <tr>\n          <td>Consumer Surplus</td>\n          <td>A</td>\n          <td>A + B + C</td>\n          <td class=\"accent2\">+(B + C)</td>\n        </tr>\n        <tr>\n          <td>Producer Surplus</td>\n          <td>F</td>\n          <td>D + E + F</td>\n          <td class=\"accent2\">+(D + E)</td>\n        </tr>\n        <tr>\n          <td>Government Cost</td>\n          <td>—</td>\n          <td>B + C + D + E + G</td>\n          <td class=\"red\">−(B + C + D + E + G)</td>\n        </tr>\n        <tr>\n          <td>Economic Surplus</td>\n          <td>A + F</td>\n          <td>A + B + C + D + E + F</td>\n          <td class=\"red\">−G</td>\n        </tr>\n      </tbody></table>\n    </div>\n\n    <div class=\"walkthrough\">\n      <div style=\"font-weight: 600; color: #fff; margin-bottom: 0.8rem;\">📍 Step-by-Step: Unit Subsidy Effects</div>\n      <div class=\"step\">\n        <div class=\"step-num\">1</div>\n        <div class=\"step-content\">Subsidy of <strong>s</strong> per unit given to producers → supply shifts down by <strong>s</strong></div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">2</div>\n        <div class=\"step-content\">New equilibrium: quantity <strong>rises</strong>, consumer price <strong>falls</strong></div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">3</div>\n        <div class=\"step-content\">Consumer price falls by less than s (unless demand is perfectly elastic)</div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">4</div>\n        <div class=\"step-content\">Producer receives: P<sub>p</sub> = P<sub>c</sub> + s (more than before)</div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">5</div>\n        <div class=\"step-content\">Cost to government = <strong>s × Q<sub>new</sub></strong> (large area)</div>\n      </div>\n      <div class=\"step\">\n        <div class=\"step-num\">6</div>\n        <div class=\"step-content\">Deadweight loss = area <strong>G</strong> (overproduction beyond efficient output)</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 7. Tax vs Subsidy Comparison -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚖️</div>\n    <h2>Tax vs Subsidy Comparison <span class=\"underline\"></span></h2>\n    <div class=\"three-col\">\n      <div class=\"col1\">\n        <div class=\"header\">💰 Unit Tax</div>\n        <ul>\n          <li>Supply shifts <strong>up</strong></li>\n          <li>Quantity <strong>falls</strong></li>\n          <li>Consumer price <strong>↑</strong></li>\n          <li>Producer price <strong>↓</strong></li>\n          <li>Gov revenue <strong>+</strong></li>\n          <li>Surplus <strong>−</strong></li>\n          <li>DWL: underproduction</li>\n        </ul>\n      </div>\n      <div class=\"col2\">\n        <div class=\"header\">💸 Unit Subsidy</div>\n        <ul>\n          <li>Supply shifts <strong>down</strong></li>\n          <li>Quantity <strong>rises</strong></li>\n          <li>Consumer price <strong>↓</strong></li>\n          <li>Producer price <strong>↑</strong></li>\n          <li>Gov cost <strong>−</strong></li>\n          <li>Surplus <strong>−</strong></li>\n          <li>DWL: overproduction</li>\n        </ul>\n      </div>\n      <div class=\"col3\">\n        <div class=\"header\">📊 Key Insight</div>\n        <ul>\n          <li>Both create DWL</li>\n          <li>Burden/benefit split depends on <strong>elasticity</strong></li>\n          <li>Inelastic side bears more tax / captures more subsidy</li>\n          <li>Both reduce economic efficiency</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 8. Flashcards -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📚</div>\n    <h2>Key Terms <span class=\"underline\"></span></h2>\n    <div class=\"flashcard-container\">\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🟢 Maximum Price (Ceiling)\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Legal price set <strong>below</strong> equilibrium<br>\n            <small>Creates shortage, black markets<br>Protects consumers</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🔴 Minimum Price (Floor)\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Legal price set <strong>above</strong> equilibrium<br>\n            <small>Creates excess supply<br>Protects producers</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🎵 Black Market\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Illegal trading above ceiling price<br>\n            <small>Price determined by demand at Q<sub>s</sub></small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            💰 Unit Tax\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Fixed tax per unit on producers<br>\n            <small>Qs = a + b(P − t)<br>Creates DWL (C + E)</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            💸 Unit Subsidy\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Government payment per unit to producers<br>\n            <small>Qs = a + b(P + s)<br>\"Negative tax\"</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            💳 Deficiency Payment\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Gov pays difference between min price &amp; market price<br>\n            <small>Producers get P<sub>min</sub>, consumers pay P<sub>mkt</sub></small>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 9. Interactive Quiz -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧰</div>\n    <h2>Test Your Knowledge <span class=\"underline\"></span></h2>\n\n    <div class=\"quiz-question\" data-q=\"1\">\n      <div class=\"q\">1. A maximum price (ceiling) is effective only when it is set:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Above the equilibrium price</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Below the equilibrium price</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">At the equilibrium price</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">On the supply curve</button>\n      <div class=\"quiz-feedback\" data-feedback=\"1\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"2\">\n      <div class=\"q\">2. What is the immediate result of an effective minimum price (floor)?</div>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Excess supply (surplus)</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Shortage</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Black market activity</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Lower prices for consumers</button>\n      <div class=\"quiz-feedback\" data-feedback=\"2\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"3\">\n      <div class=\"q\">3. When demand is inelastic, who bears more of a unit tax?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Producers</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Consumers</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">The government</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Both equally</button>\n      <div class=\"quiz-feedback\" data-feedback=\"3\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"4\">\n      <div class=\"q\">4. Under the deficiency payment system, the government:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Buys the entire surplus at market price</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Sets a ceiling price below equilibrium</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Pays producers the difference between the minimum price and what consumers pay</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Imposes a tax on producers</button>\n      <div class=\"quiz-feedback\" data-feedback=\"4\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"5\">\n      <div class=\"q\">5. Which of the following is NOT a remedy for a shortage caused by a maximum price?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Importing goods</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Rationing</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Storing the excess supply</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Producer incentives</button>\n      <div class=\"quiz-feedback\" data-feedback=\"5\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"6\">\n      <div class=\"q\">6. A unit subsidy shifts the supply curve:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Upward by the amount of the subsidy</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Downward by the amount of the subsidy</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Leftward by the amount of the subsidy</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">It does not shift the supply curve</button>\n      <div class=\"quiz-feedback\" data-feedback=\"6\"></div>\n    </div>\n\n    <button class=\"btn-reset\" onclick=\"resetQuiz()\">🔄 Reset Quiz</button>\n  </div>\n\n  <!-- 10. All Formulas Summary -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📝</div>\n    <h2>Formula Summary <span class=\"underline\"></span></h2>\n    <div class=\"formula-box\" style=\"font-size: 0.9rem;\">\n      Unit Tax Supply: Q<sub>s</sub> = a + b(P − t)\n    </div>\n    <div class=\"formula-box\" style=\"font-size: 0.9rem;\">\n      Unit Subsidy Supply: Q<sub>s</sub> = a + b(P + s)\n    </div>\n    <div class=\"formula-box\" style=\"font-size: 0.9rem;\">\n      Government Revenue from Tax = t × Q<sub>new</sub>\n    </div>\n    <div class=\"formula-box\" style=\"font-size: 0.9rem;\">\n      Cost of Subsidy to Government = s × Q<sub>new</sub>\n    </div>\n    <div class=\"formula-box\" style=\"font-size: 0.9rem;\">\n      Deficiency Payment = (P<sub>min</sub> − P<sub>mkt</sub>) × Q\n    </div>\n    <div class=\"formula-box\" style=\"font-size: 0.9rem;\">\n      Black Market Price = Price where Q<sub>demanded</sub> = Q<sub>supplied (at ceiling)</sub>\n    </div>\n  </div>\n\n</div>\n\n<script>\n  const canvas = document.getElementById('particles');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  class Particle {\n    constructor() {\n      this.reset();\n    }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.5;\n      this.speedY = (Math.random() - 0.5) * 0.5;\n      this.opacity = Math.random() * 0.5 + 0.1;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n      if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(9, 132, 227, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 80; i++) particles.push(new Particle());\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 150) {\n          ctx.beginPath();\n          ctx.strokeStyle = `rgba(9, 132, 227, ${0.06 * (1 - dist / 150)})`;\n          ctx.lineWidth = 0.5;\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  const sections = document.querySelectorAll('[data-section]');\n\n  function revealSections() {\n    sections.forEach(section => {\n      const rect = section.getBoundingClientRect();\n      if (rect.top < window.innerHeight - 80) {\n        section.classList.add('visible');\n      }\n    });\n  }\n  window.addEventListener('scroll', revealSections);\n  revealSections();\n\n  const progressBar = document.getElementById('progressBar');\n\n  window.addEventListener('scroll', () => {\n    const scrollTop = window.scrollY;\n    const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n    const progress = (scrollTop / docHeight) * 100;\n    progressBar.style.width = progress + '%';\n  });\n\n  function checkAnswer(btn, isCorrect) {\n    const question = btn.closest('.quiz-question');\n    const options = question.querySelectorAll('.quiz-option');\n    const feedback = question.querySelector('.quiz-feedback');\n\n    options.forEach(opt => {\n      opt.disabled = true;\n      opt.style.cursor = 'not-allowed';\n      if (opt.dataset.correct === 'true') opt.classList.add('correct');\n    });\n\n    if (isCorrect) {\n      btn.classList.add('correct');\n      feedback.textContent = '\\u2705 Correct!';\n      feedback.className = 'quiz-feedback show correct';\n    } else {\n      btn.classList.add('wrong');\n      const correctBtn = question.querySelector('[data-correct=\"true\"]');\n      feedback.textContent = '\\u274C Incorrect. The answer was: ' + correctBtn.textContent;\n      feedback.className = 'quiz-feedback show wrong';\n    }\n  }\n\n  function resetQuiz() {\n    document.querySelectorAll('.quiz-question').forEach(q => {\n      const options = q.querySelectorAll('.quiz-option');\n      const feedback = q.querySelector('.quiz-feedback');\n      options.forEach(opt => {\n        opt.disabled = false;\n        opt.style.cursor = 'pointer';\n        opt.classList.remove('correct', 'wrong');\n      });\n      feedback.className = 'quiz-feedback';\n      feedback.textContent = '';\n    });\n  }\n</script>\n\n\n\n\n</body>\n</html>",
    "4": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"progress-container\">\n  <div class=\"progress-bar\" id=\"progressBar\"></div>\n</div>\n\n<canvas id=\"particles\"></canvas>\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">Lesson 4</div>\n  <h1>Production, Cost &amp;<br>Market Structures</h1>\n  <p>Understanding how firms produce, calculate costs and revenue, and operate in different market environments.</p>\n  <div class=\"hero-scroll\">↓</div>\n</section>\n\n<div class=\"container\">\n\n\n\n  <!-- 1. Production -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏗️</div>\n    <h2>Production <span class=\"underline\"></span></h2>\n    <p>Production is the process of converting inputs into outputs to create goods and services that satisfy human wants.</p>\n\n    <h3>Production Function</h3>\n    <div class=\"formula-box\">\n      Q = f(L, K)\n    </div>\n    <p>Where <span class=\"highlight\">Q</span> = Output, <span class=\"highlight\">L</span> = Labour, <span class=\"highlight\">K</span> = Capital. The function shows the maximum output achievable from given inputs.</p>\n\n    <h3>Short Run vs Long Run</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">⏱ Short Run</div>\n        <ul>\n          <li>At least <strong>one input is fixed</strong></li>\n          <li>Variable inputs + Fixed inputs</li>\n          <li>Firms can change output only by changing variable inputs</li>\n          <li>Law of Diminishing Marginal Returns applies</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">⏰ Long Run</div>\n        <ul>\n          <li><strong>All inputs are variable</strong></li>\n          <li>No fixed inputs</li>\n          <li>Firms can change scale of production</li>\n          <li>Returns to Scale apply</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Total, Average &amp; Marginal Product</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">📊</div>\n        <div class=\"label\">Total Product (TP)</div>\n        <div class=\"desc\">Total output produced by all inputs</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📈</div>\n        <div class=\"label\">Average Product (AP)</div>\n        <div class=\"desc\">AP = TP / L<br>Output per unit of labour</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📉</div>\n        <div class=\"label\">Marginal Product (MP)</div>\n        <div class=\"desc\">MP = ΔTP / ΔL<br>Extra output from one more unit of labour</div>\n      </div>\n    </div>\n\n    <div class=\"formula-box\">\n      AP = TP / L &nbsp;&nbsp;|&nbsp;&nbsp; MP = ΔTP / ΔL\n    </div>\n\n    <h4>📊 Interactive TP/AP/MP Calculator</h4>\n    <p class=\"note\"><small>Enter values for Labour (L) and Total Product (TP). AP and MP are calculated automatically.</small></p>\n    <div class=\"table-wrap\">\n      <table class=\"interactive-table\" id=\"prodTable\">\n        <thead>\n          <tr>\n            <th>Labour (L)</th>\n            <th>Total Product (TP)</th>\n            <th>Average Product (AP)</th>\n            <th>Marginal Product (MP)</th>\n          </tr>\n        </thead>\n        <tbody id=\"prodBody\">\n        </tbody>\n      </table>\n    </div>\n\n    <h3>Law of Diminishing Marginal Returns</h3>\n    <div class=\"info-card\">\n      <div class=\"emoji\">ℹ️</div>\n      <div class=\"label\">Law of Diminishing Marginal Returns</div>\n      <div class=\"desc\">As more units of a variable input are added to a fixed input, beyond some point the marginal product decreases.</div>\n    </div>\n\n    <h3>Returns to Scale</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">↗️</div>\n        <div class=\"label\">Increasing Returns</div>\n        <div class=\"desc\">Output grows more than proportionally to inputs</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">→️</div>\n        <div class=\"label\">Constant Returns</div>\n        <div class=\"desc\">Output grows proportionally to inputs</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">↘️</div>\n        <div class=\"label\">Decreasing Returns</div>\n        <div class=\"desc\">Output grows less than proportionally to inputs</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 2. Cost of Production -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💰</div>\n    <h2>Cost of Production <span class=\"underline\"></span></h2>\n\n    <h3>Opportunity Cost</h3>\n    <div class=\"formula-box\">\n      Opportunity Cost = Direct Cost (Explicit) + Indirect Cost (Implicit)\n    </div>\n\n    <h3>Accounting vs Economic Profit</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">💵 Accounting Profit</div>\n        <ul>\n          <li>TR − Direct Cost (Explicit)</li>\n          <li>What appears in financial statements</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">💰 Economic Profit</div>\n        <ul>\n          <li>TR − (Direct + Indirect Cost)</li>\n          <li>Includes opportunity cost</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"formula-box\">\n      Accounting Profit = TR − Direct Cost &nbsp;&nbsp;|&nbsp;&nbsp; Economic Profit = TR − (Direct + Indirect Cost)\n    </div>\n\n    <h3>Short Run Costs</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">💸</div><div class=\"label\">TFC</div><div class=\"desc\">Total Fixed Cost</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💹</div><div class=\"label\">TVC</div><div class=\"desc\">Total Variable Cost</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💲</div><div class=\"label\">TC</div><div class=\"desc\">Total Cost = TFC + TVC</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📉</div><div class=\"label\">AFC</div><div class=\"desc\">AFC = TFC / Q</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📈</div><div class=\"label\">AVC</div><div class=\"desc\">AVC = TVC / Q</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📊</div><div class=\"label\">ATC</div><div class=\"desc\">ATC = TC / Q</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📇</div><div class=\"label\">MC</div><div class=\"desc\">MC = ΔTC / ΔQ</div></div>\n    </div>\n\n    <div class=\"formula-box\">\n      TC = TFC + TVC &nbsp;&nbsp;|&nbsp;&nbsp; AFC = TFC/Q &nbsp;&nbsp;|&nbsp;&nbsp; AVC = TVC/Q &nbsp;&nbsp;|&nbsp;&nbsp; ATC = TC/Q &nbsp;&nbsp;|&nbsp;&nbsp; MC = ΔTC/ΔQ\n    </div>\n\n    <h4>U-Shaped Cost Curves</h4>\n    <div class=\"diagram-box\">\n      <pre>  Cost\n    |\n    |   MC\n    |  /\\\n    | /  \\   ATC\n    |/    \\ /\\\n    |      \\/  \\    AVC\n    |      /\\   \\\n    |     /  \\   \\\n    |    /    \\   \\\n    |   /      \\   \\\n    |  /        \\   \\______ AFC\n    | /          \\\n    +--------------------- Q\n      </pre>\n    </div>\n    <p style=\"text-align:center;font-size:0.85rem;color:var(--text-muted);\">MC intersects ATC and AVC at their minimum points. AFC declines continuously.</p>\n\n    <h3>Long Run Costs</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">↗️ Economies of Scale</div>\n        <ul>\n          <li>LRAC <strong>falls</strong> as output increases</li>\n          <li>Specialization, bulk buying, technical efficiency</li>\n          <li>Lower average cost</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">↘️ Diseconomies of Scale</div>\n        <ul>\n          <li>LRAC <strong>rises</strong> as output increases</li>\n          <li>Coordination problems, bureaucracy</li>\n          <li>Higher average cost</li>\n        </ul>\n      </div>\n    </div>\n\n    <h4>Long Run Average Cost (LAC) Curve</h4>\n    <div class=\"diagram-box\">\n      <pre>  Cost\n    |\n    |           LAC\n    |    ---------------\n    |   /               \\\n    |  /                 \\\n    | /   Economies of    \\ Diseconomies\n    |/      Scale          \\ of Scale\n    +------------------------ Q\n      </pre>\n    </div>\n  </div>\n\n  <!-- 3. Revenue -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💶</div>\n    <h2>Revenue <span class=\"underline\"></span></h2>\n    <p>Revenue is the income a firm earns from selling its goods or services.</p>\n\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">💵</div>\n        <div class=\"label\">Total Revenue (TR)</div>\n        <div class=\"desc\">TR = P × Q</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📈</div>\n        <div class=\"label\">Average Revenue (AR)</div>\n        <div class=\"desc\">AR = TR / Q = P</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📇</div>\n        <div class=\"label\">Marginal Revenue (MR)</div>\n        <div class=\"desc\">MR = ΔTR / ΔQ</div>\n      </div>\n    </div>\n\n    <div class=\"formula-box\">\n      TR = P × Q &nbsp;&nbsp;|&nbsp;&nbsp; AR = TR / Q &nbsp;&nbsp;|&nbsp;&nbsp; MR = ΔTR / ΔQ\n    </div>\n  </div>\n\n  <!-- 4. Profit -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏆</div>\n    <h2>Profit <span class=\"underline\"></span></h2>\n\n    <div class=\"formula-box\">\n      Profit = TR − TC\n    </div>\n\n    <h3>Optimum Output</h3>\n    <p>Profit is maximized where <span class=\"highlight\">MC = MR</span> (with MC rising).</p>\n\n    <h3>Types of Profit</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">🟩</div>\n        <div class=\"label\">Super Normal Profit</div>\n        <div class=\"desc\">AC &lt; AR ⇒ P &gt; Cost</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🟨</div>\n        <div class=\"label\">Normal Profit</div>\n        <div class=\"desc\">AC = AR ⇒ P = Cost</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🔴</div>\n        <div class=\"label\">Sub Normal Profit (Loss)</div>\n        <div class=\"desc\">AC &gt; AR ⇒ P &lt; Cost</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">⛔</div>\n        <div class=\"label\">Shutdown Condition</div>\n        <div class=\"desc\">AVC = AR ⇒ Close if AR &lt; AVC</div>\n      </div>\n    </div>\n\n    <h3>Profit Conditions Summary</h3>\n    <div class=\"diagram-box\">\n      <pre>  Condition              Result\n  --------------------------------\n  AC &lt; AR (P &gt; ATC)    Super Normal Profit  ✅\n  AC = AR (P = ATC)     Normal Profit        🔄\n  AC &gt; AR (P &lt; ATC)    Sub Normal Profit     ❌\n  AVC = AR (P = AVC)    Shutdown Point       ⛔\n  AR &lt; AVC              Shutdown             🚫\n      </pre>\n    </div>\n  </div>\n\n  <!-- 5. Market Structures -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏛️</div>\n    <h2>Market Structures <span class=\"underline\"></span></h2>\n    <p>Market structure describes the competitive environment in which firms operate.</p>\n\n    <div class=\"flashcard-container\">\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🌍 Perfect Competition\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Many firms, homogeneous product<br>\n            Price taker, free entry/exit<br>\n            <small>No barriers • Perfect info</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🔒 Monopoly\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            One firm, unique product<br>\n            High barriers to entry<br>\n            <small>Price maker • No close substitutes</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🧠 Monopolistic Competition\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Many firms, differentiated products<br>\n            Free entry/exit<br>\n            <small>Non-price competition</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🤝 Oligopoly\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Few firms, mutual interdependence<br>\n            High barriers to entry<br>\n            <small>Collusion possible • Game theory</small>\n          </div>\n        </div>\n      </div>\n    </div>\n\n    <h3>Perfect Competition vs Monopoly</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🌍 Perfect Competition</div>\n        <ul>\n          <li>Many firms (large number)</li>\n          <li>Homogeneous (identical) products</li>\n          <li><strong>Price taker</strong></li>\n          <li>Free entry and exit</li>\n          <li>Zero economic profit in LR</li>\n          <li>P = MC = MR (allocative efficiency)</li>\n          <li>No advertising needed</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🔒 Monopoly</div>\n        <ul>\n          <li>Single firm</li>\n          <li>Unique product (no close substitutes)</li>\n          <li><strong>Price maker</strong></li>\n          <li>Blocked entry (barriers)</li>\n          <li>Can earn super normal profit in LR</li>\n          <li>P &gt; MC (inefficiency)</li>\n          <li>Can advertise to maintain demand</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Short Run vs Long Run in Perfect Competition</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">⏱ Short Run</div>\n        <ul>\n          <li>Fixed number of firms</li>\n          <li>Can earn super normal profit</li>\n          <li>Can earn sub normal profit (loss)</li>\n          <li>Firms cannot exit/enter</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">⏰ Long Run</div>\n        <ul>\n          <li>Firms can enter and exit</li>\n          <li>Super normal profit attracts new firms</li>\n          <li>Losses force firms to exit</li>\n          <li>Equilibrium: Normal Profit (P = ATC)</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>All Market Structures Comparison</h3>\n    <div class=\"diagram-box\">\n      <pre>  Feature           | PC    | Monop | Mono C | Oligo\n  ------------------+-------+-------+--------+-------\n  # of Firms        | Many  | One   | Many   | Few\n  Product Type      | Homo  | Unique| Diff   | Homo/Diff\n  Price Control     | Taker | Maker | Some   | Interdep.\n  Entry Barriers    | None  | High  | None   | High\n  LR Profit         | Zero  | SuperN| Zero   | SuperN\n  Non-price Comp.   | None  | Some  | High   | High\n      </pre>\n    </div>\n  </div>\n\n  <!-- Interactive Quiz -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧰</div>\n    <h2>Test Your Knowledge <span class=\"underline\"></span></h2>\n\n    <div class=\"quiz-question\" data-q=\"1\">\n      <div class=\"q\">1. In the short run, which of the following is true?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">All inputs are variable</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">At least one input is fixed</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">There are no fixed inputs</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Returns to scale apply</button>\n      <div class=\"quiz-feedback\" data-feedback=\"1\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"2\">\n      <div class=\"q\">2. The formula for Average Product (AP) is:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">AP = ΔTP / ΔL</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">AP = TP / L</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">AP = TP × L</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">AP = L / TP</button>\n      <div class=\"quiz-feedback\" data-feedback=\"2\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"3\">\n      <div class=\"q\">3. Economic profit equals:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">TR − Direct Cost</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">TR − Indirect Cost</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">TR − (Direct + Indirect Cost)</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">TR − Fixed Cost</button>\n      <div class=\"quiz-feedback\" data-feedback=\"3\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"4\">\n      <div class=\"q\">4. Profit is maximized where:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">MC = ATC</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">AR = ATC</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">MC = MR (with MC rising)</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">TR = TC</button>\n      <div class=\"quiz-feedback\" data-feedback=\"4\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"5\">\n      <div class=\"q\">5. In perfect competition, firms are:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Price makers</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Price takers</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Price setters</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Price discriminators</button>\n      <div class=\"quiz-feedback\" data-feedback=\"5\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"6\">\n      <div class=\"q\">6. Which market structure has one firm with a unique product?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Perfect Competition</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Monopoly</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Monopolistic Competition</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Oligopoly</button>\n      <div class=\"quiz-feedback\" data-feedback=\"6\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"7\">\n      <div class=\"q\">7. The shutdown condition occurs when:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">AR &lt; AFC</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">TR &lt; TFC</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">AVC = AR</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">ATC = AFC</button>\n      <div class=\"quiz-feedback\" data-feedback=\"7\"></div>\n    </div>\n  </div>\n\n</div>\n\n<script>\n  // Particles\n  const canvas = document.getElementById('particles');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  class Particle {\n    constructor() {\n      this.reset();\n    }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.5;\n      this.speedY = (Math.random() - 0.5) * 0.5;\n      this.opacity = Math.random() * 0.5 + 0.1;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n      if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(9, 132, 227, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 80; i++) particles.push(new Particle());\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 150) {\n          ctx.beginPath();\n          ctx.strokeStyle = `rgba(9, 132, 227, ${0.06 * (1 - dist / 150)})`;\n          ctx.lineWidth = 0.5;\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  // Scroll reveal\n  const sections = document.querySelectorAll('[data-section]');\n\n  function revealSections() {\n    sections.forEach(section => {\n      const rect = section.getBoundingClientRect();\n      if (rect.top < window.innerHeight - 80) {\n        section.classList.add('visible');\n      }\n    });\n  }\n  window.addEventListener('scroll', revealSections);\n  revealSections();\n\n  // Progress bar\n  const progressBar = document.getElementById('progressBar');\n\n  window.addEventListener('scroll', () => {\n    const scrollTop = window.scrollY;\n    const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n    const progress = (scrollTop / docHeight) * 100;\n    progressBar.style.width = progress + '%';\n  });\n\n  // Quiz\n  function checkAnswer(btn, isCorrect) {\n    const question = btn.closest('.quiz-question');\n    const options = question.querySelectorAll('.quiz-option');\n    const feedback = question.querySelector('.quiz-feedback');\n\n    options.forEach(opt => {\n      opt.disabled = true;\n      opt.style.cursor = 'not-allowed';\n      if (opt.dataset.correct === 'true') opt.classList.add('correct');\n    });\n\n    if (isCorrect) {\n      btn.classList.add('correct');\n      feedback.textContent = '\\u2705 Correct!';\n      feedback.className = 'quiz-feedback show correct';\n    } else {\n      btn.classList.add('wrong');\n      const correctBtn = question.querySelector('[data-correct=\"true\"]');\n      feedback.textContent = '\\u274C Incorrect. The answer was: ' + correctBtn.textContent;\n      feedback.className = 'quiz-feedback show wrong';\n    }\n  }\n\n  // Interactive TP/AP/MP Table\n  function buildProdTable() {\n    const tbody = document.getElementById('prodBody');\n    const defaultTP = [0, 10, 25, 45, 60, 70, 75, 72];\n    for (let i = 0; i < 8; i++) {\n      const tr = document.createElement('tr');\n      const tdL = document.createElement('td');\n      tdL.textContent = i;\n      const tdTP = document.createElement('td');\n      const input = document.createElement('input');\n      input.type = 'number';\n      input.value = defaultTP[i];\n      input.dataset.row = i;\n      input.addEventListener('input', recalcProdTable);\n      tdTP.appendChild(input);\n      const tdAP = document.createElement('td');\n      tdAP.className = 'auto';\n      tdAP.id = 'ap-' + i;\n      const tdMP = document.createElement('td');\n      tdMP.className = 'auto';\n      tdMP.id = 'mp-' + i;\n      tr.appendChild(tdL);\n      tr.appendChild(tdTP);\n      tr.appendChild(tdAP);\n      tr.appendChild(tdMP);\n      tbody.appendChild(tr);\n    }\n    recalcProdTable();\n  }\n\n  function recalcProdTable() {\n    const inputs = document.querySelectorAll('#prodBody input');\n    const values = [];\n    inputs.forEach(inp => values.push(parseFloat(inp.value) || 0));\n    for (let i = 0; i < values.length; i++) {\n      const apEl = document.getElementById('ap-' + i);\n      const mpEl = document.getElementById('mp-' + i);\n      if (i === 0) {\n        apEl.textContent = '-';\n        mpEl.textContent = '-';\n      } else {\n        const ap = (values[i] / i).toFixed(2);\n        apEl.textContent = ap;\n        const mp = (values[i] - values[i - 1]).toFixed(2);\n        mpEl.textContent = mp;\n      }\n    }\n  }\n\n  buildProdTable();\n</script>\n\n\n\n\n</body>\n</html>",
    "5": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"progress-container\">\n  <div class=\"progress-bar\" id=\"progressBar\"></div>\n</div>\n\n<canvas id=\"particles\"></canvas>\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">Lesson 5</div>\n  <h1>National<br>Accounting</h1>\n  <p>Measuring the economic performance of a nation through GDP, GNP, and national income aggregates.</p>\n  <div class=\"hero-scroll\">↓</div>\n</section>\n\n<div class=\"container\">\n\n\n\n  <!-- 1. Production Boundary -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏴</div>\n    <h2>Production Boundary <span class=\"underline\"></span></h2>\n    <p>The production boundary defines which economic activities are included in national income measurement.</p>\n\n    <h3>✅ Included in National Income</h3>\n    <ul>\n      <li>Market goods and services</li>\n      <li>Goods produced for own final consumption</li>\n      <li>Owner-occupied housing (imputed rent)</li>\n      <li>Paid domestic staff services</li>\n      <li>Agricultural crops grown for own consumption</li>\n    </ul>\n\n    <h3>❌ Excluded from National Income</h3>\n    <ul>\n      <li>Unpaid household work (e.g. cooking, cleaning by family members)</li>\n      <li>Child care (unpaid)</li>\n      <li>Natural resources without human intervention (e.g. wild forests, mineral deposits not yet extracted)</li>\n      <li>Leisure activities</li>\n    </ul>\n\n    <div class=\"info-card\" style=\"margin-top: 1rem;\">\n      <div class=\"emoji\">📝</div>\n      <div class=\"label\">Key Principle</div>\n      <div class=\"desc\">Only economic activities that involve a <strong>monetary transaction</strong> or <strong>imputed value</strong> are included within the production boundary.</div>\n    </div>\n  </div>\n\n  <!-- 2. Non-Observed Economic Activities -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🔍</div>\n    <h2>Non-Observed Economic Activities <span class=\"underline\"></span></h2>\n    <p>Activities that are not captured in official statistics but still involve production of goods and services.</p>\n\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🕵️ Hidden Economy</div>\n        <ul>\n          <li>Legal economic activities</li>\n          <li>Concealed from authorities to avoid:</li>\n          <li style=\"padding-left: 1rem;\">• Tax payments</li>\n          <li style=\"padding-left: 1rem;\">• Regulatory compliance</li>\n          <li style=\"padding-left: 1rem;\">• Social security contributions</li>\n          <li>Also called the <strong>underground</strong> or <strong>shadow</strong> economy</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🚫 Illegal Activities</div>\n        <ul>\n          <li>Activities forbidden by law</li>\n          <li>Or unauthorized production</li>\n          <li style=\"padding-left: 1rem;\">• Drug trafficking</li>\n          <li style=\"padding-left: 1rem;\">• Human trafficking</li>\n          <li style=\"padding-left: 1rem;\">• Illegal gambling</li>\n          <li style=\"padding-left: 1rem;\">• Production without license</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 3. Three Approaches to GDP -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📊</div>\n    <h2>Three Approaches to GDP <span class=\"underline\"></span></h2>\n    <p>GDP can be measured in three different ways, all of which yield the same result in equilibrium.</p>\n\n    <div class=\"comparison three-col\">\n      <div class=\"left\">\n        <div class=\"header\">🏭 Product Approach</div>\n        <ul>\n          <li>Value added in Agriculture</li>\n          <li>+ Value added in Industry</li>\n          <li>+ Value added in Services</li>\n          <li>+ Net taxes on products</li>\n          <li><strong>= GDP at market prices</strong></li>\n        </ul>\n      </div>\n      <div class=\"mid\">\n        <div class=\"header\">💵 Income Approach</div>\n        <ul>\n          <li>Compensation of employees</li>\n          <li>+ Gross operational surplus</li>\n          <li>+ Mixed income</li>\n          <li>+ Other net taxes on production</li>\n          <li><strong>= GDP at market prices</strong></li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">💲 Expenditure Approach</div>\n        <ul>\n          <li>Consumption (C)</li>\n          <li>+ Investment (I)</li>\n          <li>+ Government spending (G)</li>\n          <li>+ Net Exports (X − M)</li>\n          <li><strong>= GDP at market prices</strong></li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"formula-box\">\n      <span class=\"label\">Expenditure Approach</span>\n      GDP = C + I + G + (X − M)\n    </div>\n\n    <div class=\"formula-box\">\n      <span class=\"label\">Product Approach</span>\n      GDP = Σ Value Added + Net Taxes\n    </div>\n\n    <div class=\"formula-box\">\n      <span class=\"label\">Income Approach</span>\n      GDP = Employee Compensation + Operating Surplus + Mixed Income + Net Taxes\n    </div>\n  </div>\n\n  <!-- 4. Interactive GDP Calculator -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💱</div>\n    <h2>GDP Calculator <span class=\"underline\"></span></h2>\n    <p>Enter values to compute GDP using all three approaches. Try it out!</p>\n\n    <div class=\"calc-grid\">\n      <div class=\"calc-panel\">\n        <h4>💲 Expenditure Approach</h4>\n        <div class=\"calc-row\">\n          <label>Consumption (C)</label>\n          <input type=\"number\" id=\"calcC\" value=\"500\" step=\"10\" oninput=\"computeGDP()\">\n        </div>\n        <div class=\"calc-row\">\n          <label>Investment (I)</label>\n          <input type=\"number\" id=\"calcI\" value=\"200\" step=\"10\" oninput=\"computeGDP()\">\n        </div>\n        <div class=\"calc-row\">\n          <label>Government (G)</label>\n          <input type=\"number\" id=\"calcG\" value=\"150\" step=\"10\" oninput=\"computeGDP()\">\n        </div>\n        <div class=\"calc-row\">\n          <label>Exports (X)</label>\n          <input type=\"number\" id=\"calcX\" value=\"120\" step=\"10\" oninput=\"computeGDP()\">\n        </div>\n        <div class=\"calc-row\">\n          <label>Imports (M)</label>\n          <input type=\"number\" id=\"calcM\" value=\"80\" step=\"10\" oninput=\"computeGDP()\">\n        </div>\n        <div class=\"calc-total\">\n          <span>GDP (Expenditure)</span>\n          <span class=\"val\" id=\"gdpExp\">890</span>\n        </div>\n      </div>\n\n      <div class=\"calc-panel\">\n        <h4>🏭 Product Approach</h4>\n        <div class=\"calc-row\">\n          <label>Agriculture VA</label>\n          <input type=\"number\" id=\"calcAgri\" value=\"150\" step=\"10\" oninput=\"computeGDP()\">\n        </div>\n        <div class=\"calc-row\">\n          <label>Industry VA</label>\n          <input type=\"number\" id=\"calcInd\" value=\"300\" step=\"10\" oninput=\"computeGDP()\">\n        </div>\n        <div class=\"calc-row\">\n          <label>Services VA</label>\n          <input type=\"number\" id=\"calcServ\" value=\"400\" step=\"10\" oninput=\"computeGDP()\">\n        </div>\n        <div class=\"calc-row\">\n          <label>Net Taxes</label>\n          <input type=\"number\" id=\"calcTax\" value=\"40\" step=\"10\" oninput=\"computeGDP()\">\n        </div>\n        <div class=\"calc-total\">\n          <span>GDP (Product)</span>\n          <span class=\"val\" id=\"gdpProd\">890</span>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"calc-panel\" style=\"margin-top: 1rem;\">\n      <h4>💵 Income Approach</h4>\n      <div class=\"calc-row\">\n        <label>Compensation of Employees</label>\n        <input type=\"number\" id=\"calcComp\" value=\"400\" step=\"10\" oninput=\"computeGDP()\">\n      </div>\n      <div class=\"calc-row\">\n        <label>Gross Operating Surplus</label>\n        <input type=\"number\" id=\"calcSurplus\" value=\"300\" step=\"10\" oninput=\"computeGDP()\">\n      </div>\n      <div class=\"calc-row\">\n        <label>Mixed Income</label>\n        <input type=\"number\" id=\"calcMixed\" value=\"100\" step=\"10\" oninput=\"computeGDP()\">\n      </div>\n      <div class=\"calc-row\">\n        <label>Other Net Taxes</label>\n        <input type=\"number\" id=\"calcNetTax\" value=\"90\" step=\"10\" oninput=\"computeGDP()\">\n      </div>\n      <div class=\"calc-total\">\n        <span>GDP (Income)</span>\n        <span class=\"val\" id=\"gdpInc\">890</span>\n      </div>\n    </div>\n\n    <div style=\"display: flex; justify-content: center; gap: 0.5rem; flex-wrap: wrap;\">\n      <button class=\"calc-btn\" onclick=\"setExample1()\">Load Example 1</button>\n      <button class=\"calc-btn\" onclick=\"setExample2()\">Load Example 2</button>\n      <button class=\"calc-btn secondary\" onclick=\"resetCalculator()\">Reset</button>\n    </div>\n\n    <div class=\"info-card\" style=\"margin-top: 1rem;\">\n      <div class=\"emoji\">✅</div>\n      <div class=\"label\" id=\"calcStatus\">All three approaches match!</div>\n      <div class=\"desc\" id=\"calcMatch\">GDP = 890 across all three approaches</div>\n    </div>\n  </div>\n\n  <!-- 5. GDP vs GNP -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🌐</div>\n    <h2>GDP vs GNP <span class=\"underline\"></span></h2>\n\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🏴 GDP</div>\n        <ul>\n          <li><strong>Gross Domestic Product</strong></li>\n          <li>Total value of goods &amp; services produced <strong>within</strong> a country's borders</li>\n          <li>Includes output by foreign-owned firms operating domestically</li>\n          <li>Excludes output by domestic firms operating abroad</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🌍 GNP</div>\n        <ul>\n          <li><strong>Gross National Product</strong></li>\n          <li>Total value of goods &amp; services produced by <strong>citizens/residents</strong> of a country</li>\n          <li>Includes output by domestic firms operating abroad</li>\n          <li>Excludes output by foreign-owned firms domestically</li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"formula-box\">\n      <span class=\"label\">Relationship</span>\n      GNP = GDP + Net primary income from rest of the world\n    </div>\n\n    <div class=\"formula-box\">\n      <span class=\"label\">Net Primary Income</span>\n      Net Primary Income = Income earned by residents abroad − Income earned by non-residents domestically\n    </div>\n  </div>\n\n  <!-- 6. Gross vs Net -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">➖</div>\n    <h2>Gross vs Net <span class=\"underline\"></span></h2>\n\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">➕ Gross</div>\n        <ul>\n          <li>Includes depreciation (fixed capital consumption)</li>\n          <li>GDP = Gross Domestic Product</li>\n          <li>Gross Investment includes replacement capital</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">➖ Net</div>\n        <ul>\n          <li>Excludes depreciation</li>\n          <li>NDP = Net Domestic Product</li>\n          <li>NDP = GDP − Fixed Capital Consumption</li>\n          <li>Net Investment = Gross Investment − Depreciation</li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"formula-box\">\n      <span class=\"label\">Net Domestic Product</span>\n      NDP = GDP − Fixed Capital Consumption (Depreciation)\n    </div>\n  </div>\n\n  <!-- 7. Prices and National Income -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📈</div>\n    <h2>Price Concepts &amp; National Income <span class=\"underline\"></span></h2>\n\n    <h3>Three Price Levels</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">🔢</div>\n        <div class=\"label\">Basic Price</div>\n        <div class=\"desc\">Amount received by producer − net taxes on products</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">💰</div>\n        <div class=\"label\">Producers' Price</div>\n        <div class=\"desc\">Basic price + net taxes on products (excluding trade/transport margins)</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🛒</div>\n        <div class=\"label\">Purchasers' Price</div>\n        <div class=\"desc\">Producers' price + trade &amp; transport margins (the final price paid)</div>\n      </div>\n    </div>\n\n    <h3>National Income Aggregates</h3>\n    <div class=\"timeline\">\n      <div class=\"timeline-item\">\n        <div class=\"title\">GDP = Gross Domestic Product</div>\n        <div class=\"desc\">Total output within borders</div>\n      </div>\n      <div class=\"timeline-item\">\n        <div class=\"title\">GNI = GDP + Net Primary Income from ROW</div>\n        <div class=\"desc\">Gross National Income</div>\n      </div>\n      <div class=\"timeline-item\">\n        <div class=\"title\">NNI = GNI − Fixed Capital Consumption</div>\n        <div class=\"desc\">Net National Income</div>\n      </div>\n    </div>\n\n    <div class=\"formula-box\">\n      <span class=\"label\">Gross National Income</span>\n      GNI = GDP + Net Primary Income from Rest of World\n    </div>\n\n    <div class=\"formula-box\">\n      <span class=\"label\">Net National Income</span>\n      NNI = GNI − Fixed Capital Consumption\n    </div>\n  </div>\n\n  <!-- 8. Factor Incomes -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧑‍💼</div>\n    <h2>Factor Incomes <span class=\"underline\"></span></h2>\n    <p>Factor incomes represent the earnings by factors of production in the economy.</p>\n\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">🧑‍🏫</div>\n        <div class=\"label\">Compensation of Employees</div>\n        <div class=\"desc\">Wages, salaries, bonuses, and employer social contributions</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🏠</div>\n        <div class=\"label\">Rental Income</div>\n        <div class=\"desc\">Income from land and property (actual &amp; imputed)</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">💵</div>\n        <div class=\"label\">Net Interest Income</div>\n        <div class=\"desc\">Interest earned − interest paid on capital</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🏦</div>\n        <div class=\"label\">Corporate Profits</div>\n        <div class=\"desc\">Profits after tax, dividends, retained earnings</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🧩</div>\n        <div class=\"label\">Self-Employment / Mixed Income</div>\n        <div class=\"desc\">Income of unincorporated enterprises (cannot separate labour from capital)</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 9. Value Added Approach -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📊</div>\n    <h2>Final Product vs Value Added <span class=\"underline\"></span></h2>\n    <p>The value added approach avoids double counting by summing only the additional value created at each stage of production.</p>\n\n    <div class=\"diagram-box\">\n      <pre>Stage 1: Farmer grows wheat       Value Added = $100\n                     |\nStage 2: Miller grinds flour      Value Added = $50\n                     |\nStage 3: Baker bakes bread        Value Added = $50\n                     |\nStage 4: Retailer sells bread     Value Added = $30\n                     |\n            Total Value Added = $230  (GDP contribution)\n      (vs. Final Price = $230 — same result!)\n      </pre>\n    </div>\n\n    <div class=\"info-card\">\n      <div class=\"emoji\">⚠️</div>\n      <div class=\"label\">Why Value Added?</div>\n      <div class=\"desc\">If we summed all sales (100+150+200+230 = $680), we would overcount — double counting the value of intermediate goods. Value added avoids this.</div>\n    </div>\n  </div>\n\n  <!-- 10. Flashcards -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💡</div>\n    <h2>Key Terms Flashcards <span class=\"underline\"></span></h2>\n    <p>Click each card to reveal the definition.</p>\n\n    <div class=\"flashcard-container\">\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            GDP\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Gross Domestic Product<br>\n            <small>Total value of final goods and services produced within a country's borders in a given period</small>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            GNP\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Gross National Product<br>\n            <small>Total value of final goods and services produced by citizens/residents of a country</small>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            GNI\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Gross National Income<br>\n            <small>GDP + Net primary income from rest of the world</small>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            Value Added\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            The additional value created at each stage of production<br>\n            <small>Value of output − value of intermediate inputs</small>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            Depreciation\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Fixed Capital Consumption<br>\n            <small>The wearing out / loss of value of fixed assets over time</small>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            Production Boundary\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            The line between economic activities included in GDP and those excluded<br>\n            <small>Includes market production, excludes unpaid household work</small>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            Net Exports\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Exports − Imports (X − M)<br>\n            <small>A component of the expenditure approach to GDP</small>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            Mixed Income\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Income of self-employed / unincorporated enterprises<br>\n            <small>Cannot be separated into labour and capital components</small>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 11. Importance & Limitations -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚖️</div>\n    <h2>Importance &amp; Limitations of National Accounting <span class=\"underline\"></span></h2>\n\n    <h3>⭐ Importance / Uses</h3>\n    <ul>\n      <li>Assess the overall performance of the economy</li>\n      <li>Measure economic growth over time (real GDP)</li>\n      <li>Compute per capita GDP for standard of living comparisons</li>\n      <li>International comparisons of economic output</li>\n      <li>Basis for government policy formulation (fiscal &amp; monetary)</li>\n      <li>Input for business investment decisions</li>\n    </ul>\n\n    <h3>⚠️ Limitations / Criticisms</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">🧑‍🏭</div>\n        <div class=\"label\">Unpaid Household Work</div>\n        <div class=\"desc\">Excluded from GDP despite having economic value</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🕵️</div>\n        <div class=\"label\">Informal / Shadow Economy</div>\n        <div class=\"desc\">Hidden and illegal activities not captured</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🏞️</div>\n        <div class=\"label\">Environmental Effects</div>\n        <div class=\"desc\">GDP ignores resource depletion and pollution</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🎶</div>\n        <div class=\"label\">Leisure</div>\n        <div class=\"desc\">Reduction in leisure time is not accounted for</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 12. Interactive Quiz -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧰</div>\n    <h2>Test Your Knowledge <span class=\"underline\"></span></h2>\n\n    <div class=\"quiz-question\" data-q=\"1\">\n      <div class=\"q\">1. Which of the following is included in GDP calculation?</div>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Owner-occupied housing services</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Unpaid household work</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Leisure activities</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Natural resources without human intervention</button>\n      <div class=\"quiz-feedback\" data-feedback=\"1\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"2\">\n      <div class=\"q\">2. What does the expenditure approach to GDP measure?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Sum of all factor incomes</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Sum of value added across all sectors</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">C + I + G + (X − M)</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Total exports only</button>\n      <div class=\"quiz-feedback\" data-feedback=\"2\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"3\">\n      <div class=\"q\">3. GNP is equal to:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">GDP − Depreciation</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">GDP + Net primary income from rest of the world</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">GDP − Net primary income from rest of the world</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">GDP + Depreciation</button>\n      <div class=\"quiz-feedback\" data-feedback=\"3\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"4\">\n      <div class=\"q\">4. Net National Income (NNI) equals:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">GDP − Depreciation</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">GNP + Depreciation</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">GNI − Fixed Capital Consumption</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">GDP + Net primary income</button>\n      <div class=\"quiz-feedback\" data-feedback=\"4\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"5\">\n      <div class=\"q\">5. Which approach to GDP avoids double counting?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Expenditure approach</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Income approach</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Value added approach</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Final product approach alone</button>\n      <div class=\"quiz-feedback\" data-feedback=\"5\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"6\">\n      <div class=\"q\">6. Which of the following is NOT a factor income?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Compensation of employees</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Rental income</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Corporate profits</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Net exports</button>\n      <div class=\"quiz-feedback\" data-feedback=\"6\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"7\">\n      <div class=\"q\">7. The hidden economy refers to:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Illegal drug trafficking</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Legal activities concealed to avoid tax/regulation</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Unpaid household work</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Government services</button>\n      <div class=\"quiz-feedback\" data-feedback=\"7\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"8\">\n      <div class=\"q\">8. Which price includes trade and transport margins?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Basic price</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Producers' price</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Purchasers' price</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Factor cost</button>\n      <div class=\"quiz-feedback\" data-feedback=\"8\"></div>\n    </div>\n  </div>\n\n</div>\n\n<script>\n  const canvas = document.getElementById('particles');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  class Particle {\n    constructor() { this.reset(); }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.5;\n      this.speedY = (Math.random() - 0.5) * 0.5;\n      this.opacity = Math.random() * 0.5 + 0.1;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n      if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(9, 132, 227, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 80; i++) particles.push(new Particle());\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 150) {\n          ctx.beginPath();\n          ctx.strokeStyle = `rgba(9, 132, 227, ${0.06 * (1 - dist / 150)})`;\n          ctx.lineWidth = 0.5;\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  const sections = document.querySelectorAll('[data-section]');\n\n  function revealSections() {\n    sections.forEach(section => {\n      const rect = section.getBoundingClientRect();\n      if (rect.top < window.innerHeight - 80) {\n        section.classList.add('visible');\n      }\n    });\n  }\n  window.addEventListener('scroll', revealSections);\n  revealSections();\n\n  const progressBar = document.getElementById('progressBar');\n  window.addEventListener('scroll', () => {\n    const scrollTop = window.scrollY;\n    const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n    progressBar.style.width = (scrollTop / docHeight) * 100 + '%';\n  });\n\n  function checkAnswer(btn, isCorrect) {\n    const question = btn.closest('.quiz-question');\n    const options = question.querySelectorAll('.quiz-option');\n    const feedback = question.querySelector('.quiz-feedback');\n    options.forEach(opt => {\n      opt.disabled = true;\n      opt.style.cursor = 'not-allowed';\n      if (opt.dataset.correct === 'true') opt.classList.add('correct');\n    });\n    if (isCorrect) {\n      btn.classList.add('correct');\n      feedback.textContent = '\\u2705 Correct!';\n      feedback.className = 'quiz-feedback show correct';\n    } else {\n      btn.classList.add('wrong');\n      const correctBtn = question.querySelector('[data-correct=\"true\"]');\n      feedback.textContent = '\\u274C Incorrect. The answer was: ' + correctBtn.textContent;\n      feedback.className = 'quiz-feedback show wrong';\n    }\n  }\n\n  function readVal(id) {\n    return parseFloat(document.getElementById(id).value) || 0;\n  }\n\n  function computeGDP() {\n    const C = readVal('calcC');\n    const I = readVal('calcI');\n    const G = readVal('calcG');\n    const X = readVal('calcX');\n    const M = readVal('calcM');\n    const gdpExp = C + I + G + (X - M);\n    document.getElementById('gdpExp').textContent = gdpExp.toFixed(0);\n\n    const agri = readVal('calcAgri');\n    const ind = readVal('calcInd');\n    const serv = readVal('calcServ');\n    const tax = readVal('calcTax');\n    const gdpProd = agri + ind + serv + tax;\n    document.getElementById('gdpProd').textContent = gdpProd.toFixed(0);\n\n    const comp = readVal('calcComp');\n    const surplus = readVal('calcSurplus');\n    const mixed = readVal('calcMixed');\n    const netTax = readVal('calcNetTax');\n    const gdpInc = comp + surplus + mixed + netTax;\n    document.getElementById('gdpInc').textContent = gdpInc.toFixed(0);\n\n    const status = document.getElementById('calcStatus');\n    const match = document.getElementById('calcMatch');\n    if (Math.abs(gdpExp - gdpProd) < 0.01 && Math.abs(gdpExp - gdpInc) < 0.01) {\n      status.textContent = '\\u2705 All three approaches match!';\n      status.style.color = 'var(--accent2)';\n      match.textContent = 'GDP = ' + gdpExp.toFixed(0) + ' across all three approaches';\n    } else {\n      status.textContent = '\\u26A0\\uFE0F Values differ between approaches';\n      status.style.color = 'var(--accent3)';\n      match.textContent = 'Expenditure: ' + gdpExp.toFixed(0) + ' | Product: ' + gdpProd.toFixed(0) + ' | Income: ' + gdpInc.toFixed(0);\n    }\n  }\n\n  function setExample1() {\n    document.getElementById('calcC').value = 500;\n    document.getElementById('calcI').value = 200;\n    document.getElementById('calcG').value = 150;\n    document.getElementById('calcX').value = 120;\n    document.getElementById('calcM').value = 80;\n    document.getElementById('calcAgri').value = 150;\n    document.getElementById('calcInd').value = 300;\n    document.getElementById('calcServ').value = 400;\n    document.getElementById('calcTax').value = 40;\n    document.getElementById('calcComp').value = 400;\n    document.getElementById('calcSurplus').value = 300;\n    document.getElementById('calcMixed').value = 100;\n    document.getElementById('calcNetTax').value = 90;\n    computeGDP();\n  }\n\n  function setExample2() {\n    document.getElementById('calcC').value = 800;\n    document.getElementById('calcI').value = 350;\n    document.getElementById('calcG').value = 250;\n    document.getElementById('calcX').value = 200;\n    document.getElementById('calcM').value = 150;\n    document.getElementById('calcAgri').value = 180;\n    document.getElementById('calcInd').value = 500;\n    document.getElementById('calcServ').value = 620;\n    document.getElementById('calcTax').value = 50;\n    document.getElementById('calcComp').value = 650;\n    document.getElementById('calcSurplus').value = 450;\n    document.getElementById('calcMixed').value = 170;\n    document.getElementById('calcNetTax').value = 80;\n    computeGDP();\n  }\n\n  function resetCalculator() {\n    const inputs = document.querySelectorAll('.calc-panel input');\n    inputs.forEach(inp => inp.value = 0);\n    computeGDP();\n  }\n\n  computeGDP();\n</script>\n\n\n\n\n</body>\n</html>",
    "6": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"progress-container\">\n  <div class=\"progress-bar\" id=\"progressBar\"></div>\n</div>\n\n<canvas id=\"particles\"></canvas>\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">Lesson 6</div>\n  <h1>Macroeconomic<br>Concepts</h1>\n  <p>Aggregate variables, business cycles, equilibrium, and the multiplier effect in macroeconomics.</p>\n  <div class=\"hero-scroll\">↓</div>\n</section>\n\n<div class=\"container\">\n\n\n\n  <!-- 1. Macroeconomic Variables & Objectives -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📊</div>\n    <h2>Macroeconomic Variables &amp; Objectives <span class=\"underline\"></span></h2>\n    <p>Macroeconomics studies the economy as a whole through aggregate variables and aims to achieve key national objectives.</p>\n\n    <h3>📈 Key Macroeconomic Variables</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">💵</div><div class=\"label\">Aggregate Output</div><div class=\"desc\">Total value of all goods &amp; services produced</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤝</div><div class=\"label\">Employment</div><div class=\"desc\">Number of people employed in the economy</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💴</div><div class=\"label\">General Price Level</div><div class=\"desc\">Average level of prices across the economy</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌍</div><div class=\"label\">Exchange Rate</div><div class=\"desc\">Value of domestic currency in foreign currency</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📉</div><div class=\"label\">Interest Rate</div><div class=\"desc\">Cost of borrowing &amp; return on savings</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">⚖️</div><div class=\"label\">Balance of Payments</div><div class=\"desc\">Record of all international transactions</div></div>\n    </div>\n\n    <h3>🎯 Macroeconomic Objectives</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">💼</div><div class=\"label\">Full Employment</div><div class=\"desc\">All willing &amp; able individuals have jobs</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">⚖️</div><div class=\"label\">Economic Stability</div><div class=\"desc\">Stable prices &amp; steady growth</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤝</div><div class=\"label\">Equity</div><div class=\"desc\">Fair distribution of income &amp; wealth</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📈</div><div class=\"label\">Economic Growth</div><div class=\"desc\">Increase in national output over time</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">♻️</div><div class=\"label\">Sustainable Development</div><div class=\"desc\">Growth that meets present needs without compromising future</div></div>\n    </div>\n\n    <h3>⚠️ Macroeconomic Problems &amp; Policies</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">💥 Problems</div>\n        <ul>\n          <li>📉 <strong>Recessions</strong> — decline in economic activity</li>\n          <li>🧑‍🍻 <strong>Unemployment</strong> — people without work</li>\n          <li>💰 <strong>Inflation</strong> — sustained rise in price level</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🔧 Policies</div>\n        <ul>\n          <li>💵 <strong>Monetary</strong> — money supply &amp; interest rates</li>\n          <li>💰 <strong>Fiscal</strong> — government spending &amp; taxes</li>\n          <li>🏭 <strong>Supply-side</strong> — boosting productivity</li>\n          <li>💴 <strong>Income</strong> — wage &amp; price controls</li>\n          <li>📋 <strong>Direct Control</strong> — regulations &amp; quotas</li>\n          <li>🌍 <strong>Foreign Trade</strong> — tariffs, exchange rates</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 2. Business Cycle -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🔄</div>\n    <h2>The Business Cycle <span class=\"underline\"></span></h2>\n    <p>Fluctuations in GDP around the natural growth rate. The economy moves through phases of expansion and contraction.</p>\n\n    <svg class=\"cycle-svg\" viewBox=\"0 0 700 300\" xmlns=\"http://www.w3.org/2000/svg\">\n      <defs>\n        <linearGradient id=\"cycleGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n          <stop offset=\"0%\" stop-color=\"#0984e3\" stop-opacity=\"0.15\"></stop>\n          <stop offset=\"100%\" stop-color=\"#00b894\" stop-opacity=\"0.15\"></stop>\n        </linearGradient>\n        <linearGradient id=\"trendGrad\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"0%\">\n          <stop offset=\"0%\" stop-color=\"#fdcb6e\" stop-opacity=\"0.5\"></stop>\n          <stop offset=\"100%\" stop-color=\"#fdcb6e\" stop-opacity=\"0.5\"></stop>\n        </linearGradient>\n      </defs>\n      <!-- Grid lines -->\n      <line x1=\"50\" y1=\"50\" x2=\"50\" y2=\"250\" stroke=\"rgba(255,255,255,0.05)\" stroke-width=\"1\"></line>\n      <line x1=\"50\" y1=\"150\" x2=\"650\" y2=\"150\" stroke=\"rgba(255,255,255,0.08)\" stroke-width=\"1\" stroke-dasharray=\"4,4\"></line>\n      <!-- Trend line -->\n      <line x1=\"50\" y1=\"180\" x2=\"650\" y2=\"120\" stroke=\"#fdcb6e\" stroke-width=\"1.5\" stroke-dasharray=\"6,3\" opacity=\"0.4\"></line>\n      <!-- Cycle curve -->\n      <path d=\"M 50 190 \n               Q 120 180, 180 150 \n               Q 240 110, 310 130 \n               Q 380 150, 440 110 \n               Q 500 60, 540 80\n               Q 580 100, 650 130\" fill=\"none\" stroke=\"url(#cycleGrad)\" stroke-width=\"3\" stroke-linecap=\"round\"></path>\n      <path d=\"M 50 190 \n               Q 120 180, 180 150 \n               Q 240 110, 310 130 \n               Q 380 150, 440 110 \n               Q 500 60, 540 80\n               Q 580 100, 650 130\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"2\" stroke-linecap=\"round\" opacity=\"0.6\"></path>\n      <!-- Labels -->\n      <text x=\"140\" y=\"100\" fill=\"#fdcb6e\" font-size=\"13\" font-weight=\"700\" text-anchor=\"middle\">PEAK</text>\n      <text x=\"400\" y=\"60\" fill=\"#fdcb6e\" font-size=\"13\" font-weight=\"700\" text-anchor=\"middle\">PEAK</text>\n      <text x=\"60\" y=\"210\" fill=\"#0984e3\" font-size=\"13\" font-weight=\"700\" text-anchor=\"middle\">TROUGH</text>\n      <text x=\"290\" y=\"155\" fill=\"#0984e3\" font-size=\"13\" font-weight=\"700\" text-anchor=\"middle\">TROUGH</text>\n      <!-- Phase arrows -->\n      <text x=\"210\" y=\"220\" fill=\"#d63031\" font-size=\"11\" font-weight=\"600\" text-anchor=\"middle\">Recession</text>\n      <text x=\"500\" y=\"200\" fill=\"#00b894\" font-size=\"11\" font-weight=\"600\" text-anchor=\"middle\">Expansion</text>\n      <text x=\"100\" y=\"175\" fill=\"#00b894\" font-size=\"11\" font-weight=\"600\" text-anchor=\"middle\">Expansion</text>\n      <text x=\"345\" y=\"175\" fill=\"#d63031\" font-size=\"11\" font-weight=\"600\" text-anchor=\"middle\">Recession</text>\n      <!-- Arrows -->\n      <defs>\n        <marker id=\"arrowGreen\" markerWidth=\"8\" markerHeight=\"6\" refX=\"8\" refY=\"3\" orient=\"auto\">\n          <path d=\"M0,0 L8,3 L0,6\" fill=\"#00b894\"></path>\n        </marker>\n        <marker id=\"arrowRed\" markerWidth=\"8\" markerHeight=\"6\" refX=\"0\" refY=\"3\" orient=\"auto\">\n          <path d=\"M8,0 L0,3 L8,6\" fill=\"#d63031\"></path>\n        </marker>\n      </defs>\n      <text x=\"650\" y=\"145\" fill=\"#fdcb6e\" font-size=\"10\" text-anchor=\"end\">Natural Growth</text>\n      <text x=\"650\" y=\"160\" fill=\"#0984e3\" font-size=\"10\" text-anchor=\"end\">Actual Output</text>\n      <text x=\"50\" y=\"20\" fill=\"var(--text-muted)\" font-size=\"10\">Real GDP</text>\n      <text x=\"660\" y=\"260\" fill=\"var(--text-muted)\" font-size=\"10\">Time</text>\n      <!-- Dot markers on peaks/troughs -->\n      <circle cx=\"140\" cy=\"100\" r=\"5\" fill=\"#fdcb6e\" opacity=\"0.8\"></circle>\n      <circle cx=\"400\" cy=\"60\" r=\"5\" fill=\"#fdcb6e\" opacity=\"0.8\"></circle>\n      <circle cx=\"60\" cy=\"190\" r=\"5\" fill=\"#0984e3\" opacity=\"0.8\"></circle>\n      <circle cx=\"290\" cy=\"138\" r=\"5\" fill=\"#0984e3\" opacity=\"0.8\"></circle>\n    </svg>\n\n    <h3>🎯 Potential Output vs Actual Output</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">📈 Potential Output</div>\n        <ul>\n          <li>Maximum sustainable output at full employment</li>\n          <li>Grows at the natural growth rate</li>\n          <li>Represents long-run trend</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📉 Actual Output</div>\n        <ul>\n          <li>Real GDP observed in the economy</li>\n          <li>Fluctuates around potential output</li>\n          <li>Above = inflationary pressure, Below = recessionary gap</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>🧐 Business Cycle Phases — Click to Explore</h3>\n    <div class=\"phase-tags\">\n      <div class=\"phase-tag peak\" data-phase=\"0\" onclick=\"selectPhase(0)\">⚡ Peak</div>\n      <div class=\"phase-tag recession\" data-phase=\"1\" onclick=\"selectPhase(1)\">📉 Recession</div>\n      <div class=\"phase-tag trough\" data-phase=\"2\" onclick=\"selectPhase(2)\">📍 Trough</div>\n      <div class=\"phase-tag expansion\" data-phase=\"3\" onclick=\"selectPhase(3)\">📈 Expansion</div>\n    </div>\n    <div class=\"phase-detail\" id=\"phaseDetail\">\n      <div class=\"phase-title\" style=\"color: var(--accent3);\">⚡ Peak</div>\n      <div class=\"phase-desc\">The highest point of economic activity. GDP is at maximum, employment is high, and inflationary pressures build.</div>\n      <div class=\"phase-chars\">\n        <div class=\"char-item\"><div class=\"char-label\">GDP</div><div class=\"char-value\" style=\"color:var(--accent3);\">Maximum</div></div>\n        <div class=\"char-item\"><div class=\"char-label\">Employment</div><div class=\"char-value\" style=\"color:var(--accent3);\">Full</div></div>\n        <div class=\"char-item\"><div class=\"char-label\">Unemployment</div><div class=\"char-value\" style=\"color:#d63031;\">Lowest</div></div>\n        <div class=\"char-item\"><div class=\"char-label\">Aggregate Demand</div><div class=\"char-value\" style=\"color:var(--accent3);\">High</div></div>\n        <div class=\"char-item\"><div class=\"char-label\">Econ. Growth</div><div class=\"char-value\" style=\"color:#d63031;\">Slowing</div></div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 3. Macroeconomic Equilibrium -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚖️</div>\n    <h2>Macroeconomic Equilibrium <span class=\"underline\"></span></h2>\n    <p>Equilibrium occurs when aggregate demand equals aggregate supply — no tendency for change.</p>\n\n    <h3>🏡 The Four Sectors</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🏠</div><div class=\"label\">Household</div><div class=\"desc\">Consumers, suppliers of labour</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏭</div><div class=\"label\">Business</div><div class=\"desc\">Firms producing goods &amp; services</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏛️</div><div class=\"label\">Government</div><div class=\"desc\">Public spending &amp; taxation</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌍</div><div class=\"label\">Foreign</div><div class=\"desc\">International trade &amp; capital flows</div></div>\n    </div>\n\n    <h3>📊 Three Approaches to Equilibrium</h3>\n    <div class=\"formula-box\">AD = AS</div>\n    <div class=\"formula-box green\">Y = E &nbsp;&nbsp;&nbsp;(Output = Aggregate Expenditure)</div>\n    <div class=\"formula-box yellow\">W = J &nbsp;&nbsp;&nbsp;(Withdrawals = Injections)</div>\n\n    <h4>Aggregate Demand (AD)</h4>\n    <p>The total quantity of goods and services demanded in the economy at a given price level.</p>\n\n    <h4>Aggregate Supply (AS)</h4>\n    <p>The total quantity of goods and services that firms are willing to produce at a given price level.</p>\n  </div>\n\n  <!-- 4. Aggregate Expenditure Components -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💰</div>\n    <h2>Aggregate Expenditure Components <span class=\"underline\"></span></h2>\n    <p>Total spending in the economy is the sum of four components:</p>\n    <div class=\"formula-box\" style=\"font-size: 1.3rem;\">AE = C + I + G + (X − M)</div>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🛍️</div><div class=\"label\">Consumption (C)</div><div class=\"desc\">Household spending on goods &amp; services</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏭</div><div class=\"label\">Investment (I)</div><div class=\"desc\">Business spending on capital goods</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏛️</div><div class=\"label\">Government (G)</div><div class=\"desc\">Government expenditure on goods &amp; services</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌍</div><div class=\"label\">Net Exports (X−M)</div><div class=\"desc\">Exports minus Imports</div></div>\n    </div>\n  </div>\n\n  <!-- 5. Consumption Function -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📈</div>\n    <h2>The Consumption Function <span class=\"underline\"></span></h2>\n    <p>The relationship between disposable income and consumption spending.</p>\n\n    <div class=\"formula-box\" style=\"font-size: 1.3rem;\">C = a + bY<sub>d</sub></div>\n\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">💵</div>\n        <div class=\"label\"><em>a</em> = Autonomous Consumption</div>\n        <div class=\"desc\">Consumption when income is zero → C = a (dissaving)</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📈</div>\n        <div class=\"label\"><em>b</em> = MPC</div>\n        <div class=\"desc\">Marginal Propensity to Consume = ΔC / ΔY</div>\n      </div>\n    </div>\n\n    <h3>📋 Marginal Propensity to Consume (MPC)</h3>\n    <div class=\"formula-box green\">MPC = ΔC / ΔY</div>\n    <p>The fraction of an additional unit of income that is spent on consumption. <span class=\"highlight\">0 &lt; MPC &lt; 1</span></p>\n\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">💰 High MPC</div>\n        <ul>\n          <li>Consumers spend most of additional income</li>\n          <li>Large multiplier effect</li>\n          <li>Often in developing economies</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">💱 Low MPC</div>\n        <ul>\n          <li>Consumers save most of additional income</li>\n          <li>Small multiplier effect</li>\n          <li>Often in developed economies</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 6. Savings Function -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💱</div>\n    <h2>The Savings Function <span class=\"underline\"></span></h2>\n    <p>Savings is the part of income not consumed.</p>\n\n    <div class=\"formula-box\" style=\"font-size: 1.3rem;\">S = Y − C</div>\n\n    <p>Deriving the savings function from the consumption function:</p>\n    <div class=\"formula-box green\">S = −a + (1−b)Y</div>\n\n    <h3>📋 MPS — Marginal Propensity to Save</h3>\n    <div class=\"formula-box yellow\">MPS = 1 − MPC</div>\n    <p>The fraction of additional income that is saved. <span class=\"highlight\">MPC + MPS = 1</span></p>\n\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">💵</div><div class=\"label\">Autonomous Savings</div><div class=\"desc\">−a — dissaving at zero income</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📈</div><div class=\"label\">Induced Savings</div><div class=\"desc\">(1−b)Y — savings that depend on income</div></div>\n    </div>\n  </div>\n\n  <!-- 7. Closed Economy Equilibrium -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏠</div>\n    <h2>Closed Economy Equilibrium <span class=\"underline\"></span></h2>\n    <p>A closed economy has no foreign sector. Equilibrium is achieved when:</p>\n\n    <div class=\"formula-box\" style=\"font-size: 1.3rem;\">Y = C + I + G</div>\n    <div class=\"formula-box green\">S + T − R = I + G &nbsp;&nbsp;<span style=\"font-weight:400;font-size:0.9rem;color:var(--text-muted)\">(W = J approach)</span></div>\n\n    <h3>📋 Worked Example</h3>\n    <div class=\"diagram-box\">\n      <pre>Given: C = 100 + 0.75Y<sub>d</sub>, &nbsp; I = 50, &nbsp; G = 200\n\nIn equilibrium: Y = C + I + G\nY = 100 + 0.75Y + 50 + 200\nY − 0.75Y = 350\n0.25Y = 350\n<b>Y = 1400</b>\n      </pre>\n    </div>\n  </div>\n\n  <!-- 8. Open Economy Equilibrium -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🌍</div>\n    <h2>Open Economy Equilibrium <span class=\"underline\"></span></h2>\n    <p>An open economy includes international trade. Equilibrium condition:</p>\n\n    <div class=\"formula-box\" style=\"font-size: 1.3rem;\">Y = C + I + G + (X − M)</div>\n\n    <h3>📋 Worked Example</h3>\n    <div class=\"diagram-box\">\n      <pre>Given: C = 200 + 0.8Y<sub>d</sub>, &nbsp; I = 100, &nbsp; G = 200, &nbsp; Net Exports = −100\n\nIn equilibrium: Y = C + I + G + (X − M)\nY = 200 + 0.8Y + 100 + 200 + (−100)\nY − 0.8Y = 400\n0.2Y = 400\n<b>Y = 2000</b>\n      </pre>\n    </div>\n\n    <h3>📈 Effect of an Increase in Investment</h3>\n    <p>If investment increases by ΔI, the equilibrium output changes by the multiplier times the change in investment.</p>\n    <div class=\"formula-box green\">ΔY = k × ΔI</div>\n  </div>\n\n  <!-- 9. Comparison: Closed vs Open Economy -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚖️</div>\n    <h2>Closed vs Open Economy <span class=\"underline\"></span></h2>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🏠 Closed Economy</div>\n        <ul>\n          <li>No international trade</li>\n          <li>Y = C + I + G</li>\n          <li>W = S + T − R</li>\n          <li>J = I + G</li>\n          <li>Unaffected by global shocks</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🌍 Open Economy</div>\n        <ul>\n          <li>Includes exports &amp; imports</li>\n          <li>Y = C + I + G + (X−M)</li>\n          <li>W = S + T − R + M</li>\n          <li>J = I + G + X</li>\n          <li>Exposed to global economic conditions</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 10. The Multiplier -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💰</div>\n    <h2>The Multiplier <span class=\"underline\"></span></h2>\n    <p>The multiplier measures the magnified effect of a change in autonomous expenditure on equilibrium output.</p>\n\n    <div class=\"formula-box\" style=\"font-size: 1.3rem;\">k = 1 / (1 − MPC) = 1 / MPS</div>\n    <div class=\"formula-box green\">ΔY = k × ΔE</div>\n\n    <h3>📋 Examples</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">📈</div><div class=\"label\">MPC = 0.8</div><div class=\"desc\">k = 1 / (1 − 0.8) = <strong>5</strong></div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📈</div><div class=\"label\">MPC = 0.9</div><div class=\"desc\">k = 1 / (1 − 0.9) = <strong>10</strong></div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📈</div><div class=\"label\">MPC = 0.75</div><div class=\"desc\">k = 1 / (1 − 0.75) = <strong>4</strong></div></div>\n    </div>\n\n    <h3>🧩 Interactive Multiplier Calculator</h3>\n    <div class=\"calc-container\">\n      <label for=\"mpcSlider\">Marginal Propensity to Consume (MPC): <span id=\"mpcValue\" style=\"color:var(--accent);font-weight:800;\">0.75</span></label>\n      <input type=\"range\" id=\"mpcSlider\" min=\"0\" max=\"0.99\" step=\"0.01\" value=\"0.75\" oninput=\"calcMultiplier()\">\n      <div class=\"calc-result\">\n        <div class=\"stat\">\n          <div class=\"value\" id=\"multiplierValue\">4.00</div>\n          <div class=\"label\">Multiplier (k)</div>\n        </div>\n        <div class=\"stat\">\n          <div class=\"value green\" id=\"mpsValue\">0.25</div>\n          <div class=\"label\">MPS</div>\n        </div>\n      </div>\n      <div style=\"font-size:0.85rem;color:var(--text-muted);text-align:center;\">\n        If autonomous expenditure increases by <span class=\"highlight\">100</span>, output will rise by <span class=\"highlight-green\" id=\"deltaYExample\">400</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- 11. Macroeconomic Policies Comparison -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🔧</div>\n    <h2>Macroeconomic Policies <span class=\"underline\"></span></h2>\n    <div class=\"comparison three-col\">\n      <div class=\"left\">\n        <div class=\"header\">💵 Monetary</div>\n        <ul>\n          <li>Central bank controls money supply</li>\n          <li>Interest rate adjustments</li>\n          <li>Open market operations</li>\n          <li>Affects borrowing &amp; spending</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">💰 Fiscal</div>\n        <ul>\n          <li>Government spending decisions</li>\n          <li>Taxation policy</li>\n          <li>Budget deficits / surpluses</li>\n          <li>Direct demand management</li>\n        </ul>\n      </div>\n      <div class=\"col3\">\n        <div class=\"header\">🏭 Supply-side</div>\n        <ul>\n          <li>Deregulation &amp; privatization</li>\n          <li>Tax reforms to boost work</li>\n          <li>Investment in infrastructure</li>\n          <li>Labor market reforms</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 12. Flashcards -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💡</div>\n    <h2>Key Terms <span class=\"underline\"></span></h2>\n    <div class=\"flashcard-container\">\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            💵 MPC\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Marginal Propensity to Consume<br>\n            <small>ΔC / ΔY<br>The fraction of extra income spent</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            💱 MPS\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Marginal Propensity to Save<br>\n            <small>1 − MPC<br>The fraction of extra income saved</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            💰 Multiplier\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            k = 1/(1−MPC) = 1/MPS<br>\n            <small>Measures the magnified change in output from a change in autonomous expenditure</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            📈 Autonomous Consumption\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Consumption at zero income<br>\n            <small>C = a + bY<sub>d</sub> → a = autonomous<br>Funded by dissaving or borrowing</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🔄 Business Cycle\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Fluctuations in GDP<br>\n            <small>Peak → Recession → Trough → Expansion</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            ⚖️ Macro Equilibrium\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            AD = AS, Y = E, W = J<br>\n            <small>No tendency for change in the economy</small>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 13. Quiz -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧰</div>\n    <h2>Test Your Knowledge <span class=\"underline\"></span></h2>\n\n    <div class=\"quiz-question\" data-q=\"1\">\n      <div class=\"q\">1. What is the formula for the multiplier?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">k = 1 / MPC</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">k = 1 + MPS</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">k = 1 / (1 − MPC)</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">k = MPC / MPS</button>\n      <div class=\"quiz-feedback\" data-feedback=\"1\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"2\">\n      <div class=\"q\">2. In a closed economy, the equilibrium condition is:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Y = C + I</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Y = C + I + G</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Y = C + I + G + (X − M)</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Y = C + S + T</button>\n      <div class=\"quiz-feedback\" data-feedback=\"2\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"3\">\n      <div class=\"q\">3. If MPC = 0.9, what is the value of the multiplier?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">5</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">4</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">1</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">10</button>\n      <div class=\"quiz-feedback\" data-feedback=\"3\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"4\">\n      <div class=\"q\">4. Which of the following is NOT a macroeconomic objective?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Full employment</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Economic stability</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Profit maximization</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Sustainable development</button>\n      <div class=\"quiz-feedback\" data-feedback=\"4\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"5\">\n      <div class=\"q\">5. In the business cycle, the lowest point of economic activity is called:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Peak</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Recession</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Trough</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Expansion</button>\n      <div class=\"quiz-feedback\" data-feedback=\"5\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"6\">\n      <div class=\"q\">6. What does MPS equal?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">MPC − 1</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">MPC + 1</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">1 − MPC</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">1 / MPC</button>\n      <div class=\"quiz-feedback\" data-feedback=\"6\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"7\">\n      <div class=\"q\">7. If autonomous consumption is 200 and MPC is 0.8, the savings function is:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">S = 200 + 0.8Y</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">S = −200 + 0.8Y</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">S = −200 + 0.2Y</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">S = 200 + 0.2Y</button>\n      <div class=\"quiz-feedback\" data-feedback=\"7\"></div>\n    </div>\n  </div>\n\n</div>\n\n<script>\n  const canvas = document.getElementById('particles');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  class Particle {\n    constructor() {\n      this.reset();\n    }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.5;\n      this.speedY = (Math.random() - 0.5) * 0.5;\n      this.opacity = Math.random() * 0.5 + 0.1;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n      if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(9, 132, 227, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 80; i++) particles.push(new Particle());\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 150) {\n          ctx.beginPath();\n          ctx.strokeStyle = `rgba(9, 132, 227, ${0.06 * (1 - dist / 150)})`;\n          ctx.lineWidth = 0.5;\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  const sections = document.querySelectorAll('[data-section]');\n\n  function revealSections() {\n    sections.forEach(section => {\n      const rect = section.getBoundingClientRect();\n      if (rect.top < window.innerHeight - 80) {\n        section.classList.add('visible');\n      }\n    });\n  }\n  window.addEventListener('scroll', revealSections);\n  revealSections();\n\n  const progressBar = document.getElementById('progressBar');\n\n  window.addEventListener('scroll', () => {\n    const scrollTop = window.scrollY;\n    const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n    const progress = (scrollTop / docHeight) * 100;\n    progressBar.style.width = progress + '%';\n  });\n\n  // Quiz\n  function checkAnswer(btn, isCorrect) {\n    const question = btn.closest('.quiz-question');\n    const options = question.querySelectorAll('.quiz-option');\n    const feedback = question.querySelector('.quiz-feedback');\n\n    options.forEach(opt => {\n      opt.disabled = true;\n      opt.style.cursor = 'not-allowed';\n      if (opt.dataset.correct === 'true') opt.classList.add('correct');\n    });\n\n    if (isCorrect) {\n      btn.classList.add('correct');\n      feedback.textContent = '&#x2705; Correct!';\n      feedback.className = 'quiz-feedback show correct';\n    } else {\n      btn.classList.add('wrong');\n      const correctBtn = question.querySelector('[data-correct=\"true\"]');\n      feedback.textContent = '&#x274C; Incorrect. The answer was: ' + correctBtn.textContent;\n      feedback.className = 'quiz-feedback show wrong';\n    }\n  }\n\n  // Multiplier Calculator\n  function calcMultiplier() {\n    const slider = document.getElementById('mpcSlider');\n    const mpc = parseFloat(slider.value);\n    const mps = 1 - mpc;\n    const k = mps > 0 ? 1 / mps : Infinity;\n\n    document.getElementById('mpcValue').textContent = mpc.toFixed(2);\n    document.getElementById('multiplierValue').textContent = k === Infinity ? '&#x221E;' : k.toFixed(2);\n    document.getElementById('mpsValue').textContent = mps.toFixed(2);\n    document.getElementById('deltaYExample').textContent = k === Infinity ? '&#x221E;' : (k * 100).toFixed(0);\n  }\n\n  // Business Cycle Phase Selector\n  const phases = [\n    {\n      title: '&#x26A1; Peak',\n      color: 'var(--accent3)',\n      desc: 'The highest point of economic activity. GDP is at maximum, employment is high, and inflationary pressures build.',\n      chars: [\n        { label: 'GDP', value: 'Maximum', color: 'var(--accent3)' },\n        { label: 'Employment', value: 'Full', color: 'var(--accent3)' },\n        { label: 'Unemployment', value: 'Lowest', color: '#d63031' },\n        { label: 'Aggregate Demand', value: 'High', color: 'var(--accent3)' },\n        { label: 'Econ. Growth', value: 'Slowing', color: '#d63031' },\n      ]\n    },\n    {\n      title: '&#x1F4C9; Recession',\n      color: '#d63031',\n      desc: 'A period of declining economic activity. GDP falls, unemployment rises, and aggregate demand weakens.',\n      chars: [\n        { label: 'GDP', value: 'Falling', color: '#d63031' },\n        { label: 'Employment', value: 'Decreasing', color: '#d63031' },\n        { label: 'Unemployment', value: 'Rising', color: '#d63031' },\n        { label: 'Aggregate Demand', value: 'Low', color: '#d63031' },\n        { label: 'Econ. Growth', value: 'Negative', color: '#d63031' },\n      ]\n    },\n    {\n      title: '&#x1F4CD; Trough',\n      color: 'var(--accent)',\n      desc: 'The lowest point of the business cycle. GDP stops falling, unemployment is at its peak, and the economy bottoms out before recovery.',\n      chars: [\n        { label: 'GDP', value: 'Minimum', color: 'var(--accent)' },\n        { label: 'Employment', value: 'Low', color: '#d63031' },\n        { label: 'Unemployment', value: 'Highest', color: '#d63031' },\n        { label: 'Aggregate Demand', value: 'Lowest', color: 'var(--accent)' },\n        { label: 'Econ. Growth', value: 'About to rise', color: 'var(--accent2)' },\n      ]\n    },\n    {\n      title: '&#x1F4C8; Expansion',\n      color: 'var(--accent2)',\n      desc: 'A period of economic growth. GDP rises, employment increases, unemployment falls, and consumer confidence returns.',\n      chars: [\n        { label: 'GDP', value: 'Rising', color: 'var(--accent2)' },\n        { label: 'Employment', value: 'Increasing', color: 'var(--accent2)' },\n        { label: 'Unemployment', value: 'Falling', color: 'var(--accent2)' },\n        { label: 'Aggregate Demand', value: 'Growing', color: 'var(--accent2)' },\n        { label: 'Econ. Growth', value: 'Positive', color: 'var(--accent2)' },\n      ]\n    }\n  ];\n\n  function selectPhase(index) {\n    const tags = document.querySelectorAll('.phase-tag');\n    tags.forEach((t, i) => t.classList.toggle('active', i === index));\n\n    const p = phases[index];\n    const detail = document.getElementById('phaseDetail');\n    detail.innerHTML = `\n      <div class=\"phase-title\" style=\"color: ${p.color};\">${p.title}</div>\n      <div class=\"phase-desc\">${p.desc}</div>\n      <div class=\"phase-chars\">\n        ${p.chars.map(c => `<div class=\"char-item\"><div class=\"char-label\">${c.label}</div><div class=\"char-value\" style=\"color:${c.color};\">${c.value}</div></div>`).join('')}\n      </div>\n    `;\n  }\n</script>\n\n\n\n\n</body>\n</html>",
    "7": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<canvas id=\"particles-canvas\"></canvas>\n<div id=\"progress-bar\"></div>\n<div id=\"top-nav\"></div>\n\n<div class=\"content\">\n\n\n\n<!-- HERO -->\n<section class=\"hero reveal\">\n  <div class=\"hero-badge\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"></path><path d=\"M20 2v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2H20z\"></path><line x1=\"8\" y1=\"7\" x2=\"16\" y2=\"7\"></line><line x1=\"8\" y1=\"11\" x2=\"14\" y2=\"11\"></line></svg> LESSON 7</div>\n  <h1>Price, Inflation, Money &amp;<br>Financial System</h1>\n  <p>Understanding price theory, inflation dynamics, the nature of money, and Sri Lanka's financial architecture</p>\n  <div class=\"hero-scroll\">⌄</div>\n</section>\n\n<!-- 1. PRICE CONCEPTS -->\n<section class=\"section reveal\" id=\"price-concepts\">\n  <div class=\"section-title\"><span class=\"num\">1</span> Price Concepts</div>\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"21\"></line></svg> Absolute Price</h3>\n  <p>The nominal price of a good expressed in monetary units — what you actually pay at the store. Also called <strong>money price</strong>.</p>\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"21\"></line></svg> Relative Price</h3>\n  <p>The price of one good compared to another; represents the <strong>opportunity cost</strong> of consuming one good in terms of the other.</p>\n  <div class=\"formula-box\">Relative Price = Price of Good A ÷ Price of Good B</div>\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"21\"></line></svg> General Price Level</h3>\n  <p>The <strong>average</strong> of all prices in an economy, measured via a price index. A rise in the general price level = inflation.</p>\n\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"20\" x2=\"18\" y2=\"10\"></line><line x1=\"12\" y1=\"20\" x2=\"12\" y2=\"4\"></line><line x1=\"6\" y1=\"20\" x2=\"6\" y2=\"14\"></line></svg> Absolute vs Relative Price</h3>\n  <table class=\"comparison-table\">\n    <thead><tr><th>Aspect</th><th>Absolute Price</th><th>Relative Price</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Definition</strong></td><td>Price in monetary terms</td><td>Price ratio between goods</td></tr>\n      <tr><td><strong>Unit</strong></td><td>Currency (e.g. Rs.)</td><td>Ratio (unitless)</td></tr>\n      <tr><td><strong>Reflects</strong></td><td>Nominal value</td><td>Opportunity cost</td></tr>\n      <tr><td><strong>Changes with</strong></td><td>Inflation</td><td>Supply/demand shifts</td></tr>\n      <tr><td><strong>Example</strong></td><td>A pen costs Rs. 100</td><td>1 pen = 2 notebooks</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<!-- 2. PRICE INDEX & INFLATION -->\n<section class=\"section reveal\" id=\"price-index\">\n  <div class=\"section-title\"><span class=\"num\">2</span> Price Index &amp; Inflation</div>\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"21\"></line></svg> Price Index</h3>\n  <p>A <strong>measure of the average price level</strong> of a basket of goods and services relative to a base year. Examples: CPI, GDP deflator.</p>\n  <div class=\"formula-box\">Price Index = (Cost of Basket in Current Year ÷ Cost of Basket in Base Year) × 100</div>\n\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"21\"></line></svg> Inflation, Deflation &amp; Disinflation</h3>\n  <table class=\"comparison-table\">\n    <thead><tr><th>Concept</th><th>Definition</th><th>Effect on Prices</th><th>Rate Direction</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Inflation</strong></td><td>Continuous ↑ in general price level</td><td>Prices rise</td><td>Positive &amp; ↑</td></tr>\n      <tr><td><strong>Deflation</strong></td><td>Continuous ↓ in general price level</td><td>Prices fall</td><td>Negative</td></tr>\n      <tr><td><strong>Disinflation</strong></td><td>↓ rate of increase of price level</td><td>Prices still rise, but slower</td><td>Positive but ↓</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<!-- 3. TYPES OF INFLATION -->\n<section class=\"section reveal\" id=\"types-inflation\">\n  <div class=\"section-title\"><span class=\"num\">3</span> Types of Inflation</div>\n  <h3>By Rate of Increase</h3>\n  <table class=\"comparison-table\">\n    <thead><tr><th>Type</th><th>Rate</th><th>Characteristic</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Creeping</strong></td><td>≤ 2%</td><td>Beneficial — mild, encourages spending &amp; investment</td></tr>\n      <tr><td><strong>Walking</strong></td><td>3–9%</td><td>Moderate — begins to distort decisions, harmful</td></tr>\n      <tr><td><strong>Galloping</strong></td><td>10%+</td><td>Damaging — people flee from money, severe distortions</td></tr>\n      <tr><td><strong>Hyperinflation</strong></td><td>≥ 50% / month</td><td>Catastrophic — monetary system collapses</td></tr>\n    </tbody>\n  </table>\n  <p><strong>🌍 Historical Example:</strong> <span class=\"highlight\">Hungary 1945–46</span> — prices doubled every 15 hours. The highest inflation ever recorded.</p>\n</section>\n\n<!-- 4. CAUSES OF INFLATION -->\n<section class=\"section reveal\" id=\"causes-inflation\">\n  <div class=\"section-title\"><span class=\"num\">4</span> Causes of Inflation</div>\n\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"></path><polyline points=\"7 10 12 15 17 10\"></polyline><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"></line></svg> Demand-Pull Inflation</h3>\n  <p><span class=\"highlight\">\"Too much money chasing too few goods.\"</span> Aggregate demand exceeds aggregate supply at full employment.</p>\n\n  <h4>Quantity Theory of Money (QTM)</h4>\n  <div class=\"formula-box\">MV = PT<br><span style=\"font-size:0.75rem;font-family:inherit;\">M = Money Supply | V = Velocity | P = Price Level | T = Transactions</span></div>\n  <p>If V and T are constant, an <strong>increase in M</strong> causes a proportionate <strong>increase in P</strong> (inflation).</p>\n\n  <h4>Keynesian Theory</h4>\n  <p>When <strong>aggregate demand</strong> exceeds full-employment output, the excess demand pulls prices upward. Output cannot rise further, so the entire increase in AD translates into higher prices.</p>\n\n  <!-- QTM CALCULATOR -->\n  <div class=\"calculator\" id=\"qtm-calc\">\n    <h4 style=\"color:var(--accent);margin-bottom:12px;\">🧮 Interactive QTM Calculator</h4>\n    <div class=\"calc-grid\">\n      <div class=\"calc-field\"><label>Money Supply (M) — Rs.</label><input type=\"number\" id=\"qtm-m\" value=\"1000\" step=\"100\"></div>\n      <div class=\"calc-field\"><label>Velocity (V)</label><input type=\"number\" id=\"qtm-v\" value=\"5\" step=\"0.5\"></div>\n      <div class=\"calc-field\"><label>Transactions (T)</label><input type=\"number\" id=\"qtm-t\" value=\"500\" step=\"10\"></div>\n    </div>\n    <button class=\"calc-btn\" onclick=\"calcQTM()\">Calculate Price (P)</button>\n    <div class=\"calc-result\" id=\"qtm-result\">P = 10.00</div>\n    <p style=\"font-size:0.8rem;color:var(--text-dim);text-align:center;margin-top:6px;\">MV = PT → P = (M × V) ÷ T</p>\n  </div>\n\n  <div class=\"divider\"></div>\n\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"></path><polyline points=\"17 8 12 3 7 8\"></polyline><line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"></line></svg> Cost-Push Inflation</h3>\n  <p>An increase in the cost of inputs (wages, raw materials, energy) shifts the <strong>Aggregate Supply</strong> curve leftward, raising the price level.</p>\n  <ul>\n    <li><strong>Organised labour (wage push)</strong> — unions negotiate higher wages → firms raise prices to maintain margins.</li>\n    <li><strong>Oligopoly firms (profit push)</strong> — firms with market power raise prices to increase profit margins.</li>\n  </ul>\n\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2v20\"></path><path d=\"M8 22h8\"></path><path d=\"M2 6c.6.5 1.2 1 2.5 1C7 7 7 5 9.5 5c2.6 0 2.4 2 5 2 2.5 0 2.5-2 5-2 1.3 0 1.9.5 2.5 1\"></path></svg>️ Demand-Pull vs Cost-Push</h3>\n  <table class=\"comparison-table\">\n    <thead><tr><th>Aspect</th><th>Demand-Pull</th><th>Cost-Push</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Origin</strong></td><td>Aggregate Demand side</td><td>Aggregate Supply side</td></tr>\n      <tr><td><strong>Motto</strong></td><td>\"Too much money\"</td><td>\"Too costly to produce\"</td></tr>\n      <tr><td><strong>Output</strong></td><td>At or above full employment</td><td>Below full employment (stagflation)</td></tr>\n      <tr><td><strong>Key trigger</strong></td><td>Money supply ↑, fiscal expansion</td><td>Wage ↑, oil shock, raw material ↑</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<!-- 5. EFFECTS OF INFLATION -->\n<section class=\"section reveal\" id=\"effects\">\n  <div class=\"section-title\"><span class=\"num\">5</span> Effects of Inflation</div>\n  <table class=\"comparison-table\">\n    <thead><tr><th>Favourable</th><th>Unfavourable</th></tr></thead>\n    <tbody>\n      <tr><td>Encourages spending &amp; investment (mild inflation)</td><td>Erodes real incomes &amp; purchasing power</td></tr>\n      <tr><td>Reduces real burden of debt</td><td>Hurts fixed-income earners &amp; savers</td></tr>\n      <tr><td>Prevents deflation (worse than inflation)</td><td>Creates uncertainty &amp; discourages long-term planning</td></tr>\n      <tr><td>Can boost profits if wages lag</td><td>Distorts price signals &amp; resource allocation</td></tr>\n      <tr><td>—</td><td>Shoe-leather &amp; menu costs</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<!-- 6. MONEY -->\n<section class=\"section reveal\" id=\"money\">\n  <div class=\"section-title\"><span class=\"num\">6</span> Money</div>\n  <h3>📌 Definition</h3>\n  <p>Money is any asset that is <strong>generally accepted</strong> as payment for goods and services and for settling debts.</p>\n\n  <h3>❌ Drawbacks of the Barter System</h3>\n  <ul>\n    <li><strong>Lack of double coincidence of wants</strong> — both parties must want what the other offers.</li>\n    <li><strong>No common measure of value</strong> — no standard unit to express prices.</li>\n    <li><strong>Indivisibility</strong> — some goods cannot be split into smaller units.</li>\n    <li><strong>Deferred payments</strong> — difficult to make credit/loan contracts.</li>\n    <li><strong>Storing value</strong> — most goods perish or depreciate.</li>\n  </ul>\n\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"></path><polyline points=\"22 4 12 14.01 9 11.01\"></polyline></svg> Characteristics of Good Money</h3>\n  <ul>\n    <li><strong>General acceptance</strong> — everyone trusts and accepts it.</li>\n    <li><strong>Durability</strong> — lasts through repeated use.</li>\n    <li><strong>Uniformity</strong> — identical units have identical value.</li>\n    <li><strong>Divisibility</strong> — can be split into smaller denominations.</li>\n    <li><strong>Portability</strong> — easy to carry and transport.</li>\n    <li><strong>Stability of value</strong> — does not fluctuate wildly.</li>\n    <li><strong>Legal validity</strong> — recognised by law as legal tender.</li>\n    <li><strong>Difficulty to counterfeit</strong> — secure against forgery.</li>\n    <li><strong>Easy identification</strong> — recognisable by the public.</li>\n  </ul>\n\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z\"></path><polyline points=\"3.27 6.96 12 12.01 20.73 6.96\"></polyline><line x1=\"12\" y1=\"22.08\" x2=\"12\" y2=\"12\"></line></svg> Four Functions of Money</h3>\n  <table class=\"comparison-table\">\n    <thead><tr><th>Function</th><th>Meaning</th><th>Example</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Medium of Exchange</strong></td><td>Used to buy/sell goods &amp; services</td><td>Paying Rs. 50 for tea</td></tr>\n      <tr><td><strong>Unit of Account</strong></td><td>Standard unit for quoting prices</td><td>Goods priced in Rupees</td></tr>\n      <tr><td><strong>Standard of Deferred Payment</strong></td><td>Used for credit/loan contracts</td><td>Loan repayment in Rupees</td></tr>\n      <tr><td><strong>Store of Wealth</strong></td><td>Preserves value over time</td><td>Saving in a bank account</td></tr>\n    </tbody>\n  </table>\n\n  <h3>💧 Liquidity</h3>\n  <p><strong>Liquidity</strong> is the ease with which an asset can be converted into cash without loss of value. <span class=\"highlight\">Money is the most liquid asset.</span></p>\n</section>\n\n<!-- 7. TYPES OF MONEY -->\n<section class=\"section reveal\" id=\"types-money\">\n  <div class=\"section-title\"><span class=\"num\">7</span> Types of Money</div>\n  <table class=\"comparison-table\">\n    <thead><tr><th>Type</th><th>Description</th><th>Examples</th><th>Medium of Exchange?</th><th>Store of Value?</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Currency</strong></td><td>Physical notes &amp; coins</td><td>Banknotes, coins</td><td><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"></path><polyline points=\"22 4 12 14.01 9 11.01\"></polyline></svg></td><td><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"></path><polyline points=\"22 4 12 14.01 9 11.01\"></polyline></svg></td></tr>\n      <tr><td><strong>Bank Money</strong></td><td>Demand deposits at banks</td><td>Checking accounts</td><td><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"></path><polyline points=\"22 4 12 14.01 9 11.01\"></polyline></svg></td><td><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"></path><polyline points=\"22 4 12 14.01 9 11.01\"></polyline></svg></td></tr>\n      <tr><td><strong>Near Money</strong></td><td>Highly liquid but not directly spendable</td><td>Fixed deposits, T-bills</td><td>❌</td><td><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"></path><polyline points=\"22 4 12 14.01 9 11.01\"></polyline></svg></td></tr>\n      <tr><td><strong>Money Substitutes</strong></td><td>Facilitate payment but not money themselves</td><td>Credit/debit cards</td><td><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"></path><polyline points=\"22 4 12 14.01 9 11.01\"></polyline></svg></td><td>❌</td></tr>\n      <tr><td><strong>Electronic/Digital Money</strong></td><td>Digital representation of value</td><td>E-wallets, crypto</td><td><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"></path><polyline points=\"22 4 12 14.01 9 11.01\"></polyline></svg></td><td>Varies</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<!-- 8. DEMAND FOR MONEY -->\n<section class=\"section reveal\" id=\"demand-money\">\n  <div class=\"section-title\"><span class=\"num\">8</span> Demand for Money</div>\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"21\"></line></svg> Liquidity Preference Theory (Keynes)</h3>\n  <p>People hold money for three motives:</p>\n  <table class=\"comparison-table\">\n    <thead><tr><th>Motive</th><th>Purpose</th><th>Relationship with Income</th><th>Relationship with Interest Rate</th></tr></thead>\n    <tbody>\n      <tr><td><strong>Transaction</strong></td><td>Everyday purchases</td><td>Positive (↑ income → ↑ demand)</td><td>Inelastic</td></tr>\n      <tr><td><strong>Precautionary</strong></td><td>Unexpected expenses</td><td>Positive</td><td>Inelastic</td></tr>\n      <tr><td><strong>Speculative</strong></td><td>To exploit future interest rate changes</td><td>—</td><td><strong>Inverse</strong> (↓ interest → ↑ demand)</td></tr>\n    </tbody>\n  </table>\n\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"20\" x2=\"18\" y2=\"10\"></line><line x1=\"12\" y1=\"20\" x2=\"12\" y2=\"4\"></line><line x1=\"6\" y1=\"20\" x2=\"6\" y2=\"14\"></line></svg> Factors Affecting Money Demand</h3>\n  <ul>\n    <li><strong>Real income</strong> — higher income → more transactions → higher money demand.</li>\n    <li><strong>Interest rate</strong> — higher rate → higher opportunity cost of holding money → lower demand.</li>\n    <li><strong>Price level</strong> — higher prices → more money needed for same transactions.</li>\n    <li><strong>Institutional factors</strong> — payment frequency, banking habits.</li>\n    <li><strong>Financial innovations</strong> — ATMs, mobile banking reduce money demand.</li>\n  </ul>\n</section>\n\n<!-- 9. MONEY SUPPLY -->\n<section class=\"section reveal\" id=\"money-supply\">\n  <div class=\"section-title\"><span class=\"num\">9</span> Money Supply</div>\n  <h3>📐 Definitions</h3>\n  <div class=\"formula-box\">M1 = Cp + DDP<br><span style=\"font-size:0.75rem;font-family:inherit;\">Cp = Currency with Public | DDP = Demand Deposits of Public</span></div>\n  <div class=\"formula-box\">M2 = M1 + TSDP<br><span style=\"font-size:0.75rem;font-family:inherit;\">TSDP = Time &amp; Savings Deposits of Public</span></div>\n  <div class=\"formula-box\">M2b = M2 + TsDNRFC + RDFCBU<br><span style=\"font-size:0.75rem;font-family:inherit;\">TsDNRFC = Time &amp; Savings Deposits of Non-bank Financial Institutions with Commercial Banks<br>RDFCBU = Residents' Foreign Currency Deposits with Commercial Banks (Utilised)</span></div>\n  <div class=\"formula-box\">M4 = M2b + LSB + RFC<br><span style=\"font-size:0.75rem;font-family:inherit;\">LSB = Liabilities of Specialised Banks | RFC = Residents' Foreign Currency Deposits with Commercial Banks (Unutilised)</span></div>\n\n  <!-- MONEY SUPPLY CALCULATOR -->\n  <div class=\"calculator\" id=\"ms-calc\">\n    <h4 style=\"color:var(--accent);margin-bottom:12px;\">🧮 Money Supply Calculator</h4>\n    <div class=\"calc-grid\">\n      <div class=\"calc-field\"><label>Currency with Public (Cp) — Rs.</label><input type=\"number\" id=\"ms-cp\" value=\"800000\" step=\"1000\"></div>\n      <div class=\"calc-field\"><label>Demand Deposits (DDP) — Rs.</label><input type=\"number\" id=\"ms-ddp\" value=\"1200000\" step=\"1000\"></div>\n      <div class=\"calc-field\"><label>Time &amp; Savings Deposits (TSDP) — Rs.</label><input type=\"number\" id=\"ms-tsdp\" value=\"2500000\" step=\"1000\"></div>\n      <div class=\"calc-field\"><label>TsD of NBFIs (TsDNRFC) — Rs.</label><input type=\"number\" id=\"ms-tsdnrfc\" value=\"400000\" step=\"1000\"></div>\n      <div class=\"calc-field\"><label>Residents' FC Deposits Utilised — Rs.</label><input type=\"number\" id=\"ms-rdfcb\" value=\"200000\" step=\"1000\"></div>\n      <div class=\"calc-field\"><label>Liabilities of Specialised Banks (LSB) — Rs.</label><input type=\"number\" id=\"ms-lsb\" value=\"300000\" step=\"1000\"></div>\n      <div class=\"calc-field\"><label>Residents' FC Deposits Unutilised — Rs.</label><input type=\"number\" id=\"ms-rfc\" value=\"100000\" step=\"1000\"></div>\n    </div>\n    <button class=\"calc-btn\" onclick=\"calcMoneySupply()\">Calculate Money Supply</button>\n    <div style=\"margin-top:12px;display:grid;grid-template-columns:repeat(auto-fit,minmax(120px,1fr));gap:10px;text-align:center;\">\n      <div><span style=\"font-size:0.75rem;color:var(--text-dim);\">M1</span><br><span class=\"calc-result\" style=\"font-size:1.2rem;\" id=\"ms-m1\">2,000,000</span></div>\n      <div><span style=\"font-size:0.75rem;color:var(--text-dim);\">M2</span><br><span class=\"calc-result\" style=\"font-size:1.2rem;\" id=\"ms-m2\">4,500,000</span></div>\n      <div><span style=\"font-size:0.75rem;color:var(--text-dim);\">M2b</span><br><span class=\"calc-result\" style=\"font-size:1.2rem;\" id=\"ms-m2b\">5,100,000</span></div>\n      <div><span style=\"font-size:0.75rem;color:var(--text-dim);\">M4</span><br><span class=\"calc-result\" style=\"font-size:1.2rem;\" id=\"ms-m4\">5,500,000</span></div>\n    </div>\n  </div>\n</section>\n\n<!-- 10. FINANCIAL SYSTEM OF SRI LANKA -->\n<section class=\"section reveal\" id=\"sri-lanka\">\n  <div class=\"section-title\"><span class=\"num\">10</span> Financial System of Sri Lanka</div>\n\n  <h3>🏛 Components</h3>\n  <ul>\n    <li><strong>Financial institutions</strong> — banks, insurance, finance companies, pension funds.</li>\n    <li><strong>Financial markets</strong> — money market, capital market, foreign exchange market.</li>\n    <li><strong>Financial instruments</strong> — shares, bonds, T-bills, insurance policies.</li>\n    <li><strong>Financial infrastructure</strong> — payments, clearing, settlement systems.</li>\n    <li><strong>Regulatory bodies</strong> — CBSL, SEC, IRCSL.</li>\n  </ul>\n\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"4\" y=\"2\" width=\"16\" height=\"20\" rx=\"2\" ry=\"2\"></rect><path d=\"M9 22v-4h6v4\"></path><line x1=\"8\" y1=\"10\" x2=\"16\" y2=\"10\"></line><line x1=\"8\" y1=\"14\" x2=\"12\" y2=\"14\"></line></svg> Central Bank of Sri Lanka (CBSL)</h3>\n  <ul>\n    <li><strong>Established:</strong> 1950 (as the Central Bank of Ceylon).</li>\n    <li><strong>First Governor:</strong> John Exter.</li>\n  </ul>\n\n  <h4>Objectives</h4>\n  <ul>\n    <li><span class=\"highlight\">Economic &amp; price stability</span> — stable inflation, sustainable growth.</li>\n    <li><span class=\"highlight\">Financial system stability</span> — sound banking &amp; financial infrastructure.</li>\n  </ul>\n\n  <h4>Main Functions</h4>\n  <ul>\n    <li>Formulating &amp; implementing <strong>monetary policy</strong>.</li>\n    <li>Formulating &amp; implementing <strong>exchange rate policy</strong>.</li>\n    <li>Issuing <strong>currency</strong> (sole authority).</li>\n    <li>Managing <strong>foreign reserves</strong>.</li>\n    <li>Acting as <strong>banker to the government</strong>.</li>\n  </ul>\n\n  <h4>Agency Functions</h4>\n  <ul>\n    <li><strong>Public debt management</strong> — issuing &amp; servicing government securities.</li>\n    <li><strong>Foreign exchange control</strong> — administering exchange controls.</li>\n    <li><strong>EPF management</strong> — Employees' Provident Fund administration.</li>\n  </ul>\n</section>\n\n<!-- 11. MONETARY POLICY -->\n<section class=\"section reveal\" id=\"monetary-policy\">\n  <div class=\"section-title\"><span class=\"num\">11</span> Monetary Policy</div>\n\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"21\"></line></svg> Frameworks</h3>\n  <ul>\n    <li><strong>Monetary targeting</strong> — targeting growth rate of a money aggregate (e.g., M2b).</li>\n    <li><strong>Flexible inflation targeting</strong> — targeting a specific inflation range while considering output stability.</li>\n  </ul>\n\n  <h3>🔧 Instruments</h3>\n  <table class=\"comparison-table\">\n    <thead><tr><th>Type</th><th>Instrument</th><th>How it Works</th></tr></thead>\n    <tbody>\n      <tr><td rowspan=\"3\"><strong>Quantitative</strong></td><td><strong>Bank Interest Rate (Policy Rate)</strong></td><td>CBSL's rate to commercial banks — higher rate = tighter money</td></tr>\n      <tr><td><strong>Statutory Reserve Ratio (SRR)</strong></td><td>Portion of deposits banks must hold as reserves</td></tr>\n      <tr><td><strong>Open Market Operations (OMO)</strong></td><td>Buying/selling govt securities to influence reserves &amp; money supply</td></tr>\n      <tr><td><strong>Qualitative</strong></td><td>Moral suasion, margin requirements, credit guidelines</td><td>Persuasion &amp; selective controls</td></tr>\n    </tbody>\n  </table>\n\n  <!-- SRR VISUAL -->\n  <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"20\" x2=\"18\" y2=\"10\"></line><line x1=\"12\" y1=\"20\" x2=\"12\" y2=\"4\"></line><line x1=\"6\" y1=\"20\" x2=\"6\" y2=\"14\"></line></svg> How SRR Works</h3>\n  <p>The <strong>Statutory Reserve Ratio (SRR)</strong> is the percentage of deposits banks must keep with the central bank. Changing SRR directly impacts lending capacity.</p>\n\n  <div class=\"srr-visual\">\n    <div style=\"margin-bottom:6px;color:var(--text-dim);font-size:0.85rem;\">\n      Bank Deposits: <strong style=\"color:var(--text);\">Rs. 1,000,000</strong>\n      &nbsp;|&nbsp; SRR: <strong style=\"color:var(--accent);\" id=\"srr-rate-display\">10%</strong>\n    </div>\n    <div class=\"srr-bar\">\n      <div class=\"srr-fraction srr-rr\" id=\"srr-rr-bar\" style=\"width:10%;\">Reserves</div>\n      <div class=\"srr-fraction srr-excess\" id=\"srr-excess-bar\" style=\"width:90%;\">Excess (Lendable)</div>\n    </div>\n    <div class=\"srr-label\">\n      <span>Required Reserves: <strong id=\"srr-required\">100,000</strong></span>\n      <span>Excess Reserves: <strong id=\"srr-excess-val\">900,000</strong></span>\n    </div>\n    <div class=\"srr-controls\">\n      <span style=\"color:var(--text-dim);font-size:0.85rem;\">Adjust SRR:</span>\n      <input type=\"range\" id=\"srr-slider\" min=\"0\" max=\"30\" value=\"10\" step=\"0.5\" style=\"width:200px;accent-color:var(--accent);\" oninput=\"updateSRR(this.value)\">\n      <span style=\"color:var(--accent);font-weight:700;\" id=\"srr-slider-val\">10%</span>\n    </div>\n    <p style=\"font-size:0.82rem;color:var(--text-dim);\">\n      <span class=\"highlight\" style=\"font-size:0.82rem;\">↑ SRR</span> → less excess reserves → less lending → <span class=\"highlight\" style=\"font-size:0.82rem;\">↓ money supply</span> &amp; <span class=\"highlight\" style=\"font-size:0.82rem;\">↑ interest rates</span>\n    </p>\n  </div>\n</section>\n\n<!-- FLASHCARDS -->\n<section class=\"section reveal\" id=\"flashcards\">\n  <div class=\"section-title\"><span class=\"num\">★</span> Key Term Flashcards</div>\n  <p style=\"margin-bottom:14px;\">Tap a card to reveal the definition.</p>\n  <div class=\"flashcard-grid\" id=\"flashcard-grid\"></div>\n</section>\n\n<!-- QUIZ -->\n<section class=\"section reveal\" id=\"quiz\">\n  <div class=\"section-title\"><span class=\"num\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></span> Knowledge Check</div>\n  <div id=\"quiz-container\"></div>\n  <div style=\"text-align:center;margin-top:16px;\">\n    <button class=\"calc-btn\" onclick=\"checkQuiz()\">Submit Answers</button>\n    <button class=\"calc-btn\" style=\"margin-left:10px;background:rgba(168,85,247,0.3);\" onclick=\"resetQuiz()\">Reset</button>\n  </div>\n  <div class=\"quiz-score\" id=\"quiz-score\"></div>\n</section>\n\n</div><!-- /content -->\n\n<script>\n// ===== PARTICLES =====\nconst canvas = document.getElementById('particles-canvas');\nconst ctx = canvas.getContext('2d');\nlet particles = [];\nlet animId;\n\nfunction resizeCanvas() {\n  canvas.width = window.innerWidth;\n  canvas.height = window.innerHeight;\n}\nresizeCanvas();\nwindow.addEventListener('resize', resizeCanvas);\n\nclass Particle {\n  constructor() {\n    this.reset();\n  }\n  reset() {\n    this.x = Math.random() * canvas.width;\n    this.y = Math.random() * canvas.height;\n    this.size = Math.random() * 2 + 0.5;\n    this.speedX = (Math.random() - 0.5) * 0.5;\n    this.speedY = (Math.random() - 0.5) * 0.5;\n    this.opacity = Math.random() * 0.5 + 0.1;\n    this.color = ['#a855f7','#ec4899','#f59e0b'][Math.floor(Math.random()*3)];\n  }\n  update() {\n    this.x += this.speedX;\n    this.y += this.speedY;\n    if (this.x < 0 || this.x > canvas.width || this.y < 0 || this.y > canvas.height) this.reset();\n  }\n  draw() {\n    ctx.beginPath();\n    ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n    ctx.fillStyle = this.color;\n    ctx.globalAlpha = this.opacity;\n    ctx.fill();\n  }\n}\n\nfor (let i = 0; i < 80; i++) particles.push(new Particle());\n\nfunction drawLines() {\n  for (let i = 0; i < particles.length; i++) {\n    for (let j = i + 1; j < particles.length; j++) {\n      const dx = particles[i].x - particles[j].x;\n      const dy = particles[i].y - particles[j].y;\n      const dist = Math.sqrt(dx * dx + dy * dy);\n      if (dist < 140) {\n        ctx.beginPath();\n        ctx.moveTo(particles[i].x, particles[i].y);\n        ctx.lineTo(particles[j].x, particles[j].y);\n        ctx.strokeStyle = '#a855f7';\n        ctx.globalAlpha = (1 - dist / 140) * 0.12;\n        ctx.lineWidth = 0.6;\n        ctx.stroke();\n      }\n    }\n  }\n}\n\nfunction animateParticles() {\n  ctx.clearRect(0, 0, canvas.width, canvas.height);\n  particles.forEach(p => { p.update(); p.draw(); });\n  drawLines();\n  animId = requestAnimationFrame(animateParticles);\n}\nanimateParticles();\n\n// ===== PROGRESS BAR & NAV =====\nconst sections = document.querySelectorAll('.section, .hero');\nconst navContainer = document.getElementById('top-nav');\n\nsections.forEach((sec, i) => {\n  const dot = document.createElement('div');\n  dot.className = 'nav-dot';\n  dot.addEventListener('click', () => {\n    sec.scrollIntoView({ behavior: 'smooth' });\n  });\n  navContainer.appendChild(dot);\n});\n\nfunction updateProgress() {\n  const scrollTop = window.scrollY;\n  const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n  const progress = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n  document.getElementById('progress-bar').style.width = progress + '%';\n\n  const navDots = document.querySelectorAll('.nav-dot');\n  let activeIdx = 0;\n  sections.forEach((sec, i) => {\n    const rect = sec.getBoundingClientRect();\n    if (rect.top <= window.innerHeight / 2) activeIdx = i;\n  });\n  navDots.forEach((d, i) => d.classList.toggle('active', i === activeIdx));\n}\nwindow.addEventListener('scroll', updateProgress);\nupdateProgress();\n\n// ===== SCROLL REVEALS =====\nconst revealEls = document.querySelectorAll('.reveal');\nconst observer = new IntersectionObserver((entries) => {\n  entries.forEach(e => {\n    if (e.isIntersecting) {\n      e.target.classList.add('visible');\n    }\n  });\n}, { threshold: 0.1 });\nrevealEls.forEach(el => observer.observe(el));\n\n// ===== FLASHCARDS =====\nconst flashcardData = [\n  { term: 'Absolute Price', def: 'The nominal price in monetary units (money price).' },\n  { term: 'Relative Price', def: 'Price of one good in terms of another; opportunity cost.' },\n  { term: 'Inflation', def: 'Continuous increase in the general price level.' },\n  { term: 'Deflation', def: 'Continuous decrease in the general price level.' },\n  { term: 'Disinflation', def: 'A decrease in the rate of inflation.' },\n  { term: 'Creeping Inflation', def: '≤2% — mild and beneficial.' },\n  { term: 'Galloping Inflation', def: '10%+ — severe and damaging.' },\n  { term: 'Hyperinflation', def: '≥50% per month — catastrophic.' },\n  { term: 'Demand-Pull Inflation', def: 'Too much money chasing too few goods.' },\n  { term: 'Cost-Push Inflation', def: 'Rising input costs shift AS left → higher prices.' },\n  { term: 'M1 (Narrow Money)', def: 'Currency with public + Demand deposits (Cp + DDP).' },\n  { term: 'M2', def: 'M1 + Time & Savings deposits (M1 + TSDP).' },\n  { term: 'Liquidity', def: 'Ease of converting an asset into cash without loss.' },\n  { term: 'Near Money', def: 'Fixed deposits, T-bills — store of value, not medium of exchange.' },\n  { term: 'Money Substitutes', def: 'Credit/debit cards — medium of exchange, not store of value.' },\n  { term: 'SRR', def: 'Statutory Reserve Ratio — portion of deposits banks must hold as reserves.' },\n  { term: 'QTM Equation', def: 'MV = PT (Money × Velocity = Price × Transactions).' },\n  { term: 'Speculative Motive', def: 'Holding money to exploit future interest rate changes.' },\n];\n\nconst grid = document.getElementById('flashcard-grid');\nflashcardData.forEach(c => {\n  const card = document.createElement('div');\n  card.className = 'flashcard';\n  card.innerHTML = `\n    <div class=\"flashcard-inner\">\n      <div class=\"flashcard-front\">${c.term}</div>\n      <div class=\"flashcard-back\">${c.def}</div>\n    </div>\n  `;\n  card.addEventListener('click', () => card.classList.toggle('flipped'));\n  grid.appendChild(card);\n});\n\n// ===== QTM CALCULATOR =====\nfunction calcQTM() {\n  const M = parseFloat(document.getElementById('qtm-m').value) || 0;\n  const V = parseFloat(document.getElementById('qtm-v').value) || 0;\n  const T = parseFloat(document.getElementById('qtm-t').value) || 1;\n  const P = (M * V) / T;\n  document.getElementById('qtm-result').textContent = 'P = ' + P.toFixed(2);\n}\ncalcQTM();\n['qtm-m','qtm-v','qtm-t'].forEach(id => {\n  document.getElementById(id).addEventListener('input', calcQTM);\n});\n\n// ===== MONEY SUPPLY CALCULATOR =====\nfunction calcMoneySupply() {\n  const cp = parseFloat(document.getElementById('ms-cp').value) || 0;\n  const ddp = parseFloat(document.getElementById('ms-ddp').value) || 0;\n  const tsdp = parseFloat(document.getElementById('ms-tsdp').value) || 0;\n  const tsdnrfc = parseFloat(document.getElementById('ms-tsdnrfc').value) || 0;\n  const rdfcb = parseFloat(document.getElementById('ms-rdfcb').value) || 0;\n  const lsb = parseFloat(document.getElementById('ms-lsb').value) || 0;\n  const rfc = parseFloat(document.getElementById('ms-rfc').value) || 0;\n\n  const m1 = cp + ddp;\n  const m2 = m1 + tsdp;\n  const m2b = m2 + tsdnrfc + rdfcb;\n  const m4 = m2b + lsb + rfc;\n\n  document.getElementById('ms-m1').textContent = m1.toLocaleString();\n  document.getElementById('ms-m2').textContent = m2.toLocaleString();\n  document.getElementById('ms-m2b').textContent = m2b.toLocaleString();\n  document.getElementById('ms-m4').textContent = m4.toLocaleString();\n}\ncalcMoneySupply();\n['ms-cp','ms-ddp','ms-tsdp','ms-tsdnrfc','ms-rdfcb','ms-lsb','ms-rfc'].forEach(id => {\n  document.getElementById(id).addEventListener('input', calcMoneySupply);\n});\n\n// ===== SRR VISUAL =====\nfunction updateSRR(val) {\n  const srr = parseFloat(val);\n  document.getElementById('srr-rate-display').textContent = srr + '%';\n  document.getElementById('srr-slider-val').textContent = srr + '%';\n  const deposits = 1000000;\n  const required = deposits * (srr / 100);\n  const excess = deposits - required;\n  document.getElementById('srr-rr-bar').style.width = srr + '%';\n  document.getElementById('srr-excess-bar').style.width = (100 - srr) + '%';\n  document.getElementById('srr-required').textContent = required.toLocaleString();\n  document.getElementById('srr-excess-val').textContent = excess.toLocaleString();\n}\n\n// ===== QUIZ =====\nconst quizData = [\n  {\n    q: 'Which type of inflation is considered beneficial?',\n    options: ['Galloping inflation', 'Creeping inflation', 'Walking inflation', 'Hyperinflation'],\n    correct: 1\n  },\n  {\n    q: 'What does the QTM equation MV = PT stand for?',\n    options: [\n      'Money × Value = Price × Tax',\n      'Money × Velocity = Price × Transactions',\n      'Market × Volume = Product × Trade',\n      'Monetary × Value = Purchasing × Total'\n    ],\n    correct: 1\n  },\n  {\n    q: 'M2 is calculated as:',\n    options: ['Cp + DDP', 'M1 + TSDP', 'M1 + T-bills', 'Cp + TSDP + RFC'],\n    correct: 1\n  },\n  {\n    q: 'Which motive for holding money has an inverse relationship with the interest rate?',\n    options: ['Transaction motive', 'Precautionary motive', 'Speculative motive', 'Income motive'],\n    correct: 2\n  },\n  {\n    q: 'What was unique about Hungary\\'s 1945–46 hyperinflation?',\n    options: ['Prices doubled every 15 hours', 'Prices tripled every day', 'Inflation reached 1000% per year', 'The currency became worthless in one week'],\n    correct: 0\n  },\n  {\n    q: 'Which is NOT a function of money?',\n    options: ['Medium of exchange', 'Unit of account', 'Store of wealth', 'Source of income'],\n    correct: 3\n  },\n  {\n    q: 'Credit and debit cards are classified as:',\n    options: ['Currency', 'Bank money', 'Money substitutes', 'Near money'],\n    correct: 2\n  },\n  {\n    q: 'Demand-pull inflation is caused by:',\n    options: ['Rising input costs', 'Excessive aggregate demand', 'High unemployment', 'Trade deficits'],\n    correct: 1\n  },\n];\n\nconst quizContainer = document.getElementById('quiz-container');\nlet userAnswers = new Array(quizData.length).fill(-1);\n\nfunction renderQuiz() {\n  quizContainer.innerHTML = '';\n  quizData.forEach((item, idx) => {\n    const div = document.createElement('div');\n    div.className = 'quiz-question';\n    div.innerHTML = `<h4>${idx + 1}. ${item.q}</h4>`;\n    item.options.forEach((opt, oi) => {\n      const btn = document.createElement('button');\n      btn.className = 'quiz-option';\n      btn.textContent = opt;\n      btn.dataset.qIdx = idx;\n      btn.dataset.optIdx = oi;\n      btn.addEventListener('click', () => selectOption(idx, oi));\n      div.appendChild(btn);\n    });\n    const fb = document.createElement('div');\n    fb.className = 'quiz-feedback';\n    fb.id = 'quiz-fb-' + idx;\n    div.appendChild(fb);\n    quizContainer.appendChild(div);\n  });\n}\n\nfunction selectOption(qIdx, optIdx) {\n  userAnswers[qIdx] = optIdx;\n  const qDiv = quizContainer.children[qIdx];\n  qDiv.querySelectorAll('.quiz-option').forEach((btn, i) => {\n    btn.classList.toggle('selected', i === optIdx);\n    btn.classList.remove('correct', 'wrong');\n  });\n}\n\nfunction checkQuiz() {\n  let score = 0;\n  quizData.forEach((item, idx) => {\n    const fb = document.getElementById('quiz-fb-' + idx);\n    const qDiv = quizContainer.children[idx];\n    const opts = qDiv.querySelectorAll('.quiz-option');\n    opts.forEach((btn, i) => {\n      btn.classList.remove('correct', 'wrong');\n      if (i === item.correct) btn.classList.add('correct');\n      else if (i === userAnswers[idx] && i !== item.correct) btn.classList.add('wrong');\n    });\n    const isCorrect = userAnswers[idx] === item.correct;\n    if (isCorrect) score++;\n    fb.innerHTML = isCorrect ? '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg> Correct!' : `❌ Incorrect. The answer was: ${item.options[item.correct]}`;\n    fb.className = 'quiz-feedback show';\n  });\n  document.getElementById('quiz-score').innerHTML =\n    `<strong>${score}</strong> / ${quizData.length} correct (${Math.round(score/quizData.length*100)}%)`;\n}\n\nfunction resetQuiz() {\n  userAnswers = new Array(quizData.length).fill(-1);\n  renderQuiz();\n  document.getElementById('quiz-score').innerHTML = '';\n}\n\nrenderQuiz();\n</script>\n\n\n</body>\n</html>",
    "8": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<canvas id=\"particles-canvas\"></canvas>\n<div id=\"progress-bar\"></div>\n<button id=\"back-to-top\" onclick=\"window.scrollTo({top:0,behavior:'smooth'})\">↑</button>\n\n<!-- HERO -->\n<section class=\"hero\">\n  <div class=\"badge\">Lesson 8</div>\n  <h1>Market Failure, Government &amp; Public Finance</h1>\n  <p>Understanding why markets fail and how government intervention shapes economic outcomes</p>\n</section>\n\n<div class=\"container\">\n\n\n\n<!-- FLASHCARDS -->\n<section>\n  <h2 class=\"section-title reveal\">Key Terms</h2>\n  <div class=\"flashcard-grid reveal\">\n    <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n      <div class=\"flashcard-inner\">\n        <div class=\"flashcard-front\">Market Failure</div>\n        <div class=\"flashcard-back\">Inability of the market mechanism to distribute scarce resources toward society's wellbeing</div>\n      </div>\n    </div>\n    <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n      <div class=\"flashcard-inner\">\n        <div class=\"flashcard-front\">Externality</div>\n        <div class=\"flashcard-back\">Non-compensated benefit or cost to third parties from production or consumption</div>\n      </div>\n    </div>\n    <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n      <div class=\"flashcard-inner\">\n        <div class=\"flashcard-front\">Fiscal Policy</div>\n        <div class=\"flashcard-back\">Changes in government expenditure, revenue, and borrowing to achieve macroeconomic objectives</div>\n      </div>\n    </div>\n    <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n      <div class=\"flashcard-inner\">\n        <div class=\"flashcard-front\">Public Goods</div>\n        <div class=\"flashcard-back\">Non-excludable and non-rival goods (national defense, street lights, lighthouses)</div>\n      </div>\n    </div>\n    <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n      <div class=\"flashcard-inner\">\n        <div class=\"flashcard-front\">Quasi-Public Goods</div>\n        <div class=\"flashcard-back\">Non-rival until capacity is reached, but excludable (highways, museums)</div>\n      </div>\n    </div>\n    <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n      <div class=\"flashcard-inner\">\n        <div class=\"flashcard-front\">Direct Tax</div>\n        <div class=\"flashcard-back\">Tax where the burden cannot be shifted (income tax, property tax)</div>\n      </div>\n    </div>\n    <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n      <div class=\"flashcard-inner\">\n        <div class=\"flashcard-front\">Indirect Tax</div>\n        <div class=\"flashcard-back\">Tax where the burden can be shifted (sales tax, VAT, customs duty)</div>\n      </div>\n    </div>\n    <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n      <div class=\"flashcard-inner\">\n        <div class=\"flashcard-front\">Government Failure</div>\n        <div class=\"flashcard-back\">When government intervention leads to worse outcomes due to rigidities, political self-interest, or imperfect information</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- MARKET FAILURE -->\n<section>\n  <h2 class=\"section-title reveal\">Market Failure</h2>\n  <div class=\"card reveal\">\n    <p><strong>Definition:</strong> The inability of the market mechanism to distribute scarce resources toward society's wellbeing.</p>\n    <h3>Reasons for Market Failure</h3>\n    <ul>\n      <li><strong>Inefficiency of resource allocation</strong> — markets fail to produce the socially optimal quantity of goods</li>\n      <li><strong>Macroeconomic instability</strong> — fluctuations in aggregate demand cause inflation and unemployment</li>\n      <li><strong>Unequal income distribution</strong> — markets produce inequitable outcomes based on labour, education, property, and luck</li>\n    </ul>\n  </div>\n</section>\n\n<!-- INEFFICIENCY OF RESOURCE ALLOCATION -->\n<section>\n  <h2 class=\"section-title reveal\">Inefficiency of Resource Allocation</h2>\n  <div class=\"card reveal\">\n    <ul>\n      <li>Non-provision of public goods</li>\n      <li>Non-optimal consumption of quasi-public goods</li>\n      <li>Non-provision of welfare goods optimally</li>\n      <li>Provision of demerit goods</li>\n      <li>Over-utilization of common resources</li>\n      <li>Externalities</li>\n      <li>Imperfect competition / monopoly</li>\n      <li>Imperfect information</li>\n    </ul>\n  </div>\n\n  <h3 class=\"reveal\">Classification of Goods</h3>\n  <div class=\"table-wrapper reveal\">\n    <table>\n      <thead>\n        <tr>\n          <th>Type</th>\n          <th>Excludable</th>\n          <th>Rival</th>\n          <th>Examples</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr><td><strong>Public goods</strong></td><td>No</td><td>No</td><td>National defense, street lights, lighthouses</td></tr>\n        <tr><td><strong>Global public goods</strong></td><td>No</td><td>No</td><td>Knowledge, financial stability, world peace</td></tr>\n        <tr><td><strong>Quasi-public goods</strong></td><td>Yes</td><td>No (until capacity)</td><td>Highways, museums</td></tr>\n        <tr><td><strong>Common goods</strong></td><td>No</td><td>Yes</td><td>Fisheries, grasslands, atmosphere</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <h3 class=\"reveal\">Comparison: Public vs Quasi-Public vs Common Goods</h3>\n  <div class=\"table-wrapper reveal\">\n    <table class=\"comparison-table\">\n      <thead>\n        <tr>\n          <th>Feature</th>\n          <th>Public Goods</th>\n          <th>Quasi-Public Goods</th>\n          <th>Common Goods</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr><td>Excludability</td><td>Non-excludable</td><td>Excludable</td><td>Non-excludable</td></tr>\n        <tr><td>Rivalry</td><td>Non-rival</td><td>Non-rival until capacity</td><td>Rival</td></tr>\n        <tr><td>Free-rider problem</td><td>Yes</td><td>Possible</td><td>Yes</td></tr>\n        <tr><td>Tragedy of commons</td><td>No</td><td>No</td><td>Yes</td></tr>\n        <tr><td>Examples</td><td>Defense, street lights</td><td>Highways, museums</td><td>Fisheries, grasslands</td></tr>\n        <tr><td>Provider</td><td>Government</td><td>Government or private</td><td>Common pool</td></tr>\n      </tbody>\n    </table>\n  </div>\n</section>\n\n<!-- MACROECONOMIC INSTABILITY -->\n<section>\n  <h2 class=\"section-title reveal\">Macroeconomic Instability</h2>\n  <div class=\"card reveal\">\n    <ul>\n      <li><strong>Fluctuations in aggregate demand</strong>, especially private investment</li>\n      <li><strong>Inflation</strong> — rising general price level reduces purchasing power</li>\n      <li><strong>Unemployment</strong> — resources, especially labour, remain idle</li>\n    </ul>\n    <p>Markets alone cannot self-correct quickly; government intervention through fiscal and monetary policy is often required to stabilize the economy.</p>\n  </div>\n</section>\n\n<!-- UNEQUAL DISTRIBUTION -->\n<section>\n  <h2 class=\"section-title reveal\">Unequal Distribution of Income</h2>\n  <div class=\"card reveal\">\n    <p>Income inequality depends on:</p>\n    <div class=\"grid-3\">\n      <div><span class=\"tag tag-purple\">Labour</span></div>\n      <div><span class=\"tag tag-purple\">Education</span></div>\n      <div><span class=\"tag tag-purple\">Property</span></div>\n      <div><span class=\"tag tag-purple\">Factor prices</span></div>\n      <div><span class=\"tag tag-purple\">Entrepreneurial skills</span></div>\n      <div><span class=\"tag tag-purple\">Luck</span></div>\n    </div>\n  </div>\n</section>\n\n<!-- ROLE OF GOVERNMENT -->\n<section>\n  <h2 class=\"section-title reveal\">Role of Government</h2>\n  <div class=\"grid-2\">\n    <div class=\"card reveal\">\n      <h3>1. Efficient Allocation</h3>\n      <p>Providing public goods, quasi-public goods, welfare goods, and limiting demerit goods.</p>\n    </div>\n    <div class=\"card reveal\">\n      <h3>2. Fair Distribution</h3>\n      <p>Redistribution of income and wealth, limits on wealth accumulation, land reform.</p>\n    </div>\n    <div class=\"card reveal\">\n      <h3>3. Macroeconomic Stability</h3>\n      <p>Managing aggregate demand to control inflation and unemployment.</p>\n    </div>\n    <div class=\"card reveal\">\n      <h3>4. Growth &amp; Development</h3>\n      <p>Promoting economic growth and sustainable development through policy.</p>\n    </div>\n  </div>\n</section>\n\n<!-- GOVERNMENT FAILURE -->\n<section>\n  <h2 class=\"section-title reveal\">Government Failure</h2>\n  <div class=\"card reveal\">\n    <p>Government intervention can sometimes lead to worse outcomes than market failure itself.</p>\n    <div class=\"grid-2\" style=\"margin-top:12px;\">\n      <div><span class=\"tag tag-amber\">Rigidities</span></div>\n      <div><span class=\"tag tag-amber\">Political self-interest</span></div>\n      <div><span class=\"tag tag-amber\">Short-term vision</span></div>\n      <div><span class=\"tag tag-amber\">Imperfect information</span></div>\n      <div><span class=\"tag tag-amber\">Unfavorable incentive effects</span></div>\n      <div><span class=\"tag tag-amber\">Hidden economics</span></div>\n      <div><span class=\"tag tag-amber\">Increased administration cost</span></div>\n    </div>\n  </div>\n</section>\n\n<!-- EXTERNALITIES -->\n<section>\n  <h2 class=\"section-title reveal\">Externalities</h2>\n  <div class=\"card reveal\">\n    <p><strong>Externalities:</strong> Non-compensated benefits or costs to third parties arising from production or consumption.</p>\n    <h3>4 Types of Externalities</h3>\n  </div>\n  <div class=\"grid-2\">\n    <div class=\"card reveal\">\n      <h3>Negative Production</h3>\n      <p>Pollution from coal plants, pesticide runoff</p>\n      <span class=\"tag tag-pink\">Remedy:</span> Environmental taxes, licenses, fines\n    </div>\n    <div class=\"card reveal\">\n      <h3>Positive Production</h3>\n      <p>Train station shelter, new technology spillovers</p>\n      <span class=\"tag tag-pink\">Remedy:</span> Subsidies, internalization\n    </div>\n    <div class=\"card reveal\">\n      <h3>Negative Consumption</h3>\n      <p>Smoking, loud music, noise pollution</p>\n      <span class=\"tag tag-pink\">Remedy:</span> Taxes, fines, regulation\n    </div>\n    <div class=\"card reveal\">\n      <h3>Positive Consumption</h3>\n      <p>Good architecture, education, healthy diet</p>\n      <span class=\"tag tag-pink\">Remedy:</span> Subsidies, public provision\n    </div>\n  </div>\n  <div class=\"card reveal\">\n    <h3>Remedies for Externalities</h3>\n    <div class=\"grid-3\">\n      <span class=\"tag tag-purple\">Environmental taxes</span>\n      <span class=\"tag tag-purple\">Licenses</span>\n      <span class=\"tag tag-purple\">Subsidies</span>\n      <span class=\"tag tag-purple\">Internalization</span>\n      <span class=\"tag tag-purple\">Bargaining (Coase)</span>\n      <span class=\"tag tag-purple\">Fines</span>\n    </div>\n  </div>\n</section>\n\n<!-- FISCAL POLICY -->\n<section>\n  <h2 class=\"section-title reveal\">Fiscal Policy</h2>\n  <div class=\"card reveal\">\n    <p><strong>Definition:</strong> Changes in government expenditure, revenue, and borrowing to achieve macroeconomic objectives.</p>\n  </div>\n\n  <h3 class=\"reveal\">Fiscal vs Monetary Policy</h3>\n  <div class=\"table-wrapper reveal\">\n    <table class=\"comparison-table\">\n      <thead>\n        <tr><th>Feature</th><th>Fiscal Policy</th><th>Monetary Policy</th></tr>\n      </thead>\n      <tbody>\n        <tr><td>Who controls?</td><td>Government (treasury)</td><td>Central bank</td></tr>\n        <tr><td>Tools</td><td>Taxes, spending, borrowing</td><td>Interest rates, money supply</td></tr>\n        <tr><td>Focus</td><td>Budget balance, aggregate demand</td><td>Price stability, credit conditions</td></tr>\n        <tr><td>Implementation speed</td><td>Slower (legislative)</td><td>Faster (monetary authority)</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <h3 class=\"reveal\">Types of Fiscal Policy</h3>\n  <div class=\"table-wrapper reveal\">\n    <table>\n      <thead>\n        <tr><th>Type</th><th>Condition</th><th>Effect</th></tr>\n      </thead>\n      <tbody>\n        <tr><td><strong>Expansionary</strong></td><td>G &gt; R</td><td>Stimulates aggregate demand, reduces unemployment</td></tr>\n        <tr><td><strong>Contractionary</strong></td><td>G &lt; R</td><td>Cools down economy, reduces inflation</td></tr>\n        <tr><td><strong>Neutral</strong></td><td>G = R</td><td>Balanced budget, no net stimulus</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <h3 class=\"reveal\">Fiscal Instruments</h3>\n  <div class=\"grid-3 reveal\">\n    <div class=\"card\" style=\"margin:0;\"><span class=\"tag tag-purple\">Taxes</span><p style=\"margin-top:8px;\">Direct &amp; indirect taxes to influence spending</p></div>\n    <div class=\"card\" style=\"margin:0;\"><span class=\"tag tag-purple\">Expenditure</span><p style=\"margin-top:8px;\">Government spending on goods, services, transfers</p></div>\n    <div class=\"card\" style=\"margin:0;\"><span class=\"tag tag-purple\">Public Debt</span><p style=\"margin-top:8px;\">Borrowing to finance deficits</p></div>\n  </div>\n</section>\n\n<!-- GOVERNMENT REVENUE -->\n<section>\n  <h2 class=\"section-title reveal\">Government Revenue</h2>\n  <div class=\"card reveal\">\n    <p><strong>Two main sources:</strong> Tax revenue (direct &amp; indirect) and Non-tax revenue (fees, fines, dividends).</p>\n  </div>\n\n  <h3 class=\"reveal\">Objectives of Taxation</h3>\n  <div class=\"card reveal\">\n    <div class=\"grid-3\">\n      <span class=\"tag tag-purple\">Raise revenue</span>\n      <span class=\"tag tag-purple\">Redistribute income</span>\n      <span class=\"tag tag-purple\">Stabilize economy</span>\n      <span class=\"tag tag-purple\">Discourage demerit goods</span>\n      <span class=\"tag tag-purple\">Protect domestic industries</span>\n      <span class=\"tag tag-purple\">Correct externalities</span>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">Principles of Taxation</h3>\n  <div class=\"grid-2 reveal\">\n    <div class=\"card\" style=\"margin:0;\">\n      <span class=\"tag tag-amber\">Equity</span>\n      <p style=\"margin-top:6px;\"><strong>Horizontal:</strong> Equal treatment of equals<br><strong>Vertical:</strong> Unequal treatment of unequals</p>\n    </div>\n    <div class=\"card\" style=\"margin:0;\">\n      <span class=\"tag tag-amber\">Certainty</span>\n      <p style=\"margin-top:6px;\">Taxpayers should know when, how, and how much</p>\n    </div>\n    <div class=\"card\" style=\"margin:0;\">\n      <span class=\"tag tag-amber\">Economical</span>\n      <p style=\"margin-top:6px;\">Cost of collection should be low relative to revenue</p>\n    </div>\n    <div class=\"card\" style=\"margin:0;\">\n      <span class=\"tag tag-amber\">Efficiency</span>\n      <p style=\"margin-top:6px;\">Minimize distortion to economic decisions</p>\n    </div>\n    <div class=\"card\" style=\"margin:0;\">\n      <span class=\"tag tag-amber\">Convenience</span>\n      <p style=\"margin-top:6px;\">Ease of payment for taxpayers</p>\n    </div>\n    <div class=\"card\" style=\"margin:0;\">\n      <span class=\"tag tag-amber\">Flexibility</span>\n      <p style=\"margin-top:6px;\">Ability to adjust to changing conditions</p>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">Benefit vs Ability-to-Pay Principle</h3>\n  <div class=\"grid-2 reveal\">\n    <div class=\"card\" style=\"margin:0;\">\n      <h3>Benefit Principle</h3>\n      <p>Taxes paid should reflect benefits received from public services.</p>\n    </div>\n    <div class=\"card\" style=\"margin:0;\">\n      <h3>Ability-to-Pay Principle</h3>\n      <p>Taxes should be based on the taxpayer's capacity to pay, regardless of benefits received.</p>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">Direct vs Indirect Taxes</h3>\n  <div class=\"table-wrapper reveal\">\n    <table class=\"comparison-table\">\n      <thead>\n        <tr><th>Feature</th><th>Direct Tax</th><th>Indirect Tax</th></tr>\n      </thead>\n      <tbody>\n        <tr><td>Burden</td><td>Cannot be shifted</td><td>Can be shifted to consumers</td></tr>\n        <tr><td>Examples</td><td>Income tax, property tax</td><td>Sales tax, VAT, customs duty</td></tr>\n        <tr><td>Collection</td><td>Directly from individual/entity</td><td>Collected via intermediaries</td></tr>\n        <tr><td>Progressivity</td><td>Often progressive</td><td>Often regressive</td></tr>\n        <tr><td>Visibility</td><td>Highly visible</td><td>Less visible to consumer</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <h3 class=\"reveal\">Tax Sources</h3>\n  <div class=\"grid-2 reveal\">\n    <div class=\"card\" style=\"margin:0;\">\n      <ul>\n        <li><strong>Income</strong> — personal &amp; corporate</li>\n        <li><strong>Consumption</strong> — sales tax, VAT, excise</li>\n      </ul>\n    </div>\n    <div class=\"card\" style=\"margin:0;\">\n      <ul>\n        <li><strong>Wealth</strong> — property, inheritance, wealth tax</li>\n        <li><strong>Import / Export</strong> — tariffs, customs duties</li>\n      </ul>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">Tax Rates</h3>\n  <div class=\"table-wrapper reveal\">\n    <table class=\"comparison-table\">\n      <thead>\n        <tr><th>Type</th><th>Definition</th><th>Example</th><th>Graph</th></tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td><strong class=\"tag tag-purple\">Progressive</strong></td>\n          <td>Tax rate increases as tax base increases</td>\n          <td>Income tax brackets (10%, 20%, 30%)</td>\n          <td>Upward-sloping curve</td>\n        </tr>\n        <tr>\n          <td><strong class=\"tag tag-amber\">Proportional</strong></td>\n          <td>Fixed tax rate regardless of tax base</td>\n          <td>Flat tax (e.g. 15% on all income)</td>\n          <td>Horizontal line</td>\n        </tr>\n        <tr>\n          <td><strong class=\"tag tag-pink\">Regressive</strong></td>\n          <td>Tax rate decreases as tax base increases</td>\n          <td>Sales tax (poor spend higher % of income)</td>\n          <td>Downward-sloping curve</td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  <h3 class=\"reveal\">Economic Effects of Taxation</h3>\n  <div class=\"grid-3 reveal\">\n    <span class=\"tag tag-purple\">Investment</span>\n    <span class=\"tag tag-purple\">Production</span>\n    <span class=\"tag tag-purple\">Consumption</span>\n    <span class=\"tag tag-purple\">Price level</span>\n    <span class=\"tag tag-purple\">International trade</span>\n    <span class=\"tag tag-purple\">Income distribution</span>\n    <span class=\"tag tag-purple\">Savings</span>\n  </div>\n\n  <!-- TAX CALCULATOR -->\n  <div class=\"card reveal\" style=\"margin-top:20px;\">\n    <h3>Tax Rate Calculator</h3>\n    <div class=\"tax-calc\">\n      <div>\n        <label>Income / Base Amount ($)</label>\n        <input type=\"number\" id=\"taxBase\" value=\"50000\" min=\"0\">\n      </div>\n      <div>\n        <label>Tax System</label>\n        <select id=\"taxSystem\">\n          <option value=\"progressive\">Progressive</option>\n          <option value=\"proportional\" selected=\"\">Proportional (15%)</option>\n          <option value=\"regressive\">Regressive</option>\n        </select>\n      </div>\n      <div>\n        <div class=\"result-box\">\n          <div class=\"sub\">Tax Payable</div>\n          <div class=\"amount\" id=\"taxAmount\">$7,500</div>\n        </div>\n      </div>\n      <div>\n        <div class=\"result-box\">\n          <div class=\"sub\">Effective Tax Rate</div>\n          <div class=\"amount\" id=\"taxRate\">15.00%</div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- GOVERNMENT EXPENDITURE -->\n<section>\n  <h2 class=\"section-title reveal\">Government Expenditure</h2>\n  <div class=\"card reveal\">\n    <h3>Types of Expenditure</h3>\n    <div class=\"grid-2\">\n      <div>\n        <h4>Recurrent</h4>\n        <ul>\n          <li>Wages &amp; salaries</li>\n          <li>Subsidies</li>\n          <li>Pensions</li>\n          <li>Transportation costs</li>\n        </ul>\n      </div>\n      <div>\n        <h4>Capital Investment</h4>\n        <ul>\n          <li>Machinery &amp; equipment</li>\n          <li>Buildings &amp; infrastructure</li>\n          <li>Highways &amp; bridges</li>\n        </ul>\n      </div>\n      <div>\n        <h4>Net Lending</h4>\n        <p>Loans given minus repayments received by the government.</p>\n      </div>\n    </div>\n  </div>\n\n  <h3 class=\"reveal\">Classification Schemes</h3>\n  <div class=\"grid-2 reveal\">\n    <div class=\"card\" style=\"margin:0;\">\n      <h3>Economic Classification</h3>\n      <ul>\n        <li>Interest payments</li>\n        <li>Current transfers (Samurdhi, pension, food subsidy, fertilizer subsidy, school materials)</li>\n        <li>Acquisition of real capital</li>\n        <li>Capital transfers</li>\n      </ul>\n    </div>\n    <div class=\"card\" style=\"margin:0;\">\n      <h3>Functional Classification</h3>\n      <ul>\n        <li>General public services</li>\n        <li>Defense</li>\n        <li>Education</li>\n        <li>Health</li>\n        <li>Social protection</li>\n        <li>Economic affairs</li>\n      </ul>\n    </div>\n  </div>\n\n  <div class=\"card reveal\">\n    <h3>Factors Affecting Government Expenditure</h3>\n    <div class=\"grid-3\">\n      <span class=\"tag tag-amber\">Population growth</span>\n      <span class=\"tag tag-amber\">Inflation</span>\n      <span class=\"tag tag-amber\">Welfare demands</span>\n      <span class=\"tag tag-amber\">Defense needs</span>\n      <span class=\"tag tag-amber\">Debt servicing</span>\n      <span class=\"tag tag-amber\">Political priorities</span>\n    </div>\n  </div>\n</section>\n\n<!-- GOVERNMENT BUDGET -->\n<section>\n  <h2 class=\"section-title reveal\">Government Budget</h2>\n  <div class=\"card reveal\">\n    <p><strong>Key documents:</strong> Appropriation Act, Supplementary Estimate, Vote on Account.</p>\n  </div>\n\n  <h3 class=\"reveal\">Budget Types</h3>\n  <div class=\"table-wrapper reveal\">\n    <table>\n      <thead>\n        <tr><th>Type</th><th>Condition</th><th>Outcome</th></tr>\n      </thead>\n      <tbody>\n        <tr><td><strong>Deficit Budget</strong></td><td>G &gt; R</td><td>Government borrows to cover shortfall</td></tr>\n        <tr><td><strong>Surplus Budget</strong></td><td>G &lt; R</td><td>Government saves or pays down debt</td></tr>\n        <tr><td><strong>Balanced Budget</strong></td><td>G = R</td><td>Revenue equals expenditure</td></tr>\n      </tbody>\n    </table>\n  </div>\n\n  <h3 class=\"reveal\">Budget Balance Formulas</h3>\n  <div class=\"grid-2 reveal\">\n    <div class=\"formula-box\">\n      <div class=\"label\">Balance of Current Account</div>\n      <div class=\"formula\">= Total Revenue − Recurrent Expenditure</div>\n    </div>\n    <div class=\"formula-box\">\n      <div class=\"label\">Overall Balance</div>\n      <div class=\"formula\">= Total Revenue − Total Expenditure</div>\n    </div>\n    <div class=\"formula-box\">\n      <div class=\"label\">Balance of Primary Account</div>\n      <div class=\"formula\">= Overall Balance − Interest Payments</div>\n    </div>\n    <div class=\"formula-box\">\n      <div class=\"label\">Net Cash Deficit</div>\n      <div class=\"formula\">= Overall Balance − Amortization Payments</div>\n    </div>\n  </div>\n\n  <div class=\"card reveal\">\n    <h3>Expansionary vs Contractionary Budgetary Policy</h3>\n    <div class=\"grid-2\">\n      <div>\n        <h4>Expansionary</h4>\n        <p>Increase spending / cut taxes to stimulate the economy during a recession.</p>\n      </div>\n      <div>\n        <h4>Contractionary</h4>\n        <p>Decrease spending / raise taxes to cool an overheating economy and control inflation.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- GOVERNMENT DEBT -->\n<section>\n  <h2 class=\"section-title reveal\">Government Debt</h2>\n  <div class=\"card reveal\">\n    <h3>Sources of Government Debt</h3>\n    <div class=\"grid-2\">\n      <div>\n        <h4>Domestic</h4>\n        <p><strong>Banking sector:</strong> Central bank, commercial banks</p>\n        <p><strong>Non-bank sector:</strong> NSB, EPF, Insurance companies</p>\n      </div>\n      <div>\n        <h4>Foreign</h4>\n        <p><strong>Project loans:</strong> Tied to specific projects</p>\n        <p><strong>Non-project loans:</strong> General budget support</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- QUIZ -->\n<section>\n  <h2 class=\"section-title reveal\">Check Your Understanding</h2>\n  <div class=\"card reveal\" id=\"quiz\">\n    <div id=\"quizContent\"></div>\n    <div class=\"quiz-result\" id=\"quizResult\"></div>\n    <div style=\"text-align:center;margin-top:16px;\">\n      <button class=\"btn\" onclick=\"submitQuiz()\">Submit Answers</button>\n      <button class=\"btn btn-outline\" onclick=\"resetQuiz()\" style=\"margin-left:8px;\">Reset</button>\n    </div>\n  </div>\n</section>\n\n</div>\n\n<script>\n// PARTICLES\nconst canvas = document.getElementById('particles-canvas');\nconst ctx = canvas.getContext('2d');\nlet particles = [];\nfunction resizeCanvas() { canvas.width = window.innerWidth; canvas.height = document.documentElement.scrollHeight; }\nresizeCanvas();\nwindow.addEventListener('resize', resizeCanvas);\nclass Particle {\n  constructor() {\n    this.x = Math.random() * canvas.width;\n    this.y = Math.random() * canvas.height;\n    this.size = Math.random() * 2 + 0.5;\n    this.speedX = (Math.random() - 0.5) * 0.5;\n    this.speedY = (Math.random() - 0.5) * 0.5;\n    this.opacity = Math.random() * 0.5 + 0.1;\n  }\n  update() {\n    this.x += this.speedX; this.y += this.speedY;\n    if (this.x < 0) this.x = canvas.width;\n    if (this.x > canvas.width) this.x = 0;\n    if (this.y < 0) this.y = canvas.height;\n    if (this.y > canvas.height) this.y = 0;\n  }\n  draw() {\n    ctx.beginPath(); ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n    ctx.fillStyle = `rgba(168,85,247,${this.opacity})`;\n    ctx.fill();\n  }\n}\nfor (let i = 0; i < 80; i++) particles.push(new Particle());\nfunction animateParticles() {\n  ctx.clearRect(0, 0, canvas.width, canvas.height);\n  particles.forEach(p => { p.update(); p.draw(); });\n  // draw connections\n  for (let i = 0; i < particles.length; i++) {\n    for (let j = i + 1; j < particles.length; j++) {\n      const dx = particles[i].x - particles[j].x;\n      const dy = particles[i].y - particles[j].y;\n      const dist = Math.sqrt(dx * dx + dy * dy);\n      if (dist < 120) {\n        ctx.beginPath();\n        ctx.moveTo(particles[i].x, particles[i].y);\n        ctx.lineTo(particles[j].x, particles[j].y);\n        ctx.strokeStyle = `rgba(168,85,247,${0.08 * (1 - dist/120)})`;\n        ctx.lineWidth = 0.5; ctx.stroke();\n      }\n    }\n  }\n  requestAnimationFrame(animateParticles);\n}\nanimateParticles();\n\n// SCROLL REVEAL\nconst observer = new IntersectionObserver(entries => {\n  entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); });\n}, { threshold: 0.08, rootMargin: '0px 0px -40px 0px' });\ndocument.querySelectorAll('.reveal').forEach(el => observer.observe(el));\n\n// PROGRESS BAR\nwindow.addEventListener('scroll', () => {\n  const h = document.documentElement.scrollHeight - window.innerHeight;\n  document.getElementById('progress-bar').style.width = (window.scrollY / h * 100) + '%';\n  document.getElementById('back-to-top').classList.toggle('show', window.scrollY > 400);\n});\n\n// repaint particles on scroll\nlet scrollTimer;\nwindow.addEventListener('scroll', () => {\n  clearTimeout(scrollTimer);\n  scrollTimer = setTimeout(() => { canvas.height = document.documentElement.scrollHeight; }, 300);\n});\n\n// TAX CALCULATOR\nfunction calcTax() {\n  const base = parseFloat(document.getElementById('taxBase').value) || 0;\n  const system = document.getElementById('taxSystem').value;\n  let tax = 0;\n  if (system === 'proportional') {\n    tax = base * 0.15;\n  } else if (system === 'progressive') {\n    if (base <= 10000) tax = base * 0.05;\n    else if (base <= 30000) tax = 10000 * 0.05 + (base - 10000) * 0.10;\n    else if (base <= 60000) tax = 10000 * 0.05 + 20000 * 0.10 + (base - 30000) * 0.20;\n    else tax = 10000 * 0.05 + 20000 * 0.10 + 30000 * 0.20 + (base - 60000) * 0.30;\n  } else if (system === 'regressive') {\n    if (base <= 20000) tax = base * 0.20;\n    else if (base <= 50000) tax = 20000 * 0.20 + (base - 20000) * 0.15;\n    else if (base <= 100000) tax = 20000 * 0.20 + 30000 * 0.15 + (base - 50000) * 0.10;\n    else tax = 20000 * 0.20 + 30000 * 0.15 + 50000 * 0.10 + (base - 100000) * 0.05;\n  }\n  document.getElementById('taxAmount').textContent = '$' + tax.toLocaleString('en-US', {maximumFractionDigits:0});\n  document.getElementById('taxRate').textContent = base > 0 ? (tax/base * 100).toFixed(2) + '%' : '0%';\n}\ndocument.getElementById('taxBase').addEventListener('input', calcTax);\ndocument.getElementById('taxSystem').addEventListener('change', calcTax);\ncalcTax();\n\n// QUIZ\nconst questions = [\n  {\n    q: 'What is the defining characteristic of a public good?',\n    options: ['Excludable and rival', 'Non-excludable and non-rival', 'Excludable and non-rival', 'Non-excludable and rival'],\n    answer: 1\n  },\n  {\n    q: 'Which of the following is an example of a negative production externality?',\n    options: ['Smoking in public', 'Pollution from a coal plant', 'Getting a good education', 'Listening to loud music'],\n    answer: 1\n  },\n  {\n    q: 'A tax where the rate increases as the tax base increases is called:',\n    options: ['Proportional tax', 'Regressive tax', 'Progressive tax', 'Indirect tax'],\n    answer: 2\n  },\n  {\n    q: 'What does \"Overall Balance\" equal?',\n    options: [\n      'Total Revenue \\u2212 Recurrent Expenditure',\n      'Total Revenue \\u2212 Total Expenditure',\n      'Overall Balance \\u2212 Interest Payments',\n      'Total Revenue \\u2212 Capital Expenditure'\n    ],\n    answer: 1\n  },\n  {\n    q: 'Which policy involves changes in government expenditure and taxation?',\n    options: ['Monetary policy', 'Trade policy', 'Fiscal policy', 'Exchange rate policy'],\n    answer: 2\n  },\n  {\n    q: 'Which is a direct tax?',\n    options: ['Sales tax', 'Value Added Tax', 'Income tax', 'Customs duty'],\n    answer: 2\n  },\n  {\n    q: 'The free-rider problem is most associated with:',\n    options: ['Private goods', 'Public goods', 'Common goods', 'Luxury goods'],\n    answer: 1\n  }\n];\n\nfunction renderQuiz() {\n  const container = document.getElementById('quizContent');\n  container.innerHTML = questions.map((q, i) => `\n    <div class=\"quiz-question\">\n      <div class=\"q-text\">${i+1}. ${q.q}</div>\n      <div class=\"quiz-options\" data-q=\"${i}\">\n        ${q.options.map((opt, j) => `\n          <button class=\"quiz-option\" data-q=\"${i}\" data-opt=\"${j}\" onclick=\"selectOption(${i},${j})\">${opt}</button>\n        `).join('')}\n      </div>\n    </div>\n  `).join('');\n}\n\nlet selected = {};\n\nfunction selectOption(qIdx, optIdx) {\n  const btns = document.querySelectorAll(`.quiz-option[data-q=\"${qIdx}\"]`);\n  btns.forEach(b => b.classList.remove('selected'));\n  btns[optIdx].classList.add('selected');\n  selected[qIdx] = optIdx;\n}\n\nfunction submitQuiz() {\n  let correct = 0;\n  const btns = document.querySelectorAll('.quiz-option');\n  btns.forEach(b => { b.disabled = true; b.classList.remove('correct','wrong'); });\n  questions.forEach((q, i) => {\n    const opts = document.querySelectorAll(`.quiz-option[data-q=\"${i}\"]`);\n    if (selected[i] !== undefined) {\n      if (selected[i] === q.answer) { opts[selected[i]].classList.add('correct'); correct++; }\n      else { opts[selected[i]].classList.add('wrong'); opts[q.answer].classList.add('correct'); }\n    } else {\n      opts[q.answer].classList.add('correct');\n    }\n  });\n  const result = document.getElementById('quizResult');\n  const pct = Math.round(correct / questions.length * 100);\n  result.className = 'quiz-result show ' + (pct >= 60 ? 'pass' : 'fail');\n  result.innerHTML = pct >= 60\n    ? `<strong>Passed!</strong> You got ${correct}/${questions.length} correct (${pct}%).`\n    : `<strong>Needs Improvement.</strong> You got ${correct}/${questions.length} correct (${pct}%). Review the material and try again.`;\n}\n\nfunction resetQuiz() {\n  selected = {};\n  const result = document.getElementById('quizResult');\n  result.className = 'quiz-result';\n  result.innerHTML = '';\n  renderQuiz();\n}\n\nrenderQuiz();\n</script>\n\n\n\n</body>\n</html>",
    "9": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"progress-container\">\n  <div class=\"progress-bar\" id=\"progressBar\"></div>\n</div>\n\n<canvas id=\"particles\"></canvas>\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">Lesson 9</div>\n  <h1>Protectionism &amp;<br>Foreign Investments</h1>\n  <p>Government trade restrictions, tariff and non-tariff barriers, and the role of foreign capital in economic development.</p>\n  <div class=\"hero-scroll\">↓</div>\n</section>\n\n<div class=\"container\">\n\n\n\n  <!-- 1. Protectionism -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🛡️</div>\n    <h2>Protectionism <span class=\"underline\"></span></h2>\n    <p><strong>Protectionism</strong> refers to government policies that restrict international trade in order to protect domestic industries from foreign competition.</p>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">📜</div>\n        <div class=\"label\">Definition</div>\n        <div class=\"desc\">Government policies restricting international trade to help domestic industries</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🏭</div>\n        <div class=\"label\">Goal</div>\n        <div class=\"desc\">Protect domestic producers from foreign competition</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">⚖️</div>\n        <div class=\"label\">Two Types</div>\n        <div class=\"desc\">Tariff Protectionism &amp; Non-Tariff Barriers</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 2. Tariff Protectionism -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💳</div>\n    <h2>Tariff Protectionism <span class=\"underline\"></span></h2>\n    <p>Tariff protectionism involves imposing <strong>tariffs (taxes)</strong> on imports and exports. The main objective is to protect domestic producers from foreign competition by making imported goods more expensive.</p>\n\n    <div class=\"workflow\">\n      <span class=\"step\">Foreign goods cheaper</span>\n      <span class=\"arrow\">→</span>\n      <span class=\"step\">Govt imposes tariff</span>\n      <span class=\"arrow\">→</span>\n      <span class=\"step\">Imported price increases</span>\n      <span class=\"arrow\">→</span>\n      <span class=\"step\">Domestic goods relatively cheaper</span>\n    </div>\n\n    <h3>Example</h3>\n    <div class=\"example-box\">\n      <div class=\"label\">💰 How Tariffs Make Domestic Products Cheaper Relative to Imports</div>\n      <p><span class=\"tag tag-purple\">Before Tariff</span></p>\n      <p>Domestic Product: <strong>LKR 3,000</strong> | Foreign Product: <strong>LKR 2,500</strong> → Foreign is cheaper</p>\n      <p style=\"margin-top:0.5rem;\"><span class=\"tag tag-pink\">After Tariff</span></p>\n      <p>Tariff on foreign product: <strong>+LKR 2,000</strong></p>\n      <p>Foreign Product becomes: <strong>LKR 4,500</strong></p>\n      <p style=\"margin-top:0.5rem; color: var(--accent2); font-weight:600;\">➡ Now domestic (LKR 3,000) is cheaper than foreign (LKR 4,500)</p>\n    </div>\n\n    <div class=\"note\">\n      Tariffs can be imposed on both imports <em>and</em> exports, though import tariffs are far more common for protectionist purposes.\n    </div>\n  </div>\n\n  <!-- 3. Nominal Rate of Protection -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🔢</div>\n    <h2>Nominal Rate of Protection <span class=\"underline\"></span></h2>\n    <p>The <strong>nominal rate of protection</strong> is the percentage tariff imposed on a product as it enters the country. It reflects the tariff rate applied to the final product without considering imported inputs.</p>\n\n    <div class=\"formula-box\">\n      Nominal Rate = (Tariff ÷ Original Price) × 100\n    </div>\n\n    <div class=\"example-box\">\n      <div class=\"label\">📍 Example</div>\n      <p><span class=\"tag tag-amber\">20% tariff on clothing</span></p>\n      <p>A 20% tariff on imported clothing means the nominal rate of protection is <strong>20%</strong>.</p>\n      <p style=\"font-size:0.9rem; color:var(--text-muted); margin-top:0.3rem;\">However, this does <em>not</em> show the actual protection received by the domestic producer, because the producer may use imported inputs/intermediate goods that are also subject to tariffs.</p>\n    </div>\n\n    <div class=\"note\">\n      ⚠️ <strong>Limitation:</strong> The nominal rate ignores the effect of tariffs on imported inputs used in domestic production. This is where the <strong>Effective Rate of Protection (ERP)</strong> becomes useful.\n    </div>\n  </div>\n\n  <!-- 4. Effective Rate of Protection -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📊</div>\n    <h2>Effective Rate of Protection <span class=\"underline\"></span></h2>\n    <p>The <strong>Effective Rate of Protection (ERP)</strong> measures the actual protection received by the domestic producer by considering tariffs on <em>both</em> the final product and imported inputs.</p>\n\n    <div class=\"formula-box\">\n      ERP = (Vi - Vo) / Vo × 100\n    </div>\n\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">Vi</div>\n        <div class=\"label\">Value Added After Tariff</div>\n        <div class=\"desc\">Value added when tariffs are applied to final product and inputs</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">Vo</div>\n        <div class=\"label\">Value Added Before Tariff</div>\n        <div class=\"desc\">Value added under free trade (no tariffs)</div>\n      </div>\n    </div>\n\n    <h3>Worked Example 1: Tariff on Final Product Only</h3>\n    <div class=\"example-box\">\n      <p><span class=\"tag tag-purple\">Given</span></p>\n      <p>Price of Shoes = <strong>Rs. 5,000</strong></p>\n      <p>Cost of Inputs = <strong>Rs. 3,000</strong></p>\n      <p>Value Added (Vo) = Rs. 5,000 - Rs. 3,000 = <strong>Rs. 2,000</strong></p>\n      <p style=\"margin-top:0.5rem;\"><span class=\"tag tag-pink\">After 10% Tariff on Final Product</span></p>\n      <p>New Imported Price = Rs. 5,000 + 10% = <strong>Rs. 5,500</strong></p>\n      <p>New Value Added (Vi) = Rs. 5,500 - Rs. 3,000 = <strong>Rs. 2,500</strong></p>\n      <p style=\"margin-top:0.5rem;\"><span class=\"tag tag-amber\">ERP Calculation</span></p>\n      <p class=\"math\">ERP = (2,500 - 2,000) / 2,000 × 100 = <strong>25%</strong></p>\n    </div>\n\n    <h3>Worked Example 2: Tariff on Both Final Product and Inputs</h3>\n    <div class=\"example-box\">\n      <p><span class=\"tag tag-purple\">Same as above + 5% tariff on inputs</span></p>\n      <p>Input cost after 5% tariff = Rs. 3,000 + 5% = <strong>Rs. 3,150</strong></p>\n      <p>New Value Added (Vi) = Rs. 5,500 - Rs. 3,150 = <strong>Rs. 2,350</strong></p>\n      <p style=\"margin-top:0.5rem;\"><span class=\"tag tag-amber\">ERP Calculation</span></p>\n      <p class=\"math\">ERP = (2,350 - 2,000) / 2,000 × 100 = <strong>17.5%</strong></p>\n    </div>\n\n    <h4>Key Determinants of ERP</h4>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">↗️</div>\n        <div class=\"label\">Higher ERP when</div>\n        <div class=\"desc\">Higher nominal tariff on final product</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">↘️</div>\n        <div class=\"label\">Higher ERP when</div>\n        <div class=\"desc\">Lower tariff on imported inputs</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">▲</div>\n        <div class=\"label\">Higher ERP when</div>\n        <div class=\"desc\">Higher % of imported inputs in production</div>\n      </div>\n    </div>\n\n    <h3>🧮 Interactive ERP Calculator</h3>\n    <div class=\"calc-box\">\n      <label>Final Product Price (Rs.)</label>\n      <input type=\"number\" id=\"erp-final-price\" value=\"5000\" step=\"100\">\n      <label>Cost of Imported Inputs (Rs.)</label>\n      <input type=\"number\" id=\"erp-input-cost\" value=\"3000\" step=\"100\">\n      <label>Tariff on Final Product (%)</label>\n      <input type=\"number\" id=\"erp-final-tariff\" value=\"10\" step=\"0.5\">\n      <label>Tariff on Imported Inputs (%)</label>\n      <input type=\"number\" id=\"erp-input-tariff\" value=\"0\" step=\"0.5\">\n      <button class=\"btn\" onclick=\"calcERP()\">Calculate ERP</button>\n      <div class=\"result\" id=\"erp-result\">ERP = 25.00%</div>\n    </div>\n\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🔢 Nominal Rate</div>\n        <ul>\n          <li>Tariff % on final product only</li>\n          <li>Ignores imported inputs</li>\n          <li>Simple tariff rate</li>\n          <li>Less accurate measure of protection</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📊 Effective Rate (ERP)</div>\n        <ul>\n          <li>Considers tariffs on final product + inputs</li>\n          <li>Accounts for imported inputs</li>\n          <li>Measures actual value added change</li>\n          <li>More accurate measure of protection</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 5. Non-Tariff Barriers -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🚧</div>\n    <h2>Non-Tariff Barriers <span class=\"underline\"></span></h2>\n    <p>Non-tariff barriers are trade restrictions <em>other than</em> tariffs used to restrict imports and protect domestic industries.</p>\n\n    <div class=\"grid-3\">\n      <div class=\"mini-card\">\n        <div class=\"emoji\">🎛️</div>\n        <div class=\"title\">Quotas</div>\n        <div class=\"desc\">Quantitative limits on imports</div>\n      </div>\n      <div class=\"mini-card\">\n        <div class=\"emoji\">💰</div>\n        <div class=\"title\">Subsidies / Incentives</div>\n        <div class=\"desc\">Financial support to domestic producers</div>\n      </div>\n      <div class=\"mini-card\">\n        <div class=\"emoji\">💩</div>\n        <div class=\"title\">Dumping</div>\n        <div class=\"desc\">Selling goods below cost abroad</div>\n      </div>\n      <div class=\"mini-card\">\n        <div class=\"emoji\">🚫</div>\n        <div class=\"title\">Voluntary Export Restraints</div>\n        <div class=\"desc\">Exporter \"voluntarily\" limits exports</div>\n      </div>\n      <div class=\"mini-card\">\n        <div class=\"emoji\">💱</div>\n        <div class=\"title\">Foreign Exchange Controls</div>\n        <div class=\"desc\">Limiting access to foreign currency</div>\n      </div>\n      <div class=\"mini-card\">\n        <div class=\"emoji\">🥩</div>\n        <div class=\"title\">Rationing</div>\n        <div class=\"desc\">Limiting quantity available to consumers</div>\n      </div>\n      <div class=\"mini-card\">\n        <div class=\"emoji\">⛔</div>\n        <div class=\"title\">Trade Embargoes</div>\n        <div class=\"desc\">Complete ban on trade with a country</div>\n      </div>\n      <div class=\"mini-card\">\n        <div class=\"emoji\">📋</div>\n        <div class=\"title\">Administrative / Technical Standards</div>\n        <div class=\"desc\">Complex regulations, inspections, certifications</div>\n      </div>\n    </div>\n\n    <h3>Comparison: Tariff vs Non-Tariff Barriers</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">💳 Tariff Barriers</div>\n        <ul>\n          <li>Taxes on imports/exports</li>\n          <li>Generates government revenue</li>\n          <li>Transparent and measurable</li>\n          <li>Price-based restriction</li>\n          <li>Easier to negotiate/reduce in trade agreements</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🚧 Non-Tariff Barriers</div>\n        <ul>\n          <li>Quantity/regulation-based restrictions</li>\n          <li>No direct revenue generation</li>\n          <li>Often opaque and complex</li>\n          <li>Quantity/standard-based restriction</li>\n          <li>Harder to quantify and negotiate</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 6. Foreign Investments -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🌍</div>\n    <h2>Foreign Investments <span class=\"underline\"></span></h2>\n    <p>Foreign investment refers to the flow of capital from one country to another for productive or financial purposes.</p>\n\n    <h3>Types of Foreign Investments</h3>\n\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">🏭</div>\n        <div class=\"label\">FDI (Foreign Direct Investment)</div>\n        <div class=\"desc\">Acquiring productive real assets with controlling ownership &amp; management involvement</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📈</div>\n        <div class=\"label\">Portfolio Investments</div>\n        <div class=\"desc\">Purchasing financial assets (shares, securities, commercial papers) without control/management</div>\n      </div>\n    </div>\n\n    <h3>Comparison: FDI vs Portfolio Investment</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🏭 FDI</div>\n        <ul>\n          <li>Long-term investment</li>\n          <li>Involves control &amp; management</li>\n          <li>Acquires real/physical assets</li>\n          <li>Less liquid</li>\n          <li>Transfers technology &amp; management skills</li>\n          <li>Creates employment directly</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📈 Portfolio Investment</div>\n        <ul>\n          <li>Short- to medium-term investment</li>\n          <li>No control or management</li>\n          <li>Acquires financial assets</li>\n          <li>Highly liquid</li>\n          <li>No technology transfer</li>\n          <li>No direct employment creation</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Recent FDI Trends in Sri Lanka</h3>\n    <div class=\"note\">\n      Sri Lanka has attracted FDI in sectors such as <strong>telecommunications, apparel, tourism, ports, and infrastructure</strong>. Key sources include China, India, Singapore, and the UK. The government has established the <strong>Board of Investment (BOI)</strong> to facilitate and promote FDI.\n    </div>\n\n    <h3>Effects of FDI</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">✅ Favourable Effects</div>\n        <ul>\n          <li>Improves resource allocation efficiency</li>\n          <li>Fills the resource gap (savings-investment gap)</li>\n          <li>Fills the foreign exchange gap</li>\n          <li>Helps solve BOP problems</li>\n          <li>Does not increase national debt</li>\n          <li>Brings new technology &amp; management techniques</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">❌ Unfavourable Effects</div>\n        <ul>\n          <li>Outflow of dividends, interest &amp; profits</li>\n          <li>May harm domestic economic activities</li>\n          <li>Loss of employment in domestic firms</li>\n          <li>Overconsumption of natural resources</li>\n          <li>Collapse of domestic industries due to competition</li>\n          <li>Tax revenue issues (transfer pricing)</li>\n          <li>Outflow of funds for domestic investors</li>\n          <li>Brain drain of skilled workers</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 7. Flashcards -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💡</div>\n    <h2>Key Terms <span class=\"underline\"></span></h2>\n    <p>Click each card to reveal the definition.</p>\n\n    <div class=\"flashcard-container\">\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🛡️ Protectionism\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Govt policies that restrict international trade to protect domestic industries from foreign competition\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            💳 Tariff\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            A tax imposed on imported (or exported) goods to make them more expensive relative to domestic products\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🔢 Nominal Rate of Protection\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Percentage tariff rate on a final product as it enters the country; ignores tariffs on imported inputs\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            📊 Effective Rate of Protection\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Measures actual protection considering tariffs on both the final product and imported inputs: ERP = (Vi - Vo) / Vo\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🚧 Non-Tariff Barriers\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Trade restrictions other than tariffs: quotas, subsidies, dumping, embargoes, standards, etc.\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🏭 Foreign Direct Investment\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Acquiring productive real assets with controlling ownership and management involvement in another country\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            📈 Portfolio Investment\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Purchasing financial assets (shares, securities) in another country without control or management\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            💩 Dumping\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Selling goods in a foreign market at a price below their cost of production or below domestic price\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 8. Quiz -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧰</div>\n    <h2>Test Your Knowledge <span class=\"underline\"></span></h2>\n\n    <div class=\"quiz-question\" data-q=\"1\">\n      <div class=\"q\">1. What is the main objective of protectionism?</div>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Protect domestic industries from foreign competition</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Increase foreign exchange reserves</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Promote free trade between nations</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Reduce government spending</button>\n      <div class=\"quiz-feedback\" data-feedback=\"1\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"2\">\n      <div class=\"q\">2. A domestic product costs LKR 3,000 and a foreign product costs LKR 2,500. After a tariff of LKR 2,000, what is the new price of the foreign product?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">LKR 2,500</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">LKR 3,000</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">LKR 4,500</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">LKR 5,000</button>\n      <div class=\"quiz-feedback\" data-feedback=\"2\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"3\">\n      <div class=\"q\">3. Which formula correctly represents the Effective Rate of Protection (ERP)?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">ERP = (Price - Cost) / Price × 100</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">ERP = (Vi - Vo) / Vo × 100</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">ERP = (Exports - Imports) / Total Trade × 100</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">ERP = Tariff / Original Price × 100</button>\n      <div class=\"quiz-feedback\" data-feedback=\"3\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"4\">\n      <div class=\"q\">4. The nominal rate of protection on shoes is 20% if:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">The ERP on shoes is 20%</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">A 20% tariff is imposed on imported shoes</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Inputs used for shoe production have a 20% tariff</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Shoe production increased by 20%</button>\n      <div class=\"quiz-feedback\" data-feedback=\"4\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"5\">\n      <div class=\"q\">5. Which of the following is a NON-tariff barrier?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Import tax</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Export duty</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Quota</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Customs tariff</button>\n      <div class=\"quiz-feedback\" data-feedback=\"5\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"6\">\n      <div class=\"q\">6. Which statement about FDI is TRUE?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">FDI involves only financial assets</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">FDI is highly liquid</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">FDI involves control and management of real assets</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">FDI does not create employment</button>\n      <div class=\"quiz-feedback\" data-feedback=\"6\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"7\">\n      <div class=\"q\">7. Shoes: Price = Rs. 5,000, Inputs = Rs. 3,000. A 10% tariff on final product and 5% on inputs. What is the ERP?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">25.0%</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">10.0%</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">20.0%</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">17.5%</button>\n      <div class=\"quiz-feedback\" data-feedback=\"7\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"8\">\n      <div class=\"q\">8. Which is an UNFAVOURABLE effect of FDI?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">New technology transfer</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Fills resource gap</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Outflow of dividends and profits</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Improves BOP position</button>\n      <div class=\"quiz-feedback\" data-feedback=\"8\"></div>\n    </div>\n  </div>\n\n</div>\n\n<script>\n  const canvas = document.getElementById('particles');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  class Particle {\n    constructor() {\n      this.reset();\n    }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.5;\n      this.speedY = (Math.random() - 0.5) * 0.5;\n      this.opacity = Math.random() * 0.5 + 0.1;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n      if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(168, 85, 247, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 80; i++) particles.push(new Particle());\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 150) {\n          ctx.beginPath();\n          ctx.strokeStyle = `rgba(168, 85, 247, ${0.06 * (1 - dist / 150)})`;\n          ctx.lineWidth = 0.5;\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  const sections = document.querySelectorAll('[data-section]');\n  function revealSections() {\n    sections.forEach(section => {\n      const rect = section.getBoundingClientRect();\n      if (rect.top < window.innerHeight - 80) {\n        section.classList.add('visible');\n      }\n    });\n  }\n  window.addEventListener('scroll', revealSections);\n  revealSections();\n\n  const progressBar = document.getElementById('progressBar');\n  window.addEventListener('scroll', () => {\n    const scrollTop = window.scrollY;\n    const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n    progressBar.style.width = (scrollTop / docHeight) * 100 + '%';\n  });\n\n  function checkAnswer(btn, isCorrect) {\n    const question = btn.closest('.quiz-question');\n    const options = question.querySelectorAll('.quiz-option');\n    const feedback = question.querySelector('.quiz-feedback');\n    options.forEach(opt => {\n      opt.disabled = true;\n      opt.style.cursor = 'not-allowed';\n      if (opt.dataset.correct === 'true') opt.classList.add('correct');\n    });\n    if (isCorrect) {\n      btn.classList.add('correct');\n      feedback.textContent = '\\u2705 Correct!';\n      feedback.className = 'quiz-feedback show correct';\n    } else {\n      btn.classList.add('wrong');\n      const correctBtn = question.querySelector('[data-correct=\"true\"]');\n      feedback.textContent = '\\u274C Incorrect. The answer was: ' + correctBtn.textContent;\n      feedback.className = 'quiz-feedback show wrong';\n    }\n  }\n\n  function calcERP() {\n    const finalPrice = parseFloat(document.getElementById('erp-final-price').value) || 0;\n    const inputCost = parseFloat(document.getElementById('erp-input-cost').value) || 0;\n    const finalTariff = parseFloat(document.getElementById('erp-final-tariff').value) || 0;\n    const inputTariff = parseFloat(document.getElementById('erp-input-tariff').value) || 0;\n\n    const newFinalPrice = finalPrice * (1 + finalTariff / 100);\n    const newInputCost = inputCost * (1 + inputTariff / 100);\n\n    const Vo = finalPrice - inputCost;\n    const Vi = newFinalPrice - newInputCost;\n\n    const resultEl = document.getElementById('erp-result');\n\n    if (Vo === 0) {\n      resultEl.textContent = 'Error: Value added is zero (final price = input cost)';\n      return;\n    }\n\n    const erp = ((Vi - Vo) / Vo) * 100;\n    resultEl.innerHTML = `ERP = <strong>${erp.toFixed(2)}%</strong><br><small style=\"font-size:0.8rem;color:var(--text-muted);font-weight:400;\">Vo = Rs. ${Vo.toFixed(2)}, Vi = Rs. ${Vi.toFixed(2)}</small>`;\n  }\n</script>\n\n\n\n\n</body>\n</html>",
    "10": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"progress-container\">\n  <div class=\"progress-bar\" id=\"progressBar\"></div>\n</div>\n\n<canvas id=\"particles\"></canvas>\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">Lesson 10</div>\n  <h1>Foreign Exchange &amp;<br>Balance of Payments</h1>\n  <p>Understanding currency markets, exchange rate systems, and international transaction accounting.</p>\n  <div class=\"hero-scroll\">↓</div>\n</section>\n\n<div class=\"container\">\n\n\n\n  <!-- 1. Foreign Exchange -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💱</div>\n    <h2>Foreign Exchange <span class=\"underline\"></span></h2>\n    <p><strong>Foreign exchange</strong> is the conversion of one country's currency into another country's currency. It is the backbone of international trade and finance.</p>\n\n    <h3>Foreign Exchange Market</h3>\n    <p>The institutional structure and arrangements through which foreign exchange is bought, sold, and transferred between countries.</p>\n\n    <h4>Participants</h4>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🏦</div><div class=\"label\">Commercial Banks</div><div class=\"desc\">Primary intermediaries in forex transactions</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💱</div><div class=\"label\">Forex Brokers</div><div class=\"desc\">Match buyers and sellers, earn commission</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏭</div><div class=\"label\">Business Firms</div><div class=\"desc\">Importers &amp; exporters needing currency</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏦</div><div class=\"label\">Central Bank</div><div class=\"desc\">Monitors and intervenes in forex market</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">👥</div><div class=\"label\">General Public</div><div class=\"desc\">Travelers, students, remittance receivers</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏰</div><div class=\"label\">Government</div><div class=\"desc\">Debt repayment, diplomatic payments</div></div>\n    </div>\n\n    <h4>Profiteers (Arbitrageurs)</h4>\n    <p>Participants who buy foreign exchange at a low price in one market and sell it at a higher price in another market, profiting from price differences across markets.</p>\n    <div class=\"formula-box\">Arbitrage: Buy Low → Sell High (across different markets)</div>\n  </div>\n\n  <!-- 2. Nominal Exchange Rate -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💳</div>\n    <h2>Nominal Exchange Rate <span class=\"underline\"></span></h2>\n    <p>The <strong>nominal exchange rate</strong> is the price of one country's currency expressed in terms of another country's currency. It is the rate at which two currencies can be exchanged.</p>\n\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">📇 Direct Quotation</div>\n        <ul>\n          <li><strong>Price quotation</strong></li>\n          <li>Foreign currency expressed in terms of domestic currency</li>\n          <li>Ex: <span class=\"highlight\">US$1 = SLKR 152</span></li>\n          <li>\"How many rupees per dollar?\"</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📈 Indirect Quotation</div>\n        <ul>\n          <li><strong>Volume quotation</strong></li>\n          <li>Domestic currency expressed in terms of foreign currency</li>\n          <li>Ex: <span class=\"highlight-pink\">SLKR 1 = US$0.0065</span></li>\n          <li>\"How many dollars per rupee?\"</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 3. Demand & Supply -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚖️</div>\n    <h2>Demand &amp; Supply of Foreign Exchange <span class=\"underline\"></span></h2>\n\n    <h3>Demand for Foreign Exchange (Dollar)</h3>\n    <p>Dollar is demanded when payments need to be made to foreign entities:</p>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">📦</div><div class=\"label\">Imports</div><div class=\"desc\">Paying for foreign goods &amp; services</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">✈️</div><div class=\"label\">Travel</div><div class=\"desc\">Foreign travel expenses</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💵</div><div class=\"label\">Debt Repayment</div><div class=\"desc\">Paying foreign loans &amp; interest</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤝</div><div class=\"label\">Transfers</div><div class=\"desc\">Grants, gifts, aid to abroad</div></div>\n    </div>\n    <p class=\"highlight-amber\" style=\"display:inline-block;padding:0.3rem 0.6rem;border-radius:6px;\">Inverse relationship: As rupee value of dollar ↑, quantity demanded ↓</p>\n\n    <h3>Supply of Foreign Exchange (Dollar)</h3>\n    <p>Dollar is supplied when receipts come from foreign entities:</p>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">📦</div><div class=\"label\">Exports</div><div class=\"desc\">Selling goods &amp; services abroad</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💰</div><div class=\"label\">Primary Income</div><div class=\"desc\">Interest, dividends, wages from abroad</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧑‍💰</div><div class=\"label\">Secondary Income</div><div class=\"desc\">Remittances, gifts, grants from abroad</div></div>\n    </div>\n    <p class=\"highlight-amber\" style=\"display:inline-block;padding:0.3rem 0.6rem;border-radius:6px;\">Positive relationship: As rupee value of dollar ↑, quantity supplied ↑</p>\n\n    <h3>Shift Factors</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">Demand Curve Shifts</div>\n        <ul>\n          <li>↑ Imports → Demand ↑ (right)</li>\n          <li>↑ Foreign travel → Demand ↑</li>\n          <li>↑ Debt repayment → Demand ↑</li>\n          <li>↑ Transfers abroad → Demand ↑</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">Supply Curve Shifts</div>\n        <ul>\n          <li>↑ Exports → Supply ↑ (right)</li>\n          <li>↑ Primary income receipts → Supply ↑</li>\n          <li>↑ Remittances → Supply ↑</li>\n          <li>↑ Foreign investment → Supply ↑</li>\n        </ul>\n      </div>\n    </div>\n\n    <h4>Exchange Rate Market Equilibrium</h4>\n    <div class=\"diagram-box\">\n      <pre>Exchange Rate\n(Rs/$)    |\n         |   S (Supply of $)\n         |    \\\n         |     \\\n    E ---|------\\-----\n         |       \\   D (Demand for $)\n         |        \\\n         +----------------- Quantity of $\n         0        Q\n      Equilibrium where D = S\n      </pre>\n    </div>\n    <p>The market exchange rate is determined by the intersection of demand for and supply of foreign currency. At equilibrium, the quantity demanded equals the quantity supplied.</p>\n  </div>\n\n  <!-- 4. Exchange Rate Systems -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏰</div>\n    <h2>Exchange Rate Systems <span class=\"underline\"></span></h2>\n\n    <div class=\"comparison three-col\" style=\"grid-template-columns:1fr 1fr 1fr;\">\n      <div class=\"left\">\n        <div class=\"header\">🔒 Fixed</div>\n        <ul>\n          <li>Determined by monetary authority</li>\n          <li>Based on gold standard (1890–1920)</li>\n          <li>Stable &amp; predictable</li>\n          <li>Requires large reserves</li>\n          <li>Vulnerable to speculative attacks</li>\n        </ul>\n      </div>\n      <div class=\"right\" style=\"background:rgba(236,72,153,0.08);\">\n        <div class=\"header\" style=\"color:var(--accent2);\">📈 Floating</div>\n        <ul>\n          <li>Determined by market D &amp; S</li>\n          <li>Automatically balances BOP</li>\n          <li>No reserve requirement</li>\n          <li>Volatile &amp; uncertain</li>\n          <li>Self-correcting mechanism</li>\n        </ul>\n      </div>\n      <div class=\"third-col\">\n        <div class=\"header\">⚖️ Managed Floating</div>\n        <ul>\n          <li>Combination of both systems</li>\n          <li>Central bank intervenes within a range</li>\n          <li>Crawling peg / Dirty float</li>\n          <li>Limited flexibility</li>\n          <li>Most countries use this today</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 5. Effective Exchange Rates -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📊</div>\n    <h2>Effective Exchange Rates <span class=\"underline\"></span></h2>\n\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">📊</div>\n        <div class=\"label\">NEER</div>\n        <div class=\"desc\">Nominal Effective Exchange Rate</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📈</div>\n        <div class=\"label\">REER</div>\n        <div class=\"desc\">Real Effective Exchange Rate</div>\n      </div>\n    </div>\n\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">NEER</div>\n        <ul>\n          <li>Weighted average of bilateral nominal exchange rates</li>\n          <li>Weights based on trade share with each partner</li>\n          <li>Measured in nominal terms (not adjusted for inflation)</li>\n          <li>NEER = Σ (w<sub>i</sub> × E<sub>i</sub>)</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">REER</div>\n        <ul>\n          <li>NEER adjusted for inflation differences</li>\n          <li>Measures real competitiveness</li>\n          <li>REER = NEER × (P<sub>domestic</sub> / P<sub>foreign</sub>)</li>\n          <li>REER ↑ = loss of competitiveness</li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"formula-box\">\n      NEER = Σ (Trade Weight<sub>i</sub> × Exchange Rate<sub>i</sub>)\n    </div>\n    <div class=\"formula-box\">\n      REER = NEER × (Domestic Price Level / Foreign Price Level)\n    </div>\n  </div>\n\n  <!-- 6. Changes in Exchange Rate -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📉📈</div>\n    <h2>Changes in Exchange Rate <span class=\"underline\"></span></h2>\n\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">📉 Under Fixed System</div>\n        <ul>\n          <li><strong>Devaluation:</strong> Official lowering of currency value by monetary authority</li>\n          <li><strong>Revaluation:</strong> Official increase in currency value by monetary authority</li>\n          <li>Government/monetary authority makes the decision</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📈 Under Floating System</div>\n        <ul>\n          <li><strong>Depreciation:</strong> Market-driven decrease in currency value</li>\n          <li><strong>Appreciation:</strong> Market-driven increase in currency value</li>\n          <li>Determined automatically by demand and supply forces</li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"comparison\" style=\"margin-top:1rem;\">\n      <div class=\"left\">\n        <div class=\"header\">Devaluation vs Depreciation</div>\n        <ul>\n          <li>Devaluation is <strong>official/policy-driven</strong></li>\n          <li>Occurs under <strong>fixed</strong> exchange rate system</li>\n          <li>Announced by central bank/government</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">Similarity</div>\n        <ul>\n          <li><strong>Both</strong> result in a currency becoming cheaper relative to foreign currencies</li>\n          <li>Both increase the domestic price of foreign currency</li>\n          <li>Both make exports cheaper and imports more expensive</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 7. Effects of Devaluation/Depreciation -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💵</div>\n    <h2>Effects of Devaluation / Depreciation <span class=\"underline\"></span></h2>\n\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">📈</div>\n        <div class=\"label\">Import Prices ↑</div>\n        <div class=\"desc\">Increases domestic price of imports, increases import expenditure</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">💰</div>\n        <div class=\"label\">Inflation ↑</div>\n        <div class=\"desc\">Can increase domestic inflation (imported inflation)</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">💵</div>\n        <div class=\"label\">Debt Service ↑</div>\n        <div class=\"desc\">Increases foreign debt service payments in local currency</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🌍</div>\n        <div class=\"label\">Tourism ↑</div>\n        <div class=\"desc\">Improves tourism earnings (cheaper for foreigners)</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🧑‍💰</div>\n        <div class=\"label\">Remittances ↑</div>\n        <div class=\"desc\">Improves worker remittances value in local currency</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📦</div>\n        <div class=\"label\">Trade Balance</div>\n        <div class=\"desc\">Discourages imports, encourages exports</div>\n      </div>\n    </div>\n\n    <h3>Marshall-Lerner Condition</h3>\n    <p>For a devaluation/depreciation to improve the trade balance:</p>\n    <div class=\"formula-box\">\n      |E<sub>X</sub>| + |E<sub>M</sub>| &gt; 1\n    </div>\n    <p style=\"font-size:0.9rem;color:var(--text-muted);\">Where E<sub>X</sub> = price elasticity of demand for exports, E<sub>M</sub> = price elasticity of demand for imports. If the sum of elasticities exceeds 1, devaluation improves the trade balance.</p>\n  </div>\n\n  <!-- 8. Effects of Appreciation/Revaluation -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📉</div>\n    <h2>Effects of Appreciation / Revaluation <span class=\"underline\"></span></h2>\n\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">📦</div>\n        <div class=\"label\">Import Prices ↓</div>\n        <div class=\"desc\">Decreases domestic price of imported goods</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📉</div>\n        <div class=\"label\">Inflation ↓</div>\n        <div class=\"desc\">Decreases inflation rate (if import-dependent economy)</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">💵</div>\n        <div class=\"label\">Foreign Debt ↓</div>\n        <div class=\"desc\">Decreases cost of repaying foreign debt in local currency</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">💰</div>\n        <div class=\"label\">Debt Value ↓</div>\n        <div class=\"desc\">Decreases foreign debt value expressed in domestic currency</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 9. Objectives of Devaluation -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🎯</div>\n    <h2>Objectives of Devaluation <span class=\"underline\"></span></h2>\n    <p>Why do countries intentionally devalue their currency?</p>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">📉</div><div class=\"label\">Minimize BOP Deficit</div><div class=\"desc\">Reduce long-term balance of payments deficit</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🚫</div><div class=\"label\">Discourage Imports</div><div class=\"desc\">Make imports more expensive, reduce demand</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📦</div><div class=\"label\">Encourage Exports</div><div class=\"desc\">Make exports cheaper, boost foreign demand</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧑‍💰</div><div class=\"label\">Encourage Remittances</div><div class=\"desc\">Increase value of foreign worker remittances</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💵</div><div class=\"label\">Improve FDI</div><div class=\"desc\">Attract foreign direct investment (cheaper assets)</div></div>\n    </div>\n  </div>\n\n  <!-- 10. Balance of Payments -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📋</div>\n    <h2>Balance of Payments (BOP) <span class=\"underline\"></span></h2>\n    <p>The <strong>Balance of Payments</strong> is a systematic statement of all economic transactions between residents of a country and non-residents over a specific period (usually a year).</p>\n\n    <h4>Key Features</h4>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">📄</div><div class=\"label\">Statement</div><div class=\"desc\">Records all international transactions</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🔄</div><div class=\"label\">Double Entry</div><div class=\"desc\">Every transaction recorded twice (credit &amp; debit)</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">⚖️</div><div class=\"label\">Balances</div><div class=\"desc\">BOP always balances: net = 0</div></div>\n    </div>\n\n    <h4>Recording Conventions</h4>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">📤 Debit (+)</div>\n        <ul>\n          <li>When asset/good/service flows <strong>FROM</strong> the country</li>\n          <li>Payments to non-residents</li>\n          <li>Examples: imports, foreign travel, debt repayment</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📥 Credit (−)</div>\n        <ul>\n          <li>When asset/good/service flows <strong>TO</strong> the country</li>\n          <li>Receipts from non-residents</li>\n          <li>Examples: exports, remittances, foreign investment</li>\n        </ul>\n      </div>\n    </div>\n\n    <div class=\"formula-box gradient-text\"><span>Total Debits = Total Credits ⇒ BOP always balances to zero</span></div>\n  </div>\n\n  <!-- 11. Structure of BOP -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏢</div>\n    <h2>Structure of BOP <span class=\"underline\"></span></h2>\n\n    <p>The Balance of Payments has three main accounts:</p>\n\n    <div class=\"comparison three-col\" style=\"grid-template-columns:1fr 1fr 1fr;\">\n      <div class=\"left\">\n        <div class=\"header\">💳 Current Account</div>\n        <ul>\n          <li>Goods (Trade balance)</li>\n          <li>Services</li>\n          <li>Goods &amp; Services</li>\n          <li>Primary Income</li>\n          <li>Secondary Income</li>\n        </ul>\n      </div>\n      <div class=\"right\" style=\"background:rgba(236,72,153,0.08);\">\n        <div class=\"header\" style=\"color:var(--accent2);\">🏛️ Capital Account</div>\n        <ul>\n          <li>Non-produced, non-monetary assets</li>\n          <li>Licenses, leases</li>\n          <li>Brand names, patents</li>\n          <li>Royalties</li>\n        </ul>\n      </div>\n      <div class=\"third-col\">\n        <div class=\"header\">💰 Financial Account</div>\n        <ul>\n          <li>Direct investments</li>\n          <li>Portfolio investments</li>\n          <li>Financial derivatives</li>\n          <li>Other investments</li>\n          <li>Foreign reserve assets</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Current Account in Detail</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">📦</div><div class=\"label\">Goods Account</div><div class=\"desc\">Trade balance = Exports − Imports</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">✈️</div><div class=\"label\">Services Account</div><div class=\"desc\">Transport, travel, financial, telecom, insurance</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📊</div><div class=\"label\">Goods &amp; Services</div><div class=\"desc\">Goods balance + Services balance</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💰</div><div class=\"label\">Primary Income</div><div class=\"desc\">Interest, wages, dividends from abroad</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤝</div><div class=\"label\">Secondary Income</div><div class=\"desc\">Transfers, remittances, gifts, grants</div></div>\n    </div>\n\n    <h3>Worked Examples</h3>\n\n    <div class=\"diagram-box\" style=\"text-align:left;\">\n      <strong style=\"color:var(--accent);\">Example 1: Trade Balance</strong>\n      <div class=\"diagram-flow\">\n        <div class=\"box\">Exports = $500M</div>\n        <div class=\"arrow\">−</div>\n        <div class=\"box\">Imports = $700M</div>\n        <div class=\"arrow\">=</div>\n        <div class=\"result\" style=\"color:#d63031;border-color:#d63031;\">Trade Balance = −$200M (Deficit)</div>\n      </div>\n\n      <strong style=\"color:var(--accent);margin-top:1rem;display:block;\">Example 2: Services Balance</strong>\n      <div class=\"diagram-flow\">\n        <div class=\"box\">Services Exports = $300M</div>\n        <div class=\"arrow\">−</div>\n        <div class=\"box\">Services Imports = $200M</div>\n        <div class=\"arrow\">=</div>\n        <div class=\"result\">Services Balance = +$100M (Surplus)</div>\n      </div>\n\n      <strong style=\"color:var(--accent);margin-top:1rem;display:block;\">Example 3: Goods &amp; Services Balance</strong>\n      <div class=\"diagram-flow\">\n        <div class=\"box\">Goods Balance = −$200M</div>\n        <div class=\"arrow\">+</div>\n        <div class=\"box\">Services Balance = +$100M</div>\n        <div class=\"arrow\">=</div>\n        <div class=\"result\" style=\"color:#d63031;border-color:#d63031;\">G &amp; S Balance = −$100M (Deficit)</div>\n      </div>\n\n      <strong style=\"color:var(--accent);margin-top:1rem;display:block;\">Example 4: Current Account Balance</strong>\n      <div class=\"diagram-flow\">\n        <div class=\"box\">G &amp; S Balance = −$100M</div>\n        <div class=\"arrow\">+</div>\n        <div class=\"box\">Primary Income = +$50M</div>\n        <div class=\"arrow\">+</div>\n        <div class=\"box\">Secondary Income = +$80M</div>\n        <div class=\"arrow\">=</div>\n        <div class=\"result\">Current Account = +$30M (Surplus)</div>\n      </div>\n\n      <strong style=\"color:var(--accent);margin-top:1rem;display:block;\">Example 5: Capital Account</strong>\n      <div class=\"diagram-flow\">\n        <div class=\"box\">Patent sales, licenses, royalties</div>\n        <div class=\"arrow\">=</div>\n        <div class=\"result\">Capital Account = +$10M</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Interactive BOP Calculator -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📈</div>\n    <h2>Interactive BOP Calculator <span class=\"underline\"></span></h2>\n    <p>Enter values (in millions USD) to calculate the Balance of Payments:</p>\n\n    <div class=\"bop-calc\" id=\"bopCalc\">\n      <div class=\"section-label\">📦 Goods Account</div>\n      <div class=\"calc-row\">\n        <label>Exports (X)</label>\n        <input type=\"number\" id=\"exports\" value=\"500\" oninput=\"calcBOP()\">\n      </div>\n      <div class=\"calc-row\">\n        <label>Imports (M)</label>\n        <input type=\"number\" id=\"imports\" value=\"700\" oninput=\"calcBOP()\">\n      </div>\n      <div class=\"calc-row\">\n        <label style=\"font-weight:600;color:var(--accent);\">Trade Balance</label>\n        <span class=\"calc-result\" id=\"tradeBalance\">-$200M</span>\n      </div>\n\n      <div class=\"section-label\">🏭 Services Account</div>\n      <div class=\"calc-row\">\n        <label>Services Exports</label>\n        <input type=\"number\" id=\"servExports\" value=\"300\" oninput=\"calcBOP()\">\n      </div>\n      <div class=\"calc-row\">\n        <label>Services Imports</label>\n        <input type=\"number\" id=\"servImports\" value=\"200\" oninput=\"calcBOP()\">\n      </div>\n      <div class=\"calc-row\">\n        <label style=\"font-weight:600;color:var(--accent);\">Services Balance</label>\n        <span class=\"calc-result\" id=\"servicesBalance\">+$100M</span>\n      </div>\n\n      <div class=\"section-label\">📊 Combined</div>\n      <div class=\"calc-row\">\n        <label style=\"font-weight:600;color:var(--accent);\">Goods &amp; Services Balance</label>\n        <span class=\"calc-result\" id=\"gsBalance\">-$100M</span>\n      </div>\n\n      <div class=\"section-label\">💰 Income</div>\n      <div class=\"calc-row\">\n        <label>Primary Income (net)</label>\n        <input type=\"number\" id=\"primaryIncome\" value=\"50\" oninput=\"calcBOP()\">\n      </div>\n      <div class=\"calc-row\">\n        <label>Secondary Income (net)</label>\n        <input type=\"number\" id=\"secondaryIncome\" value=\"80\" oninput=\"calcBOP()\">\n      </div>\n\n      <div class=\"section-label\" style=\"border-color:rgba(236,72,153,0.3);\">🏆 Current Account Balance</div>\n      <div class=\"calc-row\">\n        <label style=\"font-weight:700;color:var(--accent2);font-size:1.05rem;\">Current Account</label>\n        <span class=\"calc-result\" id=\"currentAccountBalance\" style=\"font-size:1.1rem;\">+$30M</span>\n      </div>\n\n      <div class=\"section-label\">🏛️ Capital &amp; Financial Account</div>\n      <div class=\"calc-row\">\n        <label>Capital Account (net)</label>\n        <input type=\"number\" id=\"capitalAccount\" value=\"10\" oninput=\"calcBOP()\">\n      </div>\n      <div class=\"calc-row\">\n        <label>Financial Account (net)</label>\n        <input type=\"number\" id=\"financialAccount\" value=\"-40\" oninput=\"calcBOP()\">\n      </div>\n\n      <div class=\"section-label\" style=\"border-color:var(--accent3);\">📋 Overall BOP</div>\n      <div class=\"calc-row\">\n        <label style=\"font-weight:700;color:var(--accent3);font-size:1.05rem;\">BOP Balance</label>\n        <span class=\"calc-result\" id=\"bopBalance\" style=\"font-size:1.1rem;\">$0M</span>\n      </div>\n    </div>\n\n    <p style=\"font-size:0.85rem;color:var(--text-muted);margin-top:0.5rem;\">The BOP always balances to zero because every debit has a corresponding credit (double-entry accounting).</p>\n  </div>\n\n  <!-- Flashcards -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💡</div>\n    <h2>Key Term Flashcards <span class=\"underline\"></span></h2>\n    <p>Click each card to reveal the definition.</p>\n    <div class=\"flashcard-container\">\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            💱 Foreign Exchange\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Conversion of one country's currency into another country's currency for international transactions\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            💳 Nominal Exchange Rate\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            The price of one currency expressed in terms of another currency\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🔒 Fixed Exchange Rate\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Exchange rate determined by monetary authority; historically based on gold standard (1890–1920)\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            📈 Floating Exchange Rate\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Exchange rate determined by market demand and supply; automatically balances BOP\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            ⚖️ Managed Floating\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Mixed system: central bank intervenes within a range while market largely determines rate\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            📉 Devaluation\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Official lowering of currency value by monetary authority under a fixed exchange rate system\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            📈 Depreciation\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Market-driven decrease in currency value under a floating exchange rate system\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            📋 Balance of Payments\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Statement of all transactions between residents and non-residents over a period; always balances to zero\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            ⚖️ Marshall-Lerner Cond.\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            For devaluation to improve trade balance: |E<sub>X</sub>| + |E<sub>M</sub>| &gt; 1\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            📊 NEER\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Nominal Effective Exchange Rate: weighted average of bilateral exchange rates with trading partners\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Comparison Tables -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📋</div>\n    <h2>Comparison Tables <span class=\"underline\"></span></h2>\n\n    <h3>Fixed vs Floating vs Managed Floating</h3>\n    <div class=\"comparison three-col\" style=\"grid-template-columns:1fr 1fr 1fr;\">\n      <div class=\"left\">\n        <div class=\"header\">🔒 Fixed</div>\n        <ul>\n          <li>Set by monetary authority</li>\n          <li>Stable &amp; predictable</li>\n          <li>Needs large reserves</li>\n          <li>Prone to speculation</li>\n          <li>Gold standard basis</li>\n        </ul>\n      </div>\n      <div class=\"right\" style=\"background:rgba(236,72,153,0.08);\">\n        <div class=\"header\" style=\"color:var(--accent2);\">📈 Floating</div>\n        <ul>\n          <li>Set by market D &amp; S</li>\n          <li>Volatile &amp; uncertain</li>\n          <li>No reserves needed</li>\n          <li>Auto-corrects BOP</li>\n          <li>Self-regulating</li>\n        </ul>\n      </div>\n      <div class=\"third-col\">\n        <div class=\"header\">⚖️ Managed</div>\n        <ul>\n          <li>Hybrid approach</li>\n          <li>Partial flexibility</li>\n          <li>Central bank intervenes</li>\n          <li>Limited volatility</li>\n          <li>Most common today</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Devaluation vs Depreciation</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">📉 Devaluation</div>\n        <ul>\n          <li>Official/policy-driven</li>\n          <li>Under <strong>fixed</strong> exchange rate</li>\n          <li>Announced by government</li>\n          <li>Sudden &amp; discrete</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📈 Depreciation</div>\n        <ul>\n          <li>Market-driven</li>\n          <li>Under <strong>floating</strong> exchange rate</li>\n          <li>Automatic &amp; continuous</li>\n          <li>Gradual &amp; ongoing</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Direct vs Indirect Quotation</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">📇 Direct (Price)</div>\n        <ul>\n          <li>Foreign currency per domestic unit</li>\n          <li>US$1 = SLKR 152</li>\n          <li>\"Price of foreign currency\"</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📈 Indirect (Volume)</div>\n        <ul>\n          <li>Domestic currency per foreign unit</li>\n          <li>SLKR 1 = US$0.0065</li>\n          <li>\"Volume of domestic currency\"</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Current vs Capital vs Financial Account</h3>\n    <div class=\"comparison three-col\" style=\"grid-template-columns:1fr 1fr 1fr;\">\n      <div class=\"left\">\n        <div class=\"header\">💳 Current</div>\n        <ul>\n          <li>Goods &amp; services trade</li>\n          <li>Primary &amp; secondary income</li>\n          <li>Short-term flows</li>\n          <li>Day-to-day transactions</li>\n        </ul>\n      </div>\n      <div class=\"right\" style=\"background:rgba(236,72,153,0.08);\">\n        <div class=\"header\" style=\"color:var(--accent2);\">🏛️ Capital</div>\n        <ul>\n          <li>Non-produced assets</li>\n          <li>Patents, licenses, brands</li>\n          <li>Intangible assets</li>\n          <li>Royalties &amp; leases</li>\n        </ul>\n      </div>\n      <div class=\"third-col\">\n        <div class=\"header\">💰 Financial</div>\n        <ul>\n          <li>Direct &amp; portfolio investment</li>\n          <li>Derivatives</li>\n          <li>Reserve assets</li>\n          <li>Capital flows</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- Interactive Quiz -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧰</div>\n    <h2>Test Your Knowledge <span class=\"underline\"></span></h2>\n\n    <div class=\"quiz-question\" data-q=\"1\">\n      <div class=\"q\">1. Under a fixed exchange rate system, the official lowering of currency value is called:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Depreciation</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Devaluation</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Appreciation</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Revaluation</button>\n      <div class=\"quiz-feedback\" data-feedback=\"1\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"2\">\n      <div class=\"q\">2. Which exchange rate system is determined purely by market demand and supply?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Fixed exchange rate</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Managed floating</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Floating exchange rate</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Gold standard</button>\n      <div class=\"quiz-feedback\" data-feedback=\"2\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"3\">\n      <div class=\"q\">3. In the Balance of Payments, a debit (+) is recorded when:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">An asset flows TO the country</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">An asset flows FROM the country</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Exports are made</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Remittances are received</button>\n      <div class=\"quiz-feedback\" data-feedback=\"3\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"4\">\n      <div class=\"q\">4. The Marshall-Lerner condition states that devaluation improves trade balance when:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">|E<sub>X</sub>| + |E<sub>M</sub>| &lt; 1</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">|E<sub>X</sub>| + |E<sub>M</sub>| &gt; 1</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">|E<sub>X</sub>| + |E<sub>M</sub>| = 1</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">|E<sub>X</sub>| × |E<sub>M</sub>| &gt; 1</button>\n      <div class=\"quiz-feedback\" data-feedback=\"4\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"5\">\n      <div class=\"q\">5. Direct quotation expresses:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Domestic currency in terms of foreign currency</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Foreign currency in terms of domestic currency</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">The real exchange rate adjusted for inflation</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">The weighted average of bilateral rates</button>\n      <div class=\"quiz-feedback\" data-feedback=\"5\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"6\">\n      <div class=\"q\">6. Which of the following is NOT a participant in the foreign exchange market?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Commercial banks</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Central bank</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Stock exchanges</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Forex brokers</button>\n      <div class=\"quiz-feedback\" data-feedback=\"6\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"7\">\n      <div class=\"q\">7. An appreciation of the domestic currency typically leads to:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Higher import prices</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Lower import prices and lower inflation</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Increased exports</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Higher foreign debt service payments</button>\n      <div class=\"quiz-feedback\" data-feedback=\"7\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"8\">\n      <div class=\"q\">8. The Balance of Payments always balances to zero because:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Government policy ensures it</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Central bank intervention</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Double-entry bookkeeping: every debit has a corresponding credit</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Trade is always balanced</button>\n      <div class=\"quiz-feedback\" data-feedback=\"8\"></div>\n    </div>\n  </div>\n\n  <!-- Summary -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📑</div>\n    <h2>Summary <span class=\"underline\"></span></h2>\n    <ul>\n      <li><strong>Foreign exchange</strong> converts one currency into another; the forex market has various participants including banks, brokers, central banks, and the public.</li>\n      <li>The <strong>nominal exchange rate</strong> can be quoted directly (foreign in domestic terms) or indirectly (domestic in foreign terms).</li>\n      <li>Foreign exchange is <strong>demanded</strong> for imports, travel, debt repayment, and transfers; it is <strong>supplied</strong> by exports, primary income, and secondary income.</li>\n      <li>Three main <strong>exchange rate systems</strong>: fixed (monetary authority), floating (market D &amp; S), and managed floating (hybrid).</li>\n      <li><strong>Devaluation/depreciation</strong> makes imports expensive and exports cheap; <strong>appreciation/revaluation</strong> has the opposite effect.</li>\n      <li>The <strong>Marshall-Lerner condition</strong> requires |E<sub>X</sub>| + |E<sub>M</sub>| &gt; 1 for devaluation to improve the trade balance.</li>\n      <li><strong>BOP</strong> records all international transactions via double-entry system, always balancing to zero across current, capital, and financial accounts.</li>\n    </ul>\n  </div>\n\n</div>\n\n<script>\n  // Particles\n  const canvas = document.getElementById('particles');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  class Particle {\n    constructor() {\n      this.reset();\n    }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.5;\n      this.speedY = (Math.random() - 0.5) * 0.5;\n      this.opacity = Math.random() * 0.5 + 0.1;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n      if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(168, 85, 247, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 80; i++) particles.push(new Particle());\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 150) {\n          ctx.beginPath();\n          ctx.strokeStyle = `rgba(168, 85, 247, ${0.06 * (1 - dist / 150)})`;\n          ctx.lineWidth = 0.5;\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  // Scroll reveal\n  const sections = document.querySelectorAll('[data-section]');\n\n  function revealSections() {\n    sections.forEach(section => {\n      const rect = section.getBoundingClientRect();\n      if (rect.top < window.innerHeight - 80) {\n        section.classList.add('visible');\n      }\n    });\n  }\n  window.addEventListener('scroll', revealSections);\n  revealSections();\n\n  // Progress bar\n  const progressBar = document.getElementById('progressBar');\n\n  window.addEventListener('scroll', () => {\n    const scrollTop = window.scrollY;\n    const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n    const progress = (scrollTop / docHeight) * 100;\n    progressBar.style.width = progress + '%';\n  });\n\n  // Quiz\n  function checkAnswer(btn, isCorrect) {\n    const question = btn.closest('.quiz-question');\n    const options = question.querySelectorAll('.quiz-option');\n    const feedback = question.querySelector('.quiz-feedback');\n\n    options.forEach(opt => {\n      opt.disabled = true;\n      if (opt.dataset.correct === 'true') opt.classList.add('correct');\n    });\n\n    if (isCorrect) {\n      btn.classList.add('correct');\n      feedback.textContent = '\\u2705 Correct!';\n      feedback.className = 'quiz-feedback show correct';\n    } else {\n      btn.classList.add('wrong');\n      const correctBtn = question.querySelector('[data-correct=\"true\"]');\n      feedback.textContent = '\\u274C Incorrect. The answer was: ' + correctBtn.textContent;\n      feedback.className = 'quiz-feedback show wrong';\n    }\n  }\n\n  // BOP Calculator\n  function calcBOP() {\n    const exports = parseFloat(document.getElementById('exports').value) || 0;\n    const imports = parseFloat(document.getElementById('imports').value) || 0;\n    const servExports = parseFloat(document.getElementById('servExports').value) || 0;\n    const servImports = parseFloat(document.getElementById('servImports').value) || 0;\n    const primaryIncome = parseFloat(document.getElementById('primaryIncome').value) || 0;\n    const secondaryIncome = parseFloat(document.getElementById('secondaryIncome').value) || 0;\n    const capitalAccount = parseFloat(document.getElementById('capitalAccount').value) || 0;\n    const financialAccount = parseFloat(document.getElementById('financialAccount').value) || 0;\n\n    const tradeBal = exports - imports;\n    const servBal = servExports - servImports;\n    const gsBal = tradeBal + servBal;\n    const currentAccount = gsBal + primaryIncome + secondaryIncome;\n    const bopBal = currentAccount + capitalAccount + financialAccount;\n\n    setResult('tradeBalance', tradeBal);\n    setResult('servicesBalance', servBal);\n    setResult('gsBalance', gsBal);\n    setResult('currentAccountBalance', currentAccount);\n    setResult('bopBalance', bopBal);\n  }\n\n  function setResult(id, value) {\n    const el = document.getElementById(id);\n    const sign = value >= 0 ? '+' : '';\n    el.textContent = sign + value + 'M';\n    el.className = 'calc-result';\n    if (value > 0) el.classList.add('positive');\n    else if (value < 0) el.classList.add('negative');\n    else el.classList.add('zero');\n  }\n\n  calcBOP();\n</script>\n\n\n\n\n</body>\n</html>",
    "11": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"progress-container\">\n  <div class=\"progress-bar\" id=\"progressBar\"></div>\n</div>\n\n<canvas id=\"particles\"></canvas>\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">Lesson 11</div>\n  <h1>Economic Growth,<br>Development &amp; Labour</h1>\n  <p>Understanding how economies expand, transform, and engage their workforce to improve human well-being.</p>\n  <div class=\"hero-scroll\">↓</div>\n</section>\n\n<div class=\"container\">\n\n\n\n  <!-- Economic Growth -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📈</div>\n    <h2>Economic Growth <span class=\"underline\"></span></h2>\n    <p><strong>Economic growth</strong> refers to the continuous increase in the real Gross Domestic Product (GDP) of a country over time. It represents the expansion of an economy's production capacity.</p>\n\n    <h3>How Economic Growth is Shown</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">📈</div>\n        <div class=\"label\">PPF Outward Shift</div>\n        <div class=\"desc\">Production Possibility Frontier shifts outward, showing increased capacity to produce goods and services</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">→</div>\n        <div class=\"label\">LRAS Rightward Shift</div>\n        <div class=\"desc\">Long-Run Aggregate Supply curve shifts right, indicating sustainable growth in productive capacity</div>\n      </div>\n    </div>\n\n    <h3>Measuring Economic Growth</h3>\n    <div class=\"formula-box\">\n      Economic Growth Rate = (Current GDP - Previous GDP) / Previous GDP × 100\n    </div>\n\n    <h4>Worked Example 1</h4>\n    <p>If a country's GDP was $500 billion in 2023 and $525 billion in 2024:</p>\n    <div class=\"formula-box formula-box-pink\">\n      Growth Rate = (525 - 500) / 500 × 100 = 25 / 500 × 100 = <strong>5%</strong>\n    </div>\n\n    <h4>Worked Example 2</h4>\n    <p>If GDP was $1.2 trillion in 2023 and $1.35 trillion in 2024:</p>\n    <div class=\"formula-box formula-box-pink\">\n      Growth Rate = (1.35 - 1.2) / 1.2 × 100 = 0.15 / 1.2 × 100 = <strong>12.5%</strong>\n    </div>\n\n    <h3>Interactive Growth Rate Calculator</h3>\n    <div class=\"calc-grid\">\n      <div class=\"calc-group\">\n        <label>Previous GDP ($)</label>\n        <input type=\"number\" id=\"prevGdp\" value=\"500\" step=\"any\">\n      </div>\n      <div class=\"calc-group\">\n        <label>Current GDP ($)</label>\n        <input type=\"number\" id=\"currGdp\" value=\"525\" step=\"any\">\n      </div>\n    </div>\n    <button class=\"calc-btn\" onclick=\"calcGrowthRate()\">Calculate Growth Rate</button>\n    <div class=\"calc-result\" id=\"growthResult\">Growth Rate: 5.00%</div>\n  </div>\n\n  <!-- Factors Affecting Economic Growth -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🎯</div>\n    <h2>Factors Affecting Economic Growth <span class=\"underline\"></span></h2>\n    <p>Multiple interrelated factors determine an economy's ability to grow sustainably:</p>\n    <div class=\"three-col\">\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🏔️</span>Resource Endowment</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">💡</span>Innovations</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🏭</span>Physical Capital</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🔬</span>R&amp;D Investment</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🧑‍🎓</span>Human Capital</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">💰</span>Economic Stability</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🌱</span>Natural Capital</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🏛️</span>Political Stability</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🤝</span>Social Capital</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">⚖️</span>Good Governance</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">⚡</span>Productivity</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🏆</span>Incentives</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">💻</span>Technology</div>\n    </div>\n    <p style=\"font-size: 0.85rem; color: var(--text-muted); margin-top: 0.5rem;\">These factors interact and reinforce each other. For example, good governance fosters political stability, which encourages investment in physical and human capital.</p>\n  </div>\n\n  <!-- Importance vs Costs of Growth -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚖️</div>\n    <h2>Importance &amp; Costs of Economic Growth <span class=\"underline\"></span></h2>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">✅ Importance</div>\n        <ul>\n          <li>Improved living standards &amp; quality of life</li>\n          <li>Increased employment opportunities</li>\n          <li>Successful fiscal management (higher tax revenue)</li>\n          <li>Stronger investments in infrastructure &amp; public goods</li>\n          <li>Increased profits &amp; business trustworthiness</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">⚠️ Costs</div>\n        <ul>\n          <li>Environmental problems, degradation, pollution</li>\n          <li>Depletion of non-renewable resources</li>\n          <li>Negative externalities (health costs, congestion)</li>\n          <li>Inflationary pressures</li>\n          <li>Income &amp; regional disparities widen</li>\n          <li>Decrease in present consumption (savings for investment)</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- Characteristics of Successful Growing Countries -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🌍</div>\n    <h2>Common Characteristics of Successful Growing Countries <span class=\"underline\"></span></h2>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">🌐</div>\n        <div class=\"label\">Global Economy Integration</div>\n        <div class=\"desc\">Benefiting from trade, investment flows, and global value chains</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📊</div>\n        <div class=\"label\">Macroeconomic Stability</div>\n        <div class=\"desc\">Low inflation, sustainable debt, stable currency</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">💵</div>\n        <div class=\"label\">High Savings &amp; Investment</div>\n        <div class=\"desc\">Domestic savings fund capital formation and infrastructure</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📋</div>\n        <div class=\"label\">Market-Based Resource Allocation</div>\n        <div class=\"desc\">Price signals guide efficient distribution of resources</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🏛️</div>\n        <div class=\"label\">Efficient &amp; Trustworthy Government</div>\n        <div class=\"desc\">Rule of law, property rights, low corruption</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Economic Development -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📉</div>\n    <h2>Economic Development <span class=\"underline\"></span></h2>\n    <p><strong>Economic development</strong> is a transformation process involving structural changes that improve the quality of life. It includes qualitative features that go beyond quantitative growth.</p>\n\n    <h3>Structural Changes in Development</h3>\n    <div class=\"card-grid card-grid-4\">\n      <div class=\"info-card\"><div class=\"emoji\">🏭</div><div class=\"label\">Industrialization</div><div class=\"desc\">Shift from agriculture to industry &amp; services</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">⚡</div><div class=\"label\">Productivity Increase</div><div class=\"desc\">More output per unit of input</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💻</div><div class=\"label\">Technology Advancement</div><div class=\"desc\">Adoption of modern techniques</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏛️</div><div class=\"label\">Modernization</div><div class=\"desc\">Social &amp; institutional transformation</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📈</div><div class=\"label\">Structural Change</div><div class=\"desc\">Sectoral composition shifts</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">↓</div><div class=\"label\">Reduced Inequality</div><div class=\"desc\">Lower unemployment, poverty &amp; disparity</div></div>\n    </div>\n\n    <h3>Growth vs Development</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">📈 Economic Growth</div>\n        <ul>\n          <li>Quantitative increase in output</li>\n          <li>Measured by GDP/GNP growth rate</li>\n          <li>Narrower concept</li>\n          <li>Can occur without development</li>\n          <li>Short to medium-term focus</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📉 Economic Development</div>\n        <ul>\n          <li>Qualitative transformation + quantitative growth</li>\n          <li>Measured by HDI, poverty reduction, inequality</li>\n          <li>Broader, multidimensional concept</li>\n          <li>Requires growth but goes beyond it</li>\n          <li>Long-term sustainable focus</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Multidimensional Nature</h3>\n    <p>Development encompasses <strong>economic, social, political, and cultural</strong> dimensions. It is not merely about income but about expanding people's freedoms and capabilities.</p>\n\n    <h4>Five Determinants of Unfavorable Human States</h4>\n    <div class=\"three-col\">\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">💢</span>Limitedness</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🦵</span>Bodily Weakness</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🤝</span>Unfavorable Social Relations</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🛡️</span>Insecurity</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">⚠️</span>Powerlessness</div>\n    </div>\n  </div>\n\n  <!-- Human Development -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧍</div>\n    <h2>Human Development <span class=\"underline\"></span></h2>\n    <div class=\"info-card\">\n      <div class=\"emoji\">🌍</div>\n      <div class=\"label\">\"Process of Enlarging People's Choices\"</div>\n      <div class=\"desc\">— Mahbub ul Haq, UNDP Human Development Reports</div>\n    </div>\n\n    <h3>The Capability Approach</h3>\n    <p>Pioneered by <strong>Amartya Sen</strong>, the capability approach focuses on what people are able to <strong>do</strong> and <strong>be</strong> (their functionings and capabilities), rather than just what they have.</p>\n\n    <h3>HDI — Human Development Index</h3>\n    <p>A composite index measuring average achievement in three key dimensions:</p>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">💰</div>\n        <div class=\"label\">Income</div>\n        <div class=\"desc\">GNI per capita (PPP adjusted)</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🎓</div>\n        <div class=\"label\">Education</div>\n        <div class=\"desc\">Mean years of schooling &amp; expected years</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">❤️</div>\n        <div class=\"label\">Health</div>\n        <div class=\"desc\">Life expectancy at birth</div>\n      </div>\n    </div>\n\n    <h3>Dimensions of Human Development</h3>\n    <div class=\"three-col\">\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">💵</span>Income</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🎓</span>Education</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🏥</span>Health</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">💡</span>Empowerment</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🏛️</span>Political Freedom</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🤝</span>Social Relationships</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">⚖️</span>Equity</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🏢</span>Working Environment</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🎬</span>Leisure</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">💰</span>Economic Freedom</div>\n      <div class=\"factor-chip\"><span class=\"chip-emoji\">🌱</span>Environmental Quality</div>\n    </div>\n  </div>\n\n  <!-- Labour Force -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🤝</div>\n    <h2>Labour Force <span class=\"underline\"></span></h2>\n    <p>The <strong>labour force</strong> is defined as the sum of employed and unemployed persons within the working-age population.</p>\n\n    <div class=\"formula-box formula-box-amber\">\n      Labour Force = Employment + Unemployment\n    </div>\n\n    <h3>Sri Lanka Labour Force Calculation</h3>\n    <div class=\"timeline\">\n      <div class=\"timeline-item\">\n        <div class=\"title\">Step 1: Total Population</div>\n        <div class=\"desc\">The entire population of the country</div>\n      </div>\n      <div class=\"timeline-item\">\n        <div class=\"title\">Step 2: Subtract Child Dependents (&lt;10) &amp; Adult Dependents (&gt;60)</div>\n        <div class=\"desc\">= <strong>Active Population</strong> (working-age population)</div>\n      </div>\n      <div class=\"timeline-item\">\n        <div class=\"title\">Step 3: Subtract Non-Labour Groups</div>\n        <div class=\"desc\">Housewives + Full-time students + Retired + Disabled + Self-unemployed</div>\n      </div>\n      <div class=\"timeline-item\">\n        <div class=\"title\">Step 4: Labour Force</div>\n        <div class=\"desc\">Active Population − Non-labour groups = Labour Force</div>\n      </div>\n    </div>\n\n    <h3>Key Ratios</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">📊</div>\n        <div class=\"label\">Employment Ratio</div>\n        <div class=\"desc\">Employed ÷ Labour Force × 100</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📉</div>\n        <div class=\"label\">Unemployment Ratio</div>\n        <div class=\"desc\">Unemployed ÷ Labour Force × 100</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📈</div>\n        <div class=\"label\">Labour Force Participation Ratio</div>\n        <div class=\"desc\">Labour Force ÷ Active Population × 100</div>\n      </div>\n    </div>\n\n    <h3>Worked Example</h3>\n    <p>Suppose a country has:<br>\n    Total Population = 22,000,000<br>\n    Child dependents (&lt;10) = 3,500,000<br>\n    Adult dependents (&gt;60) = 2,500,000<br>\n    Housewives = 1,200,000<br>\n    Full-time students = 1,800,000<br>\n    Retired = 800,000<br>\n    Disabled = 200,000<br>\n    Self-unemployed = 0</p>\n\n    <div class=\"formula-box formula-box-amber\" style=\"font-size: 0.9rem; text-align: left;\">\n      Active Population = 22,000,000 − 3,500,000 − 2,500,000 = <strong>16,000,000</strong><br>\n      Labour Force = 16,000,000 − 1,200,000 − 1,800,000 − 800,000 − 200,000 = <strong>12,000,000</strong><br>\n      If Employed = 10,800,000<br>\n       Unemployed = 12,000,000 − 10,800,000 = <strong>1,200,000</strong><br>\n       Unemployment Ratio = 1,200,000 / 12,000,000 × 100 = <strong>10%</strong>\n    </div>\n\n    <h3>Interactive Labour Force Calculator</h3>\n    <div class=\"calc-grid\">\n      <div class=\"calc-group\">\n        <label>Total Population</label>\n        <input type=\"number\" id=\"totalPop\" value=\"22000000\" step=\"1\">\n      </div>\n      <div class=\"calc-group\">\n        <label>Child Dependents (&lt;10)</label>\n        <input type=\"number\" id=\"childDep\" value=\"3500000\" step=\"1\">\n      </div>\n      <div class=\"calc-group\">\n        <label>Adult Dependents (&gt;60)</label>\n        <input type=\"number\" id=\"adultDep\" value=\"2500000\" step=\"1\">\n      </div>\n      <div class=\"calc-group\">\n        <label>Housewives</label>\n        <input type=\"number\" id=\"housewives\" value=\"1200000\" step=\"1\">\n      </div>\n      <div class=\"calc-group\">\n        <label>Full-time Students</label>\n        <input type=\"number\" id=\"students\" value=\"1800000\" step=\"1\">\n      </div>\n      <div class=\"calc-group\">\n        <label>Retired</label>\n        <input type=\"number\" id=\"retired\" value=\"800000\" step=\"1\">\n      </div>\n      <div class=\"calc-group\">\n        <label>Disabled</label>\n        <input type=\"number\" id=\"disabled\" value=\"200000\" step=\"1\">\n      </div>\n      <div class=\"calc-group\">\n        <label>Employed</label>\n        <input type=\"number\" id=\"employed\" value=\"10800000\" step=\"1\">\n      </div>\n    </div>\n    <button class=\"calc-btn\" onclick=\"calcLabourForce()\">Calculate Labour Force</button>\n    <div class=\"calc-result\" id=\"labourResult\">\n      Active Pop: 16,000,000 &nbsp;|&nbsp; Labour Force: 12,000,000 &nbsp;|&nbsp; Unemployment: 10.00%\n    </div>\n  </div>\n\n  <!-- Flashcards -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📝</div>\n    <h2>Key Terms <span class=\"underline\"></span></h2>\n    <div class=\"flashcard-container\">\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            📈 Economic Growth\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Continuous increase in real GDP<br>\n            <small>PPF shifts outward<br>LRAS shifts rightward</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            📉 Economic Development\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Transformation with structural change<br>\n            <small>Qualitative + quantitative<br>Multidimensional concept</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            📊 HDI\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Human Development Index<br>\n            <small>Income + Education + Health<br>Composite measure of well-being</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🤝 Labour Force\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Employed + Unemployed<br>\n            <small>Working-age population minus non-labour groups</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            💡 Capability Approach\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Amartya Sen's approach<br>\n            <small>Focus on what people can do &amp; be, not just what they have</small>\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🏔️ Active Population\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Working-age population<br>\n            <small>Total − child dependents (&lt;10) − adult dependents (&gt;60)</small>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Poverty -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💰</div>\n    <h2>Poverty <span class=\"underline\"></span></h2>\n    <p><strong>Poverty</strong> is a state of deprivation where individuals lack the resources to meet basic needs for a minimally acceptable quality of life.</p>\n\n    <h3>Types of Poverty</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">💵 Absolute Poverty</div>\n        <ul>\n          <li>Below a fixed minimum subsistence level</li>\n          <li>Cannot afford basic necessities (food, water, shelter)</li>\n          <li>Measured by poverty line (e.g., $2.15/day World Bank)</li>\n          <li>Focuses on survival</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📉 Relative Poverty</div>\n        <ul>\n          <li>Below the average standard of living in society</li>\n          <li>Cannot participate fully in normal social life</li>\n          <li>Measured as % of median income (e.g., below 60%)</li>\n          <li>Focuses on inequality</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Poverty and Economic Growth</h3>\n    <p>Economic growth can reduce poverty through the <strong>trickle-down effect</strong>, but inclusive growth requires deliberate policies for equitable distribution. Development goes beyond growth to directly address poverty through capability enhancement, social protection, and access to education, healthcare, and productive assets.</p>\n  </div>\n\n  <!-- Quiz -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧰</div>\n    <h2>Test Your Knowledge <span class=\"underline\"></span></h2>\n\n    <div class=\"quiz-question\" data-q=\"1\">\n      <div class=\"q\">1. What is the formula for Economic Growth Rate?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">(Previous GDP - Current GDP) / Previous GDP × 100</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">(Current GDP - Previous GDP) / Previous GDP × 100</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">(Current GDP - Previous GDP) / Current GDP × 100</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Current GDP / Previous GDP × 100</button>\n      <div class=\"quiz-feedback\" data-feedback=\"1\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"2\">\n      <div class=\"q\">2. Which economist pioneered the Capability Approach?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Adam Smith</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">John Maynard Keynes</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Amartya Sen</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">David Ricardo</button>\n      <div class=\"quiz-feedback\" data-feedback=\"2\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"3\">\n      <div class=\"q\">3. What does HDI stand for?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Human Development Indicator</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Human Development Index</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Human Domestic Index</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Higher Development Index</button>\n      <div class=\"quiz-feedback\" data-feedback=\"3\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"4\">\n      <div class=\"q\">4. Which is NOT a dimension of the HDI?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Income</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Education</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Health</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Political Freedom</button>\n      <div class=\"quiz-feedback\" data-feedback=\"4\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"5\">\n      <div class=\"q\">5. Labour Force is equal to:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Total Population - Dependents</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Employment + Unemployment</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Active Population - Housewives</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Employed × 2</button>\n      <div class=\"quiz-feedback\" data-feedback=\"5\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"6\">\n      <div class=\"q\">6. Which is a cost of economic growth?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Improved living standards</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Increased employment</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Environmental degradation</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Stronger investments</button>\n      <div class=\"quiz-feedback\" data-feedback=\"6\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"7\">\n      <div class=\"q\">7. If GDP was $800B and rose to $880B, the growth rate is:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">8%</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">10%</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">12%</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">15%</button>\n      <div class=\"quiz-feedback\" data-feedback=\"7\"></div>\n    </div>\n  </div>\n\n  <!-- Formulas Reference -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📖</div>\n    <h2>Formula Reference <span class=\"underline\"></span></h2>\n    <div class=\"formula-box\">\n      Growth Rate = (GDPᵢₙ − GDPᵢₙ₋₁) / GDPᵢₙ₋₁ × 100\n    </div>\n    <div class=\"formula-box formula-box-pink\">\n      Labour Force = Employment + Unemployment\n    </div>\n    <div class=\"formula-box formula-box-pink\">\n      Active Population = Total Pop − Child Dep (&lt;10) − Adult Dep (&gt;60)\n    </div>\n    <div class=\"formula-box formula-box-amber\">\n      Unemployment Ratio = Unemployed / Labour Force × 100\n    </div>\n    <div class=\"formula-box formula-box-amber\">\n      Labour Force Participation = Labour Force / Active Population × 100\n    </div>\n  </div>\n\n</div>\n\n<script>\n  const canvas = document.getElementById('particles');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  class Particle {\n    constructor() {\n      this.reset();\n    }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.5;\n      this.speedY = (Math.random() - 0.5) * 0.5;\n      this.opacity = Math.random() * 0.5 + 0.1;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n      if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(168, 85, 247, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 80; i++) particles.push(new Particle());\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 150) {\n          ctx.beginPath();\n          ctx.strokeStyle = `rgba(168, 85, 247, ${0.06 * (1 - dist / 150)})`;\n          ctx.lineWidth = 0.5;\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  const sections = document.querySelectorAll('[data-section]');\n\n  function revealSections() {\n    sections.forEach(section => {\n      const rect = section.getBoundingClientRect();\n      if (rect.top < window.innerHeight - 80) {\n        section.classList.add('visible');\n      }\n    });\n  }\n  window.addEventListener('scroll', revealSections);\n  revealSections();\n\n  const progressBar = document.getElementById('progressBar');\n\n  window.addEventListener('scroll', () => {\n    const scrollTop = window.scrollY;\n    const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n    const progress = (scrollTop / docHeight) * 100;\n    progressBar.style.width = progress + '%';\n  });\n\n  function checkAnswer(btn, isCorrect) {\n    const question = btn.closest('.quiz-question');\n    const options = question.querySelectorAll('.quiz-option');\n    const feedback = question.querySelector('.quiz-feedback');\n\n    options.forEach(opt => {\n      opt.disabled = true;\n      opt.style.cursor = 'not-allowed';\n      if (opt.dataset.correct === 'true') opt.classList.add('correct');\n    });\n\n    if (isCorrect) {\n      btn.classList.add('correct');\n      feedback.textContent = '\\u2705 Correct!';\n      feedback.className = 'quiz-feedback show correct';\n    } else {\n      btn.classList.add('wrong');\n      const correctBtn = question.querySelector('[data-correct=\"true\"]');\n      feedback.textContent = '\\u274C Incorrect. The answer was: ' + correctBtn.textContent;\n      feedback.className = 'quiz-feedback show wrong';\n    }\n  }\n\n  function calcGrowthRate() {\n    const prev = parseFloat(document.getElementById('prevGdp').value);\n    const curr = parseFloat(document.getElementById('currGdp').value);\n    if (!prev || !curr) {\n      document.getElementById('growthResult').textContent = 'Please enter valid numbers';\n      return;\n    }\n    const rate = ((curr - prev) / prev) * 100;\n    document.getElementById('growthResult').textContent = `Growth Rate: ${rate.toFixed(2)}%`;\n  }\n\n  function calcLabourForce() {\n    const totalPop = parseInt(document.getElementById('totalPop').value) || 0;\n    const childDep = parseInt(document.getElementById('childDep').value) || 0;\n    const adultDep = parseInt(document.getElementById('adultDep').value) || 0;\n    const housewives = parseInt(document.getElementById('housewives').value) || 0;\n    const students = parseInt(document.getElementById('students').value) || 0;\n    const retired = parseInt(document.getElementById('retired').value) || 0;\n    const disabled = parseInt(document.getElementById('disabled').value) || 0;\n    const employed = parseInt(document.getElementById('employed').value) || 0;\n\n    const activePop = totalPop - childDep - adultDep;\n    const nonLabour = housewives + students + retired + disabled;\n    const labourForce = activePop - nonLabour;\n    const unemployed = labourForce - employed;\n    const unempRatio = labourForce > 0 ? (unemployed / labourForce) * 100 : 0;\n\n    document.getElementById('labourResult').textContent =\n      `Active Pop: ${activePop.toLocaleString()}  |  Labour Force: ${labourForce.toLocaleString()}  |  Unemployment: ${unempRatio.toFixed(2)}%`;\n  }\n\n  calcGrowthRate();\n  calcLabourForce();\n</script>\n\n\n\n\n</body>\n</html>",
    "12": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"progress-container\">\n  <div class=\"progress-bar\" id=\"progressBar\"></div>\n</div>\n\n<canvas id=\"particles\"></canvas>\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">Lesson 12</div>\n  <h1>Sri Lankan Economy<br>Since Independence</h1>\n  <p>Exploring the transformation from plantation exports to a modern service-driven economy since 1948.</p>\n  <div class=\"hero-scroll\">↓</div>\n</section>\n\n<div class=\"container\">\n\n\n\n  <!-- 1. Overview -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🌍</div>\n    <h2>Overview <span class=\"underline\"></span></h2>\n    <p>Since gaining independence from Britain in <span class=\"highlight\">1948</span>, Sri Lanka's economy has undergone dramatic transformations — from a colonial plantation-based export economy to a closed import-substituting regime, and then to a liberalized export-oriented economy, and most recently a services-driven post-war economy facing new challenges.</p>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">📅</div>\n        <div class=\"label\">Independence</div>\n        <div class=\"desc\">1948 — Dominion status, plantation economy</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🏭</div>\n        <div class=\"label\">Current Status</div>\n        <div class=\"desc\">Lower-middle income, services-dominated</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">💱</div>\n        <div class=\"label\">Key Exports</div>\n        <div class=\"desc\">Textiles, tea, rubber, coconut, tourism</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">⚠️</div>\n        <div class=\"label\">Challenges</div>\n        <div class=\"desc\">Debt crisis, inflation, IMF programs</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 2. Timeline -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📈</div>\n    <h2>Timeline of Economic Policy <span class=\"underline\"></span></h2>\n    <div class=\"timeline\">\n      <div class=\"timeline-item\">\n        <div class=\"year\">1948 – 1960</div>\n        <div class=\"title\">🌍 Open Economy · Plantation Exports</div>\n        <div class=\"desc\">Continued colonial trade patterns. Tea, rubber, coconut dominated exports. Minimal state intervention. Relatively open trade regime.</div>\n      </div>\n      <div class=\"timeline-item pink\">\n        <div class=\"year\">1960 – 1977</div>\n        <div class=\"title\">🔒 Closed Economy · Import Substitution</div>\n        <div class=\"desc\">Nationalization of key industries (banks, insurance, plantations). High tariffs, import controls. State-led industrialization. ISI strategy adopted.</div>\n      </div>\n      <div class=\"timeline-item amber\">\n        <div class=\"year\">1977 – 2009</div>\n        <div class=\"title\">💰 Liberalization · Export Orientation</div>\n        <div class=\"desc\">1977 economic reforms under J.R. Jayewardene. Removed import controls, floated currency, privatized state enterprises. EPZs established. Garment industry boom.</div>\n      </div>\n      <div class=\"timeline-item\">\n        <div class=\"year\">2009 – 2019</div>\n        <div class=\"title\">🏗️ Post-War Development Boom</div>\n        <div class=\"desc\">End of civil war (2009). Infrastructure boom: highways, ports, airports. Tourism surge. Construction-driven growth. Rising debt.</div>\n      </div>\n      <div class=\"timeline-item pink\">\n        <div class=\"year\">2020 – Present</div>\n        <div class=\"title\">⚠️ Debt Crisis · IMF · Recovery</div>\n        <div class=\"desc\">COVID-19 hit tourism. 2022 economic crisis: sovereign default, inflation, shortages. IMF bailout program (2023). Ongoing restructuring.</div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 3. Import Substitution Industrialization -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🔒</div>\n    <h2>Import Substitution Industrialization <span class=\"underline\"></span></h2>\n    <p><span class=\"highlight\">ISI</span> was the dominant strategy from the 1960s to 1977, aimed at reducing dependence on imported manufactured goods by promoting domestic industries behind protective barriers.</p>\n\n    <h3>Characteristics of ISI in Sri Lanka</h3>\n    <ul>\n      <li><strong>Protectionist policies:</strong> High tariffs and quantitative import controls</li>\n      <li><strong>State-led industrialization:</strong> Public sector dominated manufacturing</li>\n      <li><strong>Nationalization:</strong> Banks, insurance, plantations, petroleum, transport</li>\n      <li><strong>Overvalued currency:</strong> Made imports cheaper, exports costlier</li>\n      <li><strong>Licensing system:</strong> Strict import licensing and foreign exchange controls</li>\n    </ul>\n\n    <h3>Rationale for ISI</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">🧱</div>\n        <div class=\"label\">Infant Industry</div>\n        <div class=\"desc\">Protect young domestic industries until competitive</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">💰</div>\n        <div class=\"label\">Save Foreign Exchange</div>\n        <div class=\"desc\">Reduce import bill by producing locally</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🏢</div>\n        <div class=\"label\">Industrialization</div>\n        <div class=\"desc\">Shift from colonial plantation mono-economy</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">👥</div>\n        <div class=\"label\">Self-Sufficiency</div>\n        <div class=\"desc\">Reduce dependence on former colonial powers</div>\n      </div>\n    </div>\n\n    <div class=\"formula-box\" style=\"font-size: 0.95rem;\">\n      Effective Rate of Protection (ERP) = (Value Added in World Prices − Value Added in Domestic Prices) ÷ Value Added in World Prices × 100\n    </div>\n  </div>\n\n  <!-- 4. Export-Oriented Industrial Policy -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💰</div>\n    <h2>Export-Oriented Industrial Policy <span class=\"underline\"></span></h2>\n    <p>The landmark <span class=\"highlight\">1977 reforms</span> shifted Sri Lanka from ISI to an <span class=\"highlight-pink\">export-oriented</span> strategy, opening the economy to global markets.</p>\n\n    <h3>Key Reforms of 1977</h3>\n    <ul>\n      <li>Unified and floated the exchange rate</li>\n      <li>Abolished most import controls and reduced tariffs</li>\n      <li>Removed price controls</li>\n      <li>Privatization of state-owned enterprises</li>\n      <li>Established <strong>Export Processing Zones (EPZs)</strong> — Katunayake, Biyagama, Koggala</li>\n      <li>Liberalized foreign direct investment (FDI)</li>\n    </ul>\n\n    <h3>Major Export Sectors</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">👕</div>\n        <div class=\"label\">Textiles &amp; Garments</div>\n        <div class=\"desc\">Largest export earner since 1990s</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🍵</div>\n        <div class=\"label\">Tea</div>\n        <div class=\"desc\">Ceylon Tea — world-renowned brand</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🌲</div>\n        <div class=\"label\">Rubber</div>\n        <div class=\"desc\">Tires, industrial products</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🥥</div>\n        <div class=\"label\">Coconut</div>\n        <div class=\"desc\">Desiccated, oil, coir products</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">✈️</div>\n        <div class=\"label\">Tourism</div>\n        <div class=\"desc\">Major foreign exchange earner (pre-COVID)</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📡</div>\n        <div class=\"label\">IT &amp; BPO</div>\n        <div class=\"desc\">Emerging services export sector</div>\n      </div>\n    </div>\n\n    <h3>Export Processing Zones</h3>\n    <ul>\n      <li><strong>Katunayake EPZ</strong> (1978) — first and largest, near airport</li>\n      <li><strong>Biyagama EPZ</strong> — near Colombo</li>\n      <li><strong>Koggala EPZ</strong> — southern Sri Lanka</li>\n      <li><strong>BOI</strong> (Board of Investment) — facilitates FDI with tax incentives</li>\n    </ul>\n  </div>\n\n  <!-- 5. Comparison: ISI vs Export-Oriented -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚖️</div>\n    <h2>ISI vs Export-Oriented Strategy <span class=\"underline\"></span></h2>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🔒 Import Substitution</div>\n        <ul>\n          <li>Protect domestic industries via tariffs</li>\n          <li>State-owned enterprises dominate</li>\n          <li>Overvalued currency</li>\n          <li>Import licensing &amp; exchange controls</li>\n          <li>Limited foreign investment</li>\n          <li>Focus on domestic market</li>\n          <li>Result: inefficiency, high costs, foreign exchange shortages</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">💰 Export-Oriented</div>\n        <ul>\n          <li>Remove trade barriers, open markets</li>\n          <li>Private sector-led growth</li>\n          <li>Market-determined exchange rate</li>\n          <li>Liberalized trade and capital flows</li>\n          <li>FDI encouraged via BOI incentives</li>\n          <li>Focus on global competitiveness</li>\n          <li>Result: rapid export growth, but import dependence</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 6. Comparison: Pre-1977 vs Post-1977 -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📅</div>\n    <h2>Pre-1977 vs Post-1977 Economy <span class=\"underline\"></span></h2>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">💺 Pre-1977</div>\n        <ul>\n          <li><strong>Trade:</strong> Closed, protectionist</li>\n          <li><strong>Exchange rate:</strong> Overvalued, fixed</li>\n          <li><strong>State role:</strong> Dominant, nationalized industries</li>\n          <li><strong>Industry:</strong> Infant, inefficient, high-cost</li>\n          <li><strong>Agriculture:</strong> Plantations + subsistence</li>\n          <li><strong>Growth:</strong> Slow (&lt; 3% average)</li>\n          <li><strong>Inflation:</strong> Suppressed via controls</li>\n          <li><strong>FDI:</strong> Heavily restricted</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📈 Post-1977</div>\n        <ul>\n          <li><strong>Trade:</strong> Open, liberalized</li>\n          <li><strong>Exchange rate:</strong> Floating, market-determined</li>\n          <li><strong>State role:</strong> Reduced, privatization</li>\n          <li><strong>Industry:</strong> Competitive, export-oriented</li>\n          <li><strong>Agriculture:</strong> Commercialization + diversification</li>\n          <li><strong>Growth:</strong> Faster (5–6% pre-war)</li>\n          <li><strong>Inflation:</strong> Market-driven, periodic spikes</li>\n          <li><strong>FDI:</strong> Encouraged via BOI incentives</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- 7. Structural Changes -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏛️</div>\n    <h2>Structural Changes in the Economy <span class=\"underline\"></span></h2>\n    <p>Sri Lanka has undergone a major structural transformation from an <span class=\"highlight\">agriculture-based</span> economy to a <span class=\"highlight-pink\">services-dominated</span> economy over the post-independence period.</p>\n\n    <h3>Sectoral Composition of GDP (Approximate)</h3>\n\n    <h4>1960 — Agriculture Dominant</h4>\n    <div class=\"sector-bar\">\n      <div class=\"agriculture\" style=\"width: 38%;\"></div>\n      <div class=\"industry\" style=\"width: 20%;\"></div>\n      <div class=\"services\" style=\"width: 42%;\"></div>\n    </div>\n    <div class=\"sector-label\">\n      <span>🌾 Agriculture 38%</span>\n      <span>🏭 Industry 20%</span>\n      <span>🏢 Services 42%</span>\n    </div>\n\n    <h4>1980 — Industry Rising</h4>\n    <div class=\"sector-bar\">\n      <div class=\"agriculture\" style=\"width: 28%;\"></div>\n      <div class=\"industry\" style=\"width: 30%;\"></div>\n      <div class=\"services\" style=\"width: 42%;\"></div>\n    </div>\n    <div class=\"sector-label\">\n      <span>🌾 Agriculture 28%</span>\n      <span>🏭 Industry 30%</span>\n      <span>🏢 Services 42%</span>\n    </div>\n\n    <h4>2020 — Services Dominant</h4>\n    <div class=\"sector-bar\">\n      <div class=\"agriculture\" style=\"width: 8%;\"></div>\n      <div class=\"industry\" style=\"width: 27%;\"></div>\n      <div class=\"services\" style=\"width: 65%;\"></div>\n    </div>\n    <div class=\"sector-label\">\n      <span>🌾 Agriculture ~8%</span>\n      <span>🏭 Industry ~27%</span>\n      <span>🏢 Services ~65%</span>\n    </div>\n\n    <div class=\"sector-legend\">\n      <span><span class=\"dot\" style=\"background:#a855f7;\"></span> Agriculture</span>\n      <span><span class=\"dot\" style=\"background:#ec4899;\"></span> Industry</span>\n      <span><span class=\"dot\" style=\"background:#f59e0b;\"></span> Services</span>\n    </div>\n\n    <h3>Key Structural Changes</h3>\n    <ul>\n      <li><strong>Agriculture → Services:</strong> Agriculture's share fell from ~38% (1960) to ~8% (2020)</li>\n      <li><strong>Industry:</strong> Rose to ~30% after liberalization, then stabilized at ~27%</li>\n      <li><strong>Services:</strong> Expanded from ~42% to ~65%, driven by finance, telecom, tourism, IT</li>\n      <li><strong>Urbanization:</strong> Western Province (Colombo) dominates economic activity</li>\n      <li><strong>Labour force:</strong> Shift from agriculture to industry and services; remittance-driven migration</li>\n    </ul>\n\n    <div class=\"formula-box\" style=\"font-size: 0.95rem;\">\n      Structural Transformation Index = Change in Share of Non-Agriculture GDP over Time\n    </div>\n  </div>\n\n  <!-- 8. Flashcards -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧩</div>\n    <h2>Key Terms <span class=\"underline\"></span></h2>\n    <div class=\"flashcard-container\">\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🔒 Import Substitution Industrialization\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Protectionist strategy replacing imports with domestic production. Used in Sri Lanka 1960–1977.\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            💰 Export-Oriented Industrialization\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Strategy focusing on producing goods for export markets. Adopted in Sri Lanka post-1977.\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            📆 Liberalization\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            1977 economic reforms: removed trade barriers, floated currency, privatized SOEs, opened to FDI.\n          </div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"this.classList.toggle('flipped')\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            🏛️ EPZ / BOI\n            <div class=\"flashcard-hint\">Click to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Export Processing Zones &amp; Board of Investment. Tax-incentivized zones for export-oriented FDI.\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- 9. Key Policy Phases Overview -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📊</div>\n    <h2>Policy Phases at a Glance <span class=\"underline\"></span></h2>\n    <div style=\"overflow-x:auto;\">\n      <table style=\"width:100%; border-collapse: collapse; font-size: 0.9rem;\">\n        <thead>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.1);\">\n            <th style=\"padding:0.75rem; text-align:left; color:var(--accent);\">Period</th>\n            <th style=\"padding:0.75rem; text-align:left; color:var(--accent2);\">Regime</th>\n            <th style=\"padding:0.75rem; text-align:left; color:var(--accent3);\">Key Features</th>\n          </tr>\n        </thead>\n        <tbody>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.04);\">\n            <td style=\"padding:0.75rem; font-weight:600;\">1948–1960</td>\n            <td style=\"padding:0.75rem;\">Open Economy</td>\n            <td style=\"padding:0.75rem; color:var(--text-muted);\">Plantation exports, minimal state intervention, free trade</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.04);\">\n            <td style=\"padding:0.75rem; font-weight:600;\">1960–1977</td>\n            <td style=\"padding:0.75rem;\">Closed / ISI</td>\n            <td style=\"padding:0.75rem; color:var(--text-muted);\">Nationalization, tariffs, import controls, state-led industry</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.04);\">\n            <td style=\"padding:0.75rem; font-weight:600;\">1977–2009</td>\n            <td style=\"padding:0.75rem;\">Liberalization</td>\n            <td style=\"padding:0.75rem; color:var(--text-muted);\">Export promotion, privatization, EPZs, garment boom</td>\n          </tr>\n          <tr style=\"border-bottom: 1px solid rgba(255,255,255,0.04);\">\n            <td style=\"padding:0.75rem; font-weight:600;\">2009–2019</td>\n            <td style=\"padding:0.75rem;\">Post-War Boom</td>\n            <td style=\"padding:0.75rem; color:var(--text-muted);\">Infrastructure, tourism, construction, rising debt</td>\n          </tr>\n          <tr>\n            <td style=\"padding:0.75rem; font-weight:600;\">2020–Now</td>\n            <td style=\"padding:0.75rem;\">Crisis &amp; IMF</td>\n            <td style=\"padding:0.75rem; color:var(--text-muted);\">Sovereign default, inflation, IMF program (2023), restructuring</td>\n          </tr>\n        </tbody>\n      </table>\n    </div>\n  </div>\n\n  <!-- 10. Current Challenges -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚠️</div>\n    <h2>Recent Challenges <span class=\"underline\"></span></h2>\n\n    <div class=\"card-grid\">\n      <div class=\"info-card\">\n        <div class=\"emoji\">💵</div>\n        <div class=\"label\">Debt Crisis</div>\n        <div class=\"desc\">Sovereign default in 2022. External debt ~$50B. Restructuring underway with IMF.</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">📈</div>\n        <div class=\"label\">Inflation</div>\n        <div class=\"desc\">Peaked at ~70% in 2022. Caused by money printing, supply shocks, currency collapse.</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🏛️</div>\n        <div class=\"label\">IMF Program</div>\n        <div class=\"desc\">$3B Extended Fund Facility (2023). Conditions: tax reforms, SOE reform, fiscal discipline.</div>\n      </div>\n      <div class=\"info-card\">\n        <div class=\"emoji\">🌍</div>\n        <div class=\"label\">External Sector</div>\n        <div class=\"desc\">Remittances down, tourism recovery slow, terms of trade deterioration.</div>\n      </div>\n    </div>\n\n    <h3>Root Causes of 2022 Crisis</h3>\n    <ul>\n      <li><strong>Tax cuts:</strong> Large tax cuts in 2019 reduced government revenue sharply</li>\n      <li><strong>Money printing:</strong> Central bank financed fiscal deficits, triggering inflation</li>\n      <li><strong>Foreign exchange shortage:</strong> Tourism collapse (COVID) + remittance drop + import bill</li>\n      <li><strong>Debt unsustainability:</strong> High borrowing for infrastructure with low returns</li>\n      <li><strong>Organic farming ban:</strong> 2021 chemical fertilizer ban devastated tea/rubber yields</li>\n    </ul>\n  </div>\n\n  <!-- 11. Interactive Quiz -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧰</div>\n    <h2>Test Your Knowledge <span class=\"underline\"></span></h2>\n\n    <div class=\"quiz-question\" data-q=\"1\">\n      <div class=\"q\">1. In which year did Sri Lanka gain independence from Britain?</div>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">1948</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">1947</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">1950</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">1972</button>\n      <div class=\"quiz-feedback\" data-feedback=\"1\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"2\">\n      <div class=\"q\">2. Which policy did Sri Lanka follow during 1960–1977?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Export-Oriented Industrialization</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Free Trade</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Import Substitution Industrialization</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Structural Adjustment</button>\n      <div class=\"quiz-feedback\" data-feedback=\"2\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"3\">\n      <div class=\"q\">3. What landmark economic reforms occurred in 1977?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Nationalization of banks</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Introduction of import controls</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Liberalization &amp; export orientation</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Adoption of central planning</button>\n      <div class=\"quiz-feedback\" data-feedback=\"3\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"4\">\n      <div class=\"q\">4. Which sector contributes the largest share to Sri Lanka's GDP (2020)?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Agriculture</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Industry</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Manufacturing</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Services</button>\n      <div class=\"quiz-feedback\" data-feedback=\"4\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"5\">\n      <div class=\"q\">5. What was a key feature of the ISI period in Sri Lanka?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Floating exchange rate</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">High tariffs and import controls</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Export processing zones</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Privatization of state enterprises</button>\n      <div class=\"quiz-feedback\" data-feedback=\"5\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"6\">\n      <div class=\"q\">6. Which institution facilitated foreign investment in Sri Lanka post-1977?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">IMF</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">World Bank</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Board of Investment (BOI)</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Central Bank</button>\n      <div class=\"quiz-feedback\" data-feedback=\"6\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"7\">\n      <div class=\"q\">7. What was a major cause of Sri Lanka's 2022 economic crisis?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Excessive exports</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Trade surplus</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Tax cuts and money printing</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Too much foreign investment</button>\n      <div class=\"quiz-feedback\" data-feedback=\"7\"></div>\n    </div>\n  </div>\n\n</div>\n\n<script>\n  const canvas = document.getElementById('particles');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  class Particle {\n    constructor() {\n      this.reset();\n    }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.5;\n      this.speedY = (Math.random() - 0.5) * 0.5;\n      this.opacity = Math.random() * 0.5 + 0.1;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n      if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(168, 85, 247, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 80; i++) particles.push(new Particle());\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 150) {\n          ctx.beginPath();\n          ctx.strokeStyle = `rgba(168, 85, 247, ${0.06 * (1 - dist / 150)})`;\n          ctx.lineWidth = 0.5;\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  const sections = document.querySelectorAll('[data-section]');\n\n  function revealSections() {\n    sections.forEach(section => {\n      const rect = section.getBoundingClientRect();\n      if (rect.top < window.innerHeight - 80) {\n        section.classList.add('visible');\n      }\n    });\n  }\n  window.addEventListener('scroll', revealSections);\n  revealSections();\n\n  const progressBar = document.getElementById('progressBar');\n\n  window.addEventListener('scroll', () => {\n    const scrollTop = window.scrollY;\n    const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n    const progress = (scrollTop / docHeight) * 100;\n    progressBar.style.width = progress + '%';\n  });\n\n  function checkAnswer(btn, isCorrect) {\n    const question = btn.closest('.quiz-question');\n    const options = question.querySelectorAll('.quiz-option');\n    const feedback = question.querySelector('.quiz-feedback');\n\n    options.forEach(opt => {\n      opt.disabled = true;\n      opt.style.cursor = 'not-allowed';\n      if (opt.dataset.correct === 'true') opt.classList.add('correct');\n    });\n\n    if (isCorrect) {\n      btn.classList.add('correct');\n      feedback.textContent = '\\u2705 Correct!';\n      feedback.className = 'quiz-feedback show correct';\n    } else {\n      btn.classList.add('wrong');\n      const correctBtn = question.querySelector('[data-correct=\"true\"]');\n      feedback.textContent = '\\u274C Incorrect. The answer was: ' + correctBtn.textContent;\n      feedback.className = 'quiz-feedback show wrong';\n    }\n  }\n</script>\n\n\n\n\n</body>\n</html>"
  },
  "business": {
    "1": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"progress-container\"><div class=\"progress-bar\" id=\"progressBar\"></div></div>\n\n<canvas id=\"particles\"></canvas>\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">Chapter 1</div>\n  <h1>Basis of Business<br>&amp; the Environment</h1>\n  <p>Exploring the foundations of business, its evolution, environment, and the forces that shape modern commerce.</p>\n  <div class=\"hero-scroll\">↓</div>\n</section>\n\n<div class=\"container\">\n\n\n\n  <!-- Concept of Business -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏭</div>\n    <h2>Concept of Business <span class=\"underline\"></span></h2>\n    <p>All the activities related to the production, distribution, selling of goods and services with a profit motive in order to satisfy human needs and wants can generally be defined as <span class=\"highlight\">business</span>.</p>\n    <p>There are also businesses which fulfill needs without a profit motive — e.g. Red Cross, Leo Club.</p>\n\n    <h3>Needs vs Wants</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">❤️ Needs</div>\n        <ul>\n          <li>Compulsory for survival</li>\n          <li>Food, clothes, house, education, health</li>\n          <li>Common to all</li>\n          <li>Essential for survival</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">✨ Wants</div>\n        <ul>\n          <li>Different ways of fulfilling needs</li>\n          <li>Unlimited &amp; vary from person to person</li>\n          <li>Can be created by businesses</li>\n          <li>Subjective</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- Characteristics -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧠</div>\n    <h2>Characteristics of a Business <span class=\"underline\"></span></h2>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">💱</div><div class=\"label\">Exchange or Selling</div><div class=\"desc\">Goods/services sold for monetary value</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📦</div><div class=\"label\">Goods &amp; Services</div><div class=\"desc\">Consumer goods &amp; industrial goods</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🔄</div><div class=\"label\">Continuous</div><div class=\"desc\">Long-term, repeated transactions</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💰</div><div class=\"label\">Profit Motive</div><div class=\"desc\">Earn money, build relationships, social welfare</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">⚠️</div><div class=\"label\">Risk</div><div class=\"desc\">Uncertainty in earning profit, possibility of loss</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💡</div><div class=\"label\">Creates Wants</div><div class=\"desc\">Produces goods/services to satisfy wants</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏢</div><div class=\"label\">Economic Activity</div><div class=\"desc\">Uses limited resources, money-oriented</div></div>\n    </div>\n  </div>\n\n  <!-- Evolution of Business -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧭</div>\n    <h2>Evolution of Business <span class=\"underline\"></span></h2>\n\n    <h3>Drawbacks of the Barter System</h3>\n    <ul>\n      <li>Lack of double coincidence of wants</li>\n      <li>Lack of a common measure of value</li>\n      <li>Indivisibility of certain goods</li>\n      <li>Difficulty in making deferred payments</li>\n      <li>Difficulty in storing value</li>\n    </ul>\n\n    <h3>Stages of Evolution</h3>\n    <div class=\"timeline\">\n      <div class=\"timeline-item\"><div class=\"title\">💱 Barter System</div><div class=\"desc\">First stage — direct exchange of goods for goods</div></div>\n      <div class=\"timeline-item\"><div class=\"title\">💰 Use of Money</div><div class=\"desc\">Materials → Metals → Coins &amp; Notes → Bank Money → Electronic Money</div></div>\n      <div class=\"timeline-item\"><div class=\"title\">🏭 Industrial Revolution</div><div class=\"desc\">Cottage industries → large scale; growth of banking, transport, insurance</div></div>\n      <div class=\"timeline-item\"><div class=\"title\">💻 Information Era</div><div class=\"desc\">E-Commerce &amp; E-Business — internet-based transactions</div></div>\n    </div>\n\n    <div class=\"formula-box\">\n      Commerce = Trade + Support Services\n    </div>\n  </div>\n\n  <!-- E-Commerce -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🌐</div>\n    <h2>E-Commerce &amp; E-Business <span class=\"underline\"></span></h2>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">💻 E-Commerce</div>\n        <ul>\n          <li>Buying &amp; selling through internet</li>\n          <li>Only transactions</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">💻 E-Business</div>\n        <ul>\n          <li>All business activities via internet</li>\n          <li>Includes communication, collaboration, etc.</li>\n        </ul>\n      </div>\n    </div>\n    <h3>E-Commerce Models</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">👥</div><div class=\"label\">B2B</div><div class=\"desc\">Business to Business</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧑</div><div class=\"label\">B2C</div><div class=\"desc\">Business to Consumer</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤝</div><div class=\"label\">C2C</div><div class=\"desc\">Consumer to Consumer</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏛️</div><div class=\"label\">G2C</div><div class=\"desc\">Government to Citizen</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏢</div><div class=\"label\">B2G</div><div class=\"desc\">Business to Government</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏰</div><div class=\"label\">G2B</div><div class=\"desc\">Government to Business</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">👤</div><div class=\"label\">C2G</div><div class=\"desc\">Citizen to Government</div></div>\n    </div>\n  </div>\n\n  <!-- Classification -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📊</div>\n    <h2>Classification of Business <span class=\"underline\"></span></h2>\n    <div class=\"three-col\">\n      <div class=\"col1\">\n        <div class=\"header\">🌿 Primary</div>\n        <ul>\n          <li>Agriculture, forestry, fishing</li>\n          <li>Mining &amp; quarrying</li>\n          <li>Extracting natural resources</li>\n        </ul>\n      </div>\n      <div class=\"col2\">\n        <div class=\"header\">🏭 Secondary</div>\n        <ul>\n          <li>Manufacturing industries</li>\n          <li>Construction industries</li>\n          <li>Converting resources</li>\n        </ul>\n      </div>\n      <div class=\"col3\">\n        <div class=\"header\">🏢 Tertiary</div>\n        <ul>\n          <li>Banking, insurance, real estate</li>\n          <li>Electricity, gas, water</li>\n          <li>Service provision</li>\n        </ul>\n      </div>\n    </div>\n    <h3>Other Bases of Classification</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🏢</div><div class=\"label\">Ownership</div><div class=\"desc\">Private sector / Public (government) sector</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🎯</div><div class=\"label\">Goals</div><div class=\"desc\">Profit motive / Non-profit motive</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📏</div><div class=\"label\">Scale</div><div class=\"desc\">Small &amp; medium / Large-scale</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌾</div><div class=\"label\">Production Sector</div><div class=\"desc\">Agriculture / Industries / Services</div></div>\n    </div>\n  </div>\n\n  <!-- Business Resources -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏗️</div>\n    <h2>Business Resources <span class=\"underline\"></span></h2>\n    <p>Inputs used for business activities:</p>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🏔️</div><div class=\"label\">Land</div><div class=\"desc\">Building site, ventilation, natural light</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧑‍🏫</div><div class=\"label\">Labour</div><div class=\"desc\">Physical &amp; mental effort of all workers</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏭</div><div class=\"label\">Capital</div><div class=\"desc\">Buildings, machines, equipment, vehicles, money</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧩</div><div class=\"label\">Entrepreneurship</div><div class=\"desc\">Decision-maker, risk-taker, profit recipient</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📋</div><div class=\"label\">Information</div><div class=\"desc\">Market data, consumer taste, tech updates</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">⏰</div><div class=\"label\">Time</div><div class=\"desc\">Working hours, machine time, decision time</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📚</div><div class=\"label\">Knowledge</div><div class=\"desc\">Patents, skills, expertise, legal knowledge</div></div>\n    </div>\n  </div>\n\n  <!-- Functions -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚙️</div>\n    <h2>Basic Functions of a Business <span class=\"underline\"></span></h2>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">📄</div><div class=\"label\">Administration</div><div class=\"desc\">Files, advice, attendance</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏭</div><div class=\"label\">Production</div><div class=\"desc\">Raw materials, inventory, quality control</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📢</div><div class=\"label\">Marketing</div><div class=\"desc\">Distribution, advertising, pricing</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💵</div><div class=\"label\">Finance</div><div class=\"desc\">Funds, salaries, investments</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤝</div><div class=\"label\">Human Resources</div><div class=\"desc\">Recruiting, training, promotion</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🔬</div><div class=\"label\">R&amp;D</div><div class=\"desc\">Innovation, product improvement</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📊</div><div class=\"label\">MIS</div><div class=\"desc\">Information systems, data updates</div></div>\n    </div>\n    <div class=\"formula-box\" style=\"font-size: 0.9rem;\">\n      Inputs (Land, Labour, Capital, Entrepreneurship, Info, Time, Knowledge) → Business Functions → Outputs (Goods &amp; Services)\n    </div>\n  </div>\n\n  <!-- Stakeholders -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">👥</div>\n    <h2>Stakeholders of a Business <span class=\"underline\"></span></h2>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">👤</div><div class=\"label\">Owners</div><div class=\"desc\">Adequate profit, growth, market share</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧑‍💼</div><div class=\"label\">Managers</div><div class=\"desc\">Maximize profit, growth, decision success</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧑‍🏫</div><div class=\"label\">Employees</div><div class=\"desc\">Higher salary, bonuses, promotions</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏦</div><div class=\"label\">Creditors</div><div class=\"desc\">Loan recovery, collateral safety</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧍</div><div class=\"label\">Customers</div><div class=\"desc\">Quality goods, responsibility, existence</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🚚</div><div class=\"label\">Suppliers</div><div class=\"desc\">Continuous orders, timely payment</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏛️</div><div class=\"label\">Government</div><div class=\"desc\">Taxes, employment, development</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏠</div><div class=\"label\">Community</div><div class=\"desc\">Environment protection, jobs</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📈</div><div class=\"label\">Potential Investors</div><div class=\"desc\">Future resource investment</div></div>\n    </div>\n  </div>\n\n  <!-- Vision Mission -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💡</div>\n    <h2>Vision, Mission &amp; Objectives <span class=\"underline\"></span></h2>\n    <div class=\"timeline\">\n      <div class=\"timeline-item\"><div class=\"title\">💡 Vision</div><div class=\"desc\">Ultimate, inspirational, long-term aspiration. \"What do we want to ultimately become?\" <span style=\"color:var(--text-muted);font-size:0.85rem;\">Ex: Google — \"Provide access to the world's information in one click\"</span></div></div>\n      <div class=\"timeline-item\"><div class=\"title\">🎯 Mission</div><div class=\"desc\">Core purpose and focus. \"Why do we exist? Who do we serve?\" <span style=\"color:var(--text-muted);font-size:0.85rem;\">Ex: Alphabet — \"Organize the world's information and make it universally accessible\"</span></div></div>\n      <div class=\"timeline-item\"><div class=\"title\">📋 Objectives</div><div class=\"desc\">Broad, long-term outcomes to fulfill the vision</div></div>\n      <div class=\"timeline-item\"><div class=\"title\">✅ SMART Goals</div><div class=\"desc\">Specific, Measurable, Achievable, Relevant, Time-bound targets</div></div>\n    </div>\n  </div>\n\n  <!-- Products -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📦</div>\n    <h2>Types of Products <span class=\"underline\"></span></h2>\n    <p>Anything of value offered to satisfy a want or need:</p>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">💠</div><div class=\"label\">Goods</div><div class=\"desc\">Tangible — Dyson vacuum, Levi's jeans</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏭</div><div class=\"label\">Services</div><div class=\"desc\">Intangible — Doctor, Spotify, bank loan</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💡</div><div class=\"label\">Ideas</div><div class=\"desc\">Concepts, restructuring plans, campaigns</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🎬</div><div class=\"label\">Experiences</div><div class=\"desc\">Cooking class, hot-air balloon, VIP tour</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🎉</div><div class=\"label\">Events</div><div class=\"desc\">FIFA World Cup, CES, music festival</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">👤</div><div class=\"label\">People</div><div class=\"desc\">Messi, Oprah — talent/fame as product</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏔️</div><div class=\"label\">Places</div><div class=\"desc\">Destinations, real estate, waterfront</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏛️</div><div class=\"label\">Organizations</div><div class=\"desc\">WWF, TED, alumni associations</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📊</div><div class=\"label\">Information</div><div class=\"desc\">WSJ subscription, market reports</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏷️</div><div class=\"label\">Property</div><div class=\"desc\">Stock certificates, software licenses</div></div>\n    </div>\n  </div>\n\n  <!-- Business Environment -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🌍</div>\n    <h2>Business Environment <span class=\"underline\"></span></h2>\n    <p>The environment in which the factors which influence the business operates is known as <span class=\"highlight\">business environment</span>.</p>\n\n    <h3>Internal Environment</h3>\n    <p>Forces and conditions within the organization: <span class=\"tag tag-green\">Owners</span> <span class=\"tag tag-green\">Managers</span> <span class=\"tag tag-green\">Employees</span> <span class=\"tag tag-green\">Organization Culture</span> <span class=\"tag tag-green\">Organization Structure</span> <span class=\"tag tag-green\">Resources</span></p>\n\n    <h3>External Environment</h3>\n\n    <h4>Task (Immediate) Environment</h4>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🧍</div><div class=\"label\">Customers</div><div class=\"desc\">Buyers of goods/services</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🚚</div><div class=\"label\">Suppliers</div><div class=\"desc\">Providers of resources</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤛</div><div class=\"label\">Competitors</div><div class=\"desc\">Similar goods/services providers</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🔄</div><div class=\"label\">Substitute Producers</div><div class=\"desc\">Alternative product suppliers</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📈</div><div class=\"label\">Potential Entrants</div><div class=\"desc\">Future market entrants</div></div>\n    </div>\n\n    <h4>Macro (General) Environment</h4>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">⚖️</div><div class=\"label\">Political</div><div class=\"desc\">Govt policies, political vision</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📜</div><div class=\"label\">Legal</div><div class=\"desc\">Acts, rules, regulations</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💰</div><div class=\"label\">Economic</div><div class=\"desc\">Inflation, interest, GDP, employment</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌍</div><div class=\"label\">Social &amp; Cultural</div><div class=\"desc\">Beliefs, values, customs, religion</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📱</div><div class=\"label\">Technological</div><div class=\"desc\">New inventions, rapid change</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📊</div><div class=\"label\">Demographic</div><div class=\"desc\">Population size, age, gender, education</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌿</div><div class=\"label\">Natural</div><div class=\"desc\">Resources, climate, location, disasters</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌐</div><div class=\"label\">Global</div><div class=\"desc\">Trade agreements, trade blocs, WTO</div></div>\n    </div>\n  </div>\n\n  <!-- Challenges & Trends -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📈</div>\n    <h2>Modern Challenges &amp; Trends <span class=\"underline\"></span></h2>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">⚠️ Challenges</div>\n        <ul>\n          <li>Customer empowerment (social media)</li>\n          <li>Strict environmental rules</li>\n          <li>Rapid technology change (AI)</li>\n          <li>Globalization threats</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">📈 Trends</div>\n        <ul>\n          <li>E-money &amp; digital payments</li>\n          <li>CSR &amp; green products</li>\n          <li>Outsourcing &amp; digitalization</li>\n          <li>Sustainable development</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"info-card\">\n      <div class=\"emoji\">🌐</div>\n      <div class=\"label\">Globalization</div>\n      <div class=\"desc\">The process by which businesses, cultures, and economies integrate worldwide through trade, investment, technology, and information flow.</div>\n    </div>\n  </div>\n\n  <!-- Quiz -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧰</div>\n    <h2>Test Your Knowledge <span class=\"underline\"></span></h2>\n\n    <div class=\"quiz-question\" data-q=\"1\">\n      <div class=\"q\">1. Which of the following is NOT a characteristic of a business?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Exchange or selling takes place</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Continuous transactions</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">One-time transaction</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Involves risk</button>\n      <div class=\"quiz-feedback\" data-feedback=\"1\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"2\">\n      <div class=\"q\">2. What is the correct formula for Commerce?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Commerce = Trade + Production</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Commerce = Trade + Support Services</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Commerce = Production + Distribution</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Commerce = Marketing + Sales</button>\n      <div class=\"quiz-feedback\" data-feedback=\"2\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"3\">\n      <div class=\"q\">3. Mining and quarrying belong to which sector?</div>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Primary Sector</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Secondary Sector</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Tertiary Sector</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Quaternary Sector</button>\n      <div class=\"quiz-feedback\" data-feedback=\"3\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"4\">\n      <div class=\"q\">4. In the B2C e-commerce model, who are the participants?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Government and Citizen</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Business and Consumer</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Consumer and Consumer</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Business and Government</button>\n      <div class=\"quiz-feedback\" data-feedback=\"4\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"5\">\n      <div class=\"q\">5. Which is NOT a resource/input for business activities?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Land</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Entrepreneurship</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Information</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Advertising</button>\n      <div class=\"quiz-feedback\" data-feedback=\"5\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"6\">\n      <div class=\"q\">6. The ultimate, inspirational long-term aspiration of an organization is its:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Mission</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Vision</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Goal</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Objective</button>\n      <div class=\"quiz-feedback\" data-feedback=\"6\"></div>\n    </div>\n  </div>\n</div>\n\n<script>\n  // Particles\n  const canvas = document.getElementById('particles');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  class Particle {\n    constructor() { this.reset(); }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 1.5 + 0.3;\n      this.speedX = (Math.random() - 0.5) * 0.4;\n      this.speedY = (Math.random() - 0.5) * 0.4;\n      this.opacity = Math.random() * 0.4 + 0.08;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n      if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(16, 185, 129, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 20; i++) particles.push(new Particle());\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 120) {\n          ctx.beginPath();\n          ctx.strokeStyle = `rgba(16, 185, 129, ${0.03 * (1 - dist / 120)})`;\n          ctx.lineWidth = 0.3;\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  // Scroll reveal\n  const sections = document.querySelectorAll('[data-section]');\n\n  function revealSections() {\n    sections.forEach(section => {\n      const rect = section.getBoundingClientRect();\n      if (rect.top < window.innerHeight - 80) {\n        section.classList.add('visible');\n      }\n    });\n  }\n  window.addEventListener('scroll', revealSections);\n  revealSections();\n\n  // Progress bar\n  const progressBar = document.getElementById('progressBar');\n  window.addEventListener('scroll', () => {\n    const scrollTop = window.scrollY;\n    const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n    progressBar.style.width = (scrollTop / docHeight) * 100 + '%';\n  });\n\n  // Quiz\n  function checkAnswer(btn, isCorrect) {\n    const question = btn.closest('.quiz-question');\n    const options = question.querySelectorAll('.quiz-option');\n    const feedback = question.querySelector('.quiz-feedback');\n\n    options.forEach(opt => {\n      opt.disabled = true;\n      opt.style.cursor = 'not-allowed';\n      if (opt.dataset.correct === 'true') opt.classList.add('correct');\n    });\n\n    if (isCorrect) {\n      btn.classList.add('correct');\n      feedback.innerHTML = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg> Correct!';\n      feedback.className = 'quiz-feedback show correct';\n    } else {\n      btn.classList.add('wrong');\n      const correctBtn = question.querySelector('[data-correct=\"true\"]');\n      feedback.textContent = '❌ Incorrect. The answer was: ' + correctBtn.textContent;\n      feedback.className = 'quiz-feedback show wrong';\n    }\n  }\n</script>\n\n\n\n\n</body>\n</html>",
    "2": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"progress-container\"><div class=\"progress-bar\" id=\"progressBar\"></div></div>\n\n<canvas id=\"particles\"></canvas>\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">Lesson 2</div>\n  <h1>Social Responsibility<br>&amp; Business Ethics</h1>\n  <p>Understanding how businesses balance profit with accountability to stakeholders, society, and the environment.</p>\n  <div class=\"hero-scroll\">↓</div>\n</section>\n\n<div class=\"container\">\n\n\n\n  <!-- Social Responsibility -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🤝</div>\n    <h2>Social Responsibility <span class=\"underline\"></span></h2>\n    <p>The obligation of a business to perform its activities in an unbiased way and act favorably toward all stakeholders — <span class=\"highlight\">social responsibility</span> goes beyond legal obligations to include ethical and discretionary expectations.</p>\n\n    <h3>Key Definitions</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🌍</div><div class=\"label\">World Business Council</div><div class=\"desc\">\"The commitment of a business to contribute to sustainable economic development, working with employees, their families, and the local community.\"</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧬</div><div class=\"label\">Mallen Baker</div><div class=\"desc\">\"Companies treat stakeholders ethically &amp; responsibly beyond legal requirements.\"</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📚</div><div class=\"label\">Narayan Moorthy</div><div class=\"desc\">\"Social responsibility is the intelligent &amp; objective concern for the welfare of society that restrains individual/group behavior from destructive activities.\"</div></div>\n    </div>\n\n    <h3>Country Perspectives</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🇺🇸 USA</div>\n        <ul>\n          <li>Personal responsibility approach</li>\n          <li>Individuals and firms focus on profitability first</li>\n          <li>Legal compliance as baseline</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🇵🇭 Philippines</div>\n        <ul>\n          <li>Giving back to community</li>\n          <li>Strong tradition of helping others</li>\n          <li>CSR embedded in culture</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Developing Forces</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🏆</div><div class=\"label\">Competition</div><div class=\"desc\">Firms differentiate through ethical practices</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌐</div><div class=\"label\">Globalization</div><div class=\"desc\">Cross-border expectations for responsible conduct</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💻</div><div class=\"label\">E-Business</div><div class=\"desc\">Transparency demands from digital transactions</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏘️</div><div class=\"label\">Environmental Pollution</div><div class=\"desc\">Pressure for eco-friendly operations</div></div>\n    </div>\n  </div>\n\n  <!-- Parties to Whom Business Has Social Responsibility -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">👥</div>\n    <h2>Parties with Social Responsibility Claims <span class=\"underline\"></span></h2>\n    <p>A business has social responsibilities toward four key stakeholder groups:</p>\n\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🧍</div><div class=\"label\">Customers</div><div class=\"desc\">Quality products at reasonable price, harmless goods, accurate information</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧑‍💼</div><div class=\"label\">Employees</div><div class=\"desc\">Job rights, fair wages, safe facilities, growth opportunities</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">👤</div><div class=\"label\">Owners</div><div class=\"desc\">Reasonable earnings &amp; profit, transparent reporting</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏠</div><div class=\"label\">Society</div><div class=\"desc\">Eco-friendly operations, community development, ethical practices</div></div>\n    </div>\n\n    <h3>Responsibilities Explained</h3>\n    <div class=\"three-col\">\n      <div class=\"col1\">\n        <div class=\"header\">🧍 Customers</div>\n        <ul>\n          <li>Fair pricing</li>\n          <li>Safe, quality goods</li>\n          <li>Honest advertising</li>\n          <li>After-sales service</li>\n        </ul>\n      </div>\n      <div class=\"col2\">\n        <div class=\"header\">🧑‍💼 Employees</div>\n        <ul>\n          <li>Job security</li>\n          <li>Safe workplace</li>\n          <li>Fair compensation</li>\n          <li>Training &amp; growth</li>\n        </ul>\n      </div>\n      <div class=\"col3\">\n        <div class=\"header\">🏠 Society</div>\n        <ul>\n          <li>Pollution control</li>\n          <li>Waste management</li>\n          <li>Community welfare</li>\n          <li>Ethical governance</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- Benefits of Fulfilling Social Responsibility -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">✨</div>\n    <h2>Benefits of Fulfilling Social Responsibility <span class=\"underline\"></span></h2>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🏭</div><div class=\"label\">Ensure Business Existence</div><div class=\"desc\">Long-term viability through stakeholder trust</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💰</div><div class=\"label\">Develop Goodwill &amp; Image</div><div class=\"desc\">Positive public perception &amp; brand reputation</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤝</div><div class=\"label\">Ensure Trust</div><div class=\"desc\">Builds confidence among all stakeholders</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧍</div><div class=\"label\">Satisfy Customers</div><div class=\"desc\">Loyal customer base through ethical practices</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🎯</div><div class=\"label\">Achieve Objectives</div><div class=\"desc\">Aligns profit goals with social good</div></div>\n    </div>\n  </div>\n\n  <!-- Sustainable Development -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🌿</div>\n    <h2>Sustainable Development <span class=\"underline\"></span></h2>\n    <p><span class=\"highlight\">Sustainable development</span> is development that meets the needs of the present without compromising the ability of future generations to meet their own needs.</p>\n\n    <div class=\"quote-box\">\n      \"When the last tree is cut, the last river poisoned, and the last fish dead, we will discover that we cannot eat money.\"\n      <span class=\"author\">— Seattle, Red Indian Leader</span>\n    </div>\n\n    <h3>Three Core Pillars</h3>\n    <div class=\"three-col\">\n      <div class=\"col1\">\n        <div class=\"header\">💰 Economic</div>\n        <ul>\n          <li>Improve human welfare</li>\n          <li>Reduce resource consumption</li>\n          <li>Eco-friendly affordable products</li>\n          <li>Sustainable growth</li>\n        </ul>\n      </div>\n      <div class=\"col2\">\n        <div class=\"header\">🌿 Environmental</div>\n        <ul>\n          <li>Limited resources</li>\n          <li>Clean air &amp; water</li>\n          <li>Protect biodiversity</li>\n          <li>Combat global warming</li>\n          <li>Stop deforestation</li>\n        </ul>\n      </div>\n      <div class=\"col3\">\n        <div class=\"header\">👥 Social</div>\n        <ul>\n          <li>Equality &amp; equity</li>\n          <li>Social capital</li>\n          <li>Human rights</li>\n          <li>Social justice</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- Business Contributions to Sustainability -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏗️</div>\n    <h2>Business Contributions to Sustainability <span class=\"underline\"></span></h2>\n\n    <h3>Economic Contributions</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🧑‍🏫</div><div class=\"label\">Job Designing</div><div class=\"desc\">Create meaningful, efficient roles</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💡</div><div class=\"label\">Empowering Skills</div><div class=\"desc\">Training &amp; capability building</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏭</div><div class=\"label\">Efficient Resource Use</div><div class=\"desc\">Optimize capital &amp; resource utilization</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">⚠️</div><div class=\"label\">Risk Management</div><div class=\"desc\">Mitigate financial &amp; operational risks</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🔬</div><div class=\"label\">Innovation &amp; Tech</div><div class=\"desc\">R&amp;D for sustainable solutions</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏗️</div><div class=\"label\">Infrastructure</div><div class=\"desc\">Build community &amp; industrial infrastructure</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">❤️</div><div class=\"label\">Employee Welfare</div><div class=\"desc\">Health, safety &amp; well-being programs</div></div>\n    </div>\n\n    <h3>Environmental Contributions</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🌿</div><div class=\"label\">Eco-Friendly Products</div><div class=\"desc\">Green design &amp; sustainable materials</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">♻️</div><div class=\"label\">3R / 4R / 5R</div><div class=\"desc\">Reduce, Reuse, Recycle framework</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">☀️</div><div class=\"label\">Renewable Energy</div><div class=\"desc\">Solar, wind, hydro power adoption</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏘️</div><div class=\"label\">Pollution Minimization</div><div class=\"desc\">Emission controls &amp; waste treatment</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🦌</div><div class=\"label\">Biodiversity Protection</div><div class=\"desc\">Conserve ecosystems &amp; wildlife</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📜</div><div class=\"label\">Environmental Regulations</div><div class=\"desc\">Compliance with environmental laws</div></div>\n    </div>\n\n    <h3>Social &amp; Cultural Contributions</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">🏠</div><div class=\"label\">Standard of Living</div><div class=\"desc\">Improve quality of life</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">⚖️</div><div class=\"label\">Equal Opportunities</div><div class=\"desc\">Fair hiring &amp; promotion practices</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤝</div><div class=\"label\">Social Integrity</div><div class=\"desc\">Honest, transparent business conduct</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧑‍🎓</div><div class=\"label\">Human Capital</div><div class=\"desc\">Education &amp; skill development</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏮</div><div class=\"label\">Local Traditions</div><div class=\"desc\">Preserve cultural heritage</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💸</div><div class=\"label\">Poverty Reduction</div><div class=\"desc\">Economic inclusion &amp; fair wages</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌍</div><div class=\"label\">Human Rights</div><div class=\"desc\">Respect fundamental freedoms</div></div>\n    </div>\n  </div>\n\n  <!-- 4R Concept -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">♻️</div>\n    <h2>4R Concept for Sustainability <span class=\"underline\"></span></h2>\n    <p>The <span class=\"highlight\">4R framework</span> guides businesses in minimizing environmental impact through waste management and resource conservation.</p>\n\n    <div class=\"four-col\">\n      <div class=\"col1\">\n        <div class=\"header\">♻️ Recycle</div>\n        <ul>\n          <li>Waste → new materials</li>\n          <li><strong>Upcycle:</strong> hay → paper</li>\n          <li><strong>Low cycle:</strong> vehicles → iron</li>\n          <li>Reduces landfill waste</li>\n        </ul>\n      </div>\n      <div class=\"col2\">\n        <div class=\"header\">🔄 Reuse</div>\n        <ul>\n          <li>Using products repeatedly</li>\n          <li>Lunch boxes instead of sheets</li>\n          <li>Refillable containers</li>\n          <li>Extends product lifecycle</li>\n        </ul>\n      </div>\n      <div class=\"col3\">\n        <div class=\"header\">➖ Reduce</div>\n        <ul>\n          <li>Minimizing waste generation</li>\n          <li>No non-degradable polythene</li>\n          <li>No plastic bottles</li>\n          <li>Lower resource consumption</li>\n        </ul>\n      </div>\n      <div class=\"col4\">\n        <div class=\"header\">🔄 Replace</div>\n        <ul>\n          <li>Replacing consumed resources</li>\n          <li>Reforestation</li>\n          <li>Fish farming</li>\n          <li>Renewable resource regeneration</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- Adverse Effects of Business Activities -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚠️</div>\n    <h2>Adverse Effects of Business Activities <span class=\"underline\"></span></h2>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">📢</div><div class=\"label\">Low Quality Imports</div><div class=\"desc\">Inferior goods harm local industries &amp; consumers</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🚧</div><div class=\"label\">Misleading Customers</div><div class=\"desc\">False advertising &amp; deceptive practices</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🧑‍💼</div><div class=\"label\">Poor Employee Welfare</div><div class=\"desc\">Unfair wages, unsafe conditions, exploitation</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🗑️</div><div class=\"label\">Resource Waste</div><div class=\"desc\">Overconsumption of natural &amp; material resources</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏘️</div><div class=\"label\">Pollution</div><div class=\"desc\">Air, water, land &amp; noise pollution</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🎬</div><div class=\"label\">Inappropriate Ads &amp; Culture</div><div class=\"desc\">Harmful stereotypes &amp; cultural erosion</div></div>\n    </div>\n  </div>\n\n  <!-- Business Ethics & Code of Ethics -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚖️</div>\n    <h2>Business Ethics &amp; Code of Ethics <span class=\"underline\"></span></h2>\n    <p><span class=\"highlight\">Business ethics</span> refers to acting favorably toward all parties by acknowledging what is good and bad in business conduct. It provides a moral framework for decision-making.</p>\n\n    <h3>Examples of Business Ethics</h3>\n    <ul>\n      <li><span class=\"tag tag-green\">Quality Goods</span> Building trust through consistent product standards</li>\n      <li><span class=\"tag tag-light\">Ethical Accounting</span> Transparent financial reporting prevents misconduct</li>\n      <li><span class=\"tag tag-amber\">Fair HR Management</span> Equitable hiring, promotion, and compensation</li>\n    </ul>\n\n    <h3>Key Factors for a Code of Ethics</h3>\n    <div class=\"pill-list\">\n      <span class=\"pill\">🏭 Nature of Business</span>\n      <span class=\"pill\">🧍 Customers</span>\n      <span class=\"pill\">🧑‍💼 Employees</span>\n      <span class=\"pill\">🤛 Competition</span>\n      <span class=\"pill\">🌍 Socio-Culture</span>\n      <span class=\"pill\">🏢 Organizational Culture</span>\n      <span class=\"pill\">✅ Practicableness</span>\n    </div>\n  </div>\n\n  <!-- Flashcards -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💠</div>\n    <h2>Key Terms <span class=\"underline\"></span></h2>\n    <p>Click each card to reveal the definition.</p>\n\n    <div class=\"flashcard-container\">\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            Social Responsibility\n            <div class=\"flashcard-hint\">tap to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Performing business activities in an unbiased way to all stakeholders, going beyond legal requirements.\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            Sustainable Development\n            <div class=\"flashcard-hint\">tap to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Meeting present needs without compromising the ability of future generations to meet their own needs.\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            4R Concept\n            <div class=\"flashcard-hint\">tap to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            Recycle, Reuse, Reduce, Replace — a framework for waste management and resource conservation.\n          </div>\n        </div>\n      </div>\n\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">\n            Code of Ethics\n            <div class=\"flashcard-hint\">tap to reveal</div>\n          </div>\n          <div class=\"flashcard-back\">\n            A formal document outlining acceptable conduct, shaped by business nature, customers, employees, competition, socio-culture, and organizational culture.\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Comparison Tables -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📊</div>\n    <h2>Comparison Tables <span class=\"underline\"></span></h2>\n\n    <h3>Sustainability Pillars</h3>\n    <div class=\"three-col\">\n      <div class=\"col1\">\n        <div class=\"header\">💰 Economic</div>\n        <ul>\n          <li>Improve human welfare</li>\n          <li>Reduce resource consumption</li>\n          <li>Eco-friendly affordable products</li>\n          <li>Focus: growth &amp; efficiency</li>\n        </ul>\n      </div>\n      <div class=\"col2\">\n        <div class=\"header\">🌿 Environmental</div>\n        <ul>\n          <li>Clean air &amp; water</li>\n          <li>Biodiversity protection</li>\n          <li>Combat global warming</li>\n          <li>Focus: planet preservation</li>\n        </ul>\n      </div>\n      <div class=\"col3\">\n        <div class=\"header\">👥 Social</div>\n        <ul>\n          <li>Equality &amp; human rights</li>\n          <li>Social capital &amp; justice</li>\n          <li>Community well-being</li>\n          <li>Focus: people &amp; equity</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>4R Comparison</h3>\n    <div class=\"four-col\">\n      <div class=\"col1\">\n        <div class=\"header\">♻️ Recycle</div>\n        <ul>\n          <li>Process waste into new</li>\n          <li>Upcycle &amp; low cycle</li>\n          <li>Requires processing</li>\n        </ul>\n      </div>\n      <div class=\"col2\">\n        <div class=\"header\">🔄 Reuse</div>\n        <ul>\n          <li>Same product multiple uses</li>\n          <li>Minimal processing</li>\n          <li>Extends product life</li>\n        </ul>\n      </div>\n      <div class=\"col3\">\n        <div class=\"header\">➖ Reduce</div>\n        <ul>\n          <li>Minimize waste at source</li>\n          <li>Preventive approach</li>\n          <li>Most effective</li>\n        </ul>\n      </div>\n      <div class=\"col4\">\n        <div class=\"header\">🔄 Replace</div>\n        <ul>\n          <li>Regenerate consumed resources</li>\n          <li>Restorative action</li>\n          <li>Reforestation, fish farming</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- Quiz -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧰</div>\n    <h2>Test Your Knowledge <span class=\"underline\"></span></h2>\n\n    <div class=\"quiz-question\" data-q=\"1\">\n      <div class=\"q\">1. Which of the following best defines social responsibility?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Maximizing profit at all costs</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Performing business activities in an unbiased way to all stakeholders</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Following only legal requirements</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Reducing employee wages to save costs</button>\n      <div class=\"quiz-feedback\" data-feedback=\"1\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"2\">\n      <div class=\"q\">2. According to the World Commission, sustainable development means:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Using all resources as quickly as possible</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Focusing only on economic growth</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Meeting present needs without compromising future generations</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Prioritizing business profit over environment</button>\n      <div class=\"quiz-feedback\" data-feedback=\"2\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"3\">\n      <div class=\"q\">3. Which \"R\" involves processing waste materials into new products?</div>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Recycle</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Reuse</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Reduce</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Replace</button>\n      <div class=\"quiz-feedback\" data-feedback=\"3\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"4\">\n      <div class=\"q\">4. To which party does a business have the responsibility of providing quality products at reasonable prices?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Employees</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Owners</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Customers</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Society</button>\n      <div class=\"quiz-feedback\" data-feedback=\"4\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"5\">\n      <div class=\"q\">5. Who said, \"When the last tree is cut, the last river poisoned, and the last fish dead, we will discover that we cannot eat money\"?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">World Business Council</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Narayan Moorthy</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Seattle - Red Indian Leader</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Mallen Baker</button>\n      <div class=\"quiz-feedback\" data-feedback=\"5\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"6\">\n      <div class=\"q\">6. Which is NOT one of the three core pillars of sustainable development?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Economic</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Environmental</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Social</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Political</button>\n      <div class=\"quiz-feedback\" data-feedback=\"6\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"7\">\n      <div class=\"q\">7. Business ethics primarily deals with:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Maximizing shareholder returns</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Acting favorably to all parties by acknowledging good and bad conduct</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Following government regulations only</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Reducing operational costs</button>\n      <div class=\"quiz-feedback\" data-feedback=\"7\"></div>\n    </div>\n  </div>\n\n</div>\n\n<script>\n  const canvas = document.getElementById('particles');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  class Particle {\n    constructor() { this.reset(); }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2.5 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.4;\n      this.speedY = (Math.random() - 0.5) * 0.4;\n      this.opacity = Math.random() * 0.4 + 0.08;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n      if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(16, 185, 129, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 80; i++) particles.push(new Particle());\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 150) {\n          ctx.beginPath();\n          ctx.strokeStyle = `rgba(16, 185, 129, ${0.05 * (1 - dist / 150)})`;\n          ctx.lineWidth = 0.5;\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  const sections = document.querySelectorAll('[data-section]');\n\n  function revealSections() {\n    sections.forEach(section => {\n      const rect = section.getBoundingClientRect();\n      if (rect.top < window.innerHeight - 80) {\n        section.classList.add('visible');\n      }\n    });\n  }\n  window.addEventListener('scroll', revealSections);\n  revealSections();\n\n  const progressBar = document.getElementById('progressBar');\n  window.addEventListener('scroll', () => {\n    const scrollTop = window.scrollY;\n    const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n    progressBar.style.width = (scrollTop / docHeight) * 100 + '%';\n  });\n\n  function flipCard(card) {\n    card.classList.toggle('flipped');\n  }\n\n  function checkAnswer(btn, isCorrect) {\n    const question = btn.closest('.quiz-question');\n    const options = question.querySelectorAll('.quiz-option');\n    const feedback = question.querySelector('.quiz-feedback');\n\n    options.forEach(opt => {\n      opt.disabled = true;\n      opt.style.cursor = 'not-allowed';\n      if (opt.dataset.correct === 'true') opt.classList.add('correct');\n    });\n\n    if (isCorrect) {\n      btn.classList.add('correct');\n      feedback.innerHTML = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg> Correct!';\n      feedback.className = 'quiz-feedback show correct';\n    } else {\n      btn.classList.add('wrong');\n      const correctBtn = question.querySelector('[data-correct=\"true\"]');\n      feedback.textContent = '❌ Incorrect. The answer was: ' + correctBtn.textContent;\n      feedback.className = 'quiz-feedback show wrong';\n    }\n  }\n</script>\n\n\n\n\n</body>\n</html>",
    "3": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"progress-container\"><div class=\"progress-bar\" id=\"progressBar\"></div></div>\n\n<canvas id=\"particles\"></canvas>\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">Lesson 3</div>\n  <h1>Business-Government<br>Relations &amp; Consumer<br>Protection</h1>\n  <p>Government influence on businesses, fiscal &amp; monetary policy, and the framework of consumer protection.</p>\n  <div class=\"hero-scroll\">↓</div>\n</section>\n\n<div class=\"container\">\n\n\n\n  <!-- Government Influence on Businesses -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏛️</div>\n    <h2>Government Influence on Businesses <span class=\"underline\"></span></h2>\n    <p>The government influences businesses through <span class=\"highlight\">three levels</span> of administration:</p>\n\n    <div class=\"three-col\">\n      <div class=\"col1\">\n        <div class=\"header\">🏛️ Central Government</div>\n        <ul>\n          <li>National-level decision making</li>\n          <li>Legislation &amp; parliament</li>\n          <li>Monetary &amp; fiscal policy</li>\n          <li>National infrastructure</li>\n        </ul>\n      </div>\n      <div class=\"col2\">\n        <div class=\"header\">🏢 Provincial Councils</div>\n        <ul>\n          <li>Provincial-level administration</li>\n          <li>Regional development</li>\n          <li>Provincial roads &amp; services</li>\n          <li>Business names charter</li>\n        </ul>\n      </div>\n      <div class=\"col3\">\n        <div class=\"header\">🏠 Local Authorities</div>\n        <ul>\n          <li>Urban / Town / Municipal councils</li>\n          <li>Local waste removal</li>\n          <li>Building local markets</li>\n          <li>Environmental policies</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- Ways Government Interferes -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚔️</div>\n    <h2>Ways Government Interferes in Business <span class=\"underline\"></span></h2>\n\n    <h3>1. 🏗️ Providing Infrastructure</h3>\n    <div class=\"three-col\">\n      <div class=\"col1\"><div class=\"header\">Central</div><ul><li>Electricity generation &amp; distribution</li></ul></div>\n      <div class=\"col2\"><div class=\"header\">Provincial</div><ul><li>Road construction &amp; maintenance</li></ul></div>\n      <div class=\"col3\"><div class=\"header\">Local</div><ul><li>Waste removal &amp; sanitation</li></ul></div>\n    </div>\n\n    <h3>2. 🤛 Being a Competitor</h3>\n    <div class=\"three-col\">\n      <div class=\"col1\"><div class=\"header\">Central</div><ul><li>Government TV channels</li></ul></div>\n      <div class=\"col2\"><div class=\"header\">Provincial</div><ul><li>Conducting businesses directly</li></ul></div>\n      <div class=\"col3\"><div class=\"header\">Local</div><ul><li>Building public markets</li></ul></div>\n    </div>\n\n    <h3>3. 👥 Being a Customer</h3>\n    <div class=\"three-col\">\n      <div class=\"col1\"><div class=\"header\">Central</div><ul><li>Buying paddy, Lak Sathosa</li></ul></div>\n      <div class=\"col2\"><div class=\"header\">Provincial</div><ul><li>Defence services procurement</li></ul></div>\n      <div class=\"col3\"><div class=\"header\">Local</div><ul><li>Maintaining cemeteries</li></ul></div>\n    </div>\n\n    <h3>4. 📄 Forming Policies</h3>\n    <div class=\"three-col\">\n      <div class=\"col1\"><div class=\"header\">Central</div><ul><li>Monetary &amp; fiscal policy</li></ul></div>\n      <div class=\"col2\"><div class=\"header\">Provincial</div><ul><li>Business names charter</li></ul></div>\n      <div class=\"col3\"><div class=\"header\">Local</div><ul><li>Environmental policies</li></ul></div>\n    </div>\n  </div>\n\n  <!-- Economic Goals of Government -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🎯</div>\n    <h2>Economic Goals of Government <span class=\"underline\"></span></h2>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">📈</div><div class=\"label\">Economic Growth &amp; Development</div><div class=\"desc\">Continuous production growth + long-term human/social progress</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤝</div><div class=\"label\">Full Employment</div><div class=\"desc\">All willing labour and resources occupied effectively</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">⚖️</div><div class=\"label\">Fair Income Distribution</div><div class=\"desc\">Equal distribution of total production among citizens</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📊</div><div class=\"label\">Economic Stability</div><div class=\"desc\">Enduring crises nationally &amp; internationally</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌐</div><div class=\"label\">Favourable International Trade</div><div class=\"desc\">Protecting balance of payments</div></div>\n    </div>\n\n    <h3>Two Dimensions of Economic Stability</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">💵 Internal Price Stability</div>\n        <ul>\n          <li>Inflation control</li>\n          <li>Stable price level</li>\n          <li>Stable interest rate</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🌍 External Price Stability</div>\n        <ul>\n          <li>Foreign exchange rate stability</li>\n          <li>Balance of payments protection</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- Businesses Contribution -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💪</div>\n    <h2>How Businesses Contribute to Government Economic Goals <span class=\"underline\"></span></h2>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">💳</div><div class=\"label\">Payment of Taxes</div><div class=\"desc\">Without evasion — funds government operations</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌿</div><div class=\"label\">Use of Indigenous Resources</div><div class=\"desc\">Promotes local industry &amp; self-reliance</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📄</div><div class=\"label\">Following Govt Policies</div><div class=\"desc\">Adhering to fiscal &amp; monetary policy</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📜</div><div class=\"label\">Following Rules &amp; Regulations</div><div class=\"desc\">Compliance with legal frameworks</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">👥</div><div class=\"label\">Contribution to Employment</div><div class=\"desc\">Job creation across sectors</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌿</div><div class=\"label\">Minimizing Environmental Damage</div><div class=\"desc\">Sustainable business practices</div></div>\n    </div>\n  </div>\n\n  <!-- Fiscal Policy -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">💰</div>\n    <h2>Fiscal Policy <span class=\"underline\"></span></h2>\n    <p>Functions related to <span class=\"highlight\">government revenue and expenditure</span>.</p>\n\n    <h3>Government Revenue</h3>\n    <div class=\"formula-box\">\n      Govt Revenue = Tax Revenue + Non-tax Revenue\n    </div>\n\n    <h3>Types of Taxes</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">💵</div><div class=\"label\">Income Tax</div><div class=\"desc\">Corporation tax, PAYE tax on earnings</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">💲</div><div class=\"label\">Value Added Tax (VAT)</div><div class=\"desc\">On wholesale/retail transactions &amp; exports</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🍺</div><div class=\"label\">Excise Duties</div><div class=\"desc\">On liquor, tobacco, &amp; similar goods</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🚚</div><div class=\"label\">Customs Duties</div><div class=\"desc\">On imported goods</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📊</div><div class=\"label\">Other Taxes</div><div class=\"desc\">Development tax, Cess, Telecom tax</div></div>\n    </div>\n\n    <h3>Direct vs Indirect Tax</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">💰 Direct Tax</div>\n        <ul>\n          <li>Paid by the liable party directly</li>\n          <li>Cannot be transferred to another</li>\n          <li>Ex: Income tax, Corporation tax</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🔄 Indirect Tax</div>\n        <ul>\n          <li>Can be transferred to another party</li>\n          <li>Passed on through prices</li>\n          <li>Ex: VAT, Excise duties, Customs duties</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Government Expenditure</h3>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🔄 Recurrent Expenditure</div>\n        <ul>\n          <li>Salaries &amp; wages</li>\n          <li>Interest payments</li>\n          <li>Ongoing operational costs</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🏗️ Capital Expenditure</div>\n        <ul>\n          <li>Roads &amp; bridges</li>\n          <li>Infrastructure projects</li>\n          <li>Long-term asset creation</li>\n        </ul>\n      </div>\n    </div>\n\n    <h3>Impact of Fiscal Policy on Businesses</h3>\n    <ul>\n      <li><span class=\"highlight\">Customs duties</span> protect local industries from foreign competition</li>\n      <li><span class=\"highlight\">Taxes on inland products</span> raise prices of goods</li>\n      <li><span class=\"highlight\">Government spending</span> on infrastructure simplifies business operations</li>\n    </ul>\n  </div>\n\n  <!-- Monetary Policy -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏦</div>\n    <h2>Monetary Policy <span class=\"underline\"></span></h2>\n    <p>Policy to control <span class=\"highlight\">money supply</span> in the economy. Executed by the <span class=\"highlight\">Central Bank of Sri Lanka</span>.</p>\n    <p><strong>Main aim:</strong> <span class=\"tag tag-amber\">Price Stability</span> <span class=\"tag tag-amber\">Inflation Control</span></p>\n\n    <h3>Key Instruments of Monetary Policy</h3>\n\n    <h4>1. 💵 Interest Rate (Standing Facility Rates)</h4>\n    <div class=\"three-col\">\n      <div class=\"col1\">\n        <div class=\"header\">SDFR</div>\n        <ul><li>Standing Deposit Facility Rate</li><li>Paid when banks invest surplus in govt securities</li></ul>\n      </div>\n      <div class=\"col2\">\n        <div class=\"header\">SLFR</div>\n        <ul><li>Standing Lending Facility Rate</li><li>Charged when banks borrow pledging securities</li></ul>\n      </div>\n      <div class=\"col3\">\n        <div class=\"header\">Bank Interest Rate</div>\n        <ul><li>Final loan provider rate to customers</li></ul>\n      </div>\n    </div>\n\n    <h4>2. 📋 Statutory Reserve Requirements (SRR)</h4>\n    <p>Deposits banks must maintain at the central bank.</p>\n    <ul>\n      <li><span class=\"highlight-green\">↓ SRR</span> → <span class=\"tag tag-light\">↑ Money Supply</span></li>\n      <li><span class=\"highlight-amber\">↑ SRR</span> → <span class=\"tag tag-amber\">↓ Money Supply</span></li>\n    </ul>\n\n    <h4>3. 💱 Open Market Operations (OMO)</h4>\n    <p>Buying and selling government securities.</p>\n    <ul>\n      <li>Central bank <span class=\"highlight\">buys securities</span> → <span class=\"tag tag-light\">↑ Money Supply</span></li>\n      <li>Central bank <span class=\"highlight-amber\">sells securities</span> → <span class=\"tag tag-amber\">↓ Money Supply</span></li>\n    </ul>\n\n    <h4>4. 🔄 Changing Discount Rate</h4>\n    <p>Controlling money supply through discount rate changes.</p>\n\n    <h4>5. 🎯 Imposing Credit Limits</h4>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">📊 Quantitative</div>\n        <ul>\n          <li>Controlling total credit volume</li>\n          <li>Asset/capital ratios</li>\n          <li>Minimum deposits for LCs</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🎯 Qualitative</div>\n        <ul>\n          <li>Controlling loan direction</li>\n          <li>Motivating priority sectors</li>\n          <li>Limiting consumption loans</li>\n        </ul>\n      </div>\n    </div>\n\n    <h4>6. 📅 Managing Inactive Loans</h4>\n    <p>Direct strategy to control existing loan portfolios.</p>\n\n    <h3>Impact of Monetary Policy on Businesses</h3>\n    <div class=\"formula-box\" style=\"font-size: 0.85rem;\">\n      ↓ Interest Rate → ↓ Commercial Bank Rates → ↑ Loans → ↑ Investment → ↑ Production → ↓ Prices → ↑ Sales → ↑ Profit\n    </div>\n  </div>\n\n  <!-- Fiscal vs Monetary Comparison -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚖️</div>\n    <h2>Fiscal Policy vs Monetary Policy <span class=\"underline\"></span></h2>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">💰 Fiscal Policy</div>\n        <ul>\n          <li>Government revenue &amp; expenditure</li>\n          <li>Managed by the government (Treasury)</li>\n          <li>Uses taxation &amp; spending</li>\n          <li>Impacts budget deficits/surpluses</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🏦 Monetary Policy</div>\n        <ul>\n          <li>Control of money supply</li>\n          <li>Managed by Central Bank</li>\n          <li>Uses interest rates, SRR, OMO</li>\n          <li>Impacts inflation &amp; credit availability</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- Consumer Protection Intro -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🛡️</div>\n    <h2>Consumer Protection <span class=\"underline\"></span></h2>\n    <p>Legal cover ensuring <span class=\"highlight\">customer satisfaction</span> for the money paid.</p>\n\n    <h3>Reasons for Consumer Protection</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">📦</div><div class=\"label\">Abundance of Goods</div><div class=\"desc\">Many choices create confusion</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤝</div><div class=\"label\">Increased Competition</div><div class=\"desc\">Need to ensure fair practices</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏛️</div><div class=\"label\">Complex Market</div><div class=\"desc\">Hard to navigate without protection</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌐</div><div class=\"label\">Globalization</div><div class=\"desc\">Cross-border transactions</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌿</div><div class=\"label\">Environmental Awareness</div><div class=\"desc\">Demand for sustainable goods</div></div>\n    </div>\n  </div>\n\n  <!-- Benefits of Consumer Protection -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">👍</div>\n    <h2>Benefits of Consumer Protection <span class=\"underline\"></span></h2>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">🧍 For Consumers</div>\n        <ul>\n          <li>Value for money</li>\n          <li>Protection from malpractices</li>\n          <li>Health &amp; safety assurance</li>\n          <li>Legal cover</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🏭 For Businesses</div>\n        <ul>\n          <li>Consumer trust &amp; loyalty</li>\n          <li>Increased profit</li>\n          <li>Reduced waste</li>\n          <li>Favourable business environment</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- Consumer Rights -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">📜</div>\n    <h2>Consumer Rights <span class=\"underline\"></span></h2>\n    <p>Established by <span class=\"highlight\">John F. Kennedy</span> and expanded by <span class=\"highlight\">Consumer International</span>:</p>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">ℹ️</div><div class=\"label\">Right to be Informed</div><div class=\"desc\">Know product details before purchase</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">✅</div><div class=\"label\">Right to Choose</div><div class=\"desc\">Access to variety of goods</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏢</div><div class=\"label\">Right to be Heard</div><div class=\"desc\">Voice complaints &amp; concerns</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🛡️</div><div class=\"label\">Right to Safety</div><div class=\"desc\">Protection from hazardous goods</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏠</div><div class=\"label\">Right to Satisfaction of Basic Needs</div><div class=\"desc\">Access to essentials</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📚</div><div class=\"label\">Right to Consumer Education</div><div class=\"desc\">Knowledge about rights</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌿</div><div class=\"label\">Right to a Healthy Environment</div><div class=\"desc\">Live in a sustainable world</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🔄</div><div class=\"label\">Right to Redress</div><div class=\"desc\">Compensation for wrongs</div></div>\n    </div>\n  </div>\n\n  <!-- Consumer Responsibilities -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧑‍💼</div>\n    <h2>Consumer Responsibilities <span class=\"underline\"></span></h2>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">💭</div><div class=\"label\">Critical Awareness</div><div class=\"desc\">Question product claims &amp; quality</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">👥</div><div class=\"label\">Active Participation</div><div class=\"desc\">Engage in consumer groups</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤝</div><div class=\"label\">Social Concern</div><div class=\"desc\">Consider impact on others</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌿</div><div class=\"label\">Environmental Awareness</div><div class=\"desc\">Choose eco-friendly products</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤜🤛</div><div class=\"label\">Cooperation</div><div class=\"desc\">Work with enforcement agencies</div></div>\n    </div>\n  </div>\n\n  <!-- Rights vs Responsibilities -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">⚖️</div>\n    <h2>Consumer Rights vs Responsibilities <span class=\"underline\"></span></h2>\n    <div class=\"comparison\">\n      <div class=\"left\">\n        <div class=\"header\">📜 Rights</div>\n        <ul>\n          <li>Right to be informed</li>\n          <li>Right to choose</li>\n          <li>Right to be heard</li>\n          <li>Right to safety</li>\n          <li>Right to basic needs</li>\n          <li>Right to consumer education</li>\n          <li>Right to healthy environment</li>\n          <li>Right to redress</li>\n        </ul>\n      </div>\n      <div class=\"right\">\n        <div class=\"header\">🧑‍💼 Responsibilities</div>\n        <ul>\n          <li>Critical awareness</li>\n          <li>Active participation</li>\n          <li>Social concern</li>\n          <li>Environmental awareness</li>\n          <li>Cooperation</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!-- Consumer Affairs Authority -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏛️</div>\n    <h2>Consumer Affairs Authority <span class=\"underline\"></span></h2>\n\n    <h3>Goals</h3>\n    <ul>\n      <li>Protect consumers from hazardous goods</li>\n      <li>Prevent unfair trade practices</li>\n      <li>Ensure access to goods at competitive prices</li>\n      <li>Enable consumers to seek redress</li>\n    </ul>\n\n    <h3>Functions</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">📜</div><div class=\"label\">Control Restrictive Trade</div><div class=\"desc\">Prevent anti-competitive agreements</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">⚠️</div><div class=\"label\">Eliminate Abuse of Dominance</div><div class=\"desc\">Stop monopolistic practices</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🤝</div><div class=\"label\">Maintain Competition</div><div class=\"desc\">Ensure level playing field</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🔍</div><div class=\"label\">Investigate Practices</div><div class=\"desc\">Probe anti-competitive behaviour</div></div>\n    </div>\n\n    <h3>Importance</h3>\n    <ul>\n      <li><span class=\"highlight\">Standards compliance</span> — ensures product quality</li>\n      <li><span class=\"highlight-green\">Consumer trust</span> — builds confidence in marketplace</li>\n      <li><span class=\"highlight-amber\">Business image</span> — fair competition improves reputation</li>\n      <li><span class=\"tag tag-light\">Minimized legal issues</span> — resolves disputes</li>\n      <li><span class=\"tag tag-green\">Fair competition</span> — protects all market participants</li>\n    </ul>\n  </div>\n\n  <!-- Sri Lanka Standards Institution -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🏷️</div>\n    <h2>Sri Lanka Standards Institution <span class=\"underline\"></span></h2>\n\n    <h3>Aims</h3>\n    <ul>\n      <li>Prepare national standards</li>\n      <li>Promote standardization &amp; quality control</li>\n      <li>Examine compliance with standards</li>\n      <li>Conduct research</li>\n      <li>Issue certification marks</li>\n      <li>Cooperate internationally</li>\n    </ul>\n\n    <h3>Functions</h3>\n    <div class=\"card-grid\">\n      <div class=\"info-card\"><div class=\"emoji\">📋</div><div class=\"label\">Formulate Standards</div><div class=\"desc\">Develop &amp; implement national standards</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏷️</div><div class=\"label\">SLS Certification</div><div class=\"desc\">Award SLS mark to compliant products</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🌐</div><div class=\"label\">ISO Standards</div><div class=\"desc\">Adopt international standards</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">📚</div><div class=\"label\">Training &amp; Education</div><div class=\"desc\">Consumer education programs</div></div>\n      <div class=\"info-card\"><div class=\"emoji\">🏢</div><div class=\"label\">Library Services</div><div class=\"desc\">Standards documentation access</div></div>\n    </div>\n\n    <h3>Importance for Businesses</h3>\n    <ul>\n      <li><span class=\"highlight\">Face competition</span> with SLS mark advantage</li>\n      <li><span class=\"highlight-green\">Minimize complaints</span> through quality assurance</li>\n      <li><span class=\"highlight-amber\">Expand market share</span> with trusted products</li>\n      <li><span class=\"tag tag-light\">ISO certification</span> enables international trade</li>\n      <li><span class=\"tag tag-green\">Productivity</span> &amp; employee morale improvements</li>\n    </ul>\n  </div>\n\n  <!-- Flashcards -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧠</div>\n    <h2>Key Terms <span class=\"underline\"></span></h2>\n    <div class=\"flashcard-container\">\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">Fiscal Policy<div class=\"flashcard-hint\">Tap to reveal</div></div>\n          <div class=\"flashcard-back\">Government revenue &amp; expenditure management — taxation, spending, budgets</div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">Monetary Policy<div class=\"flashcard-hint\">Tap to reveal</div></div>\n          <div class=\"flashcard-back\">Control of money supply by Central Bank — interest rates, SRR, OMO</div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">Direct Tax<div class=\"flashcard-hint\">Tap to reveal</div></div>\n          <div class=\"flashcard-back\">Paid by liable party directly; cannot be transferred. Ex: Income tax</div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">Indirect Tax<div class=\"flashcard-hint\">Tap to reveal</div></div>\n          <div class=\"flashcard-back\">Can be transferred to another. Ex: VAT, Excise duties, Customs duties</div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">SRR<div class=\"flashcard-hint\">Tap to reveal</div></div>\n          <div class=\"flashcard-back\">Statutory Reserve Requirement — deposits banks must maintain at Central Bank</div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">OMO<div class=\"flashcard-hint\">Tap to reveal</div></div>\n          <div class=\"flashcard-back\">Open Market Operations — buying/selling govt securities to control money supply</div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">SDFR<div class=\"flashcard-hint\">Tap to reveal</div></div>\n          <div class=\"flashcard-back\">Standing Deposit Facility Rate — paid when banks invest surplus in govt securities</div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">SLFR<div class=\"flashcard-hint\">Tap to reveal</div></div>\n          <div class=\"flashcard-back\">Standing Lending Facility Rate — charged when banks borrow pledging securities</div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">VAT<div class=\"flashcard-hint\">Tap to reveal</div></div>\n          <div class=\"flashcard-back\">Value Added Tax — applied on wholesale/retail transactions and exports</div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">Consumer Affairs Authority<div class=\"flashcard-hint\">Tap to reveal</div></div>\n          <div class=\"flashcard-back\">Govt body protecting consumers from hazardous goods, unfair trade, promoting competition</div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">SLS Institution<div class=\"flashcard-hint\">Tap to reveal</div></div>\n          <div class=\"flashcard-back\">Sri Lanka Standards Institution — prepares standards, SLS certification, quality control</div>\n        </div>\n      </div>\n      <div class=\"flashcard\" onclick=\"flipCard(this)\">\n        <div class=\"flashcard-inner\">\n          <div class=\"flashcard-front\">Economic Stability<div class=\"flashcard-hint\">Tap to reveal</div></div>\n          <div class=\"flashcard-back\">Internal (inflation, price level, interest rate) + External (forex rate stability)</div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Quiz -->\n  <div class=\"section\" data-section=\"\">\n    <div class=\"section-icon\">🧰</div>\n    <h2>Test Your Knowledge <span class=\"underline\"></span></h2>\n\n    <div class=\"quiz-question\" data-q=\"1\">\n      <div class=\"q\">1. Which level of government is responsible for monetary and fiscal policy?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Local Authorities</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Provincial Councils</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Central Government</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Municipal Councils</button>\n      <div class=\"quiz-feedback\" data-feedback=\"1\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"2\">\n      <div class=\"q\">2. Which of the following is an example of an indirect tax?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Corporation Tax</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Value Added Tax (VAT)</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">PAYE Tax</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Income Tax</button>\n      <div class=\"quiz-feedback\" data-feedback=\"2\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"3\">\n      <div class=\"q\">3. What happens when the Central Bank lowers the Statutory Reserve Requirement (SRR)?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Money supply decreases</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Money supply increases</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Interest rates rise</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Inflation is guaranteed</button>\n      <div class=\"quiz-feedback\" data-feedback=\"3\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"4\">\n      <div class=\"q\">4. Which consumer right was established by John F. Kennedy?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Right to consumer education</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Right to a healthy environment</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Right to be informed</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Right to redress</button>\n      <div class=\"quiz-feedback\" data-feedback=\"4\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"5\">\n      <div class=\"q\">5. Fiscal policy relates to:</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Control of money supply</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Government revenue &amp; expenditure</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Interest rate regulation</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Foreign exchange management</button>\n      <div class=\"quiz-feedback\" data-feedback=\"5\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"6\">\n      <div class=\"q\">6. Which institution issues the SLS certification mark in Sri Lanka?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Consumer Affairs Authority</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Sri Lanka Standards Institution</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Central Bank of Sri Lanka</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Ministry of Finance</button>\n      <div class=\"quiz-feedback\" data-feedback=\"6\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"7\">\n      <div class=\"q\">7. When the Central Bank buys government securities through OMO, what happens to money supply?</div>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">It increases</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">It decreases</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">It stays the same</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">It depends on the discount rate</button>\n      <div class=\"quiz-feedback\" data-feedback=\"7\"></div>\n    </div>\n\n    <div class=\"quiz-question\" data-q=\"8\">\n      <div class=\"q\">8. Which is NOT a goal of the Consumer Affairs Authority?</div>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Protect from hazardous goods</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Eliminate abuse of dominant position</button>\n      <button class=\"quiz-option\" data-correct=\"true\" onclick=\"checkAnswer(this, true)\">Issue SLS certification marks</button>\n      <button class=\"quiz-option\" onclick=\"checkAnswer(this, false)\">Maintain competition</button>\n      <div class=\"quiz-feedback\" data-feedback=\"8\"></div>\n    </div>\n  </div>\n</div>\n\n<script>\n  // Particles\n  const canvas = document.getElementById('particles');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  class Particle {\n    constructor() { this.reset(); }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2.5 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.4;\n      this.speedY = (Math.random() - 0.5) * 0.4;\n      this.opacity = Math.random() * 0.4 + 0.08;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n      if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(16, 185, 129, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 80; i++) particles.push(new Particle());\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 150) {\n          ctx.beginPath();\n          ctx.strokeStyle = `rgba(16, 185, 129, ${0.05 * (1 - dist / 150)})`;\n          ctx.lineWidth = 0.5;\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  // Scroll reveal\n  const sections = document.querySelectorAll('[data-section]');\n\n  function revealSections() {\n    sections.forEach(section => {\n      const rect = section.getBoundingClientRect();\n      if (rect.top < window.innerHeight - 80) {\n        section.classList.add('visible');\n      }\n    });\n  }\n  window.addEventListener('scroll', revealSections);\n  revealSections();\n\n  // Progress bar\n  const progressBar = document.getElementById('progressBar');\n  window.addEventListener('scroll', () => {\n    const scrollTop = window.scrollY;\n    const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n    progressBar.style.width = (scrollTop / docHeight) * 100 + '%';\n  });\n\n  // Flashcards\n  function flipCard(card) {\n    card.classList.toggle('flipped');\n  }\n\n  // Quiz\n  function checkAnswer(btn, isCorrect) {\n    const question = btn.closest('.quiz-question');\n    const options = question.querySelectorAll('.quiz-option');\n    const feedback = question.querySelector('.quiz-feedback');\n\n    options.forEach(opt => {\n      opt.disabled = true;\n      opt.style.cursor = 'not-allowed';\n      if (opt.dataset.correct === 'true') opt.classList.add('correct');\n    });\n\n    if (isCorrect) {\n      btn.classList.add('correct');\n      feedback.innerHTML = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg> Correct!';\n      feedback.className = 'quiz-feedback show correct';\n    } else {\n      btn.classList.add('wrong');\n      const correctBtn = question.querySelector('[data-correct=\"true\"]');\n      feedback.textContent = '❌ Incorrect. The answer was: ' + correctBtn.textContent;\n      feedback.className = 'quiz-feedback show wrong';\n    }\n  }\n</script>\n\n\n\n\n</body>\n</html>",
    "4": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"ambient-glow\"></div>\n<div class=\"ambient-glow\"></div>\n<div class=\"ambient-glow\"></div>\n<canvas id=\"particles-canvas\"></canvas>\n<div class=\"progress-bar\" id=\"progress-bar\"></div>\n\n<div class=\"content\">\n\n\n  <header>\n    <div class=\"badge\">Business Studies — Lesson 4</div>\n    <h1>The Importance of Establishing &amp; Maintaining Different Types of Business Organizations Formally</h1>\n    <p>Exploring sole proprietorships, partnerships, companies, co-operatives, franchises, business combinations, and the public sector.</p>\n  </header>\n\n  <nav class=\"toc\" id=\"toc\">\n    <a href=\"#sec-org\"><span class=\"num\">1</span> Organization</a>\n    <a href=\"#sec-sole\"><span class=\"num\">2</span> Sole Proprietorship</a>\n    <a href=\"#sec-partner\"><span class=\"num\">3</span> Partnership</a>\n    <a href=\"#sec-company\"><span class=\"num\">4</span> Company</a>\n    <a href=\"#sec-coop\"><span class=\"num\">5</span> Co-Operative</a>\n    <a href=\"#sec-franchise\"><span class=\"num\">6</span> Franchise</a>\n    <a href=\"#sec-combine\"><span class=\"num\">7</span> Combinations</a>\n    <a href=\"#sec-public\"><span class=\"num\">8</span> Public Sector</a>\n  </nav>\n\n  <div class=\"section\" id=\"sec-org\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(96,165,250,0.2),rgba(167,139,250,0.2));\">■</span> What is an Organization?</h2>\n      <div class=\"def-box\">A social unit made up with a group of individuals joining together and having a common goal is an <strong>organization</strong>.</div>\n      <p class=\"subtitle\">Examples: School, Temple, Church, Shop</p>\n\n      <h3 style=\"font-size:1rem;font-weight:600;margin:20px 0 8px;color:var(--accent);\">Common Characteristics of a Formal Organization</h3>\n      <ul class=\"features\">\n        <li>Has a goal</li>\n        <li>Involves individuals</li>\n        <li>Has an organizational structure</li>\n      </ul>\n\n      <div class=\"def-box\" style=\"border-left-color:var(--accent2);\">\n        <strong>Business organizations</strong> are enterprises engaged in production, distribution and selling of goods and services with the objective of earning profits or achieving social wellbeing.\n      </div>\n\n      <p style=\"margin-top:16px;color:var(--text-dim);font-size:15px;\">\n        Business organizations can be categorized as <strong>private sector</strong> and <strong>public sector</strong> based on ownership.\n      </p>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-sole\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(52,211,153,0.2),rgba(96,165,250,0.2));\">☷</span> Sole Proprietorship</h2>\n      <div class=\"def-box\">Where the ownership of the business is held by a <strong>single individual</strong>, it is called sole proprietorship.</div>\n      <p class=\"subtitle\">Examples: Chanuli Super Centre, Dasatha Book shop, Imalka saloon</p>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('sole-chars')\">▼ Key Characteristics</button>\n      <div id=\"sole-chars\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>The owner provides the capital required on his own</li>\n          <li>All managerial decisions are made by the owner</li>\n          <li>The unlimited liability of the owner</li>\n          <li>Not a legal entity</li>\n          <li>Registration is not compulsory</li>\n          <li>Enjoy profits and losses alone</li>\n          <li>Faces risks alone</li>\n          <li>No continuity</li>\n          <li>Accounting is not compulsory</li>\n          <li>Not liable for the taxes in the name of the business</li>\n        </ul>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('sole-adv')\">▼ Advantages</button>\n      <div id=\"sole-adv\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Easy to initiate</li>\n          <li>All the profits belong to the owner</li>\n          <li>Ability of independent decision making</li>\n          <li>Fewer rules and regulations are applicable</li>\n          <li>The ability of keeping the business information confidentially</li>\n          <li>Termination of the business is convenient</li>\n          <li>Possibility of maintaining direct relations with the customers</li>\n          <li>Control is convenient</li>\n        </ul>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('sole-lim')\">▼ Limitations</button>\n      <div id=\"sole-lim\" style=\"display:none;\">\n        <ul class=\"list\">\n          <li>The unlimited liability of the owner</li>\n          <li>Problems increase when additional capital is needed</li>\n          <li>Possibility of unsuccessful decisions by the owner</li>\n          <li>Not a legal entity</li>\n          <li>No continuity</li>\n          <li>Management becomes inconvenient with expansion</li>\n          <li>Bearing losses alone</li>\n        </ul>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('sole-reg')\">▼ Registration Process</button>\n      <div id=\"sole-reg\" style=\"display:none;\">\n        <p style=\"margin:12px 0;color:var(--text-dim);font-size:14px;\">\n          If a sole proprietorship is carried on in a name other than the full name of the owner, registration is compulsory at the <strong>Provincial Business Name Registrar</strong> under the Business Name Ordinance No. 6 of 1918.\n        </p>\n        <ol class=\"step-list\">\n          <li>Obtain an application form from the Divisional Secretariat office</li>\n          <li>Obtain a report from the relevant Grama Niladari</li>\n          <li>Submit the completed form, Grama Niladari report, and fee to the Divisional Secretary</li>\n          <li>Certificate of registration is issued after examination</li>\n        </ol>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-partner\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(167,139,250,0.2),rgba(52,211,153,0.2));\">❐</span> Partnership</h2>\n      <div class=\"def-box\">\n        <strong>Partnership Ordinance 1890:</strong> “The relationship between the individuals who carry out a business with a profit motive is Partnership.”\n      </div>\n      <p class=\"subtitle\">Examples: Gunawardena &amp; Sons, Don Carolis &amp; Sons</p>\n\n      <p style=\"font-size:15px;font-weight:500;color:var(--accent);\">Essential Characteristics</p>\n      <ul class=\"features\">\n        <li>Profit generating objectives</li>\n        <li>The existence of business activity</li>\n        <li>Existence of individuals</li>\n        <li>Having a mutual relationship</li>\n      </ul>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('part-chars')\">▼ Key Features</button>\n      <div id=\"part-chars\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Minimum 2 partners, maximum 20 partners</li>\n          <li>There must be an agreement between the partners</li>\n          <li>Having an agreement on profit sharing</li>\n          <li>Every partner is an agent and a head of himself and other partners</li>\n          <li>The existence of any kind of business affair</li>\n        </ul>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('part-deed')\">▼ Partnership Deed</button>\n      <div id=\"part-deed\" style=\"display:none;\">\n        <p style=\"margin:12px 0;color:var(--text-dim);font-size:14px;\">\n          The written agreement between partners is known as the <strong>partnership deed</strong> or partnership constitution. It includes:\n        </p>\n        <ul class=\"list\">\n          <li>Basic info: business name, partner details, nature and duration</li>\n          <li>Capital investment details</li>\n          <li>Profit and loss sharing arrangement</li>\n          <li>Objectives of the partnership</li>\n          <li>Limitations on drawings</li>\n          <li>Interest on capital and drawings</li>\n          <li>Conditions on dissolution</li>\n          <li>Additional capital investment conditions</li>\n          <li>Actions on admission, retirement, or death of a partner</li>\n        </ul>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('part-rights')\">▼ Partner Rights &amp; Rules</button>\n      <div id=\"part-rights\" style=\"display:none;\">\n        <ul class=\"list\">\n          <li>Expenditure incurred personally on behalf of the partnership must be reimbursed</li>\n          <li>Partners are entitled to 5% interest on money invested beyond agreed capital</li>\n          <li>No partner is entitled to interest on capital (standard)</li>\n          <li>Every partner has the right to participate in management</li>\n          <li>No partner has the right to receive a salary for services rendered</li>\n          <li>New partners require consent of all existing partners</li>\n          <li>Disagreements solved by majority; fundamental changes require unanimous agreement</li>\n          <li>Books of accounts kept at head office; any partner may inspect and copy</li>\n        </ul>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('part-proscons')\">▼ Advantages &amp; Limitations</button>\n      <div id=\"part-proscons\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Advantages</h4>\n            <ul>\n              <li>Easy to commence</li>\n              <li>Can be dissolved easily</li>\n              <li>Possibility of gathering immense capital</li>\n              <li>Multiple skills and talents</li>\n              <li>Liabilities distributed among partners</li>\n              <li>Enhanced enthusiasm and efficiency</li>\n            </ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Limitations</h4>\n            <ul>\n              <li>Unlimited liability of partners</li>\n              <li>Disagreements can adversely affect the business</li>\n              <li>No continuity</li>\n              <li>All partners liable for conduct of a single partner</li>\n            </ul>\n          </div>\n        </div>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('part-compare')\">▼ Comparison: Sole vs Partnership</button>\n      <div id=\"part-compare\" style=\"display:none;\">\n        <table class=\"comparison-table\">\n          <tbody><tr><th>Aspect</th><th>Sole Proprietorship</th><th>Partnership</th></tr>\n          <tr><td>Ownership</td><td>Single individual</td><td>Two or more individuals</td></tr>\n          <tr><td>Capital</td><td>Limited</td><td>Higher</td></tr>\n          <tr><td>Decision Making</td><td>Independent</td><td>Collective</td></tr>\n          <tr><td>Liability</td><td>Unlimited</td><td>Unlimited (joint &amp; several)</td></tr>\n          <tr><td>Continuity</td><td>No</td><td>No</td></tr>\n          <tr><td>Legal Entity</td><td>No</td><td>No</td></tr>\n          <tr><td>Registration</td><td>Not compulsory</td><td>Not compulsory (but name registration may apply)</td></tr>\n          <tr><td>Profit Sharing</td><td>Owner alone</td><td>Shared per agreement</td></tr>\n        </tbody></table>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-company\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(251,191,36,0.2),rgba(96,165,250,0.2));\">◦</span> Company</h2>\n      <div class=\"def-box\">\n        A collection of individuals incorporated under the <strong>Companies Act No. 7 of 2007</strong> can be introduced as a company.\n      </div>\n      <p class=\"subtitle\">Examples: Aralia Company Ltd, Pratheeba Company (Pvt.) Ltd</p>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('comp-chars')\">▼ Characteristics of Incorporated Companies</button>\n      <div id=\"comp-chars\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Independent entity incorporated under the Company Act</li>\n          <li>Independent legal entity distinct from its shareholders</li>\n          <li>Continuous existence / perpetual succession</li>\n          <li>Liability of members/shareholders is limited</li>\n          <li>Capital accumulation through share issues</li>\n          <li>Ability to transfer shares</li>\n          <li>Management by a Board of Directors</li>\n        </ul>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('comp-adv')\">▼ Advantages</button>\n      <div id=\"comp-adv\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Ability to raise a large amount of capital</li>\n          <li>Possibility of beginning large-scale businesses</li>\n          <li>Ability to recruit a smart management team</li>\n          <li>Ability to attract new investors (limited liability)</li>\n          <li>Death/resignation of a shareholder does not affect the business</li>\n          <li>Ability to assemble qualified and skillful human resources</li>\n          <li>The business has a legality</li>\n        </ul>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('comp-lim')\">▼ Limitations</button>\n      <div id=\"comp-lim\" style=\"display:none;\">\n        <ul class=\"list\">\n          <li>Legal impacts being strict</li>\n          <li>Establishment procedure is complicated and expensive</li>\n          <li>Minority shareholders lack influence (1 vote per share)</li>\n          <li>Profit subjected to double taxation (company profit + dividends)</li>\n          <li>Dissolution procedure is complicated</li>\n        </ul>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('comp-inc')\">▼ Incorporation Procedure</button>\n      <div id=\"comp-inc\" style=\"display:none;\">\n        <p style=\"margin:12px 0;color:var(--text-dim);font-size:14px;\">\n          Incorporation is done under <strong>Companies Act No. 7 of 2007</strong> with the Department of Company Registrar.\n        </p>\n        <ol class=\"step-list\">\n          <li>Register the name of the company</li>\n          <li>Submit documents: application for registration, articles of association, director consent statements, secretary consent statement</li>\n          <li>The <strong>Articles of Association</strong> contains objectives, shareholder rights and responsibilities, management and administration details</li>\n          <li>Registrar issues the <strong>Certificate of Incorporation</strong> once satisfied</li>\n        </ol>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('comp-types')\">▼ Types of Companies</button>\n      <div id=\"comp-types\" style=\"display:none;\">\n        <table class=\"comparison-table\">\n          <tbody><tr><th>Type</th><th>Key Features</th><th>Examples</th></tr>\n          <tr><td><strong>Private Limited</strong></td><td>Min 1 / Max 50 shareholders; min 1 director; shares not sold to public</td><td>Central Depository (Pvt) Ltd, Lanka Clear (PVT) Ltd</td></tr>\n          <tr><td><strong>Public Limited</strong></td><td>Min 1 shareholder, unlimited max; min 2 directors; can issue shares to public; insolvency test required for dividends</td><td>—</td></tr>\n          <tr><td><strong>Listed (Quoted)</strong></td><td>Listed on the Colombo Stock Exchange</td><td>DFCC Bank PLC, Ceylinco PLC</td></tr>\n          <tr><td><strong>Unlisted (Unquoted)</strong></td><td>Not listed on CSE</td><td>Ceylon Biscuit Company Ltd, Maliban Biscuit Co. Ltd</td></tr>\n          <tr><td><strong>Offshore Company</strong></td><td>Incorporated in one country, operates outside it; must register in both countries</td><td>Sunrecko Marine Company, Asia Pacific Company</td></tr>\n          <tr><td><strong>Unlimited Company</strong></td><td>Liability of shareholders is unlimited per articles of association</td><td>—</td></tr>\n          <tr><td><strong>Limited by Guarantee</strong></td><td>No share issue; liability limited to a guaranteed amount; min 2 members; no profit sharing; public purposes</td><td>Colombo Stock Exchange (GTE) Ltd</td></tr>\n          <tr><td><strong>Overseas Company</strong></td><td>Incorporated abroad, established in Sri Lanka; must register within 1 month</td><td>HSBC</td></tr>\n        </tbody></table>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-coop\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(52,211,153,0.2),rgba(251,191,36,0.2));\">☰</span> Co-Operative Business</h2>\n      <div class=\"def-box\">\n        “A co-operative is an autonomous association of people united voluntarily in their common economic, social and cultural needs and aspirations through a jointly owned and democratically controlled enterprise.”\n        <br><span style=\"font-size:13px;color:var(--text-dim);\">— International Co-operative Alliance</span>\n      </div>\n      <p class=\"subtitle\">Examples: Maharagama Multi-purpose Co-operative Society Ltd, Cloth-weavers’ Co-operative Society Ltd, Fisheries Co-operative Society Ltd</p>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('coop-chars')\">▼ Key Characteristics</button>\n      <div id=\"coop-chars\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>An independent business organization</li>\n          <li>Group of individuals who have got together voluntarily</li>\n          <li>Collective ownership of its members</li>\n          <li>Having common needs and expectations</li>\n          <li>Democratically controlled business</li>\n          <li>Value of a share is unchanged (Rs. 100)</li>\n          <li>One vote for each member (one man one vote)</li>\n          <li>Surplus distributed according to transaction value with the society</li>\n          <li>Profit making is not the initial objective</li>\n        </ul>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('coop-principles')\">▼ Co-Operative Principles (1995 ICA, Manchester)</button>\n      <div id=\"coop-principles\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Voluntary and open membership</li>\n          <li>Democratic control of members</li>\n          <li>Member economic participation</li>\n          <li>Autonomy and independence</li>\n          <li>Co-operative education, training and provision of information</li>\n          <li>Co-operation among co-operatives (regional, national, international)</li>\n          <li>Concern for the community</li>\n        </ul>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('coop-benefits')\">▼ Benefits &amp; Limitations</button>\n      <div id=\"coop-benefits\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Benefits</h4>\n            <ul>\n              <li>10 people can initiate conveniently at low investment</li>\n              <li>Democratic control</li>\n              <li>Goods and services at reasonable prices</li>\n              <li>Different types of business activities</li>\n              <li>Mutual co-operation</li>\n              <li>Surplus distributed among members</li>\n            </ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Limitations</h4>\n            <ul>\n              <li>Limited means of fund raising</li>\n              <li>Restricted to co-operative policies</li>\n              <li>Limited opening hours</li>\n              <li>Public sector interference</li>\n              <li>No credit sales</li>\n              <li>Board may be inefficient (elected by voting)</li>\n            </ul>\n          </div>\n        </div>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('coop-reg')\">▼ Registration Process</button>\n      <div id=\"coop-reg\" style=\"display:none;\">\n        <p style=\"margin:12px 0;color:var(--text-dim);font-size:14px;\">\n          Registered under <strong>Co-operative Societies Act No. 05 of 1972</strong> with the Co-operative Development Commissioner.\n        </p>\n        <ol class=\"step-list\">\n          <li>Any 10 people above 18 may apply</li>\n          <li>Submit: application form, 2 copies of interim constitution, feasibility report, minutes of the general meeting, membership fee certificate, route map</li>\n          <li>Commissioner inspects and confirms compliance</li>\n          <li>Certificate of registration is issued</li>\n        </ol>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('coop-trends')\">▼ Emerging Trends &amp; Proposals</button>\n      <div id=\"coop-trends\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Emerging Trends</h4>\n            <ul>\n              <li>Modified self-service outlets (Co-op City, Co-op Super)</li>\n              <li>New business fields (insurance, fuel stations)</li>\n              <li>Electronic payment systems</li>\n              <li>Mobile shopping centers</li>\n            </ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Development Proposals</h4>\n            <ul>\n              <li>Extend business hours</li>\n              <li>Credit sales options</li>\n              <li>Experienced management board</li>\n              <li>Promotional strategies</li>\n              <li>Expand self-service outlets</li>\n              <li>Attractive showrooms</li>\n              <li>Increase member benefits</li>\n              <li>Member promotion propaganda</li>\n              <li>Modern technology for consumer service</li>\n            </ul>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-franchise\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(239,68,68,0.2),rgba(251,191,36,0.2));\">★</span> Franchise</h2>\n      <div class=\"def-box\">\n        A business model where one firm (the <strong>franchisor</strong>) assigns the authority of selling its goods/services to another (the <strong>franchisee</strong>) in a specific trade zone.\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('fran-parties')\">▼ Parties &amp; Agreement</button>\n      <div id=\"fran-parties\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li><strong>Franchisor</strong> — the franchising company that permits the franchisee to market products under its brand</li>\n          <li><strong>Franchisee</strong> — the organization that receives permission from the franchisor</li>\n        </ul>\n        <p style=\"margin:12px 0;color:var(--text-dim);font-size:14px;\">\n          The <strong>Franchise Agreement</strong> governs the relationship, including use of trade name, logo, brand, rules, services, financial conditions, initial payment, and monthly royalties.\n        </p>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('fran-support')\">▼ Franchisor Support &amp; Franchisee Duties</button>\n      <div id=\"fran-support\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Franchisor Provides</h4>\n            <ul>\n              <li>Permission to use trade name</li>\n              <li>Management training</li>\n              <li>Marketing assistance</li>\n              <li>Financial assistance</li>\n              <li>Layout &amp; design help</li>\n              <li>Product supply &amp; equipment</li>\n              <li>Technical knowledge</li>\n            </ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Franchee Must</h4>\n            <ul>\n              <li>Act per franchisor conditions</li>\n              <li>Make capital investment</li>\n              <li>Purchase only from franchisor/authorized suppliers</li>\n              <li>Make agreed payments</li>\n            </ul>\n          </div>\n        </div>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('fran-types')\">▼ Types of Franchises</button>\n      <div id=\"fran-types\" style=\"display:none;\">\n        <table class=\"comparison-table\">\n          <tbody><tr><th>Type</th><th>Description</th><th>Example</th></tr>\n          <tr><td><strong>Product Franchise</strong></td><td>Franchisee authorized to purchase and resell goods under brand name</td><td>IOC Fuel Stations</td></tr>\n          <tr><td><strong>Manufacturing Franchise</strong></td><td>Franchisee authorized to manufacture and distribute under brand name</td><td>Coca-Cola, Pepsi bottling</td></tr>\n          <tr><td><strong>Business Format Franchise</strong></td><td>Franchisee follows franchisor’s entire business procedure and brand</td><td>McDonalds, KFC, Pizza Hut</td></tr>\n        </tbody></table>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('fran-proscons')\">▼ Benefits &amp; Limitations</button>\n      <div id=\"fran-proscons\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Benefits to Franchisor</h4>\n            <ul>\n              <li>Expand without further investment</li>\n              <li>Share advertising costs</li>\n              <li>Returns from franchisee investment</li>\n              <li>Spontaneous returns from franchisee efficiency</li>\n              <li>Nourished by the franchisee</li>\n            </ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Benefits to Franchisee</h4>\n            <ul>\n              <li>Large market niche from goodwill</li>\n              <li>Lower tendency to be unsuccessful</li>\n              <li>Convenient publicity (popular trade name)</li>\n              <li>Management training</li>\n              <li>Financial support</li>\n              <li>Raw materials at minimum price</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"grid-2\" style=\"margin-top:12px;\">\n          <div class=\"grid-item\">\n            <h4>Limitations for Franchisor</h4>\n            <ul>\n              <li>Franchisee failure affects profits</li>\n              <li>Unfavorable activities affect goodwill</li>\n              <li>Franchisee retains most profits</li>\n            </ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Limitations for Franchisee</h4>\n            <ul>\n              <li>No perfect autonomy</li>\n              <li>Greater cost to receive franchise</li>\n              <li>Profitability uncertainty</li>\n              <li>Dependence on franchisor’s goodwill</li>\n              <li>Inconvenience from agreement adherence</li>\n            </ul>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-combine\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(167,139,250,0.2),rgba(239,68,68,0.2));\">⊕</span> Business Combinations</h2>\n      <div class=\"def-box\">\n        Joining up of two or more businesses and engaging in business activities can be introduced as <strong>Business Combinations</strong>.\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('comb-types')\">▼ Mergers &amp; Acquisitions</button>\n      <div id=\"comb-types\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Merger (Amalgamation)</h4>\n            <ul>\n              <li>Two or more companies convert into a single entity</li>\n              <li>One company purchases assets and liabilities of another</li>\n              <li>Or all companies terminate and form a new company</li>\n            </ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Acquisition</h4>\n            <ul>\n              <li>One company purchases most ordinary share capital of another</li>\n              <li>The purchasing company gains power of control</li>\n            </ul>\n          </div>\n        </div>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('comb-strategies')\">▼ Combination Strategies</button>\n      <div id=\"comb-strategies\" style=\"display:none;\">\n        <table class=\"comparison-table\">\n          <tbody><tr><th>Type</th><th>Definition</th><th>Examples</th></tr>\n          <tr><td><strong>Horizontal</strong></td><td>Combination of businesses engaged in <strong>similar</strong> activities</td><td>Two footwear manufacturers; MBSL Savings + Merchant Bank + MBSL Financial (2015); Microsoft + Nokia; Fair First Insurance amalgamation; DFCC Bank merger</td></tr>\n          <tr><td><strong>Vertical</strong></td><td>Combination of businesses at <strong>different stages</strong> in the same production/marketing process</td><td>Shoe manufacturer + leather manufacturer + shoe marketing company</td></tr>\n          <tr><td><strong>Conglomerate</strong></td><td>Combination of businesses <strong>not in the same industry</strong></td><td>Shoe manufacturer + biscuit manufacturer</td></tr>\n        </tbody></table>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-public\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(14,165,233,0.2),rgba(99,102,241,0.2));\">☂</span> Public Sector / State Sector</h2>\n      <div class=\"def-box\">\n        All business entities carried out and controlled by the state or a local authority are known as <strong>state sector</strong> or <strong>public sector</strong> enterprises.\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('pub-reasons')\">▼ Reasons for State Involvement</button>\n      <div id=\"pub-reasons\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>To control pricing levels and prevent unreasonable private profits</li>\n          <li>To prevent monopolistic firms</li>\n          <li>To engage in fields required for national defense</li>\n          <li>To provide essential goods and services at reasonable prices</li>\n          <li>To minimize wastage of natural resources</li>\n          <li>To maintain non-profit large-scale projects</li>\n        </ul>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('pub-categories')\">▼ Categories of State Sector Organizations</button>\n      <div id=\"pub-categories\" style=\"display:none;\">\n        <table class=\"comparison-table\">\n          <tbody><tr><th>Category</th><th>Key Characteristics</th><th>Examples</th></tr>\n          <tr><td><strong>State Corporation / Statutory Board</strong></td><td>Established under special/general act; has legality; full/major government ownership; board appointed by government; capital from government loans, reinvestment, and public debt; objective: efficient service at minimum price</td><td>SLTB, Mahaweli Authority, SL Rupavahini Corporation, SL Petroleum Corporation</td></tr>\n          <tr><td><strong>Government Department</strong></td><td>No separate legality; represented in official name of the head; funds allocated through annual budget</td><td>Education Dept, Agriculture Dept, Health Dept, Dept of Railways</td></tr>\n          <tr><td><strong>State Company</strong></td><td>Incorporated under Companies Act as a PLC; &gt;51% capital by state organizations</td><td>SL Insurance Company Ltd, Lanka Phosphate Company Ltd, SL Telecom, Litro Gas Ltd, State Trading Company</td></tr>\n          <tr><td><strong>Local Authority Companies</strong></td><td>Under provincial councils, urban councils, Pradeshiya Sabha; ownership with local authority; funds from local/central government</td><td>—</td></tr>\n        </tbody></table>\n      </div>\n    </div>\n  </div>\n\n  <footer>\n    <p>Business Studies — Lesson 4 • Based on original lesson notes</p>\n  </footer>\n</div>\n\n<script>\n  // Particles\n  const canvas = document.getElementById('particles-canvas');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n  let mouseX = -1000, mouseY = -1000;\n\n  function resize() {\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resize();\n  window.addEventListener('resize', resize);\n\n  class Particle {\n    constructor() { this.reset(); }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.3;\n      this.speedY = (Math.random() - 0.5) * 0.3;\n      this.opacity = Math.random() * 0.5 + 0.1;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n      if (this.x < 0 || this.x > canvas.width) this.speedX *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.speedY *= -1;\n      const dx = this.x - mouseX;\n      const dy = this.y - mouseY;\n      const dist = Math.sqrt(dx * dx + dy * dy);\n      if (dist < 120) {\n        const force = (120 - dist) / 120;\n        this.x += dx * force * 0.008;\n        this.y += dy * force * 0.008;\n      }\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(148, 163, 184, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 120; i++) particles.push(new Particle());\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n    // Draw lines between nearby particles\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 140) {\n          ctx.beginPath();\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.strokeStyle = `rgba(148, 163, 184, ${0.06 * (1 - dist / 140)})`;\n          ctx.lineWidth = 0.5;\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  document.addEventListener('mousemove', e => { mouseX = e.clientX; mouseY = e.clientY; });\n\n  // Progress bar\n  window.addEventListener('scroll', () => {\n    const scrollTop = document.documentElement.scrollTop;\n    const scrollHeight = document.documentElement.scrollHeight - document.documentElement.clientHeight;\n    document.getElementById('progress-bar').style.width = (scrollTop / scrollHeight * 100) + '%';\n  });\n\n  // Intersection Observer for section animations\n  const observer = new IntersectionObserver((entries) => {\n    entries.forEach(entry => {\n      if (entry.isIntersecting) entry.target.classList.add('visible');\n    });\n  }, { threshold: 0.1 });\n  document.querySelectorAll('.section').forEach(s => observer.observe(s));\n\n  // Toggle sections\n  function toggleSection(id) {\n    const el = document.getElementById(id);\n    if (el.style.display === 'none') {\n      el.style.display = 'block';\n      el.style.animation = 'fadeUp 0.4s ease forwards';\n    } else {\n      el.style.display = 'none';\n    }\n  }\n</script>\n\n\n\n</body>\n</html>",
    "5": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n<div class=\"ambient-glow\"></div>\n<div class=\"ambient-glow\"></div>\n<div class=\"ambient-glow\"></div>\n<canvas id=\"particles-canvas\"></canvas>\n<div class=\"progress-bar\" id=\"progress-bar\"></div>\n<div class=\"content\">\n\n\n  <header>\n    <div class=\"badge\">Business Studies — Lesson 5</div>\n    <h1>Entrepreneurship</h1>\n    <p>Definitions, importance, trends, entrepreneurial process, characteristics, skills, and small &amp; medium scale businesses.</p>\n  </header>\n  <nav class=\"toc\">\n    <a href=\"#sec-def\"><span class=\"num\">1</span> Definitions</a>\n    <a href=\"#sec-importance\"><span class=\"num\">2</span> Importance</a>\n    <a href=\"#sec-benefits\"><span class=\"num\">3</span> Benefits</a>\n    <a href=\"#sec-trends\"><span class=\"num\">4</span> Trends</a>\n    <a href=\"#sec-process\"><span class=\"num\">5</span> Process</a>\n    <a href=\"#sec-entrepreneur\"><span class=\"num\">6</span> Entrepreneur</a>\n    <a href=\"#sec-sme\"><span class=\"num\">7</span> SME</a>\n    <a href=\"#sec-incentives\"><span class=\"num\">8</span> Incentives</a>\n  </nav>\n\n  <div class=\"section\" id=\"sec-def\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(245,158,11,0.2),rgba(239,68,68,0.2));\">★</span> What is Entrepreneurship?</h2>\n      <div class=\"def-box\">“Entrepreneurship is the process of extracting environmental opportunities creatively and generating innovation while bearing risks.”</div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('def-quotes')\">▼ Key Definitions</button>\n      <div id=\"def-quotes\" style=\"display:none;\">\n        <ul class=\"list\">\n          <li><strong>William D. Bygrave:</strong> “An entrepreneur is someone who perceives an opportunity and creates an organization to pursue it.”</li>\n          <li><strong>Joseph Schumpeter:</strong> “An entrepreneur is the person who destroys the existing economic order by introducing new products and services.”</li>\n          <li><strong>Oxford Dictionary:</strong> “Entrepreneurship is the bridge between capital and labor.”</li>\n          <li><strong>Richard Nantinut:</strong> “Entrepreneurship is facing up to uncertainties.”</li>\n          <li><strong>ILO:</strong> “Entrepreneurship is the ability to launch a new company and carry it on successfully.”</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-importance\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(239,68,68,0.2),rgba(245,158,11,0.2));\">⚠</span> Importance of Entrepreneurship</h2>\n      <ul class=\"features\">\n        <li>Enormous need for entrepreneurs who can find innovations and react to rapid changes</li>\n        <li>Need for generating innovations to survive in the competitive business world</li>\n        <li>Entrepreneurs give leadership to the changing world</li>\n        <li>Innovations uplift living standards through satisfying human needs</li>\n        <li>Developing business functions in line with changing technology</li>\n        <li>Creating employment through starting new businesses</li>\n      </ul>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('ent-biz-rel')\">▼ Relationship: Entrepreneurship &amp; Business</button>\n      <div id=\"ent-biz-rel\" style=\"display:none;\">\n        <p style=\"margin:12px 0;color:var(--text-dim);font-size:14px;\">All enterprises are businesses, whereas all businesses are not enterprises. The result of entrepreneurship is known as business.</p>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-benefits\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(16,185,129,0.2),rgba(245,158,11,0.2));\">☰</span> Benefits of Entrepreneurship</h2>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('benefits-detail')\">▼ Individual, Institutional &amp; Socio-Economic Benefits</button>\n      <div id=\"benefits-detail\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Individual Benefits</h4>\n            <ul><li>Make use of individual abilities</li><li>Higher benefits through higher commitments</li><li>Social status and acceptance</li><li>Self-satisfaction</li><li>Personal and financial gains</li></ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Institutional Benefits</h4>\n            <ul><li>Easy to face competition</li><li>Expansion of business activities</li><li>Continuous development</li><li>Expansion of market shares</li><li>Becoming industry expert</li></ul>\n          </div>\n        </div>\n        <div class=\"grid-item\" style=\"margin-top:12px;\">\n          <h4>Social &amp; Economic Benefits</h4>\n          <ul><li>Creation of new employment</li><li>New goods and services for consumers</li><li>Developing standard of living</li><li>Using regional resources</li><li>Development of new markets</li><li>Creation of income opportunities</li></ul>\n        </div>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('econ-dev')\">▼ Entrepreneurship &amp; Economic Development</button>\n      <div id=\"econ-dev\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Increase in national production through innovations</li>\n          <li>Increase in employment level</li>\n          <li>Faster economic development</li>\n          <li>Increase in production → employment → income → purchasing power → demand → business expansion → economic development</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-trends\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(139,92,246,0.2),rgba(245,158,11,0.2));\">⚖</span> Trends in Entrepreneurship</h2>\n      <div class=\"grid-2\">\n        <div class=\"grid-item\">\n          <h4>Global Entrepreneurship</h4>\n          <ul><li>Engaging in trade globally using technology</li><li>Working beyond borders</li><li>Understanding other cultures</li></ul>\n        </div>\n        <div class=\"grid-item\">\n          <h4>Social Entrepreneurship</h4>\n          <ul><li>Innovations to solve social problems</li><li>Intention of social service</li><li>Mental satisfaction, acceptance, praise</li></ul>\n        </div>\n        <div class=\"grid-item\">\n          <h4>Green Entrepreneurship</h4>\n          <ul><li>Activities with positive environmental impact</li><li>Protecting environment as core concept</li><li>Sensitive to environmental issues</li></ul>\n        </div>\n        <div class=\"grid-item\">\n          <h4>Intra Entrepreneurship</h4>\n          <ul><li>Creative people within organizations</li><li>Changes in products and production methods</li><li>Introduced and implemented within the institute</li></ul>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-process\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(59,130,246,0.2),rgba(16,185,129,0.2));\">⚗</span> Entrepreneurial Process</h2>\n      <ol class=\"step-list\">\n        <li><strong>Discovery</strong> — Generate ideas, identify opportunities through environmental study, study the marketplace</li>\n        <li><strong>Concept Development &amp; Business Plan</strong> — Prepare a detailed program clarifying the business idea</li>\n        <li><strong>Resourcing</strong> — Identify and acquire financial, human and physical resources</li>\n        <li><strong>Actualization</strong> — Carry out operational activities, use resources to fulfil aims</li>\n        <li><strong>Harvesting</strong> — Take decisions regarding future growth and development</li>\n      </ol>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-entrepreneur\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(245,158,11,0.2),rgba(236,72,153,0.2));\">☶</span> The Entrepreneur</h2>\n      <div class=\"def-box\">“The person who sees changes in the marketplace as opportunities for businesses is an entrepreneur. His armory is product innovation.” <br><span style=\"font-size:13px;color:var(--text-dim);\">— Peter F. Drucker</span></div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('ent-vs-biz')\">▼ Entrepreneur vs Businessman</button>\n      <div id=\"ent-vs-biz\" style=\"display:none;\">\n        <table class=\"comparison-table\">\n          <tbody><tr><th>Aspect</th><th>Entrepreneur</th><th>Businessman</th></tr>\n          <tr><td>Orientation</td><td>Innovation &amp; opportunity</td><td>Profit &amp; operations</td></tr>\n          <tr><td>Risk</td><td>High risk taker</td><td>Calculated risk</td></tr>\n          <tr><td>Approach</td><td>Creative, disruptive</td><td>Systematic, established</td></tr>\n          <tr><td>Focus</td><td>Change &amp; growth</td><td>Stability &amp; efficiency</td></tr>\n        </tbody></table>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('ent-chars')\">▼ Entrepreneurial Characteristics</button>\n      <div id=\"ent-chars\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li><strong>Willingness to take risks</strong> — Faces risks rather than avoids them</li>\n          <li><strong>Creativity</strong> — Ability to see, think and take actions differently</li>\n          <li><strong>Commitment</strong> — Works with great enthusiasm until objectives achieved</li>\n          <li><strong>Self-confidence</strong> — Believes he can successfully overcome problems</li>\n          <li><strong>Self-reliant</strong> — Puts own ideas into effect rather than depending on others</li>\n        </ul>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('ent-skills')\">▼ Entrepreneurial Skills</button>\n      <div id=\"ent-skills\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li><strong>Leadership skills</strong> — Leads followers by encouraging them</li>\n          <li><strong>Interpersonal skills</strong> — Maintains favorable relationships</li>\n          <li><strong>Communication skills</strong> — Maintains proper coordination</li>\n          <li><strong>Basic management skills</strong> — Planning, organizing, leading, controlling</li>\n        </ul>\n        <p style=\"margin:12px 0;color:var(--text-dim);font-size:14px;\">Ways to develop: Self-evaluation, Training, Education, Profiting from experiences</p>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-sme\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(16,185,129,0.2),rgba(59,130,246,0.2));\">⚙</span> Small &amp; Medium Scale Businesses</h2>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('sme-chars')\">▼ Characteristics</button>\n      <div id=\"sme-chars\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Having a small market</li>\n          <li>Invested capital being low</li>\n          <li>Fewer staff employed</li>\n          <li>Family labor used most probably</li>\n          <li>Decision making based on personal information</li>\n          <li>Owner is the chief manager</li>\n          <li>Targeted at local markets</li>\n          <li>Fewer financial bonds</li>\n          <li>Modern technology being used</li>\n        </ul>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('sme-contribution')\">▼ Contribution to Economic Development</button>\n      <div id=\"sme-contribution\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Labor intensive → more employment</li>\n          <li>Contribution to national product growth</li>\n          <li>Utilizing inland resources</li>\n          <li>Minimizing urbanization problems through regional development</li>\n          <li>Minimizing income inequality</li>\n          <li>Supplementing raw materials and finished goods for large-scale businesses</li>\n          <li>Engaging in affairs not performed by large businesses</li>\n        </ul>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('sme-success')\">▼ Success &amp; Failure Factors</button>\n      <div id=\"sme-success\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Reasons for Success</h4>\n            <ul><li>Sufficient infrastructure</li><li>Financial and tax incentives</li><li>Expanded market</li><li>Institutional and marketing facilities</li><li>Sound management</li><li>Enthusiasm and commitment</li></ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Reasons for Failure</h4>\n            <ul><li>Financial problems</li><li>Inability to face competition</li><li>Weak management</li><li>Less entrepreneurial skills</li><li>Insufficient infrastructure</li><li>Low technology awareness</li></ul>\n          </div>\n        </div>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('sme-consider')\">▼ Factors to Consider When Starting</button>\n      <div id=\"sme-consider\" style=\"display:none;\">\n        <ul class=\"list\">\n          <li>Studying and evaluating one’s own abilities and skills</li>\n          <li>Market availability and entry possibilities</li>\n          <li>Opening capital and working capital requirements</li>\n          <li>Type of business organization</li>\n          <li>Existing rules and regulations</li>\n          <li>Existing competition</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-incentives\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(251,191,36,0.2),rgba(16,185,129,0.2));\">★</span> Incentives for SMEs</h2>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('inc-types')\">▼ Types of Incentives</button>\n      <div id=\"inc-types\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Financial Incentives</h4>\n            <ul><li>Short-term &amp; long-term loans</li><li>Financial assistance</li><li>Tax concessions</li><li>Refinancing facilities</li></ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Non-Financial Incentives</h4>\n            <ul><li>Advisory services</li><li>Entrepreneur development programs</li><li>Research and technological services</li><li>Infrastructure facilities</li><li>Market facilities</li><li>Awards and excellence awards</li></ul>\n          </div>\n        </div>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('inc-orgs')\">▼ Organizations Providing Incentives</button>\n      <div id=\"inc-orgs\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Government Institutions</h4>\n            <ul><li>Industrial Development Board</li><li>Export Development Board</li><li>SL Standards Institution</li><li>National Development Bank</li><li>Industrial Technology Institution</li></ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Other Institutions</h4>\n            <ul><li>Sarvodaya</li><li>JICA</li><li>Private tax organizations</li><li>Sanasa</li><li>Private banks &amp; financial institutions</li></ul>\n          </div>\n        </div>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('inc-projects')\">▼ Current Loan Projects</button>\n      <div id=\"inc-projects\" style=\"display:none;\">\n        <ul class=\"list\">\n          <li><strong>Liya Isura</strong> — Interest-free loans for women micro-entrepreneurs (Regional Development Bank)</li>\n          <li><strong>Suwana / SMILE</strong> — Small and Micro Industries Leader and Entrepreneur promotion (NDB with JBIC)</li>\n          <li><strong>Shanya</strong> — Loan scheme with Asian Development Bank (DFCC and commercial banks)</li>\n          <li><strong>Sanasa Loan Project</strong> — Loans for agrarians, livestock, small industry, trading</li>\n          <li><strong>Co-operative Rural Bank Loans</strong> — For agrarian, fisheries, livestock, trading</li>\n          <li><strong>Samurdhi / Divineguma Loan Scheme</strong> — For Samurdhi beneficiaries</li>\n          <li><strong>Agrarian Bank Pilot Project</strong> — Short and long-term loans for farmers</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <footer>\n    <p>Business Studies — Lesson 5 • Entrepreneurship • Based on original lesson notes</p>\n  </footer>\n</div>\n<script>\n  const canvas = document.getElementById('particles-canvas');\n  const ctx = canvas.getContext('2d');\n  let particles = []; let mouseX = -1000, mouseY = -1000;\n  function resize() { canvas.width = window.innerWidth; canvas.height = window.innerHeight; }\n  resize(); window.addEventListener('resize', resize);\n  class Particle {\n    constructor() { this.reset(); }\n    reset() { this.x = Math.random()*canvas.width; this.y = Math.random()*canvas.height; this.size = Math.random()*2+0.5; this.speedX = (Math.random()-0.5)*0.3; this.speedY = (Math.random()-0.5)*0.3; this.opacity = Math.random()*0.5+0.1; }\n    update() { this.x+=this.speedX; this.y+=this.speedY; if(this.x<0||this.x>canvas.width)this.speedX*=-1; if(this.y<0||this.y>canvas.height)this.speedY*=-1; const dx=this.x-mouseX,dy=this.y-mouseY,dist=Math.sqrt(dx*dx+dy*dy); if(dist<120){const force=(120-dist)/120;this.x+=dx*force*0.008;this.y+=dy*force*0.008;} }\n    draw() { ctx.beginPath(); ctx.arc(this.x,this.y,this.size,0,Math.PI*2); ctx.fillStyle=`rgba(212,165,116,${this.opacity})`; ctx.fill(); }\n  }\n  for(let i=0;i<120;i++)particles.push(new Particle());\n  function animateParticles(){ctx.clearRect(0,0,canvas.width,canvas.height);particles.forEach(p=>{p.update();p.draw();});for(let i=0;i<particles.length;i++){for(let j=i+1;j<particles.length;j++){const dx=particles[i].x-particles[j].x,dy=particles[i].y-particles[j].y,dist=Math.sqrt(dx*dx+dy*dy);if(dist<140){ctx.beginPath();ctx.moveTo(particles[i].x,particles[i].y);ctx.lineTo(particles[j].x,particles[j].y);ctx.strokeStyle=`rgba(212,165,116,${0.06*(1-dist/140)})`;ctx.lineWidth=0.5;ctx.stroke();}}}requestAnimationFrame(animateParticles);}\n  animateParticles();\n  document.addEventListener('mousemove',e=>{mouseX=e.clientX;mouseY=e.clientY;});\n  window.addEventListener('scroll',()=>{const s=document.documentElement.scrollTop,h=document.documentElement.scrollHeight-document.documentElement.clientHeight;document.getElementById('progress-bar').style.width=(s/h*100)+'%';});\n  const observer=new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible');});},{threshold:0.1});\n  document.querySelectorAll('.section').forEach(s=>observer.observe(s));\n  function toggleSection(id){const el=document.getElementById(id);if(el.style.display==='none'){el.style.display='block';el.style.animation='fadeUp 0.4s ease forwards';}else{el.style.display='none';}}\n</script>\n\n\n\n</body>\n</html>",
    "6": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n<div class=\"ambient-glow\"></div>\n<div class=\"ambient-glow\"></div>\n<div class=\"ambient-glow\"></div>\n<canvas id=\"particles-canvas\"></canvas>\n<div class=\"progress-bar\" id=\"progress-bar\"></div>\n<div class=\"content\">\n\n\n  <header>\n    <div class=\"badge\">Business Studies — Lesson 6</div>\n    <h1>Money and Financial Institutions</h1>\n    <p>Functions and types of money, financial institutions, central bank, commercial banks, cheques, and electronic money.</p>\n  </header>\n  <nav class=\"toc\">\n    <a href=\"#sec-money\"><span class=\"num\">1</span> Money</a>\n    <a href=\"#sec-functions\"><span class=\"num\">2</span> Functions</a>\n    <a href=\"#sec-categories\"><span class=\"num\">3</span> Categories</a>\n    <a href=\"#sec-institutions\"><span class=\"num\">4</span> Institutions</a>\n    <a href=\"#sec-cbsl\"><span class=\"num\">5</span> Central Bank</a>\n    <a href=\"#sec-commercial\"><span class=\"num\">6</span> Commercial Banks</a>\n    <a href=\"#sec-cheque\"><span class=\"num\">7</span> Cheques</a>\n    <a href=\"#sec-emoney\"><span class=\"num\">8</span> E-Money</a>\n  </nav>\n\n  <div class=\"section\" id=\"sec-money\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(16,185,129,0.2),rgba(245,158,11,0.2));\">☂</span> What is Money?</h2>\n      <div class=\"def-box\">Anything that is generally accepted in exchange for goods and services is considered as <strong>money</strong>.</div>\n      <p style=\"color:var(--text-dim);font-size:15px;\">Before money, the barter system was used — direct exchange of goods — which had many difficulties. Money emerged as a common medium of exchange acceptable to all.</p>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-functions\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(245,158,11,0.2),rgba(16,185,129,0.2));\">⚙</span> Functions of Money</h2>\n      <ul class=\"features\">\n        <li><strong>Medium of exchange</strong> — Intermediary in exchange of goods/services (e.g. buying a phone for Rs. 30,000)</li>\n        <li><strong>Standard of value</strong> — Measuring the value of goods and services (e.g. price of shoes Rs. 1,999.90)</li>\n        <li><strong>Store of value</strong> — Can be stored for future use without getting outdated (e.g. saving Rs. 10,000)</li>\n        <li><strong>Deferred payment</strong> — Agreement for future payment (e.g. buy goods in Jan, pay in March)</li>\n      </ul>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('good-currency')\">▼ Characteristics of a Good Currency</button>\n      <div id=\"good-currency\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Having general recognition</li>\n          <li>Durability</li>\n          <li>Difficulty in imitation</li>\n          <li>Easy movability</li>\n          <li>Easy identifiability / homogeneity</li>\n          <li>Ability to divide into small units (divisibility)</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-categories\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(59,130,246,0.2),rgba(16,185,129,0.2));\">♺</span> Categories of Money</h2>\n      <div class=\"grid-2\">\n        <div class=\"grid-item\">\n          <h4>Currency</h4>\n          <ul><li>Notes &amp; coins issued on orders of financial authority</li><li>100% liquidity</li></ul>\n        </div>\n        <div class=\"grid-item\">\n          <h4>Bank Money</h4>\n          <ul><li>Balances in demand/current accounts</li><li>Payments made via cheques</li><li>High liquidity (not 100%)</li></ul>\n        </div>\n        <div class=\"grid-item\">\n          <h4>Near Money</h4>\n          <ul><li>Assets that function as a store of value</li><li>Can be converted to cash easily</li><li>Time deposits, savings deposits, Treasury bills</li></ul>\n        </div>\n        <div class=\"grid-item\">\n          <h4>E-Money</h4>\n          <ul><li>Money from digital technology</li><li>Used in inland &amp; international transactions</li><li>Debit cards, credit cards, pre-paid cards</li></ul>\n        </div>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('card-facilities')\">▼ Card Payment Facilities</button>\n      <div id=\"card-facilities\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Automatic Teller Machine (ATM)</li>\n          <li>Automatic Deposits Machine (ADM)</li>\n          <li>Cheques Deposits Machines (CDM)</li>\n          <li>Electronic Funds Transfer point of sales</li>\n          <li>Telebanking, Internet banking, Television banking</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-institutions\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(245,158,11,0.2),rgba(59,130,246,0.2));\">♿</span> Financial Institutions in Sri Lanka</h2>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('fi-detail')\">▼ Categories &amp; Details</button>\n      <div id=\"fi-detail\" style=\"display:none;\">\n        <table class=\"comparison-table\">\n          <tbody><tr><th>Category</th><th>Examples</th></tr>\n          <tr><td><strong>Banking Sector</strong><br>Central Bank, Licensed commercial banks, Licensed specialized banks</td><td>BOC, People’s Bank, Sampath, HNB, Seylan, NSB, Regional Development Bank</td></tr>\n          <tr><td><strong>Deposit-taking Institutions</strong><br>Licensed finance companies, Co-operative Rural Banks, SANASA</td><td>LB Finance, Singer Finance, Maharagama CRB, Nelumkulama Sanasa</td></tr>\n          <tr><td><strong>Specialized Institutions</strong><br>Leasing companies, Primary dealers, Share brokers, Unit trusts</td><td>Asset Line Leasing, Capital Alliance, Asha Securities</td></tr>\n          <tr><td><strong>Contracted Savings</strong><br>Insurance companies, EPF, ETF, Pension funds</td><td>SL Insurance, Ceylinco Insurance</td></tr>\n        </tbody></table>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('fi-contribution')\">▼ How They Support Businesses</button>\n      <div id=\"fi-contribution\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Accepting time and savings deposits</li>\n          <li>Providing loan facilities to entrepreneurs</li>\n          <li>Underwriting of company shares</li>\n          <li>Providing leasing facilities</li>\n          <li>Providing management advisory services</li>\n          <li>Hire-purchase facilities</li>\n          <li>Pawning activities</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-cbsl\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(59,130,246,0.2),rgba(16,185,129,0.2));\">⚗</span> Central Bank of Sri Lanka</h2>\n      <div class=\"def-box\">Established on <strong>28th August 1950</strong> under the Monetary Act No. 58 of 1949. Founder Governor: Mr. John Exter.</div>\n      <p style=\"margin:12px 0;font-weight:600;color:var(--accent);\">Two Main Objectives</p>\n      <ul class=\"features\">\n        <li><strong>Maintain economic and price stability</strong> — Protect domestic currency value, avoid inflation/deflation</li>\n        <li><strong>Maintain stability of the financial system</strong> — Create security, identify and minimize threats</li>\n      </ul>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('cbsl-activities')\">▼ Key Activities</button>\n      <div id=\"cbsl-activities\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Manipulation of finance policies</li>\n          <li>Manipulation of exchange ratio policies</li>\n          <li>Management of official foreign reserves</li>\n          <li>Issuing and distribution of currency</li>\n          <li>Supervisor of banks and non-banking institutions</li>\n          <li>Financial agent, banker and economic advisor of the government</li>\n          <li>Settlement accounts for commercial banks and primary traders</li>\n        </ul>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('cbsl-systems')\">▼ Payment Systems</button>\n      <div id=\"cbsl-systems\" style=\"display:none;\">\n        <ul class=\"list\">\n          <li><strong>SLIPS</strong> — Inter-bank payment system (now Lanka Clear Pvt Ltd, brand: LankaPay)</li>\n          <li><strong>SWIFT</strong> — Universal Interbank Financial Electronic Communication Network</li>\n          <li><strong>RTGS</strong> — Real Time Gross Settlement for high-value transfers</li>\n          <li><strong>SSDS (LankaSecure)</strong> — Paperless securities depository system</li>\n          <li><strong>Lanka Settle System</strong> — RTGS + SSDS combined</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-commercial\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(16,185,129,0.2),rgba(59,130,246,0.2));\">☰</span> Commercial Banks</h2>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('cb-deposits')\">▼ Deposit Services</button>\n      <div id=\"cb-deposits\" style=\"display:none;\">\n        <table class=\"comparison-table\">\n          <tbody><tr><th>Account Type</th><th>Features</th></tr>\n          <tr><td><strong>Current Account</strong></td><td>Cheque transactions, no interest, overdraft facility</td></tr>\n          <tr><td><strong>Savings Account</strong></td><td>Interest on balance, flexible deposits/withdrawals</td></tr>\n          <tr><td><strong>Fixed Deposit</strong></td><td>Fixed sum for fixed period, higher interest rate</td></tr>\n        </tbody></table>\n        <p style=\"margin:12px 0;color:var(--text-dim);font-size:14px;\">Benefits: payments via cheques, remittance, standing orders, overdraft, bank statements</p>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('cb-loans')\">▼ Lending Services</button>\n      <div id=\"cb-loans\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Overdraft</h4>\n            <ul><li>Approval to issue cheques above balance</li><li>Temporary or permanent</li><li>Higher interest rate</li><li>Permanent requires security</li></ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Loans</h4>\n            <ul><li><strong>Business loans</strong> — short/medium/long term for business needs</li><li><strong>Consumer loans</strong> — for purchasing assets or emergency needs</li></ul>\n          </div>\n        </div>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('cb-other')\">▼ Other Services</button>\n      <div id=\"cb-other\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Agency services (purchase/sale of securities, standing orders, bill payments, leasing)</li>\n          <li>E-Banking (home banking, tele banking)</li>\n          <li>Pawning services (emergency loans against jewelry)</li>\n          <li>Safety locker facilities</li>\n          <li>Purchase and sale of foreign exchange</li>\n          <li>Credit card services (Visa, Master, Amex)</li>\n          <li>Money remittance activities</li>\n          <li>Traveler’s cheques</li>\n          <li>Automatic banking services (ATM, cash/cheque deposit)</li>\n          <li>Letters of credit</li>\n          <li>Insurance services, medical services (e-Channeling)</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-cheque\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(245,158,11,0.2),rgba(239,68,68,0.2));\">✎</span> Cheques</h2>\n      <div class=\"def-box\">A cheque is a written order issued by a bank current account holder (<strong>drawer</strong>) to the commercial bank (<strong>drawee</strong>) to pay the amount stated to the person named (<strong>payee</strong>) or bearer.</div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('cheque-types')\">▼ Types of Cheques</button>\n      <div id=\"cheque-types\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Bearer Cheque</h4>\n            <ul><li>\"Or Bearer\" not cancelled</li><li>Can be transferred by handing over</li><li>Like using currency notes</li></ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Order Cheque</h4>\n            <ul><li>\"Or Bearer\" struck off, \"Order\" written</li><li>Requires endorsement to transfer</li><li>Higher safety level</li></ul>\n          </div>\n        </div>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('cheque-crossing')\">▼ Crossing &amp; Dishonoring</button>\n      <div id=\"cheque-crossing\" style=\"display:none;\">\n        <p style=\"margin:12px 0;color:var(--accent);font-weight:500;\">Crossing (drawing two parallel lines on the cheque) adds safety.</p>\n        <ul class=\"list\">\n          <li><strong>General Crossing</strong> — Two parallel lines with or without statements</li>\n          <li><strong>Special Crossing</strong> — Name of a commercial bank stated; must be deposited in that bank</li>\n          <li>\"Not Negotiable\" — Transferee has no greater right than transferor</li>\n          <li>\"Account Payee Only\" — Must be deposited in payee’s account</li>\n        </ul>\n        <p style=\"margin:12px 0;color:var(--accent);font-weight:500;\">Dishonoring occurs when the bank rejects payment.</p>\n        <ul class=\"list\">\n          <li>Insufficient funds</li>\n          <li>Drawer stops payment (countermanded)</li>\n          <li>Drawer bankrupt or deceased</li>\n          <li>Garnishee order (court order)</li>\n          <li>Errors in writing, account closed</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-emoney\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(99,102,241,0.2),rgba(16,185,129,0.2));\">♻</span> Electronic Money</h2>\n      <div class=\"def-box\">The electronic exchange of cash or cash exchanged through a computer network is known as <strong>e-money</strong>.</div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('emoney-types')\">▼ Types</button>\n      <div id=\"emoney-types\" style=\"display:none;\">\n        <table class=\"comparison-table\">\n          <tbody><tr><th>Type</th><th>Description</th></tr>\n          <tr><td><strong>Credit Card</strong></td><td>Buy goods/services up to a limit; interest-free loan period; cash from ATM</td></tr>\n          <tr><td><strong>Debit Card</strong></td><td>Use money from account; no interest; ATM withdrawals</td></tr>\n          <tr><td><strong>Pre-Paid Card</strong></td><td>Pay in advance; no account needed; e.g. phone cards, travel passes</td></tr>\n          <tr><td><strong>Smart Card</strong></td><td>Embedded chip with money value; reloadable; acts as e-purse</td></tr>\n          <tr><td><strong>Micro Chips</strong></td><td>Integrated circuit for transactions</td></tr>\n        </tbody></table>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('emoney-proscons')\">▼ Pros &amp; Cons</button>\n      <div id=\"emoney-proscons\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Advantages</h4>\n            <ul><li>Minimized transaction costs</li><li>Safety of cash</li><li>24/7 transactions</li><li>Convenient payments</li><li>Various benefits &amp; discounts</li><li>Overseas usability</li></ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Disadvantages</h4>\n            <ul><li>Interest, penalties on late payments</li><li>Fraud risk</li><li>Addiction to unnecessary consumption</li><li>Technical interruptions</li><li>Lack of knowledge for some users</li></ul>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <footer>\n    <p>Business Studies — Lesson 6 • Money and Financial Institutions • Based on original lesson notes</p>\n  </footer>\n</div>\n<script>\n  const canvas = document.getElementById('particles-canvas');\n  const ctx = canvas.getContext('2d');\n  let particles=[];let mouseX=-1000,mouseY=-1000;\n  function resize(){canvas.width=window.innerWidth;canvas.height=window.innerHeight;}\n  resize();window.addEventListener('resize',resize);\n  class Particle{constructor(){this.reset();}reset(){this.x=Math.random()*canvas.width;this.y=Math.random()*canvas.height;this.size=Math.random()*2+0.5;this.speedX=(Math.random()-0.5)*0.3;this.speedY=(Math.random()-0.5)*0.3;this.opacity=Math.random()*0.5+0.1;}update(){this.x+=this.speedX;this.y+=this.speedY;if(this.x<0||this.x>canvas.width)this.speedX*=-1;if(this.y<0||this.y>canvas.height)this.speedY*=-1;const dx=this.x-mouseX,dy=this.y-mouseY,dist=Math.sqrt(dx*dx+dy*dy);if(dist<120){const force=(120-dist)/120;this.x+=dx*force*0.008;this.y+=dy*force*0.008;}}draw(){ctx.beginPath();ctx.arc(this.x,this.y,this.size,0,Math.PI*2);ctx.fillStyle=`rgba(110,231,183,${this.opacity})`;ctx.fill();}}\n  for(let i=0;i<120;i++)particles.push(new Particle());\n  function animateParticles(){ctx.clearRect(0,0,canvas.width,canvas.height);particles.forEach(p=>{p.update();p.draw();});for(let i=0;i<particles.length;i++){for(let j=i+1;j<particles.length;j++){const dx=particles[i].x-particles[j].x,dy=particles[i].y-particles[j].y,dist=Math.sqrt(dx*dx+dy*dy);if(dist<140){ctx.beginPath();ctx.moveTo(particles[i].x,particles[i].y);ctx.lineTo(particles[j].x,particles[j].y);ctx.strokeStyle=`rgba(110,231,183,${0.06*(1-dist/140)})`;ctx.lineWidth=0.5;ctx.stroke();}}}requestAnimationFrame(animateParticles);}\n  animateParticles();\n  document.addEventListener('mousemove',e=>{mouseX=e.clientX;mouseY=e.clientY;});\n  window.addEventListener('scroll',()=>{const s=document.documentElement.scrollTop,h=document.documentElement.scrollHeight-document.documentElement.clientHeight;document.getElementById('progress-bar').style.width=(s/h*100)+'%';});\n  const observer=new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible');});},{threshold:0.1});\n  document.querySelectorAll('.section').forEach(s=>observer.observe(s));\n  function toggleSection(id){const el=document.getElementById(id);if(el.style.display==='none'){el.style.display='block';el.style.animation='fadeUp 0.4s ease forwards';}else{el.style.display='none';}}\n</script>\n\n\n\n</body>\n</html>",
    "7": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n<div class=\"ambient-glow\"></div>\n<div class=\"ambient-glow\"></div>\n<div class=\"ambient-glow\"></div>\n<canvas id=\"particles-canvas\"></canvas>\n<div class=\"progress-bar\" id=\"progress-bar\"></div>\n<div class=\"content\">\n\n\n  <header>\n    <div class=\"badge\">Business Studies — Lesson 7</div>\n    <h1>Insurance</h1>\n    <p>Risk, insurable vs non-insurable risks, principles of insurance, life insurance, and general insurance categories.</p>\n  </header>\n  <nav class=\"toc\">\n    <a href=\"#sec-risk\"><span class=\"num\">1</span> Risk &amp; Insurance</a>\n    <a href=\"#sec-principles\"><span class=\"num\">2</span> Principles</a>\n    <a href=\"#sec-life\"><span class=\"num\">3</span> Life Insurance</a>\n    <a href=\"#sec-fire\"><span class=\"num\">4</span> Fire Insurance</a>\n    <a href=\"#sec-theft\"><span class=\"num\">5</span> Theft &amp; Marine</a>\n    <a href=\"#sec-motor\"><span class=\"num\">6</span> Motor Insurance</a>\n    <a href=\"#sec-liability\"><span class=\"num\">7</span> Liability</a>\n    <a href=\"#sec-transit\"><span class=\"num\">8</span> Transit Insurance</a>\n  </nav>\n\n  <div class=\"section\" id=\"sec-risk\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(14,165,233,0.2),rgba(20,184,166,0.2));\">⚠</span> Risk &amp; Insurance</h2>\n      <div class=\"def-box\">The space of occurring damage which can be estimated financially is known as a <strong>risk</strong> in insurance.</div>\n      <p style=\"margin:12px 0;color:var(--text-dim);font-size:15px;\">Business risks include: fire, theft, business loss, damage to properties.</p>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('insurable')\">▼ Insurable vs Non-Insurable Risks</button>\n      <div id=\"insurable\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Insurable Risks</h4>\n            <ul><li>Can be forecast</li><li>Calculable in money terms</li><li>Not certain (random)</li><li>No connection to other insured loss</li><li>Verifiable cause, place, time</li></ul>\n            <p style=\"margin-top:8px;font-size:13px;color:var(--accent);\">E.g. fire, motor accidents, money in transit, debtor non-payment</p>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Non-Insurable Risks</h4>\n            <ul><li>Business losses</li><li>Natural reasons (depreciation, expiration, vaporization)</li><li>One’s ability/strength (exam failure, loss of love)</li><li>Design changes</li></ul>\n          </div>\n        </div>\n      </div>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('insurance-def')\">▼ Insurance Agreement</button>\n      <div id=\"insurance-def\" style=\"display:none;\">\n        <div class=\"def-box\" style=\"border-left-color:var(--accent2);\">Insurance is an agreement between the <strong>insurer</strong> and the <strong>insured</strong> whereby the insured pays the premium and the insurer pays compensation for insured risks.</div>\n        <ul class=\"list\">\n          <li><strong>Insured (1st party)</strong> — Person who presents proposal / obtains coverage</li>\n          <li><strong>Insurer (2nd party)</strong> — Insurance company that accepts the proposal</li>\n          <li><strong>Third party</strong> — External party that comes into activation of the agreement</li>\n        </ul>\n      </div>\n\n      <p style=\"margin:16px 0;color:var(--text-dim);font-size:14px;\">\n        Insurance agreement validity requires: idea of legal obligation, insurance offer/proposal, acceptance, legal validity, ability to have legal obligation by parties.\n      </p>\n      <p style=\"margin:16px 0;color:var(--text-dim);font-size:14px;\">\n        <strong>Insurance policy</strong> is a written certificate given by the insurance institute to the insured after the agreement.\n      </p>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-principles\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(20,184,166,0.2),rgba(14,165,233,0.2));\">♺</span> Principles of Insurance</h2>\n      <ul class=\"features\">\n        <li><strong>Insurable Interest</strong> — Economic advantage from existence; disadvantage from loss. E.g. spouse has interest in each other’s life; legal owner in property; creditor in debtor’s life</li>\n        <li><strong>Utmost Good Faith</strong> — Both parties reveal all information related to the agreement morally</li>\n        <li><strong>Indemnity</strong> — Payment of adequate compensation to restore the damaged property (e.g. Rs. 2.5L paid for Rs. 2.5L damage on Rs. 40L vehicle)</li>\n        <li><strong>Contribution</strong> — When insured in multiple companies, they pay proportionately (e.g. 5:3:2 ratio)</li>\n        <li><strong>Subrogation</strong> — After settling loss, insurer obtains other rights/advantages from external parties (e.g. insurer takes debris after total loss)</li>\n        <li><strong>Proximate Cause</strong> — Compensation paid only if the proximate (nearest) reason is covered by the policy</li>\n      </ul>\n\n      <button class=\"toggle-btn\" onclick=\"toggleSection('principles-notes')\">▼ Key Notes</button>\n      <div id=\"principles-notes\" style=\"display:none;\">\n        <ul class=\"list\">\n          <li>Insurable interest, utmost good faith, and proximate cause apply to <strong>life insurance</strong></li>\n          <li>Indemnity, contribution, subrogation do <strong>not</strong> apply to life insurance (loss is immeasurable)</li>\n          <li><strong>Reinsurance</strong> — Insurer insures a risk it has undertaken under another insurance company</li>\n          <li><strong>Underwriting</strong> — Dividing a high-value risk among several insurance companies</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-life\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(245,158,11,0.2),rgba(14,165,233,0.2));\">☷</span> Life Insurance / Long Term Insurance</h2>\n      <div class=\"def-box\">Provides monetary benefits to the insured or beneficiaries against risks due to demise, disability, or old age.</div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('life-details')\">▼ Features &amp; Differences</button>\n      <div id=\"life-details\" style=\"display:none;\">\n        <table class=\"comparison-table\">\n          <tbody><tr><th>Life Insurance</th><th>Other Insurance</th></tr>\n          <tr><td>Risk is certain</td><td>Risk is uncertain</td></tr>\n          <tr><td>Indemnity principle NOT relevant</td><td>Indemnity principle is relevant</td></tr>\n          <tr><td>Equal to a saving</td><td>Compensation only when loss occurs</td></tr>\n          <tr><td>Policy cannot be transferred</td><td>Policy can be transferred</td></tr>\n        </tbody></table>\n        <p style=\"margin:12px 0;color:var(--text-dim);font-size:14px;\">If the insured dies during the period, the agreed value goes to beneficiaries. If they live until the end, they obtain the policy value and benefits.</p>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-fire\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(239,68,68,0.2),rgba(245,158,11,0.2));\">🔥</span> Fire Insurance</h2>\n      <div class=\"def-box\">Covers losses caused to a person, building, or property due to fire.</div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('fire-extras')\">▼ Additional Covered Risks (with extra premium)</button>\n      <div id=\"fire-extras\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Losses by riots / strikes</li>\n          <li>Losses by explosions</li>\n          <li>Losses by electricity</li>\n          <li>Earthquakes / tsunami</li>\n          <li>Flood / whirl winds / storms</li>\n          <li>Aircraft crashes</li>\n          <li>Losses from crashes</li>\n          <li>Consequential losses</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-theft\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(99,102,241,0.2),rgba(14,165,233,0.2));\">🔒</span> Theft &amp; Marine Insurance</h2>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('theft-detail')\">▼ Theft &amp; Burglary Insurance</button>\n      <div id=\"theft-detail\" style=\"display:none;\">\n        <p style=\"margin:12px 0;color:var(--text-dim);font-size:14px;\">Covers risks to business premises or homes from thievery. Natural disaster insurance covers losses from storms etc.</p>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('marine-detail')\">▼ Marine Insurance</button>\n      <div id=\"marine-detail\" style=\"display:none;\">\n        <p style=\"margin:12px 0;color:var(--text-dim);font-size:14px;\">Covers losses to ships and goods while transporting by sea. Two parts:</p>\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Hull Insurance</h4>\n            <ul><li>Full option (comprehensive) policy</li><li>Total loss policy</li><li>Port risk policy</li><li>Maintenance policy</li><li>Construction all risk policy</li></ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>Cargo Insurance</h4>\n            <ul><li>Valued policy</li><li>Open cover / floating policy</li><li>Future time policy</li></ul>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-motor\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(16,185,129,0.2),rgba(14,165,233,0.2));\">🚗</span> Motor Traffic Insurance</h2>\n      <div class=\"def-box\">An agreement between a vehicle owner and an insurance company for compensation against motor vehicle accidents.</div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('motor-types')\">▼ Types of Motor Insurance</button>\n      <div id=\"motor-types\" style=\"display:none;\">\n        <table class=\"comparison-table\">\n          <tbody><tr><th>Type</th><th>Coverage</th></tr>\n          <tr><td><strong>Full Insurance</strong></td><td>Loss to the vehicle, people, and properties that travel in the vehicle</td></tr>\n          <tr><td><strong>Third Party Fire &amp; Theft</strong></td><td>Loss to vehicle by fire/theft + losses to external people and properties</td></tr>\n          <tr><td><strong>Minimum Third Party</strong></td><td>Loss only to third party and properties (minimum required to drive on the road)</td></tr>\n        </tbody></table>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-liability\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(139,92,246,0.2),rgba(14,165,233,0.2));\">⚖</span> Liability Insurance</h2>\n      <div class=\"def-box\">Ensuring the liability for losses caused to other parties is known as <strong>liability insurance</strong>.</div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('liability-types')\">▼ Types</button>\n      <div id=\"liability-types\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li><strong>General Liability Insurance</strong> — For unexpected losses from properties or business activities</li>\n          <li><strong>Product Liability Insurance</strong> — For losses to consumers from consuming products sold</li>\n          <li><strong>Employer Liability Insurance</strong> — Covers employer’s compensation liability for employee accidents at work</li>\n          <li><strong>Goods in Transit Insurance</strong> — Covers losses to goods from loading to unloading during land transport</li>\n          <li><strong>Money in Transit Insurance</strong> — Covers loss while taking money from one place to another</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-transit\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(245,158,11,0.2),rgba(16,185,129,0.2));\">🚚</span> Goods &amp; Money in Transit</h2>\n      <div class=\"grid-2\">\n        <div class=\"grid-item\">\n          <h4>Goods in Transit Insurance</h4>\n          <ul><li>Covers losses from loading to unloading</li><li>For transport on land</li><li>Protects goods during the journey</li></ul>\n        </div>\n        <div class=\"grid-item\">\n          <h4>Money in Transit Insurance</h4>\n          <ul><li>Covers loss while moving money</li><li>Between locations</li><li>Essential for cash-heavy businesses</li></ul>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <footer>\n    <p>Business Studies — Lesson 7 • Insurance • Based on original lesson notes</p>\n  </footer>\n</div>\n<script>\n  const canvas = document.getElementById('particles-canvas');\n  const ctx = canvas.getContext('2d');\n  let particles=[];let mouseX=-1000,mouseY=-1000;\n  function resize(){canvas.width=window.innerWidth;canvas.height=window.innerHeight;}\n  resize();window.addEventListener('resize',resize);\n  class Particle{constructor(){this.reset();}reset(){this.x=Math.random()*canvas.width;this.y=Math.random()*canvas.height;this.size=Math.random()*2+0.5;this.speedX=(Math.random()-0.5)*0.3;this.speedY=(Math.random()-0.5)*0.3;this.opacity=Math.random()*0.5+0.1;}update(){this.x+=this.speedX;this.y+=this.speedY;if(this.x<0||this.x>canvas.width)this.speedX*=-1;if(this.y<0||this.y>canvas.height)this.speedY*=-1;const dx=this.x-mouseX,dy=this.y-mouseY,dist=Math.sqrt(dx*dx+dy*dy);if(dist<120){const force=(120-dist)/120;this.x+=dx*force*0.008;this.y+=dy*force*0.008;}}draw(){ctx.beginPath();ctx.arc(this.x,this.y,this.size,0,Math.PI*2);ctx.fillStyle=`rgba(125,211,252,${this.opacity})`;ctx.fill();}}\n  for(let i=0;i<120;i++)particles.push(new Particle());\n  function animateParticles(){ctx.clearRect(0,0,canvas.width,canvas.height);particles.forEach(p=>{p.update();p.draw();});for(let i=0;i<particles.length;i++){for(let j=i+1;j<particles.length;j++){const dx=particles[i].x-particles[j].x,dy=particles[i].y-particles[j].y,dist=Math.sqrt(dx*dx+dy*dy);if(dist<140){ctx.beginPath();ctx.moveTo(particles[i].x,particles[i].y);ctx.lineTo(particles[j].x,particles[j].y);ctx.strokeStyle=`rgba(125,211,252,${0.06*(1-dist/140)})`;ctx.lineWidth=0.5;ctx.stroke();}}}requestAnimationFrame(animateParticles);}\n  animateParticles();\n  document.addEventListener('mousemove',e=>{mouseX=e.clientX;mouseY=e.clientY;});\n  window.addEventListener('scroll',()=>{const s=document.documentElement.scrollTop,h=document.documentElement.scrollHeight-document.documentElement.clientHeight;document.getElementById('progress-bar').style.width=(s/h*100)+'%';});\n  const observer=new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible');});},{threshold:0.1});\n  document.querySelectorAll('.section').forEach(s=>observer.observe(s));\n  function toggleSection(id){const el=document.getElementById(id);if(el.style.display==='none'){el.style.display='block';el.style.animation='fadeUp 0.4s ease forwards';}else{el.style.display='none';}}\n</script>\n\n\n\n</body>\n</html>",
    "8": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n<div class=\"ambient-glow\"></div>\n<div class=\"ambient-glow\"></div>\n<div class=\"ambient-glow\"></div>\n<canvas id=\"particles-canvas\"></canvas>\n<div class=\"progress-bar\" id=\"progress-bar\"></div>\n<div class=\"content\">\n\n\n  <header>\n    <div class=\"badge\">Business Studies — Lesson 8</div>\n    <h1>Communication</h1>\n    <p>Definition, importance, communication process, media, electronic communication, barriers, and strategies.</p>\n  </header>\n  <nav class=\"toc\">\n    <a href=\"#sec-definition\"><span class=\"num\">1</span> Definition</a>\n    <a href=\"#sec-importance\"><span class=\"num\">2</span> Importance</a>\n    <a href=\"#sec-process\"><span class=\"num\">3</span> Process</a>\n    <a href=\"#sec-effective\"><span class=\"num\">4</span> Effective Comm.</a>\n    <a href=\"#sec-media\"><span class=\"num\">5</span> Media Types</a>\n    <a href=\"#sec-electronic\"><span class=\"num\">6</span> Electronic</a>\n    <a href=\"#sec-barriers\"><span class=\"num\">7</span> Barriers</a>\n    <a href=\"#sec-proscons\"><span class=\"num\">8</span> Pros &amp; Cons</a>\n  </nav>\n\n  <div class=\"section\" id=\"sec-definition\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(168,85,247,0.2),rgba(236,72,153,0.2));\">✉</span> What is Communication?</h2>\n      <div class=\"def-box\">Communication can be defined as sending and receiving information, understanding and sharing information from one party to another or many parties.</div>\n      <p style=\"color:var(--text-dim);font-size:15px;\">Communication is important for <strong>business activities</strong> as well as <strong>social activities</strong>.</p>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-importance\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(236,72,153,0.2),rgba(168,85,247,0.2));\">⚙</span> Importance of Communication</h2>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('imp-biz')\">▼ For Business Activities</button>\n      <div id=\"imp-biz\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>To exchange ideas between parties at businesses</li>\n          <li>To maintain employer-employee relationship</li>\n          <li>To manage human and physical resources well</li>\n          <li>For marketing promotional activities</li>\n        </ul>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('imp-social')\">▼ For Social Activities</button>\n      <div id=\"imp-social\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>To exchange ideas and messages socially</li>\n          <li>To know instantly about international incidents</li>\n          <li>To get information for educational activities</li>\n          <li>To know about new inventions with technological improvement</li>\n          <li>To build social relationships nationally and internationally</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-process\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(6,182,212,0.2),rgba(168,85,247,0.2));\">♻</span> Communication Process</h2>\n      <div class=\"grid-2\">\n        <div class=\"grid-item\">\n          <h4>Sender</h4>\n          <ul><li>The party sending the message</li><li>Speaker/lecturer (verbal) or signer/institution (written)</li></ul>\n        </div>\n        <div class=\"grid-item\">\n          <h4>Message</h4>\n          <ul><li>The information the sender provides to the receiver</li></ul>\n        </div>\n        <div class=\"grid-item\">\n          <h4>Media</h4>\n          <ul><li>How information is provided</li><li>Verbal medium, written medium, signs &amp; symbols</li></ul>\n        </div>\n        <div class=\"grid-item\">\n          <h4>Receiver</h4>\n          <ul><li>The person who grasps the message</li><li>Can be a reader, listener, or viewer</li></ul>\n        </div>\n        <div class=\"grid-item\">\n          <h4>Response</h4>\n          <ul><li>The way the receiver acts on what they heard or read</li></ul>\n        </div>\n        <div class=\"grid-item\">\n          <h4>Feedback</h4>\n          <ul><li>Response from receiver to sender confirming receipt and understanding</li></ul>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-effective\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(16,185,129,0.2),rgba(168,85,247,0.2));\">✓</span> Effective Communication</h2>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('eff-chars')\">▼ Characteristics</button>\n      <div id=\"eff-chars\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Correctness</li>\n          <li>Brevity</li>\n          <li>Completeness</li>\n          <li>Clarity</li>\n          <li>Politeness</li>\n          <li>Certainty</li>\n          <li>Consideration</li>\n          <li>Cost</li>\n          <li>Speed</li>\n        </ul>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('msg-considerations')\">▼ Key Considerations for Preparing a Message</button>\n      <div id=\"msg-considerations\" style=\"display:none;\">\n        <ul class=\"list\">\n          <li>The nature of the message</li>\n          <li>Completeness</li>\n          <li>Correctness</li>\n          <li>Politeness</li>\n          <li>The ability of being understood by the receiver</li>\n          <li>Brevity</li>\n          <li>Certainty</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-media\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(245,158,11,0.2),rgba(236,72,153,0.2));\">♿</span> Communication Media</h2>\n      <div class=\"def-box\">Communication media are categorized as: <strong>Oral media</strong>, <strong>Written media</strong>, and <strong>Signs &amp; Symbols media</strong>.</div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('internal-external')\">▼ Internal &amp; External Communication</button>\n      <div id=\"internal-external\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\">\n            <h4>Internal Communication</h4>\n            <ul><li>Among managers &amp; owners</li><li>Among employees</li><li>Among departments</li></ul>\n          </div>\n          <div class=\"grid-item\">\n            <h4>External Communication</h4>\n            <ul><li>With customers</li><li>With other businesses &amp; suppliers</li></ul>\n          </div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-electronic\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(6,182,212,0.2),rgba(168,85,247,0.2));\">⚡</span> Electronic Communication</h2>\n      <div class=\"def-box\">Communication generated with the development of information and communication technology.</div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('electronic-types')\">▼ Modern Methods</button>\n      <div id=\"electronic-types\" style=\"display:none;\">\n        <table class=\"comparison-table\">\n          <tbody><tr><th>Method</th><th>Description</th></tr>\n          <tr><td><strong>Internet</strong></td><td>Computer network covering a wide range; network of networks; information obtained through a PC</td></tr>\n          <tr><td><strong>E-mail</strong></td><td>Exchange of messages through internet from computer to computer; both need internet and email addresses</td></tr>\n          <tr><td><strong>Intranet</strong></td><td>Institutional network based on internet; data within the institute; authorized persons only</td></tr>\n          <tr><td><strong>Voice Mail</strong></td><td>Verbal message over phone stored/recorded on a disk to retrieve later</td></tr>\n          <tr><td><strong>Fax</strong></td><td>Transmits letters and documents with pictures instantly through ordinary telephone system</td></tr>\n          <tr><td><strong>Mobile Phones</strong></td><td>Used for various business activities through satellite technology</td></tr>\n          <tr><td><strong>Intercom</strong></td><td>Private telephone network within the organization</td></tr>\n        </tbody></table>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-barriers\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(239,68,68,0.2),rgba(168,85,247,0.2));\">⛔</span> Barriers &amp; Strategies</h2>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('barriers-list')\">▼ Barriers to Effective Communication</button>\n      <div id=\"barriers-list\" style=\"display:none;\">\n        <ul class=\"list\">\n          <li>Poor knowledge about modern technical methods</li>\n          <li>External barriers in communication equipment</li>\n          <li>Outdated communication systems</li>\n          <li>Barriers in the communication process</li>\n          <li>Weaknesses in communication plans</li>\n          <li>Language problems, knowledge and attitudes</li>\n          <li>Barriers in the external environment</li>\n        </ul>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('strategies-list')\">▼ Strategies to Overcome</button>\n      <div id=\"strategies-list\" style=\"display:none;\">\n        <ul class=\"features\">\n          <li>Use of modern communication equipment</li>\n          <li>Imposing rules and regulations regarding communication</li>\n          <li>Setting up communication towers</li>\n          <li>Use of digital technology</li>\n          <li>Compilation of new rules on misuse of communication methods</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"section\" id=\"sec-proscons\">\n    <div class=\"card\">\n      <h2><span class=\"icon\" style=\"background:linear-gradient(135deg,rgba(16,185,129,0.2),rgba(239,68,68,0.2));\">☰</span> Advantages &amp; Disadvantages</h2>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('oral-proscons')\">▼ Verbal Communication</button>\n      <div id=\"oral-proscons\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\"><h4>Advantages</h4><ul><li>Present problems in greater detail</li><li>Provider and receiver become much closer</li><li>Fast and confidential information</li></ul></div>\n          <div class=\"grid-item\"><h4>Disadvantages</h4><ul><li>Language problems</li><li>Problems with verbally weak parties</li><li>No proof of communication</li></ul></div>\n        </div>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('written-proscons')\">▼ Written Communication</button>\n      <div id=\"written-proscons\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\"><h4>Advantages</h4><ul><li>Information in greater detail</li><li>Can be used as proof</li><li>Transmit data, notes, tables, graphs easily</li></ul></div>\n          <div class=\"grid-item\"><h4>Disadvantages</h4><ul><li>Difficulties in understanding</li><li>Reading difficulties hinder transmission</li><li>Information may distort in transmission</li></ul></div>\n        </div>\n      </div>\n      <button class=\"toggle-btn\" onclick=\"toggleSection('signs-proscons')\">▼ Signs &amp; Symbols Communication</button>\n      <div id=\"signs-proscons\" style=\"display:none;\">\n        <div class=\"grid-2\">\n          <div class=\"grid-item\"><h4>Advantages</h4><ul><li>Brief and clear information</li><li>Higher accuracy</li><li>Easy to understand</li></ul></div>\n          <div class=\"grid-item\"><h4>Disadvantages</h4><ul><li>Sight impairment problems</li><li>Distortion over time causes miscommunication</li><li>Some signs/symbols hard to understand</li><li>Prior knowledge required</li></ul></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <footer>\n    <p>Business Studies — Lesson 8 • Communication • Based on original lesson notes</p>\n  </footer>\n</div>\n<script>\n  const canvas = document.getElementById('particles-canvas');\n  const ctx = canvas.getContext('2d');\n  let particles=[];let mouseX=-1000,mouseY=-1000;\n  function resize(){canvas.width=window.innerWidth;canvas.height=window.innerHeight;}\n  resize();window.addEventListener('resize',resize);\n  class Particle{constructor(){this.reset();}reset(){this.x=Math.random()*canvas.width;this.y=Math.random()*canvas.height;this.size=Math.random()*2+0.5;this.speedX=(Math.random()-0.5)*0.3;this.speedY=(Math.random()-0.5)*0.3;this.opacity=Math.random()*0.5+0.1;}update(){this.x+=this.speedX;this.y+=this.speedY;if(this.x<0||this.x>canvas.width)this.speedX*=-1;if(this.y<0||this.y>canvas.height)this.speedY*=-1;const dx=this.x-mouseX,dy=this.y-mouseY,dist=Math.sqrt(dx*dx+dy*dy);if(dist<120){const force=(120-dist)/120;this.x+=dx*force*0.008;this.y+=dy*force*0.008;}}draw(){ctx.beginPath();ctx.arc(this.x,this.y,this.size,0,Math.PI*2);ctx.fillStyle=`rgba(196,181,253,${this.opacity})`;ctx.fill();}}\n  for(let i=0;i<120;i++)particles.push(new Particle());\n  function animateParticles(){ctx.clearRect(0,0,canvas.width,canvas.height);particles.forEach(p=>{p.update();p.draw();});for(let i=0;i<particles.length;i++){for(let j=i+1;j<particles.length;j++){const dx=particles[i].x-particles[j].x,dy=particles[i].y-particles[j].y,dist=Math.sqrt(dx*dx+dy*dy);if(dist<140){ctx.beginPath();ctx.moveTo(particles[i].x,particles[i].y);ctx.lineTo(particles[j].x,particles[j].y);ctx.strokeStyle=`rgba(196,181,253,${0.06*(1-dist/140)})`;ctx.lineWidth=0.5;ctx.stroke();}}}requestAnimationFrame(animateParticles);}\n  animateParticles();\n  document.addEventListener('mousemove',e=>{mouseX=e.clientX;mouseY=e.clientY;});\n  window.addEventListener('scroll',()=>{const s=document.documentElement.scrollTop,h=document.documentElement.scrollHeight-document.documentElement.clientHeight;document.getElementById('progress-bar').style.width=(s/h*100)+'%';});\n  const observer=new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible');});},{threshold:0.1});\n  document.querySelectorAll('.section').forEach(s=>observer.observe(s));\n  function toggleSection(id){const el=document.getElementById(id);if(el.style.display==='none'){el.style.display='block';el.style.animation='fadeUp 0.4s ease forwards';}else{el.style.display='none';}}\n</script>\n\n\n\n</body>\n</html>"
  },
  "ict": {
    "1": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n<div class=\"progress-container\"><div class=\"progress-bar\" id=\"progressBar\"></div></div>\n\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">ICT · Lesson 1</div>\n  <h1>Introduction to<br>Python Programming</h1>\n  <p>Learn the fundamentals of Python — variables, data types, input/output, and your first programs.</p>\n</section>\n\n<div class=\"container\">\n  \n\n  <div class=\"section\" data-section=\"\">\n    <h2>What is Python? <span class=\"underline\"></span></h2>\n    <p>Python is a high-level, interpreted programming language created by <strong>Guido van Rossum</strong> and first released in 1991. It emphasizes code readability and simplicity, making it one of the best languages for beginners.</p>\n    <div class=\"info-card\">\n      <div class=\"label\">Python Philosophy</div>\n      <div class=\"desc\">\"Simple is better than complex.\" — The Zen of Python</div>\n    </div>\n    <h3>Key Features</h3>\n    <ul>\n      <li><strong>Readable:</strong> Clean syntax that reads like English</li>\n      <li><strong>Interpreted:</strong> Run code line by line, no compilation needed</li>\n      <li><strong>Dynamically typed:</strong> No need to declare variable types</li>\n      <li><strong>Cross-platform:</strong> Works on Windows, macOS, Linux</li>\n    </ul>\n  </div>\n\n  <div class=\"section\" data-section=\"\">\n    <h2>Your First Program <span class=\"underline\"></span></h2>\n    <p>The classic first program in any language prints \"Hello, World!\" to the screen. In Python, this is just one line:</p>\n    <pre class=\"code-block\">print(\"Hello, World!\")</pre>\n    <p>The <code>print()</code> function outputs text to the console. Anything inside the parentheses and quotes is printed as-is.</p>\n  </div>\n\n  <div class=\"section\" data-section=\"\">\n    <h2>Variables &amp; Data Types <span class=\"underline\"></span></h2>\n    <p>Variables store data in memory. Python is dynamically typed, so you don't need to specify the type:</p>\n    <pre class=\"code-block\">name = \"Alice\"      # String (text)\nage = 17            # Integer (whole number)\nheight = 1.65       # Float (decimal)\nis_student = True   # Boolean (True/False)</pre>\n    <div class=\"info-card\">\n      <div class=\"label\">Dynamic Typing</div>\n      <div class=\"desc\">Variables change type freely: <code>x = 5</code> then <code>x = \"hello\"</code> — both valid in Python.</div>\n    </div>\n  </div>\n\n  <div class=\"section\" data-section=\"\">\n    <h2>Taking User Input <span class=\"underline\"></span></h2>\n    <p>Use <code>input()</code> to get data from the user. It always returns a <strong>string</strong>, so convert to numbers when needed:</p>\n    <pre class=\"code-block\">name = input(\"Enter your name: \")\nage = int(input(\"Enter your age: \"))\nprint(\"Hello\", name, \"you are\", age, \"years old.\")</pre>\n  </div>\n\n  <div class=\"section\" data-section=\"\">\n    <h2>Try It Yourself <span class=\"underline\"></span></h2>\n    <p>Use the NEXO Terminal below to write and run Python code directly in your browser.</p>\n  </div>\n</div>\n\n<script>\n  window.NEXO_TERMINAL_CONFIG = {\n    lang: 'python',\n    lesson: {\n      title: 'Print, Variables & Input',\n      challenge: 'Write a Python program that:\\n1. Creates a variable called \"name\" with your name\\n2. Creates a variable called \"age\" with your age (as a number)\\n3. Prints \"Hello, [name]!\" on one line\\n4. Prints \"You are [age] years old.\" on the next line\\n\\nThen modify it to ask the user for their name and age using input().',\n      expectedOutput: 'Hello, Alice!\\nYou are 17 years old.',\n      hint: 'Use print() for output. Use input() to get user input. Remember input() returns a string — use int() to convert age to a number.',\n      starterCode: { python: '', pseudocode: '', javascript: '' }\n    }\n  };\n</script>\n\n\n<div id=\"nexo-terminal-mount\"></div>\n\n\n<script>\n  const sections = document.querySelectorAll('[data-section]');\n  function revealSections() { sections.forEach(s => { if (s.getBoundingClientRect().top < window.innerHeight - 80) s.classList.add('visible'); }); }\n  window.addEventListener('scroll', revealSections); revealSections();\n  window.addEventListener('scroll', () => { const p = window.scrollY / (document.documentElement.scrollHeight - window.innerHeight) * 100; document.getElementById('progressBar').style.width = p + '%'; });\n</script>\n\n\n\n\n</body>\n</html>",
    "2": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n<div class=\"progress-container\"><div class=\"progress-bar\" id=\"progressBar\"></div></div>\n\n<section class=\"hero\">\n  <div class=\"hero-badge\">ICT · Lesson 2</div>\n  <h1>Control Flow:<br>Conditionals &amp; Loops</h1>\n  <p>Make decisions in your code with if/else and repeat actions with for/while loops.</p>\n</section>\n<div class=\"container\">\n  \n\n  <div class=\"section\" data-section=\"\">\n    <h2>If / Elif / Else <span class=\"underline\"></span></h2>\n    <p>Conditionals let your program make decisions based on conditions:</p>\n    <pre class=\"code-block\">age = int(input(\"Enter your age: \"))\n\nif age &gt;= 18:\n    print(\"You are an adult.\")\nelif age &gt;= 13:\n    print(\"You are a teenager.\")\nelse:\n    print(\"You are a child.\")</pre>\n    <p>Key rules:\n    </p><ul>\n      <li>The <code>if</code> condition is checked first</li>\n      <li><code>elif</code> checks additional conditions (any number)</li>\n      <li><code>else</code> runs if nothing above was True</li>\n      <li>Indentation (4 spaces) is mandatory in Python</li>\n    </ul>\n  </div>\n\n  <div class=\"section\" data-section=\"\">\n    <h2>Comparison Operators <span class=\"underline\"></span></h2>\n    <pre class=\"code-block\">==    Equal to\n!=    Not equal to\n&lt;     Less than\n&gt;     Greater than\n&lt;=    Less than or equal\n&gt;=    Greater than or equal</pre>\n    <p>Combine conditions with <code>and</code>, <code>or</code>, <code>not</code>:</p>\n    <pre class=\"code-block\">if age &gt;= 13 and age &lt;= 19:\n    print(\"Teenager\")\n\nif not is_raining:\n    print(\"Let's go outside!\")</pre>\n  </div>\n\n  <div class=\"section\" data-section=\"\">\n    <h2>For Loops <span class=\"underline\"></span></h2>\n    <p>For loops iterate over a sequence. Use <code>range()</code> to repeat a number of times:</p>\n    <pre class=\"code-block\"># Print numbers 1 to 5\nfor i in range(1, 6):\n    print(i)\n\n# Iterate over a list\nfruits = [\"apple\", \"banana\", \"cherry\"]\nfor fruit in fruits:\n    print(fruit)</pre>\n    <p><code>range(start, stop, step)</code> — note that <code>stop</code> is exclusive (not included).</p>\n  </div>\n\n  <div class=\"section\" data-section=\"\">\n    <h2>While Loops <span class=\"underline\"></span></h2>\n    <p>While loops repeat <strong>as long as</strong> a condition is True:</p>\n    <pre class=\"code-block\">count = 1\nwhile count &lt;= 5:\n    print(count)\n    count += 1   # Don't forget to update!\n\n# Password loop\npassword = \"\"\nwhile password != \"nexo123\":\n    password = input(\"Enter password: \")\nprint(\"Access granted!\")</pre>\n    <p class=\"info-card\" style=\"margin-top:0.8rem;\"><span class=\"label\">Warning!</span> <span class=\"desc\">Always ensure your loop condition will eventually become False, or you'll create an <strong>infinite loop</strong>.</span></p>\n  </div>\n\n  <div class=\"section\" data-section=\"\">\n    <h2>Try It Yourself <span class=\"underline\"></span></h2>\n    <p>Practice writing conditionals and loops in the terminal below.</p>\n  </div>\n</div>\n\n<script>\n  window.NEXO_TERMINAL_CONFIG = {\n    lang: 'python',\n    lesson: {\n      title: 'Conditionals & Loops Practice',\n      challenge: 'Write a Python program that:\\n1. Asks the user for a number\\n2. Prints \"Positive\", \"Negative\", or \"Zero\" based on the number\\n3. Then prints all numbers from 1 up to that number using a loop\\n\\nBonus: Ask for a password and keep asking until they enter \"python123\".',\n      expectedOutput: 'Enter a number: 5\\nPositive\\n1\\n2\\n3\\n4\\n5',\n      hint: 'Use if/elif/else for the sign check. Use for i in range(1, num+1) for the loop. For the bonus, use a while loop.',\n      starterCode: { python: '', pseudocode: '', javascript: '' }\n    }\n  };\n</script>\n\n\n<div id=\"nexo-terminal-mount\"></div>\n\n\n<script>\n  const sections = document.querySelectorAll('[data-section]');\n  function revealSections() { sections.forEach(s => { if(s.getBoundingClientRect().top < window.innerHeight - 80) s.classList.add('visible'); }); }\n  window.addEventListener('scroll', revealSections); revealSections();\n  window.addEventListener('scroll', () => { const p = window.scrollY / (document.documentElement.scrollHeight - window.innerHeight) * 100; document.getElementById('progressBar').style.width = p + '%'; });\n</script>\n\n\n\n</body>\n</html>"
  }
};

export const BOOK_HTML = {
  "48-laws-of-power": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n\n\n<!-- HERO -->\n\n\n<!-- STATS -->\n<section>\n  <div class=\"stats\">\n    <div class=\"stat\"><div class=\"stat-value\">48</div><div class=\"stat-label\">Laws of Power</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">3,000+</div><div class=\"stat-label\">Years of History</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">1</div><div class=\"stat-label\">Game You Can't Opt Out Of</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">∞</div><div class=\"stat-label\">Ways to Apply Them</div></div>\n  </div>\n</section>\n\n<!-- PREAMBLE -->\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The Premise</div>\n  <h2>There Is Only <span class=\"hl\">One Game</span></h2>\n  <div class=\"preamble\">\n    <p>The feeling of having no power over people and events is unbearable. No one wants less power; everyone wants more. In the world today, it is dangerous to seem too power-hungry — so we must appear fair and decent while playing a game of constant duplicity.</p>\n    <p>The world is like a giant scheming court. Those who claim to be above the game are often the most dangerous players of all, using displays of weakness and morality as clever power moves. The only way out is to play masterfully.</p>\n    <p class=\"attribution\">— Preface, <em>The 48 Laws of Power</em></p>\n  </div>\n</section>\n\n<!-- THE LAWS -->\n<section id=\"laws\">\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The 48 Laws</div>\n  <h2>Master the <span class=\"hl\">Game</span></h2>\n  <p class=\"section-desc\">Click any law to reveal its full meaning. Use the search to navigate.</p>\n\n  <div class=\"law-header\">\n    <input class=\"law-search\" id=\"lawSearch\" placeholder=\"Search laws by number or keyword...\" autocomplete=\"off\">\n    <span class=\"law-count\" id=\"lawCount\">Showing 48 / 48</span>\n  </div>\n\n  <div class=\"law-grid\" id=\"lawGrid\"></div>\n</section>\n\n<!-- RANDOM LAW GENERATOR -->\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The Oracle</div>\n  <h2>Draw a <span class=\"hl\">Law</span></h2>\n  <p class=\"section-desc\">Let chance decide which law you need to hear right now.</p>\n\n  <div class=\"random-section\" id=\"randomSection\">\n    <div class=\"r-label\">Law of Power</div>\n    <div class=\"r-law\" id=\"rLaw\">LAW 48</div>\n    <div class=\"r-title\" id=\"rTitle\">Assume Formlessness</div>\n    <div class=\"r-text\" id=\"rText\">By taking a shape, by having a visible plan, you open yourself to attack. Instead, keep yourself adaptable and on the move. Be as fluid and formless as water.</div>\n    <button class=\"btn btn-gold\" id=\"randomBtn\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> Draw Again <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></button>\n  </div>\n</section>\n\n<!-- CATEGORIES -->\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The Categories</div>\n  <h2>The Laws by <span class=\"hl\">Theme</span></h2>\n  <p class=\"section-desc\">The 48 laws grouped by their strategic purpose.</p>\n\n  <div class=\"cat-grid\">\n    <div class=\"cat-card\"><span class=\"cat-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"></path><circle cx=\"12\" cy=\"12\" r=\"3\"></circle></svg>️</span><h4>Reputation &amp; Image</h4><div class=\"cat-count\">Laws 5, 6, 14, 25, 26, 30, 34, 37, 46</div></div>\n    <div class=\"cat-card\"><span class=\"cat-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"></path><path d=\"M2 17l10 5 10-5\"></path><path d=\"M2 12l10 5 10-5\"></path></svg></span><h4>Deception &amp; Misdirection</h4><div class=\"cat-count\">Laws 3, 4, 12, 17, 21, 44, 48</div></div>\n    <div class=\"cat-card\"><span class=\"cat-icon\">⚔️</span><h4>Confrontation &amp; Victory</h4><div class=\"cat-count\">Laws 9, 15, 22, 28, 36, 39, 42, 47</div></div>\n    <div class=\"cat-card\"><span class=\"cat-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"></path><circle cx=\"9\" cy=\"7\" r=\"4\"></circle><path d=\"M22 21v-2a4 4 0 0 0-3-3.87\"></path><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"></path></svg></span><h4>Allies &amp; Opponents</h4><div class=\"cat-count\">Laws 1, 2, 7, 8, 11, 13, 19, 20, 24, 41, 43</div></div>\n    <div class=\"cat-card\"><span class=\"cat-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\"></path><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"></line></svg></span><h4>Psychology &amp; Timing</h4><div class=\"cat-count\">Laws 10, 16, 23, 29, 31, 32, 33, 35, 38, 40, 45</div></div>\n  </div>\n</section>\n\n<!-- KEY QUOTE -->\n<div class=\"quote-block\">\n  <div class=\"ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <blockquote>\"Any man who tries to be good all the time is bound to come to ruin among the great number who are not good.\"</blockquote>\n  <cite>— Niccolò Machiavelli, quoted in the Preface</cite>\n</div>\n\n<!-- HOW TO READ THIS BOOK -->\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">Approach</div>\n  <h2>How to Read <span class=\"hl\">This Book</span></h2>\n  <p class=\"section-desc\">Greene's work is descriptive, not necessarily prescriptive. A reader's guide.</p>\n\n  <div class=\"timeline\" id=\"timeline\">\n    <div class=\"tl-item\"><h4>Read Critically</h4><p>Understand the mechanics Greene describes without treating them as a personal playbook. Power is amoral — your ethics are your own.</p></div>\n    <div class=\"tl-item\"><h4>Look for Patterns</h4><p>The same strategic patterns recur across centuries. Notice how different historical figures applied (or violated) the same law.</p></div>\n    <div class=\"tl-item\"><h4>Beware the \"Nonplayer\"</h4><p>Those who claim to be above power games are often the most skilled players. Naivety and moral posturing can be sophisticated strategies.</p></div>\n    <div class=\"tl-item\"><h4>Know When to Break a Law</h4><p>Some laws contradict others. Greene acknowledges that context matters — knowing <em>when</em> to apply a law is as important as knowing the law itself.</p></div>\n    <div class=\"tl-item\"><h4>Don't Take It Personally</h4><p>The book is about power dynamics, not personal morality. It reveals how the world works, not necessarily how it should work.</p></div>\n  </div>\n</section>\n\n\n\n<script>\n  //  ALL 48 LAWS \n  const laws = [\n    {n:1, title:\"Never Outshine the Master\", text:\"Make those above you feel comfortably superior. Do not go too far in displaying your talents or you might inspire fear and insecurity. Make your masters appear more brilliant than they are and you will attain the heights of power.\"},\n    {n:2, title:\"Never Put Too Much Trust in Friends, Learn How to Use Enemies\", text:\"Be wary of friends — they will betray you more quickly, for they are easily aroused to envy. Hire a former enemy and he will be more loyal than a friend, because he has more to prove. You have more to fear from friends than from enemies.\"},\n    {n:3, title:\"Conceal Your Intentions\", text:\"Keep people off-balance and in the dark by never revealing the purpose behind your actions. If they have no clue what you are up to, they cannot prepare a defense. Guide them far enough down the wrong path and by the time they realize your intentions, it will be too late.\"},\n    {n:4, title:\"Always Say Less Than Necessary\", text:\"When you try to impress people with words, the more you say, the more common you appear. Powerful people impress and intimidate by saying less. The more you say, the more likely you are to say something foolish.\"},\n    {n:5, title:\"So Much Depends on Reputation — Guard It with Your Life\", text:\"Reputation is the cornerstone of power. Through reputation alone you can intimidate and win; once it slips, you are vulnerable. Make your reputation unassailable. Learn to destroy your enemies by opening holes in their own reputations.\"},\n    {n:6, title:\"Court Attention at All Cost\", text:\"Everything is judged by its appearance; what is unseen counts for nothing. Never let yourself get lost in the crowd. Stand out. Be conspicuous. Make yourself a magnet of attention by appearing larger, more colorful, more mysterious than the masses.\"},\n    {n:7, title:\"Get Others to Do the Work for You, But Always Take the Credit\", text:\"Use the wisdom, knowledge, and legwork of other people to further your own cause. Such assistance saves you time and gives you a godlike aura of efficiency. In the end your helpers will be forgotten and you will be remembered.\"},\n    {n:8, title:\"Make Other People Come to You — Use Bait If Necessary\", text:\"When you force the other person to act, you are the one in control. It is always better to make your opponent come to you, abandoning his own plans in the process. Lure him with fabulous gains — then attack.\"},\n    {n:9, title:\"Win Through Your Actions, Never Through Argument\", text:\"Any momentary triumph gained through argument is a Pyrrhic victory. The resentment and ill will you stir up is stronger than any change of opinion. It is much more powerful to get others to agree through your actions, without saying a word.\"},\n    {n:10, title:\"Infection: Avoid the Unhappy and Unlucky\", text:\"You can die from someone else's misery — emotional states are as infectious as diseases. The unfortunate sometimes draw misfortune on themselves; they will also draw it on you. Associate with the happy and fortunate instead.\"},\n    {n:11, title:\"Learn to Keep People Dependent on You\", text:\"To maintain your independence you must always be needed and wanted. The more you are relied on, the more freedom you have. Make people depend on you for their happiness and prosperity and you have nothing to fear.\"},\n    {n:12, title:\"Use Selective Honesty and Generosity to Disarm Your Victim\", text:\"One sincere and honest move will cover over dozens of dishonest ones. Open-hearted gestures of honesty and generosity bring down the guard of even the most suspicious people. A timely gift — a Trojan horse — will serve the same purpose.\"},\n    {n:13, title:\"When Asking for Help, Appeal to People's Self-Interest, Never to Their Mercy or Gratitude\", text:\"Do not remind others of your past assistance — they will ignore you. Instead, uncover something in your request that will benefit them and emphasize it. They will respond enthusiastically when they see something to be gained for themselves.\"},\n    {n:14, title:\"Pose as a Friend, Work as a Spy\", text:\"Knowing about your rival is critical. Use spies to gather valuable information. Better still: play the spy yourself. In social encounters, learn to probe. Ask indirect questions to get people to reveal their weaknesses and intentions.\"},\n    {n:15, title:\"Crush Your Enemy Totally\", text:\"All great leaders have known that a feared enemy must be crushed completely. If one ember is left alight, no matter how dimly it smolders, a fire will eventually break out. More is lost through stopping halfway than through total annihilation.\"},\n    {n:16, title:\"Use Absence to Increase Respect and Honor\", text:\"Too much circulation makes the price go down. The more you are seen, the more common you appear. If you are already established, temporary withdrawal will make you more talked about and admired. Create value through scarcity.\"},\n    {n:17, title:\"Keep Others in Suspended Terror: Cultivate an Air of Unpredictability\", text:\"Humans are creatures of habit who need familiarity. Your predictability gives others a sense of control. Be deliberately unpredictable. Behavior that seems to have no consistency will keep them off-balance, wearing them out trying to explain you.\"},\n    {n:18, title:\"Do Not Build Fortresses to Protect Yourself — Isolation Is Dangerous\", text:\"A fortress seems safest but exposes you to more dangers — it cuts you off from information, makes you conspicuous, and an easy target. Better to circulate among people, find allies, and mingle. You are shielded by the crowd.\"},\n    {n:19, title:\"Know Who You're Dealing With — Do Not Offend the Wrong Person\", text:\"There are many kinds of people. Deceive some and they will spend their lives seeking revenge — wolves in lambs' clothing. Choose your victims and opponents carefully. Never offend or deceive the wrong person.\"},\n    {n:20, title:\"Do Not Commit to Anyone\", text:\"It is the fool who always rushes to take sides. Do not commit to any side or cause but yourself. By maintaining your independence you become the master of others — playing people against one another, making them pursue you.\"},\n    {n:21, title:\"Play a Sucker to Catch a Sucker — Seem Dumber Than Your Mark\", text:\"No one likes feeling stupider than the next person. Make your victims feel smart — smarter than you. Once convinced of this, they will never suspect you may have ulterior motives.\"},\n    {n:22, title:\"Use the Surrender Tactic: Transform Weakness Into Power\", text:\"When you are weaker, never fight for honor's sake — choose surrender instead. Surrender gives you time to recover, time to torment your conqueror, time to wait for his power to wane. Make surrender a tool of power.\"},\n    {n:23, title:\"Concentrate Your Forces\", text:\"Conserve your forces by keeping them concentrated at their strongest point. Intensity defeats extensity every time. Find one rich mine and mine it deeper rather than flitting from one shallow mine to another.\"},\n    {n:24, title:\"Play the Perfect Courtier\", text:\"The perfect courtier thrives in a world of power and political dexterity. Master indirection — flatter, yield to superiors, assert power over others in the most oblique and graceful manner. There will be no limit to how far you can rise.\"},\n    {n:25, title:\"Re-Create Yourself\", text:\"Do not accept the roles society foists on you. Forge a new identity that commands attention and never bores. Be the master of your own image. Incorporate dramatic devices into your gestures and your character will seem larger than life.\"},\n    {n:26, title:\"Keep Your Hands Clean\", text:\"You must seem a paragon of civility and efficiency — your hands never soiled by mistakes or nasty deeds. Maintain a spotless appearance by using others as scapegoats and cat's-paws to disguise your involvement.\"},\n    {n:27, title:\"Play on People's Need to Believe to Create a Cult-like Following\", text:\"People have an overwhelming desire to believe in something. Become the focal point by offering a cause, a new faith. Keep words vague but full of promise. Emphasize enthusiasm over rationality. Give rituals to perform.\"},\n    {n:28, title:\"Enter Action with Boldness\", text:\"If you are unsure of a course of action, do not attempt it — your doubts will infect execution. Timidity is dangerous. Any mistakes you commit through audacity are easily corrected with more audacity. Everyone admires the bold.\"},\n    {n:29, title:\"Plan All the Way to the End\", text:\"The ending is everything. Plan all the way to it, taking into account all consequences, obstacles, and twists of fortune. By planning to the end you will not be overwhelmed by circumstances and you will know when to stop.\"},\n    {n:30, title:\"Make Your Accomplishments Seem Effortless\", text:\"Your actions must seem natural and executed with ease. Conceal all toil and practice. Avoid the temptation of revealing how hard you work — it only raises questions. Teach no one your tricks or they will be used against you.\"},\n    {n:31, title:\"Control the Options: Get Others to Play with the Cards You Deal\", text:\"The best deceptions give the other person a choice. Your victims feel in control but are puppets. Give options that serve your purpose whichever they choose. Put them on the horns of a dilemma.\"},\n    {n:32, title:\"Play to People's Fantasies\", text:\"Truth is often avoided because it is ugly. Never appeal to truth unless prepared for the anger of disenchantment. People who manufacture romance or fantasy are like oases in the desert. Great power lies in tapping into the fantasies of the masses.\"},\n    {n:33, title:\"Discover Each Man's Thumbscrew\", text:\"Everyone has a weakness — a gap in the castle wall. Usually an insecurity, an uncontrollable emotion or need, or a secret pleasure. Once found, it is a thumbscrew you can turn to your advantage.\"},\n    {n:34, title:\"Be Royal in Your Own Fashion: Act Like a King to Be Treated Like One\", text:\"The way you carry yourself determines how you are treated. A king respects himself and inspires the same in others. By acting regally and confident in your powers, you make yourself seem destined to wear a crown.\"},\n    {n:35, title:\"Master the Art of Timing\", text:\"Never seem to be in a hurry — it betrays a lack of control. Always seem patient, as if you know everything will come to you eventually. Become a detective of the right moment. Strike fiercely when the time is ripe.\"},\n    {n:36, title:\"Disdain Things You Cannot Have: Ignoring Them Is the Best Revenge\", text:\"By acknowledging a petty problem you give it existence. The more attention you pay an enemy, the stronger you make him. If there is something you want but cannot have, show contempt for it. The less interest, the more superior you seem.\"},\n    {n:37, title:\"Create Compelling Spectacles\", text:\"Striking imagery and grand symbolic gestures create the aura of power. Stage spectacles full of arresting visuals and radiant symbols that heighten your presence. Dazzled by appearances, no one will notice what you are really doing.\"},\n    {n:38, title:\"Think as You Like But Behave Like Others\", text:\"If you flaunt unconventional ideas, people will think you look down on them and will find a way to punish you. Blend in and nurture the common touch. Share your originality only with tolerant, trusted friends.\"},\n    {n:39, title:\"Stir Up Waters to Catch Fish\", text:\"Anger and emotion are strategically counterproductive. Stay calm and objective. But if you can make your enemies angry while staying calm yourself, you gain a decided advantage. Find the chink in their vanity and rattle them.\"},\n    {n:40, title:\"Despise the Free Lunch\", text:\"What is offered for free is dangerous — it involves a trick or hidden obligation. What has worth is worth paying for. Pay your own way to stay clear of gratitude, guilt, and deceit. Generosity is a sign and magnet for power.\"},\n    {n:41, title:\"Avoid Stepping into a Great Man's Shoes\", text:\"What happens first always appears better. If you succeed a great figure, you must accomplish double their achievements. Establish your own name and identity by changing course. Slay the overbearing father and shine in your own way.\"},\n    {n:42, title:\"Strike the Shepherd and the Sheep Will Scatter\", text:\"Trouble can often be traced to a single agitator. Do not wait for troubles to multiply. Neutralize their influence by isolating or banishing them. Strike at the source and the followers will scatter.\"},\n    {n:43, title:\"Work on the Hearts and Minds of Others\", text:\"Coercion creates a reaction that works against you. Seduce others into wanting to move in your direction. Operate on their psychology and weaknesses. Ignore hearts and minds and they will grow to hate you.\"},\n    {n:44, title:\"Disarm and Infuriate with the Mirror Effect\", text:\"The mirror reflects reality but is also a tool for deception. When you mirror your enemies, they cannot figure your strategy. The Mirror Effect mocks and humiliates, making them overreact. Hold up a mirror to teach them a lesson.\"},\n    {n:45, title:\"Preach the Need for Change, But Never Reform Too Much at Once\", text:\"Everyone understands change in the abstract, but people are creatures of habit. Too much innovation leads to revolt. Make change feel like a gentle improvement on the past. Respect old ways while innovating.\"},\n    {n:46, title:\"Never Appear Too Perfect\", text:\"Appearing better than others is dangerous; appearing flawless is worst of all. Envy creates silent enemies. Display occasional defects and admit harmless vices to deflect envy. Only gods and the dead can seem perfect with impunity.\"},\n    {n:47, title:\"Do Not Go Past the Mark You Aimed For; In Victory, Learn When to Stop\", text:\"The moment of victory is often the moment of greatest peril. Overconfidence can push you past your goal, creating more enemies than you defeated. Set a goal, and when you reach it, stop. Strategy, not ego.\"},\n    {n:48, title:\"Assume Formlessness\", text:\"By taking a visible shape or plan, you open yourself to attack. Keep yourself adaptable and on the move. Accept that nothing is certain and no law is fixed. Be as fluid and formless as water — never bet on stability or lasting order.\"}\n  ];\n\n  //  THEME \n  const themeToggle = document.getElementById('themeToggle');\n  themeToggle.addEventListener('click', () => {\n    document.body.classList.toggle('light');\n    themeToggle.innerHTML = document.body.classList.contains('light') ? '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>' : '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"/></svg>️';\n  });\n\n  //  RENDER LAWS \n  const grid = document.getElementById('lawGrid');\n  const search = document.getElementById('lawSearch');\n  const count = document.getElementById('lawCount');\n\n  function renderLaws(filter = '') {\n    grid.innerHTML = '';\n    const q = filter.toLowerCase();\n    let visible = 0;\n\n    laws.forEach(law => {\n      const match = !q ||\n        law.n.toString().includes(q) ||\n        law.title.toLowerCase().includes(q) ||\n        law.text.toLowerCase().includes(q);\n\n      if (match) visible++;\n\n      const card = document.createElement('div');\n      card.className = `law-card${match ? '' : ' hidden'}`;\n      card.dataset.n = law.n;\n\n      card.innerHTML = `\n        <div class=\"num\">LAW ${law.n}</div>\n        <h3>${law.title}</h3>\n        <div class=\"preview\">${law.text.substring(0, 100)}…</div>\n        <div class=\"full\"><div class=\"full-inner\">${law.text}</div></div>\n        <div class=\"expand-icon\">+</div>\n      `;\n\n      card.addEventListener('click', () => {\n        card.classList.toggle('open');\n      });\n\n      grid.appendChild(card);\n    });\n\n    count.textContent = `Showing ${visible} / ${laws.length}`;\n  }\n\n  renderLaws();\n\n  search.addEventListener('input', (e) => renderLaws(e.target.value));\n\n  //  SCROLL REVEAL \n  const observer = new IntersectionObserver((entries) => {\n    entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); });\n  }, { threshold: 0.1 });\n\n  document.querySelectorAll('.law-card, .cat-card, .tl-item').forEach(el => observer.observe(el));\n\n  //  RANDOM LAW \n  const rLaw = document.getElementById('rLaw');\n  const rTitle = document.getElementById('rTitle');\n  const rText = document.getElementById('rText');\n  const rBtn = document.getElementById('randomBtn');\n\n  rBtn.addEventListener('click', () => {\n    rText.classList.add('fade');\n    setTimeout(() => {\n      const l = laws[Math.floor(Math.random() * laws.length)];\n      rLaw.textContent = `LAW ${l.n}`;\n      rTitle.textContent = l.title;\n      rText.textContent = l.text;\n      rText.classList.remove('fade');\n    }, 300);\n  });\n</script>\n\n\n\n</body>\n</html>",
  "atomic-habits": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n\n\n<!-- HERO -->\n\n\n<!-- STATS -->\n<section>\n  <div class=\"stats\">\n    <div class=\"stat\"><div class=\"stat-value\">1%</div><div class=\"stat-label\">Daily Improvement</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">37<small>x</small></div><div class=\"stat-label\">Better in One Year</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">4</div><div class=\"stat-label\">Laws of Change</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">∞</div><div class=\"stat-label\">Compound Potential</div></div>\n  </div>\n</section>\n\n<!-- THE FOUR LAWS -->\n<section>\n  <div class=\"section-label\">The Framework</div>\n  <h2>The Four Laws of <span class=\"hl\">Behavior Change</span></h2>\n  <p class=\"section-desc\">Every habit follows a four-step feedback loop. Master these levers and you can reshape any behavior.</p>\n\n  <div class=\"stage-flow\">\n    <div class=\"stage\"><span class=\"s-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"></path><circle cx=\"12\" cy=\"12\" r=\"3\"></circle></svg>️</span><h4>Make It Obvious</h4><p>The 1st Law: Cue — Design your environment, use implementation intentions.</p></div>\n    <div class=\"stage\"><span class=\"s-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z\"></path></svg></span><h4>Make It Attractive</h4><p>The 2nd Law: Craving — Temptation bundle, join the right culture.</p></div>\n    <div class=\"stage\"><span class=\"s-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"13 2 3 14 12 14 11 22 21 10 12 10 13 2\"></polygon></svg></span><h4>Make It Easy</h4><p>The 3rd Law: Response — Two-minute rule, reduce friction, commit.</p></div>\n    <div class=\"stage\"><span class=\"s-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"></polygon></svg></span><h4>Make It Satisfying</h4><p>The 4th Law: Reward — Track habits, use immediate reinforcement.</p></div>\n  </div>\n\n  <div class=\"grid grid-4\" style=\"margin-top:1.5rem;\">\n    <div class=\"law-card\">\n      <div class=\"l-num\">Law 1</div>\n      <h3>Make It Obvious</h3>\n      <p>Implementation intentions, habit stacking, environment design.</p>\n      <div class=\"invert\">To break: <strong>Make It Invisible</strong> — reduce exposure to cues.</div>\n    </div>\n    <div class=\"law-card\">\n      <div class=\"l-num\">Law 2</div>\n      <h3>Make It Attractive</h3>\n      <p>Temptation bundling, join a culture, create rituals.</p>\n      <div class=\"invert\">To break: <strong>Make It Unattractive</strong> — reframe your mindset.</div>\n    </div>\n    <div class=\"law-card\">\n      <div class=\"l-num\">Law 3</div>\n      <h3>Make It Easy</h3>\n      <p>Two-minute rule, reduce friction, automate decisions.</p>\n      <div class=\"invert\">To break: <strong>Make It Difficult</strong> — increase friction, use commitment devices.</div>\n    </div>\n    <div class=\"law-card\">\n      <div class=\"l-num\">Law 4</div>\n      <h3>Make It Satisfying</h3>\n      <p>Habit tracking, immediate rewards, never miss twice.</p>\n      <div class=\"invert\">To break: <strong>Make It Unsatisfying</strong> — add immediate cost or accountability.</div>\n    </div>\n  </div>\n</section>\n\n<!-- INTERACTIVE HABIT TRACKER -->\n<section>\n  <div class=\"section-label\">Try It</div>\n  <h2>Habit <span class=\"hl\">Tracker</span></h2>\n  <p class=\"section-desc\">Click the days you've stuck to a habit. Watch your streak grow — visual progress is satisfying.</p>\n\n  <div class=\"tracker\" id=\"tracker\">\n    <div style=\"font-weight:700; margin-bottom:0.5rem;\" id=\"trackerTitle\">Track a Habit</div>\n    <div class=\"tracker-grid\" id=\"trackerGrid\"></div>\n    <div class=\"tracker-streak\">Streak: <strong id=\"streakCount\">0</strong> days</div>\n    <button class=\"btn btn-outline\" id=\"resetTracker\" style=\"margin-top:1rem;\">↺ Reset</button>\n  </div>\n</section>\n\n<!-- KEY CONCEPTS -->\n<section>\n  <div class=\"section-label\">Key Concepts</div>\n  <h2>The <span class=\"hl\">Big Ideas</span></h2>\n  <p class=\"section-desc\">The most powerful concepts from the book, each with practical application.</p>\n\n  <div class=\"grid grid-2\">\n    <div class=\"card\">\n      <div class=\"num\">1</div>\n      <h3>Identity-Based Habits</h3>\n      <p>Outcome-based: \"I want to lose weight.\" Identity-based: \"I am the kind of person who moves every day.\" Every action is a vote for the person you wish to become. True change is identity change.</p>\n    </div>\n    <div class=\"card\">\n      <div class=\"num\">2</div>\n      <h3>The Habit Loop</h3>\n      <p>Cue → Craving → Response → Reward. Every habit follows this cycle. Master each stage and you can design any behavior. The Four Laws are your levers on this loop.</p>\n    </div>\n    <div class=\"card\">\n      <div class=\"num\">3</div>\n      <h3>Motion vs. Action</h3>\n      <p>Motion = planning, strategizing, learning. Action = producing results. We use motion to delay failure. The best approach? Stop preparing and start doing. Repetition, not perfection.</p>\n    </div>\n    <div class=\"card\">\n      <div class=\"num\">4</div>\n      <h3>The Two-Minute Rule</h3>\n      <p>A new habit should take less than two minutes. \"Read before bed\" becomes \"Read one page.\" \"Run 5K\" becomes \"Tie your shoes.\" Standardize before you optimize. Master the first two minutes.</p>\n    </div>\n    <div class=\"card\">\n      <div class=\"num\">5</div>\n      <h3>Never Miss Twice</h3>\n      <p>Missing once is an accident. Missing twice is the start of a new bad habit. The rule: get back on track immediately. Perfection is impossible; consistency is everything.</p>\n    </div>\n    <div class=\"card\">\n      <div class=\"num\">6</div>\n      <h3>Environment Design</h3>\n      <p>Willpower is a short-term strategy. Design your environment so good habits are obvious and bad habits are impossible. Put the fruit on the counter, the guitar by the couch, the phone in another room.</p>\n    </div>\n    <div class=\"card\">\n      <div class=\"num\">7</div>\n      <h3>Goldilocks Rule</h3>\n      <p>Peak motivation occurs at the edge of your ability — not too hard, not too easy. Boredom is the greatest threat to success. Professionals stick to the schedule even when it's not exciting.</p>\n    </div>\n    <div class=\"card\">\n      <div class=\"num\">8</div>\n      <h3>Habit Stacking</h3>\n      <p>\"After [CURRENT HABIT], I will [NEW HABIT].\" Stack new behaviors onto existing routines. Your morning coffee becomes the cue for 2 minutes of meditation. Your commute becomes your audiobook time.</p>\n    </div>\n  </div>\n</section>\n\n<!-- IDENTITY FLOW -->\n<section>\n  <div class=\"section-label\">Identity</div>\n  <h2>How Habits Shape <span class=\"hl\">Who You Are</span></h2>\n  <p class=\"section-desc\">The most powerful shift: from achieving outcomes to becoming the person who deserves them.</p>\n\n  <div class=\"identity-flow\">\n    <div class=\"id-step\"><div class=\"lbl\">Start with</div><div class=\"val\">Who you want to be</div></div>\n    <div class=\"arrow\">→</div>\n    <div class=\"id-step\"><div class=\"lbl\">Take</div><div class=\"val\">Small actions that confirm it</div></div>\n    <div class=\"arrow\">→</div>\n    <div class=\"id-step\"><div class=\"lbl\">Vote for</div><div class=\"val\">Your new identity</div></div>\n    <div class=\"arrow\">→</div>\n    <div class=\"id-step\"><div class=\"lbl\">It becomes</div><div class=\"val\">Who you actually are</div></div>\n  </div>\n\n  <div class=\"quote-block\">\n    <blockquote>\"Every action you take is a vote for the type of person you wish to become. No single instance will transform your beliefs, but as the votes build up, so does the evidence of your new identity.\"</blockquote>\n    <cite>— James Clear, Atomic Habits</cite>\n  </div>\n</section>\n\n<!-- PRACTICAL TACTICS -->\n<section>\n  <div class=\"section-label\">Tactics</div>\n  <h2>Put It Into <span class=\"hl\">Practice</span></h2>\n  <p class=\"section-desc\">Actionable strategies you can start using today.</p>\n\n  <ul class=\"tip-list\" id=\"tipList\">\n    <li><span class=\"check\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></span><div><strong>Implementation Intentions</strong><span>State exactly when and where you'll act: \"I will exercise at 7 AM in my living room.\" Specificity makes the cue obvious.</span></div></li>\n    <li><span class=\"check\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></span><div><strong>Temptation Bundling</strong><span>Pair something you want to do with something you need to do: listen to your favorite podcast only while at the gym.</span></div></li>\n    <li><span class=\"check\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></span><div><strong>Reduce Friction</strong><span>Make good habits effortless. Lay out workout clothes the night before. Pre-pack your lunch. The less friction, the more likely you'll act.</span></div></li>\n    <li><span class=\"check\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></span><div><strong>Commitment Devices</strong><span>Lock in good behavior ahead of time. Buy a timed outlet for your router. Leave your wallet at home. Pre-pay for gym sessions.</span></div></li>\n    <li><span class=\"check\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></span><div><strong>Habit Tracking</strong><span>Use a calendar. Mark an X each day you follow through. Don't break the chain. Visual progress is inherently satisfying and motivating.</span></div></li>\n    <li><span class=\"check\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></span><div><strong>Reflection &amp; Review</strong><span>Schedule annual, monthly, and daily reviews. Measure what matters. Without reflection, habits stagnate. Make small adjustments to keep improving.</span></div></li>\n  </ul>\n</section>\n\n<!-- MASTERY -->\n<section>\n  <div class=\"section-label\">Mastery</div>\n  <h2>Beyond Habits: <span class=\"hl\">Deliberate Practice</span></h2>\n  <p class=\"section-desc\">Habits are necessary but not sufficient. Mastery requires combining automatic habits with deliberate practice.</p>\n\n  <div class=\"grid grid-3\">\n    <div class=\"card\">\n      <h3>Habit + Deliberate Practice</h3>\n      <p>Habits provide the foundation. Deliberate practice pushes the boundary. Each habit unlocks the next level of performance. It's an endless cycle.</p>\n    </div>\n    <div class=\"card\">\n      <h3>Fall in Love with Boredom</h3>\n      <p>The greatest threat to success is not failure — it's boredom. Professionals show up even when it's not exciting. Amateurs wait for motivation.</p>\n    </div>\n    <div class=\"card\">\n      <h3>Plateau of Latent Potential</h3>\n      <p>Results lag behind effort. You work for weeks with no visible progress, then breakthrough. The ice doesn't melt at 31° — it melts at 32°. Keep going.</p>\n    </div>\n  </div>\n</section>\n\n\n\n<script>\n  //  THEME \n  const themeToggle = document.getElementById('themeToggle');\n  themeToggle.addEventListener('click', () => {\n    document.body.classList.toggle('dark');\n    themeToggle.innerHTML = document.body.classList.contains('dark') ? '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"/></svg>️' : '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>';\n  });\n\n  //  SCROLL REVEAL \n  const observer = new IntersectionObserver((entries) => {\n    entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); });\n  }, { threshold: 0.1 });\n\n  document.querySelectorAll('.card, .law-card, .stage, .tip-list li').forEach(el => observer.observe(el));\n\n  //  HABIT TRACKER \n  const grid = document.getElementById('trackerGrid');\n  const streakEl = document.getElementById('streakCount');\n  const resetBtn = document.getElementById('resetTracker');\n\n  let days = JSON.parse(localStorage.getItem('atomicTracker') || '{}');\n  let startDate = new Date();\n  startDate.setDate(startDate.getDate() - 27);\n\n  function renderTracker() {\n    grid.innerHTML = '';\n    let streak = 0;\n    let currentStreak = 0;\n    const today = new Date().toDateString();\n\n    for (let i = 0; i < 28; i++) {\n      const d = new Date(startDate);\n      d.setDate(d.getDate() + i);\n      const key = d.toDateString();\n      const isToday = key === today;\n      const done = days[key] || false;\n\n      const el = document.createElement('div');\n      el.className = 'tracker-day' + (done ? ' done' : '') + (isToday ? ' today' : '');\n      el.textContent = d.getDate();\n\n      if (isToday || d < new Date()) {\n        el.addEventListener('click', () => {\n          days[key] = !days[key];\n          localStorage.setItem('atomicTracker', JSON.stringify(days));\n          renderTracker();\n        });\n      }\n\n      grid.appendChild(el);\n\n      if (done) {\n        currentStreak++;\n        if (currentStreak > streak) streak = currentStreak;\n      } else {\n        if (!isToday) currentStreak = 0;\n      }\n    }\n\n    // calculate actual streak from today backwards\n    let realStreak = 0;\n    for (let i = 27; i >= 0; i--) {\n      const d = new Date(startDate);\n      d.setDate(d.getDate() + i);\n      const key = d.toDateString();\n      if (days[key]) realStreak++;\n      else if (d.toDateString() !== today) break;\n    }\n    streakEl.textContent = realStreak;\n  }\n\n  resetBtn.addEventListener('click', () => {\n    if (confirm('Reset your habit tracker?')) {\n      days = {};\n      localStorage.removeItem('atomicTracker');\n      renderTracker();\n    }\n  });\n\n  renderTracker();\n</script>\n\n\n\n</body>\n</html>",
  "book-of-wisdom": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div id=\"progress\"></div>\n<canvas id=\"bgCanvas\"></canvas>\n<div id=\"orbs\"></div>\n<div id=\"noise\"></div>\n\n\n\n<!--  HERO  -->\n\n\n<!--  CORE WISDOM PRINCIPLES  -->\n<div class=\"container\">\n  <div class=\"section-header reveal\">\n    <div class=\"label\">Core Principles</div>\n    <h2>The <span class=\"hl\">Eight Pillars</span> of Wisdom</h2>\n    <p>Foundational truths that have guided humanity across cultures and centuries — rediscovered for our time.</p>\n    <div class=\"line\"></div>\n  </div>\n\n  <div class=\"wisdom-grid\">\n    <div class=\"wisdom-card reveal\" onclick=\"toggleWisdom(this)\">\n      <span class=\"w-icon\">💡</span>\n      <span class=\"w-num\">01</span>\n      <h3>The Light of Self-Knowledge</h3>\n      <p class=\"teaser\">Know thyself — the foundation of all wisdom begins with honest self-examination.</p>\n      <div class=\"w-body\">\n        <p>Ancient Greek philosophers proclaimed \"Gnothi seauton\" (Know thyself) as the highest form of wisdom. Before you can understand the world, you must first understand the one who perceives it.</p>\n        <p>Self-knowledge is not mere introspection but courageous confrontation with your own nature — your strengths, shadows, desires, and fears. The unexamined life is not worth living, for it is lived on the terms of others.</p>\n      </div>\n      <span class=\"w-toggle\">Expand</span>\n    </div>\n\n    <div class=\"wisdom-card reveal reveal-delay-1\" onclick=\"toggleWisdom(this)\">\n      <span class=\"w-icon\">⚖️</span>\n      <span class=\"w-num\">02</span>\n      <h3>The Balance of Opposites</h3>\n      <p class=\"teaser\">Harmony emerges not from eliminating conflict but from holding tension creatively.</p>\n      <div class=\"w-body\">\n        <p>The Taoist symbol of yin and yang teaches that all reality consists of complementary opposites. Light needs darkness, joy needs sorrow, action needs rest. Wisdom is not choosing one side but dancing between them.</p>\n        <p>When you stop resisting the natural rhythm of life — its ebbs and flows, its gains and losses — you discover a deeper peace that transcends circumstances.</p>\n      </div>\n      <span class=\"w-toggle\">Expand</span>\n    </div>\n\n    <div class=\"wisdom-card reveal reveal-delay-2\" onclick=\"toggleWisdom(this)\">\n      <span class=\"w-icon\">🌱</span>\n      <span class=\"w-num\">03</span>\n      <h3>The Power of Presence</h3>\n      <p class=\"teaser\">The past is memory, the future is imagination — only now is real.</p>\n      <div class=\"w-body\">\n        <p>Ancient wisdom traditions from Buddhism to Stoicism converge on one truth: suffering arises from being absent from the present moment. Regret pulls us backward, anxiety pulls us forward, and both steal the only life we have.</p>\n        <p>To be fully present is to be fully alive. The master key to wisdom is learning to anchor your awareness in the here and now, where life actually happens.</p>\n      </div>\n      <span class=\"w-toggle\">Expand</span>\n    </div>\n\n    <div class=\"wisdom-card reveal\" onclick=\"toggleWisdom(this)\">\n      <span class=\"w-icon\">💬</span>\n      <span class=\"w-num\">04</span>\n      <h3>The Discipline of Silence</h3>\n      <p class=\"teaser\">In silence, the noise of the world settles and truth rises to the surface.</p>\n      <div class=\"w-body\">\n        <p>Solomon wrote that there is \"a time to keep silence and a time to speak.\" Ancient sages across every tradition valued silence not as emptiness but as fertile ground for insight. Words are but the froth on the deep waters of wisdom.</p>\n        <p>Regular practice of silence — whether through meditation, contemplation, or simply sitting in nature — restores clarity and connects you to sources of knowing beyond the rational mind.</p>\n      </div>\n      <span class=\"w-toggle\">Expand</span>\n    </div>\n\n    <div class=\"wisdom-card reveal reveal-delay-1\" onclick=\"toggleWisdom(this)\">\n      <span class=\"w-icon\">💪</span>\n      <span class=\"w-num\">05</span>\n      <h3>The Virtue of Discipline</h3>\n      <p class=\"teaser\">Freedom is not doing whatever you want — it is choosing what is best.</p>\n      <div class=\"w-body\">\n        <p>Every wisdom tradition teaches that discipline is the bridge between aspiration and achievement. The Stoics called it areté (excellence of character), the Buddhists called it sila (moral discipline), and the Proverbs call it the path to life.</p>\n        <p>Small, consistent actions compound into extraordinary results. The disciplined person is not rigid but free — free from the tyranny of impulse, free to pursue what truly matters.</p>\n      </div>\n      <span class=\"w-toggle\">Expand</span>\n    </div>\n\n    <div class=\"wisdom-card reveal reveal-delay-2\" onclick=\"toggleWisdom(this)\">\n      <span class=\"w-icon\">🌊</span>\n      <span class=\"w-num\">06</span>\n      <h3>The Flow of Impermanence</h3>\n      <p class=\"teaser\">Everything changes — your peace comes from embracing, not resisting, this truth.</p>\n      <div class=\"w-body\">\n        <p>Heraclitus observed that you cannot step into the same river twice. The Buddha named impermanence (anicca) as one of the three marks of existence. To fight against change is to fight against reality itself.</p>\n        <p>Wisdom does not cling to what must pass or fear what is to come. It rides the current of change with grace, knowing that each ending is a beginning and each loss creates space for something new.</p>\n      </div>\n      <span class=\"w-toggle\">Expand</span>\n    </div>\n\n    <div class=\"wisdom-card reveal\" onclick=\"toggleWisdom(this)\">\n      <span class=\"w-icon\">🤝</span>\n      <span class=\"w-num\">07</span>\n      <h3>The Unity of All Things</h3>\n      <p class=\"teaser\">Separation is an illusion — beneath the surface, all life is one interconnected whole.</p>\n      <div class=\"w-body\">\n        <p>From the Hindu concept of Advaita (non-duality) to the scientific revelation of quantum entanglement, wisdom reveals that our sense of separation is a useful but limited perspective. We are not isolated selves but expressions of a single, vast reality.</p>\n        <p>When you live from this understanding, compassion becomes natural. You cannot harm another without harming yourself. The boundary between self and other dissolves into the recognition of our fundamental unity.</p>\n      </div>\n      <span class=\"w-toggle\">Expand</span>\n    </div>\n\n    <div class=\"wisdom-card reveal reveal-delay-1\" onclick=\"toggleWisdom(this)\">\n      <span class=\"w-icon\">⭐</span>\n      <span class=\"w-num\">08</span>\n      <h3>The Call to Service</h3>\n      <p class=\"teaser\">The highest purpose is not to accumulate but to contribute.</p>\n      <div class=\"w-body\">\n        <p>Every wisdom tradition culminates in the call to serve something greater than oneself. The Golden Rule appears in virtually every culture: treat others as you would be treated. Wisdom that does not express itself in compassionate action is merely knowledge.</p>\n        <p>True fulfillment comes not from what you get but from what you give. In serving others, you discover your deepest purpose. The sage is not above the world but deeply in it, for the good of all.</p>\n      </div>\n      <span class=\"w-toggle\">Expand</span>\n    </div>\n  </div>\n</div>\n\n<!--  DIVIDER  -->\n<div class=\"section-divider\">\n  <div class=\"divider-line\"></div>\n  <div class=\"divider-symbol\">❧</div>\n</div>\n\n<!--  WISDOM FOR TODAY  -->\n<div class=\"container\">\n  <div class=\"section-header reveal\">\n    <div class=\"label\">Daily Wisdom</div>\n    <h2>Wisdom for <span class=\"hl\">Today</span></h2>\n    <p>A random teaching from the Book of Wisdom to carry with you through your day.</p>\n    <div class=\"line\"></div>\n  </div>\n\n  <div class=\"wisdom-today reveal\" id=\"wisdomToday\">\n    <div class=\"quote-text\" id=\"dailyQuote\">The journey of wisdom begins not with answers but with the courage to ask the right questions.</div>\n    <div class=\"quote-source\" id=\"dailySource\">— Book of Wisdom</div>\n    <button class=\"wisdom-btn\" onclick=\"newWisdom()\">\n      <svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21.5 2v6h-6M2.5 22v-6h6M2 11.5a10 10 0 0 1 18.8-4.3M22 12.5a10 10 0 0 1-18.8 4.2\"></path></svg>\n      New Wisdom\n    </button>\n  </div>\n</div>\n\n<!--  DIVIDER  -->\n<div class=\"section-divider\">\n  <div class=\"divider-line\"></div>\n  <div class=\"divider-symbol\">❧</div>\n</div>\n\n<!--  PROGRESS TRACKER  -->\n<div class=\"container\">\n  <div class=\"section-header reveal\">\n    <div class=\"label\">Your Journey</div>\n    <h2>Progress Through <span class=\"hl\">Wisdom</span></h2>\n    <p>Track your engagement with the eight pillars. Click each one as you explore it.</p>\n    <div class=\"line\"></div>\n  </div>\n\n  <div class=\"progress-section reveal\">\n    <div class=\"progress-tracker\" id=\"progressTracker\">\n      <div class=\"progress-step\" data-index=\"0\" onclick=\"toggleProgress(0)\">\n        <span class=\"ps-icon\">💡</span>\n        <span class=\"ps-label\">Self-Knowledge</span>\n      </div>\n      <div class=\"progress-step\" data-index=\"1\" onclick=\"toggleProgress(1)\">\n        <span class=\"ps-icon\">⚖️</span>\n        <span class=\"ps-label\">Balance</span>\n      </div>\n      <div class=\"progress-step\" data-index=\"2\" onclick=\"toggleProgress(2)\">\n        <span class=\"ps-icon\">🌱</span>\n        <span class=\"ps-label\">Presence</span>\n      </div>\n      <div class=\"progress-step\" data-index=\"3\" onclick=\"toggleProgress(3)\">\n        <span class=\"ps-icon\">💬</span>\n        <span class=\"ps-label\">Silence</span>\n      </div>\n      <div class=\"progress-step\" data-index=\"4\" onclick=\"toggleProgress(4)\">\n        <span class=\"ps-icon\">💪</span>\n        <span class=\"ps-label\">Discipline</span>\n      </div>\n      <div class=\"progress-step\" data-index=\"5\" onclick=\"toggleProgress(5)\">\n        <span class=\"ps-icon\">🌊</span>\n        <span class=\"ps-label\">Impermanence</span>\n      </div>\n      <div class=\"progress-step\" data-index=\"6\" onclick=\"toggleProgress(6)\">\n        <span class=\"ps-icon\">🤝</span>\n        <span class=\"ps-label\">Unity</span>\n      </div>\n      <div class=\"progress-step\" data-index=\"7\" onclick=\"toggleProgress(7)\">\n        <span class=\"ps-icon\">⭐</span>\n        <span class=\"ps-label\">Service</span>\n      </div>\n    </div>\n    <div class=\"progress-bar-wrap\">\n      <div class=\"progress-bar-fill\" id=\"progressFill\" style=\"width:0%\"></div>\n    </div>\n    <div class=\"progress-text\"><strong id=\"progressCount\">0</strong> of 8 pillars explored</div>\n  </div>\n</div>\n\n<!--  DIVIDER  -->\n<div class=\"section-divider\">\n  <div class=\"divider-line\"></div>\n  <div class=\"divider-symbol\">❧</div>\n</div>\n\n<!--  WISDOM QUIZ  -->\n<div class=\"container\">\n  <div class=\"section-header reveal\">\n    <div class=\"label\">Reflection</div>\n    <h2>The Wisdom <span class=\"hl\">Quiz</span></h2>\n    <p>Test your understanding of the principles and discover where you are on your wisdom journey.</p>\n    <div class=\"line\"></div>\n  </div>\n\n  <div class=\"quiz-section reveal\" id=\"quizSection\">\n    <div class=\"quiz-progress\" id=\"quizProgress\"></div>\n    <div class=\"quiz-question\" id=\"quizQuestion\">Loading...</div>\n    <div class=\"quiz-options\" id=\"quizOptions\"></div>\n    <div class=\"quiz-feedback\" id=\"quizFeedback\"></div>\n    <div class=\"quiz-score\" id=\"quizScore\"></div>\n    <button class=\"quiz-next-btn\" id=\"quizNextBtn\" onclick=\"nextQuestion()\">Next Question</button>\n  </div>\n</div>\n\n<!--  DIVIDER  -->\n<div class=\"section-divider\">\n  <div class=\"divider-line\"></div>\n  <div class=\"divider-symbol\">❧</div>\n</div>\n\n<!--  KEY QUOTES  -->\n<div class=\"container\">\n  <div class=\"section-header reveal\">\n    <div class=\"label\">Timeless Voices</div>\n    <h2>Quotes on <span class=\"hl\">Wisdom</span></h2>\n    <p>Enduring insights from the great wisdom traditions of the world.</p>\n    <div class=\"line\"></div>\n  </div>\n\n  <div class=\"quotes-grid\">\n    <div class=\"quote-card reveal\">\n      <div class=\"qm\">\"</div>\n      <blockquote>The only true wisdom is in knowing you know nothing.</blockquote>\n      <cite>— Socrates</cite>\n    </div>\n    <div class=\"quote-card reveal reveal-delay-1\">\n      <div class=\"qm\">\"</div>\n      <blockquote>The unexamined life is not worth living.</blockquote>\n      <cite>— Plato</cite>\n    </div>\n    <div class=\"quote-card reveal reveal-delay-2\">\n      <div class=\"qm\">\"</div>\n      <blockquote>It is not what happens to you, but how you react to it that matters.</blockquote>\n      <cite>— Epictetus</cite>\n    </div>\n    <div class=\"quote-card reveal\">\n      <div class=\"qm\">\"</div>\n      <blockquote>The wound is the place where the Light enters you.</blockquote>\n      <cite>— Rumi</cite>\n    </div>\n    <div class=\"quote-card reveal reveal-delay-1\">\n      <div class=\"qm\">\"</div>\n      <blockquote>Knowing others is intelligence; knowing yourself is true wisdom. Mastering others is strength; mastering yourself is true power.</blockquote>\n      <cite>— Lao Tzu</cite>\n    </div>\n    <div class=\"quote-card reveal reveal-delay-2\">\n      <div class=\"qm\">\"</div>\n      <blockquote>The journey of a thousand miles begins with a single step.</blockquote>\n      <cite>— Lao Tzu</cite>\n    </div>\n    <div class=\"quote-card reveal\">\n      <div class=\"qm\">\"</div>\n      <blockquote>In the middle of difficulty lies opportunity.</blockquote>\n      <cite>— Albert Einstein</cite>\n    </div>\n    <div class=\"quote-card reveal reveal-delay-1\">\n      <div class=\"qm\">\"</div>\n      <blockquote>Be the change that you wish to see in the world.</blockquote>\n      <cite>— Mahatma Gandhi</cite>\n    </div>\n  </div>\n</div>\n\n<!--  FOOTER  -->\n\n\n<script>\n  //  THEME \n  const themeToggle = document.getElementById('themeToggle');\n  themeToggle.addEventListener('click', () => {\n    document.body.classList.toggle('light');\n    themeToggle.innerHTML = document.body.classList.contains('light') ? '&#9790;' : '&#9790;';\n  });\n\n  //  CANVAS PARTICLES \n  (function(){\n    const canvas = document.getElementById('bgCanvas');\n    const ctx = canvas.getContext('2d');\n    let particles = [];\n    let mouse = {x: -1000, y: -1000};\n\n    function resize(){\n      canvas.width = window.innerWidth;\n      canvas.height = window.innerHeight;\n    }\n    resize();\n    window.addEventListener('resize', resize);\n\n    const colors = ['#d4a040', '#e8c868', '#c87d2b', '#f5e6c8'];\n\n    class Particle {\n      constructor() { this.reset(); }\n      reset(){\n        this.x = Math.random() * canvas.width;\n        this.y = Math.random() * canvas.height;\n        this.vx = (Math.random() - 0.5) * 0.2;\n        this.vy = (Math.random() - 0.5) * 0.2;\n        this.r = Math.random() * 2 + 0.5;\n        this.color = colors[Math.floor(Math.random() * colors.length)];\n        this.alpha = Math.random() * 0.2 + 0.05;\n      }\n      update(){\n        this.x += this.vx;\n        this.y += this.vy;\n        if (this.x < 0 || this.x > canvas.width) this.vx *= -1;\n        if (this.y < 0 || this.y > canvas.height) this.vy *= -1;\n      }\n      draw(){\n        ctx.beginPath();\n        ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);\n        ctx.fillStyle = this.color;\n        ctx.globalAlpha = this.alpha;\n        ctx.fill();\n        ctx.globalAlpha = 1;\n      }\n    }\n\n    for (let i = 0; i < 50; i++) particles.push(new Particle());\n\n    function animate(){\n      ctx.clearRect(0, 0, canvas.width, canvas.height);\n\n      for (let i = 0; i < particles.length; i++) {\n        for (let j = i + 1; j < particles.length; j++) {\n          const dx = particles[i].x - particles[j].x;\n          const dy = particles[i].y - particles[j].y;\n          const d = Math.sqrt(dx*dx + dy*dy);\n          if (d < 120) {\n            ctx.beginPath();\n            ctx.moveTo(particles[i].x, particles[i].y);\n            ctx.lineTo(particles[j].x, particles[j].y);\n            ctx.strokeStyle = particles[i].color;\n            ctx.globalAlpha = 0.04 * (1 - d/120);\n            ctx.stroke();\n            ctx.globalAlpha = 1;\n          }\n        }\n      }\n\n      particles.forEach(p => {\n        const dx = p.x - mouse.x;\n        const dy = p.y - mouse.y;\n        const d = Math.sqrt(dx*dx + dy*dy);\n        if (d < 150) {\n          ctx.beginPath();\n          ctx.moveTo(p.x, p.y);\n          ctx.lineTo(mouse.x, mouse.y);\n          ctx.strokeStyle = p.color;\n          ctx.globalAlpha = 0.06 * (1 - d/150);\n          ctx.stroke();\n          ctx.globalAlpha = 1;\n        }\n      });\n\n      particles.forEach(p => { p.update(); p.draw(); });\n      requestAnimationFrame(animate);\n    }\n    animate();\n\n    document.addEventListener('mousemove', e => {\n      mouse.x = e.clientX;\n      mouse.y = e.clientY;\n    });\n  })();\n\n  //  FLOATING ORBS \n  (function(){\n    const c = document.getElementById('orbs');\n    const orbColors = [\n      'rgba(212,160,64,0.10)',\n      'rgba(200,125,43,0.08)',\n      'rgba(245,230,200,0.06)',\n      'rgba(232,200,104,0.08)'\n    ];\n    for (let i = 0; i < 6; i++) {\n      const o = document.createElement('div');\n      o.className = 'orb';\n      const size = 180 + Math.random() * 300;\n      o.style.cssText = `\n        width:${size}px;height:${size}px;\n        left:${Math.random()*100}%;\n        top:${Math.random()*100}%;\n        background:${orbColors[i % orbColors.length]};\n        --duration:${25 + Math.random() * 35}s;\n        --delay:${Math.random() * 10}s;\n        --max-opacity:0.3;\n        --tx:${(Math.random()-0.5)*500}px;\n        --ty:${(Math.random()-0.5)*500}px;\n      `;\n      c.appendChild(o);\n    }\n  })();\n\n  //  SCROLL PROGRESS \n  window.addEventListener('scroll', () => {\n    const s = window.scrollY / (document.body.scrollHeight - window.innerHeight) * 100;\n    document.getElementById('progress').style.width = s + '%';\n  });\n\n  //  SCROLL REVEAL \n  const revealObserver = new IntersectionObserver((entries) => {\n    entries.forEach(e => {\n      if (e.isIntersecting) {\n        e.target.classList.add('visible');\n        revealObserver.unobserve(e.target);\n      }\n    });\n  }, { threshold: 0.1 });\n\n  document.querySelectorAll('.reveal').forEach(el => revealObserver.observe(el));\n\n  //  WISDOM CARDS \n  function toggleWisdom(el) {\n    el.classList.toggle('open');\n    const toggle = el.querySelector('.w-toggle');\n    if (el.classList.contains('open')) {\n      toggle.textContent = 'Collapse';\n    } else {\n      toggle.textContent = 'Expand';\n    }\n  }\n\n  //  WISDOM FOR TODAY \n  const wisdomQuotes = [\n    'The journey of wisdom begins not with answers but with the courage to ask the right questions.',\n    'Silence is not empty. It is full of answers.',\n    'The wisest person is not the one who has all the answers, but the one who lives the questions.',\n    'What you seek is seeking you. The path and the destination are one.',\n    'Let go of the need to know, and you will begin to understand.',\n    'True wisdom is knowing that you are part of something greater than yourself.',\n    'The only way to make sense out of change is to plunge into it, move with it, and join the dance.',\n    'In the midst of movement and chaos, keep stillness inside of you.',\n    'Your vision will become clear only when you can look into your own heart.',\n    'The privilege of a lifetime is to become who you truly are.',\n    'Knowing others is intelligence; knowing yourself is true wisdom.',\n    'Simplicity is the ultimate sophistication. Strip away the unnecessary and find the essential.',\n    'Patience is not the ability to wait, but the ability to keep a good attitude while waiting.',\n    'The mind is everything. What you think you become.',\n    'Happiness is not something ready made. It comes from your own actions.',\n    'Do not dwell in the past, do not dream of the future, concentrate the mind on the present moment.',\n    'The only real failure is the failure to try. The only real mistake is the one from which we learn nothing.',\n    'Wisdom is not a product of schooling but of the lifelong attempt to acquire it.',\n    'He who learns but does not think is lost. He who thinks but does not learn is in great danger.',\n    'When you change the way you look at things, the things you look at change.'\n  ];\n\n  function newWisdom() {\n    const el = document.getElementById('dailyQuote');\n    const src = document.getElementById('dailySource');\n    el.style.opacity = '0';\n    setTimeout(() => {\n      const q = wisdomQuotes[Math.floor(Math.random() * wisdomQuotes.length)];\n      el.textContent = q;\n      src.innerHTML = '&mdash; Book of Wisdom';\n      el.style.opacity = '1';\n    }, 200);\n  }\n\n  //  PROGRESS TRACKER \n  let progressState = JSON.parse(localStorage.getItem('wisdomProgress') || '[false,false,false,false,false,false,false,false]');\n\n  function updateProgress() {\n    const steps = document.querySelectorAll('.progress-step');\n    let count = 0;\n    steps.forEach((step, i) => {\n      if (progressState[i]) {\n        step.classList.add('done');\n        count++;\n      } else {\n        step.classList.remove('done');\n      }\n    });\n    const pct = (count / progressState.length) * 100;\n    document.getElementById('progressFill').style.width = pct + '%';\n    document.getElementById('progressCount').textContent = count;\n    localStorage.setItem('wisdomProgress', JSON.stringify(progressState));\n  }\n\n  function toggleProgress(index) {\n    progressState[index] = !progressState[index];\n    updateProgress();\n  }\n\n  updateProgress();\n\n  //  WISDOM QUIZ \n  const quizData = [\n    {\n      question: 'What does \"Know thyself\" teach us?',\n      options: [\n        'To memorize ancient texts',\n        'To examine our own nature honestly',\n        'To criticize others',\n        'To accumulate knowledge'\n      ],\n      correct: 1,\n      explanation: 'Self-knowledge requires honest confrontation with your own nature, not just intellectual accumulation.'\n    },\n    {\n      question: 'What is the central insight of the principle of Balance?',\n      options: [\n        'Avoid all conflict',\n        'Choose one side and commit',\n        'Hold tension creatively between opposites',\n        'Eliminate all opposing forces'\n      ],\n      correct: 2,\n      explanation: 'Harmony emerges not from eliminating conflict but from dancing between complementary opposites.'\n    },\n    {\n      question: 'According to wisdom traditions, where does suffering arise from?',\n      options: [\n        'External circumstances',\n        'Other people\\'s actions',\n        'Absence from the present moment',\n        'Lack of wealth'\n      ],\n      correct: 2,\n      explanation: 'From Buddhism to Stoicism, wisdom traditions agree that suffering arises from being absent from the present moment.'\n    },\n    {\n      question: 'What role does silence play in wisdom?',\n      options: [\n        'It is empty nothingness',\n        'It is fertile ground for insight',\n        'It means avoiding people',\n        'It is a sign of ignorance'\n      ],\n      correct: 1,\n      explanation: 'Silence is not empty but fertile ground where insight rises from beneath the noise of daily life.'\n    },\n    {\n      question: 'True freedom comes from:',\n      options: [\n        'Doing whatever you want',\n        'Having unlimited resources',\n        'Choosing what is best through discipline',\n        'Avoiding all responsibility'\n      ],\n      correct: 2,\n      explanation: 'Discipline frees you from the tyranny of impulse, allowing you to pursue what truly matters.'\n    },\n    {\n      question: 'What is the wisdom response to impermanence?',\n      options: [\n        'Fight against change',\n        'Cling to what is familiar',\n        'Fear what is to come',\n        'Embrace the flow of change'\n      ],\n      correct: 3,\n      explanation: 'Wisdom rides the current of change with grace, knowing each ending is a new beginning.'\n    },\n    {\n      question: 'What does the principle of Unity reveal?',\n      options: [\n        'We are isolated individuals',\n        'Separation is the ultimate truth',\n        'All life is interconnected',\n        'Independence is the goal'\n      ],\n      correct: 2,\n      explanation: 'Wisdom reveals that our sense of separation is limited; beneath the surface, all is one interconnected whole.'\n    },\n    {\n      question: 'What is the highest purpose according to wisdom traditions?',\n      options: [\n        'Personal accumulation',\n        'To serve something greater than yourself',\n        'Fame and recognition',\n        'Mastering others'\n      ],\n      correct: 1,\n      explanation: 'True fulfillment comes not from what you get but from what you give in service of others.'\n    }\n  ];\n\n  let currentQuestion = 0;\n  let quizScore = 0;\n  let quizAnswered = false;\n\n  function renderQuiz() {\n    const q = quizData[currentQuestion];\n    const progressDots = document.getElementById('quizProgress');\n    const questionEl = document.getElementById('quizQuestion');\n    const optionsEl = document.getElementById('quizOptions');\n    const feedbackEl = document.getElementById('quizFeedback');\n    const scoreEl = document.getElementById('quizScore');\n    const nextBtn = document.getElementById('quizNextBtn');\n\n    progressDots.innerHTML = '';\n    quizData.forEach((_, i) => {\n      const dot = document.createElement('div');\n      dot.className = 'quiz-dot' + (i === currentQuestion ? ' active' : '');\n      progressDots.appendChild(dot);\n    });\n\n    questionEl.textContent = q.question;\n    optionsEl.innerHTML = '';\n\n    q.options.forEach((opt, i) => {\n      const btn = document.createElement('button');\n      btn.className = 'quiz-option';\n      btn.textContent = opt;\n      btn.onclick = () => selectAnswer(i);\n      optionsEl.appendChild(btn);\n    });\n\n    feedbackEl.className = 'quiz-feedback';\n    feedbackEl.textContent = '';\n    scoreEl.textContent = '';\n    nextBtn.disabled = true;\n    quizAnswered = false;\n  }\n\n  function selectAnswer(index) {\n    if (quizAnswered) return;\n    quizAnswered = true;\n\n    const q = quizData[currentQuestion];\n    const options = document.querySelectorAll('.quiz-option');\n    const feedback = document.getElementById('quizFeedback');\n    const scoreEl = document.getElementById('quizScore');\n    const dots = document.querySelectorAll('.quiz-dot');\n    const nextBtn = document.getElementById('quizNextBtn');\n\n    options.forEach(btn => btn.disabled = true);\n\n    if (index === q.correct) {\n      options[index].classList.add('correct');\n      feedback.className = 'quiz-feedback show correct';\n      feedback.textContent = '\\u2713 ' + q.explanation;\n      quizScore++;\n      dots[currentQuestion].classList.add('correct');\n    } else {\n      options[index].classList.add('wrong');\n      options[q.correct].classList.add('correct');\n      feedback.className = 'quiz-feedback show wrong';\n      feedback.textContent = '\\u2717 ' + q.explanation;\n      dots[currentQuestion].classList.add('wrong');\n    }\n\n    scoreEl.innerHTML = 'Score: <strong>' + quizScore + '</strong> / ' + (currentQuestion + 1);\n    nextBtn.disabled = false;\n\n    if (currentQuestion === quizData.length - 1) {\n      nextBtn.textContent = 'See Results';\n    }\n  }\n\n  function nextQuestion() {\n    currentQuestion++;\n    if (currentQuestion >= quizData.length) {\n      const quiz = document.getElementById('quizSection');\n      const total = quizData.length;\n      const pct = Math.round((quizScore / total) * 100);\n      let level = 'Seeker';\n      if (pct === 100) level = 'Sage';\n      else if (pct >= 75) level = 'Scholar';\n      else if (pct >= 50) level = 'Apprentice';\n\n      quiz.innerHTML = `\n        <div class=\"quiz-question\">Your Wisdom Journey</div>\n        <div class=\"quiz-score\" style=\"font-size:1.4rem;margin-bottom:1rem;\">\n          You scored <strong style=\"font-size:2rem;font-family:'Playfair Display',serif;\">${quizScore}/${total}</strong>\n          <br><span style=\"font-size:0.9rem;color:var(--text-dim);\">(${pct}%)</span>\n        </div>\n        <div style=\"text-align:center;font-size:1.1rem;color:var(--gold);margin-bottom:1.5rem;font-family:'Playfair Display',serif;\">\n          Level: ${level}\n        </div>\n        <div style=\"text-align:center;color:var(--text-dim);font-size:0.9rem;margin-bottom:1.5rem;\">\n          ${pct === 100 ? 'Perfect! You embody the wisdom of the ages.' :\n            pct >= 75 ? 'Deep understanding. You walk the path of wisdom.' :\n            pct >= 50 ? 'Good foundation. Keep exploring the teachings.' :\n            'Every sage was once a beginner. The journey continues.'}\n        </div>\n        <button class=\"wisdom-btn\" style=\"margin:0 auto;display:block;\" onclick=\"resetQuiz()\">\n          Retake the Quiz\n        </button>\n      `;\n      return;\n    }\n    renderQuiz();\n  }\n\n  function resetQuiz() {\n    currentQuestion = 0;\n    quizScore = 0;\n    const quiz = document.getElementById('quizSection');\n    quiz.innerHTML = `\n      <div class=\"quiz-progress\" id=\"quizProgress\"></div>\n      <div class=\"quiz-question\" id=\"quizQuestion\">Loading...</div>\n      <div class=\"quiz-options\" id=\"quizOptions\"></div>\n      <div class=\"quiz-feedback\" id=\"quizFeedback\"></div>\n      <div class=\"quiz-score\" id=\"quizScore\"></div>\n      <button class=\"quiz-next-btn\" id=\"quizNextBtn\" onclick=\"nextQuestion()\">Next Question</button>\n    `;\n    renderQuiz();\n  }\n\n  renderQuiz();\n</script>\n\n\n\n</body>\n</html>",
  "building-a-second-brain": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<canvas id=\"particles-canvas\"></canvas>\n\n<div class=\"content\">\n  <header>\n    <div class=\"brain-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\"></path><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"></line></svg></div>\n    <h1>Building a Second Brain</h1>\n    <div class=\"subtitle\">A Proven Method to Organize Your Digital Life<br>and Unlock Your Creative Potential</div>\n    <div class=\"author\">by Tiago Forte</div>\n  </header>\n\n  <div class=\"tabs\">\n    <button class=\"tab-btn active\" data-tab=\"overview\">Overview</button>\n    <button class=\"tab-btn\" data-tab=\"code\">C.O.D.E.</button>\n    <button class=\"tab-btn\" data-tab=\"para\">P.A.R.A.</button>\n    <button class=\"tab-btn\" data-tab=\"principles\">Principles</button>\n    <button class=\"tab-btn\" data-tab=\"quotes\">Quotes</button>\n  </div>\n\n  <!-- TAB: Overview -->\n  <div class=\"tab-panel active\" id=\"tab-overview\">\n    <div class=\"card\" style=\"animation-delay: 0s;\">\n      <h2><span class=\"emoji\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\"></path><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"></line></svg></span> What is a Second Brain?</h2>\n      <p>A <strong>Second Brain</strong> is a trusted digital system for capturing, organizing, and retrieving your ideas and knowledge. It's like having an external memory that never forgets — freeing your biological brain to do what it does best: think, create, and connect.</p>\n    </div>\n\n    <div class=\"card\" style=\"animation-delay: 0.1s;\">\n      <h2><span class=\"emoji\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><circle cx=\"12\" cy=\"12\" r=\"6\"></circle><circle cx=\"12\" cy=\"12\" r=\"2\"></circle></svg></span> The Big Idea</h2>\n      <p>\"Your mind is for <strong>having ideas</strong>, not holding them.\" The goal is to offload information storage to a digital system so you can focus on creativity and action.</p>\n    </div>\n\n    <div class=\"card\" style=\"animation-delay: 0.2s;\">\n      <h2><span class=\"emoji\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"13 2 3 14 12 14 11 22 21 10 12 10 13 2\"></polygon></svg></span> Why It Matters</h2>\n      <ul>\n        <li>Stop forgetting great ideas</li>\n        <li>Connect insights across different domains</li>\n        <li>Reduce mental clutter and anxiety</li>\n        <li>Produce better creative work, faster</li>\n        <li>Turn information consumption into creation</li>\n      </ul>\n    </div>\n\n    <div class=\"progress-container\">\n      <div class=\"progress-label\">Knowledge journey</div>\n      <div class=\"progress-bar-bg\">\n        <div class=\"progress-bar-fill\" id=\"progress-fill\" style=\"width: 42%;\"></div>\n      </div>\n    </div>\n  </div>\n\n  <!-- TAB: C.O.D.E. -->\n  <div class=\"tab-panel\" id=\"tab-code\">\n    <p style=\"color:#888; margin-bottom:1rem; font-size: 0.9rem;\">The four-step method to build your Second Brain. Click each to expand.</p>\n\n    <div class=\"code-grid\">\n      <div class=\"code-box\">\n        <span class=\"letter c\">C</span>\n        <span class=\"label\">Capture</span>\n        <span class=\"desc\">Keep what resonates. Save ideas, quotes, insights — anything that sparks your interest.</span>\n      </div>\n      <div class=\"code-box\">\n        <span class=\"letter o\">O</span>\n        <span class=\"label\">Organize</span>\n        <span class=\"desc\">Save for actionability. Use the P.A.R.A. system to keep things findable.</span>\n      </div>\n      <div class=\"code-box\">\n        <span class=\"letter d\">D</span>\n        <span class=\"label\">Distill</span>\n        <span class=\"desc\">Find the essence. Use progressive summarization to layer meaning over time.</span>\n      </div>\n      <div class=\"code-box\">\n        <span class=\"letter e\">E</span>\n        <span class=\"label\">Express</span>\n        <span class=\"desc\">Share your work. Create intermediate packets and ship before perfection.</span>\n      </div>\n    </div>\n\n    <div class=\"card\" style=\"margin-top:1rem;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"></path><path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z\"></path></svg> Progressive Summarization</h2>\n      <p>Don't summarize everything at once. Let important ideas emerge naturally:</p>\n      <ul>\n        <li><strong>Layer 1:</strong> Saved notes (original content)</li>\n        <li><strong>Layer 2:</strong> Bold the important passages</li>\n        <li><strong>Layer 3:</strong> Highlight the most important</li>\n        <li><strong>Layer 4:</strong> Executive summary (a few sentences)</li>\n        <li><strong>Layer 5:</strong> Remix into something new</li>\n      </ul>\n    </div>\n  </div>\n\n  <!-- TAB: P.A.R.A. -->\n  <div class=\"tab-panel\" id=\"tab-para\">\n    <p style=\"color:#888; margin-bottom:1rem; font-size: 0.9rem;\">The organization system. Tap any card for more detail.</p>\n\n    <div class=\"para-grid\">\n      <div class=\"para-card\" onclick=\"toggleDetail(this)\">\n        <span class=\"para-letter\">P</span>\n        <span class=\"para-title\">Projects</span>\n        <span class=\"para-desc\">Short-term outcomes you're actively working on</span>\n        <span class=\"para-detail\">e.g. \"Build portfolio\", \"Plan vacation\", \"Write report\"</span>\n      </div>\n      <div class=\"para-card\" onclick=\"toggleDetail(this)\">\n        <span class=\"para-letter\">A</span>\n        <span class=\"para-title\">Areas</span>\n        <span class=\"para-desc\">Long-term responsibilities you maintain</span>\n        <span class=\"para-detail\">e.g. \"Health\", \"Finances\", \"Career\", \"Relationships\"</span>\n      </div>\n      <div class=\"para-card\" onclick=\"toggleDetail(this)\">\n        <span class=\"para-letter\">R</span>\n        <span class=\"para-title\">Resources</span>\n        <span class=\"para-desc\">Topics of interest you want to reference</span>\n        <span class=\"para-detail\">e.g. \"Design notes\", \"Book summaries\", \"Recipes\"</span>\n      </div>\n      <div class=\"para-card\" onclick=\"toggleDetail(this)\">\n        <span class=\"para-letter\">A</span>\n        <span class=\"para-title\">Archives</span>\n        <span class=\"para-desc\">Inactive items from the other categories</span>\n        <span class=\"para-detail\">Old projects, past areas, outdated resources — kept for reference</span>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"></path><polyline points=\"17 8 12 3 7 8\"></polyline><line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"></line></svg>️ The P.A.R.A. Rule</h2>\n      <p>Everything you save falls into exactly one of these four categories. When a project finishes, move it to Archives. When an area becomes inactive, archive it. This keeps your system clean and focused on the present.</p>\n    </div>\n  </div>\n\n  <!-- TAB: Principles -->\n  <div class=\"tab-panel\" id=\"tab-principles\">\n    <div class=\"card\" style=\"animation-delay: 0s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"21\"></line></svg> 1. Your Brain is for Having Ideas, Not Holding Them</h2>\n      <p>Offload memory to your Second Brain. Trust the system so you can focus on connecting and creating.</p>\n    </div>\n    <div class=\"card\" style=\"animation-delay: 0.08s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"21\"></line></svg> 2. Just-in-Time Organization</h2>\n      <p>Don't over-organize upfront. Organize only when you need to find something. Let structure emerge naturally.</p>\n    </div>\n    <div class=\"card\" style=\"animation-delay: 0.16s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"21\"></line></svg> 3. Intermediate Packets</h2>\n      <p>Break work into small, reusable chunks — a paragraph, a screenshot, a bullet list. Remix them later into something bigger.</p>\n    </div>\n    <div class=\"card\" style=\"animation-delay: 0.24s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"21\"></line></svg> 4. Divergent &amp; Convergent Modes</h2>\n      <p>Separate creation from editing. Capture freely first (divergent), then refine and organize (convergent).</p>\n    </div>\n    <div class=\"card\" style=\"animation-delay: 0.32s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"21\"></line></svg> 5. Curated Consumption</h2>\n      <p>Be intentional about what you consume. Capture only what resonates — surprising, useful, or thought-provoking.</p>\n    </div>\n    <div class=\"card\" style=\"animation-delay: 0.4s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"21\"></line></svg> 6. Weekly Review</h2>\n      <p>Spend 30 minutes each week reviewing your notes and projects. This keeps your Second Brain alive and relevant.</p>\n    </div>\n  </div>\n\n  <!-- TAB: Quotes -->\n  <div class=\"tab-panel\" id=\"tab-quotes\">\n    <div class=\"quote-box\" style=\"animation-delay: 0s;\">\n      <p>\"We can now build a digital version of our mind — a Second Brain — that works the way our biological brain wishes it could.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.1s;\">\n      <p>\"The best way to get better at organizing your notes is to organize your notes.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.2s;\">\n      <p>\"Creativity is not about creating something from nothing. It's about combining existing ideas in new ways.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.3s;\">\n      <p>\"Your mind is for having ideas, not holding them.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.4s;\">\n      <p>\"Don't wait for perfection — share your intermediate packets along the way.\"</p>\n    </div>\n\n    <div class=\"card\" style=\"margin-top: 1.5rem;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"3\" width=\"20\" height=\"14\" rx=\"2\" ry=\"2\"></rect><line x1=\"8\" y1=\"21\" x2=\"16\" y2=\"21\"></line><line x1=\"12\" y1=\"17\" x2=\"12\" y2=\"21\"></line></svg> Ready to start?</h2>\n      <p>Just start capturing. Use any tool you already have — Notes, Notion, Obsidian, Apple Notes, Google Docs. The system can evolve. What matters is taking the first step.</p>\n      <p style=\"margin-top: 0.8rem; color: #a78bfa; font-weight: 600;\">→ Open your capture tool and save one thing that resonates right now.</p>\n    </div>\n  </div>\n\n  \n</div>\n\n<script>\n  //  Particle Background \n  const canvas = document.getElementById('particles-canvas');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n  let mouse = { x: 0, y: 0 };\n  let animFrame;\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = document.documentElement.scrollHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  document.addEventListener('mousemove', e => {\n    mouse.x = e.clientX;\n    mouse.y = e.clientY + window.scrollY;\n  });\n\n  class Particle {\n    constructor() { this.reset(); }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2.5 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.3;\n      this.speedY = (Math.random() - 0.5) * 0.3;\n      this.opacity = Math.random() * 0.4 + 0.1;\n      this.hue = Math.random() * 60 + 240; // purple-blue range\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n\n      // Mouse attraction\n      const dx = mouse.x - this.x;\n      const dy = mouse.y - this.y;\n      const dist = Math.sqrt(dx * dx + dy * dy);\n      if (dist < 150) {\n        this.x -= dx * 0.003;\n        this.y -= dy * 0.003;\n      }\n\n      if (this.x < 0 || this.x > canvas.width || this.y < 0 || this.y > canvas.height) {\n        this.reset();\n      }\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `hsla(${this.hue}, 70%, 70%, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 80; i++) particles.push(new Particle());\n\n  function drawConnections() {\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 120) {\n          ctx.beginPath();\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.strokeStyle = `hsla(260, 50%, 70%, ${0.06 * (1 - dist / 120)})`;\n          ctx.lineWidth = 0.5;\n          ctx.stroke();\n        }\n      }\n    }\n  }\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n    drawConnections();\n    animFrame = requestAnimationFrame(animateParticles);\n  }\n\n  animateParticles();\n\n  //  Tab Switching \n  const tabBtns = document.querySelectorAll('.tab-btn');\n  const tabPanels = document.querySelectorAll('.tab-panel');\n\n  tabBtns.forEach(btn => {\n    btn.addEventListener('click', () => {\n      tabBtns.forEach(b => b.classList.remove('active'));\n      tabPanels.forEach(p => p.classList.remove('active'));\n      btn.classList.add('active');\n      document.getElementById('tab-' + btn.dataset.tab).classList.add('active');\n      // Recalculate canvas height for new content\n      setTimeout(resizeCanvas, 100);\n    });\n  });\n\n  //  PARA Detail Toggle \n  function toggleDetail(el) {\n    el.classList.toggle('show-detail');\n  }\n\n  //  Scroll progress bar (overview tab only) \n  // Already set to 42% as an artistic choice\n\n  //  Resize canvas on scroll too \n  window.addEventListener('scroll', resizeCanvas);\n</script>\n\n\n\n</body>\n</html>",
  "daily-robert-greene": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div id=\"progress\"></div>\n<canvas id=\"bgCanvas\"></canvas>\n\n\n\n<!--  HERO  -->\n\n\n<!--  STATS  -->\n<section>\n  <div class=\"container\">\n    <div class=\"reveal reveal-d1\">\n      <span class=\"section-label\">The Arsenal</span>\n    </div>\n    <div class=\"stats-grid\" style=\"margin-top:1rem\">\n      <div class=\"stat-card reveal reveal-d2\">\n        <div class=\"stat-num\">366</div>\n        <div class=\"stat-label\">Daily Meditations</div>\n      </div>\n      <div class=\"stat-card reveal reveal-d3\">\n        <div class=\"stat-num\">5</div>\n        <div class=\"stat-label\">Core Categories</div>\n      </div>\n      <div class=\"stat-card reveal reveal-d4\">\n        <div class=\"stat-num\">1</div>\n        <div class=\"stat-label\">Year of Wisdom</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!--  TODAY'S MEDITATION  -->\n<section>\n  <div class=\"container\">\n    <div class=\"reveal reveal-d1\">\n      <span class=\"section-label\">Forge Your Mind</span>\n      <h2 class=\"section-title\">Today's Meditation</h2>\n      <p class=\"section-desc\">A daily dose of Greene's most potent insights — click to receive your lesson.</p>\n    </div>\n    <div class=\"meditation-box reveal reveal-d2\" id=\"meditationBox\">\n      <div class=\"meditation-category\" id=\"medCategory\">Power</div>\n      <div class=\"meditation-text\" id=\"medText\">Click the button below to receive today's meditation.</div>\n      <div class=\"meditation-source\" id=\"medSource\">— The 48 Laws of Power</div>\n      <button class=\"meditation-btn\" id=\"medBtn\">⚔ Receive Lesson</button>\n      <div class=\"meditation-history\" id=\"medHistory\">\n        <h4>Recent Meditations</h4>\n        <div class=\"history-tags\" id=\"historyTags\"></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!--  CATEGORIES  -->\n<section>\n  <div class=\"container\">\n    <div class=\"reveal reveal-d1\">\n      <span class=\"section-label\">The Five Disciplines</span>\n      <h2 class=\"section-title\">Categories of Power</h2>\n      <p class=\"section-desc\">Five domains of ruthless wisdom — each holding keys to a different dimension of human nature.</p>\n    </div>\n    <div class=\"category-tabs reveal reveal-d2\" id=\"categoryTabs\">\n      <button class=\"category-tab active\" data-cat=\"all\">All</button>\n      <button class=\"category-tab\" data-cat=\"power\">Power</button>\n      <button class=\"category-tab\" data-cat=\"seduction\">Seduction</button>\n      <button class=\"category-tab\" data-cat=\"mastery\">Mastery</button>\n      <button class=\"category-tab\" data-cat=\"strategy\">Strategy</button>\n      <button class=\"category-tab\" data-cat=\"human\">Human Nature</button>\n    </div>\n    <div class=\"category-grid reveal reveal-d3\" id=\"categoryGrid\"></div>\n  </div>\n</section>\n\n<!--  QUOTES  -->\n<section>\n  <div class=\"container\">\n    <div class=\"reveal reveal-d1\">\n      <span class=\"section-label\">The Gospel of Greene</span>\n      <h2 class=\"section-title\">Definitive Lines</h2>\n      <p class=\"section-desc\">The most commanding passages from across Robert Greene's body of work.</p>\n    </div>\n    <div class=\"quotes-grid\" id=\"quotesGrid\"></div>\n  </div>\n</section>\n\n<!--  FOOTER  -->\n\n\n<script>\n// \n//  DATA\n// \n\nconst MEDITATIONS = [\n  { cat:'Power', src:'The 48 Laws of Power', text:'Law 1: Never outshine the master. Always make those above you feel comfortably superior. In your desire to please or impress them, do not go too far in displaying your talents or you might accomplish the opposite — inspire fear and insecurity.' },\n  { cat:'Power', src:'The 48 Laws of Power', text:'Law 3: Conceal your intentions. Keep people off-balance and in the dark by never revealing the purpose behind your actions. If they have no clue what you are up to, they cannot prepare a defense.' },\n  { cat:'Power', src:'The 48 Laws of Power', text:'Law 6: Court attention at all costs. Everything is judged by its appearance; what is unseen counts for nothing. Never let yourself get lost in the crowd, then, or buried in oblivion. Stand out.' },\n  { cat:'Power', src:'The 48 Laws of Power', text:'Law 15: Crush your enemy totally. If you must attack, do so with overwhelming force. More is lost through stopping halfway than through total annihilation.' },\n  { cat:'Power', src:'The 48 Laws of Power', text:'Law 25: Re-create yourself. Do not accept the roles that society foists on you. Forge a new identity, one that commands attention and never bores the audience.' },\n  { cat:'Power', src:'The 48 Laws of Power', text:'Law 33: Discover each man\\'s thumbscrew. Everyone has a weakness, a gap in their castle wall. That weakness is usually an insecurity, an uncontrollable emotion or need.' },\n  { cat:'Power', src:'The 48 Laws of Power', text:'Law 38: Think as you like but behave like others. If you make a show of going against the times, flaunting your unconventional ideas, people will think you only want attention.' },\n  { cat:'Power', src:'The 48 Laws of Power', text:'Law 47: Do not go past the mark you have aimed for. In victory, know when to stop. The moment of victory is often the moment of greatest peril.' },\n  { cat:'Seduction', src:'The Art of Seduction', text:'The Siren: The ultimate femme fatale. She is the master of the mixed message, offering promise one moment and indifference the next, keeping her target perpetually off-balance and hungry for more.' },\n  { cat:'Seduction', src:'The Art of Seduction', text:'The Rake: The dark, brooding figure whose very danger is his allure. He has a past that is hinted at but never fully revealed, making him endlessly fascinating.' },\n  { cat:'Seduction', src:'The Art of Seduction', text:'The Dandy: Style as a form of seduction. The dandy understands that appearance is reality and that what you wear, how you carry yourself, is a performance that can mesmerize.' },\n  { cat:'Seduction', src:'The Art of Seduction', text:'The Charmer: Make your target feel like the most important person in the world. Pay attention to every detail, mirror their moods, and create a bubble of intimacy.' },\n  { cat:'Seduction', src:'The Art of Seduction', text:'The Coquette: Master of withdrawal. The coquette excites desire by making her target pursue, then withdraws. She is never fully possessed.' },\n  { cat:'Seduction', src:'The Art of Seduction', text:'Seduction is a game of psychology, not sex. It appeals to the irrational, the repressed, the childlike side of human nature.' },\n  { cat:'Seduction', src:'The Art of Seduction', text:'Isolate your target. Create a world for two where the outside ceases to exist. The more cut off they are, the more they will succumb.' },\n  { cat:'Seduction', src:'The Art of Seduction', text:'The seductive gaze: Looking at someone as if they are the only person in the room, as if you see something in them no one else sees.' },\n  { cat:'Mastery', src:'Mastery', text:'The life path: Discover your calling — that deep inclination that feels fated. Your true life\\'s task is not imposed from outside but emerges from within.' },\n  { cat:'Mastery', src:'Mastery', text:'The apprenticeship: Submit to a rigorous period of learning. Spend years observing, absorbing, and practicing. Mastery cannot be rushed.' },\n  { cat:'Mastery', src:'Mastery', text:'Social intelligence: Learn to read people, to see through their masks. The naive believe people are what they seem; the master knows everyone wears a social face.' },\n  { cat:'Mastery', src:'Mastery', text:'The creative-active phase: After years of apprenticeship, you must break from convention. Innovation comes from combining skills and disciplines in new ways.' },\n  { cat:'Mastery', src:'Mastery', text:'Masters are not born; they are made through a combination of intense practice, deep observation, and a relentless desire to improve.' },\n  { cat:'Mastery', src:'Mastery', text:'The intuitive mind: After enough deep practice, the master no longer thinks consciously. Decisions flow like instinct. This is the fruit of years of work.' },\n  { cat:'Mastery', src:'Mastery', text:'Avoid the comfort trap. The moment you feel comfortable, you have stopped growing. Seek out challenges that stretch you beyond your limits.' },\n  { cat:'Strategy', src:'The 33 Strategies of War', text:'The strategy of the void: Create a vacuum that draws your enemies in. When you leave an empty space, they rush to fill it and expose themselves.' },\n  { cat:'Strategy', src:'The 33 Strategies of War', text:'The controlled chaos strategy: Do not fear disorder — use it. Stir up confusion to conceal your movements and unbalance your opponents.' },\n  { cat:'Strategy', src:'The 33 Strategies of War', text:'The death-ground strategy: Place your back against the wall. When there is no retreat, you fight with the desperation that brings victory.' },\n  { cat:'Strategy', src:'The 33 Strategies of War', text:'The perfect strategy: Go where your opponent is weak. Do not attack strength; find the gap in their armor and strike there with everything you have.' },\n  { cat:'Strategy', src:'The 33 Strategies of War', text:'The grand strategy: See the whole board. Tactics are about the moment; strategy is about the entire campaign. Think years ahead, not minutes.' },\n  { cat:'Strategy', src:'The 33 Strategies of War', text:'The fait accompli: Present your opponent with a done deal. Make your move so swiftly and decisively that there is no time for them to react.' },\n  { cat:'Strategy', src:'The 33 Strategies of War', text:'Play the subtle enemy: Be unpredictable. If your enemy cannot discern your pattern, they cannot anticipate your moves.' },\n  { cat:'Human Nature', src:'The Laws of Human Nature', text:'The law of irrationality: We think we are rational, but we are driven by deep, unconscious emotions. Master your own irrationality before trying to master others.' },\n  { cat:'Human Nature', src:'The Laws of Human Nature', text:'The law of narcissism: Everyone has some degree of narcissism. The key is to transform unhealthy narcissism into the healthy kind — into self-worth and purpose.' },\n  { cat:'Human Nature', src:'The Laws of Human Nature', text:'The law of role-playing: We are all actors on a stage. People wear masks appropriate to the situation. See through the masks to the real person beneath.' },\n  { cat:'Human Nature', src:'The Laws of Human Nature', text:'The law of compulsive behavior: People are creatures of habit. Their past behaviors predict their future actions more reliably than their words.' },\n  { cat:'Human Nature', src:'The Laws of Human Nature', text:'The law of envy: Envy is the most toxic of emotions. People will mask their envy as criticism. Learn to detect it in yourself and others.' },\n  { cat:'Human Nature', src:'The Laws of Human Nature', text:'The law of grandiosity: Beware of grandiosity in yourself and others. It is a defense against deep insecurity. The grandiose person cannot admit weakness.' },\n  { cat:'Human Nature', src:'The Laws of Human Nature', text:'The law of aggression: Repressed aggression does not disappear — it finds indirect outlets. Understand the passive-aggressive patterns in those around you.' },\n];\n\nconst CATEGORIES = [\n  {\n    id:'power', icon:'\\u2694', title:'Power', count:'8 Laws',\n    preview:'The art of acquiring and maintaining power in any social dynamic. Greene draws from history\\'s most cunning strategists.',\n    lessons:[\n      'Never outshine the master — make superiors feel secure',\n      'Conceal your intentions; keep people guessing',\n      'Court attention at all costs — invisibility is death',\n      'Crush your enemy totally — half-measures invite retaliation',\n      'Re-create yourself — forge an identity that commands respect',\n      'Find each man\\'s thumbscrew and press it',\n      'Think as you like, but behave like others',\n      'Know when to stop — victory is the moment of greatest peril'\n    ]\n  },\n  {\n    id:'seduction', icon:'\\u2726', title:'Seduction', count:'7 Archetypes',\n    preview:'The psychology of attraction — not merely romance, but the art of drawing people into your orbit.',\n    lessons:[\n      'The Siren: Master the mixed message — promise and withdrawal',\n      'The Rake: Danger itself can be the allure',\n      'The Dandy: Style as performance — appearance is reality',\n      'The Charmer: Make each person feel they are the only one',\n      'The Coquette: Withdrawal excites more than pursuit',\n      'Seduction is psychological, not physical — target the irrational',\n      'Isolate your target — create a world for two'\n    ]\n  },\n  {\n    id:'mastery', icon:'\\u2606', title:'Mastery', count:'7 Stages',\n    preview:'The path to becoming the best in your field. A lifelong journey of discipline, observation, and craft.',\n    lessons:[\n      'Discover your calling — the vocation that feels fated',\n      'Submit to a rigorous apprenticeship — years of deep learning',\n      'Develop social intelligence — read people behind their masks',\n      'Enter the creative-active phase — break from convention',\n      'Masters are made, not born — relentless practice',\n      'Cultivate the intuitive mind — let decisions flow',\n      'Avoid the comfort trap — growth lives in discomfort'\n    ]\n  },\n  {\n    id:'strategy', icon:'\\u265E', title:'Strategy', count:'7 Maneuvers',\n    preview:'The military and political mindset applied to everyday battles. Think like a general, act like a surgeon.',\n    lessons:[\n      'Create a void — let enemies rush in and expose themselves',\n      'Use controlled chaos — disorder conceals your movements',\n      'Place yourself on death-ground — no retreat, total commitment',\n      'Strike at weakness — never attack strength head-on',\n      'See the whole board — think in years, not minutes',\n      'Present a fait accompli — act before they can react',\n      'Be unpredictable — patternless movements cannot be countered'\n    ]\n  },\n  {\n    id:'human', icon:'\\u25C7', title:'Human Nature', count:'7 Laws',\n    preview:'The deep, often ugly truths about why people think, feel, and act the way they do.',\n    lessons:[\n      'We are driven by unconscious emotions, not reason',\n      'Transform narcissism into purpose and self-worth',\n      'Everyone wears a mask — learn to see behind it',\n      'Past behavior predicts future actions, not words',\n      'Envy masks as criticism — detect it in yourself and others',\n      'Grandiosity is armor for deep insecurity',\n      'Repressed aggression finds indirect outlets'\n    ]\n  }\n];\n\nconst QUOTES = [\n  { text:'The key to power is the ability to judge who is best able to further your interests in all kinds of situations.', src:'The 48 Laws of Power' },\n  { text:'In the game of power, the people who come out on top are those who can master their own emotions and exploit the emotions of others.', src:'The 48 Laws of Power' },\n  { text:'Seduction is a game of psychology, not sex — it appeals to the irrational, the repressed, the childlike side of human nature.', src:'The Art of Seduction' },\n  { text:'The future belongs to those who learn more skills and combine them in creative ways.', src:'Mastery' },\n  { text:'Your task is to build a power base so strong that you can afford to be generous, to disarm your enemies with kindness.', src:'The 48 Laws of Power' },\n  { text:'The greatest deception of all is to appear as a friend while working as an enemy.', src:'The 33 Strategies of War' },\n  { text:'Mistakes are the only way to learn deeply and permanently. Each failure brings you closer to mastery.', src:'Mastery' },\n  { text:'Understand: people are irrational. They are driven by emotions, not reason. To expect otherwise is to set yourself up for disappointment.', src:'The Laws of Human Nature' },\n  { text:'Power requires the ability to play with appearances. To seem better, nobler, more powerful than you really are.', src:'The 48 Laws of Power' },\n  { text:'The most dangerous person is the one who listens, thinks, and observes. The loud ones are the weakest.', src:'The 33 Strategies of War' },\n  { text:'All great masters are basically like children: they have a sense of wonder, of openness, of intense curiosity.', src:'Mastery' },\n  { text:'Do not waste valuable time on enemies who are beneath you. Their attacks will only drag you down to their level.', src:'The 48 Laws of Power' },\n];\n\n// \n//  PARTICLE BACKGROUND\n// \n\nconst canvas = document.getElementById('bgCanvas');\nconst ctx = canvas.getContext('2d');\nlet particles = [];\nlet mouseX = 0, mouseY = 0;\nlet animId;\n\nfunction resizeCanvas(){\n  canvas.width = window.innerWidth;\n  canvas.height = window.innerHeight;\n}\nresizeCanvas();\nwindow.addEventListener('resize', resizeCanvas);\n\nfunction initParticles(){\n  particles = [];\n  const count = Math.min(80, Math.floor(canvas.width * canvas.height / 12000));\n  for(let i=0; i<count; i++){\n    particles.push({\n      x: Math.random() * canvas.width,\n      y: Math.random() * canvas.height,\n      vx: (Math.random() - 0.5) * 0.5,\n      vy: (Math.random() - 0.5) * 0.5,\n      r: Math.random() * 2 + 0.5,\n    });\n  }\n}\ninitParticles();\nwindow.addEventListener('resize', ()=>{\n  resizeCanvas();\n  initParticles();\n});\n\ndocument.addEventListener('mousemove', e=>{mouseX = e.clientX; mouseY = e.clientY});\n\nfunction drawParticles(){\n  ctx.clearRect(0,0,canvas.width,canvas.height);\n  const isLight = document.body.classList.contains('light');\n  const particleColor = isLight ? '180,60,50' : '200,60,50';\n  const lineColor = isLight ? '180,60,50' : '212,160,71';\n\n  for(let p of particles){\n    p.x += p.vx;\n    p.y += p.vy;\n    if(p.x < 0 || p.x > canvas.width) p.vx *= -1;\n    if(p.y < 0 || p.y > canvas.height) p.vy *= -1;\n\n    const dx = mouseX - p.x;\n    const dy = mouseY - p.y;\n    const dist = Math.sqrt(dx*dx + dy*dy);\n    if(dist < 200){\n      p.x -= dx * 0.005;\n      p.y -= dy * 0.005;\n    }\n\n    ctx.beginPath();\n    ctx.arc(p.x, p.y, p.r, 0, Math.PI*2);\n    ctx.fillStyle = `rgba(${particleColor},0.7)`;\n    ctx.fill();\n  }\n\n  for(let i=0; i<particles.length; i++){\n    for(let j=i+1; j<particles.length; j++){\n      const dx = particles[i].x - particles[j].x;\n      const dy = particles[i].y - particles[j].y;\n      const dist = Math.sqrt(dx*dx + dy*dy);\n      if(dist < 150){\n        const opacity = (1 - dist/150) * 0.15;\n        ctx.beginPath();\n        ctx.moveTo(particles[i].x, particles[i].y);\n        ctx.lineTo(particles[j].x, particles[j].y);\n        ctx.strokeStyle = `rgba(${lineColor},${opacity})`;\n        ctx.lineWidth = 0.5;\n        ctx.stroke();\n      }\n    }\n  }\n\n  animId = requestAnimationFrame(drawParticles);\n}\ndrawParticles();\n\n// \n//  THEME TOGGLE\n// \n\nconst themeToggle = document.getElementById('themeToggle');\nif(localStorage.getItem('rg-theme') === 'light'){\n  document.body.classList.add('light');\n  themeToggle.innerHTML = '&#9788;';\n}\nthemeToggle.addEventListener('click', ()=>{\n  document.body.classList.toggle('light');\n  const isLight = document.body.classList.contains('light');\n  localStorage.setItem('rg-theme', isLight ? 'light' : 'dark');\n  themeToggle.innerHTML = isLight ? '&#9788;' : '&#9790;';\n});\n\n// \n//  SCROLL REVEAL\n// \n\nconst revealObserver = new IntersectionObserver((entries)=>{\n  for(let entry of entries){\n    if(entry.isIntersecting){\n      entry.target.classList.add('visible');\n    }\n  }\n}, {threshold:0.1});\n\ndocument.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));\n\n// \n//  SCROLL PROGRESS\n// \n\nconst progressBar = document.getElementById('progress');\nwindow.addEventListener('scroll', ()=>{\n  const scroll = window.scrollY;\n  const max = document.documentElement.scrollHeight - window.innerHeight;\n  progressBar.style.width = `${(scroll/max)*100}%`;\n});\n\n// \n//  TODAY'S MEDITATION\n// \n\nconst medBtn = document.getElementById('medBtn');\nconst medText = document.getElementById('medText');\nconst medCategory = document.getElementById('medCategory');\nconst medSource = document.getElementById('medSource');\nconst historyTags = document.getElementById('historyTags');\nlet medHistory = JSON.parse(localStorage.getItem('rg-history') || '[]');\n\nfunction renderHistory(){\n  historyTags.innerHTML = medHistory.map(t =>\n    `<span class=\"history-tag\">${t}</span>`\n  ).join('');\n}\n\nfunction getRandomMeditation(){\n  const idx = Math.floor(Math.random() * MEDITATIONS.length);\n  return MEDITATIONS[idx];\n}\n\nfunction showMeditation(){\n  const m = getRandomMeditation();\n  medCategory.textContent = m.cat;\n  medText.textContent = `\"${m.text}\"`;\n  medSource.innerHTML = `&mdash; ${m.src}`;\n  medBox.style.borderColor = 'var(--gold)';\n  setTimeout(()=>{ medBox.style.borderColor = ''; }, 1500);\n\n  const short = m.text.length > 60 ? m.text.substring(0,60)+'...' : m.text;\n  medHistory.unshift(short);\n  if(medHistory.length > 5) medHistory.pop();\n  localStorage.setItem('rg-history', JSON.stringify(medHistory));\n  renderHistory();\n}\n\nconst medBox = document.querySelector('.meditation-box');\nmedBtn.addEventListener('click', showMeditation);\nrenderHistory();\n\n// Show one on load\nsetTimeout(showMeditation, 1000);\n\n// \n//  CATEGORIES\n// \n\nconst categoryGrid = document.getElementById('categoryGrid');\nconst categoryTabs = document.getElementById('categoryTabs');\n\nfunction renderCategories(filter='all'){\n  categoryGrid.innerHTML = '';\n  for(let cat of CATEGORIES){\n    if(filter !== 'all' && cat.id !== filter) continue;\n    const card = document.createElement('div');\n    card.className = 'cat-card';\n    card.dataset.cat = cat.id;\n    card.innerHTML = `\n      <div class=\"cat-card-icon\">${cat.icon}</div>\n      <h3>${cat.title}</h3>\n      <div class=\"cat-count\">${cat.count}</div>\n      <div class=\"cat-preview\">${cat.preview}</div>\n      <div class=\"cat-expanded\">\n        <ul>${cat.lessons.map(l=>`<li>${l}</li>`).join('')}</ul>\n      </div>\n      <div class=\"cat-toggle\">Expand <span class=\"toggle-icon\">&#9660;</span></div>\n    `;\n    card.addEventListener('click', ()=>{\n      card.classList.toggle('open');\n      const toggle = card.querySelector('.cat-toggle');\n      toggle.innerHTML = card.classList.contains('open')\n        ? 'Collapse <span class=\"toggle-icon\">&#9650;</span>'\n        : 'Expand <span class=\"toggle-icon\">&#9660;</span>';\n    });\n    categoryGrid.appendChild(card);\n  }\n}\n\ncategoryTabs.addEventListener('click', e=>{\n  const tab = e.target.closest('.category-tab');\n  if(!tab) return;\n  categoryTabs.querySelectorAll('.category-tab').forEach(t=>t.classList.remove('active'));\n  tab.classList.add('active');\n  renderCategories(tab.dataset.cat);\n});\n\nrenderCategories();\n\n// \n//  QUOTES\n// \n\nconst quotesGrid = document.getElementById('quotesGrid');\nfor(let q of QUOTES){\n  const card = document.createElement('div');\n  card.className = 'quote-card reveal reveal-d' + ((QUOTES.indexOf(q) % 3) + 1);\n  card.innerHTML = `\n    <div class=\"quote-text\">${q.text}</div>\n    <div class=\"quote-source\">&mdash; ${q.src}</div>\n  `;\n  quotesGrid.appendChild(card);\n  revealObserver.observe(card);\n}\n\n// \n//  KEYBOARD SHORTCUT\n// \n\ndocument.addEventListener('keydown', e=>{\n  if(e.key === 'm' || e.key === 'M'){\n    showMeditation();\n  }\n});\n</script>\n\n\n\n</body>\n</html>",
  "deep-work": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div id=\"progress\"></div>\n<canvas id=\"bgCanvas\"></canvas>\n\n\n\n<!-- HERO -->\n\n\n<!-- DEFINITIONS -->\n<section id=\"thesis\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Core Concepts</span>\n    <h2 class=\"section-title\">The Deep Work Hypothesis</h2>\n    <p class=\"section-desc\">The ability to perform deep work is becoming increasingly rare at exactly the same time it is becoming increasingly valuable.</p></div>\n    \n    <div class=\"def-grid\">\n      <div class=\"def-card reveal\" onclick=\"toggleDef(this)\">\n        <div class=\"icon\">🎯</div>\n        <h3>Deep Work</h3>\n        <p>Professional activities performed in a state of distraction-free concentration that push your cognitive capabilities to their limit.</p>\n        <div class=\"expanded\"><p>These efforts create new value, improve your skill, and are hard to replicate. This is where elite performance lives.</p></div>\n        <span class=\"toggle\">Click to expand ▼</span>\n      </div>\n      <div class=\"def-card reveal reveal-delay-1\" onclick=\"toggleDef(this)\">\n        <div class=\"icon\">🌊</div>\n        <h3>Shallow Work</h3>\n        <p>Non-cognitively demanding, logistical-style tasks, often performed while distracted.</p>\n        <div class=\"expanded\"><p>These efforts tend not to create much new value in the world and are easy to replicate. Email, meetings, social media.</p></div>\n        <span class=\"toggle\">Click to expand ▼</span>\n      </div>\n    </div>\n\n    <div class=\"formula-box reveal\">\n      <div class=\"formula\">High-Quality Work = Time Spent × Intensity of Focus</div>\n      <div class=\"formula-label\">The fundamental equation of deep work</div>\n    </div>\n\n    <div class=\"comparison reveal\">\n      <div class=\"comp-side deep\">\n        <h4>✨ Deep Work</h4>\n        <ul><li>Creates new value</li><li>Improves skills</li><li>Hard to replicate</li><li>Requires full concentration</li><li>Leads to flow states</li></ul>\n      </div>\n      <div class=\"comp-side shallow\">\n        <h4>👎 Shallow Work</h4>\n        <ul><li>Logistical tasks</li><li>Done while distracted</li><li>Easily replicated</li><li>Low cognitive demand</li><li>Creates illusion of productivity</li></ul>\n      </div>\n    </div>\n  </div>\n</section>\n\n<div class=\"part-divider\">\n  <div class=\"line\"></div>\n  <h2>Part 1: The Idea</h2>\n  <p>Why deep work matters</p>\n</div>\n\n<!-- PART 1 -->\n<section id=\"part1\">\n  <div class=\"container\">\n    <div class=\"chapter reveal\">\n      <div class=\"chapter-num\">01</div>\n      <h3>Deep Work Is Valuable</h3>\n      <p>Three groups will thrive in the new economy:</p>\n      <ul>\n        <li><strong style=\"color:var(--text)\">High-Skilled Workers</strong> — Those who can work intelligently with sophisticated technology and produce at an elite level</li>\n        <li><strong style=\"color:var(--text)\">The Superstars</strong> — The absolute best at what they do, now accessible globally</li>\n        <li><strong style=\"color:var(--text)\">The Owners</strong> — Those with capital to invest in emerging technologies</li>\n      </ul>\n      <p>To join the first two groups you need two abilities: <strong style=\"color:var(--accent)\">quickly master hard things</strong> and <strong style=\"color:var(--accent)\">produce at an elite level</strong>. Both depend entirely on deep work.</p>\n    </div>\n\n    <div class=\"chapter reveal\">\n      <div class=\"chapter-num\">02</div>\n      <h3>Deep Work Is Rare</h3>\n      <p>Despite its value, deep work is declining due to:</p>\n      <ul>\n        <li>Open office plans that destroy concentration</li>\n        <li>Instant messaging and real-time collaboration tools</li>\n        <li>Social media presence expectations</li>\n        <li>Constant email responsiveness culture</li>\n      </ul>\n      <p>Two forces drive this: <strong style=\"color:var(--text)\">The Principle of Least Resistance</strong> (default to easiest behavior) and <strong style=\"color:var(--text)\">Busyness as Proxy for Productivity</strong> (visible busyness = demonstrated productivity).</p>\n    </div>\n\n    <div class=\"chapter reveal\">\n      <div class=\"chapter-num\">03</div>\n      <h3>Deep Work Is Meaningful</h3>\n      <p>Beyond economics, deep work is psychologically fulfilling. Drawing on Csikszentmihalyi's <em>flow</em> research:</p>\n      <ul>\n        <li>A deep life is a good life — our best experiences come from intense, focused engagement</li>\n        <li>Freeing your mind from shallow obligations brings purpose and satisfaction</li>\n        <li>Depth and attention to any craft generates meaning</li>\n      </ul>\n      <p style=\"color:var(--gold);font-style:italic;margin-top:1rem\">\"Your world is shaped by what you pay attention to.\"</p>\n    </div>\n  </div>\n</section>\n\n<div class=\"part-divider\">\n  <div class=\"line\"></div>\n  <h2>Part 2: The Rules</h2>\n  <p>How to practice deep work</p>\n</div>\n\n<!-- PART 2 -->\n<section id=\"part2\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Rule #1</span>\n    <div class=\"rule\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\">\n        <div class=\"rule-num\">01</div>\n        <div><h3>Work Deeply</h3></div>\n      </div>\n      <div class=\"rule-body\">\n        <p>You need a philosophy and rituals. Choose your scheduling approach:</p>\n        <div class=\"phil-grid\">\n          <div class=\"phil-card\" onclick=\"event.stopPropagation();togglePhil(this)\">\n            <div class=\"phil-icon\">🏛</div>\n            <h4>Monastic</h4>\n            <p>Eliminate shallow obligations entirely</p>\n            <div class=\"phil-detail\"><p>Go completely off the grid. Donald Knuth only checks email a few times a year. Best for those with clear, individual goals.</p></div>\n            <div class=\"click-hint\">tap for details</div>\n          </div>\n          <div class=\"phil-card\" onclick=\"event.stopPropagation();togglePhil(this)\">\n            <div class=\"phil-icon\">🌗</div>\n            <h4>Bimodal</h4>\n            <p>Split time between deep &amp; shallow</p>\n            <div class=\"phil-detail\"><p>Defined stretches of deep pursuit (at least 1 full day) and shallow everything else. Carl Jung at his Bollingen Tower.</p></div>\n            <div class=\"click-hint\">tap for details</div>\n          </div>\n          <div class=\"phil-card\" onclick=\"event.stopPropagation();togglePhil(this)\">\n            <div class=\"phil-icon\">🔁</div>\n            <h4>Rhythmic</h4>\n            <p>Fixed daily deep work habit</p>\n            <div class=\"phil-detail\"><p>Same time every day, like writing 500 words every morning. Use the chain method: don't break the streak.</p></div>\n            <div class=\"click-hint\">tap for details</div>\n          </div>\n          <div class=\"phil-card\" onclick=\"event.stopPropagation();togglePhil(this)\">\n            <div class=\"phil-icon\">📰</div>\n            <h4>Journalistic</h4>\n            <p>Fit deep work anywhere</p>\n            <div class=\"phil-detail\"><p>Switch into deep mode in any available slot. Requires practice. Best for unpredictable schedules.</p></div>\n            <div class=\"click-hint\">tap for details</div>\n          </div>\n        </div>\n        <ul style=\"margin-top:2rem\">\n          <li>Decide WHERE you'll work and for HOW LONG</li>\n          <li>Define STRUCTURE: rules, goals, and metrics</li>\n          <li>Support your work: food, coffee, exercise, walks</li>\n          <li>4 Disciplines: Focus on the wildly important, act on lead measures, keep a scoreboard, create accountability</li>\n          <li>Execute a grand gesture to signal importance (J.K. Rowling at the Balmoral Hotel)</li>\n          <li>Routines &gt; willpower</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div></div>\n\n    <div class=\"reveal reveal-delay-1\"><span class=\"section-label\">Rule #2</span>\n    <div class=\"rule\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\">\n        <div class=\"rule-num\">02</div>\n        <div><h3>Embrace Boredom</h3></div>\n      </div>\n      <div class=\"rule-body\">\n        <p>Concentration is a muscle that must be trained. If you don't practice resisting distraction, you'll lack the mental stamina when you need it.</p>\n        <ul>\n          <li>Don't take breaks from distraction — take breaks from FOCUS. Schedule internet time; avoid it completely outside those windows</li>\n          <li>Productive meditation: during walks or drives, focus intensely on one problem. When your mind wanders, bring it back</li>\n          <li>Memorization exercises strengthen concentration</li>\n          <li>Evaluate tools by whether positives substantially outweigh negatives</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div></div>\n\n    <div class=\"reveal reveal-delay-2\"><span class=\"section-label\">Rule #3</span>\n    <div class=\"rule\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\">\n        <div class=\"rule-num\">03</div>\n        <div><h3>Quit Social Media</h3></div>\n      </div>\n      <div class=\"rule-body\">\n        <p>Apply the craftsman approach to network tools. Reject the \"any-benefit\" mindset. Use the law of the vital few.</p>\n        <ul>\n          <li>Ask: Do the positives substantially outweigh the negatives?</li>\n          <li>The Craftsman Test: Does this tool help achieve my most important professional goals?</li>\n          <li>Try a 30-day break from all optional online activities, then ask: Would the month have been better with it? Did people care?</li>\n          <li>Don't use the internet to entertain between tasks — let boredom teach focus</li>\n          <li>Become hard to reach: use sender filters, make people do more work before contacting you</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div></div>\n\n    <div class=\"reveal reveal-delay-3\"><span class=\"section-label\">Rule #4</span>\n    <div class=\"rule\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\">\n        <div class=\"rule-num\">04</div>\n        <div><h3>Drain the Shallows</h3></div>\n      </div>\n      <div class=\"rule-body\">\n        <p>Shallow work is inevitable but should be contained. Keep it to a bare minimum.</p>\n        <ul>\n          <li>Schedule every minute of your day (time-blocking) to confront shallow time and protect deep blocks</li>\n          <li>Quantify depth: How long to train a smart college grad to do this task?</li>\n          <li>Set fixed-schedule productivity: finish work at a set time to force ruthless prioritization</li>\n          <li>Process-oriented email: \"Does this need a response?\" \"Who's the right person?\"</li>\n          <li>Shallow work creates no new value and is easily replicated</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div></div>\n  </div>\n</section>\n\n<!-- FOCUS TIMER -->\n<section id=\"timer\" class=\"timer-section\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Practice</span>\n    <h2 class=\"section-title\">Deep Work Timer</h2>\n    <p class=\"section-desc\" style=\"margin:0 auto 2rem\">Put the philosophy into practice. Choose your session length and start.</p></div>\n    \n    <div class=\"reveal\">\n      <div class=\"timer-modes\">\n        <button class=\"timer-mode active\" onclick=\"setTimer(25,this)\">25 min</button>\n        <button class=\"timer-mode\" onclick=\"setTimer(50,this)\">50 min</button>\n        <button class=\"timer-mode\" onclick=\"setTimer(90,this)\">90 min</button>\n        <button class=\"timer-mode\" onclick=\"setTimer(120,this)\">2 hrs</button>\n      </div>\n      <div class=\"timer-ring\">\n        <svg width=\"300\" height=\"300\">\n          <circle class=\"bg\" cx=\"150\" cy=\"150\" r=\"140\"></circle>\n          <circle class=\"progress\" id=\"ringProgress\" cx=\"150\" cy=\"150\" r=\"140\" stroke-dasharray=\"879.6\" stroke-dashoffset=\"0\"></circle>\n        </svg>\n        <div class=\"timer-display\" id=\"timerDisplay\" style=\"position:absolute;top:50%;left:50%;transform:translate(-50%,-50%)\">25:00</div>\n      </div>\n      <div class=\"timer-controls\">\n        <button class=\"timer-btn\" id=\"startBtn\" onclick=\"toggleTimer()\">Start</button>\n        <button class=\"timer-btn reset\" onclick=\"resetTimer()\">Reset</button>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- TAKEAWAYS -->\n<section id=\"takeaways\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Remember</span>\n    <h2 class=\"section-title\">Key Takeaways</h2></div>\n    <div class=\"takeaway-grid\">\n      <div class=\"takeaway reveal\"><div class=\"num\">1</div><p>Deep work is a <strong style=\"color:var(--text)\">superpower</strong> in our distracted economy — learn it, practice it, prioritize it.</p></div>\n      <div class=\"takeaway reveal reveal-delay-1\"><div class=\"num\">2</div><p>Depth is both <strong style=\"color:var(--text)\">economically valuable</strong> and <strong style=\"color:var(--text)\">personally fulfilling</strong>.</p></div>\n      <div class=\"takeaway reveal reveal-delay-1\"><div class=\"num\">3</div><p>Concentration is a <strong style=\"color:var(--text)\">muscle</strong> — train it through deliberate practice and resistance to distraction.</p></div>\n      <div class=\"takeaway reveal reveal-delay-2\"><div class=\"num\">4</div><p>Have a <strong style=\"color:var(--text)\">clear philosophy</strong> for deep work. Don't rely on willpower alone — build rituals.</p></div>\n      <div class=\"takeaway reveal reveal-delay-2\"><div class=\"num\">5</div><p>Be <strong style=\"color:var(--text)\">ruthless</strong> about eliminating shallow obligations. Not every email deserves a response.</p></div>\n      <div class=\"takeaway reveal reveal-delay-3\"><div class=\"num\">6</div><p><strong style=\"color:var(--text)\">Quit or restrict</strong> social media and network tools that fragment your attention.</p></div>\n      <div class=\"takeaway reveal reveal-delay-3\"><div class=\"num\">7</div><p><strong style=\"color:var(--text)\">Schedule deliberately</strong>. Time-block your day and protect deep sessions fiercely.</p></div>\n      <div class=\"takeaway reveal reveal-delay-3\"><div class=\"num\">8</div><p>The goal is a <strong style=\"color:var(--text)\">meaningful, focused life</strong> where attention goes to what matters most.</p></div>\n    </div>\n  </div>\n</section>\n\n\n\n<script>\n// Particle background\nconst canvas=document.getElementById('bgCanvas'),ctx=canvas.getContext('2d');\nlet particles=[];\nfunction resize(){canvas.width=window.innerWidth;canvas.height=window.innerHeight}\nresize();window.addEventListener('resize',resize);\nclass Particle{constructor(){this.reset()}reset(){this.x=Math.random()*canvas.width;this.y=Math.random()*canvas.height;this.vx=(Math.random()-.5)*.3;this.vy=(Math.random()-.5)*.3;this.r=Math.random()*2+.5;this.a=Math.random()*.5+.1}update(){this.x+=this.vx;this.y+=this.vy;if(this.x<0||this.x>canvas.width)this.vx*=-1;if(this.y<0||this.y>canvas.height)this.vy*=-1}draw(){ctx.beginPath();ctx.arc(this.x,this.y,this.r,0,Math.PI*2);ctx.fillStyle=`rgba(108,99,255,${this.a})`;ctx.fill()}}\nfor(let i=0;i<80;i++)particles.push(new Particle());\nfunction animate(){ctx.clearRect(0,0,canvas.width,canvas.height);particles.forEach(p=>{p.update();p.draw()});for(let i=0;i<particles.length;i++)for(let j=i+1;j<particles.length;j++){const dx=particles[i].x-particles[j].x,dy=particles[i].y-particles[j].y,d=Math.sqrt(dx*dx+dy*dy);if(d<120){ctx.beginPath();ctx.moveTo(particles[i].x,particles[i].y);ctx.lineTo(particles[j].x,particles[j].y);ctx.strokeStyle=`rgba(108,99,255,${.08*(1-d/120)})`;ctx.stroke()}}requestAnimationFrame(animate)}animate();\n\n// Scroll progress\nwindow.addEventListener('scroll',()=>{const s=window.scrollY/(document.body.scrollHeight-window.innerHeight)*100;document.getElementById('progress').style.width=s+'%';document.getElementById('nav').classList.toggle('visible',window.scrollY>300)});\n\n// Reveal on scroll\nconst observer=new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}})},{threshold:.1});\ndocument.querySelectorAll('.reveal').forEach(el=>observer.observe(el));\n\n// Toggle functions\nfunction toggleDef(el){el.classList.toggle('open')}\nfunction toggleRule(el){el.classList.toggle('open')}\nfunction togglePhil(el){el.classList.toggle('open')}\n\n// Timer\nlet timerDuration=25*60,timerRemaining=25*60,timerInterval=null,timerRunning=false;\nconst circumference=2*Math.PI*140;\nfunction setTimer(min,btn){document.querySelectorAll('.timer-mode').forEach(b=>b.classList.remove('active'));btn.classList.add('active');if(timerRunning){clearInterval(timerInterval);timerRunning=false}timerDuration=min*60;timerRemaining=min*60;updateDisplay();document.getElementById('ringProgress').style.strokeDashoffset=0;document.getElementById('startBtn').textContent='Start';document.getElementById('startBtn').classList.remove('active')}\nfunction toggleTimer(){if(timerRunning){clearInterval(timerInterval);timerRunning=false;document.getElementById('startBtn').textContent='Resume';document.getElementById('startBtn').classList.remove('active')}else{timerRunning=true;document.getElementById('startBtn').textContent='Pause';document.getElementById('startBtn').classList.add('active');timerInterval=setInterval(()=>{timerRemaining--;if(timerRemaining<=0){clearInterval(timerInterval);timerRunning=false;timerRemaining=0;document.getElementById('startBtn').textContent='Done!';document.getElementById('startBtn').classList.remove('active');try{new Audio('data:audio/wav;base64,')}catch(e){}};updateDisplay()},1000)}}\nfunction resetTimer(){clearInterval(timerInterval);timerRunning=false;timerRemaining=timerDuration;updateDisplay();document.getElementById('ringProgress').style.strokeDashoffset=0;document.getElementById('startBtn').textContent='Start';document.getElementById('startBtn').classList.remove('active')}\nfunction updateDisplay(){const m=Math.floor(timerRemaining/60),s=timerRemaining%60;document.getElementById('timerDisplay').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;const progress=(timerDuration-timerRemaining)/timerDuration;document.getElementById('ringProgress').style.strokeDashoffset=circumference*(1-progress)}\n</script>\n\n\n\n</body>\n</html>",
  "ego-is-the-enemy": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n\n\n\n\n<section>\n  <div class=\"stats\">\n    <div class=\"stat\"><div class=\"stat-value\">3</div><div class=\"stat-label\">Stages of Life</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">23</div><div class=\"stat-label\">Chapters</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">2,000+</div><div class=\"stat-label\">Years of Wisdom</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">1</div><div class=\"stat-label\">Enemy Within</div></div>\n  </div>\n</section>\n\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The Premise</div>\n  <h2>Your Worst Enemy Lives <span class=\"hl\">Inside You</span></h2>\n  <p class=\"section-desc\">Ego defined: an unhealthy belief in our own importance. Arrogance. Self-centered ambition. The voice that tells us we're better than we really are.</p>\n\n  <div style=\"background: var(--surface); border: 1px solid var(--border); border-left: 3px solid var(--accent); padding: 1.5rem; margin-bottom: 2rem;\">\n    <p style=\"font-size: 0.9rem; color: var(--text-dim); line-height: 1.7;\">\"Wherever you are, whatever you're doing, your worst enemy already lives inside you: your ego. Precisely what makes us so promising as thinkers, doers, creatives, and entrepreneurs, what drives us to the top of those fields, makes us vulnerable to this darker side of the psyche.\"</p>\n    <p style=\"font-size: 0.85rem; color: var(--accent-light); text-align: right; margin-top: 0.8rem;\">— Ryan Holiday, <em>Ego Is the Enemy</em></p>\n  </div>\n\n  <div class=\"grid grid-3\">\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><circle cx=\"12\" cy=\"12\" r=\"6\"></circle><circle cx=\"12\" cy=\"12\" r=\"2\"></circle></svg></span>\n      <h4>Ego Distorts Reality</h4>\n      <p>When the notion of ourselves grows so inflated it begins to distort the reality that surrounds us. Self-confidence becomes arrogance, assertiveness becomes obstinacy.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\"></path><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"></line></svg></span>\n      <h4>Ego Inhibits Growth</h4>\n      <p>It tells us we don't need to improve. It's defensive precisely when we cannot afford to be defensive. Blocks us from getting better.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"23 4 23 10 17 10\"></polyline><path d=\"M20.49 15a9 9 0 1 1-2.12-9.36L23 10\"></path></svg></span>\n      <h4>Ego Is a Short-Term Fix</h4>\n      <p>Comfort is what keeps ego around. It soothes fear and insecurity — but it's a short-term fix with a long-term consequence. Real confidence is earned, not self-anointed.</p>\n    </div>\n  </div>\n</section>\n\n<!-- PART I: ASPIRE -->\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">Part I</div>\n  <h2><span class=\"hl\">Aspire</span></h2>\n  <p class=\"section-desc\">When you're just starting out — the cure for ego is humility and reality. Talk less, serve more, stay a student.</p>\n\n  <div class=\"phase-header\">\n    <input class=\"phase-search\" id=\"searchAspire\" placeholder=\"Search chapters...\" autocomplete=\"off\">\n    <span class=\"phase-count\" id=\"countAspire\">Showing 9 / 9</span>\n  </div>\n\n  <div class=\"ch-grid\" id=\"gridAspire\"></div>\n</section>\n\n<!-- PART II: SUCCESS -->\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">Part II</div>\n  <h2><span class=\"hl\">Success</span></h2>\n  <p class=\"section-desc\">When you achieve — don't believe your own press. Stay a student, maintain perspective, keep your sobriety.</p>\n\n  <div class=\"phase-header\">\n    <input class=\"phase-search\" id=\"searchSuccess\" placeholder=\"Search chapters...\" autocomplete=\"off\">\n    <span class=\"phase-count\" id=\"countSuccess\">Showing 8 / 8</span>\n  </div>\n\n  <div class=\"ch-grid\" id=\"gridSuccess\"></div>\n</section>\n\n<!-- PART III: FAILURE -->\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">Part III</div>\n  <h2><span class=\"hl\">Failure</span></h2>\n  <p class=\"section-desc\">When you fall — turn dead time into alive time. The effort is enough. Draw the line. Maintain your own scorecard.</p>\n\n  <div class=\"phase-header\">\n    <input class=\"phase-search\" id=\"searchFailure\" placeholder=\"Search chapters...\" autocomplete=\"off\">\n    <span class=\"phase-count\" id=\"countFailure\">Showing 6 / 6</span>\n  </div>\n\n  <div class=\"ch-grid\" id=\"gridFailure\"></div>\n</section>\n\n<!-- THE THREE VIRTUES -->\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The Framework</div>\n  <h2>The Three <span class=\"hl\">Virtues</span></h2>\n  <p class=\"section-desc\">Ego is the enemy at every stage. Here's what to cultivate instead.</p>\n\n  <table class=\"virtue-table\">\n    <thead>\n      <tr><th>Phase</th><th>Virtue</th><th>Enemy</th><th>Motto</th></tr>\n    </thead>\n    <tbody>\n      <tr><td><strong>Aspire</strong></td><td>Humility</td><td style=\"color:var(--accent-light);\">Pride</td><td>Talk less, do more</td></tr>\n      <tr><td><strong>Success</strong></td><td>Graciousness</td><td style=\"color:var(--accent-light);\">Arrogance</td><td>Stay a student</td></tr>\n      <tr><td><strong>Failure</strong></td><td>Resilience</td><td style=\"color:var(--accent-light);\">Self-pity</td><td>The effort is enough</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<!-- KEY IDEAS -->\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">Core Concepts</div>\n  <h2>The Big <span class=\"hl\">Ideas</span></h2>\n  <p class=\"section-desc\">Practical frameworks from the book to apply in your life.</p>\n\n  <div class=\"grid grid-2\">\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><circle cx=\"8.5\" cy=\"8.5\" r=\"1.5\"></circle><path d=\"M21 15l-5-5L5 21\"></path></svg>️</span>\n      <h4>The Canvas Strategy</h4>\n      <p>Be an anteambulo — one who clears the path for others. Find canvases for other people to paint on. Help yourself by helping others. The person who clears the path ultimately controls its direction.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"3\" y1=\"22\" x2=\"21\" y2=\"22\"></line><line x1=\"3\" y1=\"10\" x2=\"21\" y2=\"10\"></line><line x1=\"3\" y1=\"16\" x2=\"21\" y2=\"16\"></line><line x1=\"3\" y1=\"4\" x2=\"3\" y2=\"22\"></line><line x1=\"21\" y1=\"4\" x2=\"21\" y2=\"22\"></line></svg>️</span>\n      <h4>To Be or To Do?</h4>\n      <p>John Boyd's fork: pursue status and recognition (to be somebody) or pursue purpose and impact (to do something). One is about ego, the other about contribution.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><polyline points=\"12 6 12 12 16 14\"></polyline></svg></span>\n      <h4>Alive Time vs. Dead Time</h4>\n      <p>Every moment is either alive or dead — it depends on what you do with it. Dead time: waiting, complaining. Alive time: learning, growing, using the setback productively.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><circle cx=\"12\" cy=\"12\" r=\"6\"></circle><circle cx=\"12\" cy=\"12\" r=\"2\"></circle></svg></span>\n      <h4>Purpose Over Passion</h4>\n      <p>Passion is overrated. Purpose has boundaries. Passion is about what you feel; purpose is about what you do. Realism and deliberateness beat unbridled enthusiasm.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 20h9\"></path><path d=\"M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z\"></path></svg></span>\n      <h4>Maintain Your Own Scorecard</h4>\n      <p>Don't let the world define success for you. Measure yourself by your own standards. Other people's opinions are not your reality.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M2 12h20\"></path><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"></path></svg></span>\n      <h4>Meditate on the Immensity</h4>\n      <p>The universe is vast. Your problems and achievements are small. Perspective is the antidote to ego. Read history. Look at the stars. Get over yourself.</p>\n    </div>\n  </div>\n</section>\n\n<!-- INSIGHT GENERATOR -->\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">Confront Yourself</div>\n  <h2>The <span class=\"hl\">Insight</span> You Need</h2>\n  <p class=\"section-desc\">A random principle from the book — let honesty replace ego.</p>\n\n  <div class=\"insight-section\" id=\"insightSection\">\n    <div class=\"i-label\">Remember This</div>\n    <div class=\"i-text\" id=\"insightText\">\"The first principle is that you must not fool yourself — and you are the easiest person to fool.\"</div>\n    <button class=\"btn btn-accent\" id=\"insightBtn\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> Confront <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></button>\n  </div>\n</section>\n\n<!-- KEY QUOTES -->\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">Wisdom</div>\n  <h2>Memorable <span class=\"hl\">Quotes</span></h2>\n  <p class=\"section-desc\">Words that cut through ego and get to the truth.</p>\n\n  <div class=\"quote-block\">\n    <div class=\"q-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path><path d=\"M15 21c3 0 7-1 7-8V5c0-1.25-.757-2.017-2-2h-4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2h.75c0 2.25.25 4-2.75 4v3c0 1 0 1 1 1z\"></path></svg></div>\n    <blockquote>\"It is impossible to learn that which one thinks one already knows.\"</blockquote>\n    <cite>— Epictetus</cite>\n  </div>\n\n  <div class=\"quote-block\">\n    <div class=\"q-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path><path d=\"M15 21c3 0 7-1 7-8V5c0-1.25-.757-2.017-2-2h-4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2h.75c0 2.25.25 4-2.75 4v3c0 1 0 1 1 1z\"></path></svg></div>\n    <blockquote>\"If you start believing in your greatness, it is the death of your creativity.\"</blockquote>\n    <cite>— Marina Abramović</cite>\n  </div>\n\n  <div class=\"quote-block\">\n    <div class=\"q-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path><path d=\"M15 21c3 0 7-1 7-8V5c0-1.25-.757-2.017-2-2h-4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2h.75c0 2.25.25 4-2.75 4v3c0 1 0 1 1 1z\"></path></svg></div>\n    <blockquote>\"Be natural and yourself and this glittering flattery will be as the passing breeze of the sea on a warm summer day.\"</blockquote>\n    <cite>— William Tecumseh Sherman</cite>\n  </div>\n\n  <div class=\"quote-block\">\n    <div class=\"q-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path><path d=\"M15 21c3 0 7-1 7-8V5c0-1.25-.757-2.017-2-2h-4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2h.75c0 2.25.25 4-2.75 4v3c0 1 0 1 1 1z\"></path></svg></div>\n    <blockquote>\"Ego is the enemy of what you want and of what you have.\"</blockquote>\n    <cite>— Ryan Holiday</cite>\n  </div>\n</section>\n\n\n\n<script>\n  //  ALL CHAPTERS \n  const chapters = {\n    aspire: [\n      {n:1, title:\"Talk, Talk, Talk\", text:\"Silence is strength. Talking depletes the energy needed for actual work. Talking about your goals tricks your brain into feeling progress without doing it. The more difficult the task, the more costly talk will be. Do great work quietly — let results speak.\"},\n      {n:2, title:\"To Be or To Do?\", text:\"John Boyd's fork in the road: 'To be somebody or to do something.' Pursuing status (being) vs. purpose (doing). Ego pushes you toward being — recognition, title, image. Purpose pushes you toward doing — impact, craft, contribution. Choose wisely.\"},\n      {n:3, title:\"Become a Student\", text:\"Kirk Hammett joined Metallica and still found a guitar teacher. Frank Shamrock's formula: someone better (to learn from), someone lesser (to teach), someone equal (to challenge you). True students are self-critical, feedback-hungry, always learning. 'It is impossible to learn that which one thinks one already knows.'\"},\n      {n:4, title:\"Don't Be Passionate\", text:\"Passion is overrated. What you need is purpose and realism. Purpose = passion with boundaries. Realism = detachment and perspective. John Wooden was 'dispassionate' — never passion's slave. Leave passion for amateurs. 'Surtout, pas trop de zèle.'\"},\n      {n:5, title:\"Follow the Canvas Strategy\", text:\"Be an anteambulo — one who clears the path for others. Find canvases for other people to paint on. Benjamin Franklin wrote for his brother's paper and got no credit. Bill Belichick analyzed film for free. Be lesser, do more. The path-clearer ultimately controls the direction.\"},\n      {n:6, title:\"Restrain Yourself\", text:\"Jackie Robinson endured unimaginable abuse without reacting. Self-control is not weakness — it's power. Anger and ego make you predictable and easy to defeat. 'I have observed that those who have accomplished the greatest results are those who keep under the body.' — Booker T. Washington\"},\n      {n:7, title:\"Get Out of Your Own Head\", text:\"Detachment from your own thoughts and emotions. See yourself with distance. Ego keeps you trapped inside your own narrative. Cultivate the ability to observe yourself objectively — it's the natural antidote to ego.\"},\n      {n:8, title:\"The Danger of Early Pride\", text:\"Early success is dangerous because it feeds ego before you've earned it. Pride before destruction. The young person who achieves early must be especially careful — the very qualities that got you there can undo you if unchecked.\"},\n      {n:9, title:\"Work, Work, Work\", text:\"There is no substitute for actual work. Focus on the process, not the praise. Put your head down and produce. The only relationship between work and chatter is that one kills the other.\"}\n    ],\n    success: [\n      {n:1, title:\"Always Stay a Student\", text:\"Success doesn't mean you know everything. The moment you think you've arrived, you start declining. Keep seeking teachers, feedback, and growth. The most dangerous person is the one who thinks they have nothing left to learn.\"},\n      {n:2, title:\"Don't Tell Yourself a Story\", text:\"We edit our history into a heroic narrative and start believing it. Stay grounded in facts, not fiction. 'The first principle is that you must not fool yourself — and you are the easiest person to fool.' — Feynman.\"},\n      {n:3, title:\"What's Important to You?\", text:\"Success brings more options and distractions. You must know your values or you'll drift. Purpose keeps you anchored. Without a clear sense of what matters, ego fills the void with more, more, more.\"},\n      {n:4, title:\"Entitlement, Control, and Paranoia\", text:\"Success breeds entitlement — the belief that you deserve special treatment. This leads to a need for control, which leads to paranoia. Let go. Trust others. Stay open. The opposite of paranoia is faith in your preparation.\"},\n      {n:5, title:\"Managing Yourself\", text:\"You are your own most difficult project. Self-management is harder than managing others. Success amplifies who you already are — if you were undisciplined before, success will make you recklessly so.\"},\n      {n:6, title:\"Beware the Disease of Me\", text:\"When everything becomes about you, you lose perspective. The Disease of Me destroys teams, relationships, and success. The best leaders make it about the mission, not themselves.\"},\n      {n:7, title:\"Meditate on the Immensity\", text:\"The universe is vast. Your problems and achievements are small. Perspective is the antidote to ego. Read history. Look at the stars. Get over yourself. 'A man's life is but a moment in the vast sweep of time.'\"},\n      {n:8, title:\"Maintain Your Sobriety\", text:\"Success is intoxicating. Stay sober-minded. Don't believe the hype — yours or anyone else's. 'Be natural and yourself and this glittering flattery will be as the passing breeze of the sea on a warm summer day.' — Sherman\"}\n    ],\n    failure: [\n      {n:1, title:\"Alive Time or Dead Time?\", text:\"Every moment is either alive or dead — the difference is what you do with it. Dead time: waiting, complaining, doing nothing. Alive time: learning, growing, using the setback. The same experience can be one or the other — you choose.\"},\n      {n:2, title:\"The Effort Is Enough\", text:\"You can control only effort, not outcomes. If you gave it your best, that is enough. Detach from results. Focus on what you can control. This is not resignation — it's liberation from the tyranny of outcomes.\"},\n      {n:3, title:\"Fight Club Moments\", text:\"It's only after we've lost everything that we're free to do anything. Failure strips away ego and reveals who you really are. The first rule of failure: you can talk about it — but only to learn, not to wallow.\"},\n      {n:4, title:\"Draw the Line\", text:\"There's a difference between productive struggle and destructive self-destruction. Know when to persevere and when to walk away. Don't let ego keep you in a losing battle. Sometimes the most courageous thing is to quit.\"},\n      {n:5, title:\"Maintain Your Own Scorecard\", text:\"Don't let the world define success for you. Measure yourself by your own standards. Other people's opinions are not your reality. The only score that matters is the one you keep yourself.\"},\n      {n:6, title:\"Always Love\", text:\"Don't let failure make you bitter. The only response to hate and disappointment is love. Relationships matter more than any setback. In the end, how you treated people is all that remains.\"}\n    ]\n  };\n\n  //  THEME \n  const themeToggle = document.getElementById('themeToggle');\n  themeToggle.addEventListener('click', () => {\n    document.body.classList.toggle('light');\n    themeToggle.innerHTML = document.body.classList.contains('light') ? '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>' : '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"/></svg>️';\n  });\n\n  //  RENDER CHAPTERS \n  function renderPhase(id, data, searchId, countId) {\n    const grid = document.getElementById(id);\n    const search = document.getElementById(searchId);\n    const count = document.getElementById(countId);\n\n    function render(filter = '') {\n      grid.innerHTML = '';\n      const q = filter.toLowerCase();\n      let visible = 0;\n\n      data.forEach(ch => {\n        const match = !q ||\n          ch.title.toLowerCase().includes(q) ||\n          ch.text.toLowerCase().includes(q);\n\n        if (match) visible++;\n\n        const card = document.createElement('div');\n        card.className = `ch-card${match ? '' : ' hidden'}`;\n        card.dataset.n = ch.n;\n\n        card.innerHTML = `\n          <div class=\"ch-num\">Chapter ${ch.n}</div>\n          <h4>${ch.title}</h4>\n          <div class=\"ch-preview\">${ch.text.substring(0, 120)}…</div>\n          <div class=\"ch-full\"><div class=\"ch-full-inner\">${ch.text}</div></div>\n          <div class=\"ch-icon\">+</div>\n        `;\n\n        card.addEventListener('click', () => {\n          card.classList.toggle('open');\n        });\n\n        grid.appendChild(card);\n      });\n\n      count.textContent = `Showing ${visible} / ${data.length}`;\n    }\n\n    render();\n    search.addEventListener('input', (e) => render(e.target.value));\n  }\n\n  renderPhase('gridAspire', chapters.aspire, 'searchAspire', 'countAspire');\n  renderPhase('gridSuccess', chapters.success, 'searchSuccess', 'countSuccess');\n  renderPhase('gridFailure', chapters.failure, 'searchFailure', 'countFailure');\n\n  //  SCROLL REVEAL \n  const observer = new IntersectionObserver((entries) => {\n    entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); });\n  }, { threshold: 0.1 });\n\n  document.querySelectorAll('.ch-card, .card').forEach(el => observer.observe(el));\n\n  //  INSIGHT GENERATOR \n  const insights = [\n    \"\\\"The first principle is that you must not fool yourself — and you are the easiest person to fool.\\\" — Richard Feynman\",\n    \"\\\"It is impossible to learn that which one thinks one already knows.\\\" — Epictetus\",\n    \"\\\"Those who know do not speak. Those who speak do not know.\\\" — Lao Tzu\",\n    \"\\\"If you start believing in your greatness, it is the death of your creativity.\\\" — Marina Abramović\",\n    \"\\\"Be natural and yourself and this glittering flattery will be as the passing breeze of the sea on a warm summer day.\\\" — Sherman\",\n    \"\\\"Ego is the enemy of what you want and of what you have.\\\" — Ryan Holiday\",\n    \"Silence is strength. Talking depletes the energy needed for actual work.\",\n    \"To be or to do? Choose purpose over status.\",\n    \"Clear the path for others and you will create a path for yourself.\",\n    \"Passion is for amateurs. Purpose is for professionals.\",\n    \"The person who clears the path ultimately controls its direction.\",\n    \"Stay a student forever. The moment you think you've arrived, you start declining.\",\n    \"Dead time or alive time? The same setback can be either — you choose.\",\n    \"The effort is enough. Detach from outcomes. Focus on what you can control.\",\n    \"Maintain your own scorecard. Other people's opinions are not your reality.\",\n    \"Don't tell yourself a story. Stick to facts.\",\n    \"Meditate on the immensity. The universe is vast. You are small. This is liberating.\",\n    \"Success is intoxicating. Maintain your sobriety.\",\n    \"It's only after we've lost everything that we're free to do anything.\",\n    \"Always love. Don't let failure make you bitter.\"\n  ];\n  const insightText = document.getElementById('insightText');\n  const insightBtn = document.getElementById('insightBtn');\n\n  insightBtn.addEventListener('click', () => {\n    insightText.classList.add('fade');\n    setTimeout(() => {\n      const random = insights[Math.floor(Math.random() * insights.length)];\n      insightText.textContent = random;\n      insightText.classList.remove('fade');\n    }, 300);\n  });\n</script>\n\n\n\n</body>\n</html>",
  "hyperfocus": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<canvas id=\"particles\"></canvas>\n\n\n<!-- HERO -->\n\n\n<!-- STATS -->\n<section>\n  <div class=\"stats\">\n    <div class=\"stat\"><div class=\"stat-value\" id=\"statIntent\">0<span class=\"unit\">%</span></div><div class=\"stat-label\">Time spent intentionally</div></div>\n    <div class=\"stat\"><div class=\"stat-value\" id=\"statSeconds\">0<span class=\"unit\">s</span></div><div class=\"stat-label\">Avg focus before distraction</div></div>\n    <div class=\"stat\"><div class=\"stat-value\" id=\"statWander\">47<span class=\"unit\">%</span></div><div class=\"stat-label\">Time mind wanders</div></div>\n    <div class=\"stat\"><div class=\"stat-value\" id=\"statBits\">40</div><div class=\"stat-label\">Bits processed consciously</div></div>\n  </div>\n</section>\n\n<!-- PART 1: HYPERFOCUS -->\n<section>\n  <div class=\"section-label hf\">Part One</div>\n  <h2><span class=\"hl purple\">Hyperfocus</span></h2>\n  <p class=\"section-desc\">The art of concentrating on one important thing at a time — your brain's most productive mode.</p>\n\n  <div class=\"grid grid-2\">\n    <div class=\"card\">\n      <span class=\"card-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\"></path><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"></line></svg></span>\n      <h3>Attentional Space</h3>\n      <p>Your mental RAM. Of 11 million bits of sensory input per second, you consciously process only <strong>40 bits</strong>. You can hold about <strong>4 chunks</strong> in short-term memory.</p>\n    </div>\n    <div class=\"card teal\">\n      <span class=\"card-icon\">✈️</span>\n      <h3>Autopilot Mode</h3>\n      <p>~40% of our actions are habits. We default to autopilot, reacting to whatever is most stimulating — email pings, notifications, the news.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"card-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"20\" x2=\"18\" y2=\"10\"></line><line x1=\"12\" y1=\"20\" x2=\"12\" y2=\"4\"></line><line x1=\"6\" y1=\"20\" x2=\"6\" y2=\"14\"></line></svg></span>\n      <h3>Four Task Types</h3>\n      <p><strong>Purposeful</strong> (productive + attractive) — the sweet spot.<br>\n      <strong>Necessary</strong> (productive + unattractive).<br>\n      <strong>Distracting</strong> (unproductive + attractive).<br>\n      <strong>Unnecessary</strong> (unproductive + unattractive).</p>\n    </div>\n    <div class=\"card teal\">\n      <span class=\"card-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"23 4 23 10 17 10\"></polyline><path d=\"M20.49 15a9 9 0 1 1-2.12-9.36L23 10\"></path></svg></span>\n      <h3>Attention Residue</h3>\n      <p>After switching tasks, part of your brain keeps processing the previous one. Task switching can make your work take <strong>50% longer</strong>.</p>\n    </div>\n  </div>\n\n  <h3 style=\"margin-top:2.5rem; font-weight:700;\">The Four Stages of Hyperfocus</h3>\n  <div class=\"stage-flow\">\n    <div class=\"stage\"><div class=\"s-num\">1</div><h4>Choose</h4><p>Pick one object of attention</p></div>\n    <div class=\"stage\"><div class=\"s-num\">2</div><h4>Eliminate</h4><p>Remove distractions ahead of time</p></div>\n    <div class=\"stage\"><div class=\"s-num\">3</div><h4>Focus</h4><p>Direct full attention to the task</p></div>\n    <div class=\"stage\"><div class=\"s-num\">4</div><h4>Return</h4><p>Notice wandering &amp; gently refocus</p></div>\n  </div>\n</section>\n\n<!-- TIMER -->\n<section>\n  <div class=\"section-label tools\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"13 2 3 14 12 14 11 22 21 10 12 10 13 2\"></polygon></svg> Focus Timer</div>\n  <h2>Try a <span class=\"hl purple\">Hyperfocus</span> Session</h2>\n  <p class=\"section-desc\">Set a timer and eliminate all distractions. Give one task your full attention.</p>\n\n  <div class=\"timer-section\" id=\"timerSection\">\n    <div class=\"timer-presets\" id=\"timerPresets\">\n      <button data-minutes=\"5\">5 min</button>\n      <button data-minutes=\"15\">15 min</button>\n      <button data-minutes=\"25\" class=\"active\">25 min</button>\n      <button data-minutes=\"45\">45 min</button>\n      <button data-minutes=\"90\">90 min</button>\n    </div>\n    <div class=\"timer-display\" id=\"timerDisplay\">25:00</div>\n    <div class=\"timer-controls\">\n      <button class=\"btn btn-primary\" id=\"timerStart\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"5 3 19 12 5 21 5 3\"></polygon></svg> Start</button>\n      <button class=\"btn btn-outline\" id=\"timerReset\">↺ Reset</button>\n    </div>\n  </div>\n</section>\n\n<!-- PART 2: SCATTERFOCUS -->\n<section>\n  <div class=\"section-label sf\">Part Two</div>\n  <h2><span class=\"hl teal\">Scatterfocus</span></h2>\n  <p class=\"section-desc\">Intentionally letting your mind wander — it's not slacking, it's how you plan, recharge, and connect ideas.</p>\n\n  <div class=\"grid grid-3\">\n    <div class=\"mode-card\">\n      <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 20h9\"></path><path d=\"M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z\"></path></svg> Capture Mode</h3>\n      <p>Let your mind roam freely. Capture whatever surfaces.</p>\n      <div class=\"mode-detail\"><p>Best for identifying what's on your mind. Sit with a notebook and see what rises to consciousness — tasks, ideas, people to follow up with.</p></div>\n    </div>\n    <div class=\"mode-card\">\n      <h3>🧩 Problem-Crunching Mode</h3>\n      <p>Hold a problem loosely while your mind wanders around it.</p>\n      <div class=\"mode-detail\"><p>Best for mulling over a specific challenge. Let your subconscious make connections you wouldn't find by force.</p></div>\n    </div>\n    <div class=\"mode-card\">\n      <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 2h16\"></path><path d=\"M6 2v16a2 2 0 0 0 2 2h8a2 2 0 0 0 2-2V2\"></path><path d=\"M8 6h8\"></path><path d=\"M8 10h8\"></path><path d=\"M8 14h4\"></path></svg> Habitual Mode</h3>\n      <p>Do a simple task while your mind wanders. <em>The most powerful style.</em></p>\n      <div class=\"mode-detail\"><p>Walking, showering, washing dishes. The mindless task frees your attentional space for insights. This is where eureka moments are born.</p></div>\n    </div>\n  </div>\n\n  <div class=\"grid grid-3\" style=\"margin-top:1.5rem;\">\n    <div class=\"card\">\n      <div class=\"num\">48%</div>\n      <h3>Future</h3>\n      <p>Your mind spends most wandering time planning what's next — the most productive form of daydreaming.</p>\n    </div>\n    <div class=\"card\">\n      <div class=\"num\">28%</div>\n      <h3>Present</h3>\n      <p>Reflecting on your current approach and considering alternatives you wouldn't see while deep in focus.</p>\n    </div>\n    <div class=\"card\">\n      <div class=\"num\">12%</div>\n      <h3>Past</h3>\n      <p>Learning from memories and past experiences — even the cringeworthy ones have value.</p>\n    </div>\n  </div>\n</section>\n\n<!-- INSIGHT GENERATOR -->\n<section>\n  <div class=\"section-label sf\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 18h6\"></path><path d=\"M10 22h4\"></path><path d=\"M15.09 14c.92-.83 1.61-1.95 1.91-3.23C17.52 8.2 15.54 6 13 6c-2.54 0-4.52 2.2-4 4.77.3 1.28.99 2.4 1.91 3.23\"></path><path d=\"M8 14.5A5.5 5.5 0 0 0 16 14\"></path><path d=\"M3 15c0 1.5 1.1 2.5 2 3\"></path><path d=\"M21 15c0 1.5-1.1 2.5-2 3\"></path></svg> Try This</div>\n  <h2><span class=\"hl teal\">Scatterfocus</span> Insight Generator</h2>\n  <p class=\"section-desc\">Click to let your mind wander. Each click surfaces a different way to think about your attention.</p>\n\n  <div class=\"insight-box\" id=\"insightBox\">\n    <div class=\"insight-text\" id=\"insightText\">Your attention is the most powerful tool you have to live a good life.</div>\n    <button class=\"btn btn-primary\" id=\"insightBtn\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3l1.5 5.5L19 10l-5.5 1.5L12 17l-1.5-5.5L5 10l5.5-1.5z\"></path><path d=\"M19 17l-1 3 3-1\"></path><path d=\"M5 17l1 3-3-1\"></path></svg> Wander</button>\n  </div>\n</section>\n\n<!-- QUOTES -->\n<section>\n  <div class=\"section-label quotes\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path><path d=\"M15 21c3 0 7-1 7-8V5c0-1.25-.757-2.017-2-2h-4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2h.75c0 2.25.25 4-2.75 4v3c0 1 0 1 1 1z\"></path></svg></div>\n  <h2>Key <span class=\"hl purple\">Quotes</span></h2>\n  <p class=\"section-desc\">Memorable lines from the book that capture its essence.</p>\n\n  <div class=\"grid\" style=\"display:flex; flex-direction:column; gap:1rem;\">\n    <div class=\"quote-card\"><blockquote>\"We are what we pay attention to.\"</blockquote><cite>— Chris Bailey</cite></div>\n    <div class=\"quote-card\"><blockquote>\"Productivity means accomplishing what we intend to. Being busy doesn't make us productive.\"</blockquote><cite>— Chris Bailey</cite></div>\n    <div class=\"quote-card\"><blockquote>\"The more demands made on your time, the more essential it becomes to choose what — and how many — things you pay attention to.\"</blockquote><cite>— Chris Bailey</cite></div>\n    <div class=\"quote-card\"><blockquote>\"Your attention is the most valuable ingredient you have to live a good life.\"</blockquote><cite>— Chris Bailey</cite></div>\n  </div>\n</section>\n\n<!-- QUICK TIPS -->\n<section>\n  <div class=\"section-label tools\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"></path><polyline points=\"22 4 12 14.01 9 11.01\"></polyline></svg> Quick Tactics</div>\n  <h2>Put It Into <span class=\"hl purple\">Practice</span></h2>\n  <p class=\"section-desc\">Small, actionable changes you can make today.</p>\n\n  <ul class=\"tip-list\" id=\"tipList\">\n    <li><span class=\"check\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></span><div><strong>Leave your phone in another room</strong><span>Smartphones are productivity black holes. Physical distance reduces temptation.</span></div></li>\n    <li><span class=\"check\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></span><div><strong>Set 3 daily intentions each morning</strong><span>Decide in advance what you'll focus on. Intention is the bouncer of your attentional space.</span></div></li>\n    <li><span class=\"check\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></span><div><strong>Keep a distractions list</strong><span>Capture stray thoughts on paper so they don't hijack your attention while you work.</span></div></li>\n    <li><span class=\"check\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></span><div><strong>Use an hourly awareness chime</strong><span>Every hour, check: \"What's occupying my attentional space right now?\"</span></div></li>\n    <li><span class=\"check\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></span><div><strong>Schedule scatterfocus time</strong><span>Block 15 minutes to sit with a notebook and let your mind wander without guilt.</span></div></li>\n    <li><span class=\"check\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></span><div><strong>Meditate for 5 minutes a day</strong><span>The single most validated way to expand your attentional space — proven to increase it by 30%+.</span></div></li>\n  </ul>\n</section>\n\n\n\n<script>\n  //  THEME \n  const themeToggle = document.getElementById('themeToggle');\n  themeToggle.addEventListener('click', () => {\n    document.body.classList.toggle('dark');\n    themeToggle.innerHTML = document.body.classList.contains('dark') ? '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"/></svg>️' : '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>';\n  });\n\n  //  SCROLL REVEAL \n  const observer = new IntersectionObserver((entries) => {\n    entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); });\n  }, { threshold: 0.15 });\n\n  document.querySelectorAll('.card, .stage, .quote-card, .mode-card, .tip-list li').forEach(el => observer.observe(el));\n\n  //  COUNTER ANIMATION \n  function animateCounter(el, target, suffix = '') {\n    let current = 0;\n    const step = Math.ceil(target / 40);\n    const interval = setInterval(() => {\n      current += step;\n      if (current >= target) { current = target; clearInterval(interval); }\n      el.innerHTML = current + suffix;\n    }, 30);\n  }\n\n  const statObserver = new IntersectionObserver((entries) => {\n    entries.forEach(e => {\n      if (e.isIntersecting) {\n        animateCounter(document.getElementById('statIntent'), 42, '<span class=\"unit\">%</span>');\n        animateCounter(document.getElementById('statSeconds'), 40, '<span class=\"unit\">s</span>');\n        statObserver.disconnect();\n      }\n    });\n  }, { threshold: 0.5 });\n  statObserver.observe(document.querySelector('.stats'));\n\n  //  TIMER \n  let timerMinutes = 25;\n  let timerSeconds = 25 * 60;\n  let timerRunning = false;\n  let timerInterval = null;\n  const timerDisplay = document.getElementById('timerDisplay');\n  const timerStart = document.getElementById('timerStart');\n  const timerReset = document.getElementById('timerReset');\n  const presets = document.querySelectorAll('#timerPresets button');\n\n  function updateTimerDisplay() {\n    const m = Math.floor(timerSeconds / 60);\n    const s = timerSeconds % 60;\n    timerDisplay.textContent = `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;\n  }\n\n  function stopTimer() {\n    timerRunning = false;\n    timerInterval && clearInterval(timerInterval);\n    timerStart.innerHTML = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"5 3 19 12 5 21 5 3\"/></svg> Start';\n    timerDisplay.classList.remove('running');\n  }\n\n  function startTimer() {\n    if (timerRunning) { stopTimer(); return; }\n    if (timerSeconds <= 0) { resetTimer(); return; }\n    timerRunning = true;\n    timerStart.textContent = '⏸ Pause';\n    timerDisplay.classList.add('running');\n    timerInterval = setInterval(() => {\n      timerSeconds--;\n      updateTimerDisplay();\n      if (timerSeconds <= 0) {\n        stopTimer();\n        timerDisplay.innerHTML = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 3l1.5 5.5L19 10l-5.5 1.5L12 17l-1.5-5.5L5 10l5.5-1.5z\"/><path d=\"M19 17l-1 3 3-1\"/><path d=\"M5 17l1 3-3-1\"/></svg> Done!';\n        timerDisplay.classList.remove('running');\n        timerSeconds = 0;\n      }\n    }, 1000);\n  }\n\n  function resetTimer() {\n    stopTimer();\n    timerSeconds = timerMinutes * 60;\n    updateTimerDisplay();\n  }\n\n  timerStart.addEventListener('click', startTimer);\n  timerReset.addEventListener('click', resetTimer);\n\n  presets.forEach(btn => {\n    btn.addEventListener('click', () => {\n      presets.forEach(b => b.classList.remove('active'));\n      btn.classList.add('active');\n      timerMinutes = parseInt(btn.dataset.minutes);\n      resetTimer();\n    });\n  });\n\n  //  INSIGHT GENERATOR \n  const insights = [\n    \"Your attention is the most powerful tool you have to live a good life.\",\n    \"The more demands on your time, the more essential it becomes to choose what you pay attention to.\",\n    \"What you attend to becomes your reality.\",\n    \"When we invest our limited attention intelligently and deliberately, we focus more deeply and think more clearly.\",\n    \"Managing your attention is like choosing what to watch on Netflix — except there are thousands of paths.\",\n    \"We are what we pay attention to. You are what you consume.\",\n    \"The tidier you keep your attentional space, the more clearly you think.\",\n    \"Scatterfocus lets you step back from life and work with greater intention.\",\n    \"Productivity means accomplishing what you intend to — not cramming more into your day.\",\n    \"The best way to deal with distractions is to eliminate them before they tempt you.\",\n    \"Meditation is the most validated technique for expanding your attentional space.\",\n    \"Hyperfocus without scatterfocus leads to burnout. Scatterfocus without hyperfocus leads to chaos.\",\n    \"Leaving some attentional space to spare allows you to reflect on the best approach.\",\n    \"Your brain processes 11 million bits per second. You consciously handle only 40. Choose them wisely.\",\n    \"We spend 47% of our time with a wandering mind. Make that wandering intentional.\",\n    \"Intention is the bouncer of your attentional space.\",\n    \"The smaller the object of attention, the more your mind will wander — but the more you expand your capacity.\",\n    \"Creativity emerges when you connect old ideas in new ways.\",\n  ];\n  const insightText = document.getElementById('insightText');\n  const insightBtn = document.getElementById('insightBtn');\n\n  insightBtn.addEventListener('click', () => {\n    insightText.classList.add('fade');\n    setTimeout(() => {\n      const random = insights[Math.floor(Math.random() * insights.length)];\n      insightText.textContent = random;\n      insightText.classList.remove('fade');\n    }, 300);\n  });\n\n  //  MODE CARDS (click to expand) \n  document.querySelectorAll('.mode-card').forEach(card => {\n    card.addEventListener('click', () => {\n      card.classList.toggle('active');\n    });\n  });\n\n  //  PARTICLES \n  const canvas = document.getElementById('particles');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n\n  function resizeCanvas() {\n    canvas.width = window.innerWidth;\n    canvas.height = document.body.scrollHeight;\n  }\n  resizeCanvas();\n  window.addEventListener('resize', resizeCanvas);\n\n  for (let i = 0; i < 30; i++) {\n    particles.push({\n      x: Math.random() * canvas.width,\n      y: Math.random() * canvas.height,\n      size: Math.random() * 3 + 1,\n      speedX: (Math.random() - 0.5) * 0.3,\n      speedY: (Math.random() - 0.5) * 0.3,\n      opacity: Math.random() * 0.3 + 0.1,\n    });\n  }\n\n  function animateParticles() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => {\n      p.x += p.speedX;\n      p.y += p.speedY;\n      if (p.x < 0 || p.x > canvas.width) p.speedX *= -1;\n      if (p.y < 0 || p.y > canvas.height) p.speedY *= -1;\n      ctx.beginPath();\n      ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);\n      ctx.fillStyle = document.body.classList.contains('dark')\n        ? `rgba(108,92,231,${p.opacity})`\n        : `rgba(108,92,231,${p.opacity * 0.7})`;\n      ctx.fill();\n    });\n    requestAnimationFrame(animateParticles);\n  }\n  animateParticles();\n\n  // Recalc canvas height on scroll\n  window.addEventListener('scroll', resizeCanvas);\n</script>\n\n\n\n</body>\n</html>",
  "mastery": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n\n<canvas id=\"bgCanvas\"></canvas>\n\n<!-- HERO -->\n\n\n<!-- STATS -->\n<section>\n  <div class=\"container\">\n    <div class=\"stats\">\n      <div class=\"stat reveal\"><div class=\"stat-value\">4</div><div class=\"stat-label\">Stages of Mastery</div></div>\n      <div class=\"stat reveal reveal-d1\"><div class=\"stat-value\">12</div><div class=\"stat-label\">Historical Masters</div></div>\n      <div class=\"stat reveal reveal-d2\"><div class=\"stat-value\">7</div><div class=\"stat-label\">Key Principles</div></div>\n      <div class=\"stat reveal reveal-d3\"><div class=\"stat-value\">3</div><div class=\"stat-label\">Phases of Apprenticeship</div></div>\n      <div class=\"stat reveal reveal-d4\"><div class=\"stat-value\">∞</div><div class=\"stat-label\">Lifelong Growth</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- PRINCIPLES OVERVIEW -->\n<section>\n  <div class=\"container\">\n    <div class=\"reveal\">\n      <span class=\"section-label\">Foundation</span>\n      <h2>The Seven Key <span class=\"hl\">Principles</span></h2>\n      <p class=\"section-desc\">Mastery is not a gift, but a process. These principles form the bedrock of Robert Greene's philosophy.</p>\n    </div>\n    <div class=\"principle-flow\">\n      <div class=\"principle reveal reveal-d1\">\n        <div class=\"p-num\">1</div>\n        <h4>Discover Your Calling</h4>\n        <p>Connect with your innate inclinations — your Life's Task.</p>\n      </div>\n      <div class=\"principle reveal reveal-d2\">\n        <div class=\"p-num\">2</div>\n        <h4>Apprenticeship</h4>\n        <p>Deep observation, skill acquisition, and patient practice.</p>\n      </div>\n      <div class=\"principle reveal reveal-d3\">\n        <div class=\"p-num\">3</div>\n        <h4>Social Intelligence</h4>\n        <p>Navigate politics, read people, build strategic relationships.</p>\n      </div>\n      <div class=\"principle reveal reveal-d1\">\n        <div class=\"p-num\">4</div>\n        <h4>Creative-Active</h4>\n        <p>Break rules, experiment, and let your originality emerge.</p>\n      </div>\n      <div class=\"principle reveal reveal-d2\">\n        <div class=\"p-num\">5</div>\n        <h4>Mastery</h4>\n        <p>Combine intuition with skill to reach effortless excellence.</p>\n      </div>\n      <div class=\"principle reveal reveal-d3\">\n        <div class=\"p-num\">6</div>\n        <h4>Elaboration</h4>\n        <p>Refine, teach, and extend your knowledge to new domains.</p>\n      </div>\n      <div class=\"principle reveal reveal-d1\">\n        <div class=\"p-num\">7</div>\n        <h4>Facing Your Shadow</h4>\n        <p>Confront ego, resistance, and the dark side of power.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- THE FOUR STAGES: TIMELINE -->\n<section>\n  <div class=\"container\">\n    <div class=\"reveal\">\n      <span class=\"section-label\">The Journey</span>\n      <h2>The Four Stages of <span class=\"hl\">Mastery</span></h2>\n      <p class=\"section-desc\">Every master walks the same arc. Click each stage to reveal its deeper wisdom.</p>\n    </div>\n    <div class=\"timeline\">\n      <div class=\"tl-item reveal\">\n        <div class=\"tl-content\" onclick=\"toggleTimeline(this)\">\n          <div class=\"tl-num\">I</div>\n          <h3>Apprenticeship</h3>\n          <p>The foundational phase of deep learning, observation, and patient skill-building.</p>\n          <div class=\"tl-expand\">\n            <p style=\"margin-bottom:0.5rem;\">The apprenticeship is divided into three sub-phases:</p>\n            <p style=\"margin-bottom:0.3rem;\"><strong style=\"color:var(--gold);\">Deep Observation</strong> — Watch and absorb without judgment. Understand the rules of your field before attempting to change them.</p>\n            <p style=\"margin-bottom:0.3rem;\"><strong style=\"color:var(--gold);\">Skills Acquisition</strong> — Practice deliberately. Embrace repetition. Quantity leads to quality. The master has failed more times than the beginner has tried.</p>\n            <p><strong style=\"color:var(--gold);\">Experimentation</strong> — Apply what you've learned in novel contexts. Develop your own variants. Move from follower to creator.</p>\n          </div>\n          <span class=\"tl-toggle\">▼ Expand</span>\n        </div>\n        <div class=\"tl-dot\"></div>\n        <div class=\"tl-spacer\"></div>\n      </div>\n\n      <div class=\"tl-item reveal\">\n        <div class=\"tl-content\" onclick=\"toggleTimeline(this)\">\n          <div class=\"tl-num\">II</div>\n          <h3>Creative-Active</h3>\n          <p>Transform accumulated knowledge into original work. Break established patterns.</p>\n          <div class=\"tl-expand\">\n            <p style=\"margin-bottom:0.3rem;\">After years of apprenticeship, you have internalized the rules. Now you begin to break them.</p>\n            <p style=\"margin-bottom:0.3rem;\">This phase is marked by <strong style=\"color:var(--gold);\">creative restlessness</strong> — the need to express your unique voice. You combine ideas from different domains, challenge orthodoxies, and produce work that reflects your authentic self.</p>\n            <p>Embrace the <strong style=\"color:var(--gold);\">open-ended</strong> nature of this phase. Not every experiment will succeed, but each failure is data. The goal is full creative expression.</p>\n          </div>\n          <span class=\"tl-toggle\">▼ Expand</span>\n        </div>\n        <div class=\"tl-dot\"></div>\n        <div class=\"tl-spacer\"></div>\n      </div>\n\n      <div class=\"tl-item reveal\">\n        <div class=\"tl-content\" onclick=\"toggleTimeline(this)\">\n          <div class=\"tl-num\">III</div>\n          <h3>Mastery</h3>\n          <p>Intuition blends with technical skill. You see the whole picture effortlessly.</p>\n          <div class=\"tl-expand\">\n            <p style=\"margin-bottom:0.3rem;\"><strong style=\"color:var(--gold);\">The Master's Mind</strong> — At this stage, you have practiced so deeply that conscious thought becomes unnecessary. Your intuition is now a form of high-speed reasoning.</p>\n            <p style=\"margin-bottom:0.3rem;\">You can <strong style=\"color:var(--gold);\">sense patterns</strong> invisible to others. Problems that baffle experts seem simple. Your work has a fluid, almost effortless quality.</p>\n            <p>This is not the end. Mastery is a <strong style=\"color:var(--gold);\">dynamic state</strong> — you continue to learn, but now from a position of strength rather than weakness.</p>\n          </div>\n          <span class=\"tl-toggle\">▼ Expand</span>\n        </div>\n        <div class=\"tl-dot\"></div>\n        <div class=\"tl-spacer\"></div>\n      </div>\n\n      <div class=\"tl-item reveal\">\n        <div class=\"tl-content\" onclick=\"toggleTimeline(this)\">\n          <div class=\"tl-num\">IV</div>\n          <h3>Elaboration</h3>\n          <p>Refine your craft, teach others, and extend mastery into new territories.</p>\n          <div class=\"tl-expand\">\n            <p style=\"margin-bottom:0.3rem;\"><strong style=\"color:var(--gold);\">The Final Stage</strong> — Having reached mastery, you now face a choice: coast on your reputation, or continue to evolve.</p>\n            <p style=\"margin-bottom:0.3rem;\">Elaboration is about <strong style=\"color:var(--gold);\">deepening</strong> — finding the nuances and subtleties you missed before. You teach what you know, which forces you to organize your thoughts. In teaching, you discover gaps and new questions.</p>\n            <p>You also extend your mastery to <strong style=\"color:var(--gold);\">adjacent fields</strong>, making connections that younger practitioners cannot see. Your work becomes interdisciplinary synthesis.</p>\n          </div>\n          <span class=\"tl-toggle\">▼ Expand</span>\n        </div>\n        <div class=\"tl-dot\"></div>\n        <div class=\"tl-spacer\"></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- KEY CONCEPTS -->\n<section>\n  <div class=\"container\">\n    <div class=\"reveal\">\n      <span class=\"section-label\">Deep Knowledge</span>\n      <h2>Core Concepts of <span class=\"hl\">Mastery</span></h2>\n      <p class=\"section-desc\">The essential ideas that underpin Robert Greene's philosophy of becoming a master.</p>\n    </div>\n    <div class=\"grid grid-3\">\n      <div class=\"concept-card reveal\">\n        <span class=\"c-icon\">🧠</span>\n        <h3>Social Intelligence</h3>\n        <p>The ability to read people, navigate hierarchies, and build strategic relationships is as important as technical skill.</p>\n        <ul>\n          <li>See through people's masks</li>\n          <li>Create win-win dynamics</li>\n          <li>Avoid unnecessary conflict</li>\n          <li>Build a reputation that precedes you</li>\n        </ul>\n      </div>\n      <div class=\"concept-card reveal reveal-d1\">\n        <span class=\"c-icon\">🔍</span>\n        <h3>Life's Task</h3>\n        <p>Your unique calling — the intersection of innate talent and deep fascination. Discovering it is the first step to mastery.</p>\n        <ul>\n          <li>Return to your childhood passions</li>\n          <li>Identify what others find tedious</li>\n          <li>Follow the energy of curiosity</li>\n          <li>Resist societal pressure to conform</li>\n        </ul>\n      </div>\n      <div class=\"concept-card reveal reveal-d2\">\n        <span class=\"c-icon\">⚖</span>\n        <h3>The Apprenticeship Phase</h3>\n        <p>Learning through deep observation, skill acquisition, and experimentation. The most critical phase of the journey.</p>\n        <ul>\n          <li>Move toward challenges</li>\n          <li>Embrace boredom and repetition</li>\n          <li>Trust the process over results</li>\n          <li>Find mentors who challenge you</li>\n        </ul>\n      </div>\n      <div class=\"concept-card reveal\">\n        <span class=\"c-icon\">✨</span>\n        <h3>Creative Strategies</h3>\n        <p>Break established patterns, combine disparate domains, and let your unique perspective emerge through disciplined practice.</p>\n        <ul>\n          <li>Cultivate negative capability</li>\n          <li>Alternate between focus and drift</li>\n          <li>Court serendipity</li>\n          <li>Create constraints to free creativity</li>\n        </ul>\n      </div>\n      <div class=\"concept-card reveal reveal-d1\">\n        <span class=\"c-icon\">🗣</span>\n        <h3>The Mentor Dynamic</h3>\n        <p>The right mentor provides not just knowledge but a living example of mastery in action. Choose your teachers carefully.</p>\n        <ul>\n          <li>Seek out the best in your field</li>\n          <li>Serve before you lead</li>\n          <li>Absorb their way of thinking</li>\n          <li>Eventually surpass them</li>\n        </ul>\n      </div>\n      <div class=\"concept-card reveal reveal-d2\">\n        <span class=\"c-icon\">🎯</span>\n        <h3>High-Level Intuition</h3>\n        <p>After years of practice, your unconscious mind becomes a powerful decision-making engine. Trust your trained instincts.</p>\n        <ul>\n          <li>Recognize pattern recognition</li>\n          <li>Learn to trust your gut (once trained)</li>\n          <li>Balance intuition with analysis</li>\n          <li>Stay open to new information</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- HISTORICAL MASTERS -->\n<section>\n  <div class=\"container\">\n    <div class=\"reveal\">\n      <span class=\"section-label\">The Masters</span>\n      <h2>Historical <span class=\"hl\">Exemplars</span></h2>\n      <p class=\"section-desc\">Greene draws on the lives of history's greatest masters to illustrate the timeless path. Click to explore their wisdom.</p>\n    </div>\n    <div class=\"masters-grid\">\n      <div class=\"master-card reveal\" onclick=\"toggleMaster(this)\">\n        <div class=\"avatar\">🧝</div>\n        <h4>Leonardo da Vinci</h4>\n        <div class=\"era\">1452 – 1519</div>\n        <p>The quintessential Renaissance master, embodiment of insatiable curiosity.</p>\n        <div class=\"master-expand\">\n          <p>Leonardo's apprenticeship under Verrocchio taught him the discipline of observation. He filled thousands of pages with notes and sketches, drawing connections between art, anatomy, engineering, and nature. His mastery came from relentless curiosity and refusing to be boxed into one field.</p>\n        </div>\n        <span class=\"master-toggle\">▼</span>\n      </div>\n      <div class=\"master-card reveal reveal-d1\" onclick=\"toggleMaster(this)\">\n        <div class=\"avatar\">🌱</div>\n        <h4>Charles Darwin</h4>\n        <div class=\"era\">1809 – 1882</div>\n        <p>Revolutionized biology through decades of patient observation.</p>\n        <div class=\"master-expand\">\n          <p>Darwin's five-year voyage on the Beagle was his apprenticeship. He spent 20 years gathering evidence before publishing <em>On the Origin of Species</em>. His mastery came from deep patience, meticulous data collection, and the courage to challenge established dogma.</p>\n        </div>\n        <span class=\"master-toggle\">▼</span>\n      </div>\n      <div class=\"master-card reveal reveal-d2\" onclick=\"toggleMaster(this)\">\n        <div class=\"avatar\">🎨</div>\n        <h4>Michelangelo</h4>\n        <div class=\"era\">1475 – 1564</div>\n        <p>Sculptor, painter, architect — a master of multiple arts.</p>\n        <div class=\"master-expand\">\n          <p>Michelangelo apprenticed under Ghirlandaio but surpassed his master through obsessive self-directed study. He dissected cadavers to understand anatomy, worked alone for years on the Sistine Chapel, and treated every commission as an opportunity to push the boundaries of his craft.</p>\n        </div>\n        <span class=\"master-toggle\">▼</span>\n      </div>\n      <div class=\"master-card reveal reveal-d3\" onclick=\"toggleMaster(this)\">\n        <div class=\"avatar\">📖</div>\n        <h4>Johann Wolfgang von Goethe</h4>\n        <div class=\"era\">1749 – 1832</div>\n        <p>Poet, scientist, philosopher — a master of the inner life.</p>\n        <div class=\"master-expand\">\n          <p>Goethe's apprenticeship was one of wide-ranging study: law, alchemy, art, literature. He refused specialization, believing that mastery requires engaging with the whole of human experience. His work on color theory and his epic <em>Faust</em> represent the elaboration phase of a long life.</p>\n        </div>\n        <span class=\"master-toggle\">▼</span>\n      </div>\n      <div class=\"master-card reveal\" onclick=\"toggleMaster(this)\">\n        <div class=\"avatar\">⚗</div>\n        <h4>Albert Einstein</h4>\n        <div class=\"era\">1879 – 1955</div>\n        <p>Reimagined the universe through thought experiments and persistence.</p>\n        <div class=\"master-expand\">\n          <p>Einstein's apprenticeship was solitary — he worked in a patent office while developing his theories. His mastery came from the ability to hold seemingly contradictory ideas in tension, to visualize problems physically, and to persist for a decade on general relativity while his peers dismissed him.</p>\n        </div>\n        <span class=\"master-toggle\">▼</span>\n      </div>\n      <div class=\"master-card reveal reveal-d2\" onclick=\"toggleMaster(this)\">\n        <div class=\"avatar\">🎵</div>\n        <h4>Martha Graham</h4>\n        <div class=\"era\">1894 – 1991</div>\n        <p>Revolutionized modern dance through raw emotional expression.</p>\n        <div class=\"master-expand\">\n          <p>Graham's apprenticeship at Denishawn taught her technique, but her creative-active phase broke every rule. She developed a completely new dance vocabulary based on contraction and release. Her mastery was built on decades of daily practice and an unshakable commitment to her artistic vision.</p>\n        </div>\n        <span class=\"master-toggle\">▼</span>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- YOUR PATH ASSESSMENT -->\n<section>\n  <div class=\"container\">\n    <div class=\"reveal\">\n      <span class=\"section-label\">Your Journey</span>\n      <h2>The Path <span class=\"hl\">Assessment</span></h2>\n      <p class=\"section-desc\">Reflect on where you are in your own mastery journey. Answer honestly to discover your current stage and what comes next.</p>\n    </div>\n    <div class=\"assessment reveal\" id=\"assessment\">\n      <h3>🎯 Your Mastery Stage</h3>\n      <p class=\"assess-desc\">Select the option that best describes you for each question.</p>\n\n      <div class=\"assess-question\">\n        <label>1. Your approach to learning <small>(choose closest)</small></label>\n        <div class=\"assess-options\" data-q=\"0\">\n          <button onclick=\"selectAssess(this,0)\">Seeking teachers &amp; mentors</button>\n          <button onclick=\"selectAssess(this,1)\">Practicing skills deliberately</button>\n          <button onclick=\"selectAssess(this,2)\">Creating original work</button>\n          <button onclick=\"selectAssess(this,3)\">Teaching &amp; refining</button>\n        </div>\n      </div>\n      <div class=\"assess-question\">\n        <label>2. Your relationship with rules <small>(choose closest)</small></label>\n        <div class=\"assess-options\" data-q=\"1\">\n          <button onclick=\"selectAssess(this,0)\">Learning established rules</button>\n          <button onclick=\"selectAssess(this,1)\">Applying rules with consistency</button>\n          <button onclick=\"selectAssess(this,2)\">Breaking &amp; rewriting rules</button>\n          <button onclick=\"selectAssess(this,3)\">Synthesizing across fields</button>\n        </div>\n      </div>\n      <div class=\"assess-question\">\n        <label>3. Your creative output <small>(choose closest)</small></label>\n        <div class=\"assess-options\" data-q=\"2\">\n          <button onclick=\"selectAssess(this,0)\">Still building foundation</button>\n          <button onclick=\"selectAssess(this,1)\">Competent but not original</button>\n          <button onclick=\"selectAssess(this,2)\">Producing consistent original work</button>\n          <button onclick=\"selectAssess(this,3)\">Connecting deep ideas</button>\n        </div>\n      </div>\n\n      <div class=\"assess-result\" id=\"assessResult\">\n        <h4 id=\"assessStageTitle\"></h4>\n        <p id=\"assessStageDesc\"></p>\n        <div class=\"stage-badge\" id=\"assessStageBadge\"></div>\n      </div>\n      <br>\n      <button class=\"assess-reset\" onclick=\"resetAssessment()\">↺ Reset</button>\n    </div>\n  </div>\n</section>\n\n<!-- QUOTES -->\n<section class=\"quote-section\">\n  <div class=\"container\">\n    <div class=\"reveal\">\n      <span class=\"section-label\">Wisdom</span>\n      <h2>Words from the <span class=\"hl\">Master</span></h2>\n      <p class=\"section-desc\" style=\"margin:0 auto 3rem;\">The defining ideas that cut to the heart of the mastery philosophy.</p>\n    </div>\n    <div class=\"quote-grid\">\n      <div class=\"quote-card reveal\">\n        <div class=\"q-mark\">“</div>\n        <blockquote>The future belongs to those who learn more skills and combine them in creative ways.</blockquote>\n        <cite>— Robert Greene</cite>\n      </div>\n      <div class=\"quote-card reveal reveal-d1\">\n        <div class=\"q-mark\">“</div>\n        <blockquote>In the apprenticeship phase, you are not merely learning skills. You are learning how to learn.</blockquote>\n        <cite>— Robert Greene</cite>\n      </div>\n      <div class=\"quote-card reveal reveal-d2\">\n        <div class=\"q-mark\">“</div>\n        <blockquote>The greatest mistake you can make in life is to be continually fearing you will make one.</blockquote>\n        <cite>— Robert Greene</cite>\n      </div>\n      <div class=\"quote-card reveal\">\n        <div class=\"q-mark\">“</div>\n        <blockquote>Mastery is not a function of genius or talent. It is a function of time and intense focus applied to a particular field.</blockquote>\n        <cite>— Robert Greene</cite>\n      </div>\n      <div class=\"quote-card reveal reveal-d1\">\n        <div class=\"q-mark\">“</div>\n        <blockquote>In the end, the ability to learn faster than your competitors may be the only sustainable competitive advantage.</blockquote>\n        <cite>— Robert Greene</cite>\n      </div>\n      <div class=\"quote-card reveal reveal-d2\">\n        <div class=\"q-mark\">“</div>\n        <blockquote>The key to power is to be able to see people as they are, not as you want them to be.</blockquote>\n        <cite>— Robert Greene</cite>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- FOOTER -->\n\n\n<script>\n  //  CANVAS BG \n  const canvas = document.getElementById('bgCanvas'), ctx = canvas.getContext('2d');\n  let particles = [];\n  function resize() { canvas.width = window.innerWidth; canvas.height = window.innerHeight; }\n  resize(); window.addEventListener('resize', resize);\n\n  class Particle {\n    constructor() { this.reset(); }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.vx = (Math.random() - 0.5) * 0.25;\n      this.vy = (Math.random() - 0.5) * 0.25;\n      this.r = Math.random() * 2 + 0.5;\n      this.a = Math.random() * 0.4 + 0.1;\n    }\n    update() {\n      this.x += this.vx; this.y += this.vy;\n      if (this.x < 0 || this.x > canvas.width) this.vx *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.vy *= -1;\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);\n      const isDark = document.body.classList.contains('dark');\n      ctx.fillStyle = isDark ? `rgba(201,168,76,${this.a})` : `rgba(45,27,105,${this.a})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 70; i++) particles.push(new Particle());\n\n  function animate() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n    const isDark = document.body.classList.contains('dark');\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const d = Math.sqrt(dx * dx + dy * dy);\n        if (d < 140) {\n          ctx.beginPath();\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          const color = isDark ? '201,168,76' : '45,27,105';\n          ctx.strokeStyle = `rgba(${color},${0.06 * (1 - d / 140)})`;\n          ctx.stroke();\n        }\n      }\n    }\n    requestAnimationFrame(animate);\n  }\n  animate();\n\n  //  THEME \n  const themeToggle = document.getElementById('themeToggle');\n  themeToggle.addEventListener('click', () => {\n    document.body.classList.toggle('dark');\n    themeToggle.textContent = document.body.classList.contains('dark') ? '\\u2600' : '\\u263E';\n  });\n\n  //  SCROLL REVEAL \n  const observer = new IntersectionObserver((entries) => {\n    entries.forEach(e => {\n      if (e.isIntersecting) {\n        e.target.classList.add('visible');\n        observer.unobserve(e.target);\n      }\n    });\n  }, { threshold: 0.08 });\n\n  document.querySelectorAll('.reveal, .tl-item').forEach(el => observer.observe(el));\n\n  //  TIMELINE TOGGLE \n  function toggleTimeline(el) {\n    el.classList.toggle('open');\n  }\n\n  //  MASTER TOGGLE \n  function toggleMaster(el) {\n    el.classList.toggle('open');\n  }\n\n  //  SELF ASSESSMENT \n  const stageInfo = [\n    {\n      title: 'Apprenticeship',\n      badge: 'Phase I: Learning',\n      desc: 'You are in the foundational phase. Your focus should be on finding mentors, observing deeply, and building skills through deliberate practice. Embrace repetition and don\\u2019t rush for originality. The best masters spend years in apprenticeship before creating anything new.'\n    },\n    {\n      title: 'Creative-Active',\n      badge: 'Phase II: Creation',\n      desc: 'You have built a solid foundation and are now developing your unique voice. Start breaking established rules, combining ideas from different fields, and producing original work. Not everything will succeed \\u2014 that\\u2019s part of the process. Trust your accumulated knowledge.'\n    },\n    {\n      title: 'Mastery',\n      badge: 'Phase III: Mastery',\n      desc: 'Your skills have become second nature. You see patterns others miss and work with fluid intuition. Continue to challenge yourself, seek harder problems, and remain a student. Mastery is not a destination but a dynamic state of continuous growth.'\n    },\n    {\n      title: 'Elaboration',\n      badge: 'Phase IV: Teaching',\n      desc: 'You have reached a level where you can teach, mentor, and extend your knowledge to new domains. Your work now involves synthesis across fields and deepening existing insights. Focus on legacy, teaching others, and exploring adjacent territories.'\n    }\n  ];\n\n  let assessAnswers = [];\n  const assessResult = document.getElementById('assessResult');\n\n  function selectAssess(btn, val) {\n    const parent = btn.parentElement;\n    parent.querySelectorAll('button').forEach(b => b.classList.remove('selected'));\n    btn.classList.add('selected');\n    const qIdx = parseInt(parent.dataset.q);\n    assessAnswers[qIdx] = val;\n    if (assessAnswers.length >= 3 && assessAnswers[0] !== undefined && assessAnswers[1] !== undefined && assessAnswers[2] !== undefined) {\n      updateAssessment();\n    }\n  }\n\n  function updateAssessment() {\n    const avg = Math.round(assessAnswers.reduce((a, b) => a + b, 0) / assessAnswers.length);\n    const stage = stageInfo[avg];\n    document.getElementById('assessStageTitle').textContent = '\\u2192 ' + stage.title;\n    document.getElementById('assessStageDesc').textContent = stage.desc;\n    document.getElementById('assessStageBadge').textContent = stage.badge;\n    assessResult.classList.add('show');\n    assessResult.scrollIntoView({ behavior: 'smooth', block: 'nearest' });\n  }\n\n  function resetAssessment() {\n    assessAnswers = [];\n    document.querySelectorAll('.assess-options button').forEach(b => b.classList.remove('selected'));\n    assessResult.classList.remove('show');\n  }\n</script>\n\n\n\n</body>\n</html>",
  "money-unlocked": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n<div id=\"progress\"></div>\n<canvas id=\"bgCanvas\"></canvas>\n\n\n\n\n<section id=\"thesis\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Core Philosophy</span>\n    <h2 class=\"section-title\">What Is Real Wealth?</h2>\n    <p class=\"section-desc\">Real wealth isn't measured in dollars. It's measured in joy, contribution, and time. Money is a byproduct, not the goal.</p></div>\n    <div class=\"wealth-grid\">\n      <div class=\"wealth-card reveal\" onclick=\"toggleCard(this)\">\n        <div class=\"icon\">✨</div>\n        <h3>Joy</h3>\n        <p>Doing what you love, on your own terms, waking up excited every day.</p>\n        <div class=\"expanded\"><p>Most people chase money thinking it'll bring happiness. But wealth starts with alignment between purpose and daily life. When you do what you love, money follows.</p></div>\n        <span class=\"toggle\">Click to expand ▼</span>\n      </div>\n      <div class=\"wealth-card reveal reveal-delay-1\" onclick=\"toggleCard(this)\">\n        <div class=\"icon\">🌍</div>\n        <h3>Contribution</h3>\n        <p>Making a real impact. Creating value for others and leaving a positive legacy.</p>\n        <div class=\"expanded\"><p>The ultra-rich understand that giving back doesn't make you poorer -- it makes you magnetic. Generosity creates trust, and trust builds brands.</p></div>\n        <span class=\"toggle\">Click to expand ▼</span>\n      </div>\n      <div class=\"wealth-card reveal reveal-delay-2\" onclick=\"toggleCard(this)\">\n        <div class=\"icon\">⏳</div>\n        <h3>Time</h3>\n        <p>Freedom to do what you want, when you want, with whoever you want.</p>\n        <div class=\"expanded\"><p>When people say \"I want more money,\" they usually mean they want freedom. Time is the ultimate currency -- you can't earn more of it. Spend it wisely.</p></div>\n        <span class=\"toggle\">Click to expand ▼</span>\n      </div>\n    </div>\n    <div class=\"formula-box reveal\">\n      <div class=\"formula\">Wealth = Fulfillment + Freedom + Impact</div>\n      <div class=\"formula-label\">Money is the tool, not the destination</div>\n    </div>\n    <div class=\"comparison reveal\">\n      <div class=\"comp-side smart\">\n        <h4>📈 Smart Work</h4>\n        <ul><li>Build systems that earn independently</li><li>Make money work for you</li><li>Leverage other people's money</li><li>Passive income streams</li><li>Strategic partnerships</li></ul>\n      </div>\n      <div class=\"comp-side hard\">\n        <h4>🔨 Hard Work Alone</h4>\n        <ul><li>Trade time for money</li><li>Work for someone else's dream</li><li>Linear income only</li><li>No scalability</li><li>Exhaustion with minimal results</li></ul>\n      </div>\n    </div>\n  </div>\n</section>\n\n<div class=\"part-divider\"><div class=\"line\"></div><h2>The 13-Chapter Roadmap</h2><p>From mindset shifts to wealth-building strategies</p></div>\n\n<section id=\"chapters\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Chapters 1-4</span>\n    <h2 class=\"section-title\">Foundation</h2></div>\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">01</div><div><h3>Wealth Redefined</h3><p style=\"color:var(--muted);font-size:.85rem\">Exposing the Biggest Lie You've Ever Been Told</p></div></div>\n      <div class=\"rule-body\">\n        <p>Most people are conditioned: go to school, get a job, climb the ladder, retire -- trading their best years building someone else's dream.</p>\n        <ul>\n          <li>Wealth is a feeling of abundance and well-being</li>\n          <li>It's alignment between purpose, joy, and impact</li>\n          <li>The real flex isn't a Ferrari -- it's freedom to choose</li>\n          <li>Build wealth from the inside out, starting with your values</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">02</div><div><h3>Smart Work vs. Hard Work</h3><p style=\"color:var(--muted);font-size:.85rem\">The animator who escaped the Tube</p></div></div>\n      <div class=\"rule-body\">\n        <p>\"Give me six hours to chop down a tree and I will spend the first four sharpening the axe.\" -- Abraham Lincoln</p>\n        <p>John worked three jobs, went to university, became an animator in London -- and had even less freedom. 3-hour commutes, no vacation, a supervisor threatening his job. Rock bottom: smelling like rotten anchovies in a packed Tube.</p>\n        <ul>\n          <li>Hard work alone won't make you rich</li>\n          <li>Shift from trading hours for dollars to building systems</li>\n          <li>Make money work hard for you, not the other way around</li>\n          <li>Education is the axe -- sharpen it before you chop</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">03</div><div><h3>Active to Passive Income</h3><p style=\"color:var(--muted);font-size:.85rem\">How to Make Money While You Sleep</p></div></div>\n      <div class=\"rule-body\">\n        <p>\"If you work for money, you give the power to your employer. If money works for you, you keep the power.\" -- Robert Kiyosaki</p>\n        <p>John started with real estate. Couldn't afford to buy property, so he learned to use Other People's Money (OPM). Found a mentor by investing £10,000 (sold his Honda S2000). Six months later: 35 houses. First million by year's end.</p>\n        <ul>\n          <li>Educate yourself relentlessly -- books, seminars, mentors</li>\n          <li>Find someone with success and model them exactly</li>\n          <li>Put skin in the game -- invest in knowledge</li>\n          <li>Start before you feel ready</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">04</div><div><h3>Turning Ideas into Dollars</h3><p style=\"color:var(--muted);font-size:.85rem\">The Stanley Cup case study</p></div></div>\n      <div class=\"rule-body\">\n        <p>The Stanley cup went from $70M to $750M in revenue because influencers promoted it through affiliate marketing -- without creating the product.</p>\n        <ul>\n          <li>Affiliate marketing: promote existing products, earn commissions</li>\n          <li>No inventory, no shipping, no product creation needed</li>\n          <li>Start with zero money</li>\n          <li>Digital products, licensing, audience monetization</li>\n          <li>The math: $100 product at 4% = $4/sale. Sell 250 = $1,000/month</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"reveal\" style=\"margin-top:3rem\"><span class=\"section-label\">Chapters 5-8</span>\n    <h2 class=\"section-title\">Strategy</h2></div>\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">05</div><div><h3>Becoming Indestructible</h3><p style=\"color:var(--muted);font-size:.85rem\">Economic Resilience</p></div></div>\n      <div class=\"rule-body\">\n        <p>The Chinese word for crisis -- weiji -- combines \"danger\" and \"opportunity.\" Every crisis is a turning point.</p>\n        <ul>\n          <li>Build multiple revenue streams so one disruption doesn't ruin you</li>\n          <li>Use leverage: other people's money, networks, technology</li>\n          <li>Protect what you've built: insurance, liquidity buffers</li>\n          <li>Automate with technology and systems</li>\n          <li>A one-page financial plan is not enough -- build an ecosystem</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">06</div><div><h3>Financial Freedom Unlocked</h3><p style=\"color:var(--muted);font-size:.85rem\">Building Your Money Ecosystem</p></div></div>\n      <div class=\"rule-body\">\n        <p>\"Spending money to show people how much money you have is the fastest way to have less money.\" -- Morgan Housel</p>\n        <p>The \"rich broke\" trap: people making $500K+ who are still broke because they spend everything on liabilities. Every dollar is a vote for the life you want.</p>\n        <ul>\n          <li>Financial freedom = RETENTION + GROWTH, not accumulation</li>\n          <li>What matters isn't how much you make -- it's how much you KEEP</li>\n          <li>Understand spending psychology: buying identity, validation</li>\n          <li>Don't fall for the luxury trap -- it's a treadmill</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">07</div><div><h3>The Power of Minimalism</h3><p style=\"color:var(--muted);font-size:.85rem\">Less is More</p></div></div>\n      <div class=\"rule-body\">\n        <p>After making his first million, John bought luxury cars, watches, and clothes. People were impressed -- but he wasn't. He was rich but not yet wealthy.</p>\n        <ul>\n          <li>Hidden costs: purchase price, storage, maintenance, insurance, mental load</li>\n          <li>Humans make 35,000+ decisions/day. More clutter = poorer decisions</li>\n          <li>Luxury items that don't align with values become money suckers</li>\n          <li>Minimalism isn't deprivation -- it's intentionality</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">08</div><div><h3>Wealth Mapping</h3><p style=\"color:var(--muted);font-size:.85rem\">Clear Visions, Strategic Actions</p></div></div>\n      <div class=\"rule-body\">\n        <p>\"BMW\" can stand for Bitches, Moaners, and Whiners. Instead of complaining, ask: \"What can I do about this?\"</p>\n        <ul>\n          <li>BLURRY GOALS = BLURRY ACTIONS</li>\n          <li>CLEAR DIRECTION = POWER AND MOMENTUM</li>\n          <li>Set your \"Freedom Number\" -- a specific, measurable financial goal</li>\n          <li>\"I want more money\" is not a goal -- it's a chasing loop</li>\n          <li>John's students went from debt to seven figures -- through clarity, not harder work</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"reveal\" style=\"margin-top:3rem\"><span class=\"section-label\">Chapters 9-13</span>\n    <h2 class=\"section-title\">Amplification</h2></div>\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">09</div><div><h3>Investing in Yourself</h3><p style=\"color:var(--muted);font-size:.85rem\">The £10,000 mentor that unlocked millions</p></div></div>\n      <div class=\"rule-body\">\n        <p>\"Your relationship with money is a reflection of your inner self.\" -- Ken Honda</p>\n        <p>John paid £10,000 (sold his car) for two days with a mentor. Six months later: 35 houses, first million. The quality of your questions determines the quality of your answers.</p>\n        <ul>\n          <li>Don't ask \"How do I become a millionaire?\" Ask \"Who do I need to become?\"</li>\n          <li>Instead of \"I can't afford it,\" ask \"How can I afford it?\"</li>\n          <li>Free advice is rarely followed. Paid knowledge = skin in the game</li>\n          <li>The right mentor can deliver 100x ROI</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">10</div><div><h3>Network = Net Worth</h3><p style=\"color:var(--muted);font-size:.85rem\">Building the right connections</p></div></div>\n      <div class=\"rule-body\">\n        <p>John used student loan money to attend a 3D animation festival in Copenhagen. Approached 10-20 speakers. One said yes -- led to internship at Passion Pictures (Gorillaz studio), then headhunted before graduation.</p>\n        <ul>\n          <li>Start where you are. Add value first -- make coffee, run errands</li>\n          <li>Be first in, last out. Learn quietly. Be intentional</li>\n          <li>Focus on relationships, not transactions</li>\n          <li>Follow up and maintain connections</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">11</div><div><h3>Scaling: Think Bigger</h3><p style=\"color:var(--muted);font-size:.85rem\">From rich thinking to wealthy thinking</p></div></div>\n      <div class=\"rule-body\">\n        <p>John watched Lamborghini videos daily for two years. Drove a friend's Gallardo, made a promise, bought one a year later. But that was still limited -- RICH thinking, not WEALTHY thinking.</p>\n        <ul>\n          <li>When you have purpose, action is automatic. No willpower needed</li>\n          <li>Focus attention on what you want, think about it constantly</li>\n          <li>Cars and houses are byproducts of chasing impact, not the goal</li>\n          <li>Scale beyond personal luxury to legacy and impact</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">12</div><div><h3>Secret of the Ultra-Rich</h3><p style=\"color:var(--muted);font-size:.85rem\">The $100 banana story</p></div></div>\n      <div class=\"rule-body\">\n        <p>John met a fruit vendor giving his all at the end of the day. Handed him $100 for a single banana. The vendor's face lit up, drew a crowd. John created a moment of validation.</p>\n        <ul>\n          <li>Giving back doesn't make you poorer -- it makes you MAGNETIC</li>\n          <li>Generosity creates trust. Trust builds brands</li>\n          <li>The ultra-rich understand: giving amplifies wealth</li>\n          <li>Give value to customers, insights to clients, support to community</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">13</div><div><h3>Roadmap to Limitless Wealth</h3><p style=\"color:var(--muted);font-size:.85rem\">Your Roadmap to Limitless Wealth</p></div></div>\n      <div class=\"rule-body\">\n        <p>At 40, you have roughly 245,280 waking hours left. Time isn't just valuable -- it's everything. Every hour shapes your legacy and joy.</p>\n        <ul>\n          <li>Two versions of you: Little You (fear, doubt) vs Big You (vision, courage)</li>\n          <li>Transform by clearing inner roadblocks -- patterns, beliefs, fears</li>\n          <li>It's not really about money -- it's about self-expression</li>\n          <li>Money is a tool. When it works for you, that's freedom</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n  </div>\n</section>\n\n<div class=\"part-divider\"><div class=\"line\"></div><h2>Build Your Financial Ecosystem</h2><p>Four layers of economic resilience</p></div>\n\n<section id=\"layers\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">The 4 Layers</span>\n    <h2 class=\"section-title\">Your Financial Ecosystem</h2>\n    <p class=\"section-desc\">A one-page financial plan isn't enough. Build like the Burj Khalifa, not a Lego house.</p></div>\n    <div class=\"layers-grid\">\n      <div class=\"layer-card reveal\" onclick=\"toggleLayer(this)\">\n        <div class=\"layer-num\">1</div>\n        <div class=\"l-icon\">🏗</div>\n        <h4>Passive Infrastructure</h4>\n        <p>Multiple revenue streams so one disruption doesn't ruin you</p>\n        <div class=\"layer-detail\"><p>When the pandemic hit, John had income beyond speaking because he'd diversified. Don't put all eggs in one basket.</p></div>\n        <div class=\"click-hint\">tap for details</div>\n      </div>\n      <div class=\"layer-card reveal reveal-delay-1\" onclick=\"toggleLayer(this)\">\n        <div class=\"layer-num\">2</div>\n        <div class=\"l-icon\">⚡</div>\n        <h4>Leverage</h4>\n        <p>Other people's money, networks, and technology to amplify results</p>\n        <div class=\"layer-detail\"><p>Don't grow linearly -- grow exponentially. Use OPM, partnerships, and systems to multiply your efforts.</p></div>\n        <div class=\"click-hint\">tap for details</div>\n      </div>\n      <div class=\"layer-card reveal reveal-delay-2\" onclick=\"toggleLayer(this)\">\n        <div class=\"layer-num\">3</div>\n        <div class=\"l-icon\">🛡</div>\n        <h4>Insurance</h4>\n        <p>Protect what you've built with buffers and coverage</p>\n        <div class=\"layer-detail\"><p>Liquidity buffers, proper coverage, risk management. The wealthy are prepared because they know crises are inevitable.</p></div>\n        <div class=\"click-hint\">tap for details</div>\n      </div>\n      <div class=\"layer-card reveal reveal-delay-3\" onclick=\"toggleLayer(this)\">\n        <div class=\"layer-num\">4</div>\n        <div class=\"l-icon\">🤖</div>\n        <h4>Technology &amp; Systems</h4>\n        <p>Automate processes, build systems that run without you</p>\n        <div class=\"layer-detail\"><p>Technology is the ultimate multiplier. Create systems that generate value while you sleep.</p></div>\n        <div class=\"click-hint\">tap for details</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- Little You vs Big You -->\n<section>\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Mindset</span>\n    <h2 class=\"section-title\">Two Versions of You</h2>\n    <p class=\"section-desc\">Every moment, you choose between them.</p></div>\n    <div class=\"two-versions reveal\">\n      <div class=\"version little\">\n        <h4>🔻 Little You</h4>\n        <ul><li>Ruled by fear and doubt</li><li>Weight of the past holds you back</li><li>Blurry goals, blurry actions</li><li>Complains without acting</li><li>Chases money without purpose</li><li>Trades time for dollars</li></ul>\n      </div>\n      <div class=\"version big\">\n        <h4>🔝 Big You</h4>\n        <ul><li>Leads with vision and courage</li><li>Clear direction, powerful momentum</li><li>Asks \"What can I do about this?\"</li><li>Builds systems, not just income</li><li>Invests in self and relationships</li><li>Gives back, creates impact</li></ul>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- Freedom Number Calculator -->\n<section id=\"freedom\" class=\"freedom-calc\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Action</span>\n    <h2 class=\"section-title\">Find Your Freedom Number</h2>\n    <p class=\"section-desc\" style=\"margin:0 auto 2rem\">Blurry goals = blurry actions. Get specific. Calculate the monthly passive income you need to live freely.</p></div>\n    <div class=\"calc-box reveal\">\n      <label>Monthly living expenses ($)</label>\n      <input type=\"number\" id=\"expenses\" placeholder=\"e.g. 3000\" oninput=\"calcFreedom()\">\n      <label>Desired savings rate (%)</label>\n      <input type=\"number\" id=\"savings\" placeholder=\"e.g. 20\" oninput=\"calcFreedom()\">\n      <label>Expected annual return (%)</label>\n      <input type=\"number\" id=\"return\" placeholder=\"e.g. 8\" value=\"8\" oninput=\"calcFreedom()\">\n      <div class=\"calc-result\" id=\"freedomResult\">--</div>\n      <div class=\"calc-result-label\">Target portfolio to generate your freedom income</div>\n    </div>\n  </div>\n</section>\n\n<!-- Focus Timer -->\n<section id=\"timer\" class=\"timer-section\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Practice</span>\n    <h2 class=\"section-title\">Deep Work Timer</h2>\n    <p class=\"section-desc\" style=\"margin:0 auto 2rem\">Smart work requires focused sessions. Lock in and build your systems.</p></div>\n    <div class=\"reveal\">\n      <div class=\"timer-modes\">\n        <button class=\"timer-mode active\" onclick=\"setTimer(25,this)\">25 min</button>\n        <button class=\"timer-mode\" onclick=\"setTimer(50,this)\">50 min</button>\n        <button class=\"timer-mode\" onclick=\"setTimer(90,this)\">90 min</button>\n        <button class=\"timer-mode\" onclick=\"setTimer(120,this)\">2 hrs</button>\n      </div>\n      <div class=\"timer-ring\">\n        <svg width=\"300\" height=\"300\"><circle class=\"bg\" cx=\"150\" cy=\"150\" r=\"140\"></circle><circle class=\"progress\" id=\"ringProgress\" cx=\"150\" cy=\"150\" r=\"140\" stroke-dasharray=\"879.6\" stroke-dashoffset=\"0\"></circle></svg>\n        <div class=\"timer-display\" id=\"timerDisplay\" style=\"position:absolute;top:50%;left:50%;transform:translate(-50%,-50%)\">25:00</div>\n      </div>\n      <div class=\"timer-controls\">\n        <button class=\"timer-btn\" id=\"startBtn\" onclick=\"toggleTimer()\">Start</button>\n        <button class=\"timer-btn reset\" onclick=\"resetTimer()\">Reset</button>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- Takeaways -->\n<section id=\"takeaways\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Remember</span>\n    <h2 class=\"section-title\">Key Takeaways</h2></div>\n    <div class=\"takeaway-grid\">\n      <div class=\"takeaway reveal\"><div class=\"num\">1</div><p>Wealth is <strong style=\"color:var(--text)\">not money</strong> -- it's joy, contribution, time, and freedom.</p></div>\n      <div class=\"takeaway reveal reveal-delay-1\"><div class=\"num\">2</div><p><strong style=\"color:var(--text)\">Smart &gt; Hard</strong> work. Build systems that earn while you sleep.</p></div>\n      <div class=\"takeaway reveal reveal-delay-1\"><div class=\"num\">3</div><p><strong style=\"color:var(--text)\">Passive income</strong> is the key: real estate, affiliate marketing, digital products.</p></div>\n      <div class=\"takeaway reveal reveal-delay-2\"><div class=\"num\">4</div><p>Build a <strong style=\"color:var(--text)\">financial ecosystem</strong> -- not a one-page plan. Four layers of protection.</p></div>\n      <div class=\"takeaway reveal reveal-delay-2\"><div class=\"num\">5</div><p><strong style=\"color:var(--text)\">Retain and grow</strong>, don't just spend. Every dollar is a vote for your future.</p></div>\n      <div class=\"takeaway reveal reveal-delay-3\"><div class=\"num\">6</div><p><strong style=\"color:var(--text)\">Minimalism</strong> frees capital. Clutter costs money and mental energy.</p></div>\n      <div class=\"takeaway reveal reveal-delay-3\"><div class=\"num\">7</div><p>Set <strong style=\"color:var(--text)\">specific goals</strong>. Your Freedom Number. Blurry goals = blurry actions.</p></div>\n      <div class=\"takeaway reveal\"><div class=\"num\">8</div><p><strong style=\"color:var(--text)\">Invest in yourself</strong> -- the highest ROI comes from mentors and education.</p></div>\n      <div class=\"takeaway reveal reveal-delay-1\"><div class=\"num\">9</div><p>Your <strong style=\"color:var(--text)\">network = net worth</strong>. Build relationships. Add value first.</p></div>\n      <div class=\"takeaway reveal reveal-delay-1\"><div class=\"num\">10</div><p><strong style=\"color:var(--text)\">Give back</strong> -- generosity makes you magnetic. Trust builds empires.</p></div>\n      <div class=\"takeaway reveal reveal-delay-2\"><div class=\"num\">11</div><p>Choose <strong style=\"color:var(--text)\">Big You</strong> over Little You, every single moment.</p></div>\n      <div class=\"takeaway reveal reveal-delay-2\"><div class=\"num\">12</div><p><strong style=\"color:var(--text)\">Time is everything</strong>. You have limited hours. Spend them with intention.</p></div>\n    </div>\n  </div>\n</section>\n\n\n\n<script>\nconst canvas=document.getElementById('bgCanvas'),ctx=canvas.getContext('2d');\nlet particles=[];\nfunction resize(){canvas.width=window.innerWidth;canvas.height=window.innerHeight}\nresize();window.addEventListener('resize',resize);\nclass Particle{constructor(){this.reset()}reset(){this.x=Math.random()*canvas.width;this.y=Math.random()*canvas.height;this.vx=(Math.random()-.5)*.3;this.vy=(Math.random()-.5)*.3;this.r=Math.random()*2+.5;this.a=Math.random()*.5+.1}update(){this.x+=this.vx;this.y+=this.vy;if(this.x<0||this.x>canvas.width)this.vx*=-1;if(this.y<0||this.y>canvas.height)this.vy*=-1}draw(){ctx.beginPath();ctx.arc(this.x,this.y,this.r,0,Math.PI*2);ctx.fillStyle=`rgba(0,229,160,${this.a})`;ctx.fill()}}\nfor(let i=0;i<80;i++)particles.push(new Particle());\nfunction animate(){ctx.clearRect(0,0,canvas.width,canvas.height);particles.forEach(p=>{p.update();p.draw()});for(let i=0;i<particles.length;i++)for(let j=i+1;j<particles.length;j++){const dx=particles[i].x-particles[j].x,dy=particles[i].y-particles[j].y,d=Math.sqrt(dx*dx+dy*dy);if(d<120){ctx.beginPath();ctx.moveTo(particles[i].x,particles[i].y);ctx.lineTo(particles[j].x,particles[j].y);ctx.strokeStyle=`rgba(0,229,160,${.08*(1-d/120)})`;ctx.stroke()}}requestAnimationFrame(animate)}animate();\n\nwindow.addEventListener('scroll',()=>{const s=window.scrollY/(document.body.scrollHeight-window.innerHeight)*100;document.getElementById('progress').style.width=s+'%';document.getElementById('nav').classList.toggle('visible',window.scrollY>300)});\n\nconst observer=new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}})},{threshold:.1});\ndocument.querySelectorAll('.reveal').forEach(el=>observer.observe(el));\n\nfunction toggleCard(el){el.classList.toggle('open')}\nfunction toggleRule(el){el.classList.toggle('open')}\nfunction toggleLayer(el){el.classList.toggle('open')}\n\nfunction calcFreedom(){\n  const exp=parseFloat(document.getElementById('expenses').value)||0;\n  const sav=parseFloat(document.getElementById('savings').value)||0;\n  const ret=parseFloat(document.getElementById('return').value)||0;\n  if(exp>0&&sav>=0&&ret>0){\n    const monthlyNeeded=exp*(1+sav/100);\n    const annualNeeded=monthlyNeeded*12;\n    const target=annualNeeded/(ret/100);\n    document.getElementById('freedomResult').textContent='$'+target.toLocaleString(undefined,{maximumFractionDigits:0});\n  }else{\n    document.getElementById('freedomResult').textContent='--';\n  }\n}\n\nlet timerDuration=25*60,timerRemaining=25*60,timerInterval=null,timerRunning=false;\nconst circumference=2*Math.PI*140;\nfunction setTimer(min,btn){document.querySelectorAll('.timer-mode').forEach(b=>b.classList.remove('active'));btn.classList.add('active');if(timerRunning){clearInterval(timerInterval);timerRunning=false}timerDuration=min*60;timerRemaining=min*60;updateDisplay();document.getElementById('ringProgress').style.strokeDashoffset=0;document.getElementById('startBtn').textContent='Start';document.getElementById('startBtn').classList.remove('active')}\nfunction toggleTimer(){if(timerRunning){clearInterval(timerInterval);timerRunning=false;document.getElementById('startBtn').textContent='Resume';document.getElementById('startBtn').classList.remove('active')}else{timerRunning=true;document.getElementById('startBtn').textContent='Pause';document.getElementById('startBtn').classList.add('active');timerInterval=setInterval(()=>{timerRemaining--;if(timerRemaining<=0){clearInterval(timerInterval);timerRunning=false;timerRemaining=0;document.getElementById('startBtn').textContent='Done!';document.getElementById('startBtn').classList.remove('active')};updateDisplay()},1000)}}\nfunction resetTimer(){clearInterval(timerInterval);timerRunning=false;timerRemaining=timerDuration;updateDisplay();document.getElementById('ringProgress').style.strokeDashoffset=0;document.getElementById('startBtn').textContent='Start';document.getElementById('startBtn').classList.remove('active')}\nfunction updateDisplay(){const m=Math.floor(timerRemaining/60),s=timerRemaining%60;document.getElementById('timerDisplay').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;const progress=(timerDuration-timerRemaining)/timerDuration;document.getElementById('ringProgress').style.strokeDashoffset=circumference*(1-progress)}\n</script>\n\n\n\n</body>\n</html>",
  "power-of-now": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<canvas id=\"bg-canvas\"></canvas>\n\n<div class=\"content\">\n  <header>\n    <div class=\"sun-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"></circle><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"></path></svg>️</div>\n    <h1>The Power of Now</h1>\n    <div class=\"subtitle\">A Guide to Spiritual Enlightenment</div>\n    <div class=\"author\">by Eckhart Tolle</div>\n  </header>\n\n  <div class=\"tabs\">\n    <button class=\"tab-btn active\" data-tab=\"essence\">Essence</button>\n    <button class=\"tab-btn\" data-tab=\"concepts\">Concepts</button>\n    <button class=\"tab-btn\" data-tab=\"practices\">Practices</button>\n    <button class=\"tab-btn\" data-tab=\"quotes\">Quotes</button>\n  </div>\n\n  <!--  TAB: Essence  -->\n  <div class=\"tab-panel active\" id=\"tab-essence\">\n    <div class=\"insight-box\">\n      <div class=\"big\">Be Here Now.</div>\n      <div class=\"small\">\n        The present moment is all there ever is. Suffering comes from identifying<br>\n        with the mind — dwelling on the past or worrying about the future.<br>\n        <strong style=\"color:#fbbf24;\">Presence is the path to peace.</strong>\n      </div>\n    </div>\n\n    <div class=\"card\" style=\"animation-delay: 0.1s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\"></path><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"></line></svg> You Are Not Your Mind</h2>\n      <p>Your thoughts are not who you are. You are the <strong>awareness</strong> behind them. The voice in your head is the conditioned mind — watch it without judgment and you discover your true self.</p>\n    </div>\n\n    <div class=\"card\" style=\"animation-delay: 0.2s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><polyline points=\"12 6 12 12 16 14\"></polyline></svg> The Illusion of Time</h2>\n      <p>Past and future are mental constructs — they exist only as thoughts <em>right now</em>. Problems need time to survive. In the present moment, there are no problems — only situations to be handled.</p>\n    </div>\n\n    <div class=\"card\" style=\"animation-delay: 0.3s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z\"></path></svg> The Pain-Body</h2>\n      <p>Accumulated emotional pain lives in you as an energy field. It feeds on negative thinking and drama. The cure: simply <strong>observe it</strong> without judgment. Awareness dissolves it.</p>\n    </div>\n\n    <div class=\"breath-circle\">Breathe</div>\n  </div>\n\n  <!--  TAB: Concepts  -->\n  <div class=\"tab-panel\" id=\"tab-concepts\">\n    <p style=\"color:#888; margin-bottom:1rem; font-size:0.9rem;\">Click any concept to expand.</p>\n\n    <div class=\"card\">\n      <div class=\"accordion-header\" onclick=\"toggleAccordion(this)\">\n        <h2 style=\"margin-bottom:0;\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"></path><path d=\"M2 17l10 5 10-5\"></path><path d=\"M2 12l10 5 10-5\"></path></svg> The Ego</h2>\n        <span class=\"arrow\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span>\n      </div>\n      <div class=\"accordion-body\">\n        <p>The ego is a false self built on thought patterns, beliefs, and stories. It thrives on past (resentment, regret) and future (anxiety, expectation). The ego needs problems to maintain its identity. Letting go of ego feels like dying — but that's liberation.</p>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"accordion-header\" onclick=\"toggleAccordion(this)\">\n        <h2 style=\"margin-bottom:0;\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"></path><circle cx=\"12\" cy=\"12\" r=\"3\"></circle></svg>️ The Watcher</h2>\n        <span class=\"arrow\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span>\n      </div>\n      <div class=\"accordion-body\">\n        <p>There is a dimension of awareness beyond thought — the witnessing presence. When you observe your emotions, thoughts, and sensations without labeling them good or bad, you step into the Watcher. This is your true self.</p>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"accordion-header\" onclick=\"toggleAccordion(this)\">\n        <h2 style=\"margin-bottom:0;\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6c.6.5 1.2 1 2.5 1C7 7 7 5 9.5 5c2.6 0 2.4 2 5 2 2.5 0 2.5-2 5-2 1.3 0 1.9.5 2.5 1\"></path><path d=\"M2 12c.6.5 1.2 1 2.5 1 2.5 0 2.5-2 5-2 2.6 0 2.4 2 5 2 2.5 0 2.5-2 5-2 1.3 0 1.9.5 2.5 1\"></path><path d=\"M2 18c.6.5 1.2 1 2.5 1 2.5 0 2.5-2 5-2 2.6 0 2.4 2 5 2 2.5 0 2.5-2 5-2 1.3 0 1.9.5 2.5 1\"></path></svg> Surrender</h2>\n        <span class=\"arrow\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span>\n      </div>\n      <div class=\"accordion-body\">\n        <p>Surrender is not giving up. It's accepting the present moment as it is — without resistance. Surrender to \"what is\" opens the door to deeper life energy. Acceptance of the Now frees you from suffering.</p>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"accordion-header\" onclick=\"toggleAccordion(this)\">\n        <h2 style=\"margin-bottom:0;\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2l1.5 5.5L19 7l-5.5 1.5L12 14l-1.5-5.5L5 7l5.5-1.5z\"></path><path d=\"M19 17l-5.5-1.5L12 11l-1.5 4.5L5 17l5.5 1.5L12 23l1.5-4.5z\"></path></svg> Presence</h2>\n        <span class=\"arrow\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span>\n      </div>\n      <div class=\"accordion-body\">\n        <p>Presence is the state of being fully in the Now. It's not a technique — it's a way of being. When present, you don't judge, you don't resist. You simply <em>are</em>. Presence is accessed through the body, the breath, and the senses.</p>\n      </div>\n    </div>\n\n    <div class=\"card\">\n      <div class=\"accordion-header\" onclick=\"toggleAccordion(this)\">\n        <h2 style=\"margin-bottom:0;\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z\"></path></svg> The Pain-Body</h2>\n        <span class=\"arrow\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span>\n      </div>\n      <div class=\"accordion-body\">\n        <p>Old emotional pain accumulates as a negative energy field in your body. It gets triggered by situations and people, then feeds on more negativity. Observing the pain-body without judgment is the only way to dissolve it. Don't fight it — just witness it.</p>\n      </div>\n    </div>\n  </div>\n\n  <!--  TAB: Practices  -->\n  <div class=\"tab-panel\" id=\"tab-practices\">\n    <p style=\"color:#888; margin-bottom:1rem; font-size:0.9rem;\">Tap any practice to read more.</p>\n\n    <div class=\"practice-grid\">\n      <div class=\"practice-card\" onclick=\"this.classList.toggle('open')\">\n        <span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"></path><circle cx=\"12\" cy=\"7\" r=\"4\"></circle></svg></span>\n        <span class=\"title\">Watch the Thinker</span>\n        <span class=\"detail\">Listen to the voice in your head. Observe it without engaging. That observing presence is your true self.</span>\n      </div>\n      <div class=\"practice-card\" onclick=\"this.classList.toggle('open')\">\n        <span class=\"icon\">🫁</span>\n        <span class=\"title\">Focus on the Breath</span>\n        <span class=\"detail\">One conscious breath anchors you in the Now. Feel the air moving in and out. The breath is always present.</span>\n      </div>\n      <div class=\"practice-card\" onclick=\"this.classList.toggle('open')\">\n        <span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 22c-1.5 0-3-1-3-2.5 0-1.5 1.5-2.5 3-2.5s3 1 3 2.5c0 1.5-1.5 2.5-3 2.5z\"></path><path d=\"M7 10.5c0 1.5 1 2.5 2.5 2.5\"></path><path d=\"M14.5 13c1.5 0 2.5-1 2.5-2.5\"></path><path d=\"M5 7c1 1 2 1.5 3 1.5\"></path><path d=\"M19 7c-1 1-2 1.5-3 1.5\"></path></svg></span>\n        <span class=\"title\">Feel the Body</span>\n        <span class=\"detail\">Close your eyes. Feel the aliveness in your hands, feet, chest. Do this for 30 seconds, several times a day.</span>\n      </div>\n      <div class=\"practice-card\" onclick=\"this.classList.toggle('open')\">\n        <span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"></path><circle cx=\"12\" cy=\"12\" r=\"3\"></circle></svg>️</span>\n        <span class=\"title\">Use Your Senses</span>\n        <span class=\"detail\">See, hear, touch as if for the first time. Senses only exist in the Now. Let them pull you into presence.</span>\n      </div>\n      <div class=\"practice-card\" onclick=\"this.classList.toggle('open')\">\n        <span class=\"icon\">⏸️</span>\n        <span class=\"title\">Presence Triggers</span>\n        <span class=\"detail\">Waiting in line, at a red light, washing hands — use these as cues to become aware of your body and breath.</span>\n      </div>\n      <div class=\"practice-card\" onclick=\"this.classList.toggle('open')\">\n        <span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M12 6v6l4 2\"></path></svg>️</span>\n        <span class=\"title\">Inner Body</span>\n        <span class=\"detail\">Direct attention into your body. Feel the subtle energy that animates you. This takes you beyond thought.</span>\n      </div>\n    </div>\n\n    <div class=\"card\" style=\"margin-top:0.5rem;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"4\"></circle><path d=\"M12 2v2\"></path><path d=\"M12 20v2\"></path><path d=\"M4.93 4.93l1.41 1.41\"></path><path d=\"M17.66 17.66l1.41 1.41\"></path><path d=\"M2 12h2\"></path><path d=\"M20 12h2\"></path><path d=\"M6.34 17.66l-1.41 1.41\"></path><path d=\"M19.07 4.93l-1.41 1.41\"></path></svg> The Daily Practice</h2>\n      <p>Set a gentle alarm 3-4 times a day. When it goes off, stop everything for 10 seconds. Take one conscious breath. Feel your body. That's it. Over time, presence becomes your natural state.</p>\n    </div>\n\n    <div class=\"breath-circle\">Breathe</div>\n  </div>\n\n  <!--  TAB: Quotes  -->\n  <div class=\"tab-panel\" id=\"tab-quotes\">\n    <div class=\"quote-box\">\n      <p>\"Realize deeply that the present moment is all you have. Make the Now the primary focus of your life.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.08s;\">\n      <p>\"You are not your mind.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.16s;\">\n      <p>\"The primary cause of unhappiness is never the situation but your thoughts about it.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.24s;\">\n      <p>\"The past has no power over the present moment.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.32s;\">\n      <p>\"Wherever you are, be there totally.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.40s;\">\n      <p>\"Life is now. There was never a time when your life was not now, nor will there ever be.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.48s;\">\n      <p>\"As soon as you honor the present moment, all unhappiness and struggle dissolve, and life begins to flow with joy and ease.\"</p>\n    </div>\n\n    <div class=\"card\" style=\"margin-top: 1.5rem;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0z\"></path><path d=\"M12 2v20\"></path><path d=\"M2 12h20\"></path></svg> One Final Thought</h2>\n      <p>You don't need to read more books to be present. You don't need more knowledge. Just stop. Breathe. Look around. <strong style=\"color:#fbbf24;\">This moment is enough.</strong></p>\n    </div>\n  </div>\n\n  <div class=\"progress-container\">\n    <div class=\"progress-label\">You are here —</div>\n    <div class=\"progress-bar-bg\">\n      <div class=\"progress-bar-fill\" style=\"width: 100%;\"></div>\n    </div>\n  </div>\n\n  \n</div>\n\n<script>\n  //  Ambient particles \n  const canvas = document.getElementById('bg-canvas');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n  let animFrame;\n\n  function resize() {\n    canvas.width = window.innerWidth;\n    canvas.height = document.documentElement.scrollHeight;\n  }\n  resize();\n  window.addEventListener('resize', resize);\n  window.addEventListener('scroll', resize);\n\n  let mouse = { x: 0, y: 0 };\n  document.addEventListener('mousemove', e => {\n    mouse.x = e.clientX;\n    mouse.y = e.clientY + window.scrollY;\n  });\n\n  class Particle {\n    constructor() { this.reset(); }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 3 + 0.5;\n      this.speedX = (Math.random() - 0.5) * 0.2;\n      this.speedY = (Math.random() - 0.5) * 0.2;\n      this.opacity = Math.random() * 0.3 + 0.05;\n      this.hue = 40 + Math.random() * 20; // warm golden range\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n\n      const dx = mouse.x - this.x;\n      const dy = mouse.y - this.y;\n      const dist = Math.sqrt(dx * dx + dy * dy);\n      if (dist < 120) {\n        this.x -= dx * 0.002;\n        this.y -= dy * 0.002;\n      }\n\n      if (this.x < -10 || this.x > canvas.width + 10 || this.y < -10 || this.y > canvas.height + 10) {\n        this.reset();\n      }\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `hsla(${this.hue}, 80%, 70%, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 60; i++) particles.push(new Particle());\n\n  function drawConnections() {\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 100) {\n          ctx.beginPath();\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.strokeStyle = `hsla(40, 60%, 70%, ${0.04 * (1 - dist / 100)})`;\n          ctx.lineWidth = 0.5;\n          ctx.stroke();\n        }\n      }\n    }\n  }\n\n  function animate() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    particles.forEach(p => { p.update(); p.draw(); });\n    drawConnections();\n    animFrame = requestAnimationFrame(animate);\n  }\n\n  animate();\n\n  //  Tabs \n  document.querySelectorAll('.tab-btn').forEach(btn => {\n    btn.addEventListener('click', () => {\n      document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));\n      document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));\n      btn.classList.add('active');\n      document.getElementById('tab-' + btn.dataset.tab).classList.add('active');\n      setTimeout(resize, 200);\n    });\n  });\n\n  //  Accordion \n  function toggleAccordion(header) {\n    const body = header.nextElementSibling;\n    header.classList.toggle('open');\n    body.classList.toggle('open');\n  }\n</script>\n\n\n\n</body>\n</html>",
  "psycho-cybernetics": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n<div id=\"progress\"></div>\n<canvas id=\"bgCanvas\"></canvas>\n\n\n\n\n<!-- SELF-IMAGE -->\n<section id=\"self-image\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">The Core Discovery</span>\n    <h2 class=\"section-title\">The Self-Image</h2>\n    <p class=\"section-desc\">The most important psychological discovery of the 20th century. Your self-image is a mental blueprint of \"the sort of person I am.\" Every action, feeling, and ability is consistent with it.</p></div>\n    <div class=\"key-grid\">\n      <div class=\"key-card reveal\" onclick=\"toggleCard(this)\">\n        <div class=\"icon\">🔮</div>\n        <h3>Your Golden Key</h3>\n        <p>You cannot outperform the person you see yourself as. Change the image, change your life.</p>\n        <div class=\"expanded\"><p>The self-image is built from past experiences, failures, triumphs, and how others reacted to you (especially in childhood). Once a belief about yourself enters this picture, it becomes \"true\" -- and you act accordingly, despite all willpower.</p></div>\n        <span class=\"toggle\">Click to expand ▼</span>\n      </div>\n      <div class=\"key-card reveal reveal-delay-1\" onclick=\"toggleCard(this)\">\n        <div class=\"icon\">🧠</div>\n        <h3>Surgeon's Discovery</h3>\n        <p>Dr. Maltz changed patients' faces -- but some still felt ugly inside. The real problem wasn't physical.</p>\n        <div class=\"expanded\"><p>Some patients whose faces were \"fixed\" still carried feelings of unworthiness and insecurity. This led to the insight: they suffered from a distorted self-image that no scalpel could reach. The incisions needed to go deeper than skin -- into the psyche.</p></div>\n        <span class=\"toggle\">Click to expand ▼</span>\n      </div>\n      <div class=\"key-card reveal reveal-delay-2\" onclick=\"toggleCard(this)\">\n        <div class=\"icon\">📡</div>\n        <h3>The Two Laws</h3>\n        <p>(1) You always act like the person you conceive yourself to be. (2) You literally cannot act otherwise.</p>\n        <div class=\"expanded\"><p>The man who sees himself as a failure finds ways to fail even if opportunity is dumped in his lap. The person who sees themselves as a victim of injustice will always find evidence of injustice. But change the self-image, and everything changes.</p></div>\n        <span class=\"toggle\">Click to expand ▼</span>\n      </div>\n    </div>\n    <div class=\"formula-box reveal\">\n      <div class=\"formula\">Self-Image → Actions → Feelings → Results → Reinforced Self-Image</div>\n      <div class=\"formula-label\">The feedback loop that runs your entire life</div>\n    </div>\n  </div>\n</section>\n\n<div class=\"part-divider\"><div class=\"line\"></div><h2>Your Built-In Guidance System</h2><p>Cybernetics meets psychology</p></div>\n\n<!-- MECHANISM -->\n<section id=\"mechanism\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">The Science</span>\n    <h2 class=\"section-title\">The Success Mechanism</h2>\n    <p class=\"section-desc\">Your brain and nervous system form a built-in servo-mechanism -- a goal-striving device that works automatically, like a guided missile or thermostat.</p></div>\n    <div class=\"key-grid\">\n      <div class=\"key-card reveal\" onclick=\"toggleCard(this)\">\n        <div class=\"icon\">🚀</div>\n        <h3>Guided Missile</h3>\n        <p>Reaches its target by making a series of mistakes and correcting course.</p>\n        <div class=\"expanded\"><p>You cannot correct course if you're standing still. Act, miss, correct -- that's how guided torpedoes work. Mistakes are data points, not indictments of your character. Every wrong attempt discarded is another step forward.</p></div>\n        <span class=\"toggle\">Click to expand ▼</span>\n      </div>\n      <div class=\"key-card reveal reveal-delay-1\" onclick=\"toggleCard(this)\">\n        <div class=\"icon\">🎯</div>\n        <h3>Goal-Striving</h3>\n        <p>The mechanism needs a clear target. Without a goal, it has nothing to work on.</p>\n        <div class=\"expanded\"><p>Like a thermostat needs a temperature setting, your Success Mechanism needs a goal. Feed it images of success and it steers toward them. Feed it images of failure and it steers toward those too. Garbage in, garbage out.</p></div>\n        <span class=\"toggle\">Click to expand ▼</span>\n      </div>\n      <div class=\"key-card reveal reveal-delay-2\" onclick=\"toggleCard(this)\">\n        <div class=\"icon\">⚙</div>\n        <h3>Impersonal Machine</h3>\n        <p>It has no will of its own. It works on whatever data you feed it through imagination and belief.</p>\n        <div class=\"expanded\"><p>Conscious thinking is the \"control knob.\" It was by conscious thought (perhaps irrational) that negative patterns were formed -- and it's by conscious rational thought that they can be changed. You are the operator, not the machine.</p></div>\n        <span class=\"toggle\">Click to expand ▼</span>\n      </div>\n    </div>\n    <div class=\"formula-box reveal\">\n      <div class=\"formula\">Your Nervous System Cannot Tell Real Experience from Vividly Imagined Experience</div>\n      <div class=\"formula-label\">This is the scientific foundation of visualization</div>\n    </div>\n    <div class=\"comparison reveal\">\n      <div class=\"comp-side creative\">\n        <h4>✨ Creative Imagination</h4>\n        <ul><li>Picture success vividly</li><li>See possibilities and solutions</li><li>Act \"as if\" it's already real</li><li>Your mechanism steers toward it</li><li>Strengthens neural pathways</li></ul>\n      </div>\n      <div class=\"comp-side destructive\">\n        <h4>💥 Destructive Imagination</h4>\n        <ul><li>Picture failure in detail</li><li>Dwell on worst-case scenarios</li><li>Experience failure emotions in advance</li><li>Your mechanism steers toward it</li><li>Worry = negative visualization</li></ul>\n      </div>\n    </div>\n  </div>\n</section>\n\n<div class=\"part-divider\"><div class=\"line\"></div><h2>The 8 Ingredients of Success</h2><p>Spelled out in the word itself</p></div>\n\n<!-- S-U-C-C-E-S-S -->\n<section id=\"success\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">The Success-Type Personality</span>\n    <h2 class=\"section-title\">S-U-C-C-E-S-S</h2>\n    <p class=\"section-desc\">Just as failure can be diagnosed from symptoms, so can success. The success-type personality is composed of these 8 ingredients.</p></div>\n    <div class=\"success-grid\">\n      <div class=\"success-item reveal\" onclick=\"toggleSuccess(this)\">\n        <div class=\"letter\">S</div>\n        <h5>Sense of Direction</h5>\n        <p>Have a clear goal to shoot for</p>\n        <div class=\"detail\"><p>The creative mechanism is goal-striving. Without a target, you're like a ship's skipper who's let go of the wheel, hoping to drift in the right direction.</p></div>\n        <div class=\"click-hint\">tap</div>\n      </div>\n      <div class=\"success-item reveal reveal-delay-1\" onclick=\"toggleSuccess(this)\">\n        <div class=\"letter\">U</div>\n        <h5>Understanding</h5>\n        <p>See things as they are</p>\n        <div class=\"detail\"><p>Use reason to examine beliefs. Don't jump to conclusions. Understand that mistakes are part of the process, not evidence of personal deficiency.</p></div>\n        <div class=\"click-hint\">tap</div>\n      </div>\n      <div class=\"success-item reveal reveal-delay-1\" onclick=\"toggleSuccess(this)\">\n        <div class=\"letter\">C</div>\n        <h5>Courage</h5>\n        <p>Act despite fear</p>\n        <div class=\"detail\"><p>Courage is not absence of fear -- it's acting with purpose despite it. The only way to build courage is to practice it. Take one step, the next is easier.</p></div>\n        <div class=\"click-hint\">tap</div>\n      </div>\n      <div class=\"success-item reveal reveal-delay-2\" onclick=\"toggleSuccess(this)\">\n        <div class=\"letter\">C</div>\n        <h5>Compassion</h5>\n        <p>Understand others</p>\n        <div class=\"detail\"><p>A successful personality is warm and empathetic. Understanding others' struggles builds genuine connection and deepens your own sense of purpose.</p></div>\n        <div class=\"click-hint\">tap</div>\n      </div>\n      <div class=\"success-item reveal reveal-delay-2\" onclick=\"toggleSuccess(this)\">\n        <div class=\"letter\">E</div>\n        <h5>Esteem</h5>\n        <p>Use self-esteem for yourself</p>\n        <div class=\"detail\"><p>Big personalities make mistakes and admit them. Only little people are afraid to be wrong. Your worth is not contingent on being perfect.</p></div>\n        <div class=\"click-hint\">tap</div>\n      </div>\n      <div class=\"success-item reveal reveal-delay-3\" onclick=\"toggleSuccess(this)\">\n        <div class=\"letter\">S</div>\n        <h5>Self-Confidence</h5>\n        <p>Picture yourself succeeding</p>\n        <div class=\"detail\"><p>Confidence comes from experience AND imagination. Act \"as if\" you already have the confidence you want. Your mechanism will fill in the details.</p></div>\n        <div class=\"click-hint\">tap</div>\n      </div>\n      <div class=\"success-item reveal reveal-delay-3\" onclick=\"toggleSuccess(this)\">\n        <div class=\"letter\">S</div>\n        <h5>Self-Acceptance</h5>\n        <p>Accept imperfection</p>\n        <div class=\"detail\"><p>Perfection is neither required nor possible. Approximations are good enough for all practical purposes. Accept yourself with flaws and mistakes.</p></div>\n        <div class=\"click-hint\">tap</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<div class=\"part-divider\"><div class=\"line\"></div><h2>The Failure Mechanism</h2><p>Recognize the signs. Correct the course.</p></div>\n\n<!-- F-A-I-L-U-R-E -->\n<section id=\"failure\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Negative Feedback Signals</span>\n    <h2 class=\"section-title\">F-A-I-L-U-R-E</h2>\n    <p class=\"section-desc\">These symptoms act as red lights. Recognize them, understand them, and take corrective action. Nobody is immune -- even the most successful experience them at times.</p></div>\n    <div class=\"failure-grid\">\n      <div class=\"failure-item reveal\" onclick=\"toggleFailure(this)\">\n        <div class=\"letter\">F</div>\n        <h5>Frustration</h5>\n        <p>Goals cannot be realized</p>\n        <div class=\"detail\"><p>Learn that perfection is unnecessary. Approximations are good enough. Tolerate imperfection in yourself and in life.</p></div>\n        <div class=\"click-hint\">tap</div>\n      </div>\n      <div class=\"failure-item reveal reveal-delay-1\" onclick=\"toggleFailure(this)\">\n        <div class=\"letter\">A</div>\n        <h5>Aggressiveness</h5>\n        <p>Misdirected energy</p>\n        <div class=\"detail\"><p>Positive aggression = moving toward your goal with purpose. Misdirected = attacking the wrong target instead of solving the real problem.</p></div>\n        <div class=\"click-hint\">tap</div>\n      </div>\n      <div class=\"failure-item reveal reveal-delay-1\" onclick=\"toggleFailure(this)\">\n        <div class=\"letter\">I</div>\n        <h5>Insecurity</h5>\n        <p>False need for perfection</p>\n        <div class=\"detail\"><p>Built on the premise that you must be perfect to be worthy. Mistakes are normal, expected, and necessary. Nobody is right all the time.</p></div>\n        <div class=\"click-hint\">tap</div>\n      </div>\n      <div class=\"failure-item reveal reveal-delay-2\" onclick=\"toggleFailure(this)\">\n        <div class=\"letter\">L</div>\n        <h5>Loneliness</h5>\n        <p>Lack of \"oneness\"</p>\n        <div class=\"detail\"><p>Self-imposed disconnection through emotional scar tissue. The cure: remove the protective shell and risk genuine connection again.</p></div>\n        <div class=\"click-hint\">tap</div>\n      </div>\n      <div class=\"failure-item reveal reveal-delay-2\" onclick=\"toggleFailure(this)\">\n        <div class=\"letter\">U</div>\n        <h5>Uncertainty</h5>\n        <p>Avoiding mistakes</p>\n        <div class=\"detail\"><p>\"The greatest mistake is being afraid of making one.\" You cannot correct course if you're standing still. Act, miss, correct -- repeat.</p></div>\n        <div class=\"click-hint\">tap</div>\n      </div>\n      <div class=\"failure-item reveal reveal-delay-3\" onclick=\"toggleFailure(this)\">\n        <div class=\"letter\">R</div>\n        <h5>Resentment</h5>\n        <p>Blaming unfairness</p>\n        <div class=\"detail\"><p>A deadly poison to the spirit. Uses enormous energy. Makes happiness impossible. It's a way of avoiding personal responsibility.</p></div>\n        <div class=\"click-hint\">tap</div>\n      </div>\n      <div class=\"failure-item reveal reveal-delay-3\" onclick=\"toggleFailure(this)\">\n        <div class=\"letter\">E</div>\n        <h5>Emptiness</h5>\n        <p>No goals, no purpose</p>\n        <div class=\"detail\"><p>The feeling that nothing matters. Usually from having no direction. The cure: find something meaningful to work toward and commit to it.</p></div>\n        <div class=\"click-hint\">tap</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- KEY CHAPTERS -->\n<section>\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Core Chapters</span>\n    <h2 class=\"section-title\">How to Apply Psycho-Cybernetics</h2></div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">🧠</div><div><h3>Dehypnotize False Beliefs</h3><p style=\"color:var(--muted);font-size:.85rem\">Chapter 4</p></div></div>\n      <div class=\"rule-body\">\n        <p>False beliefs are literal self-hypnosis. When Adler's teacher called him \"dumb in math,\" he accepted it -- and his grades proved it. Only after breaking free did his real ability emerge.</p>\n        <ul>\n          <li>\"I'm not the type who...\" is not a fact -- it's a belief you accepted uncritically</li>\n          <li>These beliefs formed in the past, often in childhood</li>\n          <li>They are hypotheses you can test, challenge, and replace</li>\n          <li>Replace \"I can't\" with \"How can I?\"</li>\n          <li>Rational, conscious thinking IS the control knob of your unconscious machine</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">☮</div><div><h3>The Habit of Happiness</h3><p style=\"color:var(--muted);font-size:.85rem\">Chapter 7</p></div></div>\n      <div class=\"rule-body\">\n        <p>\"Be happy -- and you will be good, more successful, healthier, and act more charitably toward others.\" Happiness is native to the human mind. It's a habit, not a reward.</p>\n        <ul>\n          <li>When happy: you see better, hear better, perform better, remember better</li>\n          <li>It's NOT earned, deserved, or a reward for suffering</li>\n          <li>It's not something that happens when everything goes right</li>\n          <li>It IS a habit, an attitude, a way of approaching life</li>\n          <li>Consciously choose pleasant thoughts -- not denial, but deliberate focus on the good</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">🛌</div><div><h3>Relax &amp; Let the Mechanism Work</h3><p style=\"color:var(--muted);font-size:.85rem\">Chapter 6</p></div></div>\n      <div class=\"rule-body\">\n        <p>Modern man tries to solve everything by conscious thought. But the forebrain is the operator, not the machine. It poses problems -- it doesn't solve them. Stress and excessive effort jam the mechanism.</p>\n        <ul>\n          <li>Decide on your goal consciously, then TRUST the mechanism to find the way</li>\n          <li>Don't micromanage the process</li>\n          <li>William James: modern man is too tense, too anxious about results</li>\n          <li>Form the habit of freeing thoughts from egoistic preoccupation about results</li>\n          <li>Let your Success Mechanism work while you sleep</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">🛡</div><div><h3>Remove Emotional Scars</h3><p style=\"color:var(--muted);font-size:.85rem\">Chapter 10</p></div></div>\n      <div class=\"rule-body\">\n        <p>Emotional injuries form scar tissue -- hardened attitudes, callousness, withdrawal -- to guard against future hurt. But these scars become a liability: they protect you from getting hurt, but also prevent you from living.</p>\n        <ul>\n          <li>Recognize scar tissue for what it is: protection that became a prison</li>\n          <li>The original injury is in the past</li>\n          <li>Living fully is more important than being safe</li>\n          <li>Practice openness and vulnerability in small steps</li>\n          <li>Risk connection again</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">🔓</div><div><h3>Unlock Your Real Personality</h3><p style=\"color:var(--muted);font-size:.85rem\">Chapter 11</p></div></div>\n      <div class=\"rule-body\">\n        <p>Personality is not acquired from without -- it's released from within. Everyone has personality locked up inside. \"Poor personality\" = inhibited personality = locked-up real self.</p>\n        <ul>\n          <li>Reduce excessive sensitivity to negative feedback</li>\n          <li>Negative feedback should correct course, not stop forward motion</li>\n          <li>If your mechanism is too sensitive, it overcorrects and goes nowhere</li>\n          <li>A baby has \"personality plus\" -- no phoniness, no inhibition, emotionally honest</li>\n          <li>Be yourself. Express your real feelings without guile.</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n\n    <div class=\"rule reveal\" onclick=\"toggleRule(this)\">\n      <div class=\"rule-header\"><div class=\"rule-num\">🏆</div><div><h3>Get the Winning Feeling</h3><p style=\"color:var(--muted);font-size:.85rem\">Chapter 14</p></div></div>\n      <div class=\"rule-body\">\n        <p>Your Creative Mechanism is teleological -- it operates in terms of goals and end results. You supply the goal. Your mechanism supplies the \"means whereby.\"</p>\n        <ul>\n          <li>Think of the end result as a PRESENT POSSIBILITY</li>\n          <li>Picture it so vividly it becomes \"real\" to your nervous system</li>\n          <li>Capture the FEELING you'd have if the goal were already achieved</li>\n          <li>Worry is the reverse: picturing failure so vividly you feel failure emotions in advance</li>\n          <li>The winning feeling is a thermometer -- it tells you your mechanism is geared for success</li>\n        </ul>\n      </div>\n      <span class=\"expand-btn\">Click to expand ▼</span>\n    </div>\n  </div>\n</section>\n\n<!-- PRACTICAL EXERCISES -->\n<section id=\"exercises\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Daily Practice</span>\n    <h2 class=\"section-title\">6 Exercises from the Book</h2>\n    <p class=\"section-desc\">These aren't theoretical. They're practical exercises designed to reprogram your Success Mechanism. Do them consistently for 21 days.</p></div>\n    <div class=\"exercises-grid\">\n      <div class=\"exercise-card reveal\" onclick=\"toggleExercise(this)\">\n        <div class=\"ex-num\">1</div>\n        <h4>Theater of the Mind</h4>\n        <p>30 minutes daily in a quiet room. Relax completely.</p>\n        <div class=\"ex-detail\"><p>Create a vivid mental movie of yourself acting, feeling, and being the person you want to be. See yourself succeeding in specific situations. Do this consistently for 21 days to form a new self-image.</p></div>\n        <div class=\"click-hint\">tap for details</div>\n      </div>\n      <div class=\"exercise-card reveal reveal-delay-1\" onclick=\"toggleExercise(this)\">\n        <div class=\"ex-num\">2</div>\n        <h4>Act As If</h4>\n        <p>Act as if you're already the person you want to become.</p>\n        <div class=\"ex-detail\"><p>Not faking -- choosing which version of yourself to express. Your self-image will catch up to your actions. When you don't know how to act, ask: \"What would the person I want to be do right now?\"</p></div>\n        <div class=\"click-hint\">tap for details</div>\n      </div>\n      <div class=\"exercise-card reveal reveal-delay-1\" onclick=\"toggleExercise(this)\">\n        <div class=\"ex-num\">3</div>\n        <h4>Rational Examination</h4>\n        <p>When you feel a negative emotion, examine the belief behind it.</p>\n        <div class=\"ex-detail\"><p>Is it based on facts? Or on a false belief you accepted uncritically? Use your power of reason. Conscious rational thinking is the control knob of your unconscious machine. Question everything.</p></div>\n        <div class=\"click-hint\">tap for details</div>\n      </div>\n      <div class=\"exercise-card reveal reveal-delay-2\" onclick=\"toggleExercise(this)\">\n        <div class=\"ex-num\">4</div>\n        <h4>The Happiness Habit</h4>\n        <p>Consciously choose pleasant thoughts throughout the day.</p>\n        <div class=\"ex-detail\"><p>Not denial of problems -- a deliberate decision to focus on the good that exists alongside the bad. Think of three things you're grateful for. Savor pleasant memories. This rewires your default emotional state.</p></div>\n        <div class=\"click-hint\">tap for details</div>\n      </div>\n      <div class=\"exercise-card reveal reveal-delay-2\" onclick=\"toggleExercise(this)\">\n        <div class=\"ex-num\">5</div>\n        <h4>Relaxation Before Sleep</h4>\n        <p>Before sleep, review the day. Release the day's failures.</p>\n        <div class=\"ex-detail\"><p>Picture your Success Mechanism working while you sleep. Trust it to find solutions. Let sleeping dogs lie -- don't dredge up past failures. Your mechanism processes data during sleep better than conscious worry ever could.</p></div>\n        <div class=\"click-hint\">tap for details</div>\n      </div>\n      <div class=\"exercise-card reveal reveal-delay-3\" onclick=\"toggleExercise(this)\">\n        <div class=\"ex-num\">6</div>\n        <h4>Forgive Yourself</h4>\n        <p>Remember: your mechanism corrects through mistakes.</p>\n        <div class=\"ex-detail\"><p>Forgive yourself for errors. They are data points, not indictments of your character. A guided missile makes hundreds of corrections to reach its target. You're doing the same thing. Every mistake is a course correction.</p></div>\n        <div class=\"click-hint\">tap for details</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- VISUALIZATION TIMER -->\n<section id=\"timer\" class=\"timer-section\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Practice</span>\n    <h2 class=\"section-title\">Theater of the Mind Timer</h2>\n    <p class=\"section-desc\" style=\"margin:0 auto 2rem\">Maltz recommended 30 minutes of daily mental rehearsal. Start your session.</p></div>\n    <div class=\"reveal\">\n      <div class=\"timer-modes\">\n        <button class=\"timer-mode\" onclick=\"setTimer(15,this)\">15 min</button>\n        <button class=\"timer-mode active\" onclick=\"setTimer(30,this)\">30 min</button>\n        <button class=\"timer-mode\" onclick=\"setTimer(60,this)\">60 min</button>\n      </div>\n      <div class=\"timer-ring\">\n        <svg width=\"300\" height=\"300\"><circle class=\"bg\" cx=\"150\" cy=\"150\" r=\"140\"></circle><circle class=\"progress\" id=\"ringProgress\" cx=\"150\" cy=\"150\" r=\"140\" stroke-dasharray=\"879.6\" stroke-dashoffset=\"0\"></circle></svg>\n        <div class=\"timer-display\" id=\"timerDisplay\" style=\"position:absolute;top:50%;left:50%;transform:translate(-50%,-50%)\">30:00</div>\n      </div>\n      <div class=\"timer-controls\">\n        <button class=\"timer-btn\" id=\"startBtn\" onclick=\"toggleTimer()\">Start</button>\n        <button class=\"timer-btn reset\" onclick=\"resetTimer()\">Reset</button>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- TAKEAWAYS -->\n<section id=\"takeaways\">\n  <div class=\"container\">\n    <div class=\"reveal\"><span class=\"section-label\">Remember</span>\n    <h2 class=\"section-title\">Key Takeaways</h2></div>\n    <div class=\"takeaway-grid\">\n      <div class=\"takeaway reveal\"><div class=\"num\">1</div><p>Your <strong style=\"color:var(--text)\">self-image</strong> is everything. You cannot outperform the person you see yourself as.</p></div>\n      <div class=\"takeaway reveal reveal-delay-1\"><div class=\"num\">2</div><p>You have a <strong style=\"color:var(--text)\">built-in Success Mechanism</strong>. Feed it images of success, it delivers success.</p></div>\n      <div class=\"takeaway reveal reveal-delay-1\"><div class=\"num\">3</div><p><strong style=\"color:var(--text)\">Imagination</strong> is the key. Your nervous system can't tell real from vividly imagined.</p></div>\n      <div class=\"takeaway reveal reveal-delay-2\"><div class=\"num\">4</div><p><strong style=\"color:var(--text)\">False beliefs</strong> are self-hypnosis. \"I'm just not the type...\" is not a fact -- it's a belief you can replace.</p></div>\n      <div class=\"takeaway reveal reveal-delay-2\"><div class=\"num\">5</div><p><strong style=\"color:var(--text)\">Happiness is a habit</strong>, not a reward. Acquire it through daily practice.</p></div>\n      <div class=\"takeaway reveal reveal-delay-3\"><div class=\"num\">6</div><p><strong style=\"color:var(--text)\">Relax and trust</strong> the mechanism. Excessive effort jams the system.</p></div>\n      <div class=\"takeaway reveal reveal-delay-3\"><div class=\"num\">7</div><p><strong style=\"color:var(--text)\">Mistakes are data</strong>. A guided missile reaches its target through corrections. You cannot correct if you're standing still.</p></div>\n      <div class=\"takeaway reveal\"><div class=\"num\">8</div><p><strong style=\"color:var(--text)\">Remove emotional scars</strong>. Protection that becomes a prison is worse than no protection.</p></div>\n      <div class=\"takeaway reveal reveal-delay-1\"><div class=\"num\">9</div><p><strong style=\"color:var(--text)\">Act as if</strong> -- your self-image will catch up to your actions.</p></div>\n      <div class=\"takeaway reveal reveal-delay-1\"><div class=\"num\">10</div><p><strong style=\"color:var(--text)\">Capture the winning feeling</strong> before success arrives. Your mechanism responds to feelings.</p></div>\n      <div class=\"takeaway reveal reveal-delay-2\"><div class=\"num\">11</div><p><strong style=\"color:var(--text)\">Never stop setting goals</strong>. Goal-setting is the fountain of youth.</p></div>\n      <div class=\"takeaway reveal reveal-delay-2\"><div class=\"num\">12</div><p>Practice the <strong style=\"color:var(--text)\">Theater of the Mind</strong> for 30 minutes daily for 21 days. Watch your life transform.</p></div>\n    </div>\n  </div>\n</section>\n\n\n\n<script>\nconst canvas=document.getElementById('bgCanvas'),ctx=canvas.getContext('2d');\nlet particles=[];\nfunction resize(){canvas.width=window.innerWidth;canvas.height=window.innerHeight}\nresize();window.addEventListener('resize',resize);\nclass Particle{constructor(){this.reset()}reset(){this.x=Math.random()*canvas.width;this.y=Math.random()*canvas.height;this.vx=(Math.random()-.5)*.3;this.vy=(Math.random()-.5)*.3;this.r=Math.random()*2+.5;this.a=Math.random()*.5+.1}update(){this.x+=this.vx;this.y+=this.vy;if(this.x<0||this.x>canvas.width)this.vx*=-1;if(this.y<0||this.y>canvas.height)this.vy*=-1}draw(){ctx.beginPath();ctx.arc(this.x,this.y,this.r,0,Math.PI*2);ctx.fillStyle=`rgba(139,92,246,${this.a})`;ctx.fill()}}\nfor(let i=0;i<80;i++)particles.push(new Particle());\nfunction animate(){ctx.clearRect(0,0,canvas.width,canvas.height);particles.forEach(p=>{p.update();p.draw()});for(let i=0;i<particles.length;i++)for(let j=i+1;j<particles.length;j++){const dx=particles[i].x-particles[j].x,dy=particles[i].y-particles[j].y,d=Math.sqrt(dx*dx+dy*dy);if(d<120){ctx.beginPath();ctx.moveTo(particles[i].x,particles[i].y);ctx.lineTo(particles[j].x,particles[j].y);ctx.strokeStyle=`rgba(139,92,246,${.08*(1-d/120)})`;ctx.stroke()}}requestAnimationFrame(animate)}animate();\n\nwindow.addEventListener('scroll',()=>{const s=window.scrollY/(document.body.scrollHeight-window.innerHeight)*100;document.getElementById('progress').style.width=s+'%';document.getElementById('nav').classList.toggle('visible',window.scrollY>300)});\n\nconst observer=new IntersectionObserver((entries)=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('visible');observer.unobserve(e.target)}})},{threshold:.1});\ndocument.querySelectorAll('.reveal').forEach(el=>observer.observe(el));\n\nfunction toggleCard(el){el.classList.toggle('open')}\nfunction toggleRule(el){el.classList.toggle('open')}\nfunction toggleSuccess(el){el.classList.toggle('open')}\nfunction toggleFailure(el){el.classList.toggle('open')}\nfunction toggleExercise(el){el.classList.toggle('open')}\n\nlet timerDuration=30*60,timerRemaining=30*60,timerInterval=null,timerRunning=false;\nconst circumference=2*Math.PI*140;\nfunction setTimer(min,btn){document.querySelectorAll('.timer-mode').forEach(b=>b.classList.remove('active'));btn.classList.add('active');if(timerRunning){clearInterval(timerInterval);timerRunning=false}timerDuration=min*60;timerRemaining=min*60;updateDisplay();document.getElementById('ringProgress').style.strokeDashoffset=0;document.getElementById('startBtn').textContent='Start';document.getElementById('startBtn').classList.remove('active')}\nfunction toggleTimer(){if(timerRunning){clearInterval(timerInterval);timerRunning=false;document.getElementById('startBtn').textContent='Resume';document.getElementById('startBtn').classList.remove('active')}else{timerRunning=true;document.getElementById('startBtn').textContent='Pause';document.getElementById('startBtn').classList.add('active');timerInterval=setInterval(()=>{timerRemaining--;if(timerRemaining<=0){clearInterval(timerInterval);timerRunning=false;timerRemaining=0;document.getElementById('startBtn').textContent='Done!';document.getElementById('startBtn').classList.remove('active')};updateDisplay()},1000)}}\nfunction resetTimer(){clearInterval(timerInterval);timerRunning=false;timerRemaining=timerDuration;updateDisplay();document.getElementById('ringProgress').style.strokeDashoffset=0;document.getElementById('startBtn').textContent='Start';document.getElementById('startBtn').classList.remove('active')}\nfunction updateDisplay(){const m=Math.floor(timerRemaining/60),s=timerRemaining%60;document.getElementById('timerDisplay').textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;const progress=(timerDuration-timerRemaining)/timerDuration;document.getElementById('ringProgress').style.strokeDashoffset=circumference*(1-progress)}\n</script>\n\n\n\n</body>\n</html>",
  "read-people-like-a-book": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div id=\"scanlines\"></div>\n<canvas id=\"pulse-canvas\"></canvas>\n<div id=\"noise\"></div>\n<div id=\"progress\"></div>\n\n<button id=\"theme-toggle\" aria-label=\"Toggle theme\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"></path></svg></button>\n\n<div class=\"container\">\n\n  <!--  HERO  -->\n  \n\n  <!--  STATS  -->\n  <div class=\"stats-grid reveal\">\n    <div class=\"stat-card\"><div class=\"num\">47</div><div class=\"label\">Behavioral Cues</div></div>\n    <div class=\"stat-card\"><div class=\"num\">7</div><div class=\"label\">Personality Types</div></div>\n    <div class=\"stat-card\"><div class=\"num\">21</div><div class=\"label\">Chapters</div></div>\n  </div>\n\n  <!--  COMMUNICATION STYLES  -->\n  <h2 class=\"section-heading reveal\"><span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"></path></svg></span> <span class=\"gradient\">4 Communication Styles</span></h2>\n  <p style=\"color:var(--text-dim);font-size:0.9rem;margin-bottom:0.8rem;\" class=\"reveal\">Click each card to reveal deeper traits.</p>\n  <div class=\"comm-grid reveal\">\n    <div class=\"comm-card\" onclick=\"this.classList.toggle('open')\">\n      <div class=\"comm-name\">Passive</div>\n      <div class=\"comm-tagline\">\"Whatever you think is best.\"</div>\n      <div class=\"comm-desc\">Avoids conflict at all costs. Speaks softly, rarely disagrees, apologizes excessively. Underneath: fear of rejection, low self-worth. May harbor resentment that surfaces indirectly.</div>\n    </div>\n    <div class=\"comm-card\" onclick=\"this.classList.toggle('open')\">\n      <div class=\"comm-name\">Aggressive</div>\n      <div class=\"comm-tagline\">\"This is how it's going to be.\"</div>\n      <div class=\"comm-desc\">Dominates conversations, interrupts, uses pointed gestures and intense eye contact. Underneath: insecurity masked as power. Needs to win to feel safe.</div>\n    </div>\n    <div class=\"comm-card\" onclick=\"this.classList.toggle('open')\">\n      <div class=\"comm-name\">Passive-Aggressive</div>\n      <div class=\"comm-tagline\">\"Fine. Whatever.\" (it's not fine)</div>\n      <div class=\"comm-desc\">Expresses anger indirectly — sarcasm, silent treatment, \"forgetting,\" backhanded compliments. Underneath: wants to express anger but fears direct confrontation.</div>\n    </div>\n    <div class=\"comm-card\" onclick=\"this.classList.toggle('open')\">\n      <div class=\"comm-name\">Assertive</div>\n      <div class=\"comm-tagline\">\"Here's how I see it. What about you?\"</div>\n      <div class=\"comm-desc\">Speaks clearly with calm confidence. Respects boundaries, maintains eye contact, listens actively. Underneath: high self-worth, emotional regulation, mutual respect.</div>\n    </div>\n  </div>\n\n  <!--  BODY LANGUAGE DECODER  -->\n  <h2 class=\"section-heading reveal\"><span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"></path><circle cx=\"12\" cy=\"7\" r=\"4\"></circle><path d=\"M12 3l-2 4h4l-2 4\"></path></svg>️</span> <span class=\"gradient\">Body Language Decoder</span></h2>\n  <p style=\"color:var(--text-dim);font-size:0.9rem;margin-bottom:0.8rem;\" class=\"reveal\">Click any body area to uncover hidden meanings.</p>\n  <div class=\"body-grid reveal\">\n    <div class=\"body-part\" onclick=\"this.classList.toggle('open')\">\n      <span class=\"body-icon\">🦶</span>\n      <span class=\"body-label\">Feet</span>\n      <div class=\"body-meaning\">\n        <ul class=\"body-clues\">\n          <li>Pointing toward you = interest/engagement</li>\n          <li>Pointing away = desire to leave</li>\n          <li>Tapping/fidgeting = anxiety or impatience</li>\n          <li>Interlaced around chair = discomfort</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"body-part\" onclick=\"this.classList.toggle('open')\">\n      <span class=\"body-icon\">🦵</span>\n      <span class=\"body-label\">Legs</span>\n      <div class=\"body-meaning\">\n        <ul class=\"body-clues\">\n          <li>Spread wide = dominance / comfort</li>\n          <li>Crossed away = defensiveness</li>\n          <li>Bouncing = nervous energy</li>\n          <li>Knee clasp = ready to leave</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"body-part\" onclick=\"this.classList.toggle('open')\">\n      <span class=\"body-icon\">🤲</span>\n      <span class=\"body-label\">Hands</span>\n      <div class=\"body-meaning\">\n        <ul class=\"body-clues\">\n          <li>Palms visible = openness, honesty</li>\n          <li>Steepling = confidence, authority</li>\n          <li>Rubbing/wringing = stress, self-soothing</li>\n          <li>Thumbs hidden = insecurity</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"body-part\" onclick=\"this.classList.toggle('open')\">\n      <span class=\"body-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.5 2A2.5 2.5 0 0 1 17 4.5V8\"></path><path d=\"M17 15v2.5a2.5 2.5 0 0 1-2.5 2.5\"></path><path d=\"M2 8h12a2 2 0 0 1 2 2v2\"></path><path d=\"M2 14h8\"></path><path d=\"M14 14h2a2 2 0 0 1 2 2v3a2 2 0 0 1-2 2h-2\"></path><path d=\"M8 20h2\"></path></svg></span>\n      <span class=\"body-label\">Arms</span>\n      <div class=\"body-meaning\">\n        <ul class=\"body-clues\">\n          <li>Crossed high = barrier, defensiveness</li>\n          <li>Crossed low = self-soothing</li>\n          <li>Open + relaxed = receptiveness</li>\n          <li>Shoulders to ears = acute stress</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"body-part\" onclick=\"this.classList.toggle('open')\">\n      <span class=\"body-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"></path><circle cx=\"12\" cy=\"12\" r=\"3\"></circle></svg>️</span>\n      <span class=\"body-label\">Eyes</span>\n      <div class=\"body-meaning\">\n        <ul class=\"body-clues\">\n          <li>Pupil dilation = interest / attraction</li>\n          <li>Rapid blinking = discomfort / stress</li>\n          <li>Gaze aversion = processing or hiding</li>\n          <li>Brow flash = recognition / greeting</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"body-part\" onclick=\"this.classList.toggle('open')\">\n      <span class=\"body-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"></path></svg></span>\n      <span class=\"body-label\">Face</span>\n      <div class=\"body-meaning\">\n        <ul class=\"body-clues\">\n          <li>Real smile = eyes crinkle (Duchenne)</li>\n          <li>Lip compression = stress / anger</li>\n          <li>Nostril flare = arousal / aggression</li>\n          <li>Head tilt = interest / trust</li>\n        </ul>\n      </div>\n    </div>\n  </div>\n\n  <!--  EMOTIONAL INTELLIGENCE  -->\n  <h2 class=\"section-heading reveal\"><span class=\"icon\">🧩</span> <span class=\"gradient\">Emotional Intelligence Principles</span></h2>\n  <div class=\"eq-grid reveal\">\n    <div class=\"eq-card\"><span class=\"eq-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"></path><path d=\"M2 17l10 5 10-5\"></path><path d=\"M2 12l10 5 10-5\"></path></svg></span><div class=\"eq-title\">Self-Awareness</div><div class=\"eq-desc\">Recognize your own emotions as they happen. You can't read others if you can't read yourself.</div></div>\n    <div class=\"eq-card\"><span class=\"eq-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"23 4 23 10 17 10\"></polyline><path d=\"M20.49 15a9 9 0 1 1-2.12-9.36L23 10\"></path></svg></span><div class=\"eq-title\">Self-Regulation</div><div class=\"eq-desc\">Pause before reacting. Emotional control prevents hijacking your perception of others.</div></div>\n    <div class=\"eq-card\"><span class=\"eq-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z\"></path></svg>️</span><div class=\"eq-title\">Empathy</div><div class=\"eq-desc\">Feel with people, not just for them. True understanding comes from perspective-taking.</div></div>\n    <div class=\"eq-card\"><span class=\"eq-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><ellipse cx=\"12\" cy=\"12\" rx=\"4\" ry=\"10\"></ellipse><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"></line></svg></span><div class=\"eq-title\">Social Skill</div><div class=\"eq-desc\">Navigate relationships with intention. Rapport is the gateway to reading anyone.</div></div>\n  </div>\n\n  <!--  KEY TECHNIQUES  -->\n  <h2 class=\"section-heading reveal\"><span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"2\"></circle><path d=\"M12 2a10 10 0 0 1 10 10\"></path><path d=\"M12 22a10 10 0 0 1-10-10\"></path><path d=\"M2 12h20\"></path></svg></span> <span class=\"gradient\">Key Techniques to Read People</span></h2>\n  <div class=\"card reveal\">\n    <div class=\"tech-item\"><span class=\"tech-num\">01</span><div><div class=\"tech-title\">Establish a Baseline</div><div class=\"tech-desc\">Know how someone acts when calm before judging deviations. One gesture means nothing — context is everything.</div></div></div>\n    <div class=\"tech-item\"><span class=\"tech-num\">02</span><div><div class=\"tech-title\">Look for Clusters</div><div class=\"tech-desc\">A single behavior is unreliable. 2–3 congruent signals form a real pattern you can trust.</div></div></div>\n    <div class=\"tech-item\"><span class=\"tech-num\">03</span><div><div class=\"tech-title\">Watch for Juxtaposition</div><div class=\"tech-desc\">When words and body contradict, believe the body. Nonverbal leaks are subconscious and honest.</div></div></div>\n    <div class=\"tech-item\"><span class=\"tech-num\">04</span><div><div class=\"tech-title\">Detect Sudden Changes</div><div class=\"tech-desc\">A shift in behavior = a shift in emotional state. That moment is where the truth lives.</div></div></div>\n    <div class=\"tech-item\"><span class=\"tech-num\">05</span><div><div class=\"tech-title\">Listen for What's Not Said</div><div class=\"tech-desc\">Pauses, omissions, deflections, and vague language reveal more than the words themselves.</div></div></div>\n    <div class=\"tech-item\"><span class=\"tech-num\">06</span><div><div class=\"tech-title\">Read the Eyes First</div><div class=\"tech-desc\">The eyes are the most expressive feature. Pupils, blinking, and gaze direction are windows into internal state.</div></div></div>\n  </div>\n\n  <!--  QUIZ  -->\n  <h2 class=\"section-heading reveal\"><span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 20h9\"></path><path d=\"M16.5 3.5a2.121 2.121 0 0 1 3 3L7 19l-4 1 1-4L16.5 3.5z\"></path></svg></span> <span class=\"gradient\">What's Your Perception Style?</span></h2>\n  <p style=\"color:var(--text-dim);font-size:0.9rem;margin-bottom:0.8rem;\" class=\"reveal\">Answer each question honestly — discover how you see the world.</p>\n  <div class=\"quiz-container reveal\">\n    <div id=\"quiz-app\">\n      <div class=\"quiz-question\" id=\"q-text\">Loading...</div>\n      <div class=\"quiz-options\" id=\"q-options\"></div>\n      <div class=\"quiz-nav\">\n        <button id=\"q-prev\" disabled=\"\">← Previous</button>\n        <span id=\"q-counter\" style=\"font-size:0.8rem;color:var(--text-muted)\">1 / 5</span>\n        <button id=\"q-next\">Next →</button>\n      </div>\n      <div class=\"quiz-result\" id=\"q-result\"></div>\n    </div>\n  </div>\n\n  <!--  MATCHING GAME  -->\n  <h2 class=\"section-heading reveal\"><span class=\"icon\">🧩</span> <span class=\"gradient\">Social Cues Matching Game</span></h2>\n  <p style=\"color:var(--text-dim);font-size:0.9rem;margin-bottom:0.8rem;\" class=\"reveal\">Match each gesture to its meaning. Click a gesture then click its matching meaning.</p>\n  <div class=\"match-game reveal\">\n    <div class=\"match-status\" id=\"match-status\">Match: 0 / 6</div>\n    <div class=\"match-grid\" id=\"match-grid\"></div>\n    <button class=\"match-reset\" id=\"match-reset\">↻ Reset Game</button>\n  </div>\n\n  <!--  EXERCISES  -->\n  <h2 class=\"section-heading reveal\"><span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"13 2 3 14 12 14 11 22 21 10 12 10 13 2\"></polygon></svg></span> <span class=\"gradient\">Practical Exercises</span></h2>\n  <p style=\"color:var(--text-dim);font-size:0.9rem;margin-bottom:0.8rem;\" class=\"reveal\">Sharpen your perception with daily drills.</p>\n  <div class=\"reveal\">\n    <div class=\"ex-card\">\n      <span class=\"ex-num\">Exercise 1</span>\n      <h4>The People-Watching Audit</h4>\n      <p>Spend 5 minutes in a public space. Observe one person from feet to face. What do their feet say? Their hands? Their eyes? Write three observations.</p>\n    </div>\n    <div class=\"ex-card\">\n      <span class=\"ex-num\">Exercise 2</span>\n      <h4>The Contradiction Hunt</h4>\n      <p>In your next conversation, look for mismatches between words and body. Someone says \"I'm fine\" but has crossed arms and averted eyes. Note these juxtapositions.</p>\n    </div>\n    <div class=\"ex-card\">\n      <span class=\"ex-num\">Exercise 3</span>\n      <h4>The Silence Game</h4>\n      <p>In a conversation, let silence hang for 5 seconds. Watch what the other person does with their body during the pause. People reveal themselves in silence.</p>\n    </div>\n    <div class=\"ex-card\">\n      <span class=\"ex-num\">Exercise 4</span>\n      <h4>Emotional Labeling Drill</h4>\n      <p>Watch a movie or show on mute. Pause every 30 seconds and label the emotion of each character. Then replay with sound to check your accuracy.</p>\n    </div>\n  </div>\n\n  <!--  QUOTES  -->\n  <h2 class=\"section-heading reveal\"><span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 18h6\"></path><path d=\"M10 22h4\"></path><path d=\"M15.09 14c.92-.83 1.61-1.95 1.91-3.23C17.52 8.2 15.54 6 13 6c-2.54 0-4.52 2.2-4 4.77.3 1.28.99 2.4 1.91 3.23\"></path><path d=\"M8 14.5A5.5 5.5 0 0 0 16 14\"></path><path d=\"M3 15c0 1.5 1.1 2.5 2 3\"></path><path d=\"M21 15c0 1.5-1.1 2.5-2 3\"></path></svg></span> <span class=\"gradient\">Insights &amp; Quotes</span></h2>\n  <div class=\"reveal\">\n    <div class=\"quote-box\"><p>\"You don't hear what people say — you hear what they mean. And meaning lives in the body, not the mouth.\"</p><div class=\"quote-author\">— Patrick King</div></div>\n    <div class=\"quote-box\"><p>\"The greatest skill in reading people is learning to listen with your eyes.\"</p><div class=\"quote-author\">— Patrick King</div></div>\n    <div class=\"quote-box\"><p>\"Emotional intelligence isn't about being nice. It's about being accurate.\"</p><div class=\"quote-author\">— Patrick King</div></div>\n    <div class=\"quote-box\"><p>\"People tell you who they are — not with words, but with patterns. Learn to see the pattern.\"</p><div class=\"quote-author\">— Patrick King</div></div>\n    <div class=\"quote-box\"><p>\"The more you understand yourself, the less mysterious others become.\"</p><div class=\"quote-author\">— Patrick King</div></div>\n    <div class=\"quote-box\"><p>\"To read people is to see past the performance and witness the person.\"</p><div class=\"quote-author\">— Patrick King</div></div>\n  </div>\n\n  <!--  FOOTER  -->\n  \n\n</div>\n\n<script>\n  //  Pulse Canvas \n  const canvas = document.getElementById('pulse-canvas');\n  const ctx = canvas.getContext('2d');\n  let w, h, time = 0, particles = [];\n  let mouse = { x: -1000, y: -1000 };\n\n  function resize() {\n    w = canvas.width = window.innerWidth;\n    h = canvas.height = document.documentElement.scrollHeight;\n  }\n  resize();\n  window.addEventListener('resize', resize);\n  window.addEventListener('scroll', resize);\n  document.addEventListener('mousemove', e => { mouse.x = e.clientX; mouse.y = e.clientY + window.scrollY; });\n\n  class Particle {\n    constructor() { this.reset(); }\n    reset() {\n      this.x = Math.random() * w;\n      this.y = Math.random() * h;\n      this.sx = (Math.random() - 0.5) * 0.2;\n      this.sy = (Math.random() - 0.5) * 0.2;\n      this.s = Math.random() * 2 + 0.5;\n      this.o = Math.random() * 0.2 + 0.03;\n      this.pulse = Math.random() * Math.PI * 2;\n    }\n    update() {\n      this.pulse += 0.02;\n      this.x += this.sx + Math.sin(this.pulse) * 0.1;\n      this.y += this.sy + Math.cos(this.pulse) * 0.1;\n      const dx = mouse.x - this.x, dy = mouse.y - this.y;\n      const d = Math.sqrt(dx * dx + dy * dy);\n      if (d < 120) { this.x -= dx * 0.002; this.y -= dy * 0.002; }\n      if (this.x < -20 || this.x > w + 20 || this.y < -20 || this.y > h + 20) this.reset();\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.s, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(42, 175, 143, ${this.o * (0.6 + 0.4 * Math.sin(this.pulse))})`;\n      ctx.fill();\n    }\n  }\n  for (let i = 0; i < 60; i++) particles.push(new Particle());\n\n  function drawConnections() {\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const d = Math.sqrt(dx * dx + dy * dy);\n        if (d < 100) {\n          ctx.beginPath();\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.strokeStyle = `rgba(122, 58, 181, ${0.025 * (1 - d / 100)})`;\n          ctx.lineWidth = 0.5;\n          ctx.stroke();\n        }\n      }\n    }\n  }\n\n  function animate() {\n    time += 0.005;\n    ctx.clearRect(0, 0, w, h);\n\n    // pulse rings from center\n    const cx = w / 2, cy = h / 2;\n    for (let r = 0; r < 3; r++) {\n      const radius = 80 + ((time * 30 + r * 120) % 400);\n      const alpha = 0.03 * (1 - radius / 400);\n      ctx.beginPath();\n      ctx.arc(cx, cy, radius, 0, Math.PI * 2);\n      ctx.strokeStyle = `rgba(42, 175, 143, ${alpha})`;\n      ctx.lineWidth = 1.5;\n      ctx.stroke();\n    }\n\n    particles.forEach(p => { p.update(); p.draw(); });\n    drawConnections();\n    requestAnimationFrame(animate);\n  }\n  animate();\n\n  //  Theme Toggle \n  const toggle = document.getElementById('theme-toggle');\n  let lightMode = false;\n  toggle.addEventListener('click', () => {\n    lightMode = !lightMode;\n    document.body.classList.toggle('light-mode', lightMode);\n    toggle.innerHTML = lightMode ? '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"/></svg>️' : '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>';\n    localStorage.setItem('rplab-theme', lightMode ? 'light' : 'dark');\n  });\n  if (localStorage.getItem('rplab-theme') === 'light') toggle.click();\n\n  //  Scroll Progress \n  const progress = document.getElementById('progress');\n  window.addEventListener('scroll', () => {\n    const h = document.documentElement.scrollHeight - window.innerHeight;\n    progress.style.width = h > 0 ? (window.scrollY / h * 100) + '%' : '0%';\n  });\n\n  //  Scroll Reveal \n  const observer = new IntersectionObserver(entries => {\n    entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); });\n  }, { threshold: 0.1 });\n  document.querySelectorAll('.reveal').forEach(el => observer.observe(el));\n\n  //  Quiz \n  const quizQuestions = [\n    {\n      q: 'You walk into a room full of strangers. What do you do first?',\n      options: [\n        { t: 'Scan the room — watch people before engaging', p: 'Observer' },\n        { t: 'Walk up and introduce yourself to someone', p: 'Connector' },\n        { t: 'Find a corner and assess who seems safe', p: 'Protector' },\n        { t: 'Notice the vibe — music, lighting, energy', p: 'Sensate' }\n      ]\n    },\n    {\n      q: 'A friend says \"I\\'m fine\" but their arms are crossed and they won\\'t look at you. You:',\n      options: [\n        { t: 'Gently say you notice they seem off — ask again', p: 'Empath' },\n        { t: 'Respect the boundary — they\\'ll talk when ready', p: 'Patience' },\n        { t: 'Mentally note the contradiction for later', p: 'Analyst' },\n        { t: 'Change the subject to ease the tension', p: 'Harmonizer' }\n      ]\n    },\n    {\n      q: 'What draws your attention most in a conversation?',\n      options: [\n        { t: 'Tone of voice and word choice', p: 'Linguist' },\n        { t: 'Facial expressions and eye movements', p: 'Visualizer' },\n        { t: 'Posture, gestures, and body positioning', p: 'Kinesthetic' },\n        { t: 'The emotional atmosphere between you', p: 'Resonator' }\n      ]\n    },\n    {\n      q: 'Someone is telling a story but their feet keep turning toward the door. You think:',\n      options: [\n        { t: 'They\\'re uncomfortable or want to leave', p: 'Decoder' },\n        { t: 'Maybe they\\'re just shifting position', p: 'Skeptic' },\n        { t: 'They need a reason to feel safe here', p: 'Caregiver' },\n        { t: 'The story is probably a distraction', p: 'Detective' }\n      ]\n    },\n    {\n      q: 'When you misread someone, you usually:',\n      options: [\n        { t: 'Analyze what you missed and adjust', p: 'Learner' },\n        { t: 'Feel bad and try to repair the connection', p: 'Healer' },\n        { t: 'Blame yourself for not paying enough attention', p: 'Perfectionist' },\n        { t: 'Make a mental note and move on', p: 'Pragmatist' }\n      ]\n    }\n  ];\n\n  let qIdx = 0, qAnswers = [];\n  const qText = document.getElementById('q-text');\n  const qOptions = document.getElementById('q-options');\n  const qPrev = document.getElementById('q-prev');\n  const qNext = document.getElementById('q-next');\n  const qCounter = document.getElementById('q-counter');\n  const qResult = document.getElementById('q-result');\n\n  function renderQuiz() {\n    const q = quizQuestions[qIdx];\n    qText.textContent = q.q;\n    qOptions.innerHTML = '';\n    q.q.options.forEach((o, i) => {\n      const btn = document.createElement('button');\n      btn.className = 'quiz-option';\n      if (qAnswers[qIdx] === i) btn.classList.add('selected');\n      btn.textContent = o.t;\n      btn.addEventListener('click', () => {\n        document.querySelectorAll('.quiz-option').forEach(b => b.classList.remove('selected'));\n        btn.classList.add('selected');\n        qAnswers[qIdx] = i;\n      });\n      qOptions.appendChild(btn);\n    });\n    qCounter.textContent = `${qIdx + 1} / ${quizQuestions.length}`;\n    qPrev.disabled = qIdx === 0;\n    qNext.textContent = qIdx === quizQuestions.length - 1 ? 'See Results' : 'Next →';\n    qResult.classList.remove('show');\n    qResult.style.display = 'none';\n  }\n\n  qPrev.addEventListener('click', () => { if (qIdx > 0) { qIdx--; renderQuiz(); } });\n  qNext.addEventListener('click', () => {\n    if (qIdx < quizQuestions.length - 1) { qIdx++; renderQuiz(); }\n    else showQuizResult();\n  });\n\n  function showQuizResult() {\n    const score = qAnswers.filter(a => a !== undefined).length;\n    const topTraits = qAnswers.map((a, i) => a !== undefined ? quizQuestions[i].options[a].p : null).filter(Boolean);\n    const freq = {};\n    topTraits.forEach(t => { freq[t] = (freq[t] || 0) + 1; });\n    const sorted = Object.entries(freq).sort((a, b) => b[1] - a[1]);\n    const primary = sorted.length > 0 ? sorted[0][0] : 'Balanced Observer';\n\n    const descs = {\n      'Observer': 'You watch before you act. You notice details others miss. Your superpower is patience — you let people reveal themselves.',\n      'Connector': 'You read people through engagement. Your warmth draws others out. Your superpower is rapport — people feel safe with you.',\n      'Protector': 'You\\'re wired for safety assessment. You detect threat and discomfort quickly. Your superpower is vigilance.',\n      'Sensate': 'You absorb the full sensory picture — mood, atmosphere, energy. Your superpower is environmental perception.',\n      'Empath': 'You feel what others feel. Your emotional attunement is rare. Your superpower is deep connection.',\n      'Patience': 'You respect people\\'s timing. You don\\'t push — you wait. Your superpower is creating space for truth.',\n      'Analyst': 'You collect data. Contradictions, patterns, clusters — you compute. Your superpower is objective clarity.',\n      'Harmonizer': 'You keep the peace by reading the room. Your superpower is social flow.',\n      'Linguist': 'You hear what people say and what they avoid saying. Words are your map. Your superpower is verbal precision.',\n      'Visualizer': 'You see what the face broadcasts. Expressions are your language. Your superpower is emotional sight.',\n      'Kinesthetic': 'You read posture and presence. Body position tells you everything. Your superpower is spatial intelligence.',\n      'Resonator': 'You tune into the emotional frequency between people. Your superpower is relational depth.',\n      'Decoder': 'You translate behavior into meaning naturally. Your superpower is instant insight.',\n      'Skeptic': 'You question before concluding. You avoid false reads. Your superpower is accuracy through doubt.',\n      'Caregiver': 'You read people because you want to help. Your superpower is compassionate perception.',\n      'Detective': 'You look for what\\'s hidden. Discrepancies are clues. Your superpower is seeing through facades.',\n      'Learner': 'Every misread is a lesson. You grow constantly. Your superpower is adaptive intelligence.',\n      'Healer': 'You read to repair and connect. Your superpower is emotional restoration.',\n      'Perfectionist': 'You hold yourself to high standards of perception. Your superpower is conscientious attention.',\n      'Pragmatist': 'You read enough to function, then move forward. Your superpower is efficient social navigation.',\n      'Balanced Observer': 'You blend multiple styles. You\\'re flexible, adaptive, and see people from many angles at once.'\n    };\n\n    qResult.innerHTML = `\n      <h4 style=\"background:var(--gradient-hero);-webkit-background-clip:text;-webkit-text-fill-color:transparent;background-clip:text;\">Your Primary Style: ${primary}</h4>\n      <p>${descs[primary] || 'You have a unique, multifaceted perception style.'}</p>\n      <p style=\"margin-top:0.6rem;font-size:0.8rem;color:var(--text-muted);\">You answered ${score}/${quizQuestions.length} questions.</p>\n    `;\n    qResult.style.display = 'block';\n    qResult.classList.add('show');\n    qPrev.style.display = 'none';\n    qNext.style.display = 'none';\n    qCounter.style.display = 'none';\n  }\n\n  renderQuiz();\n\n  //  Matching Game \n  const matchData = [\n    { gesture: 'Crossed Arms', meaning: 'Defensiveness / Barrier' },\n    { gesture: 'Steepled Fingers', meaning: 'Confidence / Authority' },\n    { gesture: 'Feet Pointing Away', meaning: 'Desire to Leave' },\n    { gesture: 'Palm Up Gestures', meaning: 'Openness / Honesty' },\n    { gesture: 'Lip Compression', meaning: 'Stress / Suppressed Anger' },\n    { gesture: 'Head Tilt', meaning: 'Interest / Trust' }\n  ];\n\n  let matchGame = { selected: null, matched: new Set(), left: [], right: [] };\n  const matchGrid = document.getElementById('match-grid');\n  const matchStatus = document.getElementById('match-status');\n\n  function shuffle(a) { for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [a[i], a[j]] = [a[j], a[i]]; } return a; }\n\n  function initMatch() {\n    matchGame.matched = new Set();\n    matchGame.selected = null;\n    matchGame.left = shuffle(matchData.map((d, i) => ({ ...d, id: i, side: 'left' })));\n    matchGame.right = shuffle(matchData.map((d, i) => ({ ...d, id: i, side: 'right' })));\n    renderMatch();\n  }\n\n  function renderMatch() {\n    matchGrid.innerHTML = '';\n    const all = shuffle([...matchGame.left, ...matchGame.right]);\n    all.forEach(item => {\n      const el = document.createElement('div');\n      el.className = 'match-item';\n      if (matchGame.matched.has(item.id)) el.classList.add('matched');\n      el.dataset.id = item.id;\n      el.dataset.side = item.side;\n      el.textContent = item.side === 'left' ? item.gesture : item.meaning;\n      el.addEventListener('click', () => handleMatchClick(el, item));\n      matchGrid.appendChild(el);\n    });\n    matchStatus.textContent = `Match: ${matchGame.matched.size} / ${matchData.length}`;\n  }\n\n  function handleMatchClick(el, item) {\n    if (matchGame.matched.has(item.id)) return;\n    if (matchGame.selected === null) {\n      matchGame.selected = { el, item };\n      el.classList.add('selected');\n      return;\n    }\n    const sel = matchGame.selected;\n    if (sel.item.id === item.id && sel.item.side !== item.side) {\n      // correct match\n      matchGame.matched.add(item.id);\n      sel.el.classList.remove('selected');\n      sel.el.classList.add('matched');\n      el.classList.add('matched');\n      matchGame.selected = null;\n      matchStatus.textContent = `Match: ${matchGame.matched.size} / ${matchData.length}`;\n      if (matchGame.matched.size === matchData.length) {\n        setTimeout(() => {\n          matchStatus.innerHTML = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg> All matched! You\\'re a natural observer.';\n        }, 300);\n      }\n    } else {\n      // wrong\n      sel.el.classList.remove('selected');\n      sel.el.classList.add('wrong');\n      el.classList.add('wrong');\n      matchGame.selected = null;\n      setTimeout(() => {\n        document.querySelectorAll('.match-item.wrong').forEach(e => e.classList.remove('wrong'));\n      }, 500);\n    }\n  }\n\n  document.getElementById('match-reset').addEventListener('click', initMatch);\n  initMatch();\n\n  //  Scanline refresh for resize \n  window.addEventListener('resize', resize);\n</script>\n\n\n\n</body>\n</html>",
  "rich-dad-poor-dad": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n\n\n<canvas id=\"bgCanvas\"></canvas>\n<div id=\"noise\"></div>\n<div id=\"mouseGlow\"></div>\n\n<!--  HERO  -->\n\n\n<!--  STATS  -->\n<section>\n  <div class=\"section-label\">Core Principles</div>\n  <h2>The <span class=\"hl\">Foundation</span></h2>\n  <p class=\"section-desc\">The key ideas that form the backbone of financial literacy.</p>\n  <div class=\"stats-grid\">\n    <div class=\"stat-card\"><span class=\"s-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 1v22M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6\"></path></svg></span><div class=\"s-val\">Assets</div><div class=\"s-label\">Put Money In Your Pocket</div><div class=\"s-sub\">Buy income-producing assets</div></div>\n    <div class=\"stat-card\"><span class=\"s-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"></path><polyline points=\"17 8 12 3 7 8\"></polyline><line x1=\"12\" y1=\"3\" x2=\"12\" y2=\"15\"></line></svg></span><div class=\"s-val\">Liabilities</div><div class=\"s-label\">Take Money Out</div><div class=\"s-sub\">Avoid the debt trap</div></div>\n    <div class=\"stat-card\"><span class=\"s-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9l1-8z\"></path></svg></span><div class=\"s-val\">Rat Race</div><div class=\"s-label\">The Trap</div><div class=\"s-sub\">Work · Spend · Repeat</div></div>\n    <div class=\"stat-card\"><span class=\"s-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"18\" y1=\"20\" x2=\"18\" y2=\"10\"></line><line x1=\"12\" y1=\"20\" x2=\"12\" y2=\"4\"></line><line x1=\"6\" y1=\"20\" x2=\"6\" y2=\"14\"></line></svg></span><div class=\"s-val\">4 Quadrants</div><div class=\"s-label\">E · S · B · I</div><div class=\"s-sub\">Move to the right side</div></div>\n    <div class=\"stat-card\"><span class=\"s-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\"></path><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"></line></svg></span><div class=\"s-val\">Mindset</div><div class=\"s-label\">The Difference</div><div class=\"s-sub\">Rich think differently</div></div>\n    <div class=\"stat-card\"><span class=\"s-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z\"></path></svg></span><div class=\"s-val\">Financial IQ</div><div class=\"s-label\">The Goal</div><div class=\"s-sub\">Make money work for you</div></div>\n  </div>\n</section>\n\n<!--  THE 6 LESSONS  -->\n<section id=\"lessons\">\n  <div class=\"section-label\">The Six Lessons</div>\n  <h2>What <span class=\"hl\">Rich Dad</span> Taught</h2>\n  <p class=\"section-desc\">Six transformative lessons that challenge everything you thought you knew about money. Click to expand each lesson.</p>\n  <div class=\"lessons-grid\" id=\"lessonsGrid\"></div>\n</section>\n\n<!--  ASSETS VS LIABILITIES  -->\n<section>\n  <div class=\"section-label\">Interactive Sorter</div>\n  <h2>Asset or <span class=\"hl\">Liability</span>?</h2>\n  <p class=\"section-desc\">Click each item to sort it. An asset puts money in your pocket. A liability takes money out. Rich Dad's simplest rule.</p>\n  <div class=\"avs-section\" id=\"avsSection\">\n    <div class=\"avs-intro\"><strong>Click</strong> each item below to move it from the pool into the correct bucket.</div>\n    <div id=\"avsPoolContainer\">\n      <div class=\"avs-pool-title\">Drag or Click to Sort</div>\n      <div class=\"avs-pool\" id=\"avsPool\"></div>\n    </div>\n    <div class=\"avs-buckets\" style=\"margin-top:1rem;\">\n      <div class=\"avs-bucket asset-bucket\" id=\"assetBucket\">\n        <h4><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg> Asset</h4>\n        <div class=\"avs-items\" id=\"assetItems\"></div>\n      </div>\n      <div class=\"avs-vs\">VS</div>\n      <div class=\"avs-bucket liability-bucket\" id=\"liabilityBucket\">\n        <h4><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 6L6 18M6 6l12 12\"></path></svg> Liability</h4>\n        <div class=\"avs-items\" id=\"liabilityItems\"></div>\n      </div>\n    </div>\n    <div class=\"avs-feedback\" id=\"avsFeedback\"></div>\n  </div>\n</section>\n\n<!--  FINANCIAL STATEMENT  -->\n<section>\n  <div class=\"section-label\">Visual Builder</div>\n  <h2>Your <span class=\"hl\">Financial Statement</span></h2>\n  <p class=\"section-desc\">Adjust the sliders to see how your financial health changes. The rich focus on the asset column.</p>\n  <div class=\"fin-section\" id=\"finSection\">\n    <div class=\"fin-builder\">\n      <div class=\"fin-col income-col\">\n        <h4>Income Statement</h4>\n        <div id=\"incomeRows\"></div>\n      </div>\n      <div class=\"fin-col expense-col\">\n        <h4>Expenses</h4>\n        <div id=\"expenseRows\"></div>\n      </div>\n    </div>\n    <div class=\"fin-total-bar\" id=\"finTotalBar\">\n      Monthly Cash Flow: <span class=\"good\" id=\"finCashflow\">$0</span>\n    </div>\n    <div class=\"fin-builder\" style=\"margin-top:1rem;\">\n      <div class=\"fin-col asset-col\">\n        <h4>Assets</h4>\n        <div id=\"assetRows\"></div>\n      </div>\n      <div class=\"fin-col liability-col\">\n        <h4>Liabilities</h4>\n        <div id=\"liabilityRows\"></div>\n      </div>\n    </div>\n    <div class=\"fin-total-bar\" style=\"border-color:var(--gold);\">\n      Net Worth: <span class=\"good\" id=\"finNetWorth\">$0</span>\n    </div>\n  </div>\n</section>\n\n<!--  CASHFLOW QUADRANT  -->\n<section>\n  <div class=\"section-label\">The CASHFLOW Quadrant</div>\n  <h2>Which Side <span class=\"hl\">Are You On</span>?</h2>\n  <p class=\"section-desc\">Four types of people. The rich operate on the right side (B and I). Click each quadrant to learn more.</p>\n  <div class=\"quad-section\" id=\"quadSection\">\n    <div class=\"quad-grid\">\n      <div class=\"quad-item q-e\" data-quad=\"e\">\n        <div class=\"q-letter\">E</div>\n        <div class=\"q-name\">Employee</div>\n        <div class=\"q-desc\">I want job security and a steady paycheck.</div>\n        <div class=\"q-arrow\">+</div>\n        <div class=\"q-detail\"><div class=\"q-detail-inner\">Employees value security and benefits. They trade time for money. When they stop working, the income stops. They are the largest quadrant — and the least financially free.</div></div>\n      </div>\n      <div class=\"quad-item q-s\" data-quad=\"s\">\n        <div class=\"q-letter\">S</div>\n        <div class=\"q-name\">Self-Employed</div>\n        <div class=\"q-desc\">I want to be my own boss and do things my way.</div>\n        <div class=\"q-arrow\">+</div>\n        <div class=\"q-detail\"><div class=\"q-detail-inner\">Self-employed own their job. They are the best workers but the worst bosses — they still trade time for money, just on their own terms. They are often \"owned by their business.\"</div></div>\n      </div>\n      <div class=\"quad-item q-b\" data-quad=\"b\">\n        <div class=\"q-letter\">B</div>\n        <div class=\"q-name\">Business Owner</div>\n        <div class=\"q-desc\">I build systems that work for me, not the other way around.</div>\n        <div class=\"q-arrow\">+</div>\n        <div class=\"q-detail\"><div class=\"q-detail-inner\">Business owners own a system that works without them. They leverage other people's time and money. A B can leave their business for a year and return to find it more profitable.</div></div>\n      </div>\n      <div class=\"quad-item q-i\" data-quad=\"i\">\n        <div class=\"q-letter\">I</div>\n        <div class=\"q-name\">Investor</div>\n        <div class=\"q-desc\">I make money work for me. Money works, I don't.</div>\n        <div class=\"q-arrow\">+</div>\n        <div class=\"q-detail\"><div class=\"q-detail-inner\">Investors make money from investments. They don't work for money — their money works for them. This is the ultimate quadrant of financial freedom. Rich Dad's goal: E → S → B → I.</div></div>\n      </div>\n    </div>\n    <div class=\"quad-arrow-path\">→ → →</div>\n    <div class=\"quad-desc\">\n      <strong>The path to financial freedom:</strong> Move from the left side (E and S) to the right side (B and I). The right side is where your money works <em>for</em> you, not the other way around.\n    </div>\n  </div>\n</section>\n\n<!--  RAT RACE  -->\n<section>\n  <div class=\"section-label\">The Rat Race</div>\n  <h2>Escaping the <span class=\"hl\">Rat Race</span></h2>\n  <p class=\"section-desc\">The endless cycle of working for money and spending it all — and how to break free.</p>\n  <div class=\"ratrace-section\" id=\"ratraceSection\">\n    <div class=\"ratrace-visual\">\n      <svg viewBox=\"0 0 500 500\">\n        <defs>\n          <radialGradient id=\"rrGrad\"><stop offset=\"0%\" stop-color=\"var(--gold-dim)\" stop-opacity=\"0.15\"></stop><stop offset=\"100%\" stop-color=\"transparent\"></stop></radialGradient>\n        </defs>\n        <circle cx=\"250\" cy=\"250\" r=\"230\" fill=\"url(#rrGrad)\" stroke=\"var(--border)\" stroke-width=\"1\"></circle>\n        <circle cx=\"250\" cy=\"250\" r=\"180\" fill=\"none\" stroke=\"var(--gold-dim)\" stroke-width=\"0.5\" stroke-dasharray=\"4 6\"></circle>\n        <circle cx=\"250\" cy=\"250\" r=\"100\" fill=\"none\" stroke=\"var(--gold)\" stroke-width=\"0.5\" stroke-dasharray=\"2 8\"></circle>\n\n        <!-- Arrows around the circle -->\n        <g fill=\"none\" stroke=\"var(--gold-dim)\" stroke-width=\"1.5\" marker-end=\"url(#arrowhead)\">\n          <defs><marker id=\"arrowhead\" markerWidth=\"6\" markerHeight=\"4\" refX=\"6\" refY=\"2\" orient=\"auto\"><polygon points=\"0 0,6 2,0 4\" fill=\"var(--gold-dim)\"></polygon></marker></defs>\n        </g>\n\n        <!-- Rat Race path arrows -->\n        <path d=\"M 250 30 A 220 220 0 1 1 249.9 30\" fill=\"none\" stroke=\"var(--gold-dim)\" stroke-width=\"1.5\" stroke-dasharray=\"6 8\" id=\"rrPath\"></path>\n        <path d=\"M 250 50 A 200 200 0 1 1 249.9 50\" fill=\"none\" stroke=\"var(--border-light)\" stroke-width=\"0.5\"></path>\n\n        <!-- Station labels -->\n        <text x=\"250\" y=\"70\" text-anchor=\"middle\" fill=\"var(--text-dim)\" font-size=\"11\" font-family=\"Inter,sans-serif\">Get Job</text>\n        <text x=\"390\" y=\"160\" text-anchor=\"middle\" fill=\"var(--text-dim)\" font-size=\"11\" font-family=\"Inter,sans-serif\">Earn Paycheck</text>\n        <text x=\"380\" y=\"380\" text-anchor=\"middle\" fill=\"var(--text-dim)\" font-size=\"11\" font-family=\"Inter,sans-serif\">Buy Stuff</text>\n        <text x=\"120\" y=\"380\" text-anchor=\"middle\" fill=\"var(--text-dim)\" font-size=\"11\" font-family=\"Inter,sans-serif\">More Debt</text>\n        <text x=\"110\" y=\"160\" text-anchor=\"middle\" fill=\"var(--text-dim)\" font-size=\"11\" font-family=\"Inter,sans-serif\">Work Harder</text>\n\n        <!-- Center label -->\n        <text x=\"250\" y=\"240\" text-anchor=\"middle\" fill=\"var(--gold)\" font-size=\"13\" font-weight=\"700\" font-family=\"Inter,sans-serif\">THE</text>\n        <text x=\"250\" y=\"260\" text-anchor=\"middle\" fill=\"var(--gold)\" font-size=\"13\" font-weight=\"700\" font-family=\"Inter,sans-serif\">RAT RACE</text>\n        <text x=\"250\" y=\"285\" text-anchor=\"middle\" fill=\"var(--text-muted)\" font-size=\"10\" font-family=\"Inter,sans-serif\">Endless Cycle</text>\n\n        <!-- Moving dot -->\n        <circle id=\"rrDot\" r=\"6\" fill=\"var(--gold)\" opacity=\"0.8\">\n          <animateMotion dur=\"6s\" repeatCount=\"indefinite\" rotate=\"auto\">\n            <mpath href=\"#rrPath\"></mpath>\n          </animateMotion>\n        </circle>\n      </svg>\n    </div>\n    <div class=\"ratrace-info\">\n      <p>The rat race is the cycle of working for money, spending it all, and needing more. The only way out: <strong>build assets that generate passive income</strong> until your asset column exceeds your expenses.</p>\n      <button class=\"rt-status\" id=\"escapeBtn\">I'm Ready to Escape →</button>\n    </div>\n  </div>\n</section>\n\n<!--  QUOTES  -->\n<section>\n  <div class=\"section-label\">Memorable Quotes</div>\n  <h2>Words That <span class=\"hl\">Stick</span></h2>\n  <p class=\"section-desc\">The most powerful ideas from Rich Dad Poor Dad, in his own words.</p>\n  <div class=\"quotes-container\" id=\"quotesContainer\"></div>\n</section>\n\n<!--  FOOTER  -->\n\n\n<script>\n  //  CANVAS PARTICLES (Dollar Signs & Chart Elements) \n  (function(){\n    const canvas = document.getElementById('bgCanvas');\n    const ctx = canvas.getContext('2d');\n    let particles = [];\n    let mouse = {x:-1000,y:-1000};\n\n    function resize(){\n      canvas.width = window.innerWidth;\n      canvas.height = window.innerHeight;\n    }\n    resize();\n    window.addEventListener('resize',resize);\n\n    const symbols = ['$','↑','↓','◆','○','★'];\n    const colors = ['rgba(255,215,0,', 'rgba(42,168,76,', 'rgba(255,215,0,'];\n\n    class Particle {\n      constructor(){\n        this.reset();\n        this.symbol = symbols[Math.floor(Math.random()*symbols.length)];\n      }\n      reset(){\n        this.x = Math.random()*canvas.width;\n        this.y = Math.random()*canvas.height;\n        this.vx = (Math.random()-0.5)*0.15;\n        this.vy = (Math.random()-0.5)*0.15 - 0.05;\n        this.size = 12 + Math.random()*18;\n        this.alpha = Math.random()*0.06 + 0.02;\n        this.color = colors[Math.floor(Math.random()*colors.length)];\n        this.rotation = Math.random()*Math.PI*2;\n        this.rotv = (Math.random()-0.5)*0.01;\n      }\n      update(){\n        this.x += this.vx;\n        this.y += this.vy;\n        this.rotation += this.rotv;\n        if(this.x < -50) this.x = canvas.width+50;\n        if(this.x > canvas.width+50) this.x = -50;\n        if(this.y < -50) this.y = canvas.height+50;\n        if(this.y > canvas.height+50) this.y = -50;\n      }\n      draw(){\n        ctx.save();\n        ctx.translate(this.x,this.y);\n        ctx.rotate(this.rotation);\n        ctx.font = `${this.size}px \"Inter\",sans-serif`;\n        ctx.fillStyle = this.color + this.alpha + ')';\n        ctx.textAlign = 'center';\n        ctx.textBaseline = 'middle';\n        ctx.fillText(this.symbol,0,0);\n        ctx.restore();\n      }\n    }\n\n    for(let i=0;i<25;i++) particles.push(new Particle());\n\n    function animate(){\n      ctx.clearRect(0,0,canvas.width,canvas.height);\n\n      // Connections\n      for(let i=0;i<particles.length;i++){\n        for(let j=i+1;j<particles.length;j++){\n          const dx = particles[i].x - particles[j].x;\n          const dy = particles[i].y - particles[j].y;\n          const d = Math.sqrt(dx*dx+dy*dy);\n          if(d < 150){\n            ctx.beginPath();\n            ctx.moveTo(particles[i].x,particles[i].y);\n            ctx.lineTo(particles[j].x,particles[j].y);\n            ctx.strokeStyle = 'rgba(255,215,0,';\n            ctx.globalAlpha = 0.03*(1-d/150);\n            ctx.stroke();\n            ctx.globalAlpha = 1;\n          }\n        }\n      }\n\n      particles.forEach(p => { p.update(); p.draw(); });\n      requestAnimationFrame(animate);\n    }\n    animate();\n  })();\n\n  //  MOUSE GLOW \n  const mouseGlow = document.getElementById('mouseGlow');\n  document.addEventListener('mousemove',e => {\n    mouseGlow.style.left = e.clientX + 'px';\n    mouseGlow.style.top = e.clientY + 'px';\n  });\n\n  //  THEME TOGGLE \n  const themeToggle = document.getElementById('themeToggle');\n  themeToggle.addEventListener('click',() => {\n    document.body.classList.toggle('light');\n    themeToggle.innerHTML = document.body.classList.contains('light') ? '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>' : '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"/></svg>️';\n  });\n\n  //  SCROLL REVEAL \n  const observer = new IntersectionObserver((entries) => {\n    entries.forEach(e => {\n      if(e.isIntersecting){\n        e.target.classList.add('visible');\n      }\n    });\n  }, { threshold:0.08 });\n\n  document.querySelectorAll('.stat-card, .lesson-card, .avs-section, .fin-section, .quad-section, .ratrace-section, .quote-card').forEach(el => observer.observe(el));\n\n  //  THE 6 LESSONS \n  const lessons = [\n    { n:1, title:\"The Rich Don't Work for Money\", body:\"Money works for you when you invest in assets. The rich understand that a job is a short-term solution — true wealth comes from owning income-producing assets. Rich Dad taught that the poor and middle class work for money, while the rich have money work for them. <strong>Key insight:</strong> Your job is not your wealth — your assets are.\" },\n    { n:2, title:\"Why Teach Financial Literacy?\", body:\"Financial literacy is the ability to understand how money works. Rich Dad said: <strong>'It's not how much money you make, but how much you keep.'</strong> The rich acquire assets. The poor and middle class acquire liabilities that they think are assets. A house is not an asset if it takes money out of your pocket every month.\" },\n    { n:3, title:\"Mind Your Own Business\", body:\"Build your own asset column. Keep your day job but start acquiring real assets: businesses that don't require your presence, stocks, bonds, real estate, intellectual property. <strong>The wealthy focus on building their asset base, not on getting a raise or promotion.</strong>\" },\n    { n:4, title:\"The History of Taxes and the Power of Corporations\", body:\"The rich use corporations to protect their wealth. An employee earns, gets taxed, then spends. A corporation earns, spends on pre-tax expenses, and pays the remaining tax. <strong>The rich play the game by different rules — they use financial knowledge to legally minimize taxes.</strong>\" },\n    { n:5, title:\"The Rich Invent Money\", body:\"Wealthy people see opportunities that others miss. Financial intelligence allows you to create your own opportunities rather than waiting for them. <strong>The more opportunities you create, the more money you make — regardless of the economy.</strong> Every problem is an opportunity in disguise.\" },\n    { n:6, title:\"Work to Learn — Don't Work for Money\", body:\"Jobs are temporary learning opportunities. Look for jobs that teach skills: sales, marketing, leadership, investing. <strong>The most valuable asset is your financial intelligence, which you build through experience, not schooling.</strong> Work to learn skills that will make you wealthy, not just a paycheck.\" }\n  ];\n\n  const lessonsGrid = document.getElementById('lessonsGrid');\n  lessons.forEach((l,i) => {\n    const card = document.createElement('div');\n    card.className = 'lesson-card';\n    card.innerHTML = `\n      <div class=\"l-num\">LESSON ${l.n} OF 6</div>\n      <div class=\"l-header\">\n        <h3>${l.title}</h3>\n        <span class=\"l-toggle\">+</span>\n      </div>\n      <div class=\"l-body\">\n        <div class=\"l-body-inner\"><p>${l.body}</p></div>\n      </div>\n    `;\n    card.addEventListener('click',() => {\n      card.classList.toggle('open');\n    });\n    lessonsGrid.appendChild(card);\n    observer.observe(card);\n  });\n\n  //  ASSETS VS LIABILITIES SORTER \n  const items = [\n    { name:\"Rental Property (Income > Expenses)\", type:\"asset\" },\n    { name:\"Stocks That Pay Dividends\", type:\"asset\" },\n    { name:\"Your Primary Residence (With Mortgage)\", type:\"liability\" },\n    { name:\"Car Loan / Car Payment\", type:\"liability\" },\n    { name:\"Bonds Paying Interest\", type:\"asset\" },\n    { name:\"Credit Card Debt\", type:\"liability\" },\n    { name:\"A Business You Don't Manage\", type:\"asset\" },\n    { name:\"Student Loans\", type:\"liability\" },\n    { name:\"Royalties from a Book\", type:\"asset\" },\n    { name:\"Mortgage on Rental (Tenant Pays)\", type:\"asset\" },\n    { name:\"Personal Mortgage (You Pay)\", type:\"liability\" },\n    { name:\"Intellectual Property (Patents)\", type:\"asset\" },\n    { name:\"Collectibles That Appreciate\", type:\"asset\" },\n    { name:\"Personal Car (Depreciating)\", type:\"liability\" },\n    { name:\"401(k) / Retirement Account\", type:\"asset\" },\n    { name:\"Vacation Home (Personal Use)\", type:\"liability\" }\n  ];\n\n  const pool = document.getElementById('avsPool');\n  const assetItems = document.getElementById('assetItems');\n  const liabilityItems = document.getElementById('liabilityItems');\n  const feedback = document.getElementById('avsFeedback');\n  const assetBucket = document.getElementById('assetBucket');\n  const liabilityBucket = document.getElementById('liabilityBucket');\n  let activeDrag = null;\n\n  function renderAVS(){\n    pool.innerHTML = '';\n    assetItems.innerHTML = '';\n    liabilityItems.innerHTML = '';\n\n    const uncategorized = items.filter(i => !i.placed);\n    const assets = items.filter(i => i.placed === 'asset');\n    const liabilities = items.filter(i => i.placed === 'liability');\n\n    if(uncategorized.length === 0 && assets.length === 0 && liabilities.length === 0){\n      pool.innerHTML = '<div style=\"text-align:center;padding:1rem;color:var(--text-muted);font-size:0.8rem;\">All items sorted!</div>';\n    }\n\n    uncategorized.forEach((item,i) => {\n      const el = document.createElement('div');\n      el.className = 'avs-item uncategorized';\n      el.textContent = item.name;\n      el.dataset.index = items.indexOf(item);\n      el.style.animationDelay = (i*30)+'ms';\n      el.addEventListener('click',() => {\n        item.placed = item.type;\n        feedback.innerHTML = item.type === 'asset'\n          ? '<strong>Correct!</strong> That puts money in your pocket.'\n          : '<strong>Correct!</strong> That takes money out of your pocket.';\n        renderAVS();\n      });\n      pool.appendChild(el);\n    });\n\n    assets.forEach(item => {\n      const el = document.createElement('div');\n      el.className = 'avs-item in-asset';\n      el.textContent = item.name;\n      el.addEventListener('click',() => {\n        item.placed = false;\n        feedback.innerHTML = 'Moved back to the pool — rethink it.';\n        renderAVS();\n      });\n      assetItems.appendChild(el);\n    });\n\n    liabilities.forEach(item => {\n      const el = document.createElement('div');\n      el.className = 'avs-item in-liability';\n      el.textContent = item.name;\n      el.addEventListener('click',() => {\n        item.placed = false;\n        feedback.innerHTML = 'Moved back to the pool — rethink it.';\n        renderAVS();\n      });\n      liabilityItems.appendChild(el);\n    });\n\n    if(uncategorized.length === 0){\n      feedback.innerHTML = '<strong>All sorted!</strong> The rich focus on acquiring assets. Liabilities keep you in the rat race.';\n    }\n  }\n\n  renderAVS();\n\n  //  FINANCIAL STATEMENT BUILDER \n  const finData = {\n    income: [\n      { label:'Salary / Job Income', val:5000, min:0, max:15000, step:100 },\n      { label:'Business Income', val:0, min:0, max:20000, step:100 },\n      { label:'Investment Income', val:0, min:0, max:10000, step:100 },\n      { label:'Rental Income', val:0, min:0, max:10000, step:100 }\n    ],\n    expenses: [\n      { label:'Rent / Mortgage', val:1500, min:0, max:5000, step:50 },\n      { label:'Car Payment', val:400, min:0, max:2000, step:50 },\n      { label:'Credit Card Minimums', val:200, min:0, max:2000, step:25 },\n      { label:'Food & Utilities', val:600, min:0, max:2000, step:25 },\n      { label:'Other Expenses', val:500, min:0, max:3000, step:50 }\n    ],\n    assetsList: [\n      { label:'Savings / Checking', val:5000, min:0, max:100000, step:500 },\n      { label:'Stocks & Bonds', val:10000, min:0, max:500000, step:1000 },\n      { label:'Real Estate Equity', val:0, min:0, max:500000, step:1000 },\n      { label:'Business Value', val:0, min:0, max:500000, step:1000 },\n      { label:'Retirement Accounts', val:15000, min:0, max:500000, step:1000 }\n    ],\n    liabilitiesList: [\n      { label:'Mortgage Balance', val:200000, min:0, max:500000, step:5000 },\n      { label:'Car Loan Balance', val:15000, min:0, max:50000, step:1000 },\n      { label:'Credit Card Debt', val:5000, min:0, max:50000, step:500 },\n      { label:'Student Loans', val:0, min:0, max:100000, step:1000 },\n      { label:'Other Debt', val:0, min:0, max:50000, step:1000 }\n    ]\n  };\n\n  function renderFin(){\n    const incomeRows = document.getElementById('incomeRows');\n    const expenseRows = document.getElementById('expenseRows');\n    const assetRows = document.getElementById('assetRows');\n    const liabilityRows = document.getElementById('liabilityRows');\n\n    let totalIncome = 0;\n    let totalExpenses = 0;\n    let totalAssets = 0;\n    let totalLiabilities = 0;\n\n    function buildSlider(item,container,type){\n      const wrap = document.createElement('div');\n      wrap.className = 'fin-row';\n      const valDisplay = document.createElement('span');\n      valDisplay.className = 'fin-val';\n      valDisplay.textContent = '$' + item.val.toLocaleString();\n\n      const fmtLabel = item.label.includes('(Income)') ? item.label.replace(' (Income)','') : item.label;\n      wrap.innerHTML = `<span class=\"fin-label\">${fmtLabel}</span>`;\n      wrap.appendChild(valDisplay);\n\n      const sliderWrap = document.createElement('div');\n      sliderWrap.style.cssText = 'grid-column:1/-1;margin:-0.3rem 0 0.3rem;';\n      const input = document.createElement('input');\n      input.type = 'range';\n      input.className = 'fin-slider';\n      input.min = item.min;\n      input.max = item.max;\n      input.step = item.step;\n      input.value = item.val;\n      input.addEventListener('input',() => {\n        item.val = parseInt(input.value);\n        renderFin();\n      });\n      sliderWrap.appendChild(input);\n      wrap.appendChild(sliderWrap);\n\n      if(type === 'income') totalIncome += item.val;\n      if(type === 'expense') totalExpenses += item.val;\n      if(type === 'asset') totalAssets += item.val;\n      if(type === 'liability') totalLiabilities += item.val;\n\n      return wrap;\n    }\n\n    incomeRows.innerHTML = '';\n    expenseRows.innerHTML = '';\n    assetRows.innerHTML = '';\n    liabilityRows.innerHTML = '';\n\n    finData.income.forEach(item => incomeRows.appendChild(buildSlider(item,null,'income')));\n    finData.expenses.forEach(item => expenseRows.appendChild(buildSlider(item,null,'expense')));\n\n    // Total row income\n    const incTotal = document.createElement('div');\n    incTotal.className = 'fin-row total-row';\n    incTotal.innerHTML = `<span class=\"fin-label\">Total Income</span><span class=\"fin-val\">$${totalIncome.toLocaleString()}</span>`;\n    incomeRows.appendChild(incTotal);\n\n    const expTotal = document.createElement('div');\n    expTotal.className = 'fin-row total-row';\n    expTotal.innerHTML = `<span class=\"fin-label\">Total Expenses</span><span class=\"fin-val\">$${totalExpenses.toLocaleString()}</span>`;\n    expenseRows.appendChild(expTotal);\n\n    finData.assetsList.forEach(item => assetRows.appendChild(buildSlider(item,null,'asset')));\n    finData.liabilitiesList.forEach(item => liabilityRows.appendChild(buildSlider(item,null,'liability')));\n\n    const aTotal = document.createElement('div');\n    aTotal.className = 'fin-row total-row';\n    aTotal.innerHTML = `<span class=\"fin-label\">Total Assets</span><span class=\"fin-val\">$${totalAssets.toLocaleString()}</span>`;\n    assetRows.appendChild(aTotal);\n\n    const lTotal = document.createElement('div');\n    lTotal.className = 'fin-row total-row';\n    lTotal.innerHTML = `<span class=\"fin-label\">Total Liabilities</span><span class=\"fin-val\">$${totalLiabilities.toLocaleString()}</span>`;\n    liabilityRows.appendChild(lTotal);\n\n    // Cash flow\n    const cashflow = totalIncome - totalExpenses;\n    const cfEl = document.getElementById('finCashflow');\n    cfEl.textContent = (cashflow >= 0 ? '+' : '') + '$' + cashflow.toLocaleString() + '/mo';\n    cfEl.className = cashflow > 0 ? 'good' : cashflow < 0 ? 'bad' : 'neutral';\n\n    // Net worth\n    const netWorth = totalAssets - totalLiabilities;\n    const nwEl = document.getElementById('finNetWorth');\n    nwEl.textContent = (netWorth >= 0 ? '+' : '') + '$' + netWorth.toLocaleString();\n    nwEl.className = netWorth > 0 ? 'good' : netWorth < 0 ? 'bad' : 'neutral';\n\n    // Update total bar description\n    const bar = document.getElementById('finTotalBar');\n    let status = '';\n    if(cashflow > 2000) status = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M8.5 14.5A2.5 2.5 0 0 0 11 12c0-1.38-.5-2-1-3-1.072-2.143-.224-4.054 2-6 .5 2.5 2 4.9 4 6.5 2 1.6 3 3.5 3 5.5a7 7 0 1 1-14 0c0-1.153.433-2.294 1-3a2.5 2.5 0 0 0 2.5 2.5z\"/></svg> Strong cash flow! You\\'re building wealth.';\n    else if(cashflow > 0) status = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 11.08V12a10 10 0 1 1-5.93-9.14\"/><polyline points=\"22 4 12 14.01 9 11.01\"/></svg> Positive cash flow — keep investing in assets.';\n    else if(cashflow === 0) status = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2v20\"/><path d=\"M8 22h8\"/><path d=\"M2 6c.6.5 1.2 1 2.5 1C7 7 7 5 9.5 5c2.6 0 2.4 2 5 2 2.5 0 2.5-2 5-2 1.3 0 1.9.5 2.5 1\"/></svg>️ Breaking even. Look for ways to increase income or cut expenses.';\n    else status = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"/><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>️ Negative cash flow! You\\'re in the rat race. Reduce liabilities and build assets.';\n    bar.innerHTML = `Monthly Cash Flow: <span class=\"${cfEl.className}\">${(cashflow >= 0 ? '+' : '') + '$' + cashflow.toLocaleString()}</span> &mdash; ${status}`;\n  }\n\n  renderFin();\n\n  //  CASHFLOW QUADRANT CLICK \n  document.querySelectorAll('.quad-item').forEach(item => {\n    item.addEventListener('click',() => {\n      item.classList.toggle('open');\n    });\n  });\n\n  //  ESCAPE BUTTON \n  const escapeBtn = document.getElementById('escapeBtn');\n  let escapeCount = 0;\n  escapeBtn.addEventListener('click',() => {\n    escapeCount++;\n    if(escapeCount === 1){\n      escapeBtn.innerHTML = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> Step 1: Start tracking your expenses';\n    } else if(escapeCount === 2){\n      escapeBtn.innerHTML = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> Step 2: Start buying assets, not liabilities';\n    } else if(escapeCount === 3){\n      escapeBtn.innerHTML = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"/></svg> Step 3: Let your assets pay for your lifestyle';\n    } else if(escapeCount === 4){\n      escapeBtn.innerHTML = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"/></svg> You\\'ve escaped the Rat Race! <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"/></svg>';\n      escapeBtn.classList.add('active');\n    } else {\n      escapeBtn.innerHTML = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"/></svg> Already free — help others escape too <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"/></svg>';\n    }\n  });\n\n  //  QUOTES \n  const quotes = [\n    { text:\"The poor and middle class work for money. The rich have money work for them.\", cite:\"Rich Dad\" },\n    { text:\"It's not how much money you make, but how much money you keep, how hard it works for you, and how many generations you keep it for.\", cite:\"Rich Dad\" },\n    { text:\"An asset is something that puts money in my pocket. A liability is something that takes money out of my pocket.\", cite:\"Rich Dad, Lesson 2\" },\n    { text:\"The single most powerful asset we all have is our mind. If it is trained well, it can create enormous wealth.\", cite:\"Robert T. Kiyosaki\" },\n    { text:\"The rich don't work for money. They know how to make money work for them. That's the difference between being rich and being poor.\", cite:\"Rich Dad\" },\n    { text:\"Financial struggle is often the result of people working for everyone else. They work for the company, the government, and the bank.\", cite:\"Rich Dad, Lesson 4\" },\n    { text:\"The size of your problem is the size of your success. Most people are afraid of losing, and that fear limits their potential.\", cite:\"Rich Dad\" },\n    { text:\"Inside of every problem lies an opportunity. The problem is that people see the problem and stop. They don't see the opportunity.\", cite:\"Robert T. Kiyosaki\" },\n    { text:\"Job is an acronym for 'Just Over Broke.' The wealthy don't work for a paycheck — they build systems.\", cite:\"Rich Dad\" }\n  ];\n\n  const quotesContainer = document.getElementById('quotesContainer');\n  quotes.forEach(q => {\n    const card = document.createElement('div');\n    card.className = 'quote-card';\n    card.innerHTML = `<blockquote>${q.text}</blockquote><cite>— ${q.cite}</cite>`;\n    quotesContainer.appendChild(card);\n    observer.observe(card);\n  });\n\n  //  NAVIGATE TO LESSONS \n  document.querySelectorAll('.stat-card').forEach((card,i) => {\n    card.addEventListener('click',() => {\n      if(i < 4){\n        document.getElementById('lessons').scrollIntoView({behavior:'smooth'});\n      }\n    });\n    card.style.cursor = 'pointer';\n  });\n</script>\n\n\n\n\n</body>\n</html>",
  "surrounded-by-idiots": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<canvas id=\"bgCanvas\"></canvas>\n\n\n\n<!--  HERO  -->\n\n\n<!--  STATS  -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-label reveal\">Overview</div>\n    <h2 class=\"reveal reveal-d1\">The <span class=\"disc-r\">D</span><span class=\"disc-y\">I</span><span class=\"disc-g\">S</span><span class=\"disc-b\">C</span> Model at a Glance</h2>\n    <p class=\"section-desc reveal reveal-d2\">Four behavioral types that explain how people think, act, and communicate. Each has unique strengths, blind spots, and communication keys.</p>\n    <div class=\"stats reveal reveal-d3\" id=\"statsContainer\">\n      <div class=\"stat\"><div class=\"stat-value\">4</div><div class=\"stat-label\">Behavioral Types</div></div>\n      <div class=\"stat\"><div class=\"stat-value\">20+</div><div class=\"stat-label\">Key Traits</div></div>\n      <div class=\"stat\"><div class=\"stat-value\">~80%</div><div class=\"stat-label\">Population Blend</div></div>\n      <div class=\"stat\"><div class=\"stat-value\">1</div><div class=\"stat-label\">Framework to Understand All</div></div>\n    </div>\n  </div>\n</section>\n\n<!--  DISC TYPE CARDS  -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-label reveal\">The Four Types</div>\n    <h2 class=\"reveal reveal-d1\">Who Are You <span class=\"disc-r\">S</span><span class=\"disc-y\">u</span><span class=\"disc-g\">r</span><span class=\"disc-b\">r</span><span class=\"disc-r\">o</span><span class=\"disc-y\">u</span><span class=\"disc-g\">n</span><span class=\"disc-b\">d</span><span class=\"disc-r\">e</span><span class=\"disc-y\">d</span> By?</h2>\n    <p class=\"section-desc reveal reveal-d2\">Click any card to explore the type in depth.</p>\n    <div class=\"disc-cards reveal reveal-d3\">\n\n      <!-- RED -->\n      <div class=\"disc-card card-red\" data-type=\"red\">\n        <div class=\"card-head\">\n          <div class=\"card-icon\">D</div>\n          <div class=\"card-type\">Red</div>\n          <div class=\"card-label\">Dominant · Driver</div>\n        </div>\n        <div class=\"card-traits\">\n          <span>Decisive</span><span>Direct</span><span>Demanding</span><span>Results-driven</span><span>Competitive</span>\n        </div>\n        <div class=\"card-expand\">\n          <p><strong>Core Motivation:</strong> Results, control, efficiency. Reds want action and measurable progress. They are natural leaders who thrive on challenges.</p>\n          <p><strong>Under Stress:</strong> Becomes dictatorial, impatient, and may steamroll others. Needs autonomy and tangible wins.</p>\n          <p><strong>Blind Spot:</strong> Can be insensitive, overly aggressive, and dismissive of others' feelings.</p>\n          <span class=\"expand-toggle\">Explore <span class=\"arrow\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span></span>\n        </div>\n      </div>\n\n      <!-- YELLOW -->\n      <div class=\"disc-card card-yellow\" data-type=\"yellow\">\n        <div class=\"card-head\">\n          <div class=\"card-icon\">I</div>\n          <div class=\"card-type\">Yellow</div>\n          <div class=\"card-label\">Influential · Inspirer</div>\n        </div>\n        <div class=\"card-traits\">\n          <span>Enthusiastic</span><span>Outgoing</span><span>Creative</span><span>Persuasive</span><span>Optimistic</span>\n        </div>\n        <div class=\"card-expand\">\n          <p><strong>Core Motivation:</strong> Recognition, social connection, fun. Yellows energize teams and generate big ideas through charisma.</p>\n          <p><strong>Under Stress:</strong> Becomes disorganized, overly emotional, and may exaggerate. Needs praise and social interaction.</p>\n          <p><strong>Blind Spot:</strong> Can be impulsive, poor with details, and struggles with follow-through.</p>\n          <span class=\"expand-toggle\">Explore <span class=\"arrow\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span></span>\n        </div>\n      </div>\n\n      <!-- GREEN -->\n      <div class=\"disc-card card-green\" data-type=\"green\">\n        <div class=\"card-head\">\n          <div class=\"card-icon\">S</div>\n          <div class=\"card-type\">Green</div>\n          <div class=\"card-label\">Stable · Supporter</div>\n        </div>\n        <div class=\"card-traits\">\n          <span>Patient</span><span>Loyal</span><span>Calm</span><span>Team-oriented</span><span>Good listener</span>\n        </div>\n        <div class=\"card-expand\">\n          <p><strong>Core Motivation:</strong> Security, harmony, belonging. Greens are the glue that holds teams together. They value deep relationships.</p>\n          <p><strong>Under Stress:</strong> Becomes overly accommodating, passive, and avoids conflict at all costs. Needs stability and appreciation.</p>\n          <p><strong>Blind Spot:</strong> Resists change, may be too indirect, and struggles with assertiveness.</p>\n          <span class=\"expand-toggle\">Explore <span class=\"arrow\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span></span>\n        </div>\n      </div>\n\n      <!-- BLUE -->\n      <div class=\"disc-card card-blue\" data-type=\"blue\">\n        <div class=\"card-head\">\n          <div class=\"card-icon\">C</div>\n          <div class=\"card-type\">Blue</div>\n          <div class=\"card-label\">Conscientious · Analyst</div>\n        </div>\n        <div class=\"card-traits\">\n          <span>Analytical</span><span>Precise</span><span>Systematic</span><span>Detail-oriented</span><span>Logical</span>\n        </div>\n        <div class=\"card-expand\">\n          <p><strong>Core Motivation:</strong> Accuracy, quality, order. Blues ensure things are done right. They are the quality controllers of any team.</p>\n          <p><strong>Under Stress:</strong> Becomes overly critical, withdraws, and may get paralyzed by analysis. Needs data and clear processes.</p>\n          <p><strong>Blind Spot:</strong> Can be overly perfectionist, cold, and slow to act due to overthinking.</p>\n          <span class=\"expand-toggle\">Explore <span class=\"arrow\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span></span>\n        </div>\n      </div>\n\n    </div>\n  </div>\n</section>\n\n<!--  DISC COLOR WHEEL  -->\n<section>\n  <div class=\"container color-wheel-section\">\n    <div class=\"section-label reveal\">Color Dynamics</div>\n    <h2 class=\"reveal reveal-d1\">The DISC <span class=\"disc-r\">C</span><span class=\"disc-y\">o</span><span class=\"disc-g\">l</span><span class=\"disc-b\">o</span><span class=\"disc-r\">r</span> <span class=\"disc-y\">W</span><span class=\"disc-g\">h</span><span class=\"disc-b\">e</span><span class=\"disc-r\">e</span><span class=\"disc-y\">l</span></h2>\n    <p class=\"section-desc reveal reveal-d2\">Each color represents a distinct behavioral dimension. Hover or tap to explore how they relate.</p>\n    <div class=\"wheel-container reveal reveal-d3\">\n      <svg class=\"wheel-svg\" viewBox=\"0 0 300 300\">\n        <defs>\n          <filter id=\"shadow1\"><fedropshadow dx=\"0\" dy=\"2\" stdDeviation=\"4\" flood-opacity=\"0.25\"></fedropshadow></filter>\n        </defs>\n        <g class=\"wheel-arc\" data-color=\"red\" onclick=\"focusColor('red')\">\n          <path class=\"wheel-arc-path\" d=\"M150,150 L150,30 A120,120 0 0,1 264.85,95.36 Z\" fill=\"#E74C3C\" filter=\"url(#shadow1)\"></path>\n          <text class=\"wheel-label\" x=\"215\" y=\"75\">D</text>\n        </g>\n        <g class=\"wheel-arc\" data-color=\"yellow\" onclick=\"focusColor('yellow')\">\n          <path class=\"wheel-arc-path\" d=\"M150,150 L264.85,95.36 A120,120 0 0,1 264.85,204.64 Z\" fill=\"#F1C40F\" filter=\"url(#shadow1)\"></path>\n          <text class=\"wheel-label\" style=\"fill:#333\" x=\"240\" y=\"150\">I</text>\n        </g>\n        <g class=\"wheel-arc\" data-color=\"green\" onclick=\"focusColor('green')\">\n          <path class=\"wheel-arc-path\" d=\"M150,150 L264.85,204.64 A120,120 0 0,1 150,270 Z\" fill=\"#2ECC71\" filter=\"url(#shadow1)\"></path>\n          <text class=\"wheel-label\" x=\"215\" y=\"235\">S</text>\n        </g>\n        <g class=\"wheel-arc\" data-color=\"blue\" onclick=\"focusColor('blue')\">\n          <path class=\"wheel-arc-path\" d=\"M150,150 L150,270 A120,120 0 0,1 35.15,204.64 L150,150 Z\" fill=\"#3498DB\" filter=\"url(#shadow1)\"></path>\n          <text class=\"wheel-label\" x=\"75\" y=\"235\">C</text>\n        </g>\n      </svg>\n      <div class=\"wheel-center\">\n        <strong>DISC</strong>\n        <small>Behavioral DNA</small>\n      </div>\n    </div>\n    <div class=\"wheel-labels reveal reveal-d4\" id=\"wheelLabels\">\n      <div class=\"wheel-label-item\" onclick=\"focusColor('red')\">\n        <span class=\"dot\" style=\"background:var(--red)\"></span>\n        <div class=\"info\"><strong>Red · Dominant</strong><small>Direct, results-oriented</small></div>\n      </div>\n      <div class=\"wheel-label-item\" onclick=\"focusColor('yellow')\">\n        <span class=\"dot\" style=\"background:var(--yellow)\"></span>\n        <div class=\"info\"><strong>Yellow · Influential</strong><small>Social, enthusiastic</small></div>\n      </div>\n      <div class=\"wheel-label-item\" onclick=\"focusColor('green')\">\n        <span class=\"dot\" style=\"background:var(--green)\"></span>\n        <div class=\"info\"><strong>Green · Stable</strong><small>Supportive, reliable</small></div>\n      </div>\n      <div class=\"wheel-label-item\" onclick=\"focusColor('blue')\">\n        <span class=\"dot\" style=\"background:var(--blue)\"></span>\n        <div class=\"info\"><strong>Blue · Conscientious</strong><small>Analytical, precise</small></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!--  COMPARISON  -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-label reveal\">Side by Side</div>\n    <h2 class=\"reveal reveal-d1\">Behavior <span class=\"disc-r\">C</span><span class=\"disc-y\">o</span><span class=\"disc-g\">m</span><span class=\"disc-b\">p</span><span class=\"disc-r\">a</span><span class=\"disc-y\">r</span><span class=\"disc-g\">i</span><span class=\"disc-b\">s</span><span class=\"disc-r\">o</span><span class=\"disc-y\">n</span></h2>\n    <p class=\"section-desc reveal reveal-d2\">Filter to compare any combination of types across key behavioral dimensions.</p>\n    <div class=\"compare-controls reveal reveal-d3\">\n      <button class=\"compare-btn all active\" data-filter=\"all\" onclick=\"filterCompare('all')\">All</button>\n      <button class=\"compare-btn\" data-filter=\"red\" onclick=\"filterCompare('red')\" style=\"border-color:var(--red);color:var(--red)\">Red</button>\n      <button class=\"compare-btn\" data-filter=\"yellow\" onclick=\"filterCompare('yellow')\" style=\"border-color:#b8860b;color:#b8860b\">Yellow</button>\n      <button class=\"compare-btn\" data-filter=\"green\" onclick=\"filterCompare('green')\" style=\"border-color:#1a8a4e;color:#1a8a4e\">Green</button>\n      <button class=\"compare-btn\" data-filter=\"blue\" onclick=\"filterCompare('blue')\" style=\"border-color:#1a6da0;color:#1a6da0\">Blue</button>\n    </div>\n    <div class=\"compare-grid reveal reveal-d4\" id=\"compareGrid\">\n      <div class=\"compare-row\"><div class=\"trait-label\">Pace</div><div class=\"trait-values\"><div class=\"trait-val r-val\">Fast, urgent</div><div class=\"trait-val y-val\">Fast, energetic</div><div class=\"trait-val g-val\">Slow, steady</div><div class=\"trait-val b-val\">Slow, methodical</div></div></div>\n      <div class=\"compare-row\"><div class=\"trait-label\">Priority</div><div class=\"trait-values\"><div class=\"trait-val r-val\">Results</div><div class=\"trait-val y-val\">Relationships</div><div class=\"trait-val g-val\">Harmony</div><div class=\"trait-val b-val\">Accuracy</div></div></div>\n      <div class=\"compare-row\"><div class=\"trait-label\">Communication</div><div class=\"trait-values\"><div class=\"trait-val r-val\">Direct, blunt</div><div class=\"trait-val y-val\">Expressive, stories</div><div class=\"trait-val g-val\">Diplomatic, warm</div><div class=\"trait-val b-val\">Precise, factual</div></div></div>\n      <div class=\"compare-row\"><div class=\"trait-label\">Decision-making</div><div class=\"trait-values\"><div class=\"trait-val r-val\">Quick, instinctive</div><div class=\"trait-val y-val\">Spontaneous, gut</div><div class=\"trait-val g-val\">Consultative, slow</div><div class=\"trait-val b-val\">Data-driven, careful</div></div></div>\n      <div class=\"compare-row\"><div class=\"trait-label\">Conflict style</div><div class=\"trait-values\"><div class=\"trait-val r-val\">Confronts directly</div><div class=\"trait-val y-val\">Emotional, loud</div><div class=\"trait-val g-val\">Avoids, accommodates</div><div class=\"trait-val b-val\">Logical debate</div></div></div>\n      <div class=\"compare-row\"><div class=\"trait-label\">Fear</div><div class=\"trait-values\"><div class=\"trait-val r-val\">Losing control</div><div class=\"trait-val y-val\">Social rejection</div><div class=\"trait-val g-val\">Sudden change</div><div class=\"trait-val b-val\">Being wrong</div></div></div>\n      <div class=\"compare-row\"><div class=\"trait-label\">Energy source</div><div class=\"trait-values\"><div class=\"trait-val r-val\">Winning, achieving</div><div class=\"trait-val y-val\">People, recognition</div><div class=\"trait-val g-val\">Stability, belonging</div><div class=\"trait-val b-val\">Knowledge, order</div></div></div>\n    </div>\n  </div>\n</section>\n\n<!--  COMMUNICATION TIPS  -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-label reveal\">Communication</div>\n    <h2 class=\"reveal reveal-d1\">How to Talk to Each <span class=\"disc-r\">T</span><span class=\"disc-y\">y</span><span class=\"disc-g\">p</span><span class=\"disc-b\">e</span></h2>\n    <p class=\"section-desc reveal reveal-d2\">Click a card to reveal detailed communication strategies for each behavioral type.</p>\n    <div class=\"comms-grid reveal reveal-d3\">\n\n      <div class=\"comms-card card-red\">\n        <div class=\"comms-header\">\n          <div class=\"comms-icon\">D</div>\n          <h3>Communicating with <span style=\"color:var(--red)\">Reds</span></h3>\n        </div>\n        <ul class=\"comms-do\">\n          <li>Be direct and concise — get to the point</li>\n          <li>Focus on results and efficiency</li>\n          <li>Give them options and let them decide</li>\n        </ul>\n        <ul class=\"comms-dont\">\n          <li>Don't waste time with small talk</li>\n          <li>Don't be vague or ambiguous</li>\n        </ul>\n        <div class=\"comms-details\">\n          <p style=\"font-size:0.82rem;color:var(--text-dim);line-height:1.6\">Reds respect competence and brevity. Lead with the bottom line, then provide supporting details if asked. Challenge them respectfully — they respect those who stand their ground. Frame your message in terms of goals, outcomes, and competitive advantage.</p>\n        </div>\n        <span class=\"comms-toggle\">Details <span class=\"arrow\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span></span>\n      </div>\n\n      <div class=\"comms-card card-yellow\">\n        <div class=\"comms-header\">\n          <div class=\"comms-icon\">I</div>\n          <h3>Communicating with <span style=\"color:#b8860b\">Yellows</span></h3>\n        </div>\n        <ul class=\"comms-do\">\n          <li>Be enthusiastic and energetic</li>\n          <li>Show appreciation and recognition</li>\n          <li>Use stories and visual examples</li>\n        </ul>\n        <ul class=\"comms-dont\">\n          <li>Don't bore them with excessive details</li>\n          <li>Don't dismiss their ideas harshly</li>\n        </ul>\n        <div class=\"comms-details\">\n          <p style=\"font-size:0.82rem;color:var(--text-dim);line-height:1.6\">Yellows thrive on enthusiasm and social connection. Start with the big picture vision, share testimonials or stories, and give them public recognition. They need to feel inspired. Follow up in writing to ensure details aren't lost in the excitement.</p>\n        </div>\n        <span class=\"comms-toggle\">Details <span class=\"arrow\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span></span>\n      </div>\n\n      <div class=\"comms-card card-green\">\n        <div class=\"comms-header\">\n          <div class=\"comms-icon\">S</div>\n          <h3>Communicating with <span style=\"color:#1a8a4e\">Greens</span></h3>\n        </div>\n        <ul class=\"comms-do\">\n          <li>Show genuine care and listen actively</li>\n          <li>Provide stability and clear expectations</li>\n          <li>Give them time to process</li>\n        </ul>\n        <ul class=\"comms-dont\">\n          <li>Don't push for quick decisions</li>\n          <li>Don't be aggressive or confrontational</li>\n        </ul>\n        <div class=\"comms-details\">\n          <p style=\"font-size:0.82rem;color:var(--text-dim);line-height:1.6\">Greens value trust and relationships above all. Take time to build rapport before getting to business. Ask about their well-being, listen patiently, and explain how changes will affect the team. Reassure them about job security and stability.</p>\n        </div>\n        <span class=\"comms-toggle\">Details <span class=\"arrow\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span></span>\n      </div>\n\n      <div class=\"comms-card card-blue\">\n        <div class=\"comms-header\">\n          <div class=\"comms-icon\">C</div>\n          <h3>Communicating with <span style=\"color:#1a6da0\">Blues</span></h3>\n        </div>\n        <ul class=\"comms-do\">\n          <li>Present data, facts, and evidence</li>\n          <li>Be precise, logical, and well-organized</li>\n          <li>Give them time to analyze thoroughly</li>\n        </ul>\n        <ul class=\"comms-dont\">\n          <li>Don't exaggerate or make emotional appeals</li>\n          <li>Don't rush their decision-making process</li>\n        </ul>\n        <div class=\"comms-details\">\n          <p style=\"font-size:0.82rem;color:var(--text-dim);line-height:1.6\">Blues are driven by logic and accuracy. Prepare thoroughly before meeting — bring data, citations, and well-structured arguments. Anticipate their questions and address potential flaws proactively. Respect their need for quality and precision.</p>\n        </div>\n        <span class=\"comms-toggle\">Details <span class=\"arrow\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span></span>\n      </div>\n\n    </div>\n  </div>\n</section>\n\n<!--  STRENGTHS & WEAKNESSES  -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-label reveal\">Growth</div>\n    <h2 class=\"reveal reveal-d1\"><span class=\"disc-g\">Strengths</span> &amp; <span class=\"disc-r\">Weaknesses</span></h2>\n    <p class=\"section-desc reveal reveal-d2\">Every type brings brilliance and blind spots. Understanding both is the key to growth.</p>\n    <div class=\"sw-section reveal reveal-d3\">\n      <div class=\"sw-col\">\n        <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.5 2A2.5 2.5 0 0 1 17 4.5V8\"></path><path d=\"M17 15v2.5a2.5 2.5 0 0 1-2.5 2.5\"></path><path d=\"M2 8h12a2 2 0 0 1 2 2v2\"></path><path d=\"M2 14h8\"></path><path d=\"M14 14h2a2 2 0 0 1 2 2v3a2 2 0 0 1-2 2h-2\"></path><path d=\"M8 20h2\"></path></svg> Strengths <span class=\"count\">(12)</span></h3>\n        <div class=\"sw-item\"><span class=\"sw-letter\" style=\"background:var(--red)\">D</span><span class=\"sw-text\"><strong>Red:</strong> Decisiveness, leadership, drive, ability to get results quickly</span></div>\n        <div class=\"sw-item\"><span class=\"sw-letter\" style=\"background:var(--yellow)\">I</span><span class=\"sw-text\"><strong>Yellow:</strong> Charisma, optimism, creativity, ability to inspire and motivate</span></div>\n        <div class=\"sw-item\"><span class=\"sw-letter\" style=\"background:var(--green)\">S</span><span class=\"sw-text\"><strong>Green:</strong> Patience, reliability, empathy, team cohesion and loyalty</span></div>\n        <div class=\"sw-item\"><span class=\"sw-letter\" style=\"background:var(--blue)\">C</span><span class=\"sw-text\"><strong>Blue:</strong> Precision, analytical thinking, quality focus, systematic approach</span></div>\n      </div>\n      <div class=\"sw-col\">\n        <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"></path><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"></line><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"></line></svg>️ Weaknesses <span class=\"count\">(12)</span></h3>\n        <div class=\"sw-item\"><span class=\"sw-letter\" style=\"background:var(--red)\">D</span><span class=\"sw-text\"><strong>Red:</strong> Impatience, insensitivity, dictatorial under stress, poor listener</span></div>\n        <div class=\"sw-item\"><span class=\"sw-letter\" style=\"background:var(--yellow)\">I</span><span class=\"sw-text\"><strong>Yellow:</strong> Disorganization, impulsiveness, poor follow-through, exaggeration</span></div>\n        <div class=\"sw-item\"><span class=\"sw-letter\" style=\"background:var(--green)\">S</span><span class=\"sw-text\"><strong>Green:</strong> Resistance to change, indirectness, avoids conflict, too passive</span></div>\n        <div class=\"sw-item\"><span class=\"sw-letter\" style=\"background:var(--blue)\">C</span><span class=\"sw-text\"><strong>Blue:</strong> Over-analysis, perfectionism, coldness, slow decision-making</span></div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!--  QUOTES  -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-label reveal\">Insights</div>\n    <h2 class=\"reveal reveal-d1\">Quotes from the <span class=\"disc-r\">B</span><span class=\"disc-y\">o</span><span class=\"disc-g\">o</span><span class=\"disc-b\">k</span></h2>\n    <p class=\"section-desc reveal reveal-d2\">Timeless wisdom on understanding the people around you.</p>\n    <div class=\"quotes-grid reveal reveal-d3\">\n      <div class=\"quote-card\">\n        <div class=\"quote-mark\">\"</div>\n        <blockquote>People are not \"idiots\" — they're just different from you. And your way of functioning is not the only way.</blockquote>\n        <cite>— Thomas Erikson</cite>\n      </div>\n      <div class=\"quote-card\">\n        <div class=\"quote-mark\">\"</div>\n        <blockquote>The ability to see the world through someone else's eyes is the greatest gift you can give yourself.</blockquote>\n        <cite>— Thomas Erikson</cite>\n      </div>\n      <div class=\"quote-card\">\n        <div class=\"quote-mark\">\"</div>\n        <blockquote>A Red's motto: \"My way is the fastest way.\" A Blue's motto: \"My way is the right way.\"</blockquote>\n        <cite>— Thomas Erikson</cite>\n      </div>\n      <div class=\"quote-card\">\n        <div class=\"quote-mark\">\"</div>\n        <blockquote>If you want to reach someone, you have to meet them where they are — not where you want them to be.</blockquote>\n        <cite>— Thomas Erikson</cite>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!--  FOOTER  -->\n\n\n<script>\n//  PARTICLE BACKGROUND \n(function(){\n  const c = document.getElementById('bgCanvas');\n  const ctx = c.getContext('2d');\n  let w, h, particles = [];\n\n  function resize() {\n    w = c.width = window.innerWidth;\n    h = c.height = window.innerHeight;\n  }\n  resize();\n  window.addEventListener('resize', resize);\n\n  const COLORS = ['#E74C3C','#F1C40F','#2ECC71','#3498DB'];\n  const COUNT = 50;\n\n  for (let i = 0; i < COUNT; i++) {\n    particles.push({\n      x: Math.random() * w,\n      y: Math.random() * h,\n      r: 2 + Math.random() * 6,\n      dx: (Math.random() - 0.5) * 0.6,\n      dy: (Math.random() - 0.5) * 0.6,\n      color: COLORS[Math.floor(Math.random() * COLORS.length)],\n      alpha: 0.1 + Math.random() * 0.3,\n      pulse: Math.random() * Math.PI * 2,\n    });\n  }\n\n  function draw() {\n    ctx.clearRect(0, 0, w, h);\n    particles.forEach(p => {\n      p.x += p.dx;\n      p.y += p.dy;\n      p.pulse += 0.008;\n      if (p.x < 0 || p.x > w) p.dx *= -1;\n      if (p.y < 0 || p.y > h) p.dy *= -1;\n      const alpha = p.alpha * (0.7 + 0.3 * Math.sin(p.pulse));\n      ctx.beginPath();\n      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);\n      ctx.fillStyle = p.color;\n      ctx.globalAlpha = alpha;\n      ctx.fill();\n      // connection lines\n      particles.forEach(p2 => {\n        const dx = p.x - p2.x;\n        const dy = p.y - p2.y;\n        const dist = Math.sqrt(dx*dx + dy*dy);\n        if (dist < 150) {\n          ctx.beginPath();\n          ctx.moveTo(p.x, p.y);\n          ctx.lineTo(p2.x, p2.y);\n          ctx.strokeStyle = p.color;\n          ctx.globalAlpha = alpha * 0.15 * (1 - dist/150);\n          ctx.lineWidth = 0.5;\n          ctx.stroke();\n        }\n      });\n    });\n    ctx.globalAlpha = 1;\n    requestAnimationFrame(draw);\n  }\n  draw();\n})();\n\n//  THEME TOGGLE \n(function(){\n  const btn = document.getElementById('themeToggle');\n  let dark = localStorage.getItem('disc-theme') === 'dark';\n  if (dark) document.body.classList.add('dark');\n  btn.innerHTML = dark ? '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"/></svg>️' : '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>';\n\n  btn.addEventListener('click', () => {\n    dark = !dark;\n    document.body.classList.toggle('dark', dark);\n    btn.innerHTML = dark ? '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"/></svg>️' : '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>';\n    localStorage.setItem('disc-theme', dark ? 'dark' : 'light');\n  });\n})();\n\n//  SCROLL REVEAL \n(function(){\n  const els = document.querySelectorAll('.reveal');\n  const observer = new IntersectionObserver(entries => {\n    entries.forEach(e => {\n      if (e.isIntersecting) { e.target.classList.add('visible'); }\n    });\n  }, { threshold: 0.1 });\n  els.forEach(el => observer.observe(el));\n})();\n\n//  DISC CARD EXPAND \ndocument.querySelectorAll('.disc-card').forEach(card => {\n  card.addEventListener('click', () => {\n    card.classList.toggle('open');\n  });\n});\n\n//  COMMUNICATION CARD EXPAND \ndocument.querySelectorAll('.comms-card').forEach(card => {\n  card.addEventListener('click', () => {\n    card.classList.toggle('open');\n  });\n});\n\n//  COMPARISON FILTER \nfunction filterCompare(filter) {\n  const btns = document.querySelectorAll('.compare-btn');\n  btns.forEach(b => {\n    b.classList.remove('active', 'active-r', 'active-y', 'active-g', 'active-b');\n    if (b.dataset.filter === filter) {\n      b.classList.add('active');\n      if (filter !== 'all') b.classList.add('active-' + filter);\n    }\n    if (filter === 'all' && b.dataset.filter === 'all') {\n      b.classList.add('active');\n    }\n  });\n  const rows = document.querySelectorAll('.compare-row .trait-values');\n  rows.forEach(row => {\n    row.querySelectorAll('.trait-val').forEach(val => {\n      if (filter === 'all') { val.classList.remove('hide'); return; }\n      val.classList.toggle('hide', !val.classList.contains(filter + '-val'));\n    });\n  });\n}\n// start with all visible\nfilterCompare('all');\n\n//  COLOR WHEEL FOCUS \nfunction focusColor(color) {\n  const labels = document.querySelectorAll('.wheel-label-item');\n  const arcs = document.querySelectorAll('.wheel-arc');\n  const colors = { red: '#E74C3C', yellow: '#F1C40F', green: '#2ECC71', blue: '#3498DB' };\n  const names = { red: 'Dominant', yellow: 'Influential', green: 'Stable', blue: 'Conscientious' };\n\n  arcs.forEach(a => {\n    const path = a.querySelector('.wheel-arc-path');\n    const isTarget = a.dataset.color === color;\n    path.style.opacity = isTarget ? '1' : '0.3';\n    if (isTarget) {\n      path.style.transform = 'scale(1.05)';\n      path.style.transformOrigin = '150px 150px';\n      path.style.transition = 'all 0.3s';\n    } else {\n      path.style.transform = 'scale(1)';\n    }\n  });\n  labels.forEach(l => {\n    const isTarget = l.querySelector('.dot').style.backgroundColor === colors[color] ||\n                     l.textContent.toLowerCase().includes(color);\n    l.style.opacity = isTarget ? '1' : '0.4';\n  });\n\n  // scroll to wheel labels\n  document.getElementById('wheelLabels').scrollIntoView({ behavior: 'smooth', block: 'nearest' });\n}\n</script>\n\n\n\n\n</body>\n</html>",
  "surrounded-by-psychopaths": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n<div class=\"noise\"></div>\n\n\n\n<!-- Hero -->\n\n\n<!-- Stats -->\n<section>\n  <div class=\"container\">\n    <div class=\"stats-grid\">\n      <div class=\"stat-card reveal\"><div class=\"stat-number\">~1%</div><div class=\"stat-label\">of the general population meets the criteria for <strong>psychopathy</strong></div></div>\n      <div class=\"stat-card reveal\"><div class=\"stat-number\">3</div><div class=\"stat-label\">personality types form the <strong>Dark Triad</strong></div></div>\n      <div class=\"stat-card reveal\"><div class=\"stat-number\">15–25%</div><div class=\"stat-label\">of corporate leaders show <strong>psychopathic traits</strong> above average</div></div>\n      <div class=\"stat-card reveal\"><div class=\"stat-number\">4</div><div class=\"stat-label\">DISC types — only <strong>one</strong> correlates with dark traits</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- What is a Psychopath -->\n<section>\n  <div class=\"container\">\n    <span class=\"section-label reveal\">Understanding</span>\n    <h2 class=\"section-title reveal\">What Is a Psychopath?</h2>\n    <p class=\"section-desc reveal\">Psychopathy is not a diagnosis in the DSM-5 but a construct describing a personality profile defined by a distinct set of emotional and behavioral characteristics.</p>\n    <div class=\"what-grid\">\n      <div class=\"what-card reveal\"><div class=\"icon\">🧊</div><h3>Lack of Empathy</h3><p>Complete inability to emotionally connect with or understand the feelings of others. They know the words but not the music.</p></div>\n      <div class=\"what-card reveal\"><div class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"></path><path d=\"M2 17l10 5 10-5\"></path><path d=\"M2 12l10 5 10-5\"></path></svg></div><h3>Superficial Charm</h3><p>Highly skilled at mimicking emotions and social cues. Can appear charismatic, confident, and engaging — a mask worn to manipulate.</p></div>\n      <div class=\"what-card reveal\"><div class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"></path><polyline points=\"7 10 12 15 17 10\"></polyline><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"></line></svg></div><h3>Grandiose Sense of Self-Worth</h3><p>An inflated, unrealistic view of their own importance and abilities. Rules don't apply to them; they are entitled to special treatment.</p></div>\n      <div class=\"what-card reveal\"><div class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"21\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"21\"></line><line x1=\"3\" y1=\"9\" x2=\"21\" y2=\"9\"></line><line x1=\"3\" y1=\"15\" x2=\"21\" y2=\"15\"></line></svg></div><h3>Pathological Lying</h3><p>Lying is a reflexive tool, not a last resort. They lie to manipulate, to gain advantage, and sometimes for no obvious reason at all.</p></div>\n      <div class=\"what-card reveal\"><div class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><circle cx=\"12\" cy=\"12\" r=\"6\"></circle><circle cx=\"12\" cy=\"12\" r=\"2\"></circle></svg></div><h3>Manipulative &amp; Conning</h3><p>Expert at identifying and exploiting vulnerabilities in others. They view relationships as games to be won and people as pawns.</p></div>\n      <div class=\"what-card reveal\"><div class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><line x1=\"4.93\" y1=\"4.93\" x2=\"19.07\" y2=\"19.07\"></line></svg></div><h3>Shallow Emotions</h3><p>Emotional experience is extremely shallow and short-lived. Anger and frustration may flare but deeper feelings like love, guilt, or grief are absent.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- Dark Triad -->\n<section>\n  <div class=\"container\">\n    <span class=\"section-label reveal\">The Personality Triad</span>\n    <h2 class=\"section-title reveal\">The Dark Triad</h2>\n    <p class=\"section-desc reveal\">Three distinct but overlapping personality types that share a common core of callous manipulation and self-interest. Tap each to learn more.</p>\n    <div class=\"triad-grid\">\n      <div class=\"triad-card psychopathy reveal\" data-hint=\"click to expand\" onclick=\"this.classList.toggle('active')\">\n        <span class=\"triad-icon\">🩸</span>\n        <h3>Psychopathy</h3>\n        <div class=\"triad-sub\">The Cold</div>\n        <p class=\"triad-desc\">Characterized by a lack of empathy, remorse, and emotional depth. Impulsive, antisocial behavior driven by reward-seeking. The most dangerous of the triad — these individuals can cause profound harm without a second thought. They are overrepresented in prisons but also walk among us in boardrooms and positions of power.</p>\n      </div>\n      <div class=\"triad-card narcissism reveal\" data-hint=\"click to expand\" onclick=\"this.classList.toggle('active')\">\n        <span class=\"triad-icon\">🪞</span>\n        <h3>Narcissism</h3>\n        <div class=\"triad-sub\">The Grandiose</div>\n        <p class=\"triad-desc\">An inflated sense of self-importance, a deep need for excessive attention and admiration, troubled relationships, and a lack of empathy for others. Beneath the grandiosity lies a fragile ego that cannot handle criticism. Narcissists exploit others to maintain their self-image and react with rage when challenged.</p>\n      </div>\n      <div class=\"triad-card machiavellianism reveal\" data-hint=\"click to expand\" onclick=\"this.classList.toggle('active')\">\n        <span class=\"triad-icon\">♟️</span>\n        <h3>Machiavellianism</h3>\n        <div class=\"triad-sub\">The Calculating</div>\n        <p class=\"triad-desc\">A personality style characterized by manipulation, cunning, and a strategic, calculating approach to social interactions. Unlike psychopaths, they can feel emotions but suppress them to achieve long-term goals. They view people as pieces on a chessboard and excel at strategic deception.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- DISC & Psychopathy -->\n<section>\n  <div class=\"container\">\n    <span class=\"section-label reveal\">The Link</span>\n    <h2 class=\"section-title reveal\">DISC Types &amp; Psychopathic Tendencies</h2>\n    <p class=\"section-desc reveal\">Erikson maps psychopathic traits onto the DISC model, showing how each type can manifest dark tendencies when exaggerated to the extreme.</p>\n    <div class=\"disc-section reveal\">\n      <p class=\"disc-intro\">The DISC model classifies behavior into four types. When healthy, each has strengths — but in extreme form, certain types share disturbing overlap with psychopathic traits. <strong>Click any card</strong> to see the correlation.</p>\n      <div class=\"disc-grid\">\n        <div class=\"disc-card D\" onclick=\"this.classList.toggle('active')\">\n          <div class=\"disc-letter\">D</div>\n          <div class=\"disc-name\">Dominance</div>\n          <span class=\"disc-risk high\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"></path><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"></line><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"></line></svg> High Risk</span>\n          <p class=\"disc-desc\">Direct, forceful, results-oriented — but when extreme: ruthless, remorseless, exploitative.</p>\n          <div class=\"disc-detail\"><strong>Dark Correlation:</strong> The D-type in overdrive mirrors psychopathy most closely. High dominance + low empathy = a person who treats others as obstacles. They win at all costs, feel no guilt, and see vulnerability as weakness. Many corporate psychopaths present as extreme D-types.</div>\n        </div>\n        <div class=\"disc-card I\" onclick=\"this.classList.toggle('active')\">\n          <div class=\"disc-letter\">I</div>\n          <div class=\"disc-name\">Influence</div>\n          <span class=\"disc-risk medium\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"></path><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"></line><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"></line></svg> Medium Risk</span>\n          <p class=\"disc-desc\">Charismatic, persuasive, social — but when extreme: manipulative, attention-seeking, dishonest.</p>\n          <div class=\"disc-detail\"><strong>Dark Correlation:</strong> The I-type's natural charm can become a weapon. When combined with narcissistic traits, they manipulate through charisma and social pressure. They love admiration and will lie to maintain their image. Less violent than D-type extremes, but can be deeply destructive in relationships.</div>\n        </div>\n        <div class=\"disc-card S\" onclick=\"this.classList.toggle('active')\">\n          <div class=\"disc-letter\">S</div>\n          <div class=\"disc-name\">Steadiness</div>\n          <span class=\"disc-risk low\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg> Low Risk</span>\n          <p class=\"disc-desc\">Patient, loyal, calm — the least likely to exhibit psychopathic traits.</p>\n          <div class=\"disc-detail\"><strong>Dark Correlation:</strong> S-types are typically the least susceptible to psychopathic tendencies. Their high empathy and need for harmony are the opposite of the psychopathic profile. However, their trusting nature makes them the most vulnerable target for psychopaths and manipulators.</div>\n        </div>\n        <div class=\"disc-card C\" onclick=\"this.classList.toggle('active')\">\n          <div class=\"disc-letter\">C</div>\n          <div class=\"disc-name\">Conscientiousness</div>\n          <span class=\"disc-risk low\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg> Low Risk</span>\n          <p class=\"disc-desc\">Analytical, precise, systematic — but when extreme: cold, detached, perfectionistic.</p>\n          <div class=\"disc-detail\"><strong>Dark Correlation:</strong> C-types rarely exhibit classic psychopathy but their emotional detachment can mask cold, calculated behavior. When combined with Machiavellian traits, they can become dangerously meticulous manipulators — planning every move with clinical precision and zero emotional interference.</div>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- Red Flag Detector -->\n<section>\n  <div class=\"container\">\n    <span class=\"section-label reveal\">Warning System</span>\n    <h2 class=\"section-title reveal\">Red Flag Detector</h2>\n    <p class=\"section-desc reveal\">Click each warning sign to reveal the hidden truth behind psychopathic behavior patterns. Knowledge is your first line of defense.</p>\n    <div class=\"flags-grid\">\n      <div class=\"flag-card reveal\" onclick=\"this.classList.toggle('revealed')\">\n        <div class=\"flag-header\">\n          <span class=\"flag-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"></path></svg>️</span>\n          <span class=\"flag-title\">Rapid Talking &amp; Dominating Conversations</span>\n          <span class=\"flag-toggle\">+</span>\n        </div>\n        <div class=\"flag-content\">\n          <p>Psychopaths often talk excessively, control conversations, and steer topics toward themselves. They use verbal dominance as a tool of control — overwhelming you with words so you cannot think clearly or challenge them. Pauses are uncomfortable for them; silence gives you power.</p>\n          <span class=\"flag-severity critical\">Critical</span>\n        </div>\n      </div>\n      <div class=\"flag-card reveal\" onclick=\"this.classList.toggle('revealed')\">\n        <div class=\"flag-header\">\n          <span class=\"flag-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"></path><path d=\"M2 17l10 5 10-5\"></path><path d=\"M2 12l10 5 10-5\"></path></svg></span>\n          <span class=\"flag-title\">Inconsistent Persona</span>\n          <span class=\"flag-toggle\">+</span>\n        </div>\n        <div class=\"flag-content\">\n          <p>They present different versions of themselves to different people. Colleagues see one face, family another, and romantic partners yet another. There is no stable core self — only a collection of masks optimized for each situation. If someone seems \"too good to be true,\" they might be wearing a costume.</p>\n          <span class=\"flag-severity critical\">Critical</span>\n        </div>\n      </div>\n      <div class=\"flag-card reveal\" onclick=\"this.classList.toggle('revealed')\">\n        <div class=\"flag-header\">\n          <span class=\"flag-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><circle cx=\"12\" cy=\"12\" r=\"4\"></circle></svg>️</span>\n          <span class=\"flag-title\">Pity Traps &amp; Victim Stories</span>\n          <span class=\"flag-toggle\">+</span>\n        </div>\n        <div class=\"flag-content\">\n          <p>A classic manipulation tactic: they share elaborate, tragic stories designed to provoke sympathy and lower your guard. The stories are often exaggerated or entirely fabricated. The goal is to make you feel sorry for them so you'll overlook red flags and comply with their requests out of misplaced compassion.</p>\n          <span class=\"flag-severity high\">High</span>\n        </div>\n      </div>\n      <div class=\"flag-card reveal\" onclick=\"this.classList.toggle('revealed')\">\n        <div class=\"flag-header\">\n          <span class=\"flag-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.5 2h-5L7 8h10l-2.5-6z\"></path><path d=\"M7 8v11a3 3 0 0 0 3 3h4a3 3 0 0 0 3-3V8\"></path><line x1=\"10\" y1=\"12\" x2=\"10\" y2=\"17\"></line><line x1=\"14\" y1=\"12\" x2=\"14\" y2=\"17\"></line></svg></span>\n          <span class=\"flag-title\">Triangulation &amp; Division</span>\n          <span class=\"flag-toggle\">+</span>\n        </div>\n        <div class=\"flag-content\">\n          <p>They pit people against each other by spreading gossip, creating jealousy, and manufacturing conflicts. This serves two purposes: it distracts everyone from the psychopath's behavior, and it positions them as the \"stable center\" who can \"help resolve\" the chaos they created. Divide and conquer is their oldest strategy.</p>\n          <span class=\"flag-severity critical\">Critical</span>\n        </div>\n      </div>\n      <div class=\"flag-card reveal\" onclick=\"this.classList.toggle('revealed')\">\n        <div class=\"flag-header\">\n          <span class=\"flag-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"></path><polyline points=\"14 2 14 8 20 8\"></polyline><line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\"></line><line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\"></line><polyline points=\"10 9 9 9 8 9\"></polyline></svg></span>\n          <span class=\"flag-title\">Pathological Lying About Trivial Things</span>\n          <span class=\"flag-toggle\">+</span>\n        </div>\n        <div class=\"flag-content\">\n          <p>They lie not just when it benefits them, but about inconsequential matters where the truth would serve just as well. This is a hallmark of the psychopathic mind — lying is not a tool but a default mode. If you catch someone in frequent small lies, the big lies are almost certainly there too.</p>\n          <span class=\"flag-severity critical\">Critical</span>\n        </div>\n      </div>\n      <div class=\"flag-card reveal\" onclick=\"this.classList.toggle('revealed')\">\n        <div class=\"flag-header\">\n          <span class=\"flag-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"></path><circle cx=\"12\" cy=\"12\" r=\"3\"></circle></svg>️</span>\n          <span class=\"flag-title\">Intense Eye Contact or Complete Avoidance</span>\n          <span class=\"flag-toggle\">+</span>\n        </div>\n        <div class=\"flag-content\">\n          <p>Both extremes are common among psychopaths. Some use an unflinching, predatory stare as an intimidation tactic — a silent power play. Others avoid eye contact entirely because they don't experience the emotional connection that makes eye contact natural. Trust your gut when someone's gaze feels \"off.\"</p>\n          <span class=\"flag-severity high\">High</span>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- Self-Assessment Checklist -->\n<section>\n  <div class=\"container\">\n    <span class=\"section-label reveal\">Self-Assessment</span>\n    <h2 class=\"section-title reveal\">Psychopath Trait Checklist</h2>\n    <p class=\"section-desc reveal\">Based on the PCL-R (Hare Psychopathy Checklist) and Erikson's adaptations. This is <strong>not a diagnostic tool</strong> — use it to recognize patterns in others, not yourself.</p>\n    <div class=\"checklist-grid\" id=\"checklist\">\n      <div class=\"check-item reveal\" data-checked=\"false\" onclick=\"toggleCheck(this)\">\n        <div class=\"check-box\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></div>\n        <div class=\"check-text\">Glib and superficial charm — smooth talker who seems too polished</div>\n      </div>\n      <div class=\"check-item reveal\" data-checked=\"false\" onclick=\"toggleCheck(this)\">\n        <div class=\"check-box\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></div>\n        <div class=\"check-text\">Grandiose sense of self-worth — believes they are exceptional and above rules</div>\n      </div>\n      <div class=\"check-item reveal\" data-checked=\"false\" onclick=\"toggleCheck(this)\">\n        <div class=\"check-box\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></div>\n        <div class=\"check-text\">Need for stimulation / proneness to boredom — constantly seeks drama or risk</div>\n      </div>\n      <div class=\"check-item reveal\" data-checked=\"false\" onclick=\"toggleCheck(this)\">\n        <div class=\"check-box\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></div>\n        <div class=\"check-text\">Pathological lying — lies reflexively, even when unnecessary</div>\n      </div>\n      <div class=\"check-item reveal\" data-checked=\"false\" onclick=\"toggleCheck(this)\">\n        <div class=\"check-box\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></div>\n        <div class=\"check-text\">Conning / manipulative — exploits others for personal gain without guilt</div>\n      </div>\n      <div class=\"check-item reveal\" data-checked=\"false\" onclick=\"toggleCheck(this)\">\n        <div class=\"check-box\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></div>\n        <div class=\"check-text\">Lack of remorse or guilt — never truly apologizes or takes accountability</div>\n      </div>\n      <div class=\"check-item reveal\" data-checked=\"false\" onclick=\"toggleCheck(this)\">\n        <div class=\"check-box\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></div>\n        <div class=\"check-text\">Shallow affect — emotional expressions feel hollow or performative</div>\n      </div>\n      <div class=\"check-item reveal\" data-checked=\"false\" onclick=\"toggleCheck(this)\">\n        <div class=\"check-box\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></div>\n        <div class=\"check-text\">Callous / lack of empathy — indifferent to others' suffering</div>\n      </div>\n      <div class=\"check-item reveal\" data-checked=\"false\" onclick=\"toggleCheck(this)\">\n        <div class=\"check-box\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></div>\n        <div class=\"check-text\">Parasitic lifestyle — financially or emotionally dependent on others</div>\n      </div>\n      <div class=\"check-item reveal\" data-checked=\"false\" onclick=\"toggleCheck(this)\">\n        <div class=\"check-box\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"20 6 9 17 4 12\"></polyline></svg></div>\n        <div class=\"check-text\">Poor behavioral controls — explosive outbursts disproportionate to triggers</div>\n      </div>\n    </div>\n    <div class=\"check-count reveal\" id=\"checkCount\">Red flags detected: <span id=\"checkScore\">0</span> / 10</div>\n    <div class=\"alert-banner reveal\">\n      <span class=\"alert-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M10.29 3.86L1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0z\"></path><line x1=\"12\" y1=\"9\" x2=\"12\" y2=\"13\"></line><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"></line></svg>️</span>\n      <h3>Trust Your Instincts</h3>\n      <p>If someone consistently triggers 5 or more of these markers, your concern is legitimate. Your gut evolved to detect threats — listen to it.</p>\n    </div>\n  </div>\n</section>\n\n<!-- Protection Strategies -->\n<section>\n  <div class=\"container\">\n    <span class=\"section-label reveal\">Defense</span>\n    <h2 class=\"section-title reveal\">How to Protect Yourself</h2>\n    <p class=\"section-desc reveal\">Practical strategies from Erikson's work to safeguard your mental health, boundaries, and autonomy against psychopathic manipulation.</p>\n    <div class=\"protection-grid\">\n      <div class=\"protection-card reveal\" onclick=\"this.classList.toggle('open')\">\n        <div class=\"protection-header\">\n          <h3><span class=\"num\">1</span> Set Unbreakable Boundaries</h3>\n          <span class=\"protection-toggle\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span>\n        </div>\n        <div class=\"protection-body\">\n          <p>Psychopaths test boundaries constantly. Define your non-negotiables clearly and enforce them without exception. The moment you make an exception, they will exploit the opening. Learn to say no without guilt or explanation — \"No\" is a complete sentence. Remember: a person who doesn't respect your boundaries doesn't deserve your presence.</p>\n        </div>\n      </div>\n      <div class=\"protection-card reveal\" onclick=\"this.classList.toggle('open')\">\n        <div class=\"protection-header\">\n          <h3><span class=\"num\">2</span> Document Everything</h3>\n          <span class=\"protection-toggle\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span>\n        </div>\n        <div class=\"protection-body\">\n          <p>Psychopaths are skilled at rewriting reality to their advantage. Keep written records of conversations, agreements, and incidents. Date everything. In professional settings, follow up verbal discussions with confirming emails. This creates a paper trail that counters their gaslighting and protects you when they attempt to distort the truth.</p>\n        </div>\n      </div>\n      <div class=\"protection-card reveal\" onclick=\"this.classList.toggle('open')\">\n        <div class=\"protection-header\">\n          <h3><span class=\"num\">3</span> Starve the Drama Cycle</h3>\n          <span class=\"protection-toggle\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span>\n        </div>\n        <div class=\"protection-body\">\n          <p>Psychopaths thrive on emotional reactions. When you stay calm, collected, and unresponsive to their provocations, you starve them of the fuel they need. Use the \"grey rock\" method: become as boring and uninteresting as a grey rock. Don't react to their jabs, don't engage in their drama, and don't explain yourself. Your emotional indifference is your armor.</p>\n        </div>\n      </div>\n      <div class=\"protection-card reveal\" onclick=\"this.classList.toggle('open')\">\n        <div class=\"protection-header\">\n          <h3><span class=\"num\">4</span> Verify, Don't Trust</h3>\n          <span class=\"protection-toggle\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span>\n        </div>\n        <div class=\"protection-body\">\n          <p>A healthy default in business is trust — but with suspected psychopaths, trust must be earned and verified. Fact-check their claims, talk to others who know them, and look for inconsistencies. If someone's stories change each time they tell them, pay attention. Trust patterns of behavior, not words. Words are cheap; behavior reveals truth.</p>\n        </div>\n      </div>\n      <div class=\"protection-card reveal\" onclick=\"this.classList.toggle('open')\">\n        <div class=\"protection-header\">\n          <h3><span class=\"num\">5</span> Build a Support Network</h3>\n          <span class=\"protection-toggle\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span>\n        </div>\n        <div class=\"protection-body\">\n          <p>Psychopaths often isolate their targets from friends, family, and colleagues. Maintain strong connections outside the toxic relationship. A support network provides reality checks when you start doubting yourself, emotional validation, and witnesses to behavior patterns you might be too close to see clearly. Isolation is their weapon — community is your shield.</p>\n        </div>\n      </div>\n      <div class=\"protection-card reveal\" onclick=\"this.classList.toggle('open')\">\n        <div class=\"protection-header\">\n          <h3><span class=\"num\">6</span> Know When to Walk Away</h3>\n          <span class=\"protection-toggle\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 19 5 5 19 5 12 19\"></polygon></svg></span>\n        </div>\n        <div class=\"protection-body\">\n          <p>The most powerful protection strategy is leaving. Psychopaths rarely change — their brain wiring is fundamentally different. If you've identified the pattern, stop trying to fix, save, or reform them. The only winning move is to exit the game entirely. Your safety, sanity, and well-being are worth more than any relationship with someone who lacks empathy.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- Key Quotes -->\n<section>\n  <div class=\"container\">\n    <span class=\"section-label reveal\">The Words</span>\n    <h2 class=\"section-title reveal\">Key Quotes</h2>\n    <div class=\"quotes-grid\">\n      <div class=\"quote-card reveal\">\n        <blockquote>A psychopath doesn't see people. He sees objects that can be used, manipulated, and discarded.</blockquote>\n        <cite>Thomas Erikson</cite>\n      </div>\n      <div class=\"quote-card reveal\">\n        <blockquote>The most dangerous people are those who have no emotional connection to anything. They can do the unthinkable without losing a second of sleep.</blockquote>\n        <cite>Thomas Erikson</cite>\n      </div>\n      <div class=\"quote-card reveal\">\n        <blockquote>Charm is the psychopath's primary weapon. It disarms you, lowers your guard, and makes you want to trust them. That is precisely the moment you are most vulnerable.</blockquote>\n        <cite>Thomas Erikson</cite>\n      </div>\n      <div class=\"quote-card reveal\">\n        <blockquote>The difference between a healthy D-type and a psychopath is empathy. One pushes hard but feels remorse. The other pushes hard and feels nothing.</blockquote>\n        <cite>Thomas Erikson</cite>\n      </div>\n      <div class=\"quote-card reveal\">\n        <blockquote>You cannot cure what doesn't believe it is sick. The psychopath does not think there is anything wrong with them. In their world, the problem is always you.</blockquote>\n        <cite>Thomas Erikson</cite>\n      </div>\n      <div class=\"quote-card reveal\">\n        <blockquote>Knowing what you're dealing with is half the battle. The other half is knowing what to do about it — and having the courage to do it.</blockquote>\n        <cite>Thomas Erikson</cite>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- Footer -->\n\n\n<script>\n// Theme toggle\nconst toggle = document.getElementById('themeToggle');\ntoggle.addEventListener('click', () => {\n  document.body.classList.toggle('light');\n  toggle.innerHTML = document.body.classList.contains('light') ? '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"/></svg>️' : '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>';\n  localStorage.setItem('theme', document.body.classList.contains('light') ? 'light' : 'dark');\n});\nif (localStorage.getItem('theme') === 'light') {\n  document.body.classList.add('light');\n  toggle.innerHTML = '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"/></svg>️';\n}\n\n// Scroll reveal\nconst revealObserver = new IntersectionObserver((entries) => {\n  entries.forEach(entry => {\n    if (entry.isIntersecting) {\n      entry.target.classList.add('visible');\n    }\n  });\n}, { threshold: 0.1, rootMargin: '0px 0px -50px 0px' });\n\ndocument.querySelectorAll('.reveal, .reveal-left, .reveal-right').forEach(el => {\n  revealObserver.observe(el);\n});\n\n// Checklist\nfunction toggleCheck(el) {\n  const isChecked = el.dataset.checked === 'true';\n  el.dataset.checked = isChecked ? 'false' : 'true';\n  el.classList.toggle('checked', !isChecked);\n  updateCheckScore();\n}\n\nfunction updateCheckScore() {\n  const checked = document.querySelectorAll('#checklist .check-item[data-checked=\"true\"]').length;\n  document.getElementById('checkScore').textContent = checked;\n}\n\n// Flag cards stagger\ndocument.querySelectorAll('.flag-card').forEach((card, i) => {\n  card.style.transitionDelay = (i * 0.05) + 's';\n});\n\n// Protection cards stagger\ndocument.querySelectorAll('.protection-card').forEach((card, i) => {\n  card.style.transitionDelay = (i * 0.05) + 's';\n});\n\n// Detect reduced motion\nconst prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)');\nif (prefersReducedMotion.matches) {\n  document.querySelectorAll('.reveal, .reveal-left, .reveal-right').forEach(el => {\n    el.classList.add('visible');\n    el.style.transition = 'none';\n  });\n}\n</script>\n\n\n\n</body>\n</html>",
  "the-art-of-seduction": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n\n<div id=\"progress\"></div>\n<canvas id=\"petalsCanvas\"></canvas>\n\n<!-- HERO -->\n\n\n<!-- STATS -->\n<section>\n  <div class=\"stats\">\n    <div class=\"stat\"><div class=\"stat-value\">9</div><div class=\"stat-label\">Seducer Types</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">4</div><div class=\"stat-label\">Seduction Phases</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">24</div><div class=\"stat-label\">Key Tactics</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">∞</div><div class=\"stat-label\">Ways to Captivate</div></div>\n  </div>\n</section>\n\n<!-- THE 9 TYPES OF SEDUCERS -->\n<section id=\"seducers\">\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The Archetypes</div>\n  <h2>The 9 Types of <span class=\"hl\">Seducers</span></h2>\n  <p class=\"section-desc\">Click each card to explore the full profile. Each type embodies a distinct strategy of attraction.</p>\n\n  <div class=\"seducer-grid\" id=\"seducerGrid\"></div>\n</section>\n\n<!-- THE SEDUCTIVE PROCESS -->\n<section id=\"phases\">\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The Strategy</div>\n  <h2>The <span class=\"hl\">Seductive Process</span></h2>\n  <p class=\"section-desc\">Seduction unfolds in four distinct phases. Click each to reveal the deeper tactics.</p>\n\n  <div class=\"timeline-wrap\" id=\"timeline\">\n    <div class=\"tl-item\">\n      <div class=\"tl-phase\">Phase I</div>\n      <h4>Separation — The First Strike</h4>\n      <p>Single out your target from the crowd. Create a feeling of emptiness that only you can fill. Stand apart through mystery, absence, and the art of not trying. The initial attraction is born from contrast — you must seem different from everyone else.</p>\n      <div class=\"tl-details\" style=\"max-height:0;overflow:hidden;transition:max-height 0.6s ease;\">\n        <p style=\"margin-top:0.6rem;font-size:0.8rem;color:var(--text-muted);border-top:1px solid var(--border);padding-top:0.6rem;\"><strong style=\"color:var(--rose);\">Tactics:</strong> Choose the right victim, create a void, keep your distance, insert yourself into their mind through absence. The key is to make them notice you without realizing they've been targeted.</p>\n      </div>\n    </div>\n    <div class=\"tl-item\">\n      <div class=\"tl-phase\">Phase II</div>\n      <h4>Attention — The Spell Begins</h4>\n      <p>Draw them in through a mixture of charm and provocation. Use words to create a dreamlike state, to lead them astray. Play on their insecurities and desires. Make them feel seen, understood, and desired — but never completely satisfied.</p>\n      <div class=\"tl-details\" style=\"max-height:0;overflow:hidden;transition:max-height 0.6s ease;\">\n        <p style=\"margin-top:0.6rem;font-size:0.8rem;color:var(--text-muted);border-top:1px solid var(--border);padding-top:0.6rem;\"><strong style=\"color:var(--rose);\">Tactics:</strong> Use poetic language, create shared secrets, hint at forbidden pleasures, play the push-pull game. Make your attention feel like a gift while keeping them slightly off-balance.</p>\n      </div>\n    </div>\n    <div class=\"tl-item\">\n      <div class=\"tl-phase\">Phase III</div>\n      <h4>The Spell — Deep Engagement</h4>\n      <p>Now the target is emotionally invested. Deepen the connection by probing their psychology, finding their weaknesses, and becoming indispensable. Create dependency through alternating warmth and withdrawal. They should feel they cannot live without you.</p>\n      <div class=\"tl-details\" style=\"max-height:0;overflow:hidden;transition:max-height 0.6s ease;\">\n        <p style=\"margin-top:0.6rem;font-size:0.8rem;color:var(--text-muted);border-top:1px solid var(--border);padding-top:0.6rem;\"><strong style=\"color:var(--rose);\">Tactics:</strong> The deep probe — discover their fantasies and insecurities. Play on emotional extremes. Use the poison approach (gentle insinuations). Create rituals and shared experiences that bind them to you.</p>\n      </div>\n    </div>\n    <div class=\"tl-item\">\n      <div class=\"tl-phase\">Phase IV</div>\n      <h4>The Final Act — Surrender &amp; Aftermath</h4>\n      <p>The moment of surrender is both an ending and a beginning. Handle it with grace — never gloat, never show your hand completely. The seduction must transform into a lasting bond, or dissolve cleanly. The greatest seducers leave their targets grateful, not resentful.</p>\n      <div class=\"tl-details\" style=\"max-height:0;overflow:hidden;transition:max-height 0.6s ease;\">\n        <p style=\"margin-top:0.6rem;font-size:0.8rem;color:var(--text-muted);border-top:1px solid var(--border);padding-top:0.6rem;\"><strong style=\"color:var(--rose);\">Tactics:</strong> Know when to stop, let them come to you for the final surrender, create an unforgettable final act, and decide whether to transform or exit. The aftermath is where the true art reveals itself.</p>\n      </div>\n    </div>\n  </div>\n  <div class=\"tl-toggle\">\n    <button class=\"btn\" id=\"expandTimeline\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> Reveal Tactics <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></button>\n  </div>\n</section>\n\n<!-- KEYS TO SEDUCTION -->\n<section id=\"keys\">\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The Principles</div>\n  <h2>Keys to <span class=\"hl\">Seduction</span></h2>\n  <p class=\"section-desc\">The timeless principles that underpin every successful seduction.</p>\n\n  <div class=\"keys-grid\">\n    <div class=\"key-item\"><span class=\"key-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2v12\"></path><path d=\"M12 14a4 4 0 0 0 4-4V3\"></path><path d=\"M8 3v7a4 4 0 0 0 4 4\"></path><path d=\"M8 7h8\"></path></svg>️</span><h4>Create Mystery</h4><p>Reveal less than they want to know. Mystery creates tension, curiosity, and desire. The more they wonder, the more they're hooked.</p></div>\n    <div class=\"key-item\"><span class=\"key-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"></path><path d=\"M2 17l10 5 10-5\"></path><path d=\"M2 12l10 5 10-5\"></path></svg></span><h4>Master the Mask</h4><p>Everyone wears masks. The seducer's art is knowing which mask to wear, when, and for whom. Adaptability is everything.</p></div>\n    <div class=\"key-item\"><span class=\"key-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 6c.6.5 1.2 1 2.5 1C7 7 7 5 9.5 5c2.6 0 2.4 2 5 2 2.5 0 2.5-2 5-2 1.3 0 1.9.5 2.5 1\"></path><path d=\"M2 12c.6.5 1.2 1 2.5 1 2.5 0 2.5-2 5-2 2.6 0 2.4 2 5 2 2.5 0 2.5-2 5-2 1.3 0 1.9.5 2.5 1\"></path><path d=\"M2 18c.6.5 1.2 1 2.5 1 2.5 0 2.5-2 5-2 2.6 0 2.4 2 5 2 2.5 0 2.5-2 5-2 1.3 0 1.9.5 2.5 1\"></path></svg></span><h4>Push &amp; Pull</h4><p>Alternate warmth with coldness, attention with withdrawal. This emotional seesaw creates obsession and deepens desire.</p></div>\n    <div class=\"key-item\"><span class=\"key-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"></path><circle cx=\"12\" cy=\"12\" r=\"3\"></circle></svg>️</span><h4>Target the Weakness</h4><p>Every person has a hidden insecurity, a secret fantasy. Find it and you hold the key to their heart — and their surrender.</p></div>\n    <div class=\"key-item\"><span class=\"key-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\"></path><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"></line></svg></span><h4>Stoke the Fantasy</h4><p>People fall in love with a fantasy, not a reality. Sell them a dream of who they could be with you. The real is disappointing; the imagined is intoxicating.</p></div>\n    <div class=\"key-item\"><span class=\"key-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><polyline points=\"12 6 12 12 16 14\"></polyline></svg></span><h4>Use Time &amp; Absence</h4><p>Scarcity increases value. Absence makes the heart grow fonder — but only if the foundation is already laid. Time is your ally when used strategically.</p></div>\n    <div class=\"key-item\"><span class=\"key-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 22 16 8\"></path><path d=\"M21 2l-5 5\"></path><path d=\"M14 7l3-3\"></path></svg></span><h4>Play on Emotions</h4><p>Logic is the enemy of seduction. Appeal to emotions — insecurity, desire, fear, hope. The rational mind must be bypassed, not convinced.</p></div>\n    <div class=\"key-item\"><span class=\"key-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><circle cx=\"12\" cy=\"12\" r=\"6\"></circle><circle cx=\"12\" cy=\"12\" r=\"2\"></circle></svg></span><h4>Know When to Retreat</h4><p>The strategic retreat is often more powerful than advance. Withdrawal ignites pursuit. The chased becomes the chaser.</p></div>\n  </div>\n</section>\n\n<!-- ANTI-SEDUCTION -->\n<section id=\"anti\">\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The Pitfalls</div>\n  <h2>Anti-<span class=\"hl\">Seduction</span></h2>\n  <p class=\"section-desc\">Traits and behaviors that repel rather than attract. Avoid these at all costs.</p>\n\n  <div class=\"anti-grid\">\n    <div class=\"anti-item\"><span class=\"anti-icon\">🥺</span><h4>Neediness</h4><p>Desperation is the most repellent quality. Need nothing from anyone and they will flock to you.</p></div>\n    <div class=\"anti-item\"><span class=\"anti-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"></path><path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z\"></path></svg></span><h4>Predictability</h4><p>Routine kills desire. If they can predict your every move, you cease to be interesting.</p></div>\n    <div class=\"anti-item\"><span class=\"anti-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"></path></svg></span><h4>Over-Talking</h4><p>Talking too much reveals insecurity and destroys mystery. Silence is more seductive than speech.</p></div>\n    <div class=\"anti-item\"><span class=\"anti-icon\">🫂</span><h4>Eagerness to Please</h4><p>The desperate need for approval signals weakness. Confidence comes from not needing anyone's validation.</p></div>\n    <div class=\"anti-item\"><span class=\"anti-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M8 15h8\"></path><path d=\"M8 9h2\"></path><path d=\"M14 9h2\"></path></svg></span><h4>Negativity</h4><p>Complaining and pessimism drain energy. Seduction requires lightness, playfulness, an air of possibility.</p></div>\n    <div class=\"anti-item\"><span class=\"anti-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 4s3 4 10 4 10-4 10-4\"></path><path d=\"M4 4v14c0 1.1.9 2 2 2h12c1.1 0 2-.9 2-2V4\"></path><path d=\"M12 8v14\"></path></svg></span><h4>Arrogance</h4><p>Arrogance without substance is a mask for insecurity. True confidence is quiet, self-contained, unprovoked.</p></div>\n    <div class=\"anti-item\"><span class=\"anti-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"></path><path d=\"M2 17l10 5 10-5\"></path><path d=\"M2 12l10 5 10-5\"></path></svg></span><h4>Inauthenticity</h4><p>People can sense a fake. The best seducers are genuine in their seduction — they believe in the spell they cast.</p></div>\n    <div class=\"anti-item\"><span class=\"anti-icon\">🪞</span><h4>Self-Absorption</h4><p>Obsession with oneself leaves no room for the other. Seduction is about making <em>them</em> feel extraordinary.</p></div>\n    <div class=\"anti-item\"><span class=\"anti-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"13 2 3 14 12 14 11 22 21 10 12 10 13 2\"></polygon></svg></span><h4>Impatience</h4><p>Rushing ruins everything. Seduction requires time, patience, and the willingness to wait for the perfect moment.</p></div>\n    <div class=\"anti-item\"><span class=\"anti-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"11 5 6 9 2 8 14 2 18 6 20 2 22 8 17 11 21 15 18 18 12 10 9 16 12 20 8 22 2 18 7 14 4 10 8 6\"></polygon></svg></span><h4>Bragging</h4><p>Announcing your virtues diminishes them. Let others discover your qualities — the discovery is half the pleasure.</p></div>\n  </div>\n</section>\n\n<!-- QUOTES -->\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The Wisdom</div>\n  <h2>Words to <span class=\"hl\">Seduce By</span></h2>\n  <p class=\"section-desc\">Key passages from <em>The Art of Seduction</em> that capture its essence.</p>\n\n  <div class=\"quote-block\">\n    <div class=\"quote-slider\" id=\"quoteSlider\">\n      <div class=\"quote-slide\">\n        <div class=\"ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n        <blockquote>\"The seducer's power lies in the ability to make people feel special, to make them feel that they are the only one. And in that feeling, they lower their defenses.\"</blockquote>\n        <cite>— Robert Greene, The Art of Seduction</cite>\n      </div>\n      <div class=\"quote-slide\">\n        <div class=\"ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n        <blockquote>\"What seduces is not what you give them, but what you make them feel. The seducer creates a void, an emptiness that only they can fill.\"</blockquote>\n        <cite>— Robert Greene, The Art of Seduction</cite>\n      </div>\n      <div class=\"quote-slide\">\n        <div class=\"ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n        <blockquote>\"The most effective seducers are those who understand that seduction is not about sex, but about power — the power to make someone lose control.\"</blockquote>\n        <cite>— Robert Greene, The Art of Seduction</cite>\n      </div>\n      <div class=\"quote-slide\">\n        <div class=\"ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n        <blockquote>\"In the game of seduction, the one who is most comfortable with solitude and silence has the upper hand. Neediness is the death of desire.\"</blockquote>\n        <cite>— Robert Greene, The Art of Seduction</cite>\n      </div>\n      <div class=\"quote-slide\">\n        <div class=\"ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n        <blockquote>\"The seducer looks at people differently than the rest of us. Where others see flaws and weaknesses, the seducer sees levers to push, hooks to set, opportunities for enchantment.\"</blockquote>\n        <cite>— Robert Greene, The Art of Seduction</cite>\n      </div>\n    </div>\n    <div class=\"quote-nav\" id=\"quoteNav\"></div>\n  </div>\n</section>\n\n<!-- FOOTER -->\n\n\n<script>\n  //  PETALS CANVAS \n  (function(){\n    const canvas = document.getElementById('petalsCanvas');\n    const ctx = canvas.getContext('2d');\n    let petals = [];\n    let W, H;\n\n    function resize(){\n      W = canvas.width = window.innerWidth;\n      H = canvas.height = window.innerHeight;\n    }\n    resize();\n    window.addEventListener('resize', resize);\n\n    const colors = [\n      'rgba(183,110,121,{a})',\n      'rgba(183,110,121,{a})',\n      'rgba(128,0,32,{a})',\n      'rgba(74,14,78,{a})',\n      'rgba(212,146,156,{a})'\n    ];\n\n    class Petal {\n      constructor(){\n        this.reset();\n        this.y = Math.random() * H;\n      }\n      reset(){\n        this.x = Math.random() * W;\n        this.y = -30;\n        this.size = 6 + Math.random() * 12;\n        this.vx = (Math.random() - 0.5) * 0.3;\n        this.vy = 0.3 + Math.random() * 0.6;\n        this.rotation = Math.random() * Math.PI * 2;\n        this.rotSpeed = (Math.random() - 0.5) * 0.02;\n        this.swing = Math.random() * 100 + 50;\n        this.swingSpeed = 0.01 + Math.random() * 0.02;\n        this.swingOffset = Math.random() * Math.PI * 2;\n        this.alpha = 0.3 + Math.random() * 0.4;\n        this.color = colors[Math.floor(Math.random() * colors.length)].replace('{a}', this.alpha);\n        this.petal = this.createPetalShape();\n      }\n      createPetalShape(){\n        const offscreen = document.createElement('canvas');\n        offscreen.width = this.size * 2;\n        offscreen.height = this.size * 2;\n        const oc = offscreen.getContext('2d');\n        const cx = this.size, cy = this.size;\n        const w = this.size * 0.7;\n        const h = this.size * 0.3;\n        oc.beginPath();\n        oc.ellipse(cx, cy, w, h, 0, 0, Math.PI * 2);\n        oc.fillStyle = this.color;\n        oc.fill();\n        oc.beginPath();\n        oc.ellipse(cx - w * 0.2, cy - h * 0.1, w * 0.5, h * 0.5, -0.3, 0, Math.PI * 2);\n        oc.fillStyle = this.color.replace('0.4', '0.3').replace('0.3', '0.2');\n        oc.fill();\n        return offscreen;\n      }\n      update(){\n        this.vy += 0.001;\n        this.x += this.vx + Math.sin(this.swingOffset + performance.now() * this.swingSpeed) * 0.5;\n        this.y += this.vy;\n        this.rotation += this.rotSpeed;\n        if (this.y > H + 30 || this.x < -50 || this.x > W + 50) this.reset();\n      }\n      draw(){\n        ctx.save();\n        ctx.translate(this.x, this.y);\n        ctx.rotate(this.rotation);\n        ctx.globalAlpha = this.alpha;\n        ctx.drawImage(this.petal, -this.size, -this.size, this.size * 2, this.size * 2);\n        ctx.restore();\n        ctx.globalAlpha = 1;\n      }\n    }\n\n    const count = Math.min(Math.floor(W * H / 15000), 30);\n    for (let i = 0; i < count; i++){\n      const p = new Petal();\n      p.y = Math.random() * H;\n      petals.push(p);\n    }\n\n    function animate(){\n      ctx.clearRect(0, 0, W, H);\n      petals.forEach(p => { p.update(); p.draw(); });\n      requestAnimationFrame(animate);\n    }\n    animate();\n  })();\n\n  //  THEME \n  (function(){\n    const toggle = document.getElementById('themeToggle');\n    toggle.addEventListener('click', () => {\n      document.body.classList.toggle('light');\n      toggle.innerHTML = document.body.classList.contains('light') ? '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"/></svg>️' : '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>';\n    });\n  })();\n\n  //  SCROLL PROGRESS \n  window.addEventListener('scroll', () => {\n    const s = window.scrollY / (document.body.scrollHeight - window.innerHeight) * 100;\n    document.getElementById('progress').style.width = s + '%';\n  });\n\n  //  9 TYPES OF SEDUCERS \n  const seducers = [\n    {n:1, icon:\"🧜‍♀️\", type:\"The Siren\", tagline:\"The Feminine Trap\", preview:\"The Siren is the archetypal feminine seducer — dangerous, alluring, and utterly captivating. She wields her power through the promise of pleasure and the threat of destruction.\", full:\"The Siren operates through <strong>indirect power</strong> — she never pursues, she attracts. Her weapon is <strong>desire</strong>; she creates such longing that her target will do anything to possess her. She is mysterious, sensual, and just out of reach. Her danger is what makes her irresistible — to possess her is to risk being consumed. <strong>Key tactic:</strong> Create an aura of forbidden pleasure. Make yourself the object of fantasy, not reality. The chase IS the seduction.\"},\n    {n:2, icon:'<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.5 2h-5L7 8h10l-2.5-6z\"/><path d=\"M7 8v11a3 3 0 0 0 3 3h4a3 3 0 0 0 3-3V8\"/></svg>️', type:\"The Rake\", tagline:\"The Masculine Hunter\", preview:\"The Rake is the masculine counterpart — a man obsessed with the art of seduction itself. His drive is not for love but for conquest, and his enthusiasm becomes infectious.\", full:\"The Rake's power lies in his <strong>single-minded intensity</strong>. He pursues with relentless charm, wearing down resistance through persistence. He is often a <strong>reformed rake</strong> — a man who has lived hard and now directs all that energy into seduction. His past gives him depth, his focus gives him power. <strong>Key tactic:</strong> Pursue with such passion that your target feels like the center of the universe. Make the seduction itself feel like an adventure, a story worth being part of.\"},\n    {n:3, icon:'<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2l1.5 5.5L19 7l-5.5 1.5L12 14l-1.5-5.5L5 7l5.5-1.5z\"/><path d=\"M19 17l-5.5-1.5L12 11l-1.5 4.5L5 17l5.5 1.5L12 23l1.5-4.5z\"/></svg>', type:\"The Ideal Lover\", tagline:\"The Romantic Fantasist\", preview:\"The Ideal Lover creates the perfect romantic fantasy — attentive, poetic, utterly devoted. They make each person feel like the sole object of their affection, the hero of a love story.\", full:\"This type succeeds by <strong>embodying the target's fantasy</strong>. They study their prey, learning what kind of love story they secretly crave, then become the perfect protagonist. The Ideal Lover is <strong>adaptable</strong>, shaping themselves to fit the dream. They speak in the language of romance, create moments of perfect intimacy. <strong>Key tactic:</strong> Mirror their unspoken desires. Become the character they've always wanted to meet. Let them project their fantasies onto you — never break the spell by being too real.\"},\n    {n:4, icon:\"🪞\", type:\"The Dandy\", tagline:\"The Provocative Rebel\", preview:\"The Dandy challenges conventions of gender, style, and behavior. They court controversy and fascination through audacity, becoming objects of curiosity and desire.\", full:\"The Dandy's power comes from <strong>transgression</strong>. By blurring lines, they create fascination. They are theatrical, self-consciously artificial, and deliberately provocative. In a world of conformity, the Dandy stands out as a work of art. They use <strong>shock and ambiguity</strong> to keep people off-balance and intrigued. <strong>Key tactic:</strong> Challenge expectations. Be deliberately ambiguous. Make yourself a walking spectacle — people are drawn to what they cannot categorize or understand.\"},\n    {n:5, icon:'<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 22c-1.5 0-3-1-3-2.5 0-1.5 1.5-2.5 3-2.5s3 1 3 2.5c0 1.5-1.5 2.5-3 2.5z\"/><path d=\"M12 2v3\"/><path d=\"M12 9v1\"/><path d=\"M12 14v1\"/></svg>', type:\"The Natural\", tagline:\"The Spontaneous Innocent\", preview:\"The Natural is childlike, spontaneous, and disarmingly sincere. They seduce not through strategy but through apparent innocence — they say and do what others only think.\", full:\"The Natural's power is <strong>authenticity in a world of artifice</strong>. They seem to have no guile, no hidden agenda. Their impulsiveness is refreshing. They say shocking things with a smile, touch without self-consciousness, live entirely in the moment. This <strong>unpredictability</strong> is intoxicating. <strong>Key tactic:</strong> Be unselfconsciously yourself — or appear to be. Say what others suppress. Act on impulse. The appearance of authenticity is often more seductive than authenticity itself.\"},\n    {n:6, icon:\"🪢\", type:\"The Coquette\", tagline:\"The Master of Withdrawal\", preview:\"The Coquette is the ultimate strategist of desire — they give just enough hope to keep the target engaged, then withdraw, creating obsessive longing.\", full:\"The Coquette understands a fundamental truth: <strong>desire thrives on frustration</strong>. They alternate warmth and coldness, attention and neglect, hope and disappointment. Each time they return, the target is more desperate. The Coquette <strong>never fully surrenders</strong> — their power lies in perpetual withholding. <strong>Key tactic:</strong> Give just enough to keep them hooked, then pull away. Make them work for your affection. The harder they try, the more they convince themselves they're in love.\"},\n    {n:7, icon:'<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"/><path d=\"M2 17l10 5 10-5\"/><path d=\"M2 12l10 5 10-5\"/></svg>', type:\"The Charmer\", tagline:\"The Social Chameleon\", preview:\"The Charmer adapts to each person's nature, making everyone feel uniquely understood. They pick up on tastes, values, and desires — reflecting them back magnified.\", full:\"The Charmer's gift is <strong>empathy weaponized</strong>. They notice everything — a turn of phrase, a style preference, a hidden insecurity — and mirror it back. They make people feel <strong>seen, heard, and validated</strong> in a way no one else does. The Charmer collects followers by making each feel like a friend. <strong>Key tactic:</strong> Listen more than you speak. Mirror their gestures, vocabulary, and values. Make them feel like the most fascinating person in the room — and they will associate that feeling with you.\"},\n    {n:8, icon:'<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"13 2 3 14 12 14 11 22 21 10 12 10 13 2\"/></svg>', type:\"The Charismatic\", tagline:\"The Magnetic Presence\", preview:\"The Charismatic exudes an intensity that draws others in like a gravitational field. They radiate confidence, purpose, and a sense of destiny that others want to share.\", full:\"The Charismatic's power is <strong>presence</strong>. They have a quality of absolute self-belief that is deeply attractive. They seem to have access to a higher energy, a deeper truth. People <strong>want to be near them</strong>, hoping some of that intensity will rub off. The Charismatic often cultivates an air of <strong>mysterious suffering or profound insight</strong> — they have seen the abyss and returned. <strong>Key tactic:</strong> Cultivate intense self-belief. Develop a compelling life narrative. Speak with absolute conviction. Energy is contagious — make yours the most powerful in the room.\"},\n    {n:9, icon:'<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15.09 8.26 22 9.27 17 14.14 18.18 21.02 12 17.77 5.82 21.02 7 14.14 2 9.27 8.91 8.26 12 2\"/></svg>', type:\"The Star\", tagline:\"The Distant Luminary\", preview:\"The Star creates a larger-than-life persona that transfixes through distance and mystery. They are adored not for who they are, but for the image they project.\", full:\"The Star understands that <strong>distance creates desire</strong>. They construct a persona — a carefully crafted image — and maintain it with discipline. The real person is hidden; the crowd adores the illusion. Stars are <strong>worshiped because they are inaccessible</strong>. Their glamour is a form of power — it sets them apart, makes them objects of fantasy. <strong>Key tactic:</strong> Craft a compelling persona and never break character. Maintain distance — familiarity breeds contempt. Let people project their fantasies onto your image. Be seen but never fully known.\"}\n  ];\n\n  const grid = document.getElementById('seducerGrid');\n\n  function renderSeducers(){\n    seducers.forEach((s, i) => {\n      const card = document.createElement('div');\n      card.className = 'seducer-card';\n      card.dataset.n = s.n;\n      card.innerHTML = `\n        <div class=\"num\">TYPE ${s.n}</div>\n        <span class=\"type-icon\">${s.icon}</span>\n        <h3>${s.type}</h3>\n        <div class=\"tagline\">${s.tagline}</div>\n        <div class=\"preview\">${s.preview}</div>\n        <div class=\"full\"><div class=\"full-inner\">${s.full}</div></div>\n        <div class=\"expand-icon\">+</div>\n        <div class=\"card-shimmer\"></div>\n      `;\n      card.addEventListener('click', () => {\n        const wasOpen = card.classList.contains('open');\n        document.querySelectorAll('.seducer-card.open').forEach(c => c.classList.remove('open'));\n        if (!wasOpen) card.classList.add('open');\n      });\n      grid.appendChild(card);\n    });\n  }\n  renderSeducers();\n\n  //  TIMELINE EXPAND \n  const expandBtn = document.getElementById('expandTimeline');\n  let timelineExpanded = false;\n  expandBtn.addEventListener('click', () => {\n    timelineExpanded = !timelineExpanded;\n    document.querySelectorAll('.tl-details').forEach(d => {\n      d.style.maxHeight = timelineExpanded ? d.scrollHeight + 80 + 'px' : '0';\n    });\n    expandBtn.innerHTML = timelineExpanded ? '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"/></svg> Hide Tactics <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"/></svg>' : '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"/></svg> Reveal Tactics <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"/></svg>';\n  });\n\n  //  TIMELINE CLICK \n  document.querySelectorAll('.tl-item').forEach(item => {\n    item.addEventListener('click', function(){\n      const details = this.querySelector('.tl-details');\n      const isOpen = details.style.maxHeight && details.style.maxHeight !== '0px';\n      document.querySelectorAll('.tl-details').forEach(d => d.style.maxHeight = '0');\n      if (!isOpen) {\n        details.style.maxHeight = details.scrollHeight + 80 + 'px';\n      }\n    });\n  });\n\n  //  QUOTE SLIDER \n  (function(){\n    const slider = document.getElementById('quoteSlider');\n    const nav = document.getElementById('quoteNav');\n    const slides = slider.querySelectorAll('.quote-slide');\n    let current = 0;\n\n    slides.forEach((_, i) => {\n      const dot = document.createElement('button');\n      dot.className = 'quote-dot' + (i === 0 ? ' active' : '');\n      dot.addEventListener('click', () => goTo(i));\n      nav.appendChild(dot);\n    });\n\n    function goTo(i){\n      current = i;\n      slides.forEach((slide, idx) => {\n        slide.style.transform = `translateX(-${current * 100}%)`;\n      });\n      nav.querySelectorAll('.quote-dot').forEach((d, idx) => {\n        d.classList.toggle('active', idx === current);\n      });\n    }\n\n    setInterval(() => {\n      goTo((current + 1) % slides.length);\n    }, 5000);\n  })();\n\n  //  SCROLL REVEAL \n  const observer = new IntersectionObserver((entries) => {\n    entries.forEach(e => {\n      if (e.isIntersecting) e.target.classList.add('visible');\n    });\n  }, { threshold: 0.1 });\n\n  document.querySelectorAll('.seducer-card, .key-item, .anti-item, .tl-item').forEach(el => observer.observe(el));\n</script>\n\n\n\n</body>\n</html>",
  "the-changing-world-order": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n\n\n\n\n<section>\n  <div class=\"stats\">\n    <div class=\"stat\"><div class=\"stat-value\">500+</div><div class=\"stat-label\">Years of History</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">11</div><div class=\"stat-label\">Empires Studied</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">17</div><div class=\"stat-label\">Forces Driving Cycles</div></div>\n    <div class=\"stat\"><div class=\"stat-value\">250</div><div class=\"stat-label\">Year Empire Cycle</div></div>\n  </div>\n</section>\n\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The Premise</div>\n  <h2>Three Big Forces Are <span class=\"hl\">Converging</span></h2>\n  <p class=\"section-desc\">For the first time in our lifetimes, three massive cycles are peaking simultaneously — just as they did in 1930-45.</p>\n\n  <div class=\"where-box\">\n    <p><strong>1. The Long-Term Debt Cycle:</strong> Interest rates are at or near 0%, debt is at all-time highs, and central banks have exhausted their traditional tools. Printing money is the only option left — and it devalues currencies.</p>\n    <p><strong>2. The Domestic Wealth &amp; Power Cycle:</strong> Wealth, values, and political gaps are wider than at any time in our lifetimes. Economic downturns will trigger intense conflict over how to divide the shrinking pie.</p>\n    <p><strong>3. The International Wealth &amp; Power Cycle:</strong> For the first time in his lifetime, Dalio sees the US encountering a true rival — China — challengning it in trade, technology, geopolitics, and capital.</p>\n  </div>\n</section>\n\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The Archetype</div>\n  <h2>The Big Cycle of <span class=\"hl\">Empires</span></h2>\n  <p class=\"section-desc\">Every empire follows the same three-phase arc: Ascent → Top → Decline. Click each phase to expand.</p>\n\n  <div class=\"phase-block\">\n    <h3>Phase 1: Ascent</h3>\n    <div class=\"phase-sub\">50–100 Years of Building</div>\n    <div class=\"phase-note\">Strong education, character, and work ethic → competitiveness → income growth → investment → new technologies → world trade → military strength → financial center → reserve currency.</div>\n  </div>\n\n  <div class=\"phase-block\">\n    <h3>Phase 2: Top</h3>\n    <div class=\"phase-sub\">Seeds of Decline Grow Within Success</div>\n    <div class=\"phase-note\">People become expensive → copied by competitors → decadence sets in → over-borrowing (reserve currency privilege) → empire becomes uneconomical → wealth gaps widen.</div>\n  </div>\n\n  <div class=\"phase-block\">\n    <h3>Phase 3: Decline</h3>\n    <div class=\"phase-sub\">Self-Reinforcing Downward Spiral</div>\n    <div class=\"phase-note\">Debt crisis → printing money → wealth gaps → internal conflict → capital flight → rival powers challenge → revolution/war → destruction → restructuring → new order.</div>\n  </div>\n\n  <h3 style=\"margin-top:2rem; font-size:1.1rem;\">The 6 Stages of the Internal Cycle</h3>\n  <p style=\"font-size:0.85rem; color:var(--text-dim); margin-bottom:1rem;\">Click each stage to learn more.</p>\n\n  <div class=\"stages\" id=\"stages\"></div>\n</section>\n\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The 8 Measures</div>\n  <h2>How Power Is <span class=\"hl\">Measured</span></h2>\n  <p class=\"section-desc\">Dalio created an index of total power from eight composite measures. They rise and fall in a specific order.</p>\n\n  <div class=\"grid grid-2\" style=\"margin-bottom:1.5rem;\">\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"></path><path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z\"></path><path d=\"M14 2v20\"></path></svg></span>\n      <h4>Education</h4>\n      <p><em>The long-leading indicator.</em> Quality of education predicts future competitiveness and innovation. It's the first to rise and the first to decline.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 9H4.5a2.5 2.5 0 0 1 0-5h1\"></path><path d=\"M18 9h1.5a2.5 2.5 0 0 0 0-5H18\"></path><path d=\"M4 22h16\"></path><path d=\"M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22\"></path><path d=\"M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22\"></path><path d=\"M18 2H6v7a6 6 0 0 0 12 0V2Z\"></path></svg></span>\n      <h4>Competitiveness</h4>\n      <p>How cost-effective and productive a country's workers are relative to global peers. Success breeds higher costs, which erodes competitiveness.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M9 18h6\"></path><path d=\"M10 22h4\"></path><path d=\"M15.09 14c.92-.83 1.61-1.95 1.91-3.23C17.52 8.2 15.54 6 13 6c-2.54 0-4.52 2.2-4 4.77.3 1.28.99 2.4 1.91 3.23\"></path><path d=\"M8 14.5A5.5 5.5 0 0 0 16 14\"></path><path d=\"M3 15c0 1.5 1.1 2.5 2 3\"></path><path d=\"M21 15c0 1.5-1.1 2.5-2 3\"></path></svg></span>\n      <h4>Technology</h4>\n      <p>Innovation drives both commercial and military advantage. New technologies create new industries and disrupt existing power structures.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z\"></path><polyline points=\"9 22 9 12 15 12 15 22\"></polyline></svg></span>\n      <h4>Economic Output</h4>\n      <p>Share of global production. The largest economy typically has the most resources to invest in military, infrastructure, and R&amp;D.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"c-icon\">🌍</span>\n      <h4>World Trade Share</h4>\n      <p>Dominance in global trade requires a strong military to protect routes, and a strong financial system to facilitate transactions.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"c-icon\">⚔️</span>\n      <h4>Military Strength</h4>\n      <p>Needed to protect trade, enforce influence, and project power. Expensive to maintain — especially when empire becomes overextended.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"4\" y=\"2\" width=\"16\" height=\"20\" rx=\"2\" ry=\"2\"></rect><path d=\"M9 22v-4h6v4\"></path><line x1=\"8\" y1=\"10\" x2=\"16\" y2=\"10\"></line><line x1=\"8\" y1=\"14\" x2=\"12\" y2=\"14\"></line></svg></span>\n      <h4>Financial Center</h4>\n      <p>The world's leading financial center (Amsterdam → London → New York → Shanghai?) attracts and distributes global capital.</p>\n    </div>\n    <div class=\"card\">\n      <span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 1v22M17 5H9.5a3.5 3.5 0 0 0 0 7h5a3.5 3.5 0 0 1 0 7H6\"></path></svg></span>\n      <h4>Reserve Currency</h4>\n      <p><em>The long-lagging indicator.</em> Last to rise, last to fall. Gives \"exorbitant privilege\" — but always, eventually, every reserve currency dies.</p>\n    </div>\n  </div>\n\n  <div class=\"where-box\" style=\"border-left-color:var(--gold);\">\n    <p><strong>Key insight:</strong> Education rises first, reserve currency falls last. The US still has dollar dominance, but its education and competitiveness have been declining for decades. History says the dollar will eventually follow — the question is when and how.</p>\n  </div>\n</section>\n\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">Case Studies</div>\n  <h2>The Rise &amp; Fall of <span class=\"hl\">Empires</span></h2>\n  <p class=\"section-desc\">Four empires that followed the same archetypical cycle. Click to expand each story.</p>\n\n  <div class=\"grid grid-2\">\n    <div class=\"empire-card\" id=\"ec0\">\n      <div class=\"e-period\">1600s Peak</div>\n      <h4>Dutch Empire</h4>\n      <div class=\"e-desc\">A small country became the world's greatest empire through trade, shipping, and finance.</div>\n      <div class=\"e-detail\"><div class=\"e-detail-inner\">The Dutch created the Dutch East India Company (the first multinational corporation) and Amsterdam became the world's financial center. The guilder was the first reserve currency. Decline came from becoming too expensive, being copied by the British, and overextending militarily. The Anglo-Dutch wars and financial bubbles accelerated the decline.</div></div>\n      <div class=\"e-expand\" onclick=\"toggleEmpire(0)\">+ Expand</div>\n    </div>\n    <div class=\"empire-card\" id=\"ec1\">\n      <div class=\"e-period\">1800s Peak</div>\n      <h4>British Empire</h4>\n      <div class=\"e-desc\">The Industrial Revolution gave Britain a decisive edge in production, trade, and military power.</div>\n      <div class=\"e-detail\"><div class=\"e-detail-inner\">London became the world's financial center, the pound the reserve currency. The Royal Navy ruled the seas. Decline: lost American colonies, faced German/Japanese challenges, took on enormous debt in WWI and WWII, colonies became uneconomical. By 1945, Britain was bankrupt and the US took over as the dominant power.</div></div>\n      <div class=\"e-expand\" onclick=\"toggleEmpire(1)\">+ Expand</div>\n    </div>\n    <div class=\"empire-card\" id=\"ec2\">\n      <div class=\"e-period\">1945 — Present</div>\n      <h4>American Empire</h4>\n      <div class=\"e-desc\">After WWII, the US had 80% of the world's gold, half of global production, and a nuclear monopoly.</div>\n      <div class=\"e-detail\"><div class=\"e-detail-inner\">Bretton Woods (1944) made the dollar the reserve currency. The US built the post-war world order (UN, World Bank, IMF, NATO). Decades of peace and prosperity followed. Now: extreme debt, wealth gaps, political polarization, overextended empire, and a rising China challenger. Classic late-cycle position.</div></div>\n      <div class=\"e-expand\" onclick=\"toggleEmpire(2)\">+ Expand</div>\n    </div>\n    <div class=\"empire-card\" id=\"ec3\">\n      <div class=\"e-period\">600 AD — Present</div>\n      <h4>Chinese Empire</h4>\n      <div class=\"e-desc\">Dominant for centuries, then declined, and is now rising back toward its historical position.</div>\n      <div class=\"e-detail\"><div class=\"e-detail-inner\">China was the world's leading power for most of history before 1800. Then came the \"Century of Humiliation\" (1800-1949). Under Mao (1949-76): foundation building. Deng (1978-2013): reforms, opening up, rapid growth. Xi (2013-present): becoming a world power. Now challenging the US in every domain. History suggests this conflict is natural and predictable.</div></div>\n      <div class=\"e-expand\" onclick=\"toggleEmpire(3)\">+ Expand</div>\n    </div>\n  </div>\n</section>\n\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">The Forces</div>\n  <h2>The 17 Drivers of <span class=\"hl\">Change</span></h2>\n  <p class=\"section-desc\">Dalio identified 17 timeless and universal forces that explain the rises and declines of empires.</p>\n\n  <div class=\"force-header\">\n    <input class=\"force-search\" id=\"forceSearch\" placeholder=\"Search forces by name or keyword...\" autocomplete=\"off\">\n    <span class=\"force-count\" id=\"forceCount\">Showing 17 / 17</span>\n  </div>\n\n  <div class=\"force-list\" id=\"forceList\"></div>\n</section>\n\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">US-China</div>\n  <h2>The Seven <span class=\"hl\">Wars</span></h2>\n  <p class=\"section-desc\">The US and China are now engaged in conflicts across seven domains simultaneously.</p>\n\n  <div class=\"grid grid-2\">\n    <div class=\"card\"><span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z\"></path><polyline points=\"3.27 6.96 12 12.01 20.73 6.96\"></polyline><line x1=\"12\" y1=\"22.08\" x2=\"12\" y2=\"12\"></line></svg></span><h4>Trade/Economic War</h4><p>Tariffs, supply chain decoupling, export controls. Both sides trying to reduce dependence on the other.</p></div>\n    <div class=\"card\"><span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"2\" y=\"3\" width=\"20\" height=\"14\" rx=\"2\" ry=\"2\"></rect><line x1=\"2\" y1=\"20\" x2=\"22\" y2=\"20\"></line><line x1=\"9\" y1=\"3\" x2=\"9\" y2=\"17\"></line><line x1=\"15\" y1=\"3\" x2=\"15\" y2=\"17\"></line></svg></span><h4>Technology War</h4><p>5G, AI, semiconductors, software bans. Who controls the next generation of technology will control the future.</p></div>\n    <div class=\"card\"><span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"></line><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"></path></svg></span><h4>Geopolitical War</h4><p>South China Sea, alliances (Quad, AUKUS vs. Belt &amp; Road), influence in developing nations.</p></div>\n    <div class=\"card\"><span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"4\" y=\"2\" width=\"16\" height=\"20\" rx=\"2\" ry=\"2\"></rect><path d=\"M9 22v-4h6v4\"></path><line x1=\"8\" y1=\"10\" x2=\"16\" y2=\"10\"></line><line x1=\"8\" y1=\"14\" x2=\"12\" y2=\"14\"></line></svg></span><h4>Capital War</h4><p>Sanctions, currency competition, capital controls. China is pushing to internationalize the yuan.</p></div>\n    <div class=\"card\"><span class=\"c-icon\">⚔️</span><h4>Military War</h4><p>Show-of-force operations, proxy conflicts, Taiwan tensions, military buildup on both sides.</p></div>\n    <div class=\"card\"><span class=\"c-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"></path><path d=\"M2 17l10 5 10-5\"></path><path d=\"M2 12l10 5 10-5\"></path></svg></span><h4>Culture War</h4><p>Ideology, values, propaganda, soft power competition. Each side presents its system as superior.</p></div>\n    <div class=\"card\" style=\"grid-column: 1 / -1; text-align:center;\"><span class=\"c-icon\">🪞</span><h4>War with Ourselves</h4><p><em>\"The enemy is us.\"</em> Each country's internal divisions are its greatest vulnerability. A house divided cannot stand.</p></div>\n  </div>\n</section>\n\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">Where We Are</div>\n  <h2>Where the US Is in Its <span class=\"hl\">Big Cycle</span></h2>\n  <p class=\"section-desc\">Dalio's assessment: The US is in the late stage of its cycle — with declining relative power, extreme debt, and internal conflict. China is in its ascent phase.</p>\n\n  <div class=\"where-box\" style=\"border-left-color:var(--orange);\">\n    <p><strong>The current confluence:</strong> The last major destruction/restructuring period was 1930-45. That created a new world order in 1945. It is now 75+ years later — classically near the end of a long-term debt cycle. We have high debt, near-zero rates, large wealth gaps, political polarization, a rising challenger, and a pandemic. This exact confluence happened in 1930-45 — and before that in similar periods.</p>\n    <p class=\"attribution\">— Based on <em>The Changing World Order</em>, Ray Dalio</p>\n  </div>\n</section>\n\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">Perspective</div>\n  <h2>A <span class=\"hl\">Dalio</span> Insight</h2>\n  <p class=\"section-desc\">Each click surfaces a principle from the book's research.</p>\n\n  <div class=\"insight-box\" id=\"insightBox\">\n    <div class=\"i-label\">Timeless &amp; Universal</div>\n    <div class=\"i-text\" id=\"insightText\">\"The only things that change are the clothes the characters are wearing and the technologies they're using.\"</div>\n    <button class=\"btn btn-accent\" id=\"insightBtn\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> Next Insight <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></button>\n  </div>\n</section>\n\n<section>\n  <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></div>\n  <div class=\"section-label\">Principles</div>\n  <h2>How to <span class=\"hl\">Navigate</span> What's Coming</h2>\n  <p class=\"section-desc\">Practical takeaways from Dalio's study of 500+ years of history.</p>\n\n  <div class=\"grid grid-2\">\n    <div class=\"card\"><span class=\"c-icon\">1</span><h4>Know Where You Are in the Cycle</h4><p>Most people miss big changes because they've never experienced them before. Study history to see the patterns.</p></div>\n    <div class=\"card\"><span class=\"c-icon\">2</span><h4>Diversify Across Countries &amp; Currencies</h4><p>Don't bet everything on one country or one currency. Reserve currencies always decline eventually.</p></div>\n    <div class=\"card\"><span class=\"c-icon\">3</span><h4>Don't Confuse the Recent Past with the Future</h4><p>The last 40 years of declining inflation and rising peace were not normal — they were one phase of a long cycle.</p></div>\n    <div class=\"card\"><span class=\"c-icon\">4</span><h4>Watch Leading Indicators</h4><p>Education quality, debt levels, infrastructure investment, and wealth gaps predict where a country is headed.</p></div>\n    <div class=\"card\"><span class=\"c-icon\">5</span><h4>Invest in Adaptability</h4><p>Humanity's power to adapt and invent always wins in the long run. Bad periods don't last forever.</p></div>\n    <div class=\"card\"><span class=\"c-icon\">6</span><h4>Expect Radical Change</h4><p>The next 10-20 years will be radically different from what we've experienced. Prepare mentally and financially.</p></div>\n  </div>\n</section>\n\n\n\n<script>\n  //  THEME \n  const themeToggle = document.getElementById('themeToggle');\n  themeToggle.addEventListener('click', () => {\n    document.body.classList.toggle('light');\n    themeToggle.innerHTML = document.body.classList.contains('light') ? '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>' : '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"/></svg>️';\n  });\n\n  //  EMPIRE EXPAND \n  function toggleEmpire(i) {\n    const card = document.getElementById('ec' + i);\n    card.classList.toggle('open');\n    const expand = card.querySelector('.e-expand');\n    expand.textContent = card.classList.contains('open') ? '− Collapse' : '+ Expand';\n  }\n\n  //  SIX STAGES \n  const stages = [\n    {n:1, title:\"The New Order Begins\", desc:\"New leadership consolidates power. The winning power establishes new rules, systems, and a new world order. Peace and prosperity follow.\", detail:\"This is where empires are born — out of the chaos of war or revolution. The new leader has strong mandate, establishes rule of law, and builds the foundation for future growth.\"},\n    {n:2, title:\"Resource-Allocation Systems Built\", desc:\"Government bureaucracies and resource-allocation systems are developed. Infrastructure, education, and R&D are invested in.\", detail:\"The systems that will drive growth are created. This is the 'building phase' — roads, schools, courts, and financial systems are established. The country becomes more efficient.\"},\n    {n:3, title:\"Peace & Prosperity\", desc:\"The golden era. People work together harmoniously. No one challenges the dominant power. Debt-financed booms begin.\", detail:\"This is the longest phase. The empire is at its peak. Trade flourishes, culture thrives, and wealth is created. But debt begins to accumulate and wealth gaps start to widen.\"},\n    {n:4, title:\"Excesses\", desc:\"Over-borrowing, speculative bubbles, and large wealth gaps emerge. Values and political polarization grow.\", detail:\"The excesses of prosperity sow the seeds of decline. People borrow to consume more than they produce. The rich get richer while others fall behind. Society fragments.\"},\n    {n:5, title:\"Bad Conditions & Intense Conflict\", desc:\"Debt crisis hits. Wealth gaps trigger populism (left vs. right). Internal fighting over how to divide the shrinking pie.\", detail:\"The 'perfect storm' phase. Economic downturn + internal conflict + external challenge = maximum danger. Civil unrest, polarization, and calls for radical change. Democracy is challenged by autocracy.\"},\n    {n:6, title:\"Civil War / Revolution\", desc:\"The old order breaks down. A destructive period of fighting and restructuring. A new leader emerges and the cycle resets.\", detail:\"The destruction phase typically lasts 10-20 years. Debt is restructured or defaulted on. The old system is torn down. New leadership emerges from the chaos and establishes a new order. Then the cycle begins again.\"}\n  ];\n\n  const stagesContainer = document.getElementById('stages');\n  stages.forEach((s, i) => {\n    const el = document.createElement('div');\n    el.className = 'stage-item';\n    el.innerHTML = `\n      <div class=\"s-num\">${s.n}</div>\n      <div class=\"s-body\">\n        <h4>${s.title}</h4>\n        <p>${s.desc}</p>\n        <div class=\"s-detail\"><p>${s.detail}</p></div>\n      </div>\n    `;\n    el.addEventListener('click', () => el.classList.toggle('open'));\n    stagesContainer.appendChild(el);\n  });\n\n  //  17 FORCES \n  const forces = [\n    {n:1, title:\"Long-Term Debt & Money Cycle\", desc:\"The 50-100 year cycle of debt accumulation, credit expansion, and eventual deleveraging. The most important driver of the big cycle.\"},\n    {n:2, title:\"Domestic Wealth & Power Cycle\", desc:\"The cycle of wealth concentration and redistribution within a country. Large gaps lead to conflict and systemic change.\"},\n    {n:3, title:\"International Wealth & Power Cycle\", desc:\"The cycle of rising and declining empires competing for global dominance. Emerging challengers vs. existing powers.\"},\n    {n:4, title:\"Education Quality\", desc:\"The long-leading indicator. Strong education produces skilled workers, innovation, and social cohesion.\"},\n    {n:5, title:\"Competitiveness\", desc:\"Cost-effective, productive workers relative to global peers. Erodes as a country becomes richer.\"},\n    {n:6, title:\"Innovation & Technology\", desc:\"New technologies drive commercial and military advantage. The source of productivity gains.\"},\n    {n:7, title:\"Economic Output\", desc:\"Share of global production. The larger the economy, the more resources available for investment and military.\"},\n    {n:8, title:\"Share of World Trade\", desc:\"Dominance in global trade requires military protection and financial infrastructure.\"},\n    {n:9, title:\"Military Strength\", desc:\"Needed to protect trade routes and project power. Becomes a burden when empire is overextended.\"},\n    {n:10, title:\"Financial Center Strength\", desc:\"The world's leading financial center attracts global capital and provides economic influence.\"},\n    {n:11, title:\"Reserve Currency Status\", desc:\"The privilege of printing the world's primary currency. Always lost eventually — usually traumatically.\"},\n    {n:12, title:\"Leadership Quality\", desc:\"Strong leadership can steer a country through difficult transitions. Weak leadership accelerates decline.\"},\n    {n:13, title:\"Internal Order & Disorder\", desc:\"The balance between civility, rule of law, and conflict. Cycles between harmony and chaos.\"},\n    {n:14, title:\"External Order & Disorder\", desc:\"The relationships between world powers. Periods of peace vs. periods of war and competition.\"},\n    {n:15, title:\"Acts of Nature\", desc:\"Pandemics, droughts, floods, and natural disasters that stress-test societies and accelerate existing trends.\"},\n    {n:16, title:\"Productivity Evolution\", desc:\"The long-term upward trend in output per person driven by learning and technology. The foundation of rising living standards.\"},\n    {n:17, title:\"Class Struggle Dynamic\", desc:\"The tension between those who have wealth/power and those who don't. The driver of internal revolutions.\"}\n  ];\n\n  const forceList = document.getElementById('forceList');\n  const forceSearch = document.getElementById('forceSearch');\n  const forceCount = document.getElementById('forceCount');\n\n  function renderForces(filter = '') {\n    forceList.innerHTML = '';\n    const q = filter.toLowerCase();\n    let visible = 0;\n\n    forces.forEach(f => {\n      const match = !q ||\n        f.title.toLowerCase().includes(q) ||\n        f.desc.toLowerCase().includes(q);\n\n      if (match) visible++;\n\n      const el = document.createElement('div');\n      el.className = `force-item${match ? '' : ' hidden'}`;\n      el.innerHTML = `\n        <div class=\"f-num\">${String(f.n).padStart(2, '0')}</div>\n        <div class=\"f-body\">\n          <h4>${f.title}</h4>\n          <p>${f.desc}</p>\n        </div>\n      `;\n      forceList.appendChild(el);\n    });\n\n    forceCount.textContent = `Showing ${visible} / ${forces.length}`;\n  }\n\n  renderForces();\n  forceSearch.addEventListener('input', (e) => renderForces(e.target.value));\n\n  //  SCROLL REVEAL \n  const observer = new IntersectionObserver((entries) => {\n    entries.forEach(e => { if (e.isIntersecting) e.target.classList.add('visible'); });\n  }, { threshold: 0.1 });\n\n  document.querySelectorAll('.force-item, .stage-item, .card, .empire-card').forEach(el => observer.observe(el));\n\n  //  INSIGHT GENERATOR \n  const insights = [\n    \"\\\"The only things that change are the clothes the characters are wearing and the technologies they're using.\\\"\",\n    \"\\\"The times ahead will be radically different from the times we have experienced so far in our lifetimes, though similar to many other times in history.\\\"\",\n    \"\\\"If some big and important event had happened in the past, I couldn't say for sure that it wouldn't happen to me.\\\"\",\n    \"\\\"There are only a limited number of personality types going down a limited number of paths to produce a limited number of stories that repeat over time.\\\"\",\n    \"Reserve currency status is the last strength to rise and the last to fall — but it always falls.\",\n    \"Debt eats equity: when you can't service debt, creditors take over your assets.\",\n    \"The most dangerous time is when economic downturn, internal conflict, and external challenge converge.\",\n    \"Humanity's power to adapt and invent is greater than all the bad stuff that can be thrown at us.\",\n    \"Education is the long-leading indicator. Reserve currency is the long-lagging indicator.\",\n    \"The person who clears the path ultimately controls its direction.\",\n    \"Prosperous periods lead to excesses that sow the seeds of the next decline.\",\n    \"It takes less time and money to copy than to invent — so emerging empires always gain on mature ones.\",\n    \"The empire cycle lasts about 250 years, give or take 150. Bad periods: 10-20 years. Good periods: 40-80 years.\",\n    \"When wealth and values gaps are large and there's an economic downturn, expect intense conflict over the shrinking pie.\",\n    \"Populists tend to be more autocratic, more inclined to fight, and more inclined to respect power than law.\",\n    \"Just as a doctor studies many cases of a disease, Dalio studies many cases of historical cycles to understand the archetype.\",\n    \"The most important thing is to know where you are in the cycle — and most people don't.\"\n  ];\n  const insightText = document.getElementById('insightText');\n  const insightBtn = document.getElementById('insightBtn');\n\n  insightBtn.addEventListener('click', () => {\n    insightText.classList.add('fade');\n    setTimeout(() => {\n      const random = insights[Math.floor(Math.random() * insights.length)];\n      insightText.textContent = random;\n      insightText.classList.remove('fade');\n    }, 300);\n  });\n</script>\n\n\n\n</body>\n</html>",
  "the-concise-laws": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div id=\"progress\"></div>\n\n<canvas id=\"bgCanvas\"></canvas>\n<div id=\"orbs\"></div>\n<div id=\"noise\"></div>\n<div id=\"mouseGlow\"></div>\n\n<!--  HERO  -->\n\n\n<!--  STATS  -->\n<div class=\"stats-bar\">\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <div class=\"reveal\"><h2>Overview</h2><div class=\"line\"></div></div>\n    </div>\n    <div class=\"stats-grid\">\n      <div class=\"stat-card\"><div class=\"stat-icon\">♛</div><div class=\"stat-num\">18</div><div class=\"stat-label\">Timeless Laws</div></div>\n      <div class=\"stat-card\"><div class=\"stat-icon\">⚙</div><div class=\"stat-num\">3</div><div class=\"stat-label\">Core Categories</div></div>\n      <div class=\"stat-card\"><div class=\"stat-icon\">★</div><div class=\"stat-num\">300+</div><div class=\"stat-label\">Pages of Insight</div></div>\n      <div class=\"stat-card\"><div class=\"stat-icon\">✎</div><div class=\"stat-num\">18</div><div class=\"stat-label\">Reflection Prompts</div></div>\n      <div class=\"stat-card\"><div class=\"stat-icon\">☰</div><div class=\"stat-num\">9</div><div class=\"stat-label\">Thematic Pillars</div></div>\n    </div>\n  </div>\n</div>\n\n<div class=\"section-divider\"><div class=\"divider-line\"></div></div>\n\n<!--  FILTER BAR  -->\n<div class=\"filter-bar\">\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <div class=\"reveal\"><h2>The 18 Laws</h2><div class=\"line\"></div><p>Click any law to expand and explore its full meaning</p></div>\n    </div>\n    <div class=\"filter-grid\">\n      <button class=\"filter-pill active\" data-filter=\"all\">All Laws</button>\n      <button class=\"filter-pill\" data-filter=\"self-mastery\">Self-Mastery</button>\n      <button class=\"filter-pill\" data-filter=\"social-dynamics\">Social Dynamics</button>\n      <button class=\"filter-pill\" data-filter=\"psychology\">Psychology &amp; Mindset</button>\n    </div>\n    <div class=\"laws-grid\" id=\"lawsGrid\"></div>\n  </div>\n</div>\n\n<div class=\"section-divider\"><div class=\"divider-line\"></div></div>\n\n<!--  THEMES  -->\n<div class=\"themes-section\">\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <div class=\"reveal\"><h2>Key Themes</h2><div class=\"line\"></div><p>The foundational pillars that run through Greene's work</p></div>\n    </div>\n    <div class=\"themes-grid\">\n      <div class=\"theme-card\">\n        <div class=\"theme-glow\"></div>\n        <div class=\"theme-icon\">⚡</div>\n        <h3>Irrationality</h3>\n        <p>Humans are fundamentally emotional creatures who rationalize after the fact. Mastery begins by recognizing your own emotional triggers and learning to pause before reacting.</p>\n      </div>\n      <div class=\"theme-card\">\n        <div class=\"theme-glow\"></div>\n        <div class=\"theme-icon\">★</div>\n        <h3>Narcissism</h3>\n        <p>Everyone operates with a degree of narcissism. The key is transforming self-absorption into genuine empathy and understanding of others' perspectives.</p>\n      </div>\n      <div class=\"theme-card\">\n        <div class=\"theme-glow\"></div>\n        <div class=\"theme-icon\">🎭</div>\n        <h3>Role-Playing</h3>\n        <p>Social life is theater. People wear masks and perform roles. Learning to see through these performances reveals true intentions and character.</p>\n      </div>\n      <div class=\"theme-card\">\n        <div class=\"theme-glow\"></div>\n        <div class=\"theme-icon\">⚔</div>\n        <h3>The Law of Aggression</h3>\n        <p>Aggression is a natural human drive. Rather than suppressing it, channel it into productive ambition. Recognize passive aggression in others before it harms you.</p>\n      </div>\n      <div class=\"theme-card\">\n        <div class=\"theme-glow\"></div>\n        <div class=\"theme-icon\">📖</div>\n        <h3>Compulsive Behavior</h3>\n        <p>Character is revealed through patterns, not isolated actions. Watch how people behave under pressure—their repetitive habits expose their true nature.</p>\n      </div>\n      <div class=\"theme-card\">\n        <div class=\"theme-glow\"></div>\n        <div class=\"theme-icon\">👁</div>\n        <h3>Envy &amp; Covetousness</h3>\n        <p>Envy is the most toxic emotion. People rarely admit it, but it drives much of human behavior. Learn to detect it and avoid provoking it in others.</p>\n      </div>\n      <div class=\"theme-card\">\n        <div class=\"theme-glow\"></div>\n        <div class=\"theme-icon\">👥</div>\n        <h3>Conformity &amp; Group Dynamics</h3>\n        <p>Individuals lose themselves in groups. The pull to conform is immense. Awareness of this force is the first step to maintaining independent thought.</p>\n      </div>\n      <div class=\"theme-card\">\n        <div class=\"theme-glow\"></div>\n        <div class=\"theme-icon\">📈</div>\n        <h3>Generational Myopia</h3>\n        <p>Each generation believes it is unique and enlightened, yet it repeats the patterns of those before. Seeing the collective cycle frees you from its grip.</p>\n      </div>\n      <div class=\"theme-card\">\n        <div class=\"theme-glow\"></div>\n        <div class=\"theme-icon\">☢</div>\n        <h3>Death &amp; Grandiosity</h3>\n        <p>Awareness of mortality can either paralyze or liberate. Meditating on death reveals what truly matters and deflates the grandiose ego.</p>\n      </div>\n    </div>\n  </div>\n</div>\n\n<div class=\"section-divider\"><div class=\"divider-line\"></div></div>\n\n<!--  QUOTES  -->\n<div class=\"quotes-section\">\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <div class=\"reveal\"><h2>Essential Quotes</h2><div class=\"line\"></div></div>\n    </div>\n    <div class=\"quotes-carousel\">\n      <div class=\"quote-card\">\n        <div class=\"quote-mark\">“</div>\n        <blockquote>The greatest enemy of rational thought is not a lack of intelligence, but the emotional currents that run beneath our conscious awareness.</blockquote>\n        <div class=\"quote-attribution\">Robert Greene, The Concise Laws of Human Nature</div>\n      </div>\n      <div class=\"quote-card\">\n        <div class=\"quote-mark\">“</div>\n        <blockquote>We imagine ourselves as the heroes of our own story, but we are often the unknowing pawns of forces we refuse to see.</blockquote>\n        <div class=\"quote-attribution\">Robert Greene</div>\n      </div>\n      <div class=\"quote-card\">\n        <div class=\"quote-mark\">“</div>\n        <blockquote>To understand human nature is to understand that people are not rational. They are emotional creatures who rationalize after the fact.</blockquote>\n        <div class=\"quote-attribution\">Robert Greene</div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<div class=\"section-divider\"><div class=\"divider-line\"></div></div>\n\n<!--  SELF-REFLECTION TOOL  -->\n<div class=\"reflection-section\">\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <div class=\"reveal\"><h2>Self-Reflection Tool</h2><div class=\"line\"></div><p>Choose a law and explore a guided reflection prompt to deepen your understanding</p></div>\n    </div>\n    <div class=\"reflection-tool\">\n      <h3>Guided Reflection</h3>\n      <p class=\"reflection-desc\">Select a law and optionally enter a personal context to generate a targeted reflection question.</p>\n      <div class=\"reflection-controls\">\n        <select id=\"reflectionSelect\">\n          <option value=\"\">Choose a law...</option>\n        </select>\n        <input type=\"text\" id=\"reflectionContext\" placeholder=\"Your context (e.g., a situation at work)...\" maxlength=\"100\">\n        <button id=\"reflectBtn\">Reflect</button>\n      </div>\n      <div class=\"reflection-output\" id=\"reflectionOutput\"></div>\n    </div>\n  </div>\n</div>\n\n<!--  FOOTER  -->\n\n\n<script>\n//  CANVAS PARTICLES \n(function(){\n  const canvas = document.getElementById('bgCanvas');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n  let mouse = {x: -1000, y: -1000};\n\n  function resize(){\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resize();\n  window.addEventListener('resize', resize);\n\n  const colors = ['#c8a84a', '#e8c860', '#c0c8d8', '#7a8aaa', '#5a6a8a'];\n\n  class Particle {\n    constructor(){this.reset();}\n    reset(){\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.vx = (Math.random() - 0.5) * 0.2;\n      this.vy = (Math.random() - 0.5) * 0.2;\n      this.r = Math.random() * 1.5 + 0.5;\n      this.color = colors[Math.floor(Math.random() * colors.length)];\n      this.alpha = Math.random() * 0.15 + 0.05;\n    }\n    update(){\n      this.x += this.vx;\n      this.y += this.vy;\n      if (this.x < 0 || this.x > canvas.width) this.vx *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.vy *= -1;\n    }\n    draw(){\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);\n      ctx.fillStyle = this.color;\n      ctx.globalAlpha = this.alpha;\n      ctx.fill();\n      ctx.globalAlpha = 1;\n    }\n  }\n\n  for (let i = 0; i < 50; i++) particles.push(new Particle());\n\n  function animate(){\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const d = Math.sqrt(dx*dx + dy*dy);\n        if (d < 120) {\n          ctx.beginPath();\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.strokeStyle = particles[i].color;\n          ctx.globalAlpha = 0.04 * (1 - d/120);\n          ctx.stroke();\n          ctx.globalAlpha = 1;\n        }\n      }\n    }\n    particles.forEach(p => {\n      const dx = p.x - mouse.x;\n      const dy = p.y - mouse.y;\n      const d = Math.sqrt(dx*dx + dy*dy);\n      if (d < 150) {\n        ctx.beginPath();\n        ctx.moveTo(p.x, p.y);\n        ctx.lineTo(mouse.x, mouse.y);\n        ctx.strokeStyle = p.color;\n        ctx.globalAlpha = 0.06 * (1 - d/150);\n        ctx.stroke();\n        ctx.globalAlpha = 1;\n      }\n    });\n    particles.forEach(p => { p.update(); p.draw(); });\n    requestAnimationFrame(animate);\n  }\n  animate();\n\n  document.addEventListener('mousemove', e => {\n    mouse.x = e.clientX;\n    mouse.y = e.clientY;\n  });\n})();\n\n//  FLOATING ORBS \n(function(){\n  const c = document.getElementById('orbs');\n  const orbColors = [\n    'rgba(200,168,74,0.10)',\n    'rgba(192,200,216,0.06)',\n    'rgba(90,106,138,0.06)',\n    'rgba(200,168,74,0.08)'\n  ];\n  for (let i = 0; i < 5; i++) {\n    const o = document.createElement('div');\n    o.className = 'orb';\n    const size = 150 + Math.random() * 250;\n    o.style.cssText = `\n      width:${size}px;height:${size}px;\n      left:${Math.random()*100}%;\n      top:${Math.random()*100}%;\n      background:${orbColors[i % orbColors.length]};\n      --duration:${20 + Math.random() * 30}s;\n      --delay:${Math.random() * 10}s;\n      --max-opacity:0.35;\n      --tx:${(Math.random()-0.5)*400}px;\n      --ty:${(Math.random()-0.5)*400}px;\n    `;\n    c.appendChild(o);\n  }\n})();\n\n//  MOUSE GLOW \nconst mouseGlow = document.getElementById('mouseGlow');\ndocument.addEventListener('mousemove', e => {\n  mouseGlow.style.left = e.clientX + 'px';\n  mouseGlow.style.top = e.clientY + 'px';\n});\n\n//  SCROLL PROGRESS \nwindow.addEventListener('scroll', () => {\n  const s = window.scrollY / (document.body.scrollHeight - window.innerHeight) * 100;\n  document.getElementById('progress').style.width = s + '%';\n});\n\n//  COUNTER ANIMATION \n(function(){\n  const counters = document.querySelectorAll('.hs-num');\n  const observer = new IntersectionObserver((entries) => {\n    entries.forEach(entry => {\n      if (entry.isIntersecting) {\n        const el = entry.target;\n        const target = parseInt(el.dataset.target);\n        let current = 0;\n        const step = Math.max(1, Math.floor(target / 40));\n        const interval = setInterval(() => {\n          current += step;\n          if (current >= target) { current = target; clearInterval(interval); }\n          el.textContent = current + (target > 100 ? '+' : '');\n        }, 25);\n        observer.unobserve(el);\n      }\n    });\n  }, {threshold: 0.5});\n  counters.forEach(c => observer.observe(c));\n})();\n\n//  SCROLL REVEAL \n(function(){\n  const reveals = document.querySelectorAll('.reveal, .theme-card, .quote-card');\n  const observer = new IntersectionObserver((entries) => {\n    entries.forEach(entry => {\n      if (entry.isIntersecting) {\n        entry.target.classList.add('visible');\n        observer.unobserve(entry.target);\n      }\n    });\n  }, {threshold: 0.15});\n  reveals.forEach(el => observer.observe(el));\n})();\n\n//  THEME TOGGLE \n(function(){\n  const btn = document.getElementById('themeToggle');\n  let dark = true;\n  btn.addEventListener('click', () => {\n    dark = !dark;\n    document.body.classList.toggle('light', !dark);\n    btn.innerHTML = dark ? '&#9790;' : '&#9788;';\n  });\n})();\n\n//  LAWS DATA \nconst laws = [\n  {\n    id:1, title:'The Law of Irrationality', subtitle:'Master Your Emotional Self',\n    cat:'self-mastery',\n    desc:'You are not rational. You are an emotional creature who rationalizes. The first law of human nature is to recognize that your emotions drive your decisions more than your logic. Until you master this, you will remain a slave to unconscious impulses.',\n    motto:'Think twice before you act — your first instinct is often your emotions speaking.',\n    key:'Practice the 6-second rule: pause for six seconds before responding to any emotional trigger.'\n  },\n  {\n    id:2, title:'The Law of Narcissism', subtitle:'Transform Self-love into Empathy',\n    cat:'psychology',\n    desc:'Everyone suffers from some degree of narcissism. The key is to recognize it in yourself and others. Transform your self-absorption into genuine empathy by learning to see the world from another person\\'s perspective without judgment.',\n    motto:'The most attractive quality is the ability to make others feel seen and understood.',\n    key:'Practice active listening — focus entirely on the other person without preparing your response.'\n  },\n  {\n    id:3, title:'The Law of Role-Playing', subtitle:'See Through People\\'s Masks',\n    cat:'social-dynamics',\n    desc:'Social life is a theater. Everyone adopts a persona, a mask they wear for the world. To understand human nature, you must learn to see past these performances and recognize the unconscious roles people play.',\n    motto:'Pay more attention to what people do than what they say — actions reveal the true script.',\n    key:'Observe discrepancies between a person\\'s words and their nonverbal behavior.'\n  },\n  {\n    id:4, title:'The Law of Compulsive Behavior', subtitle:'Determine the Strength of People\\'s Character',\n    cat:'social-dynamics',\n    desc:'Character is not defined by isolated actions but by consistent patterns of behavior. Watch how people act under pressure, how they treat those beneath them, and how they handle small temptations. These patterns reveal their true nature.',\n    motto:'A single act of kindness means little; a pattern of behavior means everything.',\n    key:'Pay attention to how people react to boredom, frustration, and small annoyances.'\n  },\n  {\n    id:5, title:'The Law of Covetousness', subtitle:'Become an Elusive Object of Desire',\n    cat:'psychology',\n    desc:'People desire what they cannot have. The more accessible you are, the less you are valued. To command attention and respect, cultivate an air of mystery and scarcity. Make others work for your approval.',\n    motto:'What is rare and difficult to obtain is valued; what is abundant is taken for granted.',\n    key:'Withhold full disclosure — let people discover you gradually.'\n  },\n  {\n    id:6, title:'The Law of Shortsightedness', subtitle:'Elevate Your Perspective',\n    cat:'self-mastery',\n    desc:'Humans are wired to focus on the immediate and the visible. We sacrifice long-term gain for short-term pleasure. The rational mind can override this impulse if you train yourself to step back and see the bigger picture.',\n    motto:'The best decisions are made by those who can see beyond the present moment.',\n    key:'Before any major decision, ask: \"What will the consequences be in 6 months? 5 years?\"'\n  },\n  {\n    id:7, title:'The Law of Defensiveness', subtitle:'Soften People\\'s Resistance',\n    cat:'psychology',\n    desc:'People are deeply invested in their self-opinion. Criticizing or attacking someone\\'s self-image triggers immediate defensiveness. To influence others, first validate their sense of self — then gently guide them toward your perspective.',\n    motto:'Criticism is the fastest way to make someone dig in their heels.',\n    key:'Frame feedback as a shared exploration: \"I wonder if we might consider...\"'\n  },\n  {\n    id:8, title:'The Law of Self-Sabotage', subtitle:'Change Your Narrative',\n    cat:'self-mastery',\n    desc:'Your past does not determine your future — your interpretation of your past does. We all carry internal narratives that either empower or limit us. By rewriting your story, you can break free from patterns of self-sabotage.',\n    motto:'You are not the victim of your past; you are the author of your future.',\n    key:'Identify the core belief underlying a repeated self-sabotaging pattern.'\n  },\n  {\n    id:9, title:'The Law of Repression', subtitle:'Confront Your Dark Side',\n    cat:'self-mastery',\n    desc:'The traits you repress in yourself — your shadow — will control you from the unconscious. What you deny in yourself, you will project onto others. Integration of your dark side is essential for genuine self-mastery.',\n    motto:'What you resist in yourself, you will despise in others.',\n    key:'Notice what irritates you most about others — it often reflects what you deny in yourself.'\n  },\n  {\n    id:10, title:'The Law of Envy', subtitle:'Beware the Splintered Eye',\n    cat:'psychology',\n    desc:'Envy is the most dangerous and hidden emotion. People rarely admit to it, but it poisons relationships and drives irrational behavior. Learn to detect the subtle signs of envy and avoid displaying your success in ways that provoke it.',\n    motto:'The greatest insults come not from enemies, but from those who envy you.',\n    key:'Downplay your successes in the presence of those who may feel inferior.'\n  },\n  {\n    id:11, title:'The Law of Grandiosity', subtitle:'Know Your Limits',\n    cat:'psychology',\n    desc:'The grandiose person believes they are special, unique, and above the rules that apply to everyone else. This delusion inevitably leads to downfall. True power lies in knowing your limitations and maintaining a realistic self-assessment.',\n    motto:'The taller the tower of ego, the harder the fall.',\n    key:'Seek honest feedback from trusted sources who will tell you what you need to hear.'\n  },\n  {\n    id:12, title:'The Law of Gender Rigidity', subtitle:'Reconnect to the Masculine or Feminine Within',\n    cat:'psychology',\n    desc:'Each person contains both masculine and feminine qualities. Rigid adherence to gender roles limits your psychological range and effectiveness. The most adaptive individuals cultivate access to the full spectrum of human traits.',\n    motto:'Strength without empathy is brutality; empathy without strength is weakness.',\n    key:'Develop the qualities you have rejected as \"not like me\" — they are latent strengths.'\n  },\n  {\n    id:13, title:'The Law of Aimlessness', subtitle:'Advance with a Sense of Purpose',\n    cat:'psychology',\n    desc:'Without a clear sense of purpose, you drift through life at the mercy of circumstance and other people\\'s agendas. A defined purpose focuses your energy, attracts opportunities, and gives you the resilience to weather setbacks.',\n    motto:'Those with a clear purpose shape the world; those without are shaped by it.',\n    key:'Articulate your purpose in one sentence — if you can\\'t, you haven\\'t found it yet.'\n  },\n  {\n    id:14, title:'The Law of Conformity', subtitle:'Resist the Group\\'s Pull',\n    cat:'social-dynamics',\n    desc:'Humans are social animals with a deep need to belong. Groups exert an invisible pressure to conform that can override individual judgment and morality. Awareness of this force is the first and most critical step to maintaining your independence.',\n    motto:'The group is not always right — history proves the crowd is often dangerously wrong.',\n    key:'When everyone agrees, appoint someone to play devil\\'s advocate.'\n  },\n  {\n    id:15, title:'The Law of Fickleness', subtitle:'Make Them Want to Follow You',\n    cat:'social-dynamics',\n    desc:'People are fickle — their loyalties shift based on their perceived self-interest. To create lasting influence, you must appeal to people\\'s deeper needs: security, belonging, status, and meaning. Give them a compelling reason to stay.',\n    motto:'Loyalty is not given freely; it is earned through consistent value.',\n    key:'Focus on what you can give, not what you can take — generosity builds lasting bonds.'\n  },\n  {\n    id:16, title:'The Law of Aggression', subtitle:'Be the Master of Your Aggression',\n    cat:'psychology',\n    desc:'Aggression is a natural, primal drive that society teaches us to suppress. But suppressed aggression turns inward or emerges as passive-aggression. The goal is not to eliminate aggression but to channel it into productive assertiveness.',\n    motto:'Suppressed aggression doesn\\'t disappear — it finds toxic outlets.',\n    key:'Use controlled confrontation as a tool for clarity, not as a weapon for destruction.'\n  },\n  {\n    id:17, title:'The Law of Generational Myopia', subtitle:'See the Collective',\n    cat:'social-dynamics',\n    desc:'Each generation believes it is unique, more enlightened, and free from the biases of the past. Yet the same cycles repeat — rebellion, materialism, disillusionment, and return to tradition. Seeing the pattern frees you from it.',\n    motto:'Those who cannot see the generational cycle are doomed to repeat its mistakes.',\n    key:'Study history not for facts, but for patterns — human nature changes little.'\n  },\n  {\n    id:18, title:'The Law of Death Denial', subtitle:'Meditate on Your Death',\n    cat:'self-mastery',\n    desc:'Modern society denies death, pushing it out of sight and mind. But avoiding death awareness makes you live superficially. Regular contemplation of mortality strips away trivial concerns and reveals what truly matters.',\n    motto:'Death is not the end of life but the intensifier of it.',\n    key:'Ask yourself daily: \"If this were my last year, how would I spend it?\"'\n  }\n];\n\nconst catDisplay = {\n  'self-mastery': 'Self-Mastery',\n  'social-dynamics': 'Social Dynamics',\n  'psychology': 'Psychology & Mindset'\n};\n\n//  RENDER LAWS \nconst grid = document.getElementById('lawsGrid');\nconst filterPills = document.querySelectorAll('.filter-pill');\nlet activeFilter = 'all';\n\nfunction renderLaws(){\n  grid.innerHTML = '';\n  const filtered = activeFilter === 'all' ? laws : laws.filter(l => l.cat === activeFilter);\n\n  filtered.forEach((law, i) => {\n    const card = document.createElement('div');\n    card.className = 'law-card';\n    card.dataset.id = law.id;\n    card.innerHTML = `\n      <div class=\"card-accent-bar\"></div>\n      <div class=\"shimmer-line\"></div>\n      <div class=\"law-number\">${String(law.id).padStart(2,'0')}</div>\n      <div class=\"law-header\">\n        <div class=\"law-num-badge\">${law.id}</div>\n        <div class=\"law-title-group\">\n          <div class=\"law-title\">${law.title}</div>\n          <div class=\"law-subtitle\">${law.subtitle}</div>\n        </div>\n      </div>\n      <div class=\"law-body\">\n        <div class=\"law-motto\">${law.motto}</div>\n        <p>${law.desc}</p>\n        <div class=\"law-key\"><strong>&#9656; Key Practice:</strong> ${law.key}</div>\n      </div>\n      <div class=\"law-expand-hint\">\n        <span class=\"law-cat\">${catDisplay[law.cat] || law.cat}</span>\n        <span class=\"law-toggle\">\n          <span>Expand</span>\n          <svg width=\"12\" height=\"12\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"m6 9 6 6 6-6\"/></svg>\n        </span>\n      </div>\n    `;\n\n    card.addEventListener('click', (e) => {\n      if (e.target.closest('.law-body')) return;\n      card.classList.toggle('expanded');\n      const toggle = card.querySelector('.law-toggle span');\n      toggle.textContent = card.classList.contains('expanded') ? 'Collapse' : 'Expand';\n    });\n\n    grid.appendChild(card);\n  });\n\n  requestAnimationFrame(() => {\n    document.querySelectorAll('.law-card').forEach((el, i) => {\n      setTimeout(() => el.classList.add('visible'), i * 60);\n    });\n  });\n}\n\nrenderLaws();\n\nfilterPills.forEach(pill => {\n  pill.addEventListener('click', () => {\n    filterPills.forEach(p => p.classList.remove('active'));\n    pill.classList.add('active');\n    activeFilter = pill.dataset.filter;\n    renderLaws();\n  });\n});\n\n//  SELF-REFLECTION TOOL \n(function(){\n  const select = document.getElementById('reflectionSelect');\n  const ctxInput = document.getElementById('reflectionContext');\n  const btn = document.getElementById('reflectBtn');\n  const output = document.getElementById('reflectionOutput');\n\n  const reflectionPrompts = {\n    self_mastery: [\n      'What emotional trigger most often leads you to act against your own best interest?',\n      'Where in your life are you prioritizing short-term comfort over long-term growth?',\n      'What story have you been telling yourself that may no longer be true?',\n      'What aspect of yourself do you judge most harshly in others?',\n      'If you had one year to live, what would you stop doing immediately?'\n    ],\n    social_dynamics: [\n      'Who in your life wears a mask that differs most from their true self?',\n      'In what situations do you find yourself conforming against your better judgment?',\n      'How do you react when someone criticizes you — do you become defensive?',\n      'What patterns do you notice in how people behave when they think no one is watching?',\n      'How can you make the people in your life feel more genuinely seen?'\n    ],\n    psychology: [\n      'Where does envy subtly influence your feelings toward others?',\n      'In what area of your life do you overestimate your abilities or importance?',\n      'How can you cultivate the qualities you have rejected as \"not like me\"?',\n      'What is your one-sentence life purpose — and is it truly yours or someone else\\'s?',\n      'How do you channel your aggressive drives into productive assertiveness?'\n    ]\n  };\n\n  laws.forEach(l => {\n    const opt = document.createElement('option');\n    opt.value = l.id;\n    opt.textContent = `Law ${l.id}: ${l.title}`;\n    select.appendChild(opt);\n  });\n\n  btn.addEventListener('click', () => {\n    const lawId = parseInt(select.value);\n    const context = ctxInput.value.trim();\n    if (!lawId) { output.textContent = 'Please select a law.'; output.classList.add('show'); return; }\n\n    const law = laws.find(l => l.id === lawId);\n    const prompts = reflectionPrompts[law.cat.replace('-','_')] || reflectionPrompts.self_mastery;\n    const prompt = prompts[Math.floor(Math.random() * prompts.length)];\n\n    output.innerHTML = '';\n    output.classList.add('show');\n\n    const q = document.createElement('div');\n    q.className = 'ref-q';\n    q.textContent = `Law ${law.id}: ${law.title}`;\n\n    const p = document.createElement('div');\n    p.className = 'ref-prompt';\n    p.textContent = prompt;\n\n    if (context) {\n      const c = document.createElement('div');\n      c.style.cssText = 'font-size:0.75rem;color:var(--text-muted);margin-top:0.5rem;';\n      c.innerHTML = 'Context: <em>' + context + '</em>';\n      output.append(q, p, c);\n    } else {\n      output.append(q, p);\n    }\n  });\n\n  select.addEventListener('change', () => { output.classList.remove('show'); });\n  ctxInput.addEventListener('input', () => { output.classList.remove('show'); });\n})();\n</script>\n\n\n\n</body>\n</html>",
  "the-laws-of-human-nature": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div id=\"progress\"></div>\n<canvas id=\"bgCanvas\"></canvas>\n<div id=\"orbs\"></div>\n<div id=\"noise\"></div>\n<div id=\"mouseGlow\"></div>\n\n<!-- TOC -->\n<div id=\"tocOverlay\"></div>\n\n<button id=\"tocToggle\" aria-label=\"Table of Contents\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><line x1=\"3\" y1=\"6\" x2=\"21\" y2=\"6\"></line><line x1=\"3\" y1=\"12\" x2=\"21\" y2=\"12\"></line><line x1=\"3\" y1=\"18\" x2=\"21\" y2=\"18\"></line></svg></button>\n<button id=\"themeToggle\" aria-label=\"Toggle theme\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"></path></svg></button>\n\n<!--  HERO  -->\n\n\n<!--  STATS  -->\n<div class=\"stats-bar reveal\">\n  <div class=\"container\">\n    <div class=\"stats-grid\">\n      <div class=\"stat-item\">\n        <div class=\"stat-number\" data-count=\"18\">0</div>\n        <div class=\"stat-label\">Laws of Nature</div>\n      </div>\n      <div class=\"stat-item\">\n        <div class=\"stat-number\" data-count=\"2500\">0</div>\n        <div class=\"stat-label\">Years of Wisdom</div>\n      </div>\n      <div class=\"stat-item\">\n        <div class=\"stat-number\" data-count=\"36\">0</div>\n        <div class=\"stat-label\">Historical Examples</div>\n      </div>\n      <div class=\"stat-item\">\n        <div class=\"stat-number\" data-count=\"400\">0</div>\n        <div class=\"stat-label\">Pages of Insight</div>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!--  INTRO  -->\n<div class=\"section\">\n  <div class=\"container\">\n    <div class=\"intro-grid\">\n      <div class=\"intro-text reveal\">\n        <p><strong>Human nature is not a mystery — it is a landscape.</strong> Every person you meet is driven by the same fundamental forces: the craving for attention, the pull of envy, the need for belonging, the fear of death. These forces operate beneath conscious awareness, shaping decisions, relationships, and destinies.</p>\n        <p>Robert Greene spent decades studying the patterns of human behavior across history — from ancient philosophers to modern psychology. The result is a comprehensive map of the human psyche: 18 laws that reveal why people do what they do, and how you can navigate the social world with clarity, strategic insight, and self-mastery.</p>\n        <p>This is not a book about manipulation. It is a book about <strong>understanding</strong>. And understanding is the foundation of all power, all connection, and all wisdom.</p>\n      </div>\n      <div class=\"intro-quote reveal reveal-delay-2\">\n        <blockquote>\"Human nature is not a problem to be solved. It is a reality to be understood, a force to be mastered. The greatest power you can possess is knowing yourself and understanding the motivations of others.\"</blockquote>\n        <cite>— Robert Greene</cite>\n      </div>\n    </div>\n  </div>\n</div>\n\n<!--  18 LAWS  -->\n<div class=\"laws-section\" id=\"laws\">\n  <div class=\"container\">\n    <div class=\"section-header reveal\">\n      <div class=\"overline\">The Foundations</div>\n      <h2>The 18 Laws of Human Nature</h2>\n      <div class=\"line\"></div>\n      <p>Each law addresses a fundamental aspect of human behavior — a pattern so deep and universal that it transcends culture, era, and circumstance.</p>\n    </div>\n    <div id=\"lawsContainer\"></div>\n  </div>\n</div>\n\n<!--  PATTERNS  -->\n<div class=\"section\" id=\"patterns\">\n  <div class=\"container\">\n    <div class=\"section-header reveal\">\n      <div class=\"overline\">Underlying Forces</div>\n      <h2>Key Patterns of Human Behavior</h2>\n      <div class=\"line\"></div>\n      <p>Beneath the surface of every interaction, universal patterns repeat across time and culture. Recognize them, and you begin to see the hidden architecture of human life.</p>\n    </div>\n    <div class=\"patterns-grid\" id=\"patternsGrid\"></div>\n  </div>\n</div>\n\n<!--  HISTORICAL FIGURES  -->\n<div class=\"section\" id=\"figures\">\n  <div class=\"container\">\n    <div class=\"section-header reveal\">\n      <div class=\"overline\">Wisdom Through Time</div>\n      <h2>Historical Case Studies</h2>\n      <div class=\"line\"></div>\n      <p>History's greatest figures — their rise, their fall, their triumphs and failures — all reveal the laws of human nature in action. Study them to understand yourself.</p>\n    </div>\n    <div class=\"historical-grid\" id=\"figuresGrid\"></div>\n  </div>\n</div>\n\n<!--  STRATEGIES  -->\n<div class=\"strategy-section\" id=\"strategies\">\n  <div class=\"container\">\n    <div class=\"section-header reveal\">\n      <div class=\"overline\">Practical Application</div>\n      <h2>Strategies for Mastery</h2>\n      <div class=\"line\"></div>\n      <p>Knowledge without action is merely philosophy. These strategies translate each law into concrete practices for navigating the social world with skill and awareness.</p>\n    </div>\n    <div class=\"strategy-grid\" id=\"strategyGrid\"></div>\n  </div>\n</div>\n\n<!--  QUOTES  -->\n<div class=\"quotes-section\" id=\"quotes\">\n  <div class=\"container\">\n    <div class=\"section-header reveal\">\n      <div class=\"overline\">On Human Nature</div>\n      <h2>Words of Power</h2>\n      <div class=\"line\"></div>\n    </div>\n    <div class=\"quotes-grid\" id=\"quotesGrid\"></div>\n  </div>\n</div>\n\n<!--  FOOTER  -->\n\n\n<!--  MODAL  -->\n<div id=\"figureModal\">\n  <div class=\"modal-inner\">\n    <button class=\"modal-close\" id=\"modalClose\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M18 6L6 18M6 6l12 12\"></path></svg></button>\n    <div class=\"modal-icon\" id=\"modalIcon\">S</div>\n    <h3 id=\"modalName\">Socrates</h3>\n    <div class=\"modal-era\" id=\"modalEra\">Ancient Greece</div>\n    <div class=\"modal-body\" id=\"modalBody\"></div>\n  </div>\n</div>\n\n<script>\n//  DATA \n\nconst laws = [\n  {\n    num: 1,\n    title: \"Master Your Emotional Self\",\n    subtitle: \"The Law of Irrationality\",\n    desc: \"The human mind is wired to react emotionally before it can think rationally. When emotions flare — fear, anger, excitement — they flood the brain, drowning out reason and foresight. The irrational person blames others and lashes out. The master of human nature learns to create space between impulse and action. By recognizing your emotional triggers, you can pause, reflect, and choose a response that serves your long-term interests. Emotional self-mastery is the foundation upon which all other social skills depend.\",\n    insight: \"You cannot reason someone out of something they did not reason themselves into. The first step to mastering others is mastering the emotional chaos within yourself.\",\n    strategies: [\n      \"Practice the 'Socratic pause': when you feel a strong emotion, stop and ask yourself what deeper need is being triggered\",\n      \"Keep a journal of emotional patterns — identify which people and situations consistently provoke you\",\n      \"Develop a 'cooling ritual': a specific physical action (deep breathing, counting, walking) that interrupts the emotional cascade\",\n      \"Study your own childhood: the most powerful emotional triggers often trace back to early experiences\",\n      \"Surround yourself with people who model emotional balance — emotions are contagious in both directions\"\n    ],\n    examples: [\n      { figure: \"Socrates\", detail: \"When his wife Xanthippe famously poured water on him, Socrates simply remarked, 'After the thunder, comes the rain.' He refused to let her anger become his own.\" },\n      { figure: \"Pericles\", detail: \"The Athenian leader was known for his unshakeable composure. When a rival cursed him in public, Pericles remained silent and walked away, later saying: 'They cannot make me lose my temper.'\" },\n      { figure: \"Marcus Aurelius\", detail: \"The Stoic emperor constantly reminded himself: 'You have power over your mind — not outside events. Realize this, and you will find strength.'\" }\n    ],\n    assess: \"When someone criticizes you harshly, what is your immediate internal reaction?\"\n  },\n  {\n    num: 2,\n    title: \"Transform Self-Love into Empathy\",\n    subtitle: \"The Law of Narcissism\",\n    desc: \"Every human being is born with a deep, primal need for attention and validation. This is the root of narcissism — not in the clinical sense, but as a universal human trait. The problem is not that we have this need, but that most people remain trapped in their own perspective, unable to truly see others. Deep health requires transforming this self-absorption into genuine empathy and social awareness. By understanding that everyone around you is also consumed with themselves, you gain a powerful key to social connection.\",\n    insight: \"The most seductive quality you can possess is the ability to make others feel seen, heard, and understood. People will open to you when they sense you are not trying to extract something from them.\",\n    strategies: [\n      \"When meeting someone, resist the urge to talk about yourself for the first 10 minutes — focus entirely on understanding their world\",\n      \"Practice deep listening: listen not to reply, but to understand. Let them finish, pause, then respond\",\n      \"Study people as if they are characters in a novel — what are their fears, desires, childhood wounds, hidden ambitions?\",\n      \"Make your empathy active: validate people's feelings before offering solutions or advice\",\n      \"Recognize the three types of narcissism: the dependent (needs constant approval), the authoritarian (needs control), and the healthy (self-aware and balanced)\"\n    ],\n    examples: [\n      { figure: \"Andy Warhol\", detail: \"Warhol understood the deep human hunger for fame and attention. He turned his own narcissism into a mirror for society, showing us our own desperate need to be seen.\" },\n      { figure: \"Marilyn Monroe\", detail: \"Beneath the glamour lay a profoundly insecure woman who never received the unconditional love she craved as a child. Her tragic life illustrates the insatiable nature of narcissistic hunger.\" },\n      { figure: \"Dale Carnegie\", detail: \"His core principle — become genuinely interested in other people — is a practical cure for pathological narcissism. He understood that the path to influence is through making others feel important.\" }\n    ],\n    assess: \"In conversations, do you find yourself waiting for your turn to speak, or truly absorbing what the other person is saying?\"\n  },\n  {\n    num: 3,\n    title: \"See Through People's Masks\",\n    subtitle: \"The Law of Role-Playing\",\n    desc: \"Life is a theater and we are all actors. From childhood, we learn to present a version of ourselves that will be accepted, admired, or feared. People are not necessarily deceptive — they are strategic. They emphasize certain traits and hide others based on what the situation demands. The key to understanding others is to look behind the performance: observe the inconsistencies, the slips, the moments when the mask cracks. Only then can you discern the genuine person beneath.\",\n    insight: \"The mask is not a lie — it is a clue. What people choose to show you reveals what they value, what they fear, and what they want you to believe.\",\n    strategies: [\n      \"Look for discrepancies between words and body language — the body rarely lies\",\n      \"Observe how people treat those beneath them in status, not just those above — that reveals true character\",\n      \"Notice what people make jokes about — humor often reveals repressed feelings and true attitudes\",\n      \"Study people in moments of crisis or stress — the mask slips when energy is focused elsewhere\",\n      \"Ask yourself: what is this person trying to achieve by presenting themselves this way?\"\n    ],\n    examples: [\n      { figure: \"Machiavelli\", detail: \"The master of political theater, Machiavelli understood that power requires strategic self-presentation. He advised the Prince to appear compassionate, faithful, and religious — whether or not he actually was.\" },\n      { figure: \"Shakespeare\", detail: \"No one understood human role-playing better. His plays are a catalogue of masks: the ambitious Macbeth hiding his guilt, the scheming Iago wearing honesty as a cloak, the wise fool speaking truth through jest.\" },\n      { figure: \"Abraham Lincoln\", detail: \"Lincoln was a master of the 'folksy' mask — presenting himself as a simple country lawyer while wielding extraordinary political skill and a razor-sharp strategic mind.\" }\n    ],\n    assess: \"Can you recall a recent situation where someone's public persona clearly differed from their private behavior? What did you observe?\"\n  },\n  {\n    num: 4,\n    title: \"Determine the Strength of People's Character\",\n    subtitle: \"The Law of Compulsive Behavior\",\n    desc: \"People are not random. Everyone operates according to deeply ingrained patterns — compulsive behaviors shaped by childhood, temperament, and life experience. These patterns are remarkably stable over time. The key to prediction is observation: watch how people react to frustration, boredom, success, and stress. Their repeated responses reveal their character more accurately than their words ever could. The art of reading people lies in recognizing these patterns and understanding that people rarely change at their core.\",\n    insight: \"Character is not what people say they believe — it is what they do repeatedly. Watch actions over time, not words in the moment.\",\n    strategies: [\n      \"Create small tests: expose people to mild frustration or ambiguity and observe their response pattern\",\n      \"Look for the 'parental voice' — people often recreate their childhood dynamics in adult relationships\",\n      \"Identify the dominant pattern: the complainer, the blamer, the withdrawer, the controller, the people-pleaser\",\n      \"Notice how people handle success — does it make them generous or arrogant? This reveals deep character\",\n      \"The past is the best predictor: study someone's history, and you will see the same patterns repeating\"\n    ],\n    examples: [\n      { figure: \"Winston Churchill\", detail: \"His depressive tendencies (the 'black dog') were a lifelong pattern. But he channeled this compulsive melancholy into resolute action during crisis — his dark nature became his strength.\" },\n      { figure: \"Charles Darwin\", detail: \"Darwin's obsessive need for order and meticulous observation — patterns established in childhood — enabled his revolutionary theory. His compulsiveness was the engine of his genius.\" },\n      { figure: \"Napoleon Bonaparte\", detail: \"Napoleon's relentless ambition and need for conquest were compulsive patterns that drove him to rule Europe — and ultimately to his catastrophic invasion of Russia and downfall.\" }\n    ],\n    assess: \"Think of someone you know well. What is their most consistent behavioral pattern when under pressure?\"\n  },\n  {\n    num: 5,\n    title: \"Become an Elusive Object of Desire\",\n    subtitle: \"The Law of Covetousness\",\n    desc: \"Human beings are drawn to what they cannot have. The moment something becomes readily available, its value plummets in our eyes. This is the law of covetousness: we want what is scarce, what others want, what seems just out of reach. Those who understand this dynamic never reveal their full hand. They maintain an air of mystery, of withheld power. They make themselves the object of pursuit rather than the pursuer. In love, business, and social life, the person who is hardest to get is the most desired.\",\n    insight: \"Availability breeds contempt; scarcity creates value. The moment you show you want something too much, you give away your power.\",\n    strategies: [\n      \"Cultivate an air of mystery: do not reveal everything about yourself at once — let people discover you slowly\",\n      \"Withhold your full presence: occasionally be unavailable, create anticipation, leave them wanting more\",\n      \"Create a sense of competition: when others perceive that you are valued by multiple people, your status rises\",\n      \"Develop rare skills or knowledge that few possess — true scarcity is rooted in genuine uniqueness\",\n      \"Never appear desperate or overly eager — the person who shows patience has the greatest leverage\"\n    ],\n    examples: [\n      { figure: \"Cleopatra\", detail: \"She famously arrived to meet Mark Antony on a magnificent barge, dressed as Aphrodite, creating an unforgettable spectacle that made her seem more goddess than woman. She understood desire through theatrical scarcity.\" },\n      { figure: \"Coco Chanel\", detail: \"Chanel built an empire on the principle of exclusivity. Her perfume was the first to be marketed as the scent of a 'certain woman' — mysterious, rare, and therefore infinitely desirable.\" },\n      { figure: \"Queen Elizabeth I\", detail: \"The Virgin Queen used her marital status as a diplomatic weapon for decades. By remaining perpetually unattainable, she kept European powers competing for her favor.\" }\n    ],\n    assess: \"Do you tend to reveal everything about yourself early in relationships, or do you maintain a sense of mystery?\"\n  },\n  {\n    num: 6,\n    title: \"Elevate Your Perspective\",\n    subtitle: \"The Law of Shortsightedness\",\n    desc: \"We are all prisoners of the present moment. Immediate sensations, urgent demands, and emotional reactions consume our attention, blinding us to the larger picture. The shortsighted person reacts to events as they happen, always putting out fires, never building a foundation. The person who masters human nature cultivates the ability to step back and see the longer arc — years, decades, generations. They understand that most short-term gains come at the cost of long-term power. Patience, far from being passive, is the most active form of strategy.\",\n    insight: \"The greatest advantage you can have is the ability to think in years while others think in days. The long-term perspective transforms obstacles into opportunities.\",\n    strategies: [\n      \"Practice 'future retrospection': imagine yourself ten years from now looking back — what would you wish you had done today?\",\n      \"Create space for deliberate reflection: schedule regular time away from immediate demands to think about the bigger picture\",\n      \"Identify the emotional triggers that make you reactive — when you feel urgency, pause. Urgency is often manufactured\",\n      \"Study history — the patterns of the past reveal the contours of the future\",\n      \"Develop the 'Stoic calendar': regularly ask yourself if this will matter in a year, in five years, in a decade\"\n    ],\n    examples: [\n      { figure: \"Pericles\", detail: \"The Athenian statesman rejected short-term populist measures in favor of a long-term strategy that made Athens the most powerful city-state in Greece. His patience built an empire.\" },\n      { figure: \"Warren Buffett\", detail: \"Buffett's entire philosophy is based on long-term thinking. While others chase quarterly gains, he holds investments for decades. 'The stock market is a device for transferring money from the impatient to the patient.'\" },\n      { figure: \"Catherine the Great\", detail: \"She ruled Russia for 34 years through careful, long-term planning. She never made a decision based on immediate pressure — always considering how it would affect her reign years later.\" }\n    ],\n    assess: \"When faced with a difficult decision, do you focus on immediate relief or long-term position?\"\n  },\n  {\n    num: 7,\n    title: \"Soften Resistance by Confirming Self-Opinion\",\n    subtitle: \"The Law of Defensiveness\",\n    desc: \"People are deeply invested in their self-image. Attack it directly, and they will resist you with all their strength. But confirm their self-opinion — show them you see them as they wish to be seen — and their defenses melt. This is not flattery in the obvious sense. It is the art of finding what is genuinely admirable in people and making that the foundation of your interaction. When you validate someone's identity, you create a bond of trust. They will be open to your influence because you have made them feel understood and respected.\",\n    insight: \"The surest way to change someone is not to argue with their self-image, but to use it as a bridge. People will walk anywhere once they feel you see them clearly.\",\n    strategies: [\n      \"Identify the core self-image: does the person see themselves as a maverick, a nurturer, a warrior, a sage? Speak to that identity\",\n      \"Begin any request by validating their expertise or perspective — 'I value your judgment on this'\",\n      \"Frame your suggestions as consistent with their existing values and self-perception\",\n      \"Never attack someone's self-image directly — even constructive criticism must be wrapped in affirmation\",\n      \"Learn the art of the 'indirect' compliment: praise something about them that is not obvious, showing you see beneath the surface\"\n    ],\n    examples: [\n      { figure: \"Benjamin Franklin\", detail: \"Franklin famously won over a political rival by asking to borrow a rare book from his library. The request validated the man's self-image as a scholar and intellectual, transforming hostility into friendship.\" },\n      { figure: \"Dale Carnegie\", detail: \"His principle 'become genuinely interested in other people' is rooted in this law. Carnegie understood that the deepest human need is the desire to feel important and understood.\" },\n      { figure: \"Franklin D. Roosevelt\", detail: \"Roosevelt's fireside chats masterfully confirmed the self-image of the American people as resilient, capable, and united — giving them the confidence to face the Great Depression.\" }\n    ],\n    assess: \"When you want someone to see things your way, do you first try to show them that you understand their perspective?\"\n  },\n  {\n    num: 8,\n    title: \"Change Your Circumstances by Changing Your Attitude\",\n    subtitle: \"The Law of Self-Sabotage\",\n    desc: \"The greatest prison is the one we build for ourselves. Our attitudes — the stories we tell ourselves about who we are, what we deserve, and what is possible — shape our reality more than external circumstances ever could. The self-sabotaging person is trapped by negative patterns: victimhood, resentment, fear of success. But these patterns are not permanent. By consciously choosing a different attitude — one of gratitude, agency, and possibility — you can transform your entire experience of life. The mind is the starting point of all change.\",\n    insight: \"You cannot always control what happens to you, but you can always control the meaning you give it. That meaning becomes your reality.\",\n    strategies: [\n      \"Identify your 'limiting story': what narrative do you tell yourself about why you cannot succeed? Write it down and examine its assumptions\",\n      \"Practice cognitive reframing: for every negative interpretation, find an alternative that empowers rather than defeats\",\n      \"Take radical responsibility: even when things are not your fault, ask 'what could I have done differently?' — this shifts you from victim to agent\",\n      \"Keep a 'gratitude practice': each day, write three things you are grateful for. This rewires the brain toward abundance\",\n      \"Surround yourself with people whose attitudes lift you — attitude is contagious\"\n    ],\n    examples: [\n      { figure: \"Viktor Frankl\", detail: \"In a Nazi concentration camp, Frankl discovered that even when everything is taken from you, you retain the freedom to choose your attitude. This realization became the foundation of logotherapy.\" },\n      { figure: \"Epictetus\", detail: \"The Stoic philosopher was born a slave, but refused to let his external circumstances define his internal state. 'It's not what happens to you, but how you react to it that matters.'\" },\n      { figure: \"Helen Keller\", detail: \"Blind and deaf from infancy, Keller refused the narrative of limitation. With an attitude of relentless determination, she became a writer, activist, and symbol of human potential.\" }\n    ],\n    assess: \"When something goes wrong, do you focus on what was done to you, or on what you can do about it?\"\n  },\n  {\n    num: 9,\n    title: \"Confront Your Dark Side\",\n    subtitle: \"The Law of Repression\",\n    desc: \"The shadow is real. Every person has a dark side — impulses, desires, and traits that we have learned to suppress because they are socially unacceptable or threaten our self-image. But what we repress does not disappear. It grows in the darkness and emerges in disguised forms: in our projections onto others, in our passive-aggressive behavior, in the traits we most despise in other people. The path to wholeness is not to eliminate the shadow, but to acknowledge it, integrate it, and channel its energy constructively.\",\n    insight: \"The person who claims to have no dark side is the most dangerous of all. What we refuse to see in ourselves, we will act out unconsciously — with devastating consequences.\",\n    strategies: [\n      \"Identify your 'projections': the traits that irritate you most in others are often the ones you have not accepted in yourself\",\n      \"Keep a 'shadow journal': write down your judgmental thoughts about others, then ask yourself how those qualities might exist within you\",\n      \"Create safe channels for your darker impulses — aggression through competition, ambition through creative work\",\n      \"Study figures who integrated their shadow: the artist who channeled chaos into creation, the leader who owned their ruthlessness\",\n      \"Practice radical self-honesty: admit your envy, your greed, your selfishness — owning them defuses their power over you\"\n    ],\n    examples: [\n      { figure: \"Carl Jung\", detail: \"Jung developed the concept of the shadow and warned that it is far more dangerous to repress than to integrate. He believed that the goal of life is not perfection but wholeness.\" },\n      { figure: \"Sigmund Freud\", detail: \"Freud's entire theory rests on the premise that what we repress controls us from the unconscious. He showed that our 'slips,' dreams, and neuroses are all messages from the shadow.\" },\n      { figure: \"Robert Louis Stevenson\", detail: \"His story of Dr. Jekyll and Mr. Hyde is the classic allegory of the shadow — the respectable man who represses his dark side, only to have it emerge with monstrous force.\" }\n    ],\n    assess: \"Think of a trait you strongly dislike in others. Can you honestly identify where that same trait exists within yourself?\"\n  },\n  {\n    num: 10,\n    title: \"Beware the Splintered Splinter\",\n    subtitle: \"The Law of Envy\",\n    desc: \"Envy is the most dangerous and universal of emotions — and the most carefully disguised. People rarely admit to envy, even to themselves. Instead, it masquerades as criticism, moral outrage, gossip, or subtle put-downs. The envious person cannot bear to see others succeed because their own life feels empty. The targets of envy are almost always those closest to us — friends, colleagues, peers. To protect yourself, learn to recognize the signs of envy in others, and more importantly, to detect its subtle presence within yourself.\",\n    insight: \"The greatest danger does not come from your enemies but from those who pretend to celebrate your success while secretly resenting it. Learn to distinguish genuine support from disguised envy.\",\n    strategies: [\n      \"Downplay your successes around those who might envy you — let your achievements be discovered rather than announced\",\n      \"Identify the 'envy triggers': the people who become slightly colder, more critical, or more distant when you succeed\",\n      \"Practice 'success inoculation': occasionally share your struggles and failures — it makes you less threatening\",\n      \"Redirect envy through admiration: when you feel envy rising in yourself, consciously transform it into curiosity and learning\",\n      \"Understand the 'tall poppy' syndrome: society often punishes those who rise too high — navigate this by lifting others as you rise\"\n    ],\n    examples: [\n      { figure: \"Joseph Stalin\", detail: \"Stalin's paranoid envy was legendary. He could not bear any rival who might outshine him, leading him to eliminate virtually every original Bolshevik leader. His envy reshaped the 20th century.\" },\n      { figure: \"John F. Kennedy\", detail: \"Kennedy's grace in the face of envy — he was constantly envied by political rivals for his wealth, charm, and success — offers lessons in how to rise above pettiness.\" },\n      { figure: \"Medusa (Mythology)\", detail: \"The myth of Medusa is an ancient allegory of envy: the goddess Athena, envious of Medusa's beautiful hair, transformed it into snakes. Envy petrifies both the envier and the envied.\" }\n    ],\n    assess: \"When a close friend or colleague achieves something significant, what is your honest internal reaction?\"\n  },\n  {\n    num: 11,\n    title: \"Know Your Limits\",\n    subtitle: \"The Law of Grandiosity\",\n    desc: \"Confidence is essential. Grandiosity is fatal. The grandiose person loses touch with reality — they believe they are special, invulnerable, above the rules that constrain ordinary people. This delusion is seductive (especially in moments of success), but it inevitably leads to downfall. The truly great are suffused with an awareness of their own limitations. They know their weaknesses, their blind spots, their capacity for error. This grounded self-awareness is the foundation of resilience and true achievement.\",\n    insight: \"Hubris is not the opposite of humility — it is the absence of self-awareness. The moment you believe you are above the laws of human nature is the moment those laws will destroy you.\",\n    strategies: [\n      \"Cultivate a 'board of advisors': people who will tell you the truth about your blind spots, not what you want to hear\",\n      \"Regularly expose yourself to domains where you are incompetent — it keeps your ego in check\",\n      \"Study the falls of the great: Alexander, Napoleon, Hitler — their grandiosity followed the same pattern\",\n      \"Practice 'negative visualization': imagine your plans failing completely, then work backward to identify where you are most vulnerable\",\n      \"Develop the habit of self-correction: when you make a mistake, own it immediately and learn from it — the grandiose cannot admit error\"\n    ],\n    examples: [\n      { figure: \"Napoleon Bonaparte\", detail: \"At his peak, Napoleon believed himself invincible. His invasion of Russia — 600,000 men lost in a single campaign — was the result of grandiosity unchecked. He died in exile, alone and defeated.\" },\n      { figure: \"Alexander the Great\", detail: \"After conquering the known world, Alexander believed himself divine. He demanded worship, alienated his generals, and died at 32 — not from battle, but from his own excesses.\" },\n      { figure: \"Howard Hughes\", detail: \"The billionaire's grandiosity evolved into pathological delusion. He believed he could control everything — germs, food, even the air he breathed. His empire crumbled as his mind disconnected from reality.\" }\n    ],\n    assess: \"Who in your life can honestly tell you when you are wrong? How do you react when they do?\"\n  },\n  {\n    num: 12,\n    title: \"Reconnect to the Masculine or Feminine Within\",\n    subtitle: \"The Law of Gender Rigidity\",\n    desc: \"The modern world has created rigid boxes for masculine and feminine behavior. Men are pressured to suppress their emotional, nurturing, and intuitive sides. Women are pressured to hide their assertive, ambitious, and competitive drives. But human nature is not binary — it is a spectrum. The most complete, powerful, and attractive individuals are those who have integrated both sides. The man who can be both strong and vulnerable, the woman who can be both nurturing and fierce — these are the people who break free from the prison of gender expectations.\",\n    insight: \"The parts of yourself you suppress do not disappear — they become sources of tension, envy, and unconscious acting out. Integration brings power; rigidity brings suffering.\",\n    strategies: [\n      \"Identify the qualities you have rejected as 'not me' because they did not fit your gender role\",\n      \"Study and admire figures of your gender who embody the qualities you have suppressed\",\n      \"Practice expressing the 'forbidden' quality in safe environments: a man crying during a moving film; a woman asserting herself directly\",\n      \"In relationships, seek partners who complement your shadow — the man who needs emotional connection finds a woman who embodies it\",\n      \"Recognize that the most magnetic people are those who transcend gender stereotypes — they are mysterious because they contain multitudes\"\n    ],\n    examples: [\n      { figure: \"Carl Jung\", detail: \"Jung's concepts of the Anima and Animus describe the inner feminine in men and inner masculine in women. He believed psychological health requires integrating these opposites.\" },\n      { figure: \"Virginia Woolf\", detail: \"Woolf argued that the greatest minds are 'androgynous' — they transcend gender categories entirely. She herself explored the full range of human experience in her writing.\" },\n      { figure: \"Miyamoto Musashi\", detail: \"The legendary samurai was not only the greatest swordsman in Japanese history but also a master painter, calligrapher, and sculptor. He integrated the warrior and the artist.\" }\n    ],\n    assess: \"What qualities have you suppressed in yourself because they felt 'not masculine enough' or 'not feminine enough'?\"\n  },\n  {\n    num: 13,\n    title: \"Advance with a Sense of Purpose\",\n    subtitle: \"The Law of Aimlessness\",\n    desc: \"The human mind craves purpose. Without a compelling sense of direction, we drift. We chase distractions, adopt other people's goals, and feel a persistent sense of emptiness. The aimless person is easily manipulated — they follow trends, seek external validation, and never develop real depth. Finding your true purpose requires introspection, experimentation, and the courage to reject paths that do not resonate. Once found, purpose organizes your life. It gives you energy, resilience, and a compass that no external circumstance can disrupt.\",\n    insight: \"Purpose is not something you find — it is something you build through the intersection of your natural talents, deep interests, and the needs of the world around you.\",\n    strategies: [\n      \"Conduct a 'life audit': identify the moments in your life when you felt most alive, engaged, and fulfilled — what were you doing?\",\n      \"Eliminate the 'purpose blockers': the habits, relationships, and commitments that drain your energy without contributing to your growth\",\n      \"Develop a 'personal mission statement': one sentence that captures what you want to contribute to the world\",\n      \"Practice 'deep work': sustained concentration on a single meaningful task is the path to both mastery and purpose\",\n      \"Accept that purpose evolves — what matters at 25 will differ at 45. The key is to keep moving forward with intention\"\n    ],\n    examples: [\n      { figure: \"Leonardo da Vinci\", detail: \"Da Vinci's purpose was not to paint or invent — it was to understand. Every notebook, every sketch, every experiment was driven by an insatiable curiosity. His purpose gave his life coherence.\" },\n      { figure: \"Steve Jobs\", detail: \"Jobs found his purpose at the intersection of technology and the humanities. 'The only way to do great work is to love what you do.' His sense of purpose was so strong it bordered on religious.\" },\n      { figure: \"Florence Nightingale\", detail: \"Despite fierce opposition from her wealthy family, Nightingale pursued her calling to nursing. Her sense of purpose was so powerful that she transformed the entire profession of nursing.\" }\n    ],\n    assess: \"If you had unlimited resources and could not fail, what would you spend your life doing? What does that tell you about your purpose?\"\n  },\n  {\n    num: 14,\n    title: \"Resist the Group's Pull\",\n    subtitle: \"The Law of Conformity\",\n    desc: \"Humans are herd animals. We have a primal need to belong, to be accepted by the group. This need can override our judgment, our values, even our perceptions of reality. History's greatest atrocities were committed not by monsters but by ordinary people who surrendered their独立思考 to the group. The pressure to conform is subtle and constant — it shapes our opinions, our career choices, our relationships. Resisting this pull requires constant vigilance, self-awareness, and the courage to stand apart. The reward is authentic thinking and genuine individuality.\",\n    insight: \"The group is not evil — it is neutral. But its gravitational pull is so strong that only those who recognize it can resist it. The price of belonging is often your own mind.\",\n    strategies: [\n      \"Practice 'contrarian thinking': regularly ask yourself what the opposite of the consensus view might reveal\",\n      \"Cultivate relationships with people who disagree with you — intellectual diversity strengthens your own thinking\",\n      \"When you find yourself agreeing with a group, pause and ask: do I really believe this, or am I conforming?\",\n      \"Study periods of mass hysteria — witch hunts, financial bubbles, political manias — to inoculate yourself\",\n      \"Develop the 'private space' habit: spend time alone in deep thought before engaging with group opinions\"\n    ],\n    examples: [\n      { figure: \"Galileo Galilei\", detail: \"When the group — the Catholic Church and all of scientific academia — insisted the Earth was the center of the universe, Galileo stood alone with the truth. 'And yet it moves.'\" },\n      { figure: \"Rosa Parks\", detail: \"One woman's refusal to conform to segregation laws sparked a civil rights movement. Her quiet act of非暴力抵抗demonstrated the power of individual conscience against group tyranny.\" },\n      { figure: \"Socrates\", detail: \"Socrates was executed by the Athenian democracy for 'corrupting the youth' — i.e., teaching them to think for themselves rather than accepting the group's wisdom. His death is the eternal warning against conformity.\" }\n    ],\n    assess: \"When your opinion differs from those around you, do you speak up or stay silent? What are you afraid of losing?\"\n  },\n  {\n    num: 15,\n    title: \"Make Them Want to Follow You\",\n    subtitle: \"The Law of Fickleness\",\n    desc: \"People are fickle. Their loyalties shift. Their attention wanders. Their enthusiasm fades. To lead effectively, you cannot rely on people's natural consistency — you must actively cultivate their engagement. The master of human nature understands that leadership is not about commanding — it is about creating an emotional connection. People follow those who make them feel significant, who give them a sense of purpose, who embody the qualities they admire. The leader who understands the law of fickleness works constantly to renew the bond with their followers.\",\n    insight: \"Leadership is not a position — it is a relationship. And like all relationships, it must be constantly nurtured, or it will atrophy.\",\n    strategies: [\n      \"Create a compelling vision: people follow those who can paint a picture of a future they want to be part of\",\n      \"Lead from the front: demonstrate the qualities you ask of others — your example is your most powerful tool\",\n      \"Make people feel seen: remember names, acknowledge contributions, show genuine interest in their lives\",\n      \"Create 'wins' that people can share in: people stay loyal to leaders who make them feel successful\",\n      \"Maintain emotional consistency: a leader who is stable and reliable inspires confidence in uncertain times\"\n    ],\n    examples: [\n      { figure: \"Queen Elizabeth I\", detail: \"She understood that her power depended on the love of her people. She cultivated this love through carefully staged public appearances, symbolic gestures, and an enduring connection with her subjects.\" },\n      { figure: \"Abraham Lincoln\", detail: \"Lincoln led a divided nation through its darkest hour not through force of command, but through emotional intelligence, storytelling, and an unshakeable moral vision that gave people hope.\" },\n      { figure: \"Winston Churchill\", detail: \"In 1940, when Britain faced annihilation, Churchill's words and defiant spirit gave a nation the courage to fight alone. His leadership was a masterpiece of emotional connection.\" }\n    ],\n    assess: \"When you want people to follow your lead, do you rely on authority and logic, or do you first build an emotional connection?\"\n  },\n  {\n    num: 16,\n    title: \"Understand the Dark Side of Human Nature\",\n    subtitle: \"The Law of Aggression\",\n    desc: \"Aggression is not an aberration — it is a fundamental part of human nature. Every person has aggressive impulses, but most have learned to suppress them, to channel them into socially acceptable forms, or to disguise them behind civilized behavior. The danger lies in denying this reality. Those who refuse to acknowledge their own aggressive drives become passive-aggressive, manipulative, or unconsciously provocative. Those who understand the dark side can recognize it in others, defend against it, and channel it constructively in themselves.\",\n    insight: \"The most dangerous people are not those who are openly aggressive but those who pretend to have no aggression at all. Their hostility will find an outlet — and you may be the target.\",\n    strategies: [\n      \"Recognize the forms of passive aggression: chronic lateness, 'forgetting,' subtle sarcasm, the silent treatment\",\n      \"Develop your own capacity for healthy assertiveness — suppressed aggression always finds worse outlets\",\n      \"Learn to read the early warning signs of aggression in others: tensing, raised voice, invasive eye contact\",\n      \"Stand your ground early — most aggressors test boundaries first. A firm early response prevents escalation\",\n      \"Channel aggressive energy into competition, creative work, and physical activity — the body needs to discharge aggression\"\n    ],\n    examples: [\n      { figure: \"Genghis Khan\", detail: \"The most successful conqueror in history understood aggression as a strategic tool. His brutality was calculated, not random — it served the purpose of psychological warfare and social control.\" },\n      { figure: \"Sun Tzu\", detail: \"The Art of War teaches that the supreme art of war is to subdue the enemy without fighting. Sun Tzu understood aggression as something to be channeled through strategy, not unleashed raw.\" },\n      { figure: \"Adolf Hitler\", detail: \"Hitler represents the catastrophic end of denied and projected aggression. His inability to confront his own weaknesses led him to project them onto entire groups of people — with devastating consequences.\" }\n    ],\n    assess: \"How do you typically handle your anger? Do you express it directly, suppress it, or let it leak out in passive-aggressive ways?\"\n  },\n  {\n    num: 17,\n    title: \"See the Larger Cycle\",\n    subtitle: \"The Law of Generational Myopia\",\n    desc: \"Every generation believes it is different — that its values, its challenges, its worldviews are unprecedented. This belief is an illusion. Human history moves in cycles: generations rebel against their parents, then eventually adopt the values they once rejected. The young are idealistic and restless; the middle-aged are pragmatic and consolidating; the old are conservative and nostalgic. Understanding these generational rhythms gives you a profound strategic advantage. You can see where the cycle is heading, position yourself accordingly, and avoid the myopia that traps most people.\",\n    insight: \"What seems like a permanent shift is often just a pendulum swing. The generation that forgets history is doomed to repeat its follies.\",\n    strategies: [\n      \"Study the generational archetypes: the Prophet (idealist), the Nomad (adaptor), the Hero (civic-minded), the Artist (affluent) — they cycle in predictable patterns\",\n      \"Identify your own generational biases: what beliefs do you hold simply because of when you were born?\",\n      \"Recognize that the rebellion of one generation becomes the orthodoxy of the next\",\n      \"Position yourself between generations — the people who bridge generational divides have the greatest influence\",\n      \"Read history not as dates and events but as cycles — patterns that reveal where we are in the larger arc\"\n    ],\n    examples: [\n      { figure: \"Arthur Schopenhauer\", detail: \"The philosopher's work on the will and generational cycles influenced Nietzsche, Freud, and Einstein. He saw that intellectual movements follow predictable arcs of emergence, dominance, and decline.\" },\n      { figure: \"Auguste Comte\", detail: \"Comte developed the law of three stages: theological, metaphysical, and positive (scientific). He argued that both civilizations and individuals pass through these stages in a fixed order.\" },\n      { figure: \"Giambattista Vico\", detail: \"Vico's 'New Science' identified the cyclical nature of history: ages of gods, heroes, and humans, followed by a ricorso (return). His work anticipated modern theories of generational cycles.\" }\n    ],\n    assess: \"What deeply held beliefs do you hold that you might have absorbed simply because of the generation you were born into?\"\n  },\n  {\n    num: 18,\n    title: \"Meditate on Death\",\n    subtitle: \"The Law of Death Denial\",\n    desc: \"The fear of death is the deepest fear of all — the root from which so many other fears grow. Most people spend their lives in a state of denial, distracting themselves with busyness, pleasure, and accumulation. But those who confront their mortality directly experience a profound transformation. The awareness of death strips away the trivial and reveals what truly matters. It gives urgency to purpose, depth to relationships, and courage to act. The person who has made peace with death is the freest person of all — they have nothing to lose.\",\n    insight: \"Death is not the enemy of life — it is the sharpener of life. The knowledge that your time is limited is the most powerful motivator you will ever know.\",\n    strategies: [\n      \"Practice 'memento mori': keep a physical reminder of mortality — a skull, a candle, a quote — to stay aware of life's finitude\",\n      \"Write your own eulogy: what would you want people to say about you? Now live in a way that makes it true\",\n      \"Ask yourself: if I had one year to live, would I be spending my time this way?\",\n      \"Study the lives of those who faced death with dignity: Seneca, Socrates, Marcus Aurelius — their courage is a model\",\n      \"Use death awareness as a filter: before making any major decision, ask: will this matter on my deathbed?\"\n    ],\n    examples: [\n      { figure: \"Marcus Aurelius\", detail: \"The Stoic emperor constantly meditated on death. 'You could leave life right now. Let that determine what you do and say and think.' His journal, Meditations, is a manual for living with mortality in mind.\" },\n      { figure: \"Michel de Montaigne\", detail: \"Montaigne wrote extensively on death, arguing that 'to philosophize is to learn how to die.' He believed that accepting our mortality is the beginning of wisdom.\" },\n      { figure: \"Samurai Tradition\", detail: \"The samurai lived by the code of constant death awareness. 'The way of the warrior is death' — meaning that by accepting death completely, the warrior becomes fearless and fully alive.\" }\n    ],\n    assess: \"How often do you genuinely contemplate your own mortality? Does the thought paralyze you or liberate you?\"\n  }\n];\n\nconst patterns = [\n  { icon: '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polyline points=\"23 4 23 10 17 10\"/><path d=\"M20.49 15a9 9 0 1 1-2.12-9.36L23 10\"/></svg>', title: \"Emotional Reactivity\", desc: \"All humans are wired to react emotionally before thinking rationally. This pattern governs most conflicts, bad decisions, and regretful actions.\", law: \"Law 1\" },\n  { icon: '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"/><path d=\"M2 17l10 5 10-5\"/><path d=\"M2 12l10 5 10-5\"/></svg>', title: \"The Masked Self\", desc: \"Everyone presents a curated version of themselves. The gap between public persona and private reality is a universal human pattern.\", law: \"Law 3\" },\n  { icon: \"🔁\", title: \"Compulsive Repetition\", desc: \"People unconsciously repeat the same behavioral patterns throughout their lives, especially those formed in childhood.\", law: \"Law 4\" },\n  { icon: '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"/><circle cx=\"12\" cy=\"12\" r=\"3\"/></svg>️', title: \"The Need for Attention\", desc: \"The hunger for validation is the most powerful and underacknowledged human drive. It shapes careers, relationships, and entire lives.\", law: \"Law 2\" },\n  { icon: '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"13 2 3 14 12 14 11 22 21 10 12 10 13 2\"/></svg>', title: \"Scarcity Obsession\", desc: \"What is rare is desired; what is abundant is devalued. This pattern operates in markets, relationships, and social status.\", law: \"Law 5\" },\n  { icon: \"🧊\", title: \"Defensive Self-Image\", desc: \"People will defend their self-image with more energy than they will defend their lives. Attack the identity, and you make an enemy for life.\", law: \"Law 7\" },\n  { icon: '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2\"/><circle cx=\"12\" cy=\"7\" r=\"4\"/></svg>', title: \"The Shadow Projection\", desc: \"What we cannot accept in ourselves, we project onto others. The traits that irritate us most in others are often our own disowned qualities.\", law: \"Law 9\" },\n  { icon: '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z\"/></svg>', title: \"The Envy Reflex\", desc: \"Envy is the most denied emotion. It disguises itself as criticism, moral superiority, gossip, or coldness. It targets those closest to us.\", law: \"Law 10\" },\n  { icon: '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 19V5M5 12l7-7 7 7\"/></svg>️', title: \"The Icarus Complex\", desc: \"Success breeds grandiosity; grandiosity breeds downfall. The higher one rises, the greater the temptation to believe one is above the laws of nature.\", law: \"Law 11\" },\n  { icon: '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 22c-3 0-6-3-6-6 0-3 2-6 6-6s6 3 6 6c0 3-3 6-6 6z\"/><path d=\"M12 4V2\"/><path d=\"M5 5l1 1\"/><path d=\"M19 5l-1 1\"/></svg>', title: \"The Herd Instinct\", desc: \"The need to belong overrides judgment, values, and perception of reality. Groups create their own reality, which members accept uncritically.\", law: \"Law 14\" },\n  { icon: '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 22 16 8\"/><path d=\"M21 2l-5 5\"/><path d=\"M14 7l3-3\"/></svg>', title: \"Generational Blindness\", desc: \"Each generation believes it is unique and that its values are permanently superior. This myopia repeats endlessly throughout history.\", law: \"Law 17\" },\n  { icon: '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 6v6l4 2\"/></svg>', title: \"Mortality Denial\", desc: \"Most human activity — ambition, accumulation, distraction — is driven by an unacknowledged attempt to escape the reality of death.\", law: \"Law 18\" }\n];\n\nconst historicalFigures = [\n  { initial: \"S\", name: \"Socrates\", era: \"Ancient Greece (470–399 BC)\", desc: \"The father of Western philosophy, Socrates used relentless questioning to expose the gap between what people believed and what they actually knew. His method of inquiry — the Socratic dialogue — forced others to examine their assumptions and confront their ignorance. He was executed for 'corrupting the youth' by teaching them to think for themselves. His calm acceptance of death remains the ultimate model of emotional self-mastery.\", laws: [1, 14] },\n  { initial: \"M\", name: \"Marcus Aurelius\", era: \"Roman Empire (121–180 AD)\", desc: \"A Stoic philosopher-emperor who ruled during Rome's most turbulent period. His private journal, 'Meditations,' written on campaign, is the definitive text on emotional self-control, mortality acceptance, and the long view. He constantly reminded himself that 'you have power over your mind — not outside events.' His reign was marked by justice, humility, and resilience in the face of plague, war, and betrayal.\", laws: [1, 6, 18] },\n  { initial: \"N\", name: \"Napoleon Bonaparte\", era: \"France (1769–1821)\", desc: \"The brilliant military strategist who conquered most of Europe before his grandiosity led to his catastrophic downfall. His invasion of Russia — 600,000 men lost — was the result of believing his own myth. Exiled to Elba, he escaped and briefly returned to power before final defeat at Waterloo. His life is the classic arc of the grandiose: rise through talent, fall through hubris.\", laws: [4, 11] },\n  { initial: \"C\", name: \"Cleopatra VII\", era: \"Ptolemaic Egypt (69–30 BC)\", desc: \"One of history's most skilled practitioners of strategic seduction and scarcity. She understood that mystery and theatrical presentation create desire. Her encounters with Julius Caesar and Mark Antony were carefully staged performances that combined political calculation with personal magnetism. She chose death by her own hand rather than being paraded as a trophy in a Roman triumph.\", laws: [5] },\n  { initial: \"A\", name: \"Alexander the Great\", era: \"Macedonia (356–323 BC)\", desc: \"Conquered the known world by age 25, but his grandiosity led him to believe he was divine. He demanded worship, killed his closest friends in paranoid rages, and died at 32 from alcoholism and fever. His life demonstrates the law of grandiosity: without limits, talent becomes tragedy.\", laws: [11] },\n  { initial: \"C\", name: \"Carl Jung\", era: \"Switzerland (1875–1961)\", desc: \"The psychiatrist who developed the concepts of the shadow, the persona, projection, and the collective unconscious. He argued that wholeness — not perfection — is the goal of life. His work on the shadow, the anima/animus, and human typology provides the psychological framework for understanding the hidden forces that shape human behavior.\", laws: [2, 9, 12] },\n  { initial: \"V\", name: \"Viktor Frankl\", era: \"Austria (1905–1997)\", desc: \"A psychiatrist who survived Nazi concentration camps and developed logotherapy — the belief that the primary human drive is not pleasure but meaning. In the camps, he discovered that even when everything is stripped away, humans retain the freedom to choose their attitude. His book 'Man's Search for Meaning' has inspired millions to find purpose in suffering.\", laws: [8] },\n  { initial: \"E\", name: \"Epictetus\", era: \"Ancient Greece (50–135 AD)\", desc: \"Born a slave, Epictetus became one of the most influential Stoic philosophers. He taught that we cannot control external events, only our judgments about them. His philosophy provides the practical foundation for the law of self-sabotage: change your attitude, and you change your life.\", laws: [8] },\n  { initial: \"W\", name: \"Winston Churchill\", era: \"United Kingdom (1874–1965)\", desc: \"Churchill's lifelong battle with depression (his 'black dog') became the source of his strength. He channeled his compulsive nature into resolute action. As Prime Minister during WWII, his leadership was a masterclass in emotional connection — he gave a nation the courage to stand alone against tyranny.\", laws: [4, 15] },\n  { initial: \"B\", name: \"Benjamin Franklin\", era: \"United States (1706–1790)\", desc: \"A master of social strategy, Franklin understood the power of indirect influence. He famously won over a rival by asking to borrow a rare book — a request that validated the man's self-image as a scholar. His autobiography is a manual of practical wisdom for navigating human nature.\", laws: [7] },\n  { initial: \"J\", name: \"Joseph Stalin\", era: \"Soviet Union (1878–1953)\", desc: \"Stalin's pathological envy drove him to eliminate every rival. He could not bear anyone who might outshine him, leading to the purges that killed millions. His life is a warning about the destructive power of unchecked envy disguised as ideology.\", laws: [10] },\n  { initial: \"G\", name: \"Galileo Galilei\", era: \"Italy (1564–1642)\", desc: \"When the group — the Church and all of academia — insisted the Earth was the center of the universe, Galileo stood alone with the truth. His persecution by the Inquisition is the definitive example of the individual vs. the herd. His whispered 'And yet it moves' is the eternal cry of the independent thinker.\", laws: [14] },\n  { initial: \"L\", name: \"Leonardo da Vinci\", era: \"Italy (1452–1519)\", desc: \"Da Vinci's purpose was not to paint or invent — it was to understand everything. His notebooks reveal a mind of insatiable curiosity operating across art, science, anatomy, and engineering. He is the supreme example of a life organized by purpose rather than external expectations.\", laws: [13] },\n  { initial: \"S\", name: \"Sun Tzu\", era: \"Ancient China (c. 544–496 BC)\", desc: \"The author of 'The Art of War,' Sun Tzu understood that the highest form of aggression is to achieve victory without fighting. His strategic principles — know yourself, know your enemy, and choose your battles — are timeless lessons for navigating conflict.\", laws: [16] },\n  { initial: \"A\", name: \"Abraham Lincoln\", era: \"United States (1809–1865)\", desc: \"Lincoln led a divided nation through civil war with extraordinary emotional intelligence. He mastered the art of confirming people's self-opinions, used storytelling as a tool of influence, and maintained emotional stability through unimaginable pressure. His leadership model is timeless.\", laws: [3, 7, 15] },\n  { initial: \"F\", name: \"Franklin D. Roosevelt\", era: \"United States (1882–1945)\", desc: \"FDR's fireside chats were a masterclass in emotional leadership. He confirmed the American people's self-image as resilient and capable, giving them the confidence to face the Great Depression and World War II. He understood that leadership is a relationship, not a command.\", laws: [7, 15] },\n  { initial: \"H\", name: \"Helen Keller\", era: \"United States (1880–1968)\", desc: \"Deaf and blind from infancy, Keller refused the narrative of limitation. With an attitude of relentless determination, she became a writer, activist, and global symbol of the power of attitude over circumstance. Her life is a living demonstration of the law of self-sabotage — reversed.\", laws: [8] },\n  { initial: \"M\", name: \"Machiavelli\", era: \"Italy (1469–1527)\", desc: \"The original analyst of power, Machiavelli stripped away all pretense to reveal politics as a theater of masks. His 'The Prince' advises rulers on strategic self-presentation: appear compassionate, faithful, and religious — control the performance, and you control the response.\", laws: [3] },\n  { initial: \"D\", name: \"Dale Carnegie\", era: \"United States (1888–1955)\", desc: \"Carnegie's 'How to Win Friends and Influence People' is built on a radical insight: the deepest human need is to feel important. His principles — become genuinely interested, remember names, listen attentively — are practical strategies for overcoming narcissism and building genuine influence.\", laws: [2, 7] },\n  { initial: \"S\", name: \"Steve Jobs\", era: \"United States (1955–2011)\", desc: \"Jobs found his purpose at the intersection of technology and the humanities. His relentless pursuit of elegant design and his ability to create a compelling vision ('insanely great') attracted followers who would work miracles. His life demonstrates the power of purpose-driven leadership.\", laws: [13, 15] },\n  { initial: \"G\", name: \"Genghis Khan\", era: \"Mongolia (c. 1162–1227)\", desc: \"The most successful conqueror in history, Genghis Khan understood aggression as a calculated strategic tool. His brutality served psychological warfare; his meritocratic policies built loyalty. He transformed warring tribes into the largest empire the world had ever seen.\", laws: [16] },\n  { initial: \"F\", name: \"Sigmund Freud\", era: \"Austria (1856–1939)\", desc: \"Freud revealed the unconscious mind — the hidden world of repressed desires, childhood conflicts, and defense mechanisms. His work on repression, projection, and the irrational foundations of human behavior provides the bedrock for understanding the law of repression.\", laws: [9] },\n  { initial: \"R\", name: \"Rosa Parks\", era: \"United States (1913–2005)\", desc: \"One woman's refusal to conform to segregation laws sparked a movement that transformed a nation. Her quiet courage demonstrated the power of individual conscience against the tyranny of the group. She proved that one person, standing on principle, can change the world.\", laws: [14] },\n  { initial: \"A\", name: \"Andy Warhol\", era: \"United States (1928–1987)\", desc: \"Warhol understood the modern hunger for fame as a form of narcissistic validation. His art — Campbell's soup cans, celebrity portraits — held a mirror to a society obsessed with image and attention. He turned his own narcissism into a commentary on the human condition.\", laws: [2] },\n  { initial: \"Q\", name: \"Queen Elizabeth I\", era: \"England (1533–1603)\", desc: \"The Virgin Queen used her marital status as a strategic tool for 25 years, maintaining the desire of European powers through perpetual unattainability. She understood that a leader's power depends on the emotional bond with followers — and cultivated that bond with masterful skill.\", laws: [5, 15] },\n  { initial: \"M\", name: \"Miyamoto Musashi\", era: \"Japan (1584–1645)\", desc: \"The greatest swordsman in Japanese history was also a master painter, calligrapher, and sculptor. He integrated the warrior and the artist, the masculine and the feminine, the violent and the serene. His 'Book of Five Rings' is a treatise on strategy that transcends combat.\", laws: [12] },\n  { initial: \"F\", name: \"Florence Nightingale\", era: \"United Kingdom (1820–1910)\", desc: \"Despite fierce opposition from her wealthy family, Nightingale pursued her calling to nursing with unwavering purpose. Her statistical analysis, hospital reforms, and relentless advocacy transformed medicine. She is the model of purpose-driven life.\", laws: [13] },\n  { initial: \"M\", name: \"Marilyn Monroe\", era: \"United States (1926–1962)\", desc: \"Beneath the glamour and fame lay a profoundly wounded woman who never received the unconditional love she needed as a child. Her tragic life — the desperate need for validation, the inability to trust, the self-destructive patterns — illustrates the insatiable nature of narcissistic hunger.\", laws: [2] },\n  { initial: \"W\", name: \"Warren Buffett\", era: \"United States (1930–Present)\", desc: \"Buffett's investing philosophy is a masterclass in long-term thinking. While others chase short-term gains, he holds investments for decades. 'The stock market is a device for transferring money from the impatient to the patient.' His life demonstrates the power of elevated perspective.\", laws: [6] },\n  { initial: \"M\", name: \"Michel de Montaigne\", era: \"France (1533–1592)\", desc: \"Montaigne invented the essay as a form of personal inquiry. He wrote extensively on death, arguing that 'to philosophize is to learn how to die.' His essays explore the full range of human nature with honesty, humor, and wisdom.\", laws: [18] },\n  { initial: \"P\", name: \"Pericles\", era: \"Ancient Greece (495–429 BC)\", desc: \"The Athenian statesman who built the Parthenon and led Athens to its golden age through long-term strategic thinking. He rejected short-term populist measures, maintained composure under attack, and elevated the Athenian people through his vision.\", laws: [1, 6] },\n  { initial: \"C\", name: \"Coco Chanel\", era: \"France (1883–1971)\", desc: \"Chanel built an empire on scarcity and mystique. Her perfume was marketed as the scent of a 'certain woman' — mysterious, rare, desirable. She understood that the most powerful brand is one that maintains an air of the unattainable.\", laws: [5] },\n  { initial: \"R\", name: \"Robert Louis Stevenson\", era: \"Scotland (1850–1894)\", desc: \"Author of 'Strange Case of Dr Jekyll and Mr Hyde,' the classic allegory of the shadow. Stevenson dramatized the danger of repressing one's dark side: the respectable Dr. Jekyll, by denying his shadow, gives it monstrous power.\", laws: [9] },\n  { initial: \"A\", name: \"Auguste Comte\", era: \"France (1798–1857)\", desc: \"Founder of sociology, Comte developed the law of three stages through which societies evolve: theological, metaphysical, and scientific. His work laid the foundation for understanding generational cycles and historical patterns.\", laws: [17] },\n  { initial: \"G\", name: \"Giambattista Vico\", era: \"Italy (1668–1744)\", desc: \"Vico's 'New Science' identified the cyclical nature of history: ages of gods, heroes, and humans, followed by a return. His idea that history moves in recurring cycles — not a linear line — anticipated modern theories of generational change.\", laws: [17] },\n  { initial: \"H\", name: \"Howard Hughes\", era: \"United States (1905–1976)\", desc: \"Billionaire, aviator, film producer — Hughes's grandiosity evolved into pathological delusion. He believed he could control everything around him, from germs to the air he breathed. His tragic decline shows the end stage of unchecked grandiosity.\", laws: [11] }\n];\n\nconst strategies = [\n  { num: 1, title: \"The Socratic Pause\", desc: \"When emotion surges, stop. Literally pause for 6 seconds before responding. Let the rational brain catch up to the emotional brain. This small gap is the difference between mastery and reactivity.\", tag: \"Law 1\" },\n  { num: 2, title: \"Deep Listening Protocol\", desc: \"For the first ten minutes of any conversation, do not speak about yourself. Listen actively. Ask questions. Show you are absorbing. People will feel your presence as something rare and magnetic.\", tag: \"Law 2\" },\n  { num: 3, title: \"Behavioral Pattern Journal\", desc: \"Keep a log of people's repeated behaviors — their reactions to stress, success, conflict, and boredom. Over time, their compulsive patterns will become as clear as a map.\", tag: \"Law 4\" },\n  { num: 4, title: \"The Scarcity Frame\", desc: \"Never reveal your full hand. In negotiations, relationships, and social interactions, maintain an element of mystery. Let people discover you slowly. What is held back creates desire.\", tag: \"Law 5\" },\n  { num: 5, title: \"Future Retrospection\", desc: \"Before any major decision, imagine yourself ten years from now looking back. What would your future self advise? This mental time travel breaks the tyranny of the present moment.\", tag: \"Law 6\" },\n  { num: 6, title: \"The Identity Bridge\", desc: \"Before asking for change, first validate who the person believes themselves to be. Frame your request as consistent with their self-image. 'Because you're someone with great taste, I thought you'd appreciate...'\", tag: \"Law 7\" },\n  { num: 7, title: \"Radical Reframing\", desc: \"When something goes wrong, consciously ask: what is the empowering interpretation here? What does this make possible? The meaning you assign creates your reality.\", tag: \"Law 8\" },\n  { num: 8, title: \"Shadow Integration Practice\", desc: \"When you feel a strong negative reaction to someone, ask: what quality am I seeing that I have not accepted in myself? The judgment is always a mirror.\", tag: \"Law 9\" },\n  { num: 9, title: \"Success Inoculation\", desc: \"Share your struggles and failures openly, especially with those who might envy your success. Make yourself relatable. The vulnerable person is rarely the target of envy.\", tag: \"Law 10\" },\n  { num: 10, title: \"The Counterweight System\", desc: \"Identify the people who will tell you the uncomfortable truth. Cultivate these relationships actively. Your grandiosity will be checked by those who love you enough to confront you.\", tag: \"Law 11\" },\n  { num: 11, title: \"Shadow Integration\", desc: \"Identify the gender-coded qualities you have rejected — sensitivity if you are male, assertiveness if you are female. Find safe ways to express them. Integration brings power.\", tag: \"Law 12\" },\n  { num: 12, title: \"Purpose Audit\", desc: \"List the moments you felt most alive. What were you doing? Who were you with? These are the clues to your purpose. Now eliminate one distraction per week to create space for it.\", tag: \"Law 13\" },\n  { num: 13, title: \"The Private Opinion\", desc: \"Before entering any group discussion, take 5 minutes alone to form your own opinion. Write it down. Then participate. Compare what you wrote to what you say — the gap reveals conformity pressure.\", tag: \"Law 14\" },\n  { num: 14, title: \"The Vision Statement\", desc: \"Articulate a clear, compelling vision of where you are leading people. Paint a picture of a future they want to inhabit. People follow vision, not commands.\", tag: \"Law 15\" },\n  { num: 15, title: \"Assertiveness Practice\", desc: \"Start small. Say no to one small request each day. Express a preference directly. The muscle of healthy assertiveness must be trained. Passive aggression is what happens when this muscle atrophies.\", tag: \"Law 16\" },\n  { num: 16, title: \"Generational Mapping\", desc: \"Identify which generational archetype you belong to. Study how your biases were shaped by the era you grew up in. Now ask: what am I blind to because of when I was born?\", tag: \"Law 17\" },\n  { num: 17, title: \"Memento Mori Practice\", desc: \"Keep a physical reminder of mortality visible — a small skull, a candle, a quote. Let it inform your daily choices. Ask: if I had one year to live, would I be doing this?\", tag: \"Law 18\" },\n  { num: 18, title: \"The Cooling Ritual\", desc: \"Develop a specific physical action that interrupts emotional flooding — five deep breaths, counting backward from 20, a brief walk. Train it until it becomes automatic.\", tag: \"Law 1\" },\n  { num: 19, title: \"Admiration Reframe\", desc: \"When envy rises, mentally transform it into admiration and study. Instead of resenting someone's success, ask: what can I learn from them? Envy is just misdirected curiosity.\", tag: \"Law 10\" },\n  { num: 20, title: \"The Eulogy Exercise\", desc: \"Write your own eulogy as you would want it spoken. Now live each day in a way that moves toward that person. Death awareness is the most powerful of all filters.\", tag: \"Law 18\" }\n];\n\nconst quotes = [\n  { text: \"The greatest power you can possess is knowing yourself and understanding the motivations of others.\", source: \"The Laws of Human Nature\" },\n  { text: \"Emotion is not something that happens to you. It is something you can learn to master.\", source: \"The Laws of Human Nature\" },\n  { text: \"People are not what they appear to be. Their outward behavior is a performance designed to hide their true nature.\", source: \"The Laws of Human Nature\" },\n  { text: \"The greatest seduction is the one that makes people feel seen, understood, and important.\", source: \"The Laws of Human Nature\" },\n  { text: \"What you repress in yourself will emerge in disguised form — as projection, as passive aggression, as unconscious acting out.\", source: \"The Laws of Human Nature\" },\n  { text: \"Envy is the most toxic of emotions because it is the most denied. It festers in the dark.\", source: \"The Laws of Human Nature\" },\n  { text: \"The greatest leaders are those who understand that leadership is not about power over others but power through others.\", source: \"The Laws of Human Nature\" },\n  { text: \"To see the world clearly, you must first accept that you are biased, emotional, and prone to illusion.\", source: \"The Laws of Human Nature\" },\n  { text: \"Your attitude is not a reflection of your circumstances. Your circumstances are a reflection of your attitude.\", source: \"The Laws of Human Nature\" },\n  { text: \"The fear of death is the hidden engine behind so much human activity — ambition, accumulation, the desperate need to matter.\", source: \"The Laws of Human Nature\" },\n  { text: \"We are all narcissists. The healthiest among us have simply learned to transform their self-absorption into empathy.\", source: \"The Laws of Human Nature\" },\n  { text: \"Character is not what people say they believe — it is what they do repeatedly. Watch actions, not words.\", source: \"The Laws of Human Nature\" },\n  { text: \"The person who maintains an air of mystery will always be more desirable than the one who reveals everything.\", source: \"The Laws of Human Nature\" },\n  { text: \"The group does not think. It feels. It reacts. To resist its pull requires more self-awareness than most people ever develop.\", source: \"The Laws of Human Nature\" },\n  { text: \"Meditating on death does not depress you — it liberates you. The person who has made peace with mortality is the freest person alive.\", source: \"The Laws of Human Nature\" },\n  { text: \"Nothing is more seductive than the person who is genuinely interested in you. The rarest gift you can give is your full attention.\", source: \"The Laws of Human Nature\" },\n  { text: \"Hubris is not confidence. It is the loss of contact with reality. The line between them is self-awareness.\", source: \"The Laws of Human Nature\" },\n  { text: \"To master human nature, you must first accept it — in all its glory, all its darkness, and all its complexity.\", source: \"The Laws of Human Nature\" }\n];\n\n//  RENDER \n\nfunction createLaws() {\n  const container = document.getElementById('lawsContainer');\n  laws.forEach((law, i) => {\n    const card = document.createElement('div');\n    card.className = 'law-card reveal';\n    card.style.transitionDelay = (i * 0.08) + 's';\n    card.id = 'law-' + law.num;\n\n    const strategiesHtml = law.strategies.map(s => `<li>${s}</li>`).join('');\n    const examplesHtml = law.examples.map(e =>\n      `<li><span class=\"example-figure\">${e.figure}:</span> ${e.detail}</li>`\n    ).join('');\n\n    card.innerHTML = `\n      <div class=\"law-header\">\n        <div class=\"law-number\">${String(law.num).padStart(2,'0')}</div>\n        <div class=\"law-title\">\n          <h3>${law.title}</h3>\n          <div class=\"law-subtitle\">${law.subtitle}</div>\n        </div>\n        <button class=\"law-toggle\" aria-label=\"Expand\">+</button>\n      </div>\n      <div class=\"law-body\">\n        <p>${law.desc}</p>\n        <div class=\"law-insight\">${law.insight}</div>\n        <div class=\"law-strategies\">\n          <h4>Strategies</h4>\n          <ul>${strategiesHtml}</ul>\n        </div>\n        <div class=\"law-examples\">\n          <h4>Historical Examples</h4>\n          <ul>${examplesHtml}</ul>\n        </div>\n        <div class=\"self-assessment\">\n          <h4>Self-Assessment</h4>\n          <div class=\"assess-question\">${law.assess}</div>\n          <div class=\"assess-options\">\n            <button class=\"assess-btn\" data-score=\"1\">Not at all</button>\n            <button class=\"assess-btn\" data-score=\"2\">Rarely</button>\n            <button class=\"assess-btn\" data-score=\"3\">Sometimes</button>\n            <button class=\"assess-btn\" data-score=\"4\">Often</button>\n            <button class=\"assess-btn\" data-score=\"5\">Always</button>\n          </div>\n          <div class=\"assess-result\"></div>\n        </div>\n      </div>\n    `;\n\n    container.appendChild(card);\n\n    // Toggle\n    const header = card.querySelector('.law-header');\n    const toggle = card.querySelector('.law-toggle');\n    const body = card.querySelector('.law-body');\n\n    header.addEventListener('click', () => {\n      const isOpen = card.classList.contains('expanded');\n      card.classList.toggle('expanded');\n      toggle.textContent = isOpen ? '+' : '×';\n    });\n\n    // Self-assessment\n    const assessBtns = card.querySelectorAll('.assess-btn');\n    const resultDiv = card.querySelector('.assess-result');\n    assessBtns.forEach(btn => {\n      btn.addEventListener('click', (e) => {\n        e.stopPropagation();\n        assessBtns.forEach(b => b.classList.remove('selected'));\n        btn.classList.add('selected');\n        const score = parseInt(btn.dataset.score);\n        let msg = '';\n        if (score <= 2) msg = 'This is an area of relative strength. Continue to build awareness.';\n        else if (score <= 3) msg = 'Moderate awareness. You have room to grow here. Study this law more deeply.';\n        else if (score <= 4) msg = 'This is a challenge for you. Consider practicing the strategies above.';\n        else msg = 'This law touches a significant pattern. Dedicated practice of the strategies will bring transformation.';\n        resultDiv.textContent = msg;\n        resultDiv.style.display = 'block';\n      });\n    });\n  });\n}\n\nfunction createTOC() {\n  const container = document.getElementById('tocLinks');\n  laws.forEach(law => {\n    const a = document.createElement('a');\n    a.className = 'toc-link';\n    a.href = '#law-' + law.num;\n    a.innerHTML = `<span class=\"toc-num\">${String(law.num).padStart(2,'0')}</span> ${law.title}`;\n    a.addEventListener('click', (e) => {\n      e.preventDefault();\n      document.getElementById('tocPanel').classList.remove('open');\n      document.getElementById('tocOverlay').classList.remove('open');\n      document.getElementById('law-' + law.num).scrollIntoView({ behavior: 'smooth' });\n    });\n    container.appendChild(a);\n  });\n}\n\nfunction createPatterns() {\n  const grid = document.getElementById('patternsGrid');\n  patterns.forEach((p, i) => {\n    const card = document.createElement('div');\n    card.className = 'pattern-card reveal';\n    card.style.transitionDelay = (i * 0.06) + 's';\n    card.innerHTML = `\n      <span class=\"pattern-icon\">${p.icon}</span>\n      <h4>${p.title}</h4>\n      <p>${p.desc}</p>\n      <span class=\"pattern-law\">${p.law}</span>\n    `;\n    grid.appendChild(card);\n  });\n}\n\nfunction createFigures() {\n  const grid = document.getElementById('figuresGrid');\n  historicalFigures.forEach((fig, i) => {\n    const card = document.createElement('div');\n    card.className = 'historical-card reveal';\n    card.style.transitionDelay = (i * 0.04) + 's';\n    card.innerHTML = `\n      <div class=\"hc-icon\">${fig.initial}</div>\n      <h4>${fig.name}</h4>\n      <div class=\"hc-era\">${fig.era}</div>\n      <p>${fig.desc.substring(0, 150)}...</p>\n      <div class=\"hc-tag\">Law ${fig.laws.join(', ')}</div>\n    `;\n    card.addEventListener('click', () => openModal(fig));\n    grid.appendChild(card);\n  });\n}\n\nfunction openModal(fig) {\n  const modal = document.getElementById('figureModal');\n  document.getElementById('modalIcon').textContent = fig.initial;\n  document.getElementById('modalName').textContent = fig.name;\n  document.getElementById('modalEra').textContent = fig.era;\n  document.getElementById('modalBody').innerHTML = `\n    <p>${fig.desc}</p>\n    <div class=\"modal-law-link\">Related Laws: ${fig.laws.map(l => `<a href=\"#law-${l}\" style=\"color:var(--bronze-light);text-decoration:none;\" onclick=\"document.getElementById('figureModal').classList.remove('open');setTimeout(()=>document.getElementById('law-${l}').scrollIntoView({behavior:'smooth'}),300)\">Law ${l}</a>`).join(', ')}</div>\n  `;\n  modal.classList.add('open');\n}\n\nfunction createStrategies() {\n  const grid = document.getElementById('strategyGrid');\n  strategies.forEach((s, i) => {\n    const card = document.createElement('div');\n    card.className = 'strategy-card reveal';\n    card.style.transitionDelay = (i * 0.05) + 's';\n    card.innerHTML = `\n      <div class=\"sc-num\">${String(s.num).padStart(2,'0')}</div>\n      <h4>${s.title}</h4>\n      <p>${s.desc}</p>\n      <div class=\"sc-tag\">${s.tag}</div>\n    `;\n    grid.appendChild(card);\n  });\n}\n\nfunction createQuotes() {\n  const grid = document.getElementById('quotesGrid');\n  quotes.forEach((q, i) => {\n    const card = document.createElement('div');\n    card.className = 'quote-card reveal';\n    card.style.transitionDelay = (i * 0.06) + 's';\n    card.innerHTML = `\n      <div class=\"quote-text\">\"${q.text}\"</div>\n      <cite>— ${q.source}</cite>\n    `;\n    grid.appendChild(card);\n  });\n}\n\n//  MODAL CLOSE \ndocument.getElementById('modalClose').addEventListener('click', () => {\n  document.getElementById('figureModal').classList.remove('open');\n});\ndocument.getElementById('figureModal').addEventListener('click', (e) => {\n  if (e.target === e.currentTarget) document.getElementById('figureModal').classList.remove('open');\n});\n\n//  TOC \ndocument.getElementById('tocToggle').addEventListener('click', () => {\n  document.getElementById('tocPanel').classList.toggle('open');\n  document.getElementById('tocOverlay').classList.toggle('open');\n});\ndocument.getElementById('tocOverlay').addEventListener('click', () => {\n  document.getElementById('tocPanel').classList.remove('open');\n  document.getElementById('tocOverlay').classList.remove('open');\n});\n\n//  THEME TOGGLE \ndocument.getElementById('themeToggle').addEventListener('click', () => {\n  document.body.classList.toggle('light');\n  const btn = document.getElementById('themeToggle');\n  btn.innerHTML = document.body.classList.contains('light') ? '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"/></svg>' : '<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>';\n});\n\n//  SCROLL REVEAL \nfunction handleReveal() {\n  const reveals = document.querySelectorAll('.reveal');\n  reveals.forEach(el => {\n    const top = el.getBoundingClientRect().top;\n    const winH = window.innerHeight;\n    if (top < winH - 60) el.classList.add('visible');\n  });\n}\n\n//  COUNTER \nfunction animateCounters() {\n  const counters = document.querySelectorAll('.stat-number');\n  counters.forEach(counter => {\n    const target = parseInt(counter.dataset.count);\n    if (!target) { counter.textContent = counter.dataset.count || '0'; return; }\n    const duration = 2000;\n    const step = Math.max(1, Math.floor(target / 60));\n    let current = 0;\n    const inc = Math.ceil(target / (duration / 16));\n    const update = setInterval(() => {\n      current += inc;\n      if (current >= target) {\n        current = target;\n        clearInterval(update);\n      }\n      counter.textContent = current >= 1000 ? (current / 1000).toFixed(1).replace('.0','') + 'k+' : current;\n    }, 16);\n  });\n}\n\n//  CANVAS PARTICLES \n(function(){\n  const canvas = document.getElementById('bgCanvas');\n  const ctx = canvas.getContext('2d');\n  let particles = [];\n  let mouse = {x: -1000, y: -1000};\n\n  function resize(){\n    canvas.width = window.innerWidth;\n    canvas.height = window.innerHeight;\n  }\n  resize();\n  window.addEventListener('resize', resize);\n\n  const colors = ['#CD7F32', '#e09e55', '#0D3B3B', '#7a4a18', '#f5efe0'];\n\n  class Particle {\n    constructor() { this.reset(); }\n    reset(){\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.vx = (Math.random() - 0.5) * 0.15;\n      this.vy = (Math.random() - 0.5) * 0.15;\n      this.r = Math.random() * 1.8 + 0.3;\n      this.color = colors[Math.floor(Math.random() * colors.length)];\n      this.alpha = Math.random() * 0.12 + 0.03;\n    }\n    update(){\n      this.x += this.vx;\n      this.y += this.vy;\n      if (this.x < 0 || this.x > canvas.width) this.vx *= -1;\n      if (this.y < 0 || this.y > canvas.height) this.vy *= -1;\n    }\n    draw(){\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);\n      ctx.fillStyle = this.color;\n      ctx.globalAlpha = this.alpha;\n      ctx.fill();\n      ctx.globalAlpha = 1;\n    }\n  }\n\n  for (let i = 0; i < 50; i++) particles.push(new Particle());\n\n  function animate(){\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const d = Math.sqrt(dx*dx + dy*dy);\n        if (d < 130) {\n          ctx.beginPath();\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.strokeStyle = particles[i].color;\n          ctx.globalAlpha = 0.03 * (1 - d/130);\n          ctx.stroke();\n          ctx.globalAlpha = 1;\n        }\n      }\n    }\n    particles.forEach(p => {\n      const dx = p.x - mouse.x;\n      const dy = p.y - mouse.y;\n      const d = Math.sqrt(dx*dx + dy*dy);\n      if (d < 150) {\n        ctx.beginPath();\n        ctx.moveTo(p.x, p.y);\n        ctx.lineTo(mouse.x, mouse.y);\n        ctx.strokeStyle = p.color;\n        ctx.globalAlpha = 0.05 * (1 - d/150);\n        ctx.stroke();\n        ctx.globalAlpha = 1;\n      }\n    });\n    particles.forEach(p => { p.update(); p.draw(); });\n    requestAnimationFrame(animate);\n  }\n  animate();\n\n  document.addEventListener('mousemove', e => {\n    mouse.x = e.clientX;\n    mouse.y = e.clientY;\n  });\n})();\n\n//  ORBS \n(function(){\n  const c = document.getElementById('orbs');\n  const orbColors = [\n    'rgba(205,127,50,0.08)',\n    'rgba(13,59,59,0.12)',\n    'rgba(205,127,50,0.05)',\n    'rgba(13,59,59,0.08)'\n  ];\n  for (let i = 0; i < 5; i++) {\n    const o = document.createElement('div');\n    o.className = 'orb';\n    const size = 200 + Math.random() * 300;\n    o.style.cssText = `\n      width:${size}px;height:${size}px;\n      left:${Math.random()*100}%;\n      top:${Math.random()*100}%;\n      background:${orbColors[i % orbColors.length]};\n      --duration:${25 + Math.random() * 35}s;\n      --delay:${Math.random() * 10}s;\n      --max-opacity:0.3;\n      --tx:${(Math.random()-0.5)*400}px;\n      --ty:${(Math.random()-0.5)*400}px;\n    `;\n    c.appendChild(o);\n  }\n})();\n\n//  MOUSE GLOW \ndocument.addEventListener('mousemove', e => {\n  const g = document.getElementById('mouseGlow');\n  g.style.left = e.clientX + 'px';\n  g.style.top = e.clientY + 'px';\n});\n\n//  SCROLL PROGRESS \nwindow.addEventListener('scroll', () => {\n  const s = window.scrollY / (document.body.scrollHeight - window.innerHeight) * 100;\n  document.getElementById('progress').style.width = s + '%';\n  handleReveal();\n});\n\n//  INIT \ncreateTOC();\ncreateLaws();\ncreatePatterns();\ncreateFigures();\ncreateStrategies();\ncreateQuotes();\nhandleReveal();\n\n// Counter animation on scroll\nlet countersAnimated = false;\nwindow.addEventListener('scroll', () => {\n  if (!countersAnimated) {\n    const statsBar = document.querySelector('.stats-bar');\n    if (statsBar && statsBar.getBoundingClientRect().top < window.innerHeight - 100) {\n      countersAnimated = true;\n      animateCounters();\n    }\n  }\n});\n// fallback\nsetTimeout(() => {\n  if (!countersAnimated) {\n    const statsBar = document.querySelector('.stats-bar');\n    if (statsBar && statsBar.getBoundingClientRect().top < window.innerHeight - 100) {\n      countersAnimated = true;\n      animateCounters();\n    }\n  }\n}, 2000);\n</script>\n\n\n\n</body>\n</html>",
  "the-millionaire-master-plan": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<canvas id=\"particles-canvas\"></canvas>\n\n\n\n<div class=\"content\">\n\n<!-- Hero -->\n\n\n<!-- Stats -->\n<section>\n  <div class=\"reveal\">\n    <div class=\"section-label\">⚡ At a Glance</div>\n    <h2 class=\"section-title\">The Framework for Wealth</h2>\n    <p class=\"section-subtitle\">Roger James Hamilton's proven system has helped thousands discover their financial path.</p>\n  </div>\n  <div class=\"stats-grid\">\n    <div class=\"stat-card reveal reveal-delay-1\"><div class=\"stat-number\">9</div><div class=\"stat-label\">Wealth Spectrum Stages</div></div>\n    <div class=\"stat-card reveal reveal-delay-2\"><div class=\"stat-number\">4</div><div class=\"stat-label\">Wealth DNA Types</div></div>\n    <div class=\"stat-card reveal reveal-delay-3\"><div class=\"stat-number\">4</div><div class=\"stat-label\">Pathways to Wealth</div></div>\n    <div class=\"stat-card reveal reveal-delay-4\"><div class=\"stat-number\">10</div><div class=\"stat-label\">Key Principles</div></div>\n  </div>\n</section>\n\n<!-- Wealth Spectrum -->\n<section id=\"spectrum\" class=\"spectrum-section\">\n<div class=\"section-inner\">\n  <div class=\"reveal\">\n    <div class=\"section-label\">▲ The Wealth Spectrum</div>\n    <h2 class=\"section-title\">From Survival to Abundance</h2>\n    <p class=\"section-subtitle\">Nine stages that map your journey from financial struggle to total freedom. Click each stage to learn more.</p>\n  </div>\n\n  <div class=\"thermometer-container reveal\">\n    <div class=\"thermometer\"><div class=\"thermometer-fill\" id=\"thermometerFill\"></div></div>\n    <div class=\"thermometer-labels\"><span>Survival</span><span>Abundance</span></div>\n  </div>\n\n  <div class=\"spectrum-ladder\" id=\"spectrumLadder\">\n    <div class=\"spectrum-stage\" data-stage=\"-1\" onclick=\"toggleStage(this)\">\n      <span class=\"stage-icon\">☢</span>\n      <span class=\"stage-num\">-1</span>\n      <span class=\"stage-name\">Survival</span>\n      <span class=\"stage-desc\">Scrambling to meet basic needs. Living paycheck to paycheck, focused on day-to-day survival with no financial cushion.</span>\n      <span class=\"stage-status\" id=\"status--1\"></span>\n    </div>\n    <div class=\"spectrum-stage\" data-stage=\"0\" onclick=\"toggleStage(this)\">\n      <span class=\"stage-icon\">⛳</span>\n      <span class=\"stage-num\">0</span>\n      <span class=\"stage-name\">Stability</span>\n      <span class=\"stage-desc\">Expenses are covered. You have a reliable income stream and are no longer in crisis mode, but savings are minimal.</span>\n      <span class=\"stage-status\" id=\"status-0\"></span>\n    </div>\n    <div class=\"spectrum-stage\" data-stage=\"1\" onclick=\"toggleStage(this)\">\n      <span class=\"stage-icon\">★</span>\n      <span class=\"stage-num\">1</span>\n      <span class=\"stage-name\">Success</span>\n      <span class=\"stage-desc\">Income exceeds expenses. You're building momentum, growing your skills, and starting to accumulate wealth intentionally.</span>\n      <span class=\"stage-status\" id=\"status-1\"></span>\n    </div>\n    <div class=\"spectrum-stage\" data-stage=\"2\" onclick=\"toggleStage(this)\">\n      <span class=\"stage-icon\">🛡</span>\n      <span class=\"stage-num\">2</span>\n      <span class=\"stage-name\">Security</span>\n      <span class=\"stage-desc\">Financial safety net in place. Multiple income streams, emergency fund secured, and wealth preservation becomes the focus.</span>\n      <span class=\"stage-status\" id=\"status-2\"></span>\n    </div>\n    <div class=\"spectrum-stage\" data-stage=\"3\" onclick=\"toggleStage(this)\">\n      <span class=\"stage-icon\">🌟</span>\n      <span class=\"stage-num\">3</span>\n      <span class=\"stage-name\">Significance</span>\n      <span class=\"stage-desc\">Wealth with purpose. You begin using your resources to make a difference — philanthropy, mentoring, and impact investing.</span>\n      <span class=\"stage-status\" id=\"status-3\"></span>\n    </div>\n    <div class=\"spectrum-stage\" data-stage=\"4\" onclick=\"toggleStage(this)\">\n      <span class=\"stage-icon\">🛦</span>\n      <span class=\"stage-num\">4</span>\n      <span class=\"stage-name\">Succession</span>\n      <span class=\"stage-desc\">Building legacy systems. You create structures and systems that generate wealth without your direct involvement.</span>\n      <span class=\"stage-status\" id=\"status-4\"></span>\n    </div>\n    <div class=\"spectrum-stage\" data-stage=\"5\" onclick=\"toggleStage(this)\">\n      <span class=\"stage-icon\">☼</span>\n      <span class=\"stage-num\">5</span>\n      <span class=\"stage-name\">Serenity</span>\n      <span class=\"stage-desc\">Complete peace of mind. Wealth serves you, not the other way around. You operate from a place of calm abundance.</span>\n      <span class=\"stage-status\" id=\"status-5\"></span>\n    </div>\n    <div class=\"spectrum-stage\" data-stage=\"6\" onclick=\"toggleStage(this)\">\n      <span class=\"stage-icon\">✨</span>\n      <span class=\"stage-num\">6</span>\n      <span class=\"stage-name\">Simplicity</span>\n      <span class=\"stage-desc\">Freedom from complexity. You've streamlined your life and wealth to focus only on what truly matters to you.</span>\n      <span class=\"stage-status\" id=\"status-6\"></span>\n    </div>\n    <div class=\"spectrum-stage\" data-stage=\"7\" onclick=\"toggleStage(this)\">\n      <span class=\"stage-icon\">♻</span>\n      <span class=\"stage-num\">7</span>\n      <span class=\"stage-name\">Abundance</span>\n      <span class=\"stage-desc\">Infinite flow. Wealth circulates freely through you and from you. You live in complete alignment with your purpose.</span>\n      <span class=\"stage-status\" id=\"status-7\"></span>\n    </div>\n  </div>\n</div>\n</section>\n\n<!-- Wealth DNA -->\n<section id=\"dna\">\n  <div class=\"reveal\">\n    <div class=\"section-label\">🧙 Your Wealth DNA</div>\n    <h2 class=\"section-title\">Find Your Wealth Personality</h2>\n    <p class=\"section-subtitle\">Everyone has a natural wealth archetype. Discover yours and unlock the pathway that aligns with who you truly are.</p>\n  </div>\n\n  <div class=\"dna-grid\">\n    <div class=\"dna-card reveal reveal-delay-1\" onclick=\"selectDna(this)\" data-type=\"dynamo\">\n      <div class=\"dna-icon\" style=\"border-color:var(--gold)\">⚡</div>\n      <div class=\"dna-name\">Dynamo</div>\n      <div class=\"dna-type\">The Creator</div>\n      <div class=\"dna-desc\">High energy, visionary, and idea-driven. You thrive on innovation and turning concepts into reality. Your wealth comes from creating value others haven't imagined.</div>\n      <div class=\"dna-traits\"><span>Visionary</span><span>Innovator</span><span>Risk-Taker</span><span>Leader</span></div>\n    </div>\n    <div class=\"dna-card reveal reveal-delay-2\" onclick=\"selectDna(this)\" data-type=\"blaze\">\n      <div class=\"dna-icon\" style=\"border-color:var(--gold)\">🌟</div>\n      <div class=\"dna-name\">Blaze</div>\n      <div class=\"dna-type\">The Star</div>\n      <div class=\"dna-desc\">Charismatic, expressive, and people-focused. You inspire others and build wealth through influence, networks, and personal brand.</div>\n      <div class=\"dna-traits\"><span>Charismatic</span><span>Influencer</span><span>Connector</span><span>Communicator</span></div>\n    </div>\n    <div class=\"dna-card reveal reveal-delay-3\" onclick=\"selectDna(this)\" data-type=\"tempo\">\n      <div class=\"dna-icon\" style=\"border-color:var(--gold)\">💚</div>\n      <div class=\"dna-name\">Tempo</div>\n      <div class=\"dna-type\">The Supporter</div>\n      <div class=\"dna-desc\">Nurturing, reliable, and relationship-driven. You build wealth through trust, service, and long-term partnerships that create lasting value.</div>\n      <div class=\"dna-traits\"><span>Nurturer</span><span>Loyal</span><span>Empathetic</span><span>Steadfast</span></div>\n    </div>\n    <div class=\"dna-card reveal reveal-delay-4\" onclick=\"selectDna(this)\" data-type=\"steel\">\n      <div class=\"dna-icon\" style=\"border-color:var(--gold)\">⚖</div>\n      <div class=\"dna-name\">Steel</div>\n      <div class=\"dna-type\">The Dealer</div>\n      <div class=\"dna-desc\">Analytical, strategic, and system-driven. You build wealth through precision, optimization, and mastering the mechanics of money.</div>\n      <div class=\"dna-traits\"><span>Analytical</span><span>Strategic</span><span>Disciplined</span><span>Precise</span></div>\n    </div>\n  </div>\n</section>\n\n<!-- Quiz -->\n<section id=\"quiz\" class=\"quiz-section reveal\">\n  <div class=\"section-label\" style=\"text-align:center;display:flex;justify-content:center\">📜 Discover Your Type</div>\n  <h2 class=\"section-title\" style=\"text-align:center\">Wealth DNA Quiz</h2>\n  <p class=\"section-subtitle\" style=\"text-align:center;margin:0 auto 2rem\">Answer a few questions to find your natural wealth personality.</p>\n\n  <div id=\"quizContainer\">\n    <div class=\"quiz-progress\" id=\"quizProgress\"></div>\n    <div id=\"quizContent\"></div>\n    <div class=\"quiz-nav\" id=\"quizNav\"></div>\n  </div>\n</section>\n\n<!-- Pathways -->\n<section id=\"pathways\">\n  <div class=\"reveal\">\n    <div class=\"section-label\">🚀 Your Pathway</div>\n    <h2 class=\"section-title\">The 4 Pathways to Wealth</h2>\n    <p class=\"section-subtitle\">Each Wealth DNA type has a natural pathway. Align yours and accelerate your journey.</p>\n  </div>\n\n  <div class=\"pathways-grid\">\n    <div class=\"pathway-card reveal reveal-delay-1\">\n      <div class=\"path-icon\">⚡</div>\n      <div class=\"path-name\">The Creator Pathway</div>\n      <div class=\"path-desc\">Build new products, services, and ventures. Your wealth grows through innovation, intellectual property, and bringing bold ideas to market. Best for: Dynamos.</div>\n      <a class=\"path-link\" href=\"#quiz\">Find your path →</a>\n    </div>\n    <div class=\"pathway-card reveal reveal-delay-2\">\n      <div class=\"path-icon\">🌟</div>\n      <div class=\"path-name\">The Star Pathway</div>\n      <div class=\"path-desc\">Leverage your influence, network, and personal brand. Your wealth grows through visibility, relationships, and inspiring others to action. Best for: Blazes.</div>\n      <a class=\"path-link\" href=\"#quiz\">Find your path →</a>\n    </div>\n    <div class=\"pathway-card reveal reveal-delay-3\">\n      <div class=\"path-icon\">💚</div>\n      <div class=\"path-name\">The Supporter Pathway</div>\n      <div class=\"path-desc\">Build deep relationships and provide unmatched service. Your wealth grows through trust, referrals, and long-term client partnerships. Best for: Tempos.</div>\n      <a class=\"path-link\" href=\"#quiz\">Find your path →</a>\n    </div>\n    <div class=\"pathway-card reveal reveal-delay-4\">\n      <div class=\"path-icon\">⚖</div>\n      <div class=\"path-name\">The Dealer Pathway</div>\n      <div class=\"path-desc\">Master systems, data, and strategic plays. Your wealth grows through efficiency, arbitrage, and building scalable automated engines. Best for: Steels.</div>\n      <a class=\"path-link\" href=\"#quiz\">Find your path →</a>\n    </div>\n  </div>\n</section>\n\n<!-- Milestone Tracker -->\n<section>\n  <div class=\"reveal\">\n    <div class=\"section-label\">📌 Milestones</div>\n    <h2 class=\"section-title\">Your Wealth Journey Tracker</h2>\n    <p class=\"section-subtitle\">Click milestones to mark your progress along the Wealth Spectrum.</p>\n  </div>\n  <div class=\"milestones\" id=\"milestones\">\n    <div class=\"milestone-item\" onclick=\"toggleMilestone(this)\">\n      <div class=\"milestone-check\">✓</div>\n      <div class=\"milestone-info\"><div class=\"ms-title\">Achieve Financial Stability</div><div class=\"ms-desc\">Cover all expenses with income to spare</div></div>\n    </div>\n    <div class=\"milestone-item\" onclick=\"toggleMilestone(this)\">\n      <div class=\"milestone-check\">✓</div>\n      <div class=\"milestone-info\"><div class=\"ms-title\">Build Your Emergency Fund</div><div class=\"ms-desc\">6 months of living expenses saved</div></div>\n    </div>\n    <div class=\"milestone-item\" onclick=\"toggleMilestone(this)\">\n      <div class=\"milestone-check\">✓</div>\n      <div class=\"milestone-info\"><div class=\"ms-title\">Create Multiple Income Streams</div><div class=\"ms-desc\">Diversify beyond your primary source</div></div>\n    </div>\n    <div class=\"milestone-item\" onclick=\"toggleMilestone(this)\">\n      <div class=\"milestone-check\">✓</div>\n      <div class=\"milestone-info\"><div class=\"ms-title\">Achieve Financial Security</div><div class=\"ms-desc\">Assets generate enough to sustain your lifestyle</div></div>\n    </div>\n    <div class=\"milestone-item\" onclick=\"toggleMilestone(this)\">\n      <div class=\"milestone-check\">✓</div>\n      <div class=\"milestone-info\"><div class=\"ms-title\">Make Your First Impact</div><div class=\"ms-desc\">Use wealth for a cause beyond yourself</div></div>\n    </div>\n    <div class=\"milestone-item\" onclick=\"toggleMilestone(this)\">\n      <div class=\"milestone-check\">✓</div>\n      <div class=\"milestone-info\"><div class=\"ms-title\">Build Legacy Systems</div><div class=\"ms-desc\">Wealth-generating systems that run without you</div></div>\n    </div>\n    <div class=\"milestone-item\" onclick=\"toggleMilestone(this)\">\n      <div class=\"milestone-check\">✓</div>\n      <div class=\"milestone-info\"><div class=\"ms-title\">Live in Full Abundance</div><div class=\"ms-desc\">Complete alignment with purpose and infinite flow</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- Personalized Pathway Generator -->\n<section>\n  <div class=\"reveal\">\n    <div class=\"section-label\">🛠 Custom Blueprint</div>\n    <h2 class=\"section-title\">Personalized Pathway Generator</h2>\n    <p class=\"section-subtitle\">Combine your Wealth DNA type and current spectrum stage to generate your custom action plan.</p>\n  </div>\n  <div class=\"generator-container reveal\">\n    <label style=\"font-size:0.85rem;font-weight:600;color:var(--text);margin-bottom:0.3rem;display:block\">Your Wealth DNA Type</label>\n    <select id=\"genDna\">\n      <option value=\"dynamo\">Dynamo — The Creator</option>\n      <option value=\"blaze\">Blaze — The Star</option>\n      <option value=\"tempo\">Tempo — The Supporter</option>\n      <option value=\"steel\">Steel — The Dealer</option>\n    </select>\n    <label style=\"font-size:0.85rem;font-weight:600;color:var(--text);margin-bottom:0.3rem;display:block\">Your Current Spectrum Stage</label>\n    <select id=\"genStage\">\n      <option value=\"-1\">-1: Survival</option>\n      <option value=\"0\">0: Stability</option>\n      <option value=\"1\">1: Success</option>\n      <option value=\"2\">2: Security</option>\n      <option value=\"3\">3: Significance</option>\n      <option value=\"4\">4: Succession</option>\n      <option value=\"5\">5: Serenity</option>\n      <option value=\"6\">6: Simplicity</option>\n      <option value=\"7\">7: Abundance</option>\n    </select>\n    <button class=\"quiz-btn submit\" onclick=\"generatePathway()\" style=\"width:100%;margin-top:0.5rem\">⚡ Generate My Pathway</button>\n    <div class=\"generator-output\" id=\"genOutput\"></div>\n  </div>\n</section>\n\n<!-- Principles -->\n<section>\n  <div class=\"reveal\">\n    <div class=\"section-label\">📖 Core Wisdom</div>\n    <h2 class=\"section-title\">Key Principles &amp; Mindset Shifts</h2>\n    <p class=\"section-subtitle\">The foundational beliefs that separate the wealthy from the rest.</p>\n  </div>\n\n  <div class=\"principles-grid\">\n    <div class=\"principle-card reveal reveal-delay-1\">\n      <span class=\"p-num\">01</span>\n      <div class=\"p-content\"><h4>Wealth is a Journey, Not a Destination</h4><p>Your net worth is a reflection of your journey through the Wealth Spectrum. Focus on progress, not perfection, and celebrate each stage.</p></div>\n    </div>\n    <div class=\"principle-card reveal reveal-delay-2\">\n      <span class=\"p-num\">02</span>\n      <div class=\"p-content\"><h4>Play to Your Strengths</h4><p>Your Wealth DNA is your natural superpower. Stop trying to fit someone else's model. Build wealth the way that's natural to you.</p></div>\n    </div>\n    <div class=\"principle-card reveal reveal-delay-3\">\n      <span class=\"p-num\">03</span>\n      <div class=\"p-content\"><h4>Your Network is Your Net Worth</h4><p>The people around you determine your ceiling. Surround yourself with those who are where you want to be, and your path will accelerate.</p></div>\n    </div>\n    <div class=\"principle-card reveal reveal-delay-1\">\n      <span class=\"p-num\">04</span>\n      <div class=\"p-content\"><h4>Income is Not Wealth</h4><p>High income without systems and assets is just high spending. Real wealth is what you keep and what works for you while you sleep.</p></div>\n    </div>\n    <div class=\"principle-card reveal reveal-delay-2\">\n      <span class=\"p-num\">05</span>\n      <div class=\"p-content\"><h4>Purpose Fuels Prosperity</h4><p>Wealth without meaning is hollow. The most successful people build wealth in service of a larger mission, which attracts more abundance.</p></div>\n    </div>\n    <div class=\"principle-card reveal reveal-delay-3\">\n      <span class=\"p-num\">06</span>\n      <div class=\"p-content\"><h4>Systems Scale, You Don't</h4><p>To move from Success to Security and beyond, you must build systems that generate wealth independently of your personal effort.</p></div>\n    </div>\n    <div class=\"principle-card reveal reveal-delay-1\">\n      <span class=\"p-num\">07</span>\n      <div class=\"p-content\"><h4>Abundance is a Mindset</h4><p>Scarcity thinking constrains your wealth. Shift to abundance — there is enough for everyone. Your success doesn't diminish others.</p></div>\n    </div>\n    <div class=\"principle-card reveal reveal-delay-2\">\n      <span class=\"p-num\">08</span>\n      <div class=\"p-content\"><h4>Significance Follows Success</h4><p>You can't give what you don't have. Build your foundation first, then use your wealth to create impact. The order matters.</p></div>\n    </div>\n    <div class=\"principle-card reveal reveal-delay-3\">\n      <span class=\"p-num\">09</span>\n      <div class=\"p-content\"><h4>Wealth Flows in Cycles</h4><p>Like nature, wealth moves in seasons. Understand the cycles of accumulation, preservation, and distribution to navigate them wisely.</p></div>\n    </div>\n    <div class=\"principle-card reveal reveal-delay-1\">\n      <span class=\"p-num\">10</span>\n      <div class=\"p-content\"><h4>Your Legacy is Your Masterpiece</h4><p>The ultimate measure of wealth is what you leave behind — not just money, but the lives you've touched and the systems you've built.</p></div>\n    </div>\n  </div>\n</section>\n\n<!-- Quotes -->\n<section>\n  <div class=\"reveal\">\n    <div class=\"section-label\">❝ Wisdom</div>\n    <h2 class=\"section-title\">Words to Live By</h2>\n    <p class=\"section-subtitle\">Timeless insights from The Millionaire Master Plan.</p>\n  </div>\n\n  <div class=\"quotes-grid\">\n    <div class=\"quote-card reveal reveal-delay-1\"><blockquote>The only way to move from one stage of the Wealth Spectrum to the next is to change who you are being, not just what you are doing.</blockquote><div class=\"attribution\">— Roger James Hamilton</div></div>\n    <div class=\"quote-card reveal reveal-delay-2\"><blockquote>Your Wealth DNA is your natural genius. When you work against it, you struggle. When you work with it, you soar.</blockquote><div class=\"attribution\">— Roger James Hamilton</div></div>\n    <div class=\"quote-card reveal reveal-delay-3\"><blockquote>Wealth is not about having more. It's about being more, loving more, and contributing more to the world.</blockquote><div class=\"attribution\">— Roger James Hamilton</div></div>\n    <div class=\"quote-card reveal reveal-delay-1\"><blockquote>Significance is the natural destination of success. The question isn't whether you will matter, but how soon you will start.</blockquote><div class=\"attribution\">— Roger James Hamilton</div></div>\n    <div class=\"quote-card reveal reveal-delay-2\"><blockquote>Stop chasing money. Start chasing your purpose. Money will chase you.</blockquote><div class=\"attribution\">— Roger James Hamilton</div></div>\n    <div class=\"quote-card reveal reveal-delay-3\"><blockquote>The Wealth Spectrum isn't a ladder to climb. It's a journey of becoming. Each stage transforms who you are.</blockquote><div class=\"attribution\">— Roger James Hamilton</div></div>\n  </div>\n</section>\n\n<!-- Footer -->\n\n\n</div>\n\n<script>\n// ========== Theme ==========\nfunction toggleTheme() {\n  const html = document.documentElement;\n  const current = html.getAttribute('data-theme');\n  html.setAttribute('data-theme', current === 'dark' ? 'light' : 'dark');\n}\nconst savedTheme = localStorage.getItem('theme');\nif (savedTheme) document.documentElement.setAttribute('data-theme', savedTheme);\ndocument.querySelector('.theme-toggle')?.addEventListener('click', () => {\n  const t = document.documentElement.getAttribute('data-theme');\n  localStorage.setItem('theme', t);\n});\n\n// ========== Animated Background ==========\n(function() {\n  const canvas = document.getElementById('particles-canvas');\n  if (!canvas) return;\n  const ctx = canvas.getContext('2d');\n  let w, h, symbols = [], mouseX = -9999, mouseY = -9999;\n\n  function resize() {\n    w = canvas.width = window.innerWidth;\n    h = canvas.height = window.innerHeight;\n  }\n  window.addEventListener('resize', resize);\n  resize();\n\n  const wealthSymbols = ['\\u25C6', '\\u2605', '\\u2666', '\\u00A5', '\\u20AC', '\\u2606', '\\u25C8', '\\u2726', '\\u263F', '\\u262F'];\n  const count = 30;\n\n  for (let i = 0; i < count; i++) {\n    symbols.push({\n      x: Math.random() * w,\n      y: Math.random() * h,\n      size: 12 + Math.random() * 28,\n      symbol: wealthSymbols[Math.floor(Math.random() * wealthSymbols.length)],\n      speedX: (Math.random() - 0.5) * 0.4,\n      speedY: (Math.random() - 0.5) * 0.4,\n      opacity: 0.04 + Math.random() * 0.08,\n      rotation: Math.random() * Math.PI * 2,\n      rotSpeed: (Math.random() - 0.5) * 0.008,\n    });\n  }\n\n  document.addEventListener('mousemove', e => { mouseX = e.clientX; mouseY = e.clientY; });\n\n  function draw() {\n    ctx.clearRect(0, 0, w, h);\n    const isLight = document.documentElement.getAttribute('data-theme') === 'light';\n    const baseColor = isLight ? '0,0,0' : '212,175,55';\n\n    for (const s of symbols) {\n      s.x += s.speedX;\n      s.y += s.speedY;\n      s.rotation += s.rotSpeed;\n      if (s.x > w + 50) s.x = -50;\n      if (s.x < -50) s.x = w + 50;\n      if (s.y > h + 50) s.y = -50;\n      if (s.y < -50) s.y = h + 50;\n\n      const dx = s.x - mouseX, dy = s.y - mouseY;\n      const dist = Math.sqrt(dx * dx + dy * dy);\n      let opacity = s.opacity;\n      if (dist < 200) opacity += (1 - dist / 200) * 0.08;\n\n      ctx.save();\n      ctx.translate(s.x, s.y);\n      ctx.rotate(s.rotation);\n      ctx.font = `${s.size}px \"Inter\", sans-serif`;\n      ctx.textAlign = 'center';\n      ctx.textBaseline = 'middle';\n      ctx.fillStyle = `rgba(${baseColor},${Math.min(opacity, 0.15)})`;\n      ctx.fillText(s.symbol, 0, 0);\n      ctx.restore();\n    }\n    requestAnimationFrame(draw);\n  }\n  draw();\n})();\n\n// ========== Scroll Reveal ==========\nconst revealObserver = new IntersectionObserver((entries) => {\n  entries.forEach(e => {\n    if (e.isIntersecting) {\n      e.target.classList.add('visible');\n      revealObserver.unobserve(e.target);\n    }\n  });\n}, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });\n\ndocument.querySelectorAll('.reveal').forEach(el => revealObserver.observe(el));\n\n// ========== Spectrum Thermometer ==========\n(function() {\n  const stages = document.querySelectorAll('.spectrum-stage');\n  const fill = document.getElementById('thermometerFill');\n  if (!fill || !stages.length) return;\n\n  function updateThermometer() {\n    let currentIndex = 0;\n    stages.forEach((s, i) => {\n      if (s.classList.contains('active')) currentIndex = i + 1;\n    });\n    const pct = (currentIndex / stages.length) * 100;\n    fill.style.width = pct + '%';\n  }\n\n  window.updateThermometer = updateThermometer;\n  // Set initial\n  setTimeout(updateThermometer, 500);\n})();\n\n// ========== Spectrum Stage Toggle ==========\nfunction toggleStage(el) {\n  el.classList.toggle('expanded');\n  el.classList.add('active');\n  const allStages = document.querySelectorAll('.spectrum-stage');\n  allStages.forEach(s => { if (s !== el) s.classList.remove('active'); });\n  if (typeof updateThermometer === 'function') updateThermometer();\n}\n\n// ========== DNA Card Selection ==========\nfunction selectDna(el) {\n  document.querySelectorAll('.dna-card').forEach(c => c.classList.remove('selected'));\n  el.classList.add('selected');\n}\n\n// ========== Milestone Tracker ==========\nfunction toggleMilestone(el) {\n  el.classList.toggle('completed');\n}\n\n// ========== Quiz ==========\nconst quizQuestions = [\n  {\n    q: 'When starting a new project, what excites you most?',\n    options: [\n      { text: 'The bold vision and creative possibilities', type: 'dynamo' },\n      { text: 'The chance to inspire and rally people', type: 'blaze' },\n      { text: 'Building meaningful relationships through it', type: 'tempo' },\n      { text: 'The strategy and systems to make it work', type: 'steel' },\n    ]\n  },\n  {\n    q: 'How do you prefer to solve problems?',\n    options: [\n      { text: 'Invent something new and original', type: 'dynamo' },\n      { text: 'Collaborate and talk it through with others', type: 'blaze' },\n      { text: 'Rely on trusted relationships and past experience', type: 'tempo' },\n      { text: 'Analyze data and optimize the process', type: 'steel' },\n    ]\n  },\n  {\n    q: 'What describes your ideal work environment?',\n    options: [\n      { text: 'Fast-paced, dynamic, and full of possibilities', type: 'dynamo' },\n      { text: 'Energetic, social, and collaborative', type: 'blaze' },\n      { text: 'Harmonious, supportive, and stable', type: 'tempo' },\n      { text: 'Structured, efficient, and organized', type: 'steel' },\n    ]\n  },\n  {\n    q: 'What is your greatest strength?',\n    options: [\n      { text: 'Turning ideas into reality', type: 'dynamo' },\n      { text: 'Connecting and inspiring people', type: 'blaze' },\n      { text: 'Building deep trust and loyalty', type: 'tempo' },\n      { text: 'Creating efficient systems and strategies', type: 'steel' },\n    ]\n  },\n];\n\nlet quizIndex = 0;\nlet quizAnswers = {};\n\nconst quizContent = document.getElementById('quizContent');\nconst quizNav = document.getElementById('quizNav');\nconst quizProgress = document.getElementById('quizProgress');\n\nfunction renderQuiz() {\n  if (!quizContent || !quizNav || !quizProgress) return;\n\n  // Progress dots\n  quizProgress.innerHTML = quizQuestions.map((_, i) =>\n    `<span class=\"dot ${i < quizIndex ? 'done' : ''} ${i === quizIndex ? 'active' : ''}\"></span>`\n  ).join('');\n\n  const q = quizQuestions[quizIndex];\n  quizContent.innerHTML = `\n    <div class=\"quiz-question\">${q.q}</div>\n    <div class=\"quiz-options\">\n      ${q.options.map((opt, i) => {\n        const selected = quizAnswers[quizIndex] === i ? 'selected' : '';\n        return `<div class=\"quiz-option ${selected}\" data-index=\"${i}\" onclick=\"selectQuizOption(this, ${i})\"><span class=\"radio\"></span>${opt.text}</div>`;\n      }).join('')}\n    </div>\n  `;\n\n  const isLast = quizIndex === quizQuestions.length - 1;\n  const isFirst = quizIndex === 0;\n  const hasAnswer = quizAnswers[quizIndex] !== undefined;\n\n  let navHtml = '';\n  if (isFirst) {\n    navHtml += '<div></div>';\n  } else {\n    navHtml += `<button class=\"quiz-btn prev\" onclick=\"prevQuiz()\">&#8592; Back</button>`;\n  }\n\n  if (isLast) {\n    navHtml += `<button class=\"quiz-btn submit\" onclick=\"submitQuiz()\" ${!hasAnswer ? 'disabled' : ''}>See My Result &#8594;</button>`;\n  } else {\n    navHtml += `<button class=\"quiz-btn next\" onclick=\"nextQuiz()\" ${!hasAnswer ? 'disabled' : ''}>Next &#8594;</button>`;\n  }\n  quizNav.innerHTML = navHtml;\n\n  // Disable styling for disabled buttons\n  quizNav.querySelectorAll('button[disabled]').forEach(b => {\n    b.style.opacity = '0.4';\n    b.style.cursor = 'not-allowed';\n  });\n}\n\nfunction selectQuizOption(el, idx) {\n  document.querySelectorAll('.quiz-option').forEach(o => o.classList.remove('selected'));\n  el.classList.add('selected');\n  quizAnswers[quizIndex] = idx;\n  renderQuiz();\n}\n\nfunction nextQuiz() {\n  if (quizAnswers[quizIndex] === undefined) return;\n  if (quizIndex < quizQuestions.length - 1) {\n    quizIndex++;\n    renderQuiz();\n  }\n}\n\nfunction prevQuiz() {\n  if (quizIndex > 0) {\n    quizIndex--;\n    renderQuiz();\n  }\n}\n\nfunction submitQuiz() {\n  const counts = { dynamo: 0, blaze: 0, tempo: 0, steel: 0 };\n  for (let i = 0; i < quizQuestions.length; i++) {\n    const ansIdx = quizAnswers[i];\n    if (ansIdx !== undefined) {\n      const type = quizQuestions[i].options[ansIdx].type;\n      counts[type]++;\n    }\n  }\n\n  let resultType = 'dynamo';\n  let maxCount = 0;\n  for (const [type, count] of Object.entries(counts)) {\n    if (count > maxCount) { maxCount = count; resultType = type; }\n  }\n\n  const resultData = {\n    dynamo: { name: 'Dynamo', subtype: 'The Creator', emoji: '&#9889;', desc: 'You are a natural visionary and innovator. Your wealth path lies in creating new value — products, services, and ventures that didn\\'t exist before. Embrace your bold ideas and bring them to life.', traits: ['Visionary', 'Innovator', 'Risk-Taker', 'Leader'] },\n    blaze: { name: 'Blaze', subtype: 'The Star', emoji: '&#127775;', desc: 'You are a charismatic influencer and connector. Your wealth path lies in inspiring others, building your personal brand, and leveraging your network. Your presence is your power.', traits: ['Charismatic', 'Influencer', 'Connector', 'Communicator'] },\n    tempo: { name: 'Tempo', subtype: 'The Supporter', emoji: '&#128154;', desc: 'You are a nurturing relationship-builder. Your wealth path lies in trust, service, and long-term partnerships. People are drawn to your reliability and genuine care.', traits: ['Nurturer', 'Loyal', 'Empathetic', 'Steadfast'] },\n    steel: { name: 'Steel', subtype: 'The Dealer', emoji: '&#9878;', desc: 'You are a strategic analyst and system-builder. Your wealth path lies in mastering the mechanics of money — optimization, efficiency, and scalable systems.', traits: ['Analytical', 'Strategic', 'Disciplined', 'Precise'] },\n  };\n\n  const r = resultData[resultType];\n  quizContent.innerHTML = `\n    <div class=\"quiz-result\">\n      <div style=\"font-size:3rem;margin-bottom:0.5rem\">${r.emoji}</div>\n      <div class=\"result-type\">${r.name}</div>\n      <div style=\"font-size:1rem;font-weight:600;color:var(--gold);margin-bottom:1rem;letter-spacing:2px;text-transform:uppercase\">${r.subtype}</div>\n      <div class=\"result-desc\">${r.desc}</div>\n      <div class=\"result-traits\">${r.traits.map(t => `<span>${t}</span>`).join('')}</div>\n      <button class=\"quiz-btn submit\" onclick=\"resetQuiz()\" style=\"margin-top:0.5rem\">Take Again</button>\n    </div>\n  `;\n  quizNav.innerHTML = '';\n  quizProgress.innerHTML = '';\n}\n\nfunction resetQuiz() {\n  quizIndex = 0;\n  quizAnswers = {};\n  renderQuiz();\n}\n\n// Init quiz\nrenderQuiz();\n\n// ========== Pathway Generator ==========\nconst pathwayData = {\n  dynamo: {\n    '-1': { focus: 'Focus: Turn one bold idea into a micro-venture. Start small, sell fast, and build momentum. Your creativity is your escape route from survival.', next: 'Aim for Stage 0: Stability by generating consistent small wins.' },\n    '0': { focus: 'Focus: Develop a scalable product or service. Move from trading time for money to selling a repeatable solution.', next: 'Aim for Stage 1: Success by building a proven offer.' },\n    '1': { focus: 'Focus: Systemize your innovation. Document your process, build a team, and create intellectual property that multiplies your value.', next: 'Aim for Stage 2: Security by creating assets that work without you.' },\n    '2': { focus: 'Focus: Launch a portfolio of ventures. Use your security to fund new ideas and acquire complementary businesses.', next: 'Aim for Stage 3: Significance by investing in ventures with purpose.' },\n    '3': { focus: 'Focus: Mentor other creators and invest in innovation ecosystems. Your greatest legacy is the next generation of builders.', next: 'Aim for Stage 4: Succession by creating self-sustaining innovation engines.' },\n    '4': { focus: 'Focus: Step back from creation into curation. Let your systems run while you focus on high-level vision and philanthropy.', next: 'Aim for Stage 5: Serenity through complete system delegation.' },\n    '5': { focus: 'Focus: Create purely for joy, not necessity. Your wealth flows from inspired ideas that you bring to life for the beauty of it.', next: 'Aim for Stage 6: Simplicity by stripping away what no longer serves.' },\n    '6': { focus: 'Focus: Live in pure creative expression. Your work is your art, and your wealth is the natural byproduct of alignment.', next: 'Aim for Stage 7: Abundance where wealth circulates freely.' },\n    '7': { focus: 'Focus: You are a master creator. Continue innovating and channel wealth back into the world to uplift others.', next: 'You embody Abundance. Your journey inspires all.' },\n  },\n  blaze: {\n    '-1': { focus: 'Focus: Build your personal brand. Share your story and expertise freely. Your network and voice are your way out of scarcity.', next: 'Aim for Stage 0: Stability by growing your influence into income.' },\n    '0': { focus: 'Focus: Monetize your influence. Create content, speak, coach, or consult. Convert your growing audience into paying clients.', next: 'Aim for Stage 1: Success by establishing yourself as a go-to authority.' },\n    '1': { focus: 'Focus: Build a platform and community. Move from being the talent to being the producer who amplifies others.', next: 'Aim for Stage 2: Security by creating media and community assets.' },\n    '2': { focus: 'Focus: Launch a talent empire. Represent other stars, build a media company, or create a platform that showcases voices.', next: 'Aim for Stage 3: Significance using your influence for social impact.' },\n    '3': { focus: 'Focus: Champion causes and amplify marginalized voices. Your platform becomes a force for meaningful change.', next: 'Aim for Stage 4: Succession by building institutions that outlast you.' },\n    '4': { focus: 'Focus: Step into the background as an elder statesperson. Let your platform run through others while you guide from wisdom.', next: 'Aim for Stage 5: Serenity through detachment from the spotlight.' },\n    '5': { focus: 'Focus: Connect deeply with a small circle. Your peace comes from quality over quantity in relationships and influence.', next: 'Aim for Stage 6: Simplicity by letting go of performative aspects.' },\n    '6': { focus: 'Focus: Be authentically yourself without audience expectations. Your influence flows naturally without effort.', next: 'Aim for Stage 7: Abundance where your presence alone creates value.' },\n    '7': { focus: 'Focus: Radiate pure inspiration. Your life is the message, and your abundance inspires countless others to find their voice.', next: 'You embody Abundance. Your light guides the way.' },\n  },\n  tempo: {\n    '-1': { focus: 'Focus: Identify one person you can serve deeply. Offer your support and build trust. Your relationships are your foundation out of survival.', next: 'Aim for Stage 0: Stability by turning service into steady income.' },\n    '0': { focus: 'Focus: Build a referral-based business. Delight your clients so completely that they become your sales team. Your reputation is your asset.', next: 'Aim for Stage 1: Success through exceptional service delivery.' },\n    '1': { focus: 'Focus: Create a client experience system. Document your service process and train others to deliver it. Your care scales through systems.', next: 'Aim for Stage 2: Security by building a service organization.' },\n    '2': { focus: 'Focus: Expand through partnerships and JVs. Your strength is trust — leverage it to create win-win ventures with aligned partners.', next: 'Aim for Stage 3: Significance by serving communities at scale.' },\n    '3': { focus: 'Focus: Build a foundation or community program. Your wealth enables you to care for causes and people you believe in.', next: 'Aim for Stage 4: Succession by creating care-focused institutions.' },\n    '4': { focus: 'Focus: Step into an advisory role. Guide the next generation of supporters while your organization runs on relationship-centered systems.', next: 'Aim for Stage 5: Serenity through the peace of a thriving community.' },\n    '5': { focus: 'Focus: Nurture your inner circle. Your serenity comes from deep, authentic connections with those who matter most.', next: 'Aim for Stage 6: Simplicity by focusing only on relationships that nourish.' },\n    '6': { focus: 'Focus: Love without agenda. Your support flows freely because you can, not because you need to. Pure generosity.', next: 'Aim for Stage 7: Abundance where your care creates infinite ripples.' },\n    '7': { focus: 'Focus: Be a beacon of unconditional support. Your abundance enables you to uplift everyone you touch with no expectation of return.', next: 'You embody Abundance. Your love transforms the world.' },\n  },\n  steel: {\n    '-1': { focus: 'Focus: Track every penny and create a strict budget. Your analytical mind can find efficiencies others miss. Use data to escape survival.', next: 'Aim for Stage 0: Stability by creating a reliable financial system.' },\n    '0': { focus: 'Focus: Build automated savings and investment systems. Optimize your income-to-wealth conversion with precision.', next: 'Aim for Stage 1: Success by hitting your first savings milestones.' },\n    '1': { focus: 'Focus: Create arbitrage and optimization engines. Find gaps in markets, streamline operations, and build efficiency-driven businesses.', next: 'Aim for Stage 2: Security through diversified, optimized asset portfolios.' },\n    '2': { focus: 'Focus: Build a portfolio of systematic investments. Real estate, index funds, automated businesses — let systems compound your wealth.', next: 'Aim for Stage 3: Significance by funding strategic philanthropic initiatives.' },\n    '3': { focus: 'Focus: Apply your analytical skills to impact investing. Optimize charitable giving for maximum social ROI.', next: 'Aim for Stage 4: Succession by creating self-managing investment trusts.' },\n    '4': { focus: 'Focus: Manage and optimize your legacy systems. Your role shifts from building to fine-tuning the wealth engines you created.', next: 'Aim for Stage 5: Serenity through complete system independence.' },\n    '5': { focus: 'Focus: Enjoy the view. Your systems run perfectly. Engage in strategic thinking and high-level allocation decisions.', next: 'Aim for Stage 6: Simplicity by eliminating unnecessary complexity.' },\n    '6': { focus: 'Focus: Pursue intellectual challenges for their own sake. Your wealth allows you to solve problems simply because they interest you.', next: 'Aim for Stage 7: Abundance where wisdom flows as freely as wealth.' },\n    '7': { focus: 'Focus: Be the master strategist and sage. Your understanding of systems and wealth mechanics serves the highest good.', next: 'You embody Abundance. Your precision is pure art.' },\n  },\n};\n\nfunction generatePathway() {\n  const dna = document.getElementById('genDna').value;\n  const stage = document.getElementById('genStage').value;\n  const output = document.getElementById('genOutput');\n\n  const data = pathwayData[dna]?.[stage];\n  if (!data) {\n    output.innerHTML = '<strong>Pathway generating...</strong><br>Combining your DNA and current stage to build your custom plan.';\n  } else {\n    const dnaNames = { dynamo: 'Dynamo (Creator)', blaze: 'Blaze (Star)', tempo: 'Tempo (Supporter)', steel: 'Steel (Dealer)' };\n    output.innerHTML = `<strong>&#9889; Your Custom Pathway</strong><br><br>\n    <strong>DNA Type:</strong> ${dnaNames[dna]}<br>\n    <strong>Current Stage:</strong> ${stage}: ${document.querySelector('#genStage option[value=\"'+stage+'\"]')?.textContent || ''}<br><br>\n    <strong>&#9654; ${data.focus}</strong><br><br>\n    <strong>&#9650; Next Step:</strong> ${data.next}`;\n    output.classList.add('show');\n  }\n}\n\n// ========== Thermometer on spectrum scroll ==========\nconst spectrumObserver = new IntersectionObserver((entries) => {\n  entries.forEach(e => {\n    if (e.isIntersecting && typeof updateThermometer === 'function') updateThermometer();\n  });\n}, { threshold: 0.3 });\nconst spectrumEl = document.getElementById('spectrumLadder');\nif (spectrumEl) spectrumObserver.observe(spectrumEl);\n\n</script>\n\n\n</body>\n</html>",
  "the-prince": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div id=\"progress\"></div>\n<div id=\"ornaments\"></div>\n<div id=\"noise\"></div>\n\n\n\n\n\n\n\n<!-- STATS -->\n<section>\n  <div class=\"container\">\n    <div class=\"stats-grid\">\n      <div class=\"stat\"><div class=\"stat-value\">26</div><div class=\"stat-label\">Chapters</div></div>\n      <div class=\"stat\"><div class=\"stat-value\">1</div><div class=\"stat-label\">Dedicatee — Medici</div></div>\n      <div class=\"stat\"><div class=\"stat-value\">3</div><div class=\"stat-label\">Types of Principalities</div></div>\n      <div class=\"stat\"><div class=\"stat-value\">2</div><div class=\"stat-label\">Arms: Own vs. Mercenary</div></div>\n      <div class=\"stat\"><div class=\"stat-value\">∞</div><div class=\"stat-label\">Enduring Relevance</div></div>\n    </div>\n  </div>\n</section>\n\n<!-- CORE THEMES -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg></div>\n      <div class=\"section-label\">The Pillars</div>\n      <h2>Core <span class=\"hl\">Themes</span></h2>\n      <p class=\"section-desc\" style=\"margin:0.5rem auto 0;\">The foundational ideas that underpin Machiavelli's philosophy of power.</p>\n    </div>\n    <div class=\"theme-cards\">\n      <div class=\"theme-card\">\n        <span class=\"tc-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><rect x=\"3\" y=\"3\" width=\"18\" height=\"18\" rx=\"2\" ry=\"2\"></rect><line x1=\"3\" y1=\"9\" x2=\"21\" y2=\"9\"></line><line x1=\"9\" y1=\"21\" x2=\"9\" y2=\"9\"></line></svg></span>\n        <h4>Fortune vs. <span class=\"hl\">Virtù</span></h4>\n        <p>Fortune controls half our actions, but the other half is within our power. A prince with <em>virtù</em> — skill, strength, and decisive will — can shape his destiny. Fortune favors the bold, the impetuous, the one who adapts to the times.</p>\n      </div>\n      <div class=\"theme-card\">\n        <span class=\"tc-icon\">🦁</span>\n        <h4>The Lion and <span class=\"hl\">the Fox</span></h4>\n        <p>A prince must be both beast and man. The lion defends against wolves; the fox recognizes traps. Strength without cunning is insufficient; cunning without strength is vulnerable. To rule is to master both natures.</p>\n      </div>\n      <div class=\"theme-card\">\n        <span class=\"tc-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2v20\"></path><path d=\"M8 22h8\"></path><path d=\"M2 6c.6.5 1.2 1 2.5 1C7 7 7 5 9.5 5c2.6 0 2.4 2 5 2 2.5 0 2.5-2 5-2 1.3 0 1.9.5 2.5 1\"></path></svg>️</span>\n        <h4>The Ends <span class=\"hl\">Justify the Means</span></h4>\n        <p>In matters of state, the ruler must sometimes act immorally for the greater good. The welfare of the people and the stability of the state justify harsh actions. A prince who tries to be good at all times will be destroyed among so many who are not.</p>\n      </div>\n      <div class=\"theme-card\">\n        <span class=\"tc-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z\"></path></svg>️</span>\n        <h4>Feared vs. <span class=\"hl\">Loved</span></h4>\n        <p>If a prince cannot be both loved and feared, it is far safer to be feared. Love is held by a thread of obligation, easily broken. Fear is sustained by the dread of punishment, which never fails. But a prince must avoid being hated.</p>\n      </div>\n      <div class=\"theme-card\">\n        <span class=\"tc-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.5 2h-5L7 8h10l-2.5-6z\"></path><path d=\"M7 8v11a3 3 0 0 0 3 3h4a3 3 0 0 0 3-3V8\"></path></svg>️</span>\n        <h4>Arms &amp; <span class=\"hl\">the Law</span></h4>\n        <p>Good laws and good arms — these are the foundations of every state. A prince must master the art of war above all else. One's own arms are the only reliable defense; mercenaries and auxiliaries are useless and dangerous.</p>\n      </div>\n      <div class=\"theme-card\">\n        <span class=\"tc-icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"></path><circle cx=\"12\" cy=\"12\" r=\"3\"></circle></svg>️</span>\n        <h4>Appearance <span class=\"hl\">vs. Reality</span></h4>\n        <p>A prince should appear merciful, faithful, humane, religious, and upright — but must be ready to act otherwise when necessary. The common people judge by what they see and hear. The appearance of virtue matters more than virtue itself.</p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- KEY CHAPTERS -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg></div>\n      <div class=\"section-label\">The Text</div>\n      <h2>Key <span class=\"hl\">Chapters</span></h2>\n      <p class=\"section-desc\" style=\"margin:0.5rem auto 0;\">The essential chapters of <em>The Prince</em>, organized by theme — tap to expand.</p>\n    </div>\n    <div class=\"chapters-bar\" id=\"chapterTabs\">\n      <button class=\"ch-tab active\" data-ch=\"all\">All</button>\n      <button class=\"ch-tab\" data-ch=\"principalities\">Principalities</button>\n      <button class=\"ch-tab\" data-ch=\"arms\">Arms &amp; War</button>\n      <button class=\"ch-tab\" data-ch=\"qualities\">Qualities of a Prince</button>\n      <button class=\"ch-tab\" data-ch=\"fortune\">Fortune &amp; Virtù</button>\n    </div>\n    <div class=\"ch-grid\" id=\"chapterGrid\"></div>\n  </div>\n</section>\n\n<!-- THE PRINCE'S TOOLKIT -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg></div>\n      <div class=\"section-label\">Principles of Power</div>\n      <h2>The Prince's <span class=\"hl\">Toolkit</span></h2>\n      <p class=\"section-desc\" style=\"margin:0.5rem auto 0;\">Machiavelli's strategic principles — click each card to reveal deeper wisdom.</p>\n    </div>\n    <div class=\"grid-2\" id=\"toolkitGrid\"></div>\n  </div>\n</section>\n\n<!-- GOOD VS EVIL -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg></div>\n      <div class=\"section-label\">The Dilemma</div>\n      <h2>Good Prince vs. <span class=\"hl\">Effective Prince</span></h2>\n      <p class=\"section-desc\" style=\"margin:0.5rem auto 0;\">Machiavelli's most controversial insight — the tension between moral virtue and effective rule.</p>\n    </div>\n    <div class=\"good-evil\">\n      <div class=\"ge-side ge-good\">\n        <div class=\"ge-label\">The Good Prince</div>\n        <h3>Virtue · Morality · Honor</h3>\n        <ul>\n          <li>Keeps all promises and oaths</li>\n          <li>Rules with mercy and compassion</li>\n          <li>Gives generously to all</li>\n          <li>Fights openly and honorably</li>\n          <li>Remains faithful to allies</li>\n          <li>Acts only within moral bounds</li>\n          <li>Seeks to be loved by all</li>\n        </ul>\n      </div>\n      <div class=\"ge-divider\">vs.</div>\n      <div class=\"ge-side ge-evil\">\n        <div class=\"ge-label\">The Effective Prince</div>\n        <h3>Power · Pragmatism · Statecraft</h3>\n        <ul>\n          <li>Breaks promises when convenient</li>\n          <li>Uses cruelty decisively when needed</li>\n          <li>Practices parsimony to avoid taxing subjects</li>\n          <li>Employs deception and cunning</li>\n          <li>Shifts alliances as circumstances demand</li>\n          <li>Enters evil knowingly when necessary</li>\n          <li>Prefers to be feared rather than loved</li>\n        </ul>\n      </div>\n    </div>\n    <p style=\"font-size:0.85rem;color:var(--text-dim);text-align:center;font-style:italic;margin-top:1rem;\">\"A prince who wants to maintain his position cannot always be good, for to preserve his state he must often act against faith, charity, humanity, and religion.\" — <em>The Prince, Ch. 18</em></p>\n  </div>\n</section>\n\n<!-- QUALITIES OF A PRINCE -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg></div>\n      <div class=\"section-label\">Character</div>\n      <h2>The Qualities of <span class=\"hl\">a Prince</span></h2>\n      <p class=\"section-desc\" style=\"margin:0.5rem auto 0;\">Machiavelli's practical counsel on how a prince should conduct himself.</p>\n    </div>\n    <div class=\"qualities-list\" id=\"qualitiesList\"></div>\n  </div>\n</section>\n\n<!-- LEADERSHIP STYLE QUIZ -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg></div>\n      <div class=\"section-label\">Self-Assessment</div>\n      <h2>What Kind of <span class=\"hl\">Prince</span> Are You?</h2>\n      <p class=\"section-desc\" style=\"margin:0.5rem auto 0;\">How would Machiavelli classify your leadership style? Answer these five dilemmas.</p>\n    </div>\n    <div class=\"quiz-section\" id=\"quizSection\">\n      <div class=\"quiz-intro\">\n        <h3><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> The Machiavelli Test <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></h3>\n        <p>Choose the option that most closely matches your approach to leadership.</p>\n      </div>\n      <div id=\"quizQuestions\"></div>\n      <div style=\"text-align:center;\">\n        <button class=\"quiz-btn\" id=\"quizSubmit\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg> Reveal Your Ruler Type <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"></polygon></svg></button>\n      </div>\n      <div class=\"quiz-result\" id=\"quizResult\">\n        <h4>Your Ruler Archetype</h4>\n        <div class=\"qr-type\" id=\"qrType\"></div>\n        <p id=\"qrDesc\"></p>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- QUOTES -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg></div>\n      <div class=\"section-label\">Wisdom</div>\n      <h2>Notable <span class=\"hl\">Quotes</span></h2>\n      <p class=\"section-desc\" style=\"margin:0.5rem auto 0;\">The most enduring passages from Machiavelli's masterpiece.</p>\n    </div>\n    <div id=\"quotesContainer\"></div>\n  </div>\n</section>\n\n<!-- MODERN RELEVANCE -->\n<section>\n  <div class=\"container\">\n    <div class=\"section-header\">\n      <div class=\"section-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg> <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"></path></svg></div>\n      <div class=\"section-label\">Legacy</div>\n      <h2>Modern <span class=\"hl\">Relevance</span></h2>\n      <p class=\"section-desc\" style=\"margin:0.5rem auto 0;\">Why a 500-year-old political treatise still shapes how we think about power today.</p>\n    </div>\n    <div class=\"modern-grid\" id=\"modernGrid\"></div>\n  </div>\n</section>\n\n\n\n<script>\n  //  FLOATING ORNAMENTS \n  (function(){\n    const c = document.getElementById('ornaments');\n    const colors = [\n      'rgba(184,134,11,0.08)',\n      'rgba(192,64,0,0.06)',\n      'rgba(139,0,0,0.05)',\n      'rgba(232,213,183,0.04)'\n    ];\n    for (let i = 0; i < 5; i++) {\n      const o = document.createElement('div');\n      o.className = 'orn';\n      const size = 200 + Math.random() * 300;\n      o.style.cssText = `\n        width:${size}px;height:${size}px;\n        left:${Math.random()*100}%;top:${Math.random()*100}%;\n        background:${colors[i%colors.length]};\n        --d:${25+Math.random()*30}s;\n        --del:${Math.random()*10}s;\n        --mo:0.5;\n        --tx:${(Math.random()-0.5)*500}px;\n        --ty:${(Math.random()-0.5)*500}px;\n      `;\n      c.appendChild(o);\n    }\n  })();\n\n  //  SCROLL PROGRESS \n  window.addEventListener('scroll',()=>{\n    const s=window.scrollY/(document.body.scrollHeight-window.innerHeight)*100;\n    document.getElementById('progress').style.width=s+'%';\n  });\n\n  //  THEME \n  const themeToggle=document.getElementById('themeToggle');\n  themeToggle.addEventListener('click',()=>{\n    document.body.classList.toggle('light');\n    themeToggle.innerHTML=document.body.classList.contains('light')\n      ? '<svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"5\"/><path d=\"M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42\"/></svg>'\n      : '<svg width=\"20\" height=\"20\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z\"/></svg>';\n  });\n\n  //  SCROLL REVEAL \n  const observer=new IntersectionObserver((entries)=>{\n    entries.forEach(e=>{if(e.isIntersecting)e.target.classList.add('visible')});\n  },{threshold:0.08});\n\n  //  CHAPTERS DATA \n  const chapters=[\n    {n:1,title:\"Of the Various Kinds of Principalities\",cat:\"principalities\",text:\"All states and dominions that have held sway over men are either republics or principalities. Principalities are either hereditary (passed down through a ruling family) or new. New principalities are either entirely new or annexed to an existing state. They are acquired by one's own arms and virtù, by fortune and the arms of others, or by wickedness.\"},\n    {n:2,title:\"Of Hereditary Principalities\",cat:\"principalities\",text:\"Hereditary principalities are far easier to maintain than new ones. A prince of hereditary stock can keep his state with only modest effort, so long as he does not depart from the customs of his ancestors and deals with unforeseen events as they arise. The natural affection of the people for their ancient line is a powerful anchor.\"},\n    {n:3,title:\"Of Mixed Principalities\",cat:\"principalities\",text:\"Mixed principalities — those annexed to an existing state — present the greatest difficulty. The conqueror must consider: those he has injured by his conquest, the expectation of improvement among the people, the need to pacify the conquered territory. Live in the conquered territory, plant colonies, protect smaller neighbors, weaken the strong, and prevent any foreign power from entering.\"},\n    {n:4,title:\"Why the Kingdom of Darius Did Not Rebel\",cat:\"principalities\",text:\"States accustomed to living under a prince are harder to conquer but easier to hold. The memory of the prince's family fades with his death. States governed by a prince and his barons are easier to conquer through a disaffected baron but harder to hold, as the people may rally to a new leader from the old nobility.\"},\n    {n:5,title:\"How Cities or Provinces Should Be Administered\",cat:\"principalities\",text:\"Three ways to hold a state accustomed to its own laws: ruin it, go live there, or let it keep its laws under tribute with a friendly government. The safest is to ruin it. He who does not destroy a rebellious city may one day be destroyed by it. A city accustomed to freedom is harder to hold.\"},\n    {n:6,title:\"Of New Principalities Acquired by One's Own Arms and Virtù\",cat:\"principalities\",text:\"The greatest princes rise through their own virtù, not fortune. Moses, Cyrus, Romulus, Theseus — all were armed prophets who succeeded through their own ability. Difficulties in acquiring a new state are many, but once established, such princes are secure. Men who become princes through their own merit face many initial dangers but enjoy lasting security.\"},\n    {n:7,title:\"Of New Principalities Acquired by Fortune\",cat:\"principalities\",text:\"Those who rise by fortune — through bribery, favor, or inheritance — do so with little effort but must labor mightily to maintain their state. They depend on the goodwill of those who raised them, which is unreliable. A prince who rises by fortune may lack the virtù to command his own destiny. His state is built on sand.\"},\n    {n:8,title:\"Of Those Who Become Princes by Wickedness\",cat:\"principalities\",text:\"Some rise through crime and violence. Cruelty used well is inflicted at once, for necessity, and then ceased. Cruelty used badly is inflicted gradually and without end. A prince should commit all necessary cruelties at once, so he may later dispense benefits gradually. Injuries must be done all at once; benefits, one by one.\"},\n    {n:12,title:\"Of the Different Kinds of Soldiers\",cat:\"arms\",text:\"The foundation of every state is good laws and good arms. There are three types of armies: one's own, mercenaries, and auxiliaries. Mercenaries are disunited, ambitious, undisciplined, and treacherous. They will fight well enough for pay but will not die for you. Auxiliaries are even more dangerous — they are united under their own commander and can turn on you.\"},\n    {n:13,title:\"Of Auxiliary, Mixed, and Citizen Soldiers\",cat:\"arms\",text:\"Auxiliary troops — those borrowed from a foreign power — are the most dangerous. If they win, you are their prisoner. If they lose, you are ruined. A wise prince always fights with his own arms. Without one's own army, no prince is truly secure. The arms of others either fall away, burden you, or constrain you.\"},\n    {n:14,title:\"What a Prince Should Do Concerning the Art of War\",cat:\"arms\",text:\"A prince must study the art of war above all else. It is his only profession. In peacetime, he must train harder than in war. He must study history, the actions of great men, the terrain of his country. To neglect the art of war is to invite ruin. An armed prince is surrounded by armed subjects; an unarmed prince is at the mercy of his armed servants.\"},\n    {n:15,title:\"Of Things for Which Men and Princes Are Praised or Blamed\",cat:\"qualities\",text:\"A prince who wants to maintain his position cannot always do what is considered good. Many qualities for which men are praised — generosity, mercy, honesty — can ruin a prince if practiced without discretion. The prince must be willing to enter evil when necessity commands. He must understand that some virtuous qualities lead to ruin, while some vices lead to security and well-being.\"},\n    {n:16,title:\"Of Liberality and Parsimony\",cat:\"qualities\",text:\"Liberality practiced virtuously will harm you. To maintain a reputation for generosity, you must tax your people heavily, which makes you hated. Parsimony is a wiser course — it lets you live within your means, defend your state, and undertake ventures without burdening your subjects. In time, you will be considered generous by all those you do not tax.\"},\n    {n:17,title:\"Of Cruelty and Mercy\",cat:\"qualities\",text:\"A prince should desire to be considered merciful rather than cruel, but he must not misuse mercy. A prince who keeps his subjects united and loyal should not worry about the reputation for cruelty. It is far safer to be feared than loved. Love is held by a thread of obligation; fear is sustained by the dread of punishment. But a prince must never be hated.\"},\n    {n:18,title:\"How Princes Should Keep Faith\",cat:\"qualities\",text:\"A prudent prince cannot and should not keep his word when doing so would work against his interests. Men are wretched creatures who would not keep their word to you, so you need not keep yours to them. A prince must be a great feigner and dissembler. He should appear merciful, faithful, humane, religious, and upright — and be so in truth, but ready to act otherwise when needed.\"},\n    {n:19,title:\"Of Avoiding Contempt and Hatred\",cat:\"qualities\",text:\"A prince must avoid being hated and despised. He is hated for rapaciousness and for meddling with the property and women of his subjects. He is despised for being fickle, effeminate, cowardly, and irresolute. A prince should demonstrate greatness, courage, wisdom, and strength. The people judge by appearances; a prince who commands respect is safe.\"},\n    {n:22,title:\"Of the Ministers of Princes\",cat:\"qualities\",text:\"The first judgment of a ruler's intelligence comes from the men around him. If his ministers are capable and loyal, the prince is wise. If they are not, the prince is weak. A wise prince chooses shrewd ministers and keeps them loyal with honors, wealth, and responsibilities. He seeks counsel from many but gives his own judgment.\"},\n    {n:25,title:\"How Much Fortune Can Do in Human Affairs\",cat:\"fortune\",text:\"Fortune governs half our actions, but the other half is within our control. Fortune is like a river that floods its banks — it rages when unopposed, but in calm seasons, men can build dams and levees. The prince who adapts his nature to the times will succeed. Fortune favors the bold. It is better to be impetuous than cautious.\"},\n    {n:26,title:\"Exhortation to Liberate Italy\",cat:\"fortune\",text:\"Machiavelli's passionate plea: Italy, disunited and overrun by foreign powers, awaits a prince who will free her. Never was a time more favorable for a new prince. God has shown signs of deliverance. The Medici are called to take up this cause. 'Not, then, let your illustrious House reject this opportunity, that Italy may at last find her savior.'\"}\n  ];\n\n  //  RENDER CHAPTERS \n  const chapterGrid=document.getElementById('chapterGrid');\n  const chapterTabs=document.querySelectorAll('.ch-tab');\n  let activeChapterFilter='all';\n\n  function renderChapters(filter='all'){\n    chapterGrid.innerHTML='';\n    const q=filter.toLowerCase();\n    let visible=0;\n\n    chapters.forEach(ch=>{\n      const match=q==='all'||ch.cat===q;\n      if(match)visible++;\n\n      const card=document.createElement('div');\n      card.className=`ch-card${match?'':' hidden'}`;\n      card.innerHTML=`\n        <div class=\"ch-num\">Chapter ${ch.n}</div>\n        <h4>${ch.title}</h4>\n        <div class=\"ch-preview\">${ch.text.substring(0,140)}…</div>\n        <div class=\"ch-full\"><div class=\"ch-full-inner\">${ch.text}</div></div>\n        <div class=\"ch-icon\">+</div>\n      `;\n      card.addEventListener('click',()=>card.classList.toggle('open'));\n      chapterGrid.appendChild(card);\n      if(match)observer.observe(card);\n    });\n\n    requestAnimationFrame(()=>{\n      document.querySelectorAll('.ch-card:not(.hidden)').forEach((el,i)=>{\n        setTimeout(()=>el.classList.add('visible'),i*40);\n      });\n    });\n  }\n\n  renderChapters();\n\n  chapterTabs.forEach(tab=>{\n    tab.addEventListener('click',()=>{\n      chapterTabs.forEach(t=>t.classList.remove('active'));\n      tab.classList.add('active');\n      activeChapterFilter=tab.dataset.ch;\n      renderChapters(activeChapterFilter);\n    });\n  });\n\n  //  TOOLKIT \n  const toolkitData=[\n    {n:1,t:\"Master the Art of War\",p:\"A prince must have no other object than war, its organization, and its discipline. In peacetime, train harder than in war. Study terrain, history, and the actions of great commanders. The neglect of military art is the first cause of ruin.\"},\n    {n:2,t:\"Be Both Lion and Fox\",p:\"The lion cannot defend against traps; the fox cannot defend against wolves. A prince must be both — strong enough to frighten wolves, cunning enough to recognize snares. Pure strength invites traps; pure cunning invites attack.\"},\n    {n:3,t:\"Use Cruelty Well\",p:\"All necessary cruelties must be inflicted at once and then ceased. Benefits should be dispensed gradually. The prince who settles his accounts in one stroke will not need to be cruel again. Sporadic cruelty breeds perpetual hatred.\"},\n    {n:4,t:\"Never Rely on Mercenaries\",p:\"Mercenaries are disunited, ambitious, and treacherous. They fight for pay, not loyalty. In peace they rob you; in war they flee. Your own arms — citizens loyal to their prince — are the only reliable defense of any state.\"},\n    {n:5,t:\"Appear Virtuous\",p:\"The prince should appear merciful, faithful, humane, religious, and upright. The multitude judges by appearances. But he must be ready, when necessity commands, to act against every virtue. The appearance of virtue is your shield; the willingness to set it aside is your sword.\"},\n    {n:6,t:\"Secure the People's Support\",p:\"The goodwill of the people is the prince's best fortress. Fortresses and walls are useful, but nothing protects a prince like the loyalty of his subjects. A prince who has the people on his side need fear no conspiracy.\"},\n    {n:7,t:\"Eliminate Threats Early\",p:\"Emerging problems must be dealt with while they are small and manageable. Recognize trouble at its inception. A prince must treat a small fire as he would a great conflagration — extinguish it before it spreads beyond control.\"},\n    {n:8,t:\"Choose Wise Counselors\",p:\"A prince's intelligence is judged by the men around him. Choose ministers who are capable, loyal, and honest. Keep them loyal through honor, wealth, and shared responsibility. Avoid flatterers — the greatest trap of any court.\"},\n    {n:9,t:\"Keep Your Word... Strategically\",p:\"A prudent prince cannot keep his word when it harms his interests. Men are wretched; they will not keep faith with you, so you need not keep faith with them. But never break your word without just cause, and always maintain the appearance of honesty.\"},\n    {n:10,t:\"Fortify Your State\",p:\"Good laws and good arms are the foundations of every state. Fortify your territories, but remember: the strongest fortress is not being hated by your people. Internal strength and external deterrence must go hand in hand.\"}\n  ];\n\n  const toolkitGrid=document.getElementById('toolkitGrid');\n  toolkitData.forEach(item=>{\n    const card=document.createElement('div');\n    card.className='tk-card';\n    card.innerHTML=`\n      <div class=\"tk-num\">${item.n}</div>\n      <h4>${item.t}</h4>\n      <p>${item.p.substring(0,80)}…</p>\n      <div class=\"tk-full\"><div class=\"tk-full-inner\">${item.p}</div></div>\n    `;\n    card.addEventListener('click',()=>card.classList.toggle('open'));\n    toolkitGrid.appendChild(card);\n    observer.observe(card);\n  });\n\n  //  QUALITIES \n  const qualitiesData=[\n    {label:\"Liberality vs. Parsimony\",t:\"Give Sparingly, Keep Plenty\",p:\"Generosity depletes your resources and forces you to tax the people, making you hated. It is wiser to be considered miserly than to be generous at the people's expense. In time, your parsimony will be seen as liberality — for you take nothing from your subjects.\"},\n    {label:\"Cruelty vs. Mercy\",t:\"Be Feared but Not Hated\",p:\"A prince should be slow to believe accusations and slow to act. He must punish when necessary but never confiscate property without cause — men forgive the death of a father more quickly than the loss of a patrimony. Be feared, but never despised.\"},\n    {label:\"Keeping Faith\",t:\"Break Promises When Needed\",p:\"Honesty is admirable, but the prince who always keeps his word will be destroyed among the dishonest. Break your promises when the reasons for making them no longer exist. But always maintain the appearance of integrity.\"},\n    {label:\"Avoiding Contempt\",t:\"Be Decisive and Resolute\",p:\"A prince who is fickle, effeminate, cowardly, or irresolute will be despised. He must demonstrate greatness, courage, and wisdom in all his actions. His decisions should be irrevocable, so that no one will think to deceive him.\"},\n    {label:\"Choosing Ministers\",t:\"The Mirror of Your Judgment\",p:\"The quality of your ministers reflects your own intelligence. Reward honest counsel and punish flattery. Listen to advice from many sources, but make your own decisions. A prince who asks for advice from everyone will have no will of his own.\"}\n  ];\n\n  const qualitiesList=document.getElementById('qualitiesList');\n  qualitiesData.forEach((q,i)=>{\n    const el=document.createElement('div');\n    el.className='q-item';\n    el.innerHTML=`\n      <div class=\"q-label\">${q.label}</div>\n      <h4>${q.t}</h4>\n      <p>${q.p}</p>\n      <div class=\"q-mach\">— Machiavelli, The Prince</div>\n    `;\n    qualitiesList.appendChild(el);\n    observer.observe(el);\n  });\n\n  //  QUIZ \n  const quizQuestions=[\n    {\n      q:\"Your trusted ally makes a promise that would now harm your state. Do you keep your word?\",\n      opts:[\n        {v:3,t:\"Make an honorable withdrawal — find a legal or diplomatic way out that preserves your reputation\"},\n        {v:2,t:\"Keep your word reluctantly; a prince's honor is his bond\"},\n        {v:4,t:\"Break the promise without hesitation; the state's welfare trumps personal obligations\"},\n        {v:1,t:\"Delegate the decision to your ministers so you bear no direct blame\"}\n      ]\n    },\n    {\n      q:\"A rebellious province threatens the stability of your entire realm. How do you respond?\",\n      opts:[\n        {v:4,t:\"Crush the rebellion swiftly and decisively; make an example that deters future revolt\"},\n        {v:1,t:\"Negotiate terms of surrender with concessions on both sides\"},\n        {v:2,t:\"Send a trusted general to handle it while you remain above the conflict\"},\n        {v:3,t:\"Punish only the leaders severely, but pardon the common people to win their gratitude\"}\n      ]\n    },\n    {\n      q:\"Your army faces a superior force. What is your primary consideration?\",\n      opts:[\n        {v:4,t:\"Fight using strategy and deception — divide their forces, attack at night, feign retreat\"},\n        {v:1,t:\"Avoid battle at all costs; preserve your army for another day through diplomacy\"},\n        {v:2,t:\"Rely on your professional soldiers; they know better than you how to fight\"},\n        {v:3,t:\"Lead from the front; your men will fight harder seeing their prince in the ranks\"}\n      ]\n    },\n    {\n      q:\"A minister grows very popular — perhaps too popular. The people adore him. What do you do?\",\n      opts:[\n        {v:1,t:\"Celebrate his success publicly; a popular minister is a reflection of your wisdom in choosing him\"},\n        {v:4,t:\"Transfer him to a position of honor far from the capital; neutral power or remove him\"},\n        {v:2,t:\"Publicly rebuke him for something minor to remind the people who truly rules\"},\n        {v:3,t:\"Promote him further, but place a loyal observer at his side to report on his activities\"}\n      ]\n    },\n    {\n      q:\"Fortune has dealt you a setback. A territory is lost. Your reputation is shaken. How do you regain control?\",\n      opts:[\n        {v:4,t:\"Seize the moment with bold, impetuous action — fortune favors the audacious\"},\n        {v:1,t:\"Retreat, consolidate your remaining forces, and wait for a more favorable opportunity\"},\n        {v:2,t:\"Send ambassadors to negotiate favorable terms while rebuilding in secret\"},\n        {v:3,t:\"Study what went wrong, adapt your methods, and prepare to strike again with new wisdom\"}\n      ]\n    }\n  ];\n\n  const quizContainer=document.getElementById('quizQuestions');\n  quizQuestions.forEach((qq,i)=>{\n    const d=document.createElement('div');\n    d.className='quiz-q';\n    let opts='';\n    qq.opts.forEach((o,oi)=>{\n      opts+=`<label data-v=\"${o.v}\">\n        <input type=\"radio\" name=\"q${i}\" value=\"${oi}\">\n        <span>${o.t}</span>\n      </label>`;\n    });\n    d.innerHTML=`\n      <div class=\"qq-num\">Dilemma ${i+1}</div>\n      <div class=\"qq-text\">${qq.q}</div>\n      <div class=\"qq-opt\">${opts}</div>\n    `;\n    quizContainer.appendChild(d);\n    d.querySelectorAll('label').forEach(l=>{\n      l.querySelector('input').addEventListener('change',()=>{\n        d.querySelectorAll('label').forEach(x=>x.classList.remove('selected'));\n        l.classList.add('selected');\n      });\n    });\n  });\n\n  document.getElementById('quizSubmit').addEventListener('click',()=>{\n    let total=0;\n    let answered=0;\n    document.querySelectorAll('.quiz-q').forEach(q=>{\n      const sel=q.querySelector('input:checked');\n      if(sel){\n        answered++;\n        total+=parseInt(sel.closest('label').dataset.v);\n      }\n    });\n\n    if(answered<5){\n      alert('Answer all five dilemmas before revealing your ruler type.');\n      return;\n    }\n\n    const result=document.getElementById('quizResult');\n    const rType=document.getElementById('qrType');\n    const rDesc=document.getElementById('qrDesc');\n\n    let type,desc;\n    if(total<=8){\n      type='The Cautious Diplomat';\n      desc='You favor negotiation, patience, and preservation. Like Machiavelli\\'s more conservative prince, you seek stability through restraint and deliberation. Your strength lies in avoiding unnecessary conflict — but watch that caution does not become indecision. The bold still have their place in the world.';\n    }else if(total<=12){\n      type='The Balanced Ruler';\n      desc='You blend pragmatism with principle. Neither purely lion nor purely fox, you choose your approach based on circumstance. Machiavelli would approve of your flexibility — but caution you: in matters of state, consistency can become a prison. Be ready to set aside even your virtues when necessity demands.';\n    }else if(total<=16){\n      type='The Cunning Strategist';\n      desc='You think three moves ahead. Deception, timing, and human nature are your tools. Machiavelli would recognize you as a kindred spirit — one who understands that appearances matter as much as reality. Your risk: that cunning without strength will leave you vulnerable when force is needed.';\n    }else{\n      type='The Lion Prince';\n      desc='Bold, decisive, and unafraid of cruelty when it serves your purpose. You lead from the front and trust in strength and action. Machiavelli\\'s ideal prince would recognize your virtù. Your danger: impetuosity without caution. Remember — the fox also has its place. Not every battle is won by charging.';\n    }\n\n    rType.innerHTML='<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"/></svg> '+type+' <svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"12 2 15 9 22 9 16.5 14 18.5 21 12 17 5.5 21 7.5 14 2 9 9 9 12 2\"/></svg>';\n    rDesc.textContent=desc;\n    result.classList.add('show');\n    result.scrollIntoView({behavior:'smooth',block:'center'});\n  });\n\n  //  QUOTES \n  const quotes=[\n    {q:\"It is much safer to be feared than loved, if one must choose.\",c:\"Chapter 17 — Of Cruelty and Mercy\"},\n    {q:\"The ends justify the means.\",c:\"Chapter 18 — How Princes Should Keep Faith\"},\n    {q:\"A prince never lacks legitimate reasons to break his promise.\",c:\"Chapter 18 — How Princes Should Keep Faith\"},\n    {q:\"The first method for estimating the intelligence of a ruler is to look at the men he has around him.\",c:\"Chapter 22 — Of the Ministers of Princes\"},\n    {q:\"There is no avoiding war; it can only be postponed to the advantage of others.\",c:\"Chapter 3 — Of Mixed Principalities\"},\n    {q:\"He who neglects what is done for what ought to be done will sooner bring about his ruin than his preservation.\",c:\"Chapter 15 — Of Things for Which Princes Are Praised or Blamed\"},\n    {q:\"All armed prophets have conquered; unarmed prophets have been destroyed.\",c:\"Chapter 6 — Of New Principalities Acquired by Virtù\"},\n    {q:\"Fortune is a woman, and if you wish to keep her under, it is necessary to beat and ill-use her.\",c:\"Chapter 25 — How Much Fortune Can Do\"},\n    {q:\"Men are quick to change their nature when it serves their interest.\",c:\"Chapter 18 — How Princes Should Keep Faith\"},\n    {q:\"A prince should appear merciful, faithful, humane, religious, and upright — and should actually be so, but with a mind so trained that, when the need arises, he can become the opposite.\",c:\"Chapter 18 — How Princes Should Keep Faith\"},\n    {q:\"The wise prince does not keep faith when such faith works against his interests.\",c:\"Chapter 18 — How Princes Should Keep Faith\"},\n    {q:\"It is better to be impetuous than cautious, for fortune is a woman.\",c:\"Chapter 25 — How Much Fortune Can Do\"}\n  ];\n\n  const quotesContainer=document.getElementById('quotesContainer');\n  quotes.forEach((q,i)=>{\n    const d=document.createElement('div');\n    d.className='quote-block';\n    d.innerHTML=`\n      <div class=\"q-ornament\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M3 21c3 0 7-1 7-8V5c0-1.25-.756-2.017-2-2H4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2 1 0 1 0 1 1v1c0 1-1 2-2 2s-1 .008-1 1.031V20c0 1 0 1 1 1z\"/><path d=\"M15 21c3 0 7-1 7-8V5c0-1.25-.757-2.017-2-2h-4c-1.25 0-2 .75-2 1.972V11c0 1.25.75 2 2 2h.75c0 2.25.25 4-2.75 4v3c0 1 0 1 1 1z\"/></svg></div>\n      <blockquote>\"${q.q}\"</blockquote>\n      <cite>— Niccolò Machiavelli, <em>The Prince</em></cite>\n      <div class=\"q-ref\">${q.c}</div>\n    `;\n    quotesContainer.appendChild(d);\n    observer.observe(d);\n  });\n\n  //  MODERN RELEVANCE \n  const modernData=[\n    {i:\"🏛️\",t:\"Political Strategy\",p:\"Modern political campaigns, diplomacy, and international relations still follow Machiavelli's principles — alliances, calculated deception, and the pragmatic use of power are standard tools of statecraft.\"},\n    {i:'<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M20 7h-4a2 2 0 0 1-2-2V3\"/><path d=\"M4 7V3a2 2 0 0 1 2-2h10l4 4v13a2 2 0 0 1-2 2\"/><circle cx=\"12\" cy=\"15\" r=\"4\"/><path d=\"M12 11v4\"/></svg>',t:\"Business & Leadership\",p:\"Corporate strategy, competitive positioning, and organizational leadership echo Machiavelli. Concepts like strategic alliances, brand perception, and competitive advantage mirror the Prince's playbook.\"},\n    {i:\"⚔️\",t:\"Military Doctrine\",p:\"The emphasis on one's own arms, preparation during peace, and the study of war remain central to military academies worldwide. Clausewitz, Sun Tzu, and Machiavelli form the bedrock of strategic thought.\"},\n    {i:'<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\"/><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"/></svg>',t:\"Psychology of Power\",p:\"Machiavelli understood human nature — fear, ambition, self-interest — with piercing clarity. Modern behavioral economics and social psychology confirm many of his observations about how people respond to authority.\"},\n    {i:'<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4\"/><polyline points=\"7 10 12 15 17 10\"/><line x1=\"12\" y1=\"15\" x2=\"12\" y2=\"3\"/></svg>',t:\"Negotiation Tactics\",p:\"The principles of leverage, appearing strong while being flexible, and knowing when to break a commitment are taught in every serious negotiation program. Machiavelli's fingerprints are everywhere.\"},\n    {i:'<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 19.5A2.5 2.5 0 0 1 6.5 17H20\"/><path d=\"M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z\"/></svg>',t:\"Enduring Controversy\",p:\"'Machiavellian' remains a byword for cunning and duplicity. The book continues to provoke debate about ethics, power, and whether the ends truly justify the means — a testament to its enduring power.\"}\n  ];\n\n  const modernGrid=document.getElementById('modernGrid');\n  modernData.forEach(item=>{\n    const d=document.createElement('div');\n    d.className='modern-card';\n    d.innerHTML=`\n      <span class=\"mc-icon\">${item.i}</span>\n      <h4>${item.t}</h4>\n      <p>${item.p}</p>\n    `;\n    modernGrid.appendChild(d);\n    observer.observe(d);\n  });\n\n  //  OBSERVE ALL \n  document.querySelectorAll('.theme-card, .tk-card, .q-item, .quote-block, .modern-card').forEach(el=>observer.observe(el));\n</script>\n\n\n\n</body>\n</html>",
  "the-psychology-of-money": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div class=\"particles\" id=\"particles\"></div>\n\n\n\n\n\n<div class=\"container\">\n\n<section id=\"takeaways\">\n  <div class=\"section-label reveal\">Chapter by Chapter</div>\n  <h2 class=\"section-title reveal\">The 20 Most Important Takeaways</h2>\n  <p class=\"section-subtitle reveal\">Each chapter distills a timeless truth about our relationship with money — not from a spreadsheet, but from lived experience and human psychology.</p>\n  <div class=\"stats-bar reveal\">\n    <div class=\"stat-item\">\n      <div class=\"stat-number\">20</div>\n      <div class=\"stat-label\">Timeless Lessons</div>\n    </div>\n    <div class=\"stat-item\">\n      <div class=\"stat-number\">200+</div>\n      <div class=\"stat-label\">Pages of Wisdom</div>\n    </div>\n    <div class=\"stat-item\">\n      <div class=\"stat-number\">4.7</div>\n      <div class=\"stat-label\">Goodreads Rating</div>\n    </div>\n    <div class=\"stat-item\">\n      <div class=\"stat-number\">35+</div>\n      <div class=\"stat-label\">Languages</div>\n    </div>\n  </div>\n  <div class=\"takeaways-grid\" id=\"takeawaysGrid\"></div>\n</section>\n\n<section id=\"concepts\">\n  <div class=\"section-label reveal\">Core Ideas</div>\n  <h2 class=\"section-title reveal\">Key Concepts That Shape Everything</h2>\n  <p class=\"section-subtitle reveal\">Housel's most powerful ideas — the mental models that rewire how you think about money, risk, and happiness.</p>\n  <div class=\"concepts-grid\">\n    <div class=\"concept-card\" data-delay=\"0\">\n      <span class=\"concept-icon\">⏱</span>\n      <h3>The Power of Compounding</h3>\n      <p>The most powerful force in finance is not intelligence or insight — it's time. Small, consistent actions, given enough decades, produce outcomes that defy intuition. Housel shows that Warren Buffett's true secret isn't investing brilliance, but that he started at age 10 and lived to 90.</p>\n    </div>\n    <div class=\"concept-card\" data-delay=\"100\">\n      <span class=\"concept-icon\">⚠</span>\n      <h3>Luck &amp; Risk</h3>\n      <p>Everything in finance comes from a blend of skill and chance. We desperately want to believe success is earned and failure is deserved, but the line between luck and skill is blurrier than we admit. Be humble in success and forgiving in failure.</p>\n    </div>\n    <div class=\"concept-card\" data-delay=\"200\">\n      <span class=\"concept-icon\">∞</span>\n      <h3>The Concept of Enough</h3>\n      <p>There is no amount of money that will make you feel wealthy if you don't know what \"enough\" means. When you have more than you'll ever need, the goalposts move. The hardest financial skill is getting the goalposts to stop moving.</p>\n    </div>\n    <div class=\"concept-card\" data-delay=\"300\">\n      <span class=\"concept-icon\">★</span>\n      <h3>Wealth vs. Income</h3>\n      <p>Wealth is what you don't see. Income is what you show. The wealthy often look like they have less than they do, and those who look wealthy often have less than they appear. True wealth is the gap between what you earn and what you don't spend.</p>\n    </div>\n  </div>\n\n  <div class=\"comparison-section reveal\">\n    <div class=\"section-label\" style=\"text-align:center;\">Side by Side</div>\n    <h3 style=\"text-align:center;font-size:1.6rem;font-weight:700;margin-bottom:0.5rem;\">Wealth <span style=\"color:var(--text-light);font-weight:300;\">vs.</span> Rich</h3>\n    <p style=\"text-align:center;color:var(--text-light);font-size:0.9rem;\">The distinction that changes everything</p>\n    <div class=\"comparison-grid\">\n      <div class=\"comparison-column wealth\">\n        <h3>◆ Wealth</h3>\n        <ul>\n          <li>What you keep, not what you spend</li>\n          <li>Built through patience and restraint</li>\n          <li>Invisible — lives below its means</li>\n          <li>Buys freedom and independence</li>\n          <li>Compounds slowly over time</li>\n          <li>About control over your time</li>\n        </ul>\n      </div>\n      <div class=\"comparison-column rich\">\n        <h3>◆ Rich</h3>\n        <ul>\n          <li>What you display, not what you own</li>\n          <li>Built through spending and showing</li>\n          <li>Visible — lives at or above means</li>\n          <li>Buys status and approval</li>\n          <li>Dissipates quickly</li>\n          <li>About control over perception</li>\n        </ul>\n      </div>\n    </div>\n    <div class=\"comparison-quote\">\n      \"Wealth is the nice cars not purchased. The diamonds not bought. The clothes not worn. Wealth is the financial assets that accumulate silently, invisibly, while we go about our day.\"\n    </div>\n  </div>\n\n  <div class=\"compounding-section\" id=\"compoundingSection\">\n    <h3>⏱ The Compounding Visualizer</h3>\n    <p>See how small, consistent investments explode over time — the single most important graph in the book.</p>\n    <div class=\"compounding-controls\">\n      <div class=\"control-group\">\n        <label>Annual Return <span id=\"returnValue\">8%</span></label>\n        <input type=\"range\" id=\"returnSlider\" min=\"1\" max=\"25\" value=\"8\" step=\"0.5\">\n      </div>\n      <div class=\"control-group\">\n        <label>Time Horizon <span id=\"yearsValue\">30 years</span></label>\n        <input type=\"range\" id=\"yearsSlider\" min=\"5\" max=\"60\" value=\"30\" step=\"1\">\n      </div>\n      <div class=\"control-group\">\n        <label>Monthly Savings <span id=\"savingsValue\">$500</span></label>\n        <input type=\"range\" id=\"savingsSlider\" min=\"100\" max=\"5000\" value=\"500\" step=\"50\">\n      </div>\n    </div>\n    <div class=\"compounding-chart\" id=\"compoundingChart\"></div>\n    <div class=\"compounding-result\">\n      <div class=\"final-value\" id=\"finalValue\">$745,000</div>\n      <div class=\"final-label\">Total after investment period</div>\n    </div>\n  </div>\n</section>\n\n<section id=\"biases\">\n  <div class=\"section-label reveal\">Behavioral Psychology</div>\n  <h2 class=\"section-title reveal\">Biases That Shape Your Money Decisions</h2>\n  <p class=\"section-subtitle reveal\">Housel reveals that we are not rational calculators — we are emotional beings shaped by our unique histories with money.</p>\n  <div class=\"bias-section reveal\">\n    <div class=\"bias-tabs\" id=\"biasTabs\"></div>\n    <div class=\"bias-content\" id=\"biasContent\">\n      <h3><span class=\"bias-icon\">📈</span>Select a bias above</h3>\n      <p>Click on any bias to explore how it affects your financial decisions — and how to recognize it in yourself.</p>\n    </div>\n  </div>\n</section>\n\n<section>\n  <div class=\"section-label reveal\">Housel's Craft</div>\n  <h2 class=\"section-title reveal\">The Art of Financial Storytelling</h2>\n  <p class=\"section-subtitle reveal\">What makes The Psychology of Money resonate so deeply is not the data — it's the stories. Housel writes about finance the way a novelist writes about the human condition.</p>\n  <div class=\"story-section reveal\">\n    <div class=\"story-text\">\n      <div class=\"section-divider\" style=\"margin-bottom:1.5rem;\"></div>\n      <p style=\"font-size:1.05rem;line-height:1.8;color:var(--text-light);margin-bottom:1rem;\">\n        \"A genius who loses money is just a genius who lost money. A person who can earn a good living and save a lot of money becomes wealthy. Finance is not a hard science — it's a soft one.\"\n      </p>\n      <p style=\"font-size:0.9rem;color:var(--text-light);line-height:1.7;\">\n        Housel's gift is making complex ideas feel like conversations with a wise friend. He doesn't lecture — he invites. Each chapter is a short story, with characters, tension, and a lesson that stays with you. That's why this book has sold millions: it treats the reader as a human being, not a spreadsheet.\n      </p>\n    </div>\n    <div class=\"story-visual\">\n      <div class=\"story-circle\">\n        <div class=\"orbit\"></div>\n        <div class=\"orbit\"></div>\n        <div class=\"story-circle-content\">\n          <div class=\"big-number\">★</div>\n          <p style=\"font-size:0.95rem;font-weight:600;color:var(--gold);margin-top:0.5rem;\">Storytelling<br>over<br>Statistics</p>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section id=\"quotes\">\n  <div class=\"section-label reveal\">Words That Stick</div>\n  <h2 class=\"section-title reveal\">Key Quotes</h2>\n  <p class=\"section-subtitle reveal\">The passages that readers return to again and again — distilled wisdom from every chapter.</p>\n  <div class=\"quotes-grid\" id=\"quotesGrid\"></div>\n</section>\n\n<section>\n  <div class=\"section-label reveal\">Your Philosophy</div>\n  <h2 class=\"section-title reveal\">Build Your Financial Philosophy</h2>\n  <p class=\"section-subtitle reveal\">Mix and match Housel's core principles to create your personal money philosophy.</p>\n  <div class=\"philosophy-section\">\n    <div class=\"philosophy-builder\" id=\"philosophyBuilder\">\n      <h3 style=\"margin-bottom:0.5rem;\">⚡ Your Philosophy</h3>\n      <p>Select one principle from each category below.</p>\n      <div class=\"philosophy-options\" id=\"philosophyOptions\"></div>\n      <div class=\"phi-result\" id=\"phiResult\">\n        Select your principles above to generate your philosophy.\n      </div>\n    </div>\n  </div>\n</section>\n\n</div>\n\n\n\n<script>\nconst takeaways = [\n  { num: 1, title: \"No One's Crazy\", detail: \"Your financial decisions are shaped by your unique experiences — what seems crazy to you may be perfectly rational to someone else born in a different time, place, or circumstance.\" },\n  { num: 2, title: \"Luck & Risk\", detail: \"Everything worthwhile in finance carries both luck and risk. Be humble in success — you got lucky. Be forgiving in failure — they got unlucky.\" },\n  { num: 3, title: \"Never Enough\", detail: \"The hardest financial skill is knowing when 'enough' is enough. When greed exceeds enough, you'll always find ways to lose what you have.\" },\n  { num: 4, title: \"The Power of Compounding\", detail: \"Warren Buffett's fortune isn't from being the best investor — it's from starting at age 10 and living to 90. Time is the only factor you can't replace.\" },\n  { num: 5, title: \"Getting Wealthy vs. Staying Wealthy\", detail: \"Getting rich requires risk and optimism. Staying rich requires fear and humility. They are entirely different skills.\" },\n  { num: 6, title: \"Tails, You Win\", detail: \"You can be wrong half the time and still do incredibly well. A small number of outsized events drive the majority of returns.\" },\n  { num: 7, title: \"Freedom\", detail: \"The highest dividend money pays is the ability to control your time. No amount of wealth is worth losing your freedom.\" },\n  { num: 8, title: \"Man in the Car Paradox\", detail: \"When you see someone in a fancy car, you rarely think about the driver — you imagine yourself in the car. People want admiration, but display signals rarely deliver it.\" },\n  { num: 9, title: \"Wealth is What You Don't See\", detail: \"Wealth is the nice cars not purchased, the diamonds not bought. True wealth is invisible — it accumulates in quiet, boring assets.\" },\n  { num: 10, title: \"Save Money\", detail: \"The only factor you can fully control is your savings rate. Income is earned by others; spending is earned by you. Saving is the gap between ego and income.\" },\n  { num: 11, title: \"Reasonable > Rational\", detail: \"You don't need to be a cold, calculating machine. Being reasonable — good enough, most of the time — beats being perfectly rational but unable to stick with a plan.\" },\n  { num: 12, title: \"Surprise!\", detail: \"History is not a guidebook for the future. The things that surprise us most are the things that have never happened before — but they will.\" },\n  { num: 13, title: \"Room for Error\", detail: \"The margin of safety is the only way to safely navigate an uncertain world. Plan for things to go wrong — not because they will, but because they might.\" },\n  { num: 14, title: \"You'll Change\", detail: \"Long-term planning is hard because your goals and desires will change. Be open to evolution — the person you are today won't be the same in 20 years.\" },\n  { num: 15, title: \"Nothing's Free\", detail: \"Every financial return comes with a price — volatility, uncertainty, doubt. The problem is the price isn't labeled. You only see it after you've paid.\" },\n  { num: 16, title: \"You & Me\", detail: \"Your financial timeline is unique. What works for a pension fund or a billionaire may be terrible for you. Play your own game.\" },\n  { num: 17, title: \"The Seduction of Pessimism\", detail: \"Pessimism sounds smarter and more sophisticated than optimism. But optimism is the only stance that works long-term — because the future belongs to those who keep showing up.\" },\n  { num: 18, title: \"When You Believe Anything\", detail: \"We believe stories that confirm our views. The more you want something to be true, the more likely you are to believe it. Stay skeptical.\" },\n  { num: 19, title: \"All Together Now\", detail: \"The most powerful financial strategy is simple: live below your means, save consistently, be patient, and give yourself room for error. Boring works.\" },\n  { num: 20, title: \"Confusion of Goals\", detail: \"Money's greatest value is giving you control over your time. If money isn't buying you autonomy, you're using it wrong. The goal isn't to be rich — it's to be free.\" }\n];\n\nconst quotes = [\n  { text: \"The ability to do what you want, when you want, with who you want, for as long as you want, is the single most powerful tool money gives us.\", source: \"Chapter 7: Freedom\" },\n  { text: \"Wealth is the nice cars not purchased. The diamonds not bought. The clothes not worn. Wealth is financial assets that haven't yet been converted into the things you see.\", source: \"Chapter 9: Wealth is What You Don't See\" },\n  { text: \"The hardest financial skill is getting the goalposts to stop moving.\", source: \"Chapter 3: Never Enough\" },\n  { text: \"There is no reason to risk what you have and need for what you don't have and don't need.\", source: \"Chapter 5: Getting Wealthy vs. Staying Wealthy\" },\n  { text: \"A genius who loses money is just a genius who lost money. A person who can earn a good living and save a lot of money becomes wealthy.\", source: \"Chapter 1: No One's Crazy\" },\n  { text: \"More than I want to be rich, I want to be able to wake up every morning and say, 'I can do whatever I want today.'\", source: \"Foreword\" },\n  { text: \"Compounding doesn't rely on earning big returns. It relies on earning decent returns consistently for a long time. That's it.\", source: \"Chapter 4: The Power of Compounding\" },\n  { text: \"An iron rule of finance: money seeks anonymity. The more visible you make your money, the more likely you are to lose it.\", source: \"Chapter 9: Wealth is What You Don't See\" }\n];\n\nconst biases = [\n  { name: \"Confirmation Bias\", icon: \"&#128269;\", desc: \"We seek information that confirms what we already believe about money and investing. If you think the market will crash, you'll find evidence everywhere — even when the data says otherwise.\", example: \"An investor only reads bearish news and thinks the economy is collapsing, while ignoring GDP growth and low unemployment.\" },\n  { name: \"Recency Bias\", icon: \"&#9200;\", desc: \"We assume what happened recently will continue. After a bull market, we believe stocks only go up. After a crash, we think they'll never recover. This makes us buy high and sell low.\", example: \"After seeing 30% returns last year, you assume 30% is normal and invest recklessly, ignoring historical averages.\" },\n  { name: \"Hindsight Bias\", icon: \"&#128064;\", desc: \"After something happens, we convince ourselves we knew it all along. This makes us overconfident in our ability to predict the future and blind to the role of luck.\", example: \"After a stock doubles, you say 'I knew it would go up' — but you didn't invest in it.\" },\n  { name: \"Loss Aversion\", icon: \"&#128308;\", desc: \"Losing $100 hurts roughly twice as much as gaining $100 feels good. This asymmetry makes us overly conservative when we should take calculated risks, and overly reckless trying to break even.\", example: \"Holding a losing stock for years because selling and realizing the loss feels unbearable.\" },\n  { name: \"Social Proof\", icon: \"&#128101;\", desc: \"We look to others to decide what's correct. When everyone around us is buying crypto, real estate, or a hot stock, we feel an almost physical urge to join — even if it defies logic.\", example: \"Buying Bitcoin at $60k because your friends got rich, ignoring that you're arriving late.\" },\n  { name: \"Overconfidence\", icon: \"&#128170;\", desc: \"Men in particular tend to overestimate their financial ability. We think we're above average drivers, investors, and savers. Overconfidence leads to excessive trading, concentrated bets, and catastrophic losses.\", example: \"A day trader believes they've cracked the market code, taking massive leverage before a correction wipes them out.\" },\n  { name: \"Narrative Fallacy\", icon: \"&#128214;\", desc: \"We prefer compelling stories over dry statistics. A vivid anecdote about someone getting rich from a stock feels more true than the data showing most people lose money trying the same thing.\", example: \"Hearing about your neighbor who made millions in Tesla stock, ignoring the thousands who lost money timing it wrong.\" },\n  { name: \"Anchoring\", icon: \"&#9878;\", desc: \"We fixate on a specific reference point — the price we bought a stock at, the market's all-time high — and make decisions based on that anchor rather than current reality.\", example: \"Refusing to buy a stock at $100 because you remember it was $50 last year, even though the company is worth more now.\" }\n];\n\nconst philosophyCategories = [\n  {\n    category: \"Your Relationship with Money\",\n    options: [\n      \"Money is a tool for freedom and autonomy\",\n      \"Money is a measure of achievement and success\",\n      \"Money is security against life's uncertainties\",\n      \"Money is a responsibility to be managed wisely\"\n    ]\n  },\n  {\n    category: \"Your Approach to Risk\",\n    options: [\n      \"Take calculated risks with room for error\",\n      \"Avoid risk entirely — preservation first\",\n      \"Take bold bets with asymmetric upside\",\n      \"Diversify broadly and stay the course\"\n    ]\n  },\n  {\n    category: \"Your Definition of Enough\",\n    options: [\n      \"Enough is when I control my time\",\n      \"Enough is when my basic needs are covered for life\",\n      \"Enough keeps moving — I always want more\",\n      \"Enough is measured by impact, not accumulation\"\n    ]\n  },\n  {\n    category: \"Your Investing Stance\",\n    options: [\n      \"Patient compounding over decades\",\n      \"Active trading and market timing\",\n      \"Index funds and hands-off approach\",\n      \"Value investing with deep research\"\n    ]\n  }\n];\n\n// Render takeaways\nconst grid = document.getElementById('takeawaysGrid');\ntakeaways.forEach(t => {\n  const card = document.createElement('div');\n  card.className = 'takeaway-card';\n  card.innerHTML = `\n    <div class=\"takeaway-number\">Chapter ${t.num}</div>\n    <h3>${t.title}</h3>\n    <p>${t.detail}</p>\n    <div class=\"takeaway-expand-icon\">+</div>\n  `;\n  card.addEventListener('click', () => card.classList.toggle('expanded'));\n  grid.appendChild(card);\n});\n\n// Render quotes\nconst quotesGrid = document.getElementById('quotesGrid');\nquotes.forEach(q => {\n  const card = document.createElement('div');\n  card.className = 'quote-card';\n  card.innerHTML = `\n    <div class=\"quote-mark\">\"</div>\n    <blockquote>${q.text}</blockquote>\n    <div class=\"quote-source\">${q.source}</div>\n  `;\n  quotesGrid.appendChild(card);\n});\n\n// Render biases\nconst tabs = document.getElementById('biasTabs');\nconst biasContent = document.getElementById('biasContent');\nbiases.forEach((b, i) => {\n  const tab = document.createElement('button');\n  tab.className = 'bias-tab' + (i === 0 ? ' active' : '');\n  tab.textContent = b.name;\n  tab.addEventListener('click', () => {\n    document.querySelectorAll('.bias-tab').forEach(t => t.classList.remove('active'));\n    tab.classList.add('active');\n    biasContent.innerHTML = `\n      <h3><span class=\"bias-icon\">${b.icon}</span>${b.name}</h3>\n      <p>${b.desc}</p>\n      <div class=\"bias-example\">\"${b.example}\"</div>\n    `;\n  });\n  tabs.appendChild(tab);\n});\n// Activate first bias\nbiases[0] && tabs.querySelector('.bias-tab')?.click();\n\n// Render philosophy builder\nconst phiOptions = document.getElementById('philosophyOptions');\nconst phiResult = document.getElementById('phiResult');\nconst selections = [];\n\nphilosophyCategories.forEach((cat, ci) => {\n  cat.options.forEach((opt, oi) => {\n    const el = document.createElement('button');\n    el.className = 'phi-option';\n    el.innerHTML = `<div class=\"phi-category\">${cat.category}</div>${opt}`;\n    el.addEventListener('click', () => {\n      document.querySelectorAll(`.phi-option`).forEach(e => {\n        if (e.querySelector('.phi-category')?.textContent === cat.category) {\n          e.classList.remove('selected');\n        }\n      });\n      el.classList.add('selected');\n      selections[ci] = opt;\n      updatePhilosophy();\n    });\n    phiOptions.appendChild(el);\n  });\n});\n\nfunction updatePhilosophy() {\n  if (selections.length < philosophyCategories.length || selections.some(s => !s)) {\n    phiResult.textContent = 'Select your principles above to generate your philosophy.';\n    return;\n  }\n  phiResult.innerHTML = `\n    <strong style=\"color:var(--gold);font-size:1.05rem;\">Your Financial Philosophy</strong><br><br>\n    ${selections[0]}. I believe ${selections[0].toLowerCase()}.<br>\n    When it comes to risk: ${selections[1].toLowerCase()}.<br>\n    For me, enough means: ${selections[2].toLowerCase()}.<br>\n    My investing approach: ${selections[3].toLowerCase()}.<br><br>\n    <em style=\"color:var(--text-light);font-size:0.85rem;\">\"A reasonable philosophy you can stick with beats a perfect one you abandon.\"</em>\n  `;\n}\n\n// Compounding visualizer\nconst returnSlider = document.getElementById('returnSlider');\nconst yearsSlider = document.getElementById('yearsSlider');\nconst savingsSlider = document.getElementById('savingsSlider');\nconst returnValue = document.getElementById('returnValue');\nconst yearsValue = document.getElementById('yearsValue');\nconst savingsValue = document.getElementById('savingsValue');\nconst finalValue = document.getElementById('finalValue');\nconst chart = document.getElementById('compoundingChart');\n\nfunction formatMoney(n) {\n  if (n >= 1e6) return '$' + (n / 1e6).toFixed(1) + 'M';\n  if (n >= 1e3) return '$' + (n / 1e3).toFixed(0) + 'K';\n  return '$' + Math.round(n);\n}\n\nfunction updateCompound() {\n  const rate = parseFloat(returnSlider.value) / 100;\n  const years = parseInt(yearsSlider.value);\n  const monthly = parseInt(savingsSlider.value);\n  const monthlyRate = rate / 12;\n  const totalMonths = years * 12;\n\n  returnValue.textContent = (rate * 100).toFixed(1) + '%';\n  yearsValue.textContent = years + ' years';\n  savingsValue.textContent = '$' + monthly;\n\n  let balance = 0;\n  const points = [];\n  for (let m = 1; m <= totalMonths; m++) {\n    balance = (balance + monthly) * (1 + monthlyRate);\n    if (m % Math.max(1, Math.floor(totalMonths / 60)) === 0 || m === totalMonths) {\n      points.push({ month: m, value: balance });\n    }\n  }\n\n  const maxVal = Math.max(...points.map(p => p.value), 1);\n  chart.innerHTML = '';\n  points.forEach((p, i) => {\n    const bar = document.createElement('div');\n    bar.className = 'bar';\n    const h = (p.value / maxVal) * 100;\n    bar.style.height = h + '%';\n    bar.title = `Year ${(p.month / 12).toFixed(1)}: ${formatMoney(p.value)}`;\n    chart.appendChild(bar);\n  });\n\n  finalValue.textContent = formatMoney(balance);\n}\n\n[returnSlider, yearsSlider, savingsSlider].forEach(s => {\n  s.addEventListener('input', updateCompound);\n});\nupdateCompound();\n\n// Particles\n(function createParticles() {\n  const container = document.getElementById('particles');\n  for (let i = 0; i < 30; i++) {\n    const p = document.createElement('div');\n    p.className = 'particle';\n    const size = 2 + Math.random() * 4;\n    p.style.width = size + 'px';\n    p.style.height = size + 'px';\n    p.style.left = Math.random() * 100 + '%';\n    p.style.animationDuration = (15 + Math.random() * 25) + 's';\n    p.style.animationDelay = Math.random() * 20 + 's';\n    p.style.setProperty('--p-opacity', (0.2 + Math.random() * 0.4).toFixed(2));\n    container.appendChild(p);\n  }\n})();\n\n// Theme toggle\nconst themeToggle = document.getElementById('themeToggle');\nthemeToggle.addEventListener('click', () => {\n  const isDark = document.documentElement.getAttribute('data-theme') === 'dark';\n  document.documentElement.setAttribute('data-theme', isDark ? 'light' : 'dark');\n});\n\n// Scroll reveal\nconst revealObserver = new IntersectionObserver((entries) => {\n  entries.forEach(entry => {\n    if (entry.isIntersecting) {\n      const el = entry.target;\n      const delay = parseInt(el.dataset.delay) || 0;\n      setTimeout(() => el.classList.add('visible'), delay);\n      revealObserver.unobserve(el);\n    }\n  });\n}, { threshold: 0.1, rootMargin: '0px 0px -40px 0px' });\n\ndocument.querySelectorAll('.reveal, .takeaway-card, .concept-card, .quote-card, .compounding-section, .philosophy-builder, .story-text, .story-visual').forEach(el => {\n  revealObserver.observe(el);\n});\n\n// Also observe takeaway cards and concept cards after they're created\nsetTimeout(() => {\n  document.querySelectorAll('.takeaway-card, .concept-card, .quote-card').forEach(el => {\n    if (!el.classList.contains('visible')) revealObserver.observe(el);\n  });\n}, 100);\n</script>\n\n\n\n</body>\n</html>",
  "what-every-body-is-saying": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no\">\n<style>\n*{margin:0;padding:0;box-sizing:border-box}\nbody{background:#080c08;color:#e0e0e0;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',system-ui,sans-serif;font-size:16px;line-height:1.7;-webkit-font-smoothing:antialiased}\n</style>\n</head>\n<body>\n\n\n<div id=\"scanlines\"></div>\n<canvas id=\"radar-canvas\"></canvas>\n\n<div class=\"content\">\n  <header>\n    <div class=\"badge\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"11\" cy=\"11\" r=\"8\"></circle><path d=\"m21 21-4.35-4.35\"></path></svg> Classified — Field Guide</div>\n    <h1>What Every BODY Is Saying</h1>\n    <div class=\"subtitle\">An Ex-FBI Agent's Guide to Speed-Reading People</div>\n    <div class=\"author\">Joe Navarro (with Marvin Karlins)</div>\n  </header>\n\n  <div class=\"tabs\">\n    <button class=\"tab-btn active\" data-tab=\"basics\">Basics</button>\n    <button class=\"tab-btn\" data-tab=\"body\">Body Map</button>\n    <button class=\"tab-btn\" data-tab=\"signals\">Signals</button>\n    <button class=\"tab-btn\" data-tab=\"rules\">Rules</button>\n    <button class=\"tab-btn\" data-tab=\"quotes\">Quotes</button>\n  </div>\n\n  <!--  TAB: Basics  -->\n  <div class=\"tab-panel active\" id=\"tab-basics\">\n    <div class=\"card\" style=\"animation-delay: 0s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3\"></path><line x1=\"12\" y1=\"17\" x2=\"12.01\" y2=\"17\"></line></svg> <span class=\"accent-green\">The Triune Brain</span></h2>\n      <p>Three brains, one purpose: survival. The key to reading people is the <strong>limbic brain</strong> — the emotional center that <em>cannot lie</em>.</p>\n      <ul style=\"margin-top:0.6rem;\">\n        <li><span class=\"accent-green\">Reptilian</span> — Basic survival (breathing, heartbeat, fight-or-flight)</li>\n        <li><span class=\"accent-blue\">Limbic</span> — Emotions, memory, nonverbal honesty ← <strong>THIS IS THE ONE</strong></li>\n        <li><span class=\"accent-purple\">Neocortex</span> — Rational thought, language, planning (also: <em>lying</em>)</li>\n      </ul>\n    </div>\n\n    <div class=\"card\" style=\"animation-delay: 0.1s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><polygon points=\"13 2 3 14 12 14 11 22 21 10 12 10 13 2\"></polygon></svg> <span class=\"accent-green\">The 3 F's — Limbic Survival Responses</span></h2>\n      <div class=\"ff-grid\">\n        <div class=\"ff-card\">\n          <div class=\"icon\">🧊</div>\n          <div class=\"name\">FREEZE</div>\n          <div class=\"desc\">Stop moving to avoid detection. Held breath, shoulders to ears, stiff posture.</div>\n        </div>\n        <div class=\"ff-card\">\n          <div class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M13 2L3 14h9l-1 8 10-12h-9l1-8z\"></path></svg></div>\n          <div class=\"name\">FLIGHT</div>\n          <div class=\"desc\">Move away from threat. Feet toward exit, leaning back, barriers (crossed arms, objects).</div>\n        </div>\n        <div class=\"ff-card\">\n          <div class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M8 14s1.5 2 4 2 4-2 4-2\"></path><line x1=\"9\" y1=\"9\" x2=\"9.01\" y2=\"9\"></line><line x1=\"15\" y1=\"9\" x2=\"15.01\" y2=\"9\"></line></svg></div>\n          <div class=\"name\">FIGHT</div>\n          <div class=\"desc\">Aggression. Chin jut, nostril flare, fist clench, space invasion.</div>\n        </div>\n      </div>\n    </div>\n\n    <div class=\"card\" style=\"animation-delay: 0.2s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"2\"></circle><path d=\"M12 2a10 10 0 0 1 10 10\"></path><path d=\"M12 22a10 10 0 0 1-10-10\"></path><path d=\"M2 12h20\"></path></svg> <span class=\"accent-green\">The Golden Rule</span></h2>\n      <p>\"The body is the subconscious mind made visible.\" Words can deceive. The body <em>always</em> leaks the truth — you just have to know where to look.</p>\n    </div>\n  </div>\n\n  <!--  TAB: Body Map  -->\n  <div class=\"tab-panel\" id=\"tab-body\">\n    <p style=\"color:#778; margin-bottom:0.8rem; font-size:0.85rem;\">Click any body area to uncover what it reveals.</p>\n\n    <div class=\"body-map\">\n      <div class=\"body-part\" onclick=\"this.classList.toggle('open')\">\n        <span class=\"icon\">🦶</span>\n        <span class=\"label\">Feet &amp; Legs</span>\n        <span class=\"clues\">Most honest part of the body.<br>• Pointing away = want to leave<br>• \"Happy feet\" = excitement<br>• Interlaced around chair legs = anxiety<br>• Knee clasp = ready to go</span>\n      </div>\n      <div class=\"body-part\" onclick=\"this.classList.toggle('open')\">\n        <span class=\"icon\">🦵</span>\n        <span class=\"label\">Torso &amp; Hips</span>\n        <span class=\"clues\">• Leaning in = interest<br>• Leaning/turning away = discomfort<br>• Torso away + face toward you = fake<br>• Arms akimbo = assertiveness</span>\n      </div>\n      <div class=\"body-part\" onclick=\"this.classList.toggle('open')\">\n        <span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14.5 2A2.5 2.5 0 0 1 17 4.5V8\"></path><path d=\"M17 15v2.5a2.5 2.5 0 0 1-2.5 2.5\"></path><path d=\"M2 8h12a2 2 0 0 1 2 2v2\"></path><path d=\"M2 14h8\"></path><path d=\"M14 14h2a2 2 0 0 1 2 2v3a2 2 0 0 1-2 2h-2\"></path><path d=\"M8 20h2\"></path></svg></span>\n        <span class=\"label\">Arms &amp; Shoulders</span>\n        <span class=\"clues\">• Shoulders to ears = stress<br>• One-shoulder shrug = uncertainty<br>• Arms crossed high = barrier<br>• Arms crossed low = self-soothing</span>\n      </div>\n      <div class=\"body-part\" onclick=\"this.classList.toggle('open')\">\n        <span class=\"icon\">🤲</span>\n        <span class=\"label\">Hands &amp; Fingers</span>\n        <span class=\"clues\">• Palms visible = honesty<br>• Steepling = confidence<br>• Wringing/rubbing = stress<br>• Thumbs up = high status<br>• Thumbs hidden = insecurity</span>\n      </div>\n      <div class=\"body-part\" onclick=\"this.classList.toggle('open')\">\n        <span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z\"></path></svg></span>\n        <span class=\"label\">Face</span>\n        <span class=\"clues\">• Real smile = eyes crinkle (Duchenne)<br>• Fake smile = mouth only<br>• Lip compression = stress<br>• Nostril flare = anger<br>• Head tilt = interest/trust</span>\n      </div>\n      <div class=\"body-part\" onclick=\"this.classList.toggle('open')\">\n        <span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z\"></path><circle cx=\"12\" cy=\"12\" r=\"3\"></circle></svg>️</span>\n        <span class=\"label\">Eyes</span>\n        <span class=\"clues\">• Pupil dilation = interest/arousal<br>• Pupil constriction = stress/dislike<br>• Blink increase = discomfort<br>• Brow flash = recognition<br>• Gaze aversion = processing or hiding</span>\n      </div>\n    </div>\n  </div>\n\n  <!--  TAB: Signals  -->\n  <div class=\"tab-panel\" id=\"tab-signals\">\n    <div class=\"card\" style=\"animation-delay: 0s;\">\n      <h2>🫂 <span class=\"accent-green\">Pacifying Behaviors</span></h2>\n      <p>When stressed, the limbic brain self-soothes. Spot these calming signals:</p>\n      <div class=\"pac-grid\">\n        <div class=\"pac-item\"><span class=\"icon\">🤚</span><span class=\"label\">Neck rubbing</span></div>\n        <div class=\"pac-item\"><span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M2 12h10\"></path><path d=\"M6 8v8\"></path><path d=\"M10 6v4\"></path><path d=\"M14 4v8\"></path><path d=\"M18 2v12\"></path><path d=\"M22 8v4\"></path></svg></span><span class=\"label\">Face touching</span></div>\n        <div class=\"pac-item\"><span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"></path><path d=\"M2 17l10 5 10-5\"></path><path d=\"M2 12l10 5 10-5\"></path></svg></span><span class=\"label\">Lip licking</span></div>\n        <div class=\"pac-item\"><span class=\"icon\">🤗</span><span class=\"label\">Arm rubbing</span></div>\n        <div class=\"pac-item\"><span class=\"icon\">🦵</span><span class=\"label\">Leg rubbing</span></div>\n        <div class=\"pac-item\"><span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><path d=\"M8 14s1.5 2 4 2 4-2 4-2\"></path><circle cx=\"9\" cy=\"9\" r=\"1\"></circle><circle cx=\"15\" cy=\"9\" r=\"1\"></circle></svg>‍<svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2v8\"></path><path d=\"M16 6l-4 4-4-4\"></path><path d=\"M2 18h20\"></path><path d=\"M4 14h16\"></path></svg></span><span class=\"label\">Deep exhale</span></div>\n        <div class=\"pac-item\"><span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z\"></path><line x1=\"3\" y1=\"6\" x2=\"21\" y2=\"6\"></line><path d=\"M16 10a4 4 0 0 1-8 0\"></path></svg></span><span class=\"label\">Collar tug</span></div>\n        <div class=\"pac-item\"><span class=\"icon\"><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"2\"></circle><path d=\"M12 2v4\"></path><path d=\"M12 18v4\"></path><path d=\"M4.93 4.93l2.83 2.83\"></path><path d=\"M16.24 16.24l2.83 2.83\"></path><path d=\"M2 12h4\"></path><path d=\"M18 12h4\"></path><path d=\"M4.93 19.07l2.83-2.83\"></path><path d=\"M16.24 7.76l2.83-2.83\"></path></svg></span><span class=\"label\">Playing with objects</span></div>\n      </div>\n      <p style=\"margin-top:0.8rem; font-size:0.8rem; color:#888;\">More pacifying = more stress. Look for <em>clusters</em>.</p>\n    </div>\n\n    <div class=\"card\" style=\"animation-delay: 0.1s;\">\n      <h2>🧩 <span class=\"accent-green\">Reading the Signs</span></h2>\n      <ul>\n        <li><strong>Confidence:</strong> Steepled fingers, thumbs out, palms visible, chin up</li>\n        <li><strong>Anxiety:</strong> Fidgeting, pacifying, shallow breaths, feet wrapped around chair</li>\n        <li><strong>Deception:</strong> Delayed responses, grooming gestures, covering mouth, gaze shifts</li>\n        <li><strong>Aggression:</strong> Nostril flare, lip compression, chin jut, pointing, space invasion</li>\n        <li><strong>Interest:</strong> Leaning in, head tilt, pupil dilation, mirroring your posture</li>\n        <li><strong>Discomfort:</strong> Torso turn, barrier objects, feet toward exit, lip purse</li>\n      </ul>\n    </div>\n\n    <div class=\"card\" style=\"animation-delay: 0.2s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M12 2L2 7l10 5 10-5-10-5z\"></path><path d=\"M2 17l10 5 10-5\"></path><path d=\"M2 12l10 5 10-5\"></path></svg> <span class=\"accent-green\">The Truth About Smiles</span></h2>\n      <p>A <strong>genuine</strong> smile (Duchenne) activates the eyes — crow's feet crinkle, the lower eyelids rise, the whole face lights up. A <strong>fake</strong> smile uses only the mouth. If the eyes don't change, the smile is social armor.</p>\n    </div>\n  </div>\n\n  <!--  TAB: Rules  -->\n  <div class=\"tab-panel\" id=\"tab-rules\">\n    <div class=\"card\" style=\"animation-delay: 0s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"></path><polyline points=\"14 2 14 8 20 8\"></polyline><line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\"></line><line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\"></line><polyline points=\"10 9 9 9 8 9\"></polyline></svg> <span class=\"accent-green\">The 5 Golden Rules of Observation</span></h2>\n      <div class=\"rule-row\"><span class=\"rule-num\">01</span> <div><strong>Establish a Baseline</strong><br><span style=\"font-size:0.85rem;color:#888;\">Know how someone acts normally before judging. One gesture = nothing.</span></div></div>\n      <div class=\"rule-row\"><span class=\"rule-num\">02</span> <div><strong>Look for Clusters</strong><br><span style=\"font-size:0.85rem;color:#888;\">One behavior is unreliable. 2-3 congruent behaviors = a real signal.</span></div></div>\n      <div class=\"rule-row\"><span class=\"rule-num\">03</span> <div><strong>Context is Everything</strong><br><span style=\"font-size:0.85rem;color:#888;\">Cold room? Crossed arms might mean temperature, not defensiveness.</span></div></div>\n      <div class=\"rule-row\"><span class=\"rule-num\">04</span> <div><strong>Watch for Sudden Change</strong><br><span style=\"font-size:0.85rem;color:#888;\">A change in behavior = a change in emotional state. That's the truth.</span></div></div>\n      <div class=\"rule-row\"><span class=\"rule-num\">05</span> <div><strong>Trust the Feet First</strong><br><span style=\"font-size:0.85rem;color:#888;\">Feet are the most honest part. Start your observation there.</span></div></div>\n    </div>\n\n    <div class=\"card\" style=\"animation-delay: 0.1s;\">\n      <h2><svg class=\"icon\" width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"></circle><circle cx=\"12\" cy=\"12\" r=\"6\"></circle><circle cx=\"12\" cy=\"12\" r=\"2\"></circle></svg> <span class=\"accent-green\">How to Practice</span></h2>\n      <p>Watch people in public (coffee shops, airports, trains). Start from the ground up:</p>\n      <ol style=\"padding-left:1.2rem;color:#c0c0cc;font-size:0.9rem;line-height:2;\">\n        <li>Feet — what direction? Moving?</li>\n        <li>Torso — leaning toward or away?</li>\n        <li>Arms — open or barrier?</li>\n        <li>Hands — visible or hidden?</li>\n        <li>Face — genuine or social smile?</li>\n      </ol>\n      <p style=\"margin-top:0.6rem;font-size:0.8rem;color:#888;\">Do this for 2 minutes a day. Your observation skill will compound.</p>\n    </div>\n  </div>\n\n  <!--  TAB: Quotes  -->\n  <div class=\"tab-panel\" id=\"tab-quotes\">\n    <div class=\"quote-box\" style=\"animation-delay: 0s;\">\n      <p>\"The body is the subconscious mind made visible.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.08s;\">\n      <p>\"When the limbic brain is distressed, it will pacify — it's universal.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.16s;\">\n      <p>\"The feet are the most honest part of the body.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.24s;\">\n      <p>\"There is no such thing as a 'tell' — there are only behaviors that signal a change in emotional state.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.32s;\">\n      <p>\"We are biologically hardwired to broadcast our emotions.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.40s;\">\n      <p>\"A genuine smile not only mobilizes the mouth but also the eyes.\"</p>\n    </div>\n    <div class=\"quote-box\" style=\"animation-delay: 0.48s;\">\n      <p>\"Observation is not a gift — it's a skill.\"</p>\n    </div>\n  </div>\n\n  \n</div>\n\n<script>\n  //  Radar Scan Canvas \n  const canvas = document.getElementById('radar-canvas');\n  const ctx = canvas.getContext('2d');\n  let angle = 0;\n  let particles = [];\n  let animFrame;\n\n  function resize() {\n    canvas.width = window.innerWidth;\n    canvas.height = document.documentElement.scrollHeight;\n  }\n  resize();\n  window.addEventListener('resize', resize);\n  window.addEventListener('scroll', resize);\n\n  // Mouse interaction\n  let mouse = { x: 0, y: 0 };\n  document.addEventListener('mousemove', e => {\n    mouse.x = e.clientX;\n    mouse.y = e.clientY + window.scrollY;\n  });\n\n  // Particles\n  class Particle {\n    constructor() { this.reset(); }\n    reset() {\n      this.x = Math.random() * canvas.width;\n      this.y = Math.random() * canvas.height;\n      this.size = Math.random() * 2 + 0.3;\n      this.speedX = (Math.random() - 0.5) * 0.15;\n      this.speedY = (Math.random() - 0.5) * 0.15;\n      this.opacity = Math.random() * 0.3 + 0.05;\n    }\n    update() {\n      this.x += this.speedX;\n      this.y += this.speedY;\n\n      const dx = mouse.x - this.x;\n      const dy = mouse.y - this.y;\n      const dist = Math.sqrt(dx * dx + dy * dy);\n      if (dist < 100) {\n        this.x -= dx * 0.0015;\n        this.y -= dy * 0.0015;\n      }\n\n      if (this.x < -10 || this.x > canvas.width + 10 || this.y < -10 || this.y > canvas.height + 10) {\n        this.reset();\n      }\n    }\n    draw() {\n      ctx.beginPath();\n      ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);\n      ctx.fillStyle = `rgba(0, 204, 136, ${this.opacity})`;\n      ctx.fill();\n    }\n  }\n\n  for (let i = 0; i < 50; i++) particles.push(new Particle());\n\n  function drawConnections() {\n    for (let i = 0; i < particles.length; i++) {\n      for (let j = i + 1; j < particles.length; j++) {\n        const dx = particles[i].x - particles[j].x;\n        const dy = particles[i].y - particles[j].y;\n        const dist = Math.sqrt(dx * dx + dy * dy);\n        if (dist < 80) {\n          ctx.beginPath();\n          ctx.moveTo(particles[i].x, particles[i].y);\n          ctx.lineTo(particles[j].x, particles[j].y);\n          ctx.strokeStyle = `rgba(0, 204, 136, ${0.03 * (1 - dist / 80)})`;\n          ctx.lineWidth = 0.5;\n          ctx.stroke();\n        }\n      }\n    }\n  }\n\n  function animate() {\n    ctx.clearRect(0, 0, canvas.width, canvas.height);\n\n    // Radar sweep line\n    const cx = canvas.width / 2;\n    const cy = canvas.height / 2;\n    const radius = Math.max(canvas.width, canvas.height) * 0.7;\n\n    // Subtle radar arc\n    ctx.beginPath();\n    ctx.moveTo(cx, cy);\n    ctx.arc(cx, cy, radius, angle - 0.3, angle + 0.3);\n    ctx.closePath();\n    ctx.fillStyle = 'rgba(0, 204, 136, 0.015)';\n    ctx.fill();\n\n    // Radar line\n    ctx.beginPath();\n    ctx.moveTo(cx, cy);\n    ctx.lineTo(cx + Math.cos(angle) * radius, cy + Math.sin(angle) * radius);\n    ctx.strokeStyle = 'rgba(0, 204, 136, 0.08)';\n    ctx.lineWidth = 1;\n    ctx.stroke();\n\n    // Radar rings\n    for (let r = 1; r <= 3; r++) {\n      ctx.beginPath();\n      ctx.arc(cx, cy, radius * (r / 3), 0, Math.PI * 2);\n      ctx.strokeStyle = 'rgba(0, 204, 136, 0.03)';\n      ctx.lineWidth = 0.5;\n      ctx.stroke();\n    }\n\n    angle += 0.008;\n\n    // Particles\n    particles.forEach(p => { p.update(); p.draw(); });\n    drawConnections();\n\n    animFrame = requestAnimationFrame(animate);\n  }\n\n  animate();\n\n  //  Tabs \n  document.querySelectorAll('.tab-btn').forEach(btn => {\n    btn.addEventListener('click', () => {\n      document.querySelectorAll('.tab-btn').forEach(b => b.classList.remove('active'));\n      document.querySelectorAll('.tab-panel').forEach(p => p.classList.remove('active'));\n      btn.classList.add('active');\n      document.getElementById('tab-' + btn.dataset.tab).classList.add('active');\n      setTimeout(resize, 200);\n    });\n  });\n</script>\n\n\n\n</body>\n</html>"
};
